```python
import requests
from jsonschema import validate, ValidationError
import logging

# Configure logging
logging.basicConfig(filename='update_profile.log', level=logging.INFO)

def update_user_profile(api_url, user_id, email, phone_number):
    # Define schema for validation
    schema = {
        "type": "object",
        "properties": {
            "email": {"type": "string", "format": "email"},
            "phone_number": {"type": "string"}
        },
        "required": ["email", "phone_number"]
    }

    # Prepare the data
    profile_data = {
        "user_id": user_id,
        "email": email,
        "phone_number": phone_number
    }

    try:
        # Validate input data against schema
        validate(instance=profile_data, schema=schema)

        # Make the API request to update user's profile information
        response = requests.put(f"{api_url}/users/{user_id}", json={
            "email": email,
            "phone_number": phone_number
        })

        if response.status_code == 200:
            logging.info(f"Successfully updated user {user_id}")
        elif response.status_code == 429:  # Rate limit exceeded
            logging.warning(f"Rate limit exceeded for user {user_id}")
        else:
            logging.error(f"Failed to update user {user_id}: {response.status_code} - {response.text}")

    except ValidationError as e:
        logging.error(f"Validation error for user {user_id}: {e.message}")

    except requests.exceptions.RequestException as e:
        logging.error(f"Network error occurred for user {user_id}: {str(e)}")

# Example usage
update_user_profile(
    api_url="https://api.example.com",
    user_id=123,
    email="new_email@example.com",
    phone_number="+11234567890"
)
