#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>
#include <unistd.h>

char* validate_and_construct_path(const char* path, int max_size, bool is_absolute, char* error_buffer) {
    if (!path || *path == '\0' || strlen(path) > max_size - 1) {
        snprintf(error_buffer, max_size, "Path exceeds size limit or is improperly formatted.");
        return NULL;
    }

    if (is_absolute) {
        char* result = malloc(max_size);
        if (!result) {
            strcpy(error_buffer, "Memory allocation failed.");
            return NULL;
        }
        strncpy(result, path, max_size - 1);
        result[max_size - 1] = '\0';
        return result;
    } else {
        char cwd[PATH_MAX];
        if (getcwd(cwd, sizeof(cwd)) == NULL) {
            snprintf(error_buffer, max_size, "Failed to get current working directory: %s", strerror(errno));
            return NULL;
        }

        size_t cwd_len = strlen(cwd);
        size_t path_len = strlen(path);

        if (cwd_len + 1 + path_len >= max_size - 1) {
            snprintf(error_buffer, max_size, "Path exceeds size limit when combined with current working directory.");
            return NULL;
        }

        char* result = malloc(max_size);
        if (!result) {
            strcpy(error_buffer, "Memory allocation failed.");
            return NULL;
        }

        snprintf(result, max_size, "%s/%s", cwd, path);
        return result;
    }
}
