#include <iostream>
#include <vector>
#include <unordered_map>
#include <fstream>

struct Point {
    float x, y, z;
};

class SpatialHashGrid {
public:
    SpatialHashGrid(size_t width, size_t height, size_t depth, 
                    float bucketSize, int maxEntriesPerBucket)
        : mWidth(width), mHeight(height), mDepth(depth),
          mBucketSize(bucketSize), mMaxEntriesPerBucket(maxEntriesPerBucket) {

        mNumBucketsX = static_cast<size_t>(std::ceil(mWidth / mBucketSize));
        mNumBucketsY = static_cast<size_t>(std::ceil(mHeight / mBucketSize));
        mNumBucketsZ = static_cast<size_t>(std::ceil(mDepth / mBucketSize));

        for (size_t x = 0; x < mNumBucketsX; ++x) {
            for (size_t y = 0; y < mNumBucketsY; ++y) {
                for (size_t z = 0; z < mNumBucketsZ; ++z) {
                    auto bucketIndex = std::make_tuple(x, y, z);
                    mGrid[bucketIndex] = std::vector<Point>();
                }
            }
        }
    }

    void insert(const Point& point) {
        size_t xBucket = static_cast<size_t>(point.x / mBucketSize);
        size_t yBucket = static_cast<size_t>(point.y / mBucketSize);
        size_t zBucket = static_cast<size_t>(point.z / mBucketSize);

        auto bucketIndex = std::make_tuple(xBucket, yBucket, zBucket);

        if (mGrid[bucketIndex].size() < mMaxEntriesPerBucket) {
            mGrid[bucketIndex].push_back(point);
        } else {
            std::cerr << "Error: Maximum entries per bucket exceeded for bucket (" 
                      << xBucket << ", " << yBucket << ", " << zBucket << ").\n";
        }
    }

    bool query(const Point& point, std::vector<Point>& results) const {
        size_t xBucket = static_cast<size_t>(point.x / mBucketSize);
        size_t yBucket = static_cast<size_t>(point.y / mBucketSize);
        size_t zBucket = static_cast<size_t>(point.z / mBucketSize);

        auto bucketIndex = std::make_tuple(xBucket, yBucket, zBucket);

        if (mGrid.find(bucketIndex) != mGrid.end()) {
            results = mGrid.at(bucketIndex);
            return true;
        }
        return false;
    }

    void serialize(const std::string& filename) const {
        std::ofstream file(filename, std::ios::out | std::ios::binary);

        if (!file.is_open()) {
            std::cerr << "Error: Could not open file for writing.\n";
            return;
        }

        size_t numBuckets = mGrid.size();
        file.write(reinterpret_cast<const char*>(&numBuckets), sizeof(size_t));

        for (const auto& [bucketIndex, points] : mGrid) {
            size_t bucketIndexTuple[3];
            std::tie(bucketIndexTuple[0], bucketIndexTuple[1], bucketIndexTuple[2]) = bucketIndex;

            file.write(reinterpret_cast<const char*>(bucketIndexTuple), sizeof(size_t) * 3);
            size_t numPoints = points.size();
            file.write(reinterpret_cast<const char*>(&numPoints), sizeof(size_t));

            for (const auto& point : points) {
                file.write(reinterpret_cast<const char*>(&point), sizeof(Point));
            }
        }

        file.close();
    }

private:
    size_t mWidth, mHeight, mDepth;
    float mBucketSize;
    int mMaxEntriesPerBucket;

    size_t mNumBucketsX, mNumBucketsY, mNumBucketsZ;
    std::unordered_map<std::tuple<size_t, size_t, size_t>, std::vector<Point>> mGrid;
};

