import hashlib
import os

def calculate_sha256(file_path, provided_checksum=None):
    def hash_file(file_obj):
        sha256 = hashlib.sha256()
        while chunk := file_obj.read(8192):  # Read in chunks of 8KB
            sha256.update(chunk)
        return sha256.hexdigest()

    try:
        if file_path.startswith(('http://', 'https://')):
            import requests
            from io import BytesIO

            response = requests.get(file_path, stream=True)
            response.raise_for_status()
            file_obj = BytesIO(response.content)
        else:
            if not os.path.exists(file_path):
                raise FileNotFoundError(f"File {file_path} does not exist.")
            with open(file_path, 'rb') as file_obj:
                file_hash = hash_file(file_obj)

        calculated_hash = hash_file(BytesIO(requests.get(file_path).content) if file_path.startswith(('http://', 'https://')) else open(file_path, 'rb'))

        if provided_checksum is not None:
            if calculated_hash == provided_checksum.lower():
                return f"Success: The checksum matches the calculated hash."
            else:
                return "Error: Checksum mismatch. The calculated hash does not match the provided checksum."

        return f"The SHA-256 hash of the file is {calculated_hash}."

    except FileNotFoundError as e:
        return str(e)
    except requests.RequestException as e:
        return f"Error accessing the remote file: {str(e)}"
    except ValueError:
        return "Invalid checksum format provided."
```

Below is a JavaScript implementation for the `uploadFileFromUrl` function, which includes handling retries with exponential backoff, logging, and chunked uploads for large files. This example uses AWS S3 as the cloud storage service, but you can adapt it to other services like Azure Blob Storage by modifying the SDK-specific parts.

```javascript
const axios = require('axios');
const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const { v4: uuidv4 } = require('uuid');
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'upload.log' })
  ],
});

// Create an S3 client
const s3Client = new S3Client({ region: 'us-east-1' });

async function uploadFileFromUrl(url, bucketName, credentials) {
  const MAX_RETRIES = 3;
  const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB

  async function fetchFile() {
    try {
      const response = await axios({
        url,
        responseType: 'stream',
      });
      return response.data;
    } catch (error) {
      logger.error(`Error fetching file from URL: ${error.message}`);
      throw error;
    }
  }

  async function uploadStreamToS3(stream, fileName, attempt = 1) {
    try {
      const command = new PutObjectCommand({
        Bucket: bucketName,
        Key: fileName,
        Body: stream,
      });

      await s3Client.send(command);
      logger.info(`Successfully uploaded ${fileName}`);
      return `https://${bucketName}.s3.amazonaws.com/${fileName}`;
    } catch (error) {
      if (attempt <= MAX_RETRIES) {
        const delay = Math.pow(2, attempt) * 1000;
        logger.warn(`Upload failed for ${fileName}, retrying in ${delay}ms...`);
        await new Promise(res => setTimeout(res, delay));
        return uploadStreamToS3(stream, fileName, attempt + 1);
      } else {
        logger.error(`Failed to upload ${fileName}: ${error.message}`);
        throw error;
      }
    }
  }

  async function handleFileUpload() {
    try {
      const stream = await fetchFile();
      const metadata = await axios.head(url);

      if (metadata.headers['content-length'] > MAX_FILE_SIZE) {
        logger.warn('File size exceeds limit, consider chunked upload implementation');
        throw new Error('File too large');
      }

      const fileName = `${uuidv4()}-${new URL(url).pathname.split('/').pop()}`;
      return await uploadStreamToS3(stream, fileName);
    } catch (error) {
      logger.error(`Error in file upload process: ${error.message}`);
      throw error;
    }
  }

  return handleFileUpload();
}

// Example usage
uploadFileFromUrl('https://example.com/sample.jpg', 'my-bucket-name', { accessKeyId: 'your-access-key-id', secretAccessKey: 'your-secret-access-key' })
  .then((publicUrl) => console.log(`File uploaded to: ${publicUrl}`))
  .catch(error => console.error(error));

module.exports = uploadFileFromUrl;
```

### Key Points:
- **Retries with Exponential Backoff**: The function retries failed uploads up to three times, waiting longer between each attempt.
- **Logging**: Uses `winston` for logging errors and information about the upload process.
- **Unique Filenames**: Generates unique filenames using UUIDs.
- **File Size Handling**: Currently logs a warning if the file exceeds 50MB. You can extend this to implement chunked uploads.
- **Cloud Service Configuration**: Designed to be easily adaptable for different cloud storage services by changing SDK-specific parts.

