public class ValueGenerator
{
    private float minValue;
    private float maxValue;
    private IDistribution currentDistribution;

    public ValueGenerator(float min, float max)
    {
        SetRange(min, max);
        SetDefaultDistribution();
    }

    public void SetRange(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        minValue = min;
        maxValue = max;
    }

    public void SetDistribution(IDistribution distribution)
    {
        if (distribution == null || !IsValidDistribution(distribution))
        {
            throw new InvalidOperationException("Invalid or unsupported distribution requested.");
        }
        currentDistribution = distribution;
    }

    private bool IsValidDistribution(IDistribution distribution)
    {
        // Implement validation logic for supported distributions
        return true;  // Placeholder for actual implementation
    }

    public float GetRandomFloat()
    {
        if (currentDistribution != null)
            return currentDistribution.Generate(minValue, maxValue);

        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        if (currentDistribution != null)
            return Mathf.RoundToInt(currentDistribution.Generate(minValue, maxValue));

        return Random.Range((int)minValue, (int)maxValue);
    }

    private void SetDefaultDistribution()
    {
        currentDistribution = new UniformDistribution();
    }

    public override string ToString()
    {
        var distributionType = currentDistribution?.GetType().Name ?? "Uniform";
        return $"Range: [{minValue}, {maxValue}), Distribution: {distributionType}";
    }
}

public interface IDistribution
{
    float Generate(float min, float max);
}

public class UniformDistribution : IDistribution
{
    public float Generate(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }
}

// Example of another distribution type
public class GaussianDistribution : IDistribution
{
    private System.Random random = new System.Random();

    public float Generate(float min, float max)
    {
        var gaussRandomValue = (float)random.NextDouble();
        // Convert to range and ensure it falls within [min, max]
        return Mathf.Clamp01(gaussRandomValue);
    }
}
