Here is a Java service implementation using Spring Boot to achieve the described functionality. This code assumes you have access to the necessary REST APIs for fetching Pokemon data, weather effects, and terrain effects.

```java
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.client.RestTemplate;
import org.springframework.cache.annotation.Cacheable;
import java.util.List;
import java.util.Map;

@SpringBootApplication
public class PokemonServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(PokemonServiceApplication.class, args);
    }
}

@RestController
class PokemonController {

    @Autowired
    private RestTemplate restTemplate;

    @GetMapping("/pokemon/weaknesses")
    public ResponseEntity<Map<String, Object>> getPokemonWeaknesses(@RequestParam int pokemonId) {
        try {
            Map<String, Object> pokemonData = getFromPokemonApi(pokemonId);
            List<String> weatherEffects = getWeatherEffects();
            List<String> terrainEffects = getTerrainEffects();

            Map<String, Object> response = Map.of(
                "name", pokemonData.get("name"),
                "type", pokemonData.get("type"),
                "weaknesses", pokemonData.get("weaknesses"),
                "weather_effects", weatherEffects,
                "terrain_effects", terrainEffects
            );

            return ResponseEntity.ok(response);
        } catch (Exception e) {
            // Log error and handle gracefully
            return ResponseEntity.status(500).body(Map.of(
                "error", "Failed to retrieve Pokemon data"
            ));
        }
    }

    @Cacheable("pokemonData")
    private Map<String, Object> getFromPokemonApi(int pokemonId) throws Exception {
        String url = "https://api.example.com/pokemon/" + pokemonId;
        return restTemplate.getForObject(url, Map.class);
    }

    @Cacheable("weatherEffects")
    private List<String> getWeatherEffects() throws Exception {
        String url = "https://api.example.com/weather/effects";
        return (List<String>) restTemplate.getForObject(url, List.class);
    }

    @Cacheable("terrainEffects")
    private List<String> getTerrainEffects() throws Exception {
        String url = "https://api.example.com/terrain/effects";
        return (List<String>) restTemplate.getForObject(url, List.class);
    }
}
