std::string generateMockUuid(const std::string& ip) {
    return "mock-uuid-for-" + ip;
}

class InterfaceTableTestDouble {
public:
    unsigned int callCount = 0;

    std::string FindVmUuidFromMetadataIp(const std::string& ip) {
        ++callCount;
        LogCall(ip);
        return generateMockUuid(ip);
    }

private:
    void LogCall(const std::string& ip) {
        std::lock_guard<std::mutex> lock(fileMutex);
        auto now = std::chrono::system_clock::now();
        auto time_t_now = std::chrono::system_clock::to_time_t(now);

        logFile << "FindVmUuidFromMetadataIp called with IP: " << ip
                << " at " << std::ctime(&time_t_now) 
                << " Call count: " << callCount << '\n';
    }

    std::mutex fileMutex;
    static std::ofstream logFile;
};

std::ofstream InterfaceTableTestDouble::logFile("interaction_log.txt", std::ios_base::app);

class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& ioContext, const std::string& serverAddress)
        : resolver_(ioContext), socket_(ioContext) {}

    void SendRequest(const std::string& requestType, const std::string& endpoint) {
        try {
            auto endpoints = resolver_.resolve(serverAddress_, "http");
            boost::asio::async_connect(socket_, endpoints,
                [this, requestType, endpoint](const boost::system::error_code& ec, const auto&) {
                    if (!ec) {
                        SendHttpRequest(requestType, endpoint);
                    } else {
                        LogError(ec.message());
                    }
                });
        } catch (std::exception& e) {
            LogError(e.what());
        }
    }

private:
    void SendHttpRequest(const std::string& requestType, const std::string& endpoint) {
        // Implement HTTP client functionality using Boost.Beast or another suitable library
        auto responseTimeStart = std::chrono::system_clock::now();

        // Mock sending and receiving requests
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate network delay

        LogInteraction(requestType, endpoint);

        auto responseTimeEnd = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(responseTimeEnd - responseTimeStart).count();

        LogResponseTime(duration);
    }

    void LogInteraction(const std::string& requestType, const std::string& endpoint) {
        std::lock_guard<std::mutex> lock(fileMutex);
        auto now = std::chrono::system_clock::now();
        auto time_t_now = std::chrono::system_clock::to_time_t(now);

        logFile << "Request Type: " << requestType 
                << ", Endpoint: " << endpoint
                << " at " << std::ctime(&time_t_now) << '\n';
    }

    void LogResponseTime(int duration) {
        std::lock_guard<std::mutex> lock(fileMutex);
        auto now = std::chrono::system_clock::now();
        auto time_t_now = std::chrono::system_clock::to_time_t(now);

        logFile << "Response Time: " << duration << "ms at "
                << std::ctime(&time_t_now) << '\n';
    }

    void LogError(const std::string& errorMessage) {
        std::lock_guard<std::mutex> lock(fileMutex);
        auto now = std::chrono::system_clock::now();
        auto time_t_now = std::chrono::system_clock::to_time_t(now);

        logFile << "Error: " << errorMessage
                << " at " << std::ctime(&time_t_now) << '\n';
    }

    boost::asio::ip::tcp::resolver resolver_;
    boost::asio::ip::tcp::socket socket_;
    std::string serverAddress_ = "example.com"; // Replace with actual server address
    static std::ofstream logFile;
    static std::mutex fileMutex;
};

std::ofstream SandeshClient::logFile("interaction_log.txt", std::ios_base::app);
std::mutex SandeshClient::fileMutex;

