    int number;
    size_t count = 0;
    size_t capacity = 10;
    int *arr = malloc(capacity * sizeof(int));

    if (!arr) {
        perror("Memory allocation failed");
        fclose(file);
        return 1;
    }

    while (fscanf(file, "%d", &number) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            arr = realloc(arr, capacity * sizeof(int));
            if (!arr) {
                perror("Memory reallocation failed");
                fclose(file);
                return 1;
            }
        }
        arr[count++] = number;
    }

    fclose(file);

    if (count == 0) {
        printf("The file is empty or contains no valid integers.\n");
        free(arr);
        return 1;
    }

    sortArray(arr, count);

    int largest = arr[count - 1];
    printf("Largest integer: %d\n", largest);

    free(arr);
    return 0;
}
