<?php

class ConfigurationScript {
    private $environment;
    private $envData = [];
    private $configCache = [];

    public function __construct($environment) {
        $this->environment = $environment;
    }

    public function execute() {
        try {
            $this->loadEnvironmentVariables();
            $this->loadAutoloaders();
            $configFile = $this->selectConfigFile();
            $this->configureApplication($configFile);
            $this->monitorForReload();
        } catch (Exception $e) {
            $this->logError('Execution failed: ' . $e->getMessage());
        }
    }

    private function loadEnvironmentVariables() {
        if ($data = parse_ini_file('.env.local', true)) {
            $this->envData = array_merge($this->envData, $data);
        } elseif (!empty($data = parse_ini_file('.env', true))) {
            $this->envData = $data;
        }

        foreach ($this->envData as $key => &$value) {
            $value = getenv($key) ?: $value;
        }
    }

    private function loadAutoloaders() {
        if (file_exists(__DIR__ . '/vendor/autoload.php')) {
            require __DIR__ . '/vendor/autoload.php';
        } elseif (file_exists(__DIR__ . '/autoload.php')) { // Assuming PEAR-style autoloader
            require __DIR__ . '/autoload.php';
        }
    }

    private function selectConfigFile() {
        $configBase = isset($this->envData['APP_CONFIG_PATH']) ? 
                      rtrim($this->envData['APP_CONFIG_PATH'], '/') : 
                      'config';

        if ($this->environment === 'production') {
            return "{$configBase}/prod.php";
        } elseif (file_exists("{$configBase}.local.php")) {
            return "{$configBase}.local.php";
        }

        return "{$configBase}/default.php";
    }

    private function configureApplication($configFile) {
        if (!is_readable($configFile)) {
            throw new Exception("Configuration file not found: $configFile");
        }

        $config = include $configFile;
        $this->cacheConfigSettings($config);

        // Application-specific configuration logic goes here
    }

    private function cacheConfigSettings($config) {
        foreach ($config as $key => $value) {
            $this->configCache[$key] = $value;
        }
    }

    private function monitorForReload() {
        if (isset($_ENV['DYNAMIC_RELOAD'])) {
            // Logic to handle dynamic reloading
            $this->execute(); // Simplified for this example; a more robust implementation would be needed.
        }
    }

    private function logError($message) {
        error_log(date('[Y-m-d H:i:s] ') . "ERROR: $message" . PHP_EOL, 3, __DIR__ . '/error.log');
    }
}

// Example usage:
$script = new ConfigurationScript('development');
$script->execute();

$script = new ConfigurationScript('production');
$script->execute();
```

