```python
import json
import requests
from typing import Any, Dict

class ConfigError(Exception):
    pass

class Configuration:
    def __init__(self, config: Dict[str, Any]):
        self.config = config

    def get(self, key: str, default=None):
        return self.config.get(key, default)

    def set(self, key: str, value: Any):
        self.config[key] = value

    def update(self, new_config: Dict[str, Any]):
        self.config.update(new_config)

class ConfigParser:
    @staticmethod
    def load_from_file(file_path: str) -> Dict[str, Any]:
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                return json.load(file)
        except FileNotFoundError:
            raise ConfigError(f"Configuration file not found: {file_path}")
        except json.JSONDecodeError:
            raise ConfigError("Failed to decode JSON from the configuration file")

class APIIntegrator:
    @staticmethod
    def fetch_remote_config(api_url: str) -> Dict[str, Any]:
        try:
            response = requests.get(api_url)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            raise ConfigError(f"Failed to fetch remote configuration: {str(e)}")

class ConfigurationMerger:
    @staticmethod
    def merge_configs(local_config: Dict[str, Any], remote_config: Dict[str, Any]) -> Dict[str, Any]:
        merged = local_config.copy()
        for key, value in remote_config.items():
            if isinstance(value, dict) and key in merged and isinstance(merged[key], dict):
                merged[key] = ConfigurationMerger.merge_configs(merged[key], value)
            else:
                merged[key] = value
        return merged

def initialize_configuration(file_path: str, api_url: str) -> Configuration:
    try:
        local_config = ConfigParser.load_from_file(file_path)

        remote_config = APIIntegrator.fetch_remote_config(api_url)

        final_config = ConfigurationMerger.merge_configs(local_config, remote_config)

        config_obj = Configuration(final_config)
        print("Configuration loaded and merged successfully.")
        return config_obj
    except ConfigError as e:
        print(f"Configuration Error: {str(e)}")
    except Exception as ex:
        print(f"An unexpected error occurred: {str(ex)}")

# Example usage:
# config = initialize_configuration('config.json', 'https://api.example.com/config')
