```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SensorDataProcessor {

    private static final Logger logger = LoggerFactory.getLogger(SensorDataProcessor.class);
    private final KafkaProducer<String, String> producer;
    private final ObjectMapper objectMapper;
    private final ExecutorService executorService;

    public SensorDataProcessor(String bootstrapServers) {
        this.objectMapper = new ObjectMapper();

        Properties props = new Properties();
        props.put("bootstrap.servers", bootstrapServers);
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        this.producer = new KafkaProducer<>(props);
        this.executorService = Executors.newFixedThreadPool(10); // Adjust the pool size as needed
    }

    public void processSensorData(String jsonData, String topic) {
        executorService.submit(() -> {
            try {
                if (validateJson(jsonData)) {
                    ProducerRecord<String, String> record = new ProducerRecord<>(topic, null, jsonData);
                    producer.send(record, (metadata, exception) -> {
                        if (exception != null) {
                            logger.error("Failed to send data: ", exception);
                            reprocessFailedTransaction(metadata.topic(), metadata.partition(), jsonData);
                        } else {
                            logger.info("Data sent successfully to partition {} with offset {}", metadata.partition(), metadata.offset());
                        }
