using json = nlohmann::json;
using namespace std;

// Union-Find Data Structure with Path Compression and Union by Rank
class UnionFind {
public:
    UnionFind(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (u != parent[u])
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);
        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) 
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

private:
    vector<int> parent, rank;
};

// Thread-safe JSON parsing
class ConfigParser {
public:
    static unordered_map<string, variant<int, double, string, bool>> parseConfig(const string& filePath) {
        static mutex mtx;
        lock_guard<mutex> lock(mtx);
        ifstream file(filePath);
        if (!file.is_open()) throw runtime_error("Unable to open config file");

        json j;
        try {
            file >> j;
        } catch (exception& e) {
            throw runtime_error("JSON parse error: " + string(e.what()));
        }

        unordered_map<string, variant<int, double, string, bool>> config;
        for (auto& [key, value] : j.items()) {
            if (value.is_number_integer())
                config[key] = value.get<int>();
            else if (value.is_number_float())
                config[key] = value.get<double>();
            else if (value.is_string())
                config[key] = value.get<string>();
            else if (value.is_boolean())
                config[key] = value.get<bool>();
        }

        return config;
    }
};

// Function to interact with an external API
string fetchElementMetadata(const string& apiEndpoint, const string& params) {
    CURL* curl;
    CURLcode res;
    string responseString;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = nullptr;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        curl_easy_setopt(curl, CURLOPT_URL, apiEndpoint.c_str());
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, params.c_str());

        // Handle retries and errors
        int retryCount = 0;
        while (retryCount < 3) {
            res = curl_easy_perform(curl);
            if (res == CURLE_OK)
                break;
            else {
                cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << endl;
                ++retryCount;
                this_thread::sleep_for(chrono::seconds(2));
            }
        }

        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
        if (res == 200 || res == 201) {
            // Assume successful response
            char* buffer = new char[10000];
            size_t responseLength;
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* ptr, size_t size, size_t nmemb, void* stream){
                ((string*)stream)->append((char*)ptr, size * nmemb);
                return size * nmemb;
            });
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &responseString);
            curl_easy_perform(curl);

            delete[] buffer;
        } else {
            throw runtime_error("API request failed with response code: " + to_string(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return responseString;
}

// Function to find all disjoint pairs in an array using multi-threading
void identifyDisjointPairs(const vector<int>& arr, const unordered_map<string, variant<int, double, string, bool>>& config) {
    if (arr.empty()) return;

    int setSize = get<0>(config.at("set_size"));
    UnionFind uf(arr.size());

    auto worker = [&](int start, int end) {
        for (int i = start; i < end; ++i) {
            for (int j = i + 1; j < arr.size(); ++j) {
                if (arr[i] != arr[j])
                    uf.unite(i, j);
            }
        }
    };

    vector<thread> threads;
    int chunkSize = arr.size() / setSize;

    for (int i = 0; i < setSize; ++i) {
        int start = i * chunkSize;
        int end = (i == setSize - 1) ? arr.size() : start + chunkSize;
        threads.emplace_back(worker, start, end);
    }

    for (auto& t : threads)
        t.join();

    // Output results
    unordered_map<int, vector<int>> sets;
    for (int i = 0; i < arr.size(); ++i) {
        int root = uf.find(i);
        sets[root].push_back(arr[i]);
    }

    cout << "Disjoint Sets:" << endl;
    for (const auto& [root, set] : sets)
        cout << "{" << root << ": {" << set[0];
        for (size_t i = 1; i < set.size(); ++i)
            cout << ", " << set[i];
        cout << "}}" << endl;
}

// Command-line interface
void runCLI() {
    string configFile;
    cout << "Enter the path to configuration file: ";
    cin >> configFile;

    try {
        auto config = ConfigParser::parseConfig(configFile);

        vector<int> arr(100); // Example array, replace with dynamic generation as needed
        for (int& x : arr)
            x = rand() % 50; // Random example data

        identifyDisjointPairs(arr, config);

    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
    }
}

int main(int argc, char* argv[]) {
    runCLI();
    return 0;
}
```

### Explanation:

- **Union-Find Data Structure:** Implemented with path compression and union by rank for efficient disjoint set management.

- **ConfigParser:** Thread-safe JSON parsing using `nlohmann::json` library. Utilizes mutex to ensure concurrent read access safety.

- **fetchElementMetadata:** Uses libcurl to interact with an external API, implementing retry logic in case of transient failures.

- **identifyDisjointPairs:** Multi-threaded processing to identify disjoint pairs using Union-Find and splits work among threads based on configuration settings.

- **runCLI & main:** Provides a command-line interface for user input and starts the utility. 

