    private readonly IDatabaseService _databaseService;

    public PreferencesLoader(string binaryFilePath, ILogger logger, ICacheService cacheService, IDatabaseService databaseService)
    {
        _binaryFilePath = binaryFilePath ?? throw new ArgumentNullException(nameof(binaryFilePath));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cacheService = cacheService ?? throw new ArgumentNullException(nameof(cacheService));
        _databaseService = databaseService ?? throw new ArgumentNullException(nameof(databaseService));
    }

    public async Task<UserPreferences> LoadUserPreferencesAsync(int userId)
    {
        try
        {
            UserPreferences preferences;

            // Try loading from binary file
            if (File.Exists(_binaryFilePath))
            {
                using var stream = File.OpenRead(_binaryFilePath);
                var formatter = new BinaryFormatter();

                lock (stream) // Ensure thread safety when reading the file
                {
                    preferences = (UserPreferences)formatter.Deserialize(stream);
                }

                _cacheService.SetCache(userId, preferences);  // Update cache with loaded data

            }
            else
            {
                throw new FileNotFoundException("Binary file not found.");
            }

            return preferences;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading user preferences from binary file.");

            // Fallback to database retrieval
            try
            {
                preferences = await _databaseService.GetUserPreferencesAsync(userId);

                if (preferences != null)
                {
                    _cacheService.SetCache(userId, preferences);  // Update cache with database data
                }
                else
                {
                    throw new InvalidOperationException("No user preferences found in database.");
                }

                return preferences;
            }
            catch (Exception dbEx)
            {
                _logger.LogError(dbEx, "Error retrieving user preferences from the database.");

                throw new ApplicationException("Failed to load user preferences. Please try again later.");
            }
        }
    }
}

