```javascript
class CancellationToken {
    constructor() {
        this.isCancelled = false;
    }

    cancel() {
        this.isCancelled = true;
    }
}

async function asyncReduce(array, initialValues, callback) {
    const logger = console; // Replace with centralized logging service if needed

    const results = initialValues.map(initialValue => initialValue);
    const promises = initialValues.map(() => Promise.resolve());

    for (let i = 0; i < array.length; i++) {
        if (cancellationToken.isCancelled) {
            logger.log("Reduction process cancelled.");
            break;
        }

        const elementPromises = results.map(async (result, index) => {
            try {
                return await callback(result, array[i], i, cancellationToken);
            } catch (error) {
                logger.error(`Error at index ${i}:`, error.message);
                return result; // Continue with the current result
            }
        });

        results.forEach((_, index) => {
            promises[index] = promises[index].then(() => elementPromises[index]);
        });
    }

    return Promise.all(promises).then(resolvedResults =>
        resolvedResults.map(result => result)
    );
}

// Sample callback function that supports both synchronous and asynchronous operations
async function sampleCallback(acc, value, index, cancellationToken) {
    if (cancellationToken.isCancelled) {
        throw new Error("Operation cancelled");
    }

    await new Promise(resolve => setTimeout(resolve, 100)); // Simulating async operation

    return acc + value; // Example of a reduction operation
}

// Sample unit test function using Jest or similar testing framework
describe('asyncReduce', () => {
    it('should correctly reduce the array with multiple initial values', async () => {
        const array = [1, 2, 3];
        const initialValues = [0, 10];
        const cancellationToken = new CancellationToken();

        const result = await asyncReduce(array, initialValues, sampleCallback);
        expect(result).toEqual([6, 16]);
    });

    it('should handle errors gracefully', async () => {
        const array = [1, 'invalid', 3];
        const initialValues = [0];

        const faultyCallback = (acc, value) => {
            if (typeof value !== 'number') {
                throw new Error("Invalid type");
            }
            return acc + value;
        };

        const result = await asyncReduce(array, initialValues, faultyCallback);
        expect(result).toEqual([4]); // Should skip the invalid entry
    });

    it('should respect cancellation', async () => {
        const array = [1, 2, 3];
        const initialValues = [0];
        const cancellationToken = new CancellationToken();

        setTimeout(() => cancellationToken.cancel(), 150); // Cancel after some time

        const result = await asyncReduce(array, initialValues, sampleCallback);
        expect(result).toEqual([1]); // Should only process the first element
    });
});

