import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.amazonaws.services.kms.AWSKMS;
import com.amazonaws.services.kms.AWSKMSClientBuilder;
import com.amazonaws.services.kms.model.DecryptRequest;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.time.LocalDateTime;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class TokenService {

    private static final Logger logger = Logger.getLogger(TokenService.class.getName());
    private AWSKMS kmsClient;
    private String keyId;
    private long tokenValidityDurationMinutes = 30; // Example duration
    private ObjectMapper objectMapper = new ObjectMapper();

    private Map<String, JWT> tokenCache = new ConcurrentHashMap<>();

    public TokenService(String keyId) {
        this.kmsClient = AWSKMSClientBuilder.defaultClient();
        this.keyId = keyId;
    }

    public String generateToken(HttpRequest request) throws Exception {
        logger.info("Received request for token generation.");

        if (!validateRequest(request)) {
            logger.warning("Invalid credentials or insufficient permissions.");
            throw new IllegalArgumentException("Invalid request");
        }

        // Retrieve private key from KMS
        byte[] privateKeyBytes = retrievePrivateKeyFromKms(keyId);
        Algorithm algorithm = Algorithm.RSA256(null, new java.security.KeyFactorySpi.PrivateKeySpec(privateKeyBytes));

        String jwtToken = JWT.create()
                .withSubject(request.getUsername())
                .withExpiresAt(LocalDateTime.now().plusMinutes(tokenValidityDurationMinutes).toEpochSecond(java.time.temporal.ChronoUnit.SECONDS))
                .sign(algorithm);

        tokenCache.put(jwtToken, new JWT(jwtToken)); // Cache the generated token
        logger.info("JWT Token generated and cached successfully.");

        return jwtToken;
    }

    private boolean validateRequest(HttpRequest request) {
        try {
            JsonNode body = objectMapper.readTree(request.getBody());
            String role = body.get("role").asText();
            if (request.hasValidCredentials() && hasPermission(role)) {
                logger.info("Request validated successfully.");
                return true;
            }
        } catch (IOException e) {
            logger.severe("Error parsing request JSON: " + e.getMessage());
        }

        return false;
    }

    private boolean hasPermission(String role) {
        // Implement role-based permission logic
        return "USER".equals(role);
    }

    private byte[] retrievePrivateKeyFromKms(String keyId) throws Exception {
        logger.info("Retrieving private key from KMS.");
        DecryptRequest decryptRequest = new DecryptRequest()
                .withCiphertextBlob(ByteBuffer.wrap(keyId.getBytes()));

        try {
            com.amazonaws.services.kms.model.DecryptResult result = kmsClient.decrypt(decryptRequest);
            return result.getPlaintext().array();
        } catch (Exception e) {
            logger.severe("Error retrieving key from KMS: " + e.getMessage());
            throw new RuntimeException("KMS retrieval error", e);
        }
    }

    public JWT refreshJwtToken(String jwtToken) throws Exception {
        if (!tokenCache.containsKey(jwtToken)) {
            logger.warning("JWT token not found in cache.");
            throw new IllegalArgumentException("Invalid token");
        }

        JWT existingToken = tokenCache.get(jwtToken);
        LocalDateTime expiresAt = existingToken.expiresAt();

        if (expiresAt.isAfter(LocalDateTime.now())) {
            long timeUntilExpiry = java.time.temporal.ChronoUnit.MINUTES.between(LocalDateTime.now(), expiresAt);

            // Refresh the token only if less than 5 minutes remain
            if (timeUntilExpiry < 5) {
                logger.info("Refreshing JWT Token.");
                return new JWT(JWT.decode(jwtToken).getJWTClaimsSet().toString()); // Simplified for example
            }
        }

        return existingToken;
    }

    public void logInteraction(String message) {
        logger.info(message);
    }
}

class HttpRequest {
    private String body;

    public String getBody() {
        return body;
    }

    public boolean hasValidCredentials() {
        // Implement logic to check credentials
        return true;
    }

    public String getUsername() {
        // Extract username from request if necessary
        return "user";
    }
}
