    public CompletableFuture<ResponseEntity<byte[]>> generateReport(HttpServletRequest request) {
        logger.info("Generating report for request: " + request.getRequestURI());

        return CompletableFuture.supplyAsync(() -> {
            try {
                // Parse request parameters
                String reportType = request.getParameter("reportType");
                if (reportType == null || reportType.isEmpty()) {
                    throw new IllegalArgumentException("Report type is required.");
                }

                // Fetch and aggregate data from databases
                var mysqlData = cacheManager.getCachedOrFetch(() -> mySqlRepository.fetchData(request));
                var postgreData = cacheManager.getCachedOrFetch(() -> postgreSqlRepository.fetchData(request));
                var mongoData = cacheManager.getCachedOrFetch(() -> mongoDbRepository.fetchData(request));

                // Perform data transformation
                var transformedData = transformData(mysqlData, postgreData, mongoData);

                // Generate PDF report
                byte[] pdfBytes = pdfFormatter.formatReport(transformedData);

                // Send the report via external API (email/SMS)
                sendReportViaApi(pdfBytes, request.getParameter("recipients"));

                return ResponseEntity.ok().body(pdfBytes);
            } catch (Exception e) {
                logger.severe("Error generating report: " + e.getMessage());
                return ResponseEntity.internalServerError().build();
            }
        });
    }

