#define MAX_SIZE 100

// Function to find the largest integer in an array
int findLargest(int arr[], int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to create a semaphore with an initial value and delete it
void manageSemaphore(int initialValue) {
    sem_t *sem = sem_open("/my_semaphore", O_CREAT, 0644, initialValue);
    if (sem == SEM_FAILED) {
        perror("Failed to open semaphore");
        exit(EXIT_FAILURE);
    }

    // Simulate using the semaphore here

    if (sem_close(sem) != 0) {
        perror("Failed to close semaphore");
    }

    if (sem_unlink("/my_semaphore") != 0) {
        perror("Failed to unlink semaphore");
    }
}

int main() {
    int array[MAX_SIZE];
    int size = 0;
    printf("Enter integers (non-integer to stop):\n");

    while (scanf("%d", &array[size]) == 1 && size < MAX_SIZE) {
        size++;
    }

    if (size > 0) {
        int largest = findLargest(array, size);
        printf("The largest integer is: %d\n", largest);
    } else {
        printf("No integers were entered.\n");
    }

    manageSemaphore(1);

    return 0;
}
