    private Class<?> fetchClassDefinition(String className) throws ClassNotFoundException {
        try {
            String url = "https://api.example.com/classes/" + className;
            JsonNode response = objectMapper.readTree(performApiCall(url));
            return Class.forName(response.get("classPath").asText());
        } catch (IOException e) {
            throw new ClassNotFoundException(className, e);
        }
    }

    private JsonNode fetchConstructorInfo(String className) throws IOException {
        String url = "https://api.example.com/classes/" + className;
        return objectMapper.readTree(performApiCall(url)).get("constructors");
    }

    private Constructor<?> findSuitableConstructor(Class<?> clazz, JsonNode constructorInfo) {
        for (JsonNode node : constructorInfo) {
            try {
                Class<?>[] paramTypes = new Class<?>[node.size()];
                for (int i = 0; i < node.size(); i++) {
                    String paramName = node.get(i).asText();
                    paramTypes[i] = classCache.computeIfAbsent(paramName, this::fetchClassDefinition);
                }
                return clazz.getConstructor(paramTypes);
            } catch (NoSuchMethodException ignored) {
            }
        }
        throw new IllegalStateException("No suitable constructor found for " + clazz.getName());
    }

    private Object instantiateObject(Constructor<?> constructor, byte[] data, int offset, int length)
            throws IllegalAccessException, InstantiationException {
