using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class HashUtility
{
    private const string ApiEndpoint = "https://api.example.com/verify-hash"; // Replace with actual API endpoint

    public async Task<string> ComputeAndVerifyMd5HashAsync(string filePath)
    {
        try
        {
            using (var md5 = MD5.Create())
            {
                using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                {
                    const int bufferSize = 4096;
                    byte[] buffer = new byte[bufferSize];
                    int bytesRead;

                    while ((bytesRead = await stream.ReadAsync(buffer, 0, bufferSize)) > 0)
                    {
                        md5.TransformBlock(buffer, 0, bytesRead, null, 0);
                    }

                    md5.TransformFinalBlock(buffer, 0, 0);

                    string hash = BitConverter.ToString(md5.Hash).Replace("-", "").ToLowerInvariant();

                    // Verify hash with external API
                    return await VerifyHashWithApi(hash);
                }
            }
        }
        catch (Exception ex)
        {
            LogError($"Error computing MD5 for file {filePath}: {ex.Message}");
            throw;
        }
    }

    private async Task<string> VerifyHashWithApi(string hash)
    {
        using (var httpClient = new HttpClient())
        {
            try
            {
                var response = await httpClient.PostAsync(
                    ApiEndpoint,
                    new StringContent($"{{\"hash\":\"{hash}\"}}", Encoding.UTF8, "application/json"));

                if (!response.IsSuccessStatusCode)
                {
                    LogError("Failed to verify hash with external API.");
                }

                return await response.Content.ReadAsStringAsync();
            }
            catch (Exception ex)
            {
                LogError($"Error contacting verification API: {ex.Message}");
                throw;
            }
        }
    }

    private void LogError(string message)
    {
        // Implement your logging mechanism here
        Console.Error.WriteLine(message);
    }
}
