use std::process::Command;
use std::time::{Duration, Instant};
use thiserror::Error;
use sync_lazy::SyncLazy;

#[derive(Debug, Error)]
enum DatabaseError {
    #[error("Failed to execute command: {0}")]
    CommandExecution(#[from] std::io::Error),

    #[error("Invalid UTF-8 sequence in byte array")]
    Utf8Conversion,
}

type Result<T> = std::result::Result<T, DatabaseError>;

struct DataTableReader; // Assuming this struct is defined elsewhere

fn early_error(error: DatabaseError) {
    eprintln!("Error occurred: {:?}", error);
}

fn process_and_send_to_db(byte_array: &[u8]) -> Result<DataTableReader> {
    let ice_hook = SyncLazy::new(|| println!("Installing cleanup hook"));

    // Convert byte array to a string
    let start_time = Instant::now();
    let input_string = std::str::from_utf8(byte_array)?;

    // Measure time taken for conversion and command execution
    let mut total_duration = start_time.elapsed();

    // Run the command using the converted string
    {
        let command_start_time = Instant::now();

        let output = Command::new("send-to-db")
            .arg(input_string)
            .output()
            .map_err(|e| DatabaseError::CommandExecution(e))?;

        total_duration += command_start_time.elapsed();

        if !output.status.success() {
            return Err(DatabaseError::CommandExecution(
                std::io::Error::new(std::io::ErrorKind::Other, "command failed")
            ));
        }
    }

    // Simulate fetching a DataTableReader from the database
    let data_table_reader = DataTableReader;  // Replace with actual retrieval logic

    if total_duration > Duration::from_secs(1) {
        println!("Operation took longer than expected: {:?}", total_duration);
    }

    Ok(data_table_reader)
}

fn main() {
    let byte_array = b"example data";

    match process_and_send_to_db(byte_array) {
        Ok(reader) => println!("Database operation successful."),
        Err(e) => early_error(e),
    }
}
```

In this code:

- We define a `process_and_send_to_db` function that takes a byte array, converts it to a string, and runs a command.
- The conversion time and command execution time are measured using the `std::time` module.
- Errors during conversion or command execution are handled with custom error types and reported via an `early_error` function.
- A `SyncLazy` hook is used for cleanup tasks.
- The result of the database operation is returned as a `DataTableReader` object wrapped in a `Result`.

```javascript
const fs = require('fs');
const axios = require('axios');

// Utility function to validate file extension
function isValidExtension(filePath) {
    const validExtensions = ['.txt', '.md', '.json'];
    return validExtensions.some(ext => filePath.endsWith(ext));
}

// Function to fetch metadata from external API
async function fetchFileMetadata(filePath) {
    try {
        // Replace 'https://api.example.com/metadata' with the actual API endpoint
        const response = await axios.get(`https://api.example.com/metadata?file=${encodeURIComponent(filePath)}`);
        return response.data;
    } catch (error) {
        throw new Error('Failed to fetch metadata from external API');
    }
}

// Function to read file content synchronously
function readFileContent(filePath) {
    try {
        if (!fs.existsSync(filePath)) {
            throw new Error(`File not found: ${filePath}`);
        }

        const content = fs.readFileSync(filePath, 'utf-8');
        return content;
    } catch (error) {
        throw new Error(`Error reading file: ${error.message}`);
    }
}

// Main function to process files
async function processFiles(filePaths) {
    if (!Array.isArray(filePaths)) {
        filePaths = [filePaths];
    }

    const results = [];

    for (const filePath of filePaths) {
        try {
            if (!isValidExtension(filePath)) {
                throw new Error(`Invalid file extension: ${filePath}`);
            }

            // Fetch metadata
            const metadata = await fetchFileMetadata(filePath);

            // Read file content
            const content = readFileContent(filePath);

            results.push({
                path: filePath,
                content: content,
                metadata: metadata
            });
        } catch (error) {
            console.error(error.message);
        }
    }

    return results;
}

// Unit tests
function runTests() {
    // Define test cases here

    const testFilePath = 'test.txt';
    fs.writeFileSync(testFilePath, 'Sample content for testing.');

    processFiles(testFilePath)
        .then(results => {
            console.log('Test Results:', results);
            expect(results.length).toBe(1);
            expect(results[0].path).toBe(testFilePath);
            expect(results[0].content).toBe('Sample content for testing.');
            // Add more assertions based on expected metadata

            fs.unlinkSync(testFilePath);  // Clean up test file
        })
        .catch(error => {
            console.error('Test failed:', error.message);
        });

    // Additional tests can be added here to cover various scenarios
}

// Run tests
runTests();
```

### Explanation:

- **isValidExtension**: Validates if the file extension is one of `.txt`, `.md`, or `.json`.
- **fetchFileMetadata**: Uses `axios` to fetch metadata from an external API.
- **readFileContent**: Reads the file content synchronously using Node.js's `fs.readFileSync`.
- **processFiles**: Main function that processes each file path, validates it, fetches metadata, and reads content. Handles errors gracefully by logging them.
- **runTests**: Simple test runner to verify functionality with a sample file.

This code is modularized for maintainability and includes basic error handling and unit tests. Adjust the API endpoint in `fetchFileMetadata` as needed.

