            {
                Console.WriteLine($"Adding and starting website '{siteName}' at {directoryPath}...");
                // ExternalApi.AddWebsite(directoryPath, siteName);
                // ExternalApi.StartWebsite(siteName);

                LogAction($"Successfully added and started website '{siteName}'.");
            }

            return $"Site '{siteName}' added and started successfully.";
        }
        catch (Exception ex)
        {
            LogError($"Failed to add/start the website: {ex.Message}");
            return $"Error: Failed to add/start the website. {ex.Message}";
        }
    }

    public async Task<string> CalculateFileMd5Async(string filePath, int bufferSize = 8192)
    {
        try
        {
            using (var md5 = MD5.Create())
            {
                if (Uri.IsWellFormedUriString(filePath, UriKind.Absolute))
                {
                    // Handle remote URL
                    return await CalculateRemoteFileMd5Async(md5, filePath, bufferSize);
                }
                else
                {
                    // Handle local file
                    using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize, useAsync: true))
                    {
                        var hash = await ComputeHashAsync(md5, stream);
                        return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to calculate MD5 for {filePath}: {ex.Message}");
            throw;
        }
    }

    private async Task<string> CalculateRemoteFileMd5Async(MD5 md5, string url, int bufferSize)
    {
        using (var httpClient = new HttpClient())
        {
            var responseStream = await httpClient.GetStreamAsync(url);
            return BitConverter.ToString(await ComputeHashAsync(md5, responseStream)).Replace("-", "").ToLowerInvariant();
        }
    }

    private async Task<byte[]> ComputeHashAsync(MD5 md5, Stream stream)
    {
        var hash = new byte[md5.HashSize / 8];
        using (var buffer = new MemoryStream())
        {
            var chunk = new byte[buffer.Capacity];
            int bytesRead;
            while ((bytesRead = await stream.ReadAsync(chunk, 0, chunk.Length)) > 0)
            {
                buffer.Write(chunk, 0, bytesRead);
            }
            buffer.Seek(0, SeekOrigin.Begin);
            hash = md5.ComputeHash(buffer);
        }
        return hash;
    }

    private void LogAction(string message)
    {
        Console.WriteLine($"[INFO] {message}");
        // Implement actual logging
    }

    private void LogError(string message)
    {
        Console.WriteLine($"[ERROR] {message}");
        // Implement actual error logging
    }
}
