public class UserPreferencesLoader
{
    private readonly string _binaryFilePath;
    private readonly DatabaseContext _dbContext;
    private readonly ILogger _logger;

    public UserPreferencesLoader(string binaryFilePath, DatabaseContext dbContext, ILogger logger)
    {
        _binaryFilePath = binaryFilePath ?? throw new ArgumentNullException(nameof(binaryFilePath));
        _dbContext = dbContext ?? throw new ArgumentNullException(nameof(dbContext));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<CustomDataStructure> LoadUserPreferencesAsync(int userId)
    {
        try
        {
            if (File.Exists(_binaryFilePath))
            {
                using var fileStream = new FileStream(_binaryFilePath, FileMode.Open, FileAccess.Read, FileShare.Read);
                using var binaryFormatter = new BinaryFormatter();

                lock (fileStream) // Ensure thread safety for multiple concurrent reads
                {
                    return (CustomDataStructure)binaryFormatter.Deserialize(fileStream);
                }
            }
        }
        catch (Exception ex)
