    }

    public void InsertStringAfterFirstOccurrence(IForwardList<string> list, string firstStr, string secondStr)
    {
        if (list == null) throw new ArgumentNullException(nameof(list));

        var position = list.FindIndex(x => x.Equals(firstStr));
        if (position != -1)
        {
            list.Insert(position + 1, secondStr);
        }
        else
        {
            list.Add(secondStr);
        }
    }
}

