#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SESSIONS 100

typedef struct {
    int incomingBytes;
    int outgoingBytes;
} TrafficStats;

typedef struct {
    int UserId;
    int SessionId;
    TrafficStats stats;
} UserSession;

typedef struct {
    UserSession* sessions[MAX_SESSIONS];
    size_t count;
    pthread_mutex_t lock;
} SessionList;

void initializeTrafficStats(TrafficStats *stats) {
    stats->incomingBytes = rand() % 1000000; // Random bytes for demo
    stats->outgoingBytes = rand() % 1000000;
}

void addSession(SessionList* list, int userId, int sessionId) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&list->lock);
        return; // List is full
    }

    UserSession* newSession = malloc(sizeof(UserSession));
    if (!newSession) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    newSession->UserId = userId;
    newSession->SessionId = sessionId;
    initializeTrafficStats(&newSession->stats);

    list->sessions[list->count++] = newSession;

    pthread_mutex_unlock(&list->lock);
}

void populateSessions(SessionList* list, int N) {
    for (int i = 0; i < N; ++i) {
        addSession(list, rand() % 10000, rand() % 10000); // Random user/session IDs
    }
}

void freeSessions(SessionList* list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->sessions[i]);
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    srand((unsigned int)time(NULL));

    SessionList sessionList = { .count = 0 };
    pthread_mutex_init(&sessionList.lock, NULL);

    populateSessions(&sessionList, MAX_SESSIONS + 10); // Attempt to add more than max

    freeSessions(&sessionList);
    pthread_mutex_destroy(&sessionList.lock);

    return 0;
}
