```java
import java.util.*;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DisjointPairs {

    private static final Logger logger = Logger.getLogger(DisjointPairs.class.getName());
    private static final String DB_URL = "jdbc:mysql://localhost:3306/disjoint_pairs_db";
    private static final String USER = "root";
    private static final String PASS = "password";

    public static int countDisjointPairs(int[] array, boolean removeDuplicates) {
        long startTime = System.currentTimeMillis();

        if (removeDuplicates) {
            Set<Integer> uniqueElements = new HashSet<>();
            for (int num : array) {
                uniqueElements.add(num);
            }
            array = uniqueElements.stream().mapToInt(Number::intValue).toArray();
        }

        UnionFind uf = new UnionFind(array.length);
        int disjointPairsCount = 0;

        // Simulate pair checking
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                long operationTime = System.currentTimeMillis();
                if (uf.union(i, j)) {
                    disjointPairsCount++;
                }
                logger.log(Level.INFO, "Checked pair ({}, {}): {} ms", new Object[]{i, j, System.currentTimeMillis() - operationTime});
            }
        }

        storeResultInDatabase(array, disjointPairsCount);
        long endTime = System.currentTimeMillis();
        logger.info("Operation took: {} ms", (endTime - startTime));

        return disjointPairsCount;
    }

    private static void storeResultInDatabase(int[] array, int count) {
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
            String sql = "INSERT INTO results (array_data, disjoint_count) VALUES (?, ?)";
            PreparedStatement pstmt = conn.prepareStatement(sql);
            pstmt.setString(1, Arrays.toString(array));
            pstmt.setInt(2, count);
            pstmt.executeUpdate();
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Database operation failed", e);
        }
    }

    public static void validateAgainstGroundTruth(int[] array, int expectedCount) {
        int actualCount = countDisjointPairs(array, false);
        if (actualCount != expectedCount) {
            logger.severe("Validation failed for array: " + Arrays.toString(array));
        } else {
            logger.info("Validation passed for array: " + Arrays.toString(array));
        }
    }

    public static void main(String[] args) {
        int[] testArray = {1, 2, 3, 4, 5};
        countDisjointPairs(testArray, false);
        validateAgainstGroundTruth(testArray, 10); // Assuming ground truth is known
    }

    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public int find(int p) {
            if (parent[p] != p) {
                parent[p] = find(parent[p]);
            }
            return parent[p];
        }

        public boolean union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);

            if (rootP == rootQ) return false;

            if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
            return true;
        }
    }

    // Unit tests
    public static void runUnitTests() {
        assert countDisjointPairs(new int[]{}, false) == 0 : "Test failed for empty array";
        assert countDisjointPairs(new int[]{1}, false) == 0 : "Test failed for single element array";
        assert countDisjointPairs(new int[]{1, 2, 3, 4, 5}, false) == 10 : "Test failed for unique elements array";
        assert countDisjointPairs(new int[]{1, 1, 1, 1}, true) == 0 : "Test failed for duplicate elements array with duplicates removed";
    }
}
```

### Key Points:
- **Union-Find**: Implemented with path compression and union by rank.
