    // Rate Limiting: Check if the IP has exceeded 5 requests per minute
    $currentTime = time();
    if (file_exists($rateLimitFile)) {
        $logData = json_decode(file_get_contents($rateLimitFile), true);
        $requests = array_filter($logData, function ($timestamp) use ($currentTime) {
            return ($currentTime - $timestamp) < 60;
        });
        if (count($requests) >= 5) {
            return "Rate limit exceeded. Try again later.";
        }
    } else {
        $requests = [];
    }

    // Add current request timestamp
