        $this->charSet = $charSet ?: '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!@#$%^&*()_+';
    }

    public function generate(int $length): string {
        if ($length <= 0) {
            throw new InvalidArgumentException('Length must be greater than zero.');
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, strlen($this->charSet) - 1);
            $randomString .= $this->charSet[$randomIndex];
        }

        return $randomString;
    }
}

// PasswordHasher.php
class PasswordHasher {
    private $rounds;

    public function __construct(int $rounds = 12) {
        $this->rounds = $rounds;
    }

    public function hash(string $password): string {
        if (empty($password)) {
            throw new InvalidArgumentException('Password cannot be empty.');
        }

        return password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->rounds]);
    }

    public function verify(string $password, string $hash): bool {
        if (empty($password) || empty($hash)) {
            throw new InvalidArgumentException('Invalid input for verification.');
        }

        return password_verify($password, $hash);
    }
}

// AuthService.php
class AuthService {
    private $apiUrl;
    private $httpClient;

    public function __construct(string $apiUrl, $httpClient) {
        $this->apiUrl = $apiUrl;
        $this->httpClient = $httpClient;
    }

    public function storeHashedPassword(string $userId, string $hash): bool {
        $response = $this->sendRequest('POST', "/users/{$userId}/password", ['hash' => $hash]);
        return $response['success'] ?? false;
    }

    private function sendRequest(string $method, string $endpoint, array $data) {
        try {
            $url = $this->apiUrl . $endpoint;
            $options = [
                'http' => [
                    'header'  => "Content-type: application/json\r\n",
                    'method'  => $method,
                    'content' => json_encode($data),
                ],
            ];

            $context = stream_context_create($options);
            $result = file_get_contents($url, false, $context);

            if ($result === FALSE) {
                throw new Exception("Error communicating with external service.");
            }

            return json_decode($result, true);
        } catch (Exception $e) {
            // Log error or handle it appropriately
            return ['success' => false];
        }
    }
}

