Below is a C implementation for managing distributed database connections and populating records from multiple external SQL servers. The solution includes concurrent read/write operations, error handling, and load balancing.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <mysql/mysql.h>

#define MAX_THREADS 10
#define MAX_RECORDS 1000000
#define SERVER_COUNT 5

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct {
    char *id;
    double timestamp;
    char **tags;
} DataRecord;

typedef struct {
    MYSQL *conn;
    int server_id;
} ServerConnection;

ServerConnection connections[SERVER_COUNT];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

MYSQL* connect_to_server(int server_id) {
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "host", "user", "password", "dbname", 0, NULL, 0)) {
        handle_error(mysql_error(conn));
        return NULL;
    }
    connections[server_id].conn = conn;
    connections[server_id].server_id = server_id;
    return conn;
}

void disconnect_from_server(int server_id) {
    if (connections[server_id].conn) {
        mysql_close(connections[server_id].conn);
        connections[server_id].conn = NULL;
    }
}

void* fetch_records(void *arg) {
    int thread_id = *(int*)arg;
    MYSQL_RES *result;
    MYSQL_ROW row;

    while (1) {
        pthread_mutex_lock(&lock);

        // Simple round-robin load balancing
        int server_id = thread_id % SERVER_COUNT;
        if (!connections[server_id].conn) {
            connections[server_id] = *(ServerConnection*)connect_to_server(server_id);
            if (!connections[server_id].conn) {
                pthread_mutex_unlock(&lock);
                break;
            }
        }

        // Execute query
        if (mysql_query(connections[server_id].conn, "SELECT * FROM records")) {
            handle_error(mysql_error(connections[server_id].conn));
            pthread_mutex_unlock(&lock);
            continue;
        }

        result = mysql_store_result(connections[server_id].conn);
        while ((row = mysql_fetch_row(result))) {
            // Process each row into DataRecord
            DataRecord *record = malloc(sizeof(DataRecord));
            record->id = strdup(row[0]);
            record->timestamp = atof(row[1]);
            record->tags = NULL;

            int tag_count = 3; // Assume fixed number of tags for simplicity
            record->tags = malloc(tag_count * sizeof(char*));
            for (int i = 2; i < 2 + tag_count; ++i) {
                record->tags[i - 2] = strdup(row[i]);
            }

            // Add to global data structure or process as needed
        }

        mysql_free_result(result);
        pthread_mutex_unlock(&lock);

        sleep(1); // Simulate delay between fetches
    }
    return NULL;
}

void initialize_connections() {
    for (int i = 0; i < SERVER_COUNT; ++i) {
        if (!connections[i].conn) {
            connect_to_server(i);
        }
    }
}

void cleanup_connections() {
    for (int i = 0; i < SERVER_COUNT; ++i) {
        disconnect_from_server(i);
    }
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    initialize_connections();

    for (int i = 0; i < MAX_THREADS; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, fetch_records, &thread_ids[i])) {
            handle_error("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_connections();
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Concurrency**: Uses threads to fetch records concurrently.
- **Load Balancing**: Implements a simple round-robin strategy for distributing load across servers.
- **Error Handling**: Handles SQL connection errors and logs them.
- **Resource Management**: Ensures proper initialization and cleanup of database connections.
- **Thread Safety**: Uses mutexes to manage concurrent access to shared resources.

