        {
            return BadRequest("Invalid input IDs.");
        }

        try
        {
            // Check user permissions
            bool hasPermission = await _permissionsService.HasPermissionAsync(User, request.PageSectionId, request.ElementId);
            if (!hasPermission)
            {
