// Union-Find data structure with path compression and union by rank
class UnionFind {
public:
    UnionFind(size_t n) : parent(n), rank(n, 0) {
        for (size_t i = 0; i < n; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);
        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV])
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

private:
    std::vector<int> parent, rank;
};

// Thread-safe JSON parsing
std::unordered_map<std::string, std::variant<int, double, std::string, bool>> parseJSONConfig(const std::string& filepath) {
    static std::mutex jsonMutex;
    std::lock_guard<std::mutex> lock(jsonMutex);

    std::ifstream file(filepath);
    Json::CharReaderBuilder readerBuilder;
    Json::Value root;

    if (!file.is_open()) {
        std::cerr << "Error opening JSON config file." << std::endl;
        return {};
    }

    std::string errs;
    bool parsingSuccessful = Json::parseFromStream(readerBuilder, file, &root, &errs);
    if (!parsingSuccessful) {
        std::cerr << "Failed to parse JSON: " << errs << std::endl;
        return {};
    }

    // Convert the parsed JSON into a std::unordered_map
    auto config = std::make_shared<std::unordered_map<std::string, std::variant<int, double, std::string, bool>>>();
    for (const auto& key : root.getMemberNames()) {
        if (root[key].isInt())
            (*config)[key] = root[key].asInt();
        else if (root[key].isDouble())
            (*config)[key] = root[key].asDouble();
        else if (root[key].isString())
            (*config)[key] = root[key].asString();
        else if (root[key].isBool())
            (*config)[key] = root[key].asBool();
    }
    return *config;
}

// Function to fetch metadata with retry logic and exponential backoff
bool fetchDataWithRetry(const std::string& url, std::string& response) {
    static constexpr int maxRetries = 5;
    int attempt = 0;
    int waitTime = 100; // Start with 100ms

    while (attempt < maxRetries) {
        CURL* curl = curl_easy_init();
        if (!curl) return false;

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        CURLcode res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);

        if (res == CURLE_OK) return true;

        std::cerr << "Request failed: " << curl_easy_strerror(res)
                  << ". Retrying in " << waitTime / 1000.0 << " seconds..." << std::endl;

        std::this_thread::sleep_for(std::chrono::milliseconds(waitTime));
        attempt++;
        waitTime *= 2; // Exponential backoff
    }

    return false;
}

size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Main processing function using multi-threading
void processArray(const std::vector<int>& array, const std::unordered_map<std::string, std::variant<int, double, std::string, bool>>& config) {
    size_t n = array.size();
    UnionFind uf(n);

    auto worker = [&](size_t start, size_t end) {
        for (size_t i = start; i < end; ++i) {
            for (size_t j = i + 1; j < n; ++j) {
                if ((array[i] % config.at("pair_modulus").as_int() == array[j] % config.at("pair_modulus").as_int())) {
                    uf.unite(i, j);
                }
            }
        }
    };

    const size_t numThreads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads(numThreads);

    for (size_t i = 0; i < numThreads; ++i) {
        size_t start = i * n / numThreads;
        size_t end = (i + 1) * n / numThreads;
        threads[i] = std::thread(worker, start, end);
    }

    for (auto& t : threads)
        t.join();

    // Count disjoint sets
    std::unordered_map<int, int> componentSize;
    for (size_t i = 0; i < n; ++i) {
        int root = uf.find(i);
        if (++componentSize[root] == 2) { // Found a pair
            std::cout << "Disjoint pair found: (" << array[i] << ", some_other_element)" << std::endl;
        }
    }
}

// Command-line interface for testing the utility
int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <config_file.json>" << std::endl;
        return 1;
    }

    auto config = parseJSONConfig(argv[1]);
    if (config.empty()) return 1;

    size_t arraySize = config.at("array_size").as_int();
    std::vector<int> array(arraySize);

    // Generate dummy data for demonstration
    for (size_t i = 0; i < arraySize; ++i)
        array[i] = rand() % 100;

    processArray(array, config);

    return 0;
}
