#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* appendSlashIfNeeded(const char *input, size_t size_limit) {
    size_t input_length = strlen(input);

    if (input_length >= size_limit) {
        return NULL;
    }

    // Allocate memory for new string with slash and null terminator
    char *result = (char *)malloc(size_limit + 1);
    if (!result) {
        return NULL; // Memory allocation failed
    }

    strncpy(result, input, input_length);
    result[input_length] = '/';  // Append the slash
    result[input_length + 1] = '\0'; // Null-terminate the string

    return result;
}
