def sort_and_extract_sequence(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        # Sort the lines
        sorted_lines = sorted(lines)

        if not sorted_lines:
            raise ValueError("File is empty")

        # Extract sequence number from last line
        last_line = sorted_lines[-1].strip()
        parts = last_line.split()

        if len(parts) == 0 or not parts[-1].isdigit():
            raise ValueError("No valid sequence number found in the last line")

        return int(parts[-1])

    except (IOError, OSError) as e:
        print(f"File error: {e}")
    except ValueError as ve:
        print(f"Value error: {ve}")
    except Exception as ex:
        print(f"An unexpected error occurred: {ex}")

# Example usage:
# sequence_number = sort_and_extract_sequence('example.txt')
