    private void ValidateRange(double min, double max)
    {
        if (min >= max)
        {
            throw new ArgumentException("Minimum value must be less than maximum value.");
        }
    }

    public override string ToString()
    {
        return $"Weather Simulator at Latitude: {_location.Latitude}, Longitude: {_location.Longitude}";
    }

    // Example distribution functions
    private static double GaussianDistribution(double[] values)
    {
        double mean = values[1];
        double stdDev = values[2];
        double u1 = 1.0 - new Random().NextDouble();
        double u2 = 1.0 - new Random().NextDouble();

        return mean + stdDev * Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
    }

    private static double UniformDistribution(double[] values)
    {
        return values[0];
    }
}
