@RestController
class PokemonController {

    private final WebClient primaryWebClient;
    private final WebClient fallbackWebClient;

    PokemonController(WebClient primaryWebClient, WebClient fallbackWebClient) {
        this.primaryWebClient = primaryWebClient;
        this.fallbackWebClient = fallbackWebClient;
    }

    @GetMapping("/pokemon/{id}")
    public CompletableFuture<Map<String, Object>> getPokemonDetails(@PathVariable String id) {
        ExecutorService executorService = PokemonServiceApplication.class.getAnnotation(Applications.class).getBean(ExecutorService.class);

        return CompletableFuture.allOf(
                fetchPokemonData(primaryWebClient, id, "weaknesses"),
                fetchPokemonData(primaryWebClient, id, "evolution"),
                fetchPokemonData(primaryWebClient, id, "habitat")
        ).thenApply(v -> {
            Map<String, Object> result = new java.util.HashMap<>();
            // Assuming the methods return some map structure
            CompletableFuture<Map<String, Object>> weaknessesFuture = (CompletableFuture<Map<String, Object>>) v[0];
            CompletableFuture<Map<String, Object>> evolutionFuture = (CompletableFuture<Map<String, Object>>) v[1];
            CompletableFuture<Map<String, Object>> habitatFuture = (CompletableFuture<Map<String, Object>>) v[2];

            return result.putAll(weaknessesFuture.join())
                         .putAll(evolutionFuture.join())
                         .putAll(habitatFuture.join());
        });
    }

    private CompletableFuture<Map<String, Object>> fetchPokemonData(WebClient webClient, String pokemonId, String dataType) {
        URI uri = UriComponentsBuilder.fromHttpUrl("https://api.example.com/pokemon/{id}/{type}")
                .build(pokemonId, dataType).toUri();

        return webClient.get()
                .uri(uri)
                .retrieve()
                .bodyToMono(JsonNode.class)
                .onErrorResume(ex -> {
                    // Fallback logic
                    URI fallbackUri = UriComponentsBuilder.fromHttpUrl("https://fallback.api.com/pokemon/{id}/{type}")
                            .build(pokemonId, dataType).toUri();
                    return webClient.get()
                            .uri(fallbackUri)
                            .retrieve()
                            .bodyToMono(JsonNode.class);
                })
                .flatMap(json -> {
                    Map<String, Object> data = new java.util.HashMap<>();
                    // Populate data map from JSON
                    json.fields().forEachRemaining(entry -> data.put(entry.getKey(), entry.getValue()));
                    return CompletableFuture.completedFuture(data);
                }).toFuture();
    }
}

