<?php

require 'vendor/autoload.php';

use PhpAmqpLib\Connection\AMQPStreamConnection;
use PhpAmqpLib\Message\AMQPMessage;

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    // Rate limiting parameters
    $rateLimitKey = "update_limit:" . $last_modified_ip;
    $maxUpdates = 5;

    // Connect to Redis
    $redis = new Redis();
    if (!$redis->connect('localhost', 6379)) {
        logError("Redis connection failed", ['clinic_id' => $clinic_id, 'ip' => $last_modified_ip]);
        return "Rate limiting error: Unable to connect to Redis.";
    }

    // Check rate limit
    $currentCount = (int) $redis->get($rateLimitKey);
    if ($currentCount >= $maxUpdates) {
        logError("Rate limit exceeded", ['clinic_id' => $clinic_id, 'ip' => $last_modified_ip]);
        return "Update failed: Rate limit exceeded.";
    }

    // Increment the count for this IP
    $redis->incr($rateLimitKey);
    $redis->expire($rateLimitKey, 60); // Reset every minute

    // Begin distributed transaction and prepare to update database nodes
    try {
        // Connect to primary database node (use your actual connection details)
        $pdo = new PDO('mysql:host=primary_node_host;dbname=mydb', 'username', 'password');
        $pdo->beginTransaction();

        // Prepare the statement for updating clinic status
        $stmt = $pdo->prepare("UPDATE clinics SET status = :new_status, last_modified_ip = :last_modified_ip, last_modified_date = NOW() WHERE clinic_id = :clinic_id");

        // Bind parameters
        $stmt->bindParam(':new_status', $new_status);
        $stmt->bindParam(':last_modified_ip', $last_modified_ip);
        $stmt->bindParam(':clinic_id', $clinic_id);

        // Execute the statement across distributed database nodes (pseudo-implementation)
        foreach ($distributedNodes as $node) {
            // Update each node
            updateNode($node, $stmt); 
        }

        // Commit transaction if all updates are successful
        $pdo->commit();
    } catch (\Exception $e) {
        logError("Database error", ['clinic_id' => $clinic_id, 'ip' => $last_modified_ip, 'error' => $e->getMessage()]);

        // Rollback in case of an exception
        if (isset($pdo)) {
            $pdo->rollBack();
        }

        return "Update failed: Database error.";
    }

    return "Clinic status updated successfully.";
}

function updateNode($node, $stmt) {
    // Pseudo-implementation for updating a distributed node
    $pdo = new PDO("mysql:host={$node['host']};dbname=mydb", 'username', 'password');
    $stmt->execute();
}

function logError($message, $context = []) {
    // Connect to RabbitMQ server (ELK stack)
    $connection = new AMQPStreamConnection('localhost', 5672, 'guest', 'guest');
    $channel = $connection->channel();

    // Declare a queue for logging errors
    $channel->queue_declare('log_errors', false, true, false, false);

    $context['message'] = $message;
    $msgBody = json_encode($context);
    $msg = new AMQPMessage($msgBody, ['delivery_mode' => 2]);

    // Publish the error message to the queue
    $channel->basic_publish($msg, '', 'log_errors');

    // Close connection
    $channel->close();
    $connection->close();
}

