using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static XmlNode GetFirstElementByName(XmlDocument xmlDoc, string elementName)
    {
        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select($"//{elementName}");

        if (!nodes.MoveNext())
            throw new Exception("No elements found with the given name.");

        if (nodes.Count > 1)
            throw new Exception("Multiple elements found with the same name.");

        return nodes.Current as XmlNode;
    }
}

