char* appendSlashIfWithinLimit(const char* input, size_t limit)
{
    if (strlen(input) >= limit)
        return NULL;

    size_t newLength = strlen(input) + 2; // For slash and null terminator
    char* result = malloc(newLength);

    if (!result)
        return NULL;

    strcpy(result, input);
    strcat(result, "/");

    return result;
}
