pub async fn execute_complex_query(data: &[u8]) -> Result<Vec<serde_json::Value>, String> {
    let start_time = Instant::now();

    // Convert byte array to formatted JSON string
    let json_str = match serde_json::from_slice::<serde_json::Value>(data) {
        Ok(val) => val.to_string(),
        Err(err) => return Err(format!("JSON conversion error: {}", err)),
    };

    // Measure the time taken for conversion
    let conversion_time = start_time.elapsed();

    info!("Conversion took {:?}", conversion_time);

    // Setup database connection pooling (assuming tokio-postgres is used)
    let pool = SyncLazy::new(|| {
        // Replace with actual connection pool setup
        tokio_postgres::connect("host=localhost user=postgres dbname=mydb", NoTls).unwrap()
    });

    // Execute the complex query using the formatted JSON string
    let client = pool.get_ref();
    let query_result: Result<Vec<serde_json::Value>, PgError> = async {
        let mut rows = client.query("SELECT * FROM table1 JOIN table2 ON condition WHERE data=$1", &[&json_str]).await?;

        // Process results into Vec<serde_json::Value>
        let mut result_vec = Vec::new();
        while let Some(row) = rows.try_next().await? {
            let row_value: serde_json::Value = serde_json::from_value(serde_json::to_value(row)?).unwrap();
            result_vec.push(row_value);
        }

        Ok(result_vec)
    }.await;

    // Measure total execution time
    let total_time = start_time.elapsed();

    info!("Total query execution took {:?}", total_time);

    match query_result {
        Ok(values) => Ok(values),
        Err(e) => {
            early_error(&format!("Query execution error: {}", e));
            Err(format!("Database operation failed: {}", e))
        }
    }
}

