```c
#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_FILE "secure_messaging.log"

// Log errors to the specified file
void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

// Initialize OpenSSL algorithms based on configuration string
int initialize_secure_messaging(const char *config) {
    const EVP_CIPHER *(*get_aes256_cbc)(void) = NULL;
    const EVP_CIPHER *(*get_chacha20_poly1305)(void) = NULL;

    // Enable dynamic loading of crypto library modules
    if (!OPENSSL_init_crypto(OPENSSL_INIT_LOAD_ENVIRONMENT | OPENSSL_INIT_ADD_ALL_CIPHERS, NULL)) {
        log_error("Failed to initialize OpenSSL");
        return 0;
    }

    // Load AES-256 and ChaCha20 ciphers dynamically
    get_aes256_cbc = EVP_aes_256_cbc();
    get_chacha20_poly1305 = EVP_chacha20_poly1305();

    if (!get_aes256_cbc || !get_chacha20_poly1305) {
        log_error("Failed to load AES-256 or ChaCha20 ciphers");
        return 0;
    }

    // Initialize hashing algorithms
    const EVP_MD *(*get_sha256)(void) = NULL;
    const EVP_MD *(*get_sha384)(void) = NULL;
    const EVP_MD *(*get_sha512)(void) = NULL;

    get_sha256 = EVP_sha256();
    get_sha384 = EVP_sha384();
    get_sha512 = EVP_sha512();

    if (!get_sha256 || !get_sha384 || !get_sha512) {
        log_error("Failed to load SHA-256, SHA-384, or SHA-512 hashing algorithms");
        return 0;
    }

    // Parse configuration string and enable selected algorithms
    for (char *token = strtok((char *)config, ","); token; token = strtok(NULL, ",")) {
        if (strcmp(token, "AES-256") == 0) {
            // Enable AES-256 support
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            if (!ctx) {
                log_error("Failed to create AES-256 context");
                return 0;
            }
            EVP_CIPHER *cipher = get_aes256_cbc();
            if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
                log_error("Failed to initialize AES-256 encryption");
                EVP_CIPHER_CTX_free(ctx);
                return 0;
            }
            // Additional setup for AES-256 can be done here
            EVP_CIPHER_CTX_free(ctx);
        } else if (strcmp(token, "ChaCha20") == 0) {
            // Enable ChaCha20 support
            EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
            if (!ctx) {
                log_error("Failed to create ChaCha20 context");
                return 0;
            }
            EVP_CIPHER *cipher = get_chacha20_poly1305();
            if (!EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
                log_error("Failed to initialize ChaCha20 encryption");
                EVP_CIPHER_CTX_free(ctx);
                return 0;
            }
            // Additional setup for ChaCha20 can be done here
            EVP_CIPHER_CTX_free(ctx);
        } else if (strcmp(token, "SHA-256") == 0) {
            // Enable SHA-256 support
            const EVP_MD *md = get_sha256();
            if (!md) {
                log_error("Failed to initialize SHA-256");
                return 0;
            }
            // Additional setup for SHA-256 can be done here
        } else if (strcmp(token, "SHA-384") == 0) {
            // Enable SHA-384 support
            const EVP_MD *md = get_sha384();
            if (!md) {
                log_error("Failed to initialize SHA-384");
                return 0;
            }
            // Additional setup for SHA-384 can be done here
        } else if (strcmp(token, "SHA-512") == 0) {
            // Enable SHA-512 support
            const EVP_MD *md = get_sha512();
            if (!md) {
                log_error("Failed to initialize SHA-512");
                return 0;
            }
            // Additional setup for SHA-512 can be done here
        } else {
            char error_msg[256];
            snprintf(error_msg, sizeof(error_msg), "Unknown algorithm specified: %s", token);
            log_error(error_msg);
        }
    }

    // Clean up OpenSSL errors
    ERR_free_strings();

    return 1;
}
