use backtrace::Backtrace;
use rlimit::set_rlimit;
use sysinfo::{ProcessExt, System, ProcessorExt};

/// Custom logging hook to log compilation duration
fn custom_logging_hook(
    run: &RunCompiler,
    matches: &rustc_driver::Matches,
) -> rustc_driver::CompileResult<()> {
    if let Some(name) = matches.source_filenames().next() {
        let start_time = Instant::now();
        run.compile_match(matches)?;
        let duration = start_time.elapsed();

        println!("Compiled {} in {:?}", name, duration);
    }
    Ok(())
}

/// Function to limit RSS and monitor memory usage
fn monitor_rss_and_limit(max_rss: u64) -> bool {
    let system = System::new_all();

    for (pid, process) in system.get_process_list() {
        if pid == std::process::id() as u32 {
            let rss = process.ram();
            println!("Current RSS: {} KB", rss);

            if rss > max_rss {
                println!(
                    "RSS limit exceeded: current {}, maximum {}",
                    rss, max_rss
                );
                return false;
            }
        }
    }

    true
}

/// Function to compile a Rust source file with custom logging and resource monitoring
fn compile_with_resource_limits(
    source_path: &PathBuf,
    max_rss_kb: u64,
) -> i32 {
    // Check if the source file exists
    if !source_path.exists() {
        eprintln!("Source file not found: {:?}", source_path);
        return 1;
    }

    // Install an ICE hook with SyncLazy
    let _lazy_hook = SyncLazy::new(|| Box::new(custom_logging_hook));

    // Set the RSS limit using rlimit (example for Linux)
    match set_rlimit(sysinfo::ResourceLimit::RLIMIT_RSS, max_rss_kb) {
        Ok(_) => println!("RSS limit set to {} KB", max_rss_kb),
        Err(e) => eprintln!("Failed to set RSS limit: {:?}", e),
    }

    // Check and log initial memory usage
    if !monitor_rss_and_limit(max_rss_kb) {
        return 2;
    }

    let start_time = Instant::now();

    // Compile the source file with custom logging hook and error handling
    match catch_with_exit_code(|| rustc_driver::RunCompiler::new().run(None, None)) {
        Ok(exit_code) => {
            if !monitor_rss_and_limit(max_rss_kb) {
                return 3;
            }

            let duration = start_time.elapsed();
            println!("Compilation finished in {:?}", duration);
            exit_code
        }
        Err(error) => {
            eprintln!("Error during compilation: {:?}", error);
            eprintln!("{:?}", Backtrace::new());
            4 // Return an appropriate non-zero exit code for errors
        }
    }
}

fn main() {
    let source_path = PathBuf::from("path/to/source.rs");
    let max_rss_kb = 10240; // Example RSS limit in KB

    let result = compile_with_resource_limits(&source_path, max_rss_kb);

    std::process::exit(result);
}
```

### Explanation:
1. **Custom Logging Hook**: Uses `rustc_driver::RunCompiler` to log the duration of the compilation.
2. **RSS Monitoring and Limiting**: Utilizes the `sysinfo` crate to monitor resident set size (RSS) before and after the compilation, aborting if the RSS exceeds a specified threshold.
3. **Error Handling**: Implements error handling for missing files, compiler errors, and resource limits using Rust's error management facilities.
4. **Maintainability**: The code is structured with functions that encapsulate specific tasks, ensuring readability and maintainability.

