```cpp
#include <vector>
#include <memory>

class OctreeNode {
public:
    struct Bounds {
        float x_min, y_min, z_min;
        float x_max, y_max, z_max;

        bool contains(const Point& point) const {
            return (point.x >= x_min && point.x <= x_max &&
                    point.y >= y_min && point.y <= y_max &&
                    point.z >= z_min && point.z <= z_max);
        }
    };

    OctreeNode(Bounds bounds, int level)
        : bounds_(bounds), level_(level), isLeaf_(true), objects_() {}

    bool insert(const Point& object) {
        if (!bounds_.contains(object)) return false;

        if (objects_.size() < maxCapacity_ || level_ >= maxLevel_) {
            objects_.push_back(object);
            return true;
        }

        if (isLeaf_) subdivide();

        for (auto& child : children_) {
            if (child->insert(object)) return true;
        }
        return false;
    }

private:
    static const int maxCapacity_ = 4; // Example capacity
    static const int maxLevel_ = 10;   // Example maximum level

    Bounds bounds_;
    std::vector<OctreeNode*> children_;
    bool isLeaf_;
    int level_;
    std::vector<Point> objects_;

    void subdivide() {
        float x_mid = (bounds_.x_min + bounds_.x_max) / 2;
        float y_mid = (bounds_.y_min + bounds_.y_max) / 2;
        float z_mid = (bounds_.z_min + bounds_.z_max) / 2;

        isLeaf_ = false;

        children_.emplace_back(new OctreeNode({bounds_.x_min, bounds_.y_min, bounds_.z_min,
                                              x_mid, y_mid, z_mid}, level_ + 1));
        children_.emplace_back(new OctreeNode({x_mid, bounds_.y_min, bounds_.z_min,
                                              bounds_.x_max, y_mid, z_mid}, level_ + 1));
        children_.emplace_back(new OctreeNode({bounds_.x_min, y_mid, bounds_.z_min,
                                              x_mid, bounds_.y_max, z_mid}, level_ + 1));
        children_.emplace_back(new OctreeNode({x_mid, y_mid, bounds_.z_min,
                                              bounds_.x_max, bounds_.y_max, z_mid}, level_ + 1));

        children_.emplace_back(new OctreeNode({bounds_.x_min, bounds_.y_min, z_mid,
                                              x_mid, y_mid, bounds_.z_max}, level_ + 1));
        children_.emplace_back(new OctreeNode({x_mid, bounds_.y_min, z_mid,
                                              bounds_.x_max, y_mid, bounds_.z_max}, level_ + 1));
        children_.emplace_back(new OctreeNode({bounds_.x_min, y_mid, z_mid,
                                              x_mid, bounds_.y_max, bounds_.z_max}, level_ + 1));
        children_.emplace_back(new OctreeNode({x_mid, y_mid, z_mid,
                                              bounds_.x_max, bounds_.y_max, bounds_.z_max}, level_ + 1));
    }
};

class Octree {
public:
    Octree(float featureSize, int initialLeafNodes, int maxCapacity)
        : root_(createNode(Bounds{0, 0, 0, worldSize_, worldSize_, worldSize_}, 0)),
          maxCapacity_(maxCapacity) {}

    ~Octree() { clear(root_.get()); }

    bool insert(const Point& object) {
        return root_->insert(object);
    }

private:
    using Bounds = OctreeNode::Bounds;
    struct Point {
        float x, y, z;
    };

    std::unique_ptr<OctreeNode> root_;
    int maxCapacity_;

    static const float worldSize_ = 100.0f; // Example world size

    static std::unique_ptr<OctreeNode> createNode(Bounds bounds, int level) {
        return std::make_unique<OctreeNode>(bounds, level);
    }

    void clear(OctreeNode* node) {
        if (!node || node->isLeaf_) return;

        for (auto& child : node->children_) {
            clear(child);
        }
    }
};

// Usage Example
void initializeOctree() {
    Octree octree(1.0f, 8, 10); // Feature size: 1.0, Initial leaf nodes: 8, Max capacity per node: 10

    Point object = {5.0f, 5.0f, 5.0f};
    if (octree.insert(object)) {
        std::cout << "Object inserted successfully." << std::endl;
    } else {
        std::cerr << "Failed to insert the object." << std::endl;
    }
}
```

This code defines a simple octree structure with support for dynamic resizing based on the number of objects. It uses smart pointers (`std::unique_ptr`) to manage memory efficiently and ensures that resources are deallocated when no longer needed. The `Octree` class provides an interface for inserting points into the spatial partitioning data structure, handling subdivision as necessary. Error checks can be further extended in a real-world application to handle specific conditions more gracefully.

