public class EvolutionDataFetcher {
    private static final Logger logger = Logger.getLogger(EvolutionDataFetcher.class.getName());
    private final ClassProvider classProvider;
    private final ConcurrentMap<String, PokemonData> cache;
    private final ScheduledExecutorService scheduler;
    private final HttpClient httpClient;
    private final int cacheSize;
    private final long requestTimeout;

    public EvolutionDataFetcher(ClassProvider classProvider, int cacheSize, long requestTimeout) {
        this.classProvider = classProvider;
        this.cache = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(2);
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(requestTimeout))
                .build();
        this.cacheSize = cacheSize;
        this.requestTimeout = requestTimeout;

        scheduler.scheduleAtFixedRate(this::clearCache, 1, 1, TimeUnit.HOURS);
    }

    public CompletableFuture<PokemonData> fetchEvolutionData(String pokemonId) {
        return CompletableFuture.supplyAsync(() -> {
            PokemonData cachedData = cache.get(pokemonId);
            if (cachedData != null && !isStale(cachedData)) {
                return cachedData;
            }
            try {
                return fetchDataFromSources(pokemonId).thenApply(data -> {
                    if (!cache.contains(pokemonId) || cache.size() >= cacheSize) {
                        cache.remove(cache.keySet().iterator().next());
                    }
                    cache.put(pokemonId, data);
                    return data;
                }).exceptionally(ex -> {
                    logger.warning("Failed to fetch evolution data for " + pokemonId + ": " + ex.getMessage());
                    return getDefaultData();
                });
            } catch (Exception e) {
                logger.severe("Error fetching evolution data: " + e.getMessage());
                return getDefaultData();
            }
        }, Executors.newFixedThreadPool(10));
    }

    private boolean isStale(PokemonData data) {
        // Implement logic to determine if cached data is stale
        return false;
    }

    private PokemonData fetchDataFromSources(String pokemonId) throws InterruptedException, ExecutionException {
        List<CompletableFuture<PokemonData>> futures = new ArrayList<>();
        String[] apis = {"https://api1.example.com/pokemon/", "https://api2.example.com/pokemon/"};

        for (String apiUrl : apis) {
            URI uri = URI.create(apiUrl + pokemonId);
            CompletableFuture<PokemonData> future = fetchData(uri)
                    .thenApply(response -> mergeData(response, classProvider.getClassDefinition(pokemonId)));
            futures.add(future);
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenCompose(v -> {
                    List<PokemonData> dataList = futures.stream()
                            .map(CompletableFuture::join)
                            .filter(Objects::nonNull)
                            .collect(Collectors.toList());
                    return CompletableFuture.completedFuture(mergeAllData(dataList));
                }).get();
    }

    private CompletableFuture<String> fetchData(URI uri) {
        HttpRequest request = HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(requestTimeout)).build();
        return httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body)
                .exceptionally(ex -> {
                    logger.warning("Network error: " + ex.getMessage());
                    return "{}";
                });
    }

    private PokemonData mergeData(String data, ClassDefinition classDef) {
        // Implement merging logic based on API responses and class definitions
        return new PokemonData(data, classDef);
    }

    private PokemonData mergeAllData(List<PokemonData> dataList) {
        // Implement logic to intelligently merge multiple data sources
        return dataList.stream().reduce(PokemonData::merge).orElseGet(this::getDefaultData);
    }

    private void clearCache() {
        if (cache.size() > cacheSize * 0.8) {
            int excess = cache.size() - (int)(cacheSize * 0.8);
            List<String> keysToRemove = new ArrayList<>(cache.keySet());
            for (int i = 0; i < excess; i++) {
                cache.remove(keysToRemove.get(i));
            }
        }
    }

    private PokemonData getDefaultData() {
        // Provide default data in case of errors
        return new PokemonData("Default data");
    }

    public void shutdown() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }

    // Dummy class definitions for illustration
    private static class PokemonData {
        private final String data;
        private final ClassDefinition classDef;

        public PokemonData(String data) { this(data, null); }
        public PokemonData(String data, ClassDefinition classDef) { this.data = data; this.classDef = classDef; }

        public boolean isComplete() { return true; } // Implement completeness check
        public static PokemonData merge(PokemonData a, PokemonData b) {
            // Merge two PokemonData instances
            return new PokemonData(a.data + "; " + b.data);
        }
    }

    private interface ClassProvider {
        ClassDefinition getClassDefinition(String pokemonId);
    }

    private static class ClassDefinition { /* Fields for class definition */ }

    public static void main(String[] args) {
        // Sample usage
        ClassProvider classProvider = new ClassProvider() {
            @Override
            public ClassDefinition getClassDefinition(String pokemonId) {
                return new ClassDefinition();
            }
        };

        EvolutionDataFetcher fetcher = new EvolutionDataFetcher(classProvider, 1000, 10);
        fetcher.fetchEvolutionData("pikachu").thenAccept(data -> System.out.println(data.data));
        Runtime.getRuntime().addShutdownHook(new Thread(fetcher::shutdown));
    }
}
