public class CloudStorageUploader {
    private static final Logger logger = Logger.getLogger(CloudStorageUploader.class.getName());
    private static final int DEFAULT_CHUNK_SIZE = 8192; // 8 KB

    public enum UploadStatus {
        SUCCESS,
        FILE_EXISTS,
        ERROR
    }

    public UploadStatus uploadFileToCloudStorage(String filePath, String bucketName, String directoryPath) {
        try {
            byte[] fileHash = calculateFileSha256(filePath);
            String existingHash = checkIfFileExists(bucketName, directoryPath, fileHash);

            if (existingHash != null && existingHash.equals(bytesToHex(fileHash))) {
                logger.info("File already exists in the cloud storage.");
                return UploadStatus.FILE_EXISTS;
            }

            // Simulated upload to cloud service
            boolean success = uploadToCloudService(filePath, bucketName, directoryPath);
            if (!success) {
                logger.log(Level.SEVERE, "Failed to upload file to cloud storage.");
                return UploadStatus.ERROR;
            }
            return UploadStatus.SUCCESS;

        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error during file upload process: ", e);
            return UploadStatus.ERROR;
        }
    }

    private byte[] calculateFileSha256(String pathOrUrl) throws IOException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        InputStream inputStream;

        if (pathOrUrl.startsWith("http")) {
            inputStream = downloadFileWithResume(pathOrUrl);
        } else {
            inputStream = new BufferedInputStream(new FileInputStream(pathOrUrl));
        }

        byte[] buffer = new byte[DEFAULT_CHUNK_SIZE];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            digest.update(buffer, 0, bytesRead);
        }
        return digest.digest();
    }

    private String checkIfFileExists(String bucketName, String directoryPath, byte[] fileHash) {
        // Simulated API call to check for existing files
        // Return the hash of the existing file or null if not found.
        return null;  // Replace with actual implementation
    }

    private boolean uploadToCloudService(String filePath, String bucketName, String directoryPath) throws IOException {
        // Simulated file upload process
        // Implement using cloud SDK like AWS S3, Google Cloud Storage, etc.
        return true;
    }

    private InputStream downloadFileWithResume(String urlString) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        int responseCode = connection.getResponseCode();

        if (responseCode == 206 || responseCode == 200) { // Partial content or OK
            return new BufferedInputStream(connection.getInputStream());
        }

        throw new IOException("Failed to download file: HTTP error code " + responseCode);
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        CloudStorageUploader uploader = new CloudStorageUploader();
        UploadStatus status = uploader.uploadFileToCloudStorage("path/to/local/file.txt", "myBucket", "/directory/");
        System.out.println("Upload Status: " + status);
    }
}
