import json
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime
import requests
import time
import random

# Set up secure logging
logging.basicConfig(filename='user_updates.log', level=logging.INFO, format='%(asctime)s %(message)s')
logger = logging.getLogger()

# Sample schema for validation (extendable)
SCHEMA = {
    "email": str,
    "phone_number": str,
    "address": dict,
    "date_of_birth": datetime,
    "employment_status": str
}

def validate_data(data):
    """Validate the user data against the SCHEMA."""
    if not all(key in data and isinstance(value, type_) for key, type_ in SCHEMA.items() for value, type_ in [(data[key], type_)]):
        raise ValueError("Invalid data format")

def make_request(url, method='GET', headers=None, data=None, retries=3):
    """Make a request to an API with retry logic and exponential backoff."""
    try:
        response = requests.request(method, url, headers=headers, json=data)
        if response.status_code == 429:  # Rate limit exceeded
            raise requests.exceptions.RequestException("Rate limit hit")

        response.raise_for_status()
        return response.json()

    except requests.exceptions.RequestException as e:
        if retries > 0:
            sleep_time = (2 ** (3 - retries)) + random.uniform(0, 1)  # Exponential backoff with jitter
            time.sleep(sleep_time)
            return make_request(url, method, headers, data, retries - 1)
        else:
            logger.error(f"Failed to update {url}: {str(e)}")
            raise

def update_service(service_info, user_data):
    """Update a single service with the user's information."""
    try:
        url = service_info['url']
        auth_token = service_info.get('auth_token')
        method = service_info.get('method', 'POST')

        headers = {'Authorization': f"Bearer {auth_token}"} if auth_token else {}

        response = make_request(url, method=method, headers=headers, data=user_data)
        logger.info(f"Successfully updated {url}: {response}")
        return True

    except Exception as e:
        logger.error(f"Error updating {service_info['name']}: {str(e)}")
        return False

def update_user_profile(user_data, services):
    """Update user profile across multiple services."""
    validate_data(user_data)

    results = []
    with ThreadPoolExecutor() as executor:
        future_to_service = {executor.submit(update_service, service, user_data): service for service in services}

        for future in as_completed(future_to_service):
            service = future_to_service[future]
            try:
                result = future.result()
                results.append((service['name'], result))
            except Exception as exc:
                logger.error(f"Service {service['name']} generated an exception: {exc}")

    return results

# Example usage
if __name__ == "__main__":
    user_data = {
        "email": "user@example.com",
        "phone_number": "+1234567890",
        "address": {"street": "123 Main St", "city": "Anytown"},
        "date_of_birth": datetime(1990, 1, 1),
        "employment_status": "Employed"
    }

    services = [
        {
            'name': 'ServiceA',
            'url': 'https://api.servicea.com/update',
            'auth_token': 'servicea_token'
        },
        {
            'name': 'ServiceB',
            'url': 'https://api.serviceb.com/update',
            # ServiceB might not require an auth token
        }
    ]

    results = update_user_profile(user_data, services)
    for service_name, success in results:
        if success:
            print(f"Successfully updated {service_name}")
        else:
            print(f"Failed to update {service_name}")
