import java.io.IOException;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class AsyncFileProcessor {
    private final Path directory;
    private final List<String> keywords;
    private final ExecutorService executor;
    private final ExternalReportingAPI reportingApi;

    public AsyncFileProcessor(Path directory, List<String> keywords) {
        this.directory = directory;
        this.keywords = keywords;
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.reportingApi = new ExternalReportingAPI();
    }

    public void processFiles() {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directory)) {
            List<CompletableFuture<Void>> futures = stream
                .filter(Files::isRegularFile)
                .map(file -> CompletableFuture.runAsync(() -> processFile(file), executor))
                .collect(Collectors.toList());

            CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
        } catch (IOException e) {
            System.err.println("Error accessing directory: " + e.getMessage());
        }
    }

    private void processFile(Path file) {
        try {
            List<String> lines = Files.readAllLines(file);
            String summary = generateSummary(lines);

            if (!summary.isEmpty()) {
                uploadReport(file.getFileName().toString(), summary);
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Error processing file " + file + ": " + e.getMessage());
        }
    }

    private String generateSummary(List<String> lines) {
        StringBuilder summary = new StringBuilder();
        Pattern pattern = Pattern.compile(Patterns.join("|", keywords));

        for (String line : lines) {
            if (pattern.matcher(line).find()) {
                summary.append(line).append("\n");
            }
        }

        return summary.toString().trim();
    }

    private void uploadReport(String fileName, String reportContent) {
        try {
            reportingApi.upload(fileName, reportContent);
            System.out.println("Report uploaded for file: " + fileName);
        } catch (ReportingAPIException e) {
            System.err.println("Failed to upload report for file " + fileName + ": " + e.getMessage());
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private static class ExternalReportingAPI {
        public void upload(String fileName, String content) throws ReportingAPIException {
            // Implement the API call to upload the report
            // Simulate successful upload
        }
    }

    private static class ReportingAPIException extends Exception {
        public ReportingAPIException(String message) {
            super(message);
        }
    }

    private static class Patterns {
        public static String join(String delimiter, List<String> elements) {
            return String.join(delimiter, elements.stream().map(Pattern::quote).toArray(String[]::new));
        }
    }

    public static void main(String[] args) {
        Path directory = Paths.get("path/to/directory");
        List<String> keywords = List.of("error", "warning");

        AsyncFileProcessor processor = new AsyncFileProcessor(directory, keywords);
        processor.processFiles();
        processor.shutdown();
    }
}
