    public async Task<string> FetchAndCacheXmlAsync(string url, int cacheDurationMinutes)
    {
        if (_cache.TryGetValue(url, out var cachedEntry) && DateTime.UtcNow < cachedEntry.Expiration)
        {
            return cachedEntry.Content;
        }

        try
        {
            string content = await _httpClient.GetStringAsync(url);
            _cache[url] = (content, DateTime.UtcNow.AddMinutes(cacheDurationMinutes));
            return content;
