        return fetchTask.ContinueWith(async task =>
        {
            if (task.Exception != null)
                throw task.Exception;

            var xmlContent = await task;

            // Fetch hash functions
            var hashes = parser.ParseXml<HashFunctionStruct>(xmlContent, hashXPath);
            // Fetch ciphers
            var ciphers = parser.ParseXml<CipherFunctionStruct>(xmlContent, cipherXPath);

            return hashes.Cast<CryptoFunction>().Concat(ciphers).ToList();
        }, TaskContinuationOptions.OnlyOnRanToCompletion).Result;
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}

