public class DynamicDeserializer {

    private static final int CACHE_SIZE = 100;
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final Map<String, Class<?>> classCache = Collections.synchronizedMap(
            new LinkedHashMap<String, Class<?>>() {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, Class<?>> eldest) {
                    return size() > CACHE_SIZE;
                }
            }
    );

    public Object deserialize(byte[] byteArray, String mainClassType) throws CustomDeserializationException {
