                if (clazz == null) {
                    clazz = fetchAndCacheClassDefinition(className);
                }

                Constructor<?> constructor = clazz.getDeclaredConstructor();
                Object instance = constructObject(byteArray, clazz, constructor);

                // Handle nested object deserialization
                return handleNestedObjects(instance, byteArray, clazz);

            } catch (ClassNotFoundException | IOException | ReflectiveOperationException e) {
                logError("Deserialization error: " + e.getMessage());
                throw new CustomDeserializationException(e);
            }
        }
