class CryptoManager {
public:
    CryptoManager() = default;

    bool initialize(const json& config) {
        // Parse configuration and initialize cryptographic algorithms
        for (const auto& [key, value] : config.items()) {
            if (key == "enable_aes256" && std::get<bool>(value)) {
                if (!initializeAES256()) return false;
            }
            else if (key == "enable_chacha20" && std::get<bool>(value)) {
                if (!initializeChaCha20()) return false;
            }
        }
        return true;
    }

private:
    bool initializeAES256() {
        // Initialize AES-256
        return EVP_aes_256_cbc() != nullptr;
    }

    bool initializeChaCha20() {
        // Initialize ChaCha20
        return CHACHA20_DEFAULT_VERSION == 1; // Example check
    }
};

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> parse_config(const std::string& filename) {
    std::ifstream file(filename);
    json config;
    if (file.is_open()) {
        file >> config;
    } else {
        log_error("Failed to open configuration file");
        return {};
    }
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> parsed_config;
    for (const auto& [key, value] : config.items()) {
        if (value.is_number_integer()) {
            parsed_config[key] = static_cast<int>(value.get<double>());
        } else if (value.is_number_float()) {
            parsed_config[key] = value.get<double>();
        } else if (value.is_string()) {
            parsed_config[key] = value.get<std::string>();
        } else if (value.is_boolean()) {
            parsed_config[key] = value.get<bool>();
        }
    }
    return parsed_config;
}

void process_data(const std::unordered_map<std::string, std::variant<int, double, std::string, bool>>& config) {
    // Simulate processing data using configuration
