}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        log_error("No configuration file provided");
        return 1;
    }

    const auto config = parse_config(argv[1]);
    CryptoManager crypto_manager;

    if (!crypto_manager.initialize(config)) {
