```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Polly;
using Polly.Retry;

class Program
{
    private static readonly HttpClient httpClient = new HttpClient();
    private static readonly IMemoryCache cache = new MemoryCache(new MemoryCacheOptions());
    private static readonly AsyncRetryPolicy retryPolicy = Policy.Handle<HttpRequestException>()
        .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

    static async Task Main(string[] args)
    {
        if (args.Length == 0 || args[0] == "--help")
        {
            ShowHelp();
            return;
        }

        try
        {
            string directoryPath = args[1];
            string siteName = args[2];
            string operation = args[3];

            await ManageWebsiteLifecycle(directoryPath, siteName, operation);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    private static void ShowHelp()
    {
        Console.WriteLine("Usage:");
        Console.WriteLine("  Program.exe <directory_path> <site_name> <operation>");
        Console.WriteLine("\nOperations:");
        Console.WriteLine("  add   - Add a new website.");
        Console.WriteLine("  remove - Remove an existing website.");
        Console.WriteLine("  start - Start the website.");
        Console.WriteLine("  stop  - Stop the website.");
        Console.WriteLine("  restart - Restart the website.");
    }

    private static async Task ManageWebsiteLifecycle(string directoryPath, string siteName, string operation)
    {
        if (!Directory.Exists(directoryPath))
        {
            Console.WriteLine("Error: Invalid directory path.");
            return;
        }

        ValidateSiteName(siteName);

        if (!await CheckWebConfigExists(directoryPath))
        {
            Console.WriteLine("Error: web.config file is missing.");
            return;
        }

        try
        {
            await retryPolicy.ExecuteAsync(async () =>
            {
                string apiEndpoint = $"https://api.example.com/websites/{operation}";
                var response = await httpClient.PostAsJsonAsync(apiEndpoint, new { SiteName = siteName });

                if (!response.IsSuccessStatusCode)
                {
                    Console.WriteLine($"API Error: {(int)response.StatusCode} - {response.ReasonPhrase}");
                }
                else
                {
                    string responseBody = await response.Content.ReadAsStringAsync();
                    Console.WriteLine("Operation successful: " + responseBody);
                }
            });
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unexpected error: {ex.Message}");
        }
    }

    private static async Task<bool> CheckWebConfigExists(string directoryPath)
    {
        string cacheKey = $"{directoryPath}_webconfig_exists";

        if (!cache.TryGetValue(cacheKey, out bool exists))
        {
            exists = File.Exists(Path.Combine(directoryPath, "web.config"));
            cache.Set(cacheKey, exists, TimeSpan.FromMinutes(10));
        }

        return exists;
    }

    private static void ValidateSiteName(string siteName)
    {
        var invalidChars = System.IO.Path.GetInvalidFileNameChars();
        if (siteName.IndexOfAny(invalidChars) >= 0)
        {
            throw new ArgumentException("Site name contains invalid characters.");
        }
    }
}
```

