import os
import concurrent.futures
from PIL import Image
from PIL.ExifTags import TAGS, GPSTAGS
import boto3
from botocore.exceptions import NoCredentialsError
import requests

class ImageProcessor:
    def __init__(self, directory_path, s3_bucket_name, slack_webhook_url):
        self.directory_path = directory_path
        self.s3_bucket_name = s3_bucket_name
        self.slack_webhook_url = slack_webhook_url
        self.supported_formats = ['JPEG', 'PNG']

    def extract_metadata(self, image_path):
        try:
            with Image.open(image_path) as img:
                exif_data = {
                    TAGS.get(tag): value 
                    for tag, value in img._getexif().items() if tag in TAGS
                } if hasattr(img, '_getexif') else {}

                gps_info = {GPSTAGS.get(t): v for t, v in exif_data.pop('GPSInfo').items()} if 'GPSInfo' in exif_data else {}

                return {
                    "format": img.format,
                    "mode": img.mode,
                    "size": img.size,
                    "exif": exif_data,
                    "gps_info": gps_info
                }
        except Exception as e:
            print(f"Error processing {image_path}: {e}")
            return None

    def filter_images(self, images_metadata, date_range=None, min_size=(0, 0), specific_fields=None):
        filtered_images = []

        for metadata in images_metadata:
            if 'DateTime' in metadata['exif'] and date_range:
                image_date = metadata['exif']['DateTime']
                # Implement actual date comparison logic here
                pass

            if metadata['size'][0] < min_size[0] or metadata['size'][1] < min_size[1]:
                continue

            if specific_fields:
                for field in specific_fields:
                    if field not in metadata['exif']:
                        break
                else:
                    filtered_images.append(metadata)

            else:
                filtered_images.append(metadata)

        return filtered_images

    def generate_report(self, images_metadata):
        report = "\n".join([f"Image: {metadata['format']}, Size: {metadata['size']}" for metadata in images_metadata])
        return report

    def upload_to_s3(self, report_content, report_name='report.txt'):
        s3_client = boto3.client('s3')
        try:
            s3_client.put_object(Bucket=self.s3_bucket_name, Key=report_name, Body=report_content)
            print("Report uploaded to S3")
        except NoCredentialsError as e:
            print(f"Failed to upload report: {e}")

    def notify_slack(self, message):
        try:
            response = requests.post(self.slack_webhook_url, json={"text": message})
            if response.status_code != 200:
                raise ValueError('Request to slack returned an error %s, the response is:\n%s' % (response.status_code, response.text))
        except Exception as e:
            print(f"Failed to send Slack notification: {e}")

    def process_directory(self, date_range=None, min_size=(0, 0), specific_fields=None):
        images_metadata = []

        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.extract_metadata, os.path.join(root, file))
                       for root, _, files in os.walk(self.directory_path)
                       for file in files
                       if Image.open(os.path.join(root, file)).format in self.supported_formats]

            for future in concurrent.futures.as_completed(futures):
                result = future.result()
                if result:
                    images_metadata.append(result)

        filtered_images = self.filter_images(images_metadata, date_range=date_range, min_size=min_size, specific_fields=specific_fields)

        report_content = self.generate_report(filtered_images)
        self.upload_to_s3(report_content)
        self.notify_slack("Image processing report is ready and uploaded to S3.")

# Example usage
processor = ImageProcessor(directory_path='/path/to/images', s3_bucket_name='your-s3-bucket-name', slack_webhook_url='https://hooks.slack.com/services/xxx')
processor.process_directory(date_range=('2022:01:01 00:00:00', '2022:12:31 23:59:59'), min_size=(1024, 768), specific_fields=['DateTime'])
