```csharp
using System;
using System.Collections.Concurrent;
using UnityEngine;

public enum DistributionType
{
    Uniform,
    Gaussian,
    Exponential
}

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, float> _floatCache = new();
    private readonly ConcurrentDictionary<string, int> _intCache = new();

    private string _currentDistribution = "Uniform";
    private (float min, float max) _range;

    // Simulating external configuration for demonstration purposes.
    private static readonly object ConfigLock = new();
    private static DistributionConfig _config;

    public DynamicValueGenerator(float min, float max)
    {
        SetRange(min, max);
        LoadConfiguration();
    }

    public void SetDistribution(DistributionType type, params object[] parameters)
    {
        lock (ConfigLock)
        {
            switch (type)
            {
                case DistributionType.Uniform:
                    _config = new DistributionConfig(type, "None");
                    break;
                case DistributionType.Gaussian:
                    if (parameters.Length != 2 || !(parameters[0] is float mean) || !(parameters[1] is float stdDev))
                        throw new ArgumentException("Gaussian requires a mean and standard deviation.");
                    _config = new DistributionConfig(type, $"Mean={mean}, StdDev={stdDev}");
                    break;
                case DistributionType.Exponential:
                    if (parameters.Length != 1 || !(parameters[0] is float lambda))
                        throw new ArgumentException("Exponential requires a rate parameter lambda.");
                    _config = new DistributionConfig(type, $"Lambda={lambda}");
                    break;
                default:
                    throw new ArgumentOutOfRangeException(nameof(type), "Invalid distribution type.");
            }
        }
    }

    public float GetRandomFloat()
    {
        string cacheKey = $"{_currentDistribution}_{_range.min}_{_range.max}";

        if (_floatCache.TryGetValue(cacheKey, out var cachedValue))
            return cachedValue;

        switch (_config.Type)
        {
            case DistributionType.Uniform:
                cachedValue = UnityEngine.Random.Range(_range.min, _range.max);
                break;
            case DistributionType.Gaussian:
                float mean = float.Parse(_config.Parameters.Split(',')[0].Split('=')[1]);
                float stdDev = float.Parse(_config.Parameters.Split(',')[1].Split('=')[1]);
                cachedValue = GaussianRandom(mean, stdDev);
                break;
            case DistributionType.Exponential:
                float lambda = float.Parse(_config.Parameters.Split('=')[1]);
                cachedValue = ExponentialRandom(lambda);
                break;
        }

        _floatCache[cacheKey] = cachedValue;
        return cachedValue;
    }

    public int GetRandomInteger()
    {
        string cacheKey = $"{_currentDistribution}_{_range.min}_Int_{_range.max}";

        if (_intCache.TryGetValue(cacheKey, out var cachedValue))
            return cachedValue;

        float floatValue = GetRandomFloat();
        cachedValue = Mathf.FloorToInt(floatValue);

        _intCache[cacheKey] = cachedValue;
        return cachedValue;
    }

    public override string ToString()
    {
        return $"Range: {_range.min} to {_range.max}, Distribution: {_currentDistribution}, Parameters: {_config.Parameters}";
    }

    private void SetRange(float min, float max)
    {
        if (min >= max) throw new ArgumentOutOfRangeException("Invalid range provided.");
        _range = (_range = (_range.min, _range.max));
    }

    private float GaussianRandom(float mean, float stdDev)
    {
        return Mathf.Sqrt(-2.0f * Mathf.Log(1.0f - UnityEngine.Random.value)) *
               Mathf.Sin(2.0f * Mathf.PI * UnityEngine.Random.value) * stdDev + mean;
    }

    private float ExponentialRandom(float lambda)
    {
        return -Mathf.Log(1.0f - UnityEngine.Random.value) / lambda;
    }

    private void LoadConfiguration()
    {
        lock (ConfigLock)
        {
            _config = new DistributionConfig(DistributionType.Uniform, "None");
        }
    }
}

public class DistributionConfig
{
    public DistributionType Type { get; }
    public string Parameters { get; }

    public DistributionConfig(DistributionType type, string parameters)
    {
        Type = type;
        Parameters = parameters;
    }
}
