        self.services_config = {}

    def register_service(self, service_name: str, required_fields: list[str], 
                         optional_fields: list[str] = None, validation_fn: Callable[[Dict[str, Any]], bool] = None):
        with self.lock:
            self.services_config[service_name] = {
                "required": set(required_fields),
                "optional": set(optional_fields) if optional_fields else set(),
                "validate": validation_fn
            }

    def handle_response(self, service_name: str, response_json: str):
        try:
            response_data = json.loads(response_json)
            self._process_response(service_name, response_data)
        except json.JSONDecodeError as e:
            logging.error(f"Failed to parse JSON for {service_name}: {e}")

    def _process_response(self, service_name: str, response_data: Dict[str, Any]):
        with self.lock:
            config = self.services_config.get(service_name)
            if not config:
                logging.warning(f"No configuration found for service {service_name}")
                return

            required_fields = config["required"]
            optional_fields = config["optional"]

            # Validate presence of required fields
            missing_fields = [field for field in required_fields if field not in response_data]
            if missing_fields:
                logging.error(f"Missing fields for {service_name}: {missing_fields}")
                return

            # Validate additional criteria using custom validation function, if provided
            if config["validate"] and not config["validate"](response_data):
                logging.error(f"Validation failed for {service_name} with response: {response_data}")
                return

            unified_profile = {
                "access_token": response_data.get("access_token"),
                "user_id": response_data.get("user_id")
            }

            # Handle optional fields
            for field in optional_fields:
                if field in response_data:
                    unified_profile[field] = response_data[field]

            logging.info(f"Unified user profile from {service_name}: {unified_profile}")

    def retry_with_exponential_backoff(self, service_call: Callable[[], str], max_retries: int = 5):
        base_delay = 1
        for attempt in range(max_retries):
            try:
                response_json = service_call()
                return response_json
            except Exception as e:
                logging.error(f"Attempt {attempt + 1} failed with error: {e}")
                delay = base_delay * (2 ** attempt)
                time.sleep(delay)

        raise Exception("Max retries exceeded")

    def process_concurrent_requests(self, service_calls: Dict[str, Callable[[], str]], 
                                    service_names: list[str]):
        threads = []
        for service_name, call in zip(service_names, service_calls.values()):
            thread = threading.Thread(target=self._handle_service_request, args=(service_name, call))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

    def _handle_service_request(self, service_name: str, service_call: Callable[[], str]):
        try:
            response_json = self.retry_with_exponential_backoff(service_call)
            self.handle_response(service_name, response_json)
        except Exception as e:
            logging.error(f"Failed to process request for {service_name}: {e}")

# Example usage
