#include <sys/wait.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Function to log messages
void logMessage(const char* message) {
    printf("[LOG] %s\n", message);
}

// Helper function to execute a single command and manage its lifecycle
int executeCommand(const char* command, int timeout, int retries) {
    for (int attempt = 0; attempt < retries; ++attempt) {
        pid_t pid = fork();
        if (pid == -1) {
            logMessage("Fork failed");
            return 0;
        } else if (pid > 0) { // Parent process
            int status;
            struct timespec start, now;
            clock_gettime(CLOCK_MONOTONIC, &start);

            do {
                clock_gettime(CLOCK_MONOTONIC, &now);
                double elapsed = (double)(now.tv_sec - start.tv_sec) + (double)(now.tv_nsec - start.tv_nsec) / 1e9;

                if (waitpid(pid, &status, WNOHANG) > 0 || elapsed >= timeout) {
                    break;
                }
                usleep(100000); // Sleep for 100ms
            } while (WIFSTOPPED(status));

            if (WIFEXITED(status) || WIFSIGNALED(status)) {
                logMessage("Command execution failed or timed out");
                return 0;
            }

            logMessage("Command started successfully in background");
            return 1;

        } else { // Child process
            execlp("/bin/sh", "sh", "-c", command, (char*)NULL);
            perror("execlp");
            exit(EXIT_FAILURE); // Exit if exec fails
        }
    }
    logMessage("All retries failed");
    return 0;
}

int runCommandBackground(const char* command, int timeout, int retries) {
    if (!command || timeout <= 0 || retries <= 0) {
        logMessage("Invalid input parameters");
        return 0;
    }

    // Sanitize the command to prevent injection attacks
    const char *safe_command = strdup(command);
    if (safe_command == NULL) {
        perror("strdup failed");
        return 0;
    }

    int result = executeCommand(safe_command, timeout, retries);

    free((void*)safe_command); // Free allocated memory for command

    return result;
}

// Unit test function
void testRunCommandBackground() {
    const char* test_command = "sleep 2";
    int timeout = 5; // seconds
    int retries = 3;

    printf("Test runCommandBackground: ");
    if (runCommandBackground(test_command, timeout, retries)) {
        printf("PASSED\n");
    } else {
        printf("FAILED\n");
    }
}

int main() {
    testRunCommandBackground();
    return 0;
}
