// Simulate external service for fetching numbers
class ExternalService {
    constructor() {}

    async fetchNumber(index) {
        // Simulating network latency with random delay
        await new Promise(resolve => setTimeout(resolve, Math.random() * 1000));

        // Simulated rate limiting and errors
        if (Math.random() < 0.1) throw new Error('Network error');
        return index; // In a real scenario, this would be fetched from an API or DB
    }
}

// Worker pool for concurrent processing
class WorkerPool {
    constructor(size) {
        this.size = size;
        this.workers = [];
    }

    async process(chunks, workerFunction) {
        let results = new Array(chunks.length);
        let activeWorkers = 0;

        const enqueueWorker = async (i) => {
            try {
                const result = await workerFunction(chunks[i]);
                results[i] = result;
            } catch (err) {
                throw err; // Handle error appropriately
            } finally {
                activeWorkers--;
                if (activeWorkers < this.size && i + 1 < chunks.length) {
                    enqueueWorker(i + 1);
                }
            }
        };

        for (let i = 0; i < Math.min(this.size, chunks.length); i++) {
            enqueueWorker(i);
            activeWorkers++;
        }

        return new Promise((resolve, reject) => {
            const interval = setInterval(() => {
                if (activeWorkers === 0 && results.every(r => r !== undefined)) {
                    clearInterval(interval);
                    resolve(results);
                }
            }, 100); // Check every 100ms
        });
    }
}

// Helper function to split array into chunks
function chunkArray(array, size) {
    const chunks = [];
    for (let i = 0; i < array.length; i += size) {
        chunks.push(array.slice(i, i + size));
    }
    return chunks;
}

// Main async reduce function
async function robustAsyncReduce(numbers, initialValue, callback, chunkSize = 10, timeout = 5000) {
    const externalService = new ExternalService();
    const workerPool = new WorkerPool(4); // Number of concurrent workers

    if (!Array.isArray(numbers)) throw new Error('Input must be an array');
    if (typeof callback !== 'function') throw new Error('Callback must be a function');

    async function processChunk(chunk, accumulatedValue) {
        for (const index of chunk) {
            let retries = 3;
            while (retries > 0) {
                try {
                    const number = await Promise.race([
                        externalService.fetchNumber(index),
                        new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), timeout))
                    ]);
                    accumulatedValue = callback(accumulatedValue, number);
                    break; // Exit retry loop on success
                } catch (error) {
                    if (retries === 1 || error.message !== 'Network error') throw error;
                    retries--;
                    await new Promise(resolve => setTimeout(resolve, Math.pow(2, 3 - retries) * 100)); // Exponential backoff
                }
            }
        }
        return accumulatedValue;
    }

    const chunks = chunkArray(numbers, chunkSize);

    try {
        console.log(`Starting reduction with ${numbers.length} numbers...`);

        let results = await workerPool.process(chunks, async (chunk) => processChunk(chunk, initialValue));

        // Final reduce step to combine all partial results
        return results.reduce((acc, val) => callback(acc, val));
    } catch (error) {
        console.error('Error during reduction:', error.message);
        throw new Error('Reduction failed');
    }
}

// Usage Example:
(async () => {
    try {
        const numbers = Array.from({ length: 100 }, (_, i) => i + 1); // Sample array
        const initialValue = 0;

        const sumReducer = (acc, val) => acc + val;

        const result = await robustAsyncReduce(numbers, initialValue, sumReducer);
        console.log(`Final Result: ${result}`);
    } catch (error) {
        console.error('An error occurred:', error.message);
    }
})();
