#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_PATH 1024
#define LOG_FILE "conversion.log"

typedef struct {
    char **files;
    int fileCount;
    const char *outputDir;
    size_t maxPagesPerPdf;
} ThreadData;

void logMessage(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int isJPEGFile(const char *filename) {
    return strstr(filename, ".jpg") != NULL || strstr(filename, ".jpeg") != NULL;
}

void* convertFiles(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    int startIndex = 0; // For simplicity, each thread processes from the start
    char command[MAX_PATH];

    while (startIndex + data->maxPagesPerPdf <= data->fileCount) {
        snprintf(command, sizeof(command), "convert %s -density 300 ", data->outputDir);

        for (int i = startIndex; i < startIndex + data->maxPagesPerPdf && i < data->fileCount; ++i) {
            strcat(command, data->files[i]);
            if (i < startIndex + data->maxPagesPerPdf - 1) {
                strcat(command, " ");
            }
        }

        char outputFilename[MAX_PATH];
        snprintf(outputFilename, sizeof(outputFilename), "%s/page_%d.pdf", data->outputDir, startIndex / data->maxPagesPerPdf);
        strcat(command, outputFilename);

        int result = system(command);
        if (result != 0) {
            logMessage("Error converting files");
            return (void *)(intptr_t)result;
        }

        startIndex += data->maxPagesPerPdf;
    }

    return NULL;
}

int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf) {
    DIR *dir = opendir(inputDir);
    if (!dir) {
        logMessage("Failed to open directory");
        return 1;
    }

    struct dirent *entry;
    int jpegCount = 0;
    char **jpegFiles = NULL;

    while ((entry = readdir(dir)) != NULL) {
        if (isJPEGFile(entry->d_name)) {
            jpegCount++;
            jpegFiles = realloc(jpegFiles, jpegCount * sizeof(char *));
            snprintf(jpegFiles[jpegCount - 1], MAX_PATH, "%s/%s", inputDir, entry->d_name);
        }
    }

    closedir(dir);

    if (jpegCount == 0) {
        logMessage("No JPEG files found");
        return 2;
    }

    ThreadData *data = malloc(sizeof(ThreadData));
    data->files = jpegFiles;
    data->fileCount = jpegCount;
    data->outputDir = outputDir;
    data->maxPagesPerPdf = maxPagesPerPdf;

    pthread_t threads[4]; // Assuming a maximum of 4 threads for simplicity
    int threadCount = 0;

    for (int i = 0; i < jpegCount; i += maxPagesPerPdf) {
        if (threadCount >= 4) break;

        ThreadData *dataCopy = malloc(sizeof(ThreadData));
        memcpy(dataCopy, data, sizeof(ThreadData));

        int result = pthread_create(&threads[threadCount], NULL, convertFiles, dataCopy);
        if (result != 0) {
            logMessage("Failed to create thread");
            free(dataCopy);
            return 3;
        }

        ++threadCount;
    }

    for (int i = 0; i < threadCount; ++i) {
        void *status;
        pthread_join(threads[i], &status);
        if (status != NULL && (intptr_t)status != 0) {
            free(data);
            return (intptr_t)status;
        }
    }

    free(data->files);
    free(data);

    logMessage("Conversion completed successfully");
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("Usage: %s <inputDir> <outputDir> <maxPagesPerPdf>\n", argv[0]);
        return 1;
    }

    const char *inputDir = argv[1];
    const char *outputDir = argv[2];
    size_t maxPagesPerPdf = (size_t)atoi(argv[3]);

    int result = batchConvertJpegToPdf(inputDir, outputDir, maxPagesPerPdf);
    return result;
}
```

