public class WebServerManager
{
    private static readonly object _lockObject = new object();

    public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName, Dictionary<string, string> configurationSettings)
    {
        lock (_lockObject) // Ensuring thread safety for the operation
        {
            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                LogError($"Missing web.config in {directoryPath}");
                return "Error: Missing web.config file.";
            }
        }

        try
        {
            await AddWebsiteAsync(directoryPath, siteName, configurationSettings);
            await StartWebsiteAsync(siteName);

            // Example usage of MD5 calculation for a local file or URL
            string filePath = Path.Combine(directoryPath, "example.txt");
            string remoteUrl = "http://example.com/file.txt";

            string localFileHash = CalculateMD5(filePath);
            string remoteFileHash = await CalculateFileMd5Async(remoteUrl);

            LogInfo($"Local File MD5: {localFileHash}");
            LogInfo($"Remote File MD5: {remoteFileHash}");

            return "Website added and started successfully.";
        }
        catch (Exception ex)
        {
            LogError($"An error occurred while adding or starting the website: {ex.Message}");
            return $"Error: {ex.Message}";
        }
    }

    private async Task AddWebsiteAsync(string directoryPath, string siteName, Dictionary<string, string> configurationSettings)
    {
        // Placeholder for API interaction to add a new website
        await Task.Delay(100); // Simulate network call

        LogInfo($"Added website '{siteName}' at {directoryPath} with settings: {string.Join(", ", configurationSettings)}");
    }

    private async Task StartWebsiteAsync(string siteName)
    {
        // Placeholder for API interaction to start a website
        await Task.Delay(100); // Simulate network call

        LogInfo($"Started website '{siteName}'.");
    }

    public string CalculateMD5(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hashBytes = md5.ComputeHash(stream);
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }
        }
    }

    public async Task<string> CalculateFileMd5Async(string fileUrl)
    {
        var httpClient = new HttpClient();
        using (var responseStream = await httpClient.GetAsync(fileUrl, HttpCompletionOption.ResponseHeadersRead))
        {
            responseStream.EnsureSuccessStatusCode();

            using (var md5 = MD5.Create())
            {
                using (var stream = await responseStream.Content.ReadAsStreamAsync())
                {
                    var hashBytes = md5.ComputeHash(stream);
                    return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                }
            }
        }
    }

    private void LogError(string message)
    {
        // Implementation for logging errors
        Console.Error.WriteLine(message);
    }

    private void LogInfo(string message)
    {
        // Implementation for logging information
        Console.WriteLine(message);
    }
}
