// Install necessary packages: express, ws, redis, axios, winston
const WebSocket = require('ws');
const http = require('http');
const express = require('express');
const { createClient } = require('redis');
const axios = require('axios');
const winston = require('winston');

// Configuration for Redis and WebSockets
const REDIS_URL = 'redis://localhost:6379';
const WEBSOCKET_PORT = 8080;
const API_GATEWAY_URL = 'http://api-gateway.example.com';

// Create a WebSocket server and an HTTP server to handle REST API requests
const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Redis client for data storage
const redisClient = createClient({ url: REDIS_URL });
redisClient.on('error', (err) => winston.error(`Redis error: ${err}`));
await redisClient.connect();

// Logger setup using Winston
winston.configure({
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'sensor-data.log' })
  ]
});

// WebSocket connection handling
wss.on('connection', async (ws) => {
  try {
    let lastSequenceId = null;

    ws.on('message', async (data) => {
      const message = JSON.parse(data);
      const { deviceId, sequenceId, sensorData } = message;

      // Check for missed data
      if (lastSequenceId !== null && sequenceId <= lastSequenceId + 1) {
        winston.warn(`Duplicate or out-of-order message from device ${deviceId}`);
        return;
      }

      // Store sensor data in Redis
      const key = `sensorData:${deviceId}:${sequenceId}`;
      await redisClient.set(key, JSON.stringify(sensorData));

      // Update the last sequence ID to track ordered messages
      lastSequenceId = sequenceId;

      winston.info(`Received and stored data from device ${deviceId} with sequence ID ${sequenceId}`);
    });

    ws.on('close', async () => {
      winston.warn(`Connection closed for device: ${ws.deviceId}`);
    });
  } catch (error) {
    winston.error(`Error in WebSocket connection: ${error}`);
    if (ws) ws.close();
  }
});

// Exponential backoff strategy
async function retryWithBackoff(fn, retries = 5, delay = 1000) {
  let attempt = 0;
  while (attempt < retries) {
    try {
      return await fn();
    } catch (error) {
      winston.error(`Error: ${error}, Retrying in ${delay}ms...`);
      await new Promise((resolve) => setTimeout(resolve, delay));
      delay *= 2;
      attempt++;
    }
  }
  throw new Error('Max retries reached');
}

// RESTful API endpoint for retrieving sensor data
app.get('/sensor-data', async (req, res) => {
  const { deviceId, startSequenceId = 0, endSequenceId, limit = 100 } = req.query;

  try {
    // Fetch sensor data from Redis within a range of sequence IDs
    const keysPattern = `sensorData:${deviceId}:*`;
    const keys = await redisClient.keys(keysPattern);
    const filteredKeys = keys.filter((key) => {
      const seqId = parseInt(key.split(':')[2], 10);
      return seqId >= parseInt(startSequenceId, 10) && (!endSequenceId || seqId <= endSequenceId);
    }).slice(0, limit);

    const sensorDataPromises = filteredKeys.map(async (key) => {
      const data = await redisClient.get(key);
      return { key, data: JSON.parse(data) };
    });

    const results = await Promise.all(sensorDataPromises);

    res.json(results);
  } catch (error) {
    winston.error(`Error retrieving sensor data: ${error}`);
    res.status(500).send('Internal Server Error');
  }
});

// Handle graceful shutdowns and connection issues
process.on('SIGINT', async () => {
  winston.info('Shutting down server...');
  await redisClient.quit();
  server.close(() => winston.info('Server closed'));
});

server.listen(WEBSOCKET_PORT, () => {
  winston.info(`WebSocket server is listening on port ${WEBSOCKET_PORT}`);
});

// Unit and integration tests (example using Mocha/Chai)
describe('Sensor Data Module', function() {
  it('should store sensor data in Redis', async function() {
    const testData = { deviceId: 'device1', sequenceId: 1, sensorData: { temperature: 22.5 } };
    await redisClient.set(`sensorData:${testData.deviceId}:${testData.sequenceId}`, JSON.stringify(testData.sensorData));

    const storedData = await redisClient.get(`sensorData:${testData.deviceId}:${testData.sequenceId}`);
    chai.expect(storedData).to.equal(JSON.stringify(testData.sensorData));
  });

  // Additional tests for WebSocket connections, error handling, etc.
});

// Stress testing can be conducted using tools like Apache JMeter or k6
```

