Below is an outline of a scalable C# middleware component designed to update specific HTML elements dynamically via HTTP POST requests:

```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class ContentUpdateMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ContentUpdateMiddleware> _logger;
    private readonly IConfiguration _configuration;
    private readonly ConcurrentDictionary<string, ICmsProvider> _cmsProviders = new();

    public ContentUpdateMiddleware(RequestDelegate next, ILogger<ContentUpdateMiddleware> logger, IConfiguration configuration)
    {
        _next = next ?? throw new ArgumentNullException(nameof(next));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _configuration = configuration ?? throw new ArgumentNullException(nameof(configuration));
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method != HttpMethods.Post || !context.Request.Path.StartsWithSegments("/update-content", StringComparison.OrdinalIgnoreCase))
            return;

        var requestPayload = await JsonSerializer.DeserializeAsync<ContentUpdateRequest>(await new StreamReader(context.Request.Body).ReadToEndAsync());

        if (requestPayload == null || string.IsNullOrEmpty(requestPayload.ElementId) || string.IsNullOrEmpty(requestPayload.Content))
        {
            context.Response.StatusCode = StatusCodes.Status400BadRequest;
            await context.Response.WriteAsync("Invalid request payload.");
            return;
        }

        try
        {
            var cmsProvider = _cmsProviders.GetOrAdd(
                requestPayload.CmsType,
                type => CreateCmsProvider(type, _configuration));

            string updatedContent = await UpdateElementContent(cmsProvider, requestPayload.ElementId, requestPayload.Content);

            context.Response.StatusCode = StatusCodes.Status200OK;
            await context.Response.WriteAsync(updatedContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update content.");
            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            await context.Response.WriteAsync("Internal server error. Please try again later.");
        }
    }

    private ICmsProvider CreateCmsProvider(string cmsType, IConfiguration configuration)
    {
        switch (cmsType.ToLower())
        {
            case "wordpress":
                return new WordPressCmsProvider(configuration.GetSection(cmsType));
            case "drupal":
                return new DrupalCmsProvider(configuration.GetSection(cmsType));
            // Add other CMS providers as needed.
            default:
                throw new NotSupportedException($"CMS provider {cmsType} is not supported.");
        }
    }

    private async Task<string> UpdateElementContent(ICmsProvider cmsProvider, string elementId, string content)
    {
        return await cmsProvider.UpdateElementAsync(elementId, content);
    }
}

public interface ICmsProvider
{
    Task<string> UpdateElementAsync(string elementId, string content);
}

