    } else if (strcmp(cache_type, "memcached") == 0) {
        // Initialize Memcached
        printf("Initializing Memcached...\n");
    } else {
        log_error("Unsupported or missing CACHE_TYPE.");
    }
}

// Function to log errors with timestamps and stack traces
