using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.XPath;

public class XmlAndBinaryParser
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, string> _cache;
    private readonly TimeSpan _cacheDuration;
    private readonly long _maxCacheSize;
    private readonly object _lockObject = new();

    public XmlAndBinaryParser(TimeSpan cacheDuration, long maxCacheSize)
    {
        _httpClient = new HttpClient();
        _cache = new ConcurrentDictionary<string, string>();
        _cacheDuration = cacheDuration;
        _maxCacheSize = maxCacheSize;
    }

    public async Task<XmlNode> GetFirstMatchingElement(string xmlUrl, string xPathExpression)
    {
        try
        {
            var cachedXml = TryGetFromCache(xmlUrl);

            if (cachedXml != null)
            {
                using var reader = new StringReader(cachedXml);
                return ParseXmlAndFindFirstMatch(reader, xPathExpression);
            }

            var xmlContent = await FetchAndCacheXmlAsync(xmlUrl);

            using var reader = new StringReader(xmlContent);
            return ParseXmlAndFindFirstMatch(reader, xPathExpression);
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Error: {ex.Message}");
            throw;
        }
    }

    private string TryGetFromCache(string key)
    {
        if (_cache.TryGetValue(key, out var cachedXml))
        {
            return cachedXml; // In a real scenario, check cache expiration here.
        }

        return null;
    }

    private async Task<string> FetchAndCacheXmlAsync(string url)
    {
        var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();

        UpdateCache(url, content);

        return content;
    }

    private void UpdateCache(string key, string value)
    {
        lock (_lockObject)
        {
            if (GetCurrentCacheSize() + value.Length > _maxCacheSize)
            {
                RemoveOldestFromCache(); // Implement a method to remove the oldest cache item
            }

            _cache[key] = value;
            // Set expiration for the cached item based on _cacheDuration.
        }
    }

    private long GetCurrentCacheSize()
    {
        return _cache.Values.Sum(item => item.Length);
    }

    private void RemoveOldestFromCache()
    {
        var oldestKey = _cache.Keys.OrderBy(k => DateTime.UtcNow - GetLastAccessTime(k)).FirstOrDefault();
        if (oldestKey != null)
        {
            _cache.TryRemove(oldestKey, out _);
        }
    }

    private DateTime? GetLastAccessTime(string key)
    {
        // Implement retrieval of the last access time for cache items.
        return DateTime.UtcNow;
    }

    private XmlNode ParseXmlAndFindFirstMatch(StringReader reader, string xPathExpression)
    {
        using var xmlReader = XmlReader.Create(reader);
        var document = new XmlDocument();
        document.Load(xmlReader);

        var nsmgr = new XmlNamespaceManager(document.NameTable);
        return document.SelectSingleNode(xPathExpression, nsmgr) as XmlNode;
    }

    public void InsertAfterFirstOccurrence(IList<string> list, string firstString, string secondString)
    {
        try
        {
            int index = list.IndexOf(firstString);
            if (index != -1)
            {
                list.Insert(index + 1, secondString);
            }
            else
            {
                list.Add(secondString);
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Error: {ex.Message}");
            throw;
        }
    }

    // Additional methods for binary file loading and integration would be implemented here.
}
