Below is an implementation of the described function in Rust. This code uses the `reqwest` crate for HTTP requests, `tokio` for asynchronous runtime, and `log` for logging errors. It assumes that you have an external authentication service capable of providing tokens.

```rust
use reqwest::header::{HeaderMap, HeaderValue};
use reqwest::{Client, RequestBuilder, StatusCode, Url};
use std::collections::HashMap;
use std::time::Duration;
use tokio::time::sleep;
use log::{error, info};

#[derive(Debug)]
pub struct HttpClientConfig {
    pub disable_certificate_validation: bool,
    pub retries: usize,
    pub retry_interval: Duration,
    pub timeout: Duration,
    pub custom_headers: HashMap<String, String>,
}

#[derive(Debug)]
pub enum HttpClientError {
    InvalidUrl,
    NetworkError(reqwest::Error),
    Unauthorized(String), // Could be replaced with a more detailed error
    Other(String),
}

struct AuthClient; // Stub for an authentication client

impl AuthClient {
    async fn get_token(&self) -> Result<String, HttpClientError> {
        // Simulate fetching a token from an external service
        Ok("new_token".to_string())
    }
}

async fn fetch_with_retries(
    url: &Url,
    config: &HttpClientConfig,
    auth_client: &AuthClient,
    headers: HeaderMap,
) -> Result<reqwest::Response, HttpClientError> {
    let client = Client::builder()
        .danger_accept_invalid_certs(config.disable_certificate_validation)
        .build()?;

    for attempt in 0..=config.retries {
        match client
            .get(url.clone())
            .timeout(config.timeout)
            .headers(headers.clone())
            .send()
            .await
        {
            Ok(response) => {
                if response.status() == StatusCode::UNAUTHORIZED {
                    let token = auth_client.get_token().await?;
                    headers.insert("Authorization", HeaderValue::from_str(&format!("Bearer {}", token)).unwrap());
                    continue;
                }
                return Ok(response);
            }
            Err(err) => {
                if attempt == config.retries {
                    return Err(HttpClientError::NetworkError(err));
                }
                sleep(config.retry_interval).await;
            }
        }
    }

    Err(HttpClientError::Other("Failed to fetch after retries".into()))
}

pub async fn create_http_client(
    url: &str,
    config: HttpClientConfig,
) -> Result<RequestBuilder, HttpClientError> {
    let auth_client = AuthClient {};

    let parsed_url = Url::parse(url).map_err(|_| HttpClientError::InvalidUrl)?;

    let mut headers = HeaderMap::new();
    for (key, value) in &config.custom_headers {
        headers.insert(key.clone(), HeaderValue::from_str(value).unwrap());
    }

    match fetch_with_retries(&parsed_url, &config, &auth_client, headers).await {
        Ok(response) => {
            info!("Request successful: {:?}", response.status());
            Ok(Client::new().get(url))
        }
        Err(e) => {
            error!("Request failed: {:?}", e);
            Err(e)
        }
    }
}

#[tokio::main]
async fn main() {
    let config = HttpClientConfig {
        disable_certificate_validation: false,
        retries: 3,
        retry_interval: Duration::from_secs(2),
        timeout: Duration::from_secs(10),
        custom_headers: HashMap::new(),
    };

    match create_http_client("https://example.com", config).await {
        Ok(request_builder) => {
            if let Ok(response) = request_builder.send().await {
                println!("Response status: {}", response.status());
            }
        }
        Err(err) => eprintln!("Failed to create client: {:?}", err),
    }
}
```

This implementation includes:

- A configuration struct for setting up the HTTP client.
