```javascript
/**
 * Function to run tests on a given module using Blueslip for mocking.
 * 
 * @param {string} moduleName - The name of the module being tested.
 * @param {Array<Function>} testCases - An array of functions, each representing a test case.
 * @param {Function} [setUpFunction] - Optional setup function to initialize resources before tests.
 */
function runTests(moduleName, testCases, setUpFunction = () => {}) {
    try {
        // Load the module
        const moduleToTest = require(moduleName);

        console.log(`Starting tests for module: ${moduleName}`);

        // Setup initial resources if a setup function is provided
        setUpFunction();

        testCases.forEach((testCase, index) => {
            console.log(`Running test case #${index + 1}: ${testCase.name || 'Unnamed Test'}`);

            try {
                // Reset Blueslip before each test
                blueslip.reset();

                // Execute the test case function
                testCase(moduleToTest);

                console.log(`Test case #${index + 1} passed: ${testCase.name || 'Unnamed Test'}`);
            } catch (error) {
                console.error(`Error in test case #${index + 1}: ${testCase.name || 'Unnamed Test'}`, error);
            } finally {
                // Ensure Blueslip is reset after each test
                blueslip.reset();

                // Additional cleanup can be done here if necessary
            }
        });

    } catch (error) {
        console.error(`Failed to run tests for module: ${moduleName}`, error);
    }
}

