        bool enableSHA256 = config.find("SHA-256") != std::string::npos;
        bool enableSHA384 = config.find("SHA-384") != std::string::npos;
        bool enableSHA512 = config.find("SHA-512") != std::string::npos;

        // Initialize encryption algorithms
        if (enableAES256 && !initializeAlgorithm(AES256, "AES-256")) {
            logError(logfile, "Failed to initialize AES-256");
            return false;
        }

        if (enableChaCha20 && !initializeAlgorithm(CHACHA20, "ChaCha20")) {
            logError(logfile, "Failed to initialize ChaCha20");
            return false;
        }

        // Initialize hashing algorithms
        if (enableSHA256 && !initializeAlgorithm(SHA256, "SHA-256")) {
            logError(logfile, "Failed to initialize SHA-256");
            return false;
        }

        if (enableSHA384 && !initializeAlgorithm(SHA384, "SHA-384")) {
            logError(logfile, "Failed to initialize SHA-384");
            return false;
        }

        if (enableSHA512 && !initializeAlgorithm(SHA512, "SHA-512")) {
            logError(logfile, "Failed to initialize SHA-512");
            return false;
        }

        logfile.close();
        return true;
    }

private:
    enum Algorithms {
        AES256,
        CHACHA20,
        SHA256,
        SHA384,
        SHA512
    };

    bool initializeAlgorithm(Algorithms algo, const std::string& name) {
        switch (algo) {
            case AES256: 
                return EVP_aes_256_cbc() != nullptr;
            case CHACHA20:
                return EVP_chacha20() != nullptr;
            case SHA256:
                return EVP_sha256() != nullptr;
            case SHA384:
                return EVP_sha384() != nullptr;
            case SHA512:
                return EVP_sha512() != nullptr;
            default:
                return false;
        }
    }

    void logError(std::ofstream& logfile, const std::string& message) {
        logfile << "ERROR: " << message << std::endl;
    }

public:
    template<typename T>
    static std::unique_ptr<uint8_t[]> inlineCopy(const std::vector<std::unique_ptr<T[]>>& chunks,
                                                 size_t totalSize, size_t offset = 0) {
        std::unique_ptr<uint8_t[]> result(new uint8_t[totalSize]);

        size_t copiedBytes = 0;
        for (const auto& chunk : chunks) {
            if (copiedBytes + sizeof(T) <= offset)
                continue;

            const T* data = chunk.get();
            size_t bytesToCopy = sizeof(T);

            if (offset < copiedBytes + sizeof(T)) {
                bytesToCopy = std::min(bytesToCopy, totalSize - (copiedBytes - offset));
                bytesToCopy = std::min(bytesToCopy, static_cast<size_t>(sizeof(T) - (offset - copiedBytes)));
            }

            if (bytesToCopy > 0)
                memcpy(result.get() + (copiedBytes - offset), data, bytesToCopy);

            copiedBytes += sizeof(T);
        }

        return result;
    }
};
```

This code provides a structure for initializing a secure messaging library with support for specified encryption and hashing algorithms using OpenSSL. It also includes an inlining feature to copy chunks of data without modifying the originals, leveraging `std::vector` and `std::unique_ptr`.

