async function fetchWeatherData(location) {
  try {
    const openWeatherResponse = await axios.get(`http://api.openweathermap.org/data/2.5/weather?q=${location}&appid=YOUR_API_KEY`);
    const climateApiResponse = await axios.get(`https://climate.api.com/location/${location}/data`, { params: { apiKey: 'YOUR_API_KEY' } });

