import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;

public class CommandExecutor {

    private static final String ERROR_LOG_FILE = "error.log";

    public static void main(String[] args) {
        Path filePath = Path.of("commandInput.txt");

        // Check and delete the file if it exists
        try {
            if (Files.exists(filePath)) {
                Files.delete(filePath);
            }

            // Execute command
            String command = "your-command-here";  // Replace with your actual command
            Process process = Runtime.getRuntime().exec(command, null, new File("."));

            // Read and log output and error streams
            readAndLogStream(process.getInputStream(), true);
            readAndLogStream(process.getErrorStream(), false);

        } catch (IOException e) {
            logError("IOException occurred: " + e.getMessage());
        }
    }

    private static void readAndLogStream(InputStream inputStream, boolean isOutput) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (!isOutput && !line.isEmpty()) {
                    logError(line);
                } else {
                    System.out.println(line);
                }
            }
        }
    }

    private static void logError(String message) {
        // Using `snprintf` style formatting
        String formattedMessage = String.format("ERROR: %s%n", message);

        try (FileWriter fw = new FileWriter(ERROR_LOG_FILE, true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            bw.write(formattedMessage);
        } catch (IOException e) {
            System.err.println("Failed to log error: " + e.getMessage());
        }
    }
}
