using System;
using System.Collections.Concurrent;
using UnityEngine;

public class DynamicValueGenerator
{
    private enum DistributionType { Uniform, Gaussian, Exponential }

    private struct Config
    {
        public DistributionType Type;
        public float MinRange;
        public float MaxRange;
        public float Mean;
        public float StandardDeviation;
    }

    private readonly ConcurrentDictionary<string, float> cache = new();
    private readonly ConcurrentDictionary<string, int> intCache = new();
    private Config currentConfig;

    public DynamicValueGenerator(Config config)
    {
        if (config.MinRange >= config.MaxRange) 
            throw new ArgumentException("MinRange must be less than MaxRange.");

        currentConfig = config;
    }

    public float GetRandomFloat()
    {
        string cacheKey = $"float-{currentConfig.Type}-{currentConfig.MinRange}-{currentConfig.MaxRange}";

        return cache.GetOrAdd(cacheKey, _ =>
        {
            switch (currentConfig.Type)
            {
                case DistributionType.Uniform:
                    return UnityEngine.Random.Range(currentConfig.MinRange, currentConfig.MaxRange);
                case DistributionType.Gaussian:
                    float gaussianValue = UnityEngine.Random.value * 2 - 1;
                    return Mathf.Clamp((gaussianValue * currentConfig.StandardDeviation) + currentConfig.Mean, currentConfig.MinRange, currentConfig.MaxRange);
                case DistributionType.Exponential:
                    return Mathf.Exp(UnityEngine.Random.Range(0f, currentConfig.StandardDeviation)) * (currentConfig.MaxRange - currentConfig.MinRange) + currentConfig.MinRange;
                default:
                    throw new NotSupportedException("Unsupported distribution type.");
            }
        });
    }

    public int GetRandomInt()
    {
        string cacheKey = $"int-{currentConfig.Type}-{currentConfig.MinRange}-{currentConfig.MaxRange}";

        return intCache.GetOrAdd(cacheKey, _ =>
        {
            float randomFloat = GetRandomFloat();
            return Mathf.RoundToInt(randomFloat);
        });
    }

    public void UpdateConfig(Config newConfig)
    {
        if (newConfig.MinRange >= newConfig.MaxRange) 
            throw new ArgumentException("MinRange must be less than MaxRange.");

        currentConfig = newConfig;
        cache.Clear();
        intCache.Clear();
    }

    public override string ToString()
    {
        return $"Distribution: {currentConfig.Type}, Range: [{currentConfig.MinRange}, {currentConfig.MaxRange}], Mean: {currentConfig.Mean}, StdDev: {currentConfig.StandardDeviation}";
    }
}

