using Microsoft.Extensions.Caching.Memory;

public class WebsiteLifecycleManager
{
    private readonly IMemoryCache _cache;
    private static readonly HttpClient _httpClient = new HttpClient();

    public WebsiteLifecycleManager(IMemoryCache cache)
    {
        _cache = cache;
    }

    public async Task ManageWebsiteLifecycle(string configFilePath, List<string> siteNames, List<string> operations)
    {
        var configData = await LoadConfigurationAsync(configFilePath);
        ValidateInput(siteNames, operations);

        foreach (var operation in operations)
        {
            Parallel.ForEach(siteNames, async siteName =>
            {
                if (!await IsWebConfigExistAsync(siteName))
                {
                    LogError($"Missing web.config for {siteName}");
                    return;
                }

                try
                {
                    await PerformOperationWithRetryAsync(operation, siteName);
                    LogAction($"{operation} operation performed on {siteName}");
                }
                catch (Exception ex)
                {
                    LogError($"Error performing {operation} on {siteName}: {ex.Message}");
                }
            });
        }

        ValidateOAuthTokenResponse(); // Assuming this is executed within the main thread or appropriately managed
    }

    private async Task<Dictionary<string, string>> LoadConfigurationAsync(string configFilePath)
    {
        if (!File.Exists(configFilePath))
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        var json = await File.ReadAllTextAsync(configFilePath);
        return JsonConvert.DeserializeObject<Dictionary<string, string>>(json);
    }

    private void ValidateInput(List<string> siteNames, List<string> operations)
    {
        if (siteNames == null || siteNames.Count == 0)
            throw new ArgumentException("Site names cannot be empty.");

        if (operations == null || operations.Count == 0)
            throw new ArgumentException("Operations cannot be empty.");

        var uniqueSites = new HashSet<string>(siteNames);
        if (uniqueSites.Count != siteNames.Count)
            throw new ArgumentException("Duplicate site names found.");

        foreach (var operation in operations)
        {
            if (!new[] { "add", "remove", "start", "stop", "restart" }.Contains(operation))
                throw new ArgumentException($"Invalid operation: {operation}");
        }
    }

    private async Task<bool> IsWebConfigExistAsync(string siteName)
    {
        string cacheKey = $"web.config.exist.{siteName}";
        if (!_cache.TryGetValue(cacheKey, out bool exists))
        {
            // Assume GetSiteDirectoryPath returns the path for a given site name
            var webConfigPath = Path.Combine(GetSiteDirectoryPath(siteName), "web.config");
            exists = File.Exists(webConfigPath);
            _cache.Set(cacheKey, exists, TimeSpan.FromMinutes(10));
        }

        return exists;
    }

    private async Task PerformOperationWithRetryAsync(string operation, string siteName)
    {
        int retries = 3;
        for (int attempt = 1; attempt <= retries; attempt++)
        {
            try
            {
                await PerformApiCallAsync(operation, siteName);
                break;
            }
            catch (HttpRequestException) when (attempt < retries)
            {
                await Task.Delay(ExponentialBackoff(attempt));
            }
        }
    }

    private async Task PerformApiCallAsync(string operation, string siteName)
    {
        // Example API call
        var response = await _httpClient.PostAsync($"https://api.example.com/{operation}/{siteName}", null);
        response.EnsureSuccessStatusCode();
    }

    private TimeSpan ExponentialBackoff(int attempt)
    {
        return TimeSpan.FromSeconds(Math.Pow(2, attempt));
    }

    private void ValidateOAuthTokenResponse()
    {
        // This method needs to be adapted for real usage
        Task.Run(() =>
        {
            try
            {
                // Assume this is the received JSON string from an external service
                var jsonResponse = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
                JObject json = JObject.Parse(jsonResponse);

                if (!json.ContainsKey("access_token") || !json.ContainsKey("expires_in") ||
                    !json.ContainsKey("token_type"))
                {
                    throw new Exception("Invalid token response.");
                }

                if (json["token_type"].ToString() != "Bearer")
                {
                    throw new Exception("Token type must be 'Bearer'.");
                }
            }
            catch (JsonException ex)
            {
                LogError($"JSON parsing error: {ex.Message}");
            }
        });
    }

    private string GetSiteDirectoryPath(string siteName)
    {
        // Placeholder for actual logic to get the directory path
        return $"/var/www/{siteName}";
    }

