```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <mysql/mysql.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    int id;
    long offset1;
    long offset2;
    int key1;
    int key2;
    double average;
} Record;

MYSQL *conn;
pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

void connect_db() {
    conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "host", "user", "password", "database", 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        exit(1);
    }
}

void disconnect_db() {
    if (conn) {
        mysql_close(conn);
    }
}

int process_line(char *line, Record *record) {
    int result = sscanf(line, "%d %ld %ld %d %d",
                        &record->id, &record->offset1, &record->offset2,
                        &record->key1, &record->key2);

    if (result != 5) return -1;

    record->average = ((double)(record->key1 + record->key2)) / 2.0;
    return 0;
}

void *insert_record(void *arg) {
    Record *record = (Record *)arg;

    pthread_mutex_lock(&db_lock);
    if (mysql_real_query(conn, 
        "INSERT INTO records (id, offset1, offset2, key1, key2, average) VALUES (?, ?, ?, ?, ?, ?)",
        strlen("INSERT INTO records (id, offset1, offset2, key1, key2, average) VALUES (?, ?, ?, ?, ?, ?)"))) {
        fprintf(stderr, "%s\n", mysql_error(conn));
    }
    // Use prepared statements in production code
    pthread_mutex_unlock(&db_lock);

    free(record);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        exit(1);
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    connect_db();

    char line[MAX_LINE_LENGTH];
    pthread_t threads[100]; // Limiting to a maximum of 100 concurrent threads
    int thread_count = 0;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        if (process_line(line, record) != 0) {
            free(record);
            continue; // Skip malformed lines
        }

        if (pthread_create(&threads[thread_count], NULL, insert_record, record)) {
            perror("Failed to create thread");
            free(record);
        } else {
            thread_count++;

            if (thread_count >= sizeof(threads) / sizeof(pthread_t)) {
                for (int i = 0; i < thread_count; ++i)
                    pthread_join(threads[i], NULL);

                thread_count = 0;
            }
        }
    }

    // Join remaining threads
    for (int i = 0; i < thread_count; ++i) 
        pthread_join(threads[i], NULL);

    fclose(file);
    disconnect_db();

    return 0;
}
