using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

class UserProfileUpdater
{
    private static readonly HttpClient client = new HttpClient();
    private static Dictionary<string, bool> cachedDirectoryValidations = new Dictionary<string, bool>();
    private static Dictionary<string, bool> cachedUserIds = new Dictionary<string, bool>();

    public static async Task UpdateUserProfileAsync(string configFilePath, List<int> userIds, JObject profileDetails)
    {
        // Load configuration
        var config = LoadConfiguration(configFilePath);

        // Validate directory paths
        if (!ValidateDirectoryPaths(config.DirectoryPath))
            throw new InvalidOperationException("Invalid directory path.");

        // Prepare tasks for concurrent updates
        List<Task> updateTasks = new List<Task>();

        foreach (var userId in userIds)
        {
            if (!cachedUserIds.ContainsKey(userId.ToString()) && !ValidateUserId(userId, config))
                continue;

            var userTask = UpdateUserProfileForUserAsync(userId, profileDetails);
            updateTasks.Add(userTask);
        }

        await Task.WhenAll(updateTasks);

        // Log completion
        Console.WriteLine("All profiles updated successfully.");
    }

    private static bool ValidateDirectoryPaths(string directoryPath)
    {
        if (cachedDirectoryValidations.ContainsKey(directoryPath))
            return cachedDirectoryValidations[directoryPath];

        var isValid = Directory.Exists(directoryPath) && Path.GetInvalidFileNameChars().IsSubsetOf(directoryPath.ToCharArray());
        cachedDirectoryValidations[directoryPath] = isValid;

        return isValid;
    }

    private static bool ValidateUserId(int userId, Config config)
    {
        if (cachedUserIds.ContainsKey(userId.ToString()))
            return cachedUserIds[userId.ToString()];

        var isValid = CheckWithExternalApi(config.ApiUrl, $"users/{userId}");
        cachedUserIds[userId.ToString()] = isValid;

        return isValid;
    }

    private static async Task UpdateUserProfileForUserAsync(int userId, JObject profileDetails)
    {
        try
        {
            // Rate limiting and retry logic
            var response = await RetryPolicy.ExecuteAsync(() => SendUpdateRequest(userId, profileDetails));

            if (!response.IsSuccessStatusCode)
                Log($"Failed to update user {userId}. Status Code: {response.StatusCode}", LogLevel.Error);
            else
                Log($"User {userId} updated successfully.", LogLevel.Info);
        }
        catch (Exception ex)
        {
            Log($"Error updating user {userId}: {ex.Message}", LogLevel.Error);
        }
    }

    private static async Task<HttpResponseMessage> SendUpdateRequest(int userId, JObject profileDetails)
    {
        var url = $"https://api.example.com/users/{userId}/update";
        return await client.PostAsync(url, new StringContent(profileDetails.ToString(), System.Text.Encoding.UTF8, "application/json"));
    }

    private static Config LoadConfiguration(string filePath)
    {
        string json = File.ReadAllText(filePath);
        return JsonConvert.DeserializeObject<Config>(json);
    }

    public class RetryPolicy
    {
        public static async Task<T> ExecuteAsync<T>(Func<Task<T>> action, int maxRetries = 3, TimeSpan? delay = null)
        {
            if (delay == null) delay = TimeSpan.FromSeconds(2);

            for (int i = 0; i < maxRetries; i++)
            {
                try
                {
                    return await action();
                }
                catch
                {
                    if (i == maxRetries - 1) throw;
                    await Task.Delay(delay.Value);
                }
            }

            throw new InvalidOperationException("Retry policy failed.");
        }
    }

    private static void Log(string message, LogLevel level)
    {
        // Implement logging logic here
        Console.WriteLine($"[{level}] {message}");
    }

    private static bool CheckWithExternalApi(string apiUrl, string endpoint)
    {
        try
        {
            var response = client.GetAsync($"{apiUrl}/{endpoint}").Result;
            return response.IsSuccessStatusCode;
        }
        catch
        {
            return false;
        }
    }

    private enum LogLevel { Info, Warning, Error }

    private class Config
    {
        public string ApiUrl { get; set; }
        public string DirectoryPath { get; set; }
    }
}

class Program
{
    static async Task Main(string[] args)
    {
        if (args.Length < 3)
        {
            ShowHelp();
            return;
        }

        var configFilePath = args[0];
        var userIds = new List<int> { int.Parse(args[1]) }; // Parse user IDs from arguments
        var profileDetails = JObject.FromObject(new { Email = "newemail@example.com", Phone = "1234567890" });

        await UserProfileUpdater.UpdateUserProfileAsync(configFilePath, userIds, profileDetails);
    }

    private static void ShowHelp()
    {
        Console.WriteLine("Usage:");
        Console.WriteLine("  UpdateUserProfile <configFilePath> <userId1> [<userId2> ...]");
        Console.WriteLine();
        Console.WriteLine("Options:");
        Console.WriteLine("  configFilePath   Path to the configuration file.");
        Console.WriteLine("  userId           User IDs whose profiles need updating.");
    }
}
