```javascript
class FinancialApiService {
  constructor(baseUrl) {
    this.baseUrl = baseUrl;
  }

  async fetchTransactionAmount(transactionId, retryCount = 3) {
    const url = `${this.baseUrl}/transactions/${transactionId}`;

    for (let attempt = 1; attempt <= retryCount; attempt++) {
      try {
        // Simulate network latency
        await new Promise(resolve => setTimeout(resolve, Math.random() * 500));

        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch transaction: ${transactionId}`);

        const data = await response.json();
        if (typeof data.amount !== 'number') throw new Error(`Invalid amount for transaction: ${transactionId}`);

        return data.amount;
      } catch (error) {
        console.error(`Attempt ${attempt} failed for transaction: ${transactionId}`, error.message);

        // Exponential backoff
        const delay = Math.pow(2, attempt) * 100; 
        if (attempt < retryCount) await new Promise(resolve => setTimeout(resolve, delay));
      }
    }

    console.error(`All retries exhausted for transaction: ${transactionId}`);
    return null;
  }
}

class WorkerPool {
  constructor(size) {
    this.size = size;
    this.tasks = [];
    this.results = [];
    this.running = 0;
  }

  addTask(task) {
    this.tasks.push(task);
  }

  async processTasks() {
    while (this.tasks.length > 0 || this.running > 0) {
      if (this.running < this.size && this.tasks.length > 0) {
        const task = this.tasks.shift();
        this.running++;

        task().then(result => {
          this.results.push(result);
          this.running--;
        }).catch(error => console.error('Worker error:', error));
      }

      await new Promise(resolve => setTimeout(resolve, 10)); // Short delay to allow other tasks
    }

    return this.results;
  }
}

class TransactionReducer {
  constructor(financialApiService, maxConcurrentWorkers) {
    this.financialApiService = financialApiService;
    this.workerPool = new WorkerPool(maxConcurrentWorkers);
  }

  async reduceTransactionIds(transactionIds, initialTotal = 0) {
    const tasks = transactionIds.map(id => () =>
      this.financialApiService.fetchTransactionAmount(id).then(amount => ({ id, amount }))
    );

    // Add tasks to the worker pool
    tasks.forEach(task => this.workerPool.addTask(task));

    // Process all tasks asynchronously
    const results = await this.workerPool.processTasks();

    // Reduce valid amounts
    return results.reduce((total, { amount }) => (amount !== null ? total + amount : total), initialTotal);
  }
}

// Example usage:
(async () => {
  const financialApiService = new FinancialApiService('https://api.example.com');
  const transactionReducer = new TransactionReducer(financialApiService, maxConcurrentWorkers = 5);

  const transactionIds = [1, 2, 3, /* up to >10,000 IDs */];

  try {
    const totalAmount = await transactionReducer.reduceTransactionIds(transactionIds);
    console.log(`Total Amount: ${totalAmount}`);
  } catch (error) {
    console.error('Error reducing transactions:', error.message);
  }
})();
