int encrypt(void *cipher_handle, DataBuffer *input, DataBuffer *output);
int decrypt(void *cipher_handle, DataBuffer *input, DataBuffer *output);
void cleanup_cipher(void *cipher_handle);

typedef struct {
    pthread_t thread_id;
    void *cipher_handle;
    DataBuffer input_data;
    DataBuffer output_data;
} CipherThreadArgs;

// Thread function for concurrent encryption/decryption
void* cipher_operation(void *args) {
    CipherThreadArgs *thread_args = (CipherThreadArgs *) args;
    if (encrypt(thread_args->cipher_handle, &thread_args->input_data, &thread_args->output_data)) {
        fprintf(stderr, "Encryption failed\n");
    }
    // Cleanup after operation
    cleanup_cipher(thread_args->cipher_handle);
    return NULL;
}

// User-friendly API functions
int encrypt_data(CipherConfig config, DataBuffer input, DataBuffer *output) {
    void *cipher_handle = NULL;
    if (initialize_cipher(config, &cipher_handle) != 0) {
        fprintf(stderr, "Cipher initialization failed\n");
        return -1;
    }

    output->data = malloc(input.length);
    output->length = input.length;

    CipherThreadArgs args = {pthread_self(), cipher_handle, input, *output};
    pthread_create(&args.thread_id, NULL, cipher_operation, &args);
    pthread_join(args.thread_id, NULL);

    return 0;
}

int decrypt_data(CipherConfig config, DataBuffer input, DataBuffer *output) {
    void *cipher_handle = NULL;
    if (initialize_cipher(config, &cipher_handle) != 0) {
        fprintf(stderr, "Cipher initialization failed\n");
        return -1;
    }

    output->data = malloc(input.length);
    output->length = input.length;

    CipherThreadArgs args = {pthread_self(), cipher_handle, input, *output};
    pthread_create(&args.thread_id, NULL, cipher_operation, &args);
    pthread_join(args.thread_id, NULL);

    return 0;
}

// Internal functions
int initialize_cipher(CipherConfig config, void **cipher_handle) {
    // Initialize the cipher based on mode and key management integration
    switch (config.mode) {
        case ECB:
            *cipher_handle = des_init_ecb(config.key);
            break;
        case EDE:
            *cipher_handle = des_init_ede(config.key);
            break;
        case EDE3:
            *cipher_handle = des_init_ede3(config.key);
            break;
        case CFB:
            *cipher_handle = des_init_cfb(config.key);
            break;
        case NULL_MODE:
            *cipher_handle = NULL; // No encryption
            break;
        default:
            return -1;
    }
    if (*cipher_handle == NULL) {
        fprintf(stderr, "Failed to initialize cipher\n");
        return -1;
    }
    return 0;
}

int encrypt(void *cipher_handle, DataBuffer *input, DataBuffer *output) {
    if (cipher_handle == NULL) {
        memcpy(output->data, input->data, input->length); // Null encryption
        return 0;
    }

    int result = des_encrypt(cipher_handle, input->data, output->data, input->length);
    return result == 0 ? 0 : -1;
}

int decrypt(void *cipher_handle, DataBuffer *input, DataBuffer *output) {
    if (cipher_handle == NULL) {
        memcpy(output->data, input->data, input->length); // Null decryption
        return 0;
    }

    int result = des_decrypt(cipher_handle, input->data, output->data, input->length);
    return result == 0 ? 0 : -1;
}

void cleanup_cipher(void *cipher_handle) {
    if (cipher_handle != NULL) {
        des_cleanup(cipher_handle);
    }
}

