### Core Library Implementation (`crypto_library.c`)

```c
#include <openssl/evp.h>
#include <dlfcn.h>
#include "crypto_library.h"
#include "plugins.h"

typedef struct {
    char *name;
    void *handle;
    EVP_CIPHER *(*init_cipher)();
} AlgorithmPlugin;

static AlgorithmPlugin plugins[] = {{"AES-256", NULL, NULL}, {"ChaCha20", NULL, NULL}};
static size_t num_plugins = 2;

void load_algorithm_plugin(const char *name) {
    void *handle = dlopen(name, RTLD_LAZY);
    if (!handle) {
        log_error("Failed to load plugin: %s\n", dlerror());
        return;
    }

    for (size_t i = 0; i < num_plugins; ++i) {
        if (strcmp(plugins[i].name, name) == 0) {
            plugins[i].handle = handle;
            plugins[i].init_cipher = dlsym(handle, "init_cipher");
            if (!plugins[i].init_cipher) {
                log_error("Failed to find init_cipher function: %s\n", dlerror());
            }
        }
    }
}

EVP_CIPHER_CTX *initialize_algorithm(const char *name) {
    for (size_t i = 0; i < num_plugins; ++i) {
        if (strcmp(plugins[i].name, name) == 0 && plugins[i].init_cipher) {
            return (*plugins[i].init_cipher)();
        }
    }

    log_error("Algorithm %s not available\n", name);
    return NULL;
}

void cleanup_library() {
    for (size_t i = 0; i < num_plugins; ++i) {
        if (plugins[i].handle) {
            dlclose(plugins[i].handle);
        }
    }
}
