pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize records from configuration file
int init_records_from_config(const char *config_path, int min_val, int max_val) {
    FILE *file = fopen(config_path, "r");
    if (!file) return -1;  // Error opening config file

    fscanf(file, "%zu", &record_count);  // Read the number of records
    if (record_count > MAX_RECORDS) record_count = MAX_RECORDS;

    records = malloc(record_count * sizeof(Record));
    if (!records) {
        fclose(file);
        return -2;  // Error allocating memory for records
    }

    srand(time(NULL));  // Seed random number generator

    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = rand() % (max_val - min_val + 1) + min_val;
        records[i].offset_value = rand();
    }

    fclose(file);
    return 0;  // Success
}

// Function to connect and store records in external database
int store_records_in_db(const char *db_config) {
    if (!records || record_count == 0) return -1;

    int db_conn = db_connect(db_config);  // Assume this connects to the DB
    if (db_conn < 0) return -2;  // Error connecting to database

    for (size_t i = 0; i < record_count; ++i) {
        if (!db_store_record(db_conn, records[i].key, records[i].offset_value)) {
            db_disconnect(db_conn);
            return -3;  // Error storing a record
        }
    }

    db_disconnect(db_conn);
    return 0;  // Success
}

// Thread-safe function to modify a specific record by key
int modify_record(int key, long new_offset) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < record_count; ++i) {
        if (records[i].key == key) {
            records[i].offset_value = new_offset;
            pthread_mutex_unlock(&lock);
            return 0;  // Success
        }
    }

    pthread_mutex_unlock(&lock);
    return -1;  // Record not found
}

// Thread-safe function to retrieve a record by key
int get_record(int key, long *result) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < record_count; ++i) {
        if (records[i].key == key) {
            *result = records[i].offset_value;
            pthread_mutex_unlock(&lock);
            return 0;  // Success
        }
    }

    pthread_mutex_unlock(&lock);
    return -1;  // Record not found
}

// Clean-up function to free allocated resources
void cleanup() {
    if (records) free(records);
    records = NULL;
    record_count = 0;
}
```

### Design Choices and Trade-offs

- **Memory Management**: We use dynamic memory allocation for the records to handle potentially large datasets, with a cap at `MAX_RECORDS` to prevent excessive usage. The choice of malloc/free is typical in C when managing memory manually.

- **Concurrency**: A pthread mutex (`pthread_mutex_t`) ensures that modifications and retrievals are thread-safe by locking critical sections where shared data is accessed or modified. This ensures consistency, though it may introduce some contention if many threads try to access the records simultaneously.

- **File I/O Operations**: The configuration file is read once during initialization. We use `fscanf` for reading a single integer (the number of records) and then allocate memory accordingly. Error handling is implemented using return codes from functions like `fopen`.

- **Performance Optimization**: 
  - Using a mutex ensures thread safety but can be a bottleneck if many threads access it simultaneously.
  - Memory allocation is done in bulk to minimize the overhead associated with frequent allocations/deallocations.

- **Error Handling**: Functions return error codes for various failure scenarios, including file I/O errors and database connection issues. This allows calling functions to handle these cases appropriately.

- **External Database Integration**: The code assumes an external API is provided for connecting, storing, and disconnecting from the database (`db_connect`, `db_store_record`, `db_disconnect`). Error checking on each operation ensures robustness against connectivity or write failures.

Overall, this implementation balances between ease of management, performance, and reliability while ensuring thread safety and error handling.

```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import org.springframework.util.concurrent.ListenableFuture;
import org.springframework.web.client.RestTemplate;

import javax.sql.DataSource;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Service
public class PokemonService {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/%d";
    private static final int MAX_CONCURRENT_REQUESTS = 1000;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private DataSource dataSource;

    private ObjectMapper objectMapper = new ObjectMapper();

    public ListenableFuture<Map<String, Object>> getPokemonDetails(int pokemonId) {
        return executorService.submit(() -> {
            Map<String, Object> response = new HashMap<>();
            try {
                String apiUrl = String.format(API_URL, pokemonId);
                HttpEntity<?> request = new HttpEntity<>(Collections.emptyMap());

                HttpResponse<String> httpResponse = HttpClient.newBuilder()
                        .version(HttpClient.Version.HTTP_2)
                        .build()
                        .send(
                                HttpRequest.newBuilder(URI.create(apiUrl)).GET().build(),
                                HttpResponse.BodyHandlers.ofString());

                if (httpResponse.statusCode() == 200) {
                    JsonNode rootNode = objectMapper.readTree(httpResponse.body());
                    response.put("name", rootNode.get("name").asText());
                    response.put("types", parseTypes(rootNode));
                    response.put("weaknesses", parseWeaknesses(rootNode));
                    response.put("evolutions", parseEvolutions(rootNode, pokemonId));
                } else {
                    response.put("error", "Pokemon not found or API error");
                }
            } catch (Exception e) {
                response.put("error", "Network error or unexpected response: " + e.getMessage());
            }
            return cacheData(pokemonId, response);
        });
    }

    @Cacheable("pokemonDetails")
    private Map<String, Object> cacheData(int pokemonId, Map<String, Object> data) {
        // Cache the data
        try (Connection connection = dataSource.getConnection()) {
            String sql = "INSERT INTO pokemon_cache (id, data) VALUES (?, ?) ON DUPLICATE KEY UPDATE data = ?";
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setInt(1, pokemonId);
                statement.setString(2, objectMapper.writeValueAsString(data));
                statement.setString(3, objectMapper.writeValueAsString(data));
                statement.executeUpdate();
            }
        } catch (Exception e) {
            System.err.println("Error caching data: " + e.getMessage());
        }
        return data;
    }

    private List<String> parseTypes(JsonNode rootNode) throws IOException {
        List<String> types = new ArrayList<>();
        JsonNode typesNode = rootNode.get("types");
        for (JsonNode type : typesNode) {
            String typeName = type.get("type").get("name").asText();
            types.add(typeName);
        }
        return types;
    }

    private List<String> parseWeaknesses(JsonNode rootNode) throws IOException {
        // Placeholder logic: Implement actual weakness parsing
        List<String> weaknesses = new ArrayList<>();
        JsonNode statsNode = rootNode.get("stats");
        for (JsonNode stat : statsNode) {
            if ("defense".equals(stat.get("stat").get("name").asText())) {
                JsonNode effectivenessArray = stat.get("base_stat").findValues("0"); // Weakness type index
                weaknesses.addAll(effectivenessArray.map(JsonNode::asText));
            }
        }
        return weaknesses;
    }

    private Map<String, Object> parseEvolutions(JsonNode rootNode, int pokemonId) throws IOException {
        Map<String, Object> evolutions = new HashMap<>();
        JsonNode evolutionChainUrlNode = rootNode.get("evolution_chain");
        if (evolutionChainUrlNode != null) {
            String evolutionUrl = evolutionChainUrlNode.asText();
            HttpEntity<?> req = new HttpEntity<>(Collections.emptyMap());
            HttpResponse<String> response = HttpClient.newBuilder()
                    .version(HttpClient.Version.HTTP_2)
                    .build()
                    .send(
                            HttpRequest.newBuilder(URI.create(evolutionUrl)).GET().build(),
                            HttpResponse.BodyHandlers.ofString());

            if (response.statusCode() == 200) {
                JsonNode evolutionRoot = objectMapper.readTree(response.body());
                JsonNode evolvesTo = findEvolutionStage(evolutionRoot, pokemonId);
                if (evolvesTo != null) {
                    evolutions.put("next", parseEvolutionDetails(evolvesTo));
                }
            }
        }
        return evolutions;
    }

    private JsonNode findEvolutionStage(JsonNode evolutionRoot, int currentPokemonId) throws IOException {
        String chainUrl = evolutionRoot.get("url").asText();
        HttpEntity<?> req = new HttpEntity<>(Collections.emptyMap());
        HttpResponse<String> response = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_2)
                .build()
                .send(
                        HttpRequest.newBuilder(URI.create(chainUrl)).GET().build(),
                        HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            JsonNode evolutionChainRoot = objectMapper.readTree(response.body());
            return findStageById(evolutionChainRoot, currentPokemonId);
        }
        return null;
    }

    private JsonNode findStageById(JsonNode chainRoot, int pokemonId) throws IOException {
        JsonNode evolvesToNode = chainRoot.get("evolves_to");
        if (evolvesToNode.isArray() && !evolvesToNode.isEmpty()) {
            for (JsonNode evolve : evolvesToNode) {
                JsonNode speciesUrlNode = evolve.get("species").get("url");
                HttpEntity<?> req = new HttpEntity<>(Collections.emptyMap());
                HttpResponse<String> response = HttpClient.newBuilder()
                        .version(HttpClient.Version.HTTP_2)
                        .build()
                        .send(
                                HttpRequest.newBuilder(URI.create(speciesUrlNode.asText())).GET().build(),
                                HttpResponse.BodyHandlers.ofString());

                if (response.statusCode() == 200) {
                    JsonNode speciesRoot = objectMapper.readTree(response.body());
                    int id = speciesRoot.get("id").asInt();
                    if (id == pokemonId) {
                        return evolve;
                    }
                    JsonNode nextStage = findStageById(evolve, pokemonId);
                    if (nextStage != null) {
                        return nextStage;
                    }
                }
            }
        }
        return null;
    }

    private Map<String, Object> parseEvolutionDetails(JsonNode evolvesTo) throws IOException {
        Map<String, Object> evolutionDetails = new HashMap<>();
        JsonNode speciesUrlNode = evolvesTo.get("species").get("url");
        HttpEntity<?> req = new HttpEntity<>(Collections.emptyMap());
        HttpResponse<String> response = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_2)
                .build()
                .send(
                        HttpRequest.newBuilder(URI.create(speciesUrlNode.asText())).GET().build(),
                        HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            JsonNode speciesRoot = objectMapper.readTree(response.body());
            String name = speciesRoot.get("name").asText();
            evolutionDetails.put("name", name);
            // Placeholder for level: Implement actual logic to fetch the required level
            evolutionDetails.put("level", "Next evolution not defined");
        }
        return evolutionDetails;
    }

}
