class OffsetManager {
public:
    OffsetManager(const std::string& configFilePath) 
        : database(DB_CONNECT_STRING), userService(), htmlService() {

        loadConfig(configFilePath);
        setupHTTPServer();
    }

    void handlePostRequest(int userId, int requestId) {
        // Validate permissions
        if (!userService.hasPermission(userId)) {
            throw std::runtime_error("Permission denied");
        }

        auto future = std::async(std::launch::async, &OffsetManager::processRequest, this, userId, requestId);
    }

private:
    struct Record {
        int key;
        long offsetValue;
    };

    DatabaseAPI database;
    UserService userService;
    HTMLService htmlService;

    std::unordered_map<int, Record> records; // Stores the current version of records
    std::mutex recordMutex;

    void loadConfig(const std::string& configFilePath) {
        std::ifstream configFile(configFilePath);
        if (!configFile.is_open()) {
            throw std::runtime_error("Failed to open configuration file");
        }

        nlohmann::json configJson;
        configFile >> configJson;

        for (auto& elem : configJson["initialValues"]) {
            int key = elem.value<int>("key", -1);
            long offsetValue = elem.value<long>("offsetValue", 0L);

            if (key == -1) continue; // Invalid entry

            std::lock_guard<std::mutex> lock(recordMutex);
            records[key] = {key, offsetValue};
        }
    }

    void setupHTTPServer() {
        HTTPRequestHandler requestHandler([this](int userId, int requestId) {
            handlePostRequest(userId, requestId);
        });

        requestHandler.start();
    }

    void processRequest(int userId, int requestId) {
        std::lock_guard<std::mutex> lock(recordMutex);

        if (!records.count(requestId)) {
            throw std::runtime_error("Invalid request ID");
        }

        Record& record = records[requestId];

        // Simulate database read/write operation
        try {
            auto dbRecord = database.fetchRecord(requestId);
            long newOffsetValue = dbRecord.offsetValue + 1; // Example logic

            if (!database.updateRecord(requestId, {dbRecord.key, newOffsetValue})) {
                throw std::runtime_error("Database update failed");
            }

            record.offsetValue = newOffsetValue;
        } catch (const DatabaseConnectionException& e) {
            logError(e.what());
            throw;
        }

        // Update HTML content
        try {
            htmlService.updateHTML(requestId, record);
        } catch (const std::exception& e) {
            logError(e.what());
            throw;
        }

        logAction(userId, requestId, record.offsetValue);
    }

    void logError(const std::string& message) const {
        // Logging logic
        std::cerr << "ERROR: " << message << std::endl;
    }

    void logAction(int userId, int requestId, long offsetValue) const {
        // Logging successful actions for auditing purposes
        std::cout << "User " << userId << " updated record " << requestId 
                  << " to offset value " << offsetValue << std::endl;
    }
};

// Usage Example (not part of class implementation):
int main() {
    try {
        OffsetManager manager("config.json");
    } catch (const std::exception& e) {
        std::cerr << "Initialization failed: " << e.what() << std::endl;
    }

    return 0;
}
