    let start_time = Instant::now();

    let dom = match DomTree::from(*node) {
        Ok(dom) => dom,
        Err(e) => {
            early_error(Box::new(e));
            return Err("Failed to create DOM tree".into());
        }
    };

    let elements = dom.select(selector).collect::<Vec<_>>();

    if ICE_HOOK.with(|hook| hook.get()) {
