    try {
      const key = Buffer.from(process.env.ENCRYPTION_KEY, 'hex');
      const decipher = crypto.createDecipheriv('aes-256-cbc', key, Buffer.alloc(16));
      let decryptedData = decipher.update(encryptedMessage, 'base64', 'utf8');
      decryptedData += decipher.final('utf8');

      const data = JSON.parse(decryptedData);
      // Data validation
      if (!validateData(data)) {
        ws.send(JSON.stringify({ error: 'Invalid data' }));
        return;
      }

      // Advanced processing (e.g., aggregation)
      const processedData = processData(data);

      // Store in Redis
      await setAsync(`sensor:${data.deviceId}:${Date.now()}`, JSON.stringify(processedData));

      // Real-time alerting logic
      if (checkAlertThresholds(processedData)) {
        triggerRealTimeAlert(processedData);
      }
    } catch (error) {
      console.error('Error processing message:', error.message);
      ws.send(JSON.stringify({ error: 'Processing Error' }));
    }
  });
});

