  windowMs: 15 * 60 * 1000,
  max: process.env.REQUEST_LIMIT || 100,
});

app.use(limiter);

app.get('/data', authenticate, async (req, res) => {
  const { deviceId } = req.query;
  try {
    const data = await getAsync(`sensor:${deviceId}`);
    if (!data) return res.status(404).send('Data not found');
    res.send(data);
  } catch (error) {
    res.status(500).send('Server Error');
  }
});

// Authentication middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization'];
  if (!token) return res.status(403).send('No token provided');

  jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
    if (err) return res.status(500).send('Failed to authenticate token');
    req.user = decoded;
    next();
  });
}

// Start HTTP server
const server = http.createServer(app);
server.on('upgrade', (request, socket, head) => {
  wss.handleUpgrade(request, socket, head, (ws) => {
    wss.emit('connection', ws, request);
  });
});

server.listen(process.env.PORT || 3000, () => console.log(`Server is running on port ${process.env.PORT || 3000}`));

