using Polly;

public class UserProfileUpdater
{
    private static readonly HttpClient httpClient = new HttpClient();
    private IMemoryCache _cache;
    private ILogger _logger;

    public UserProfileUpdater(IMemoryCache cache, ILogger logger)
    {
        _cache = cache;
        _logger = logger;
    }

    public async Task UpdateUserProfile(string configFilePath, List<int> userIds, Dictionary<string, string> updatedProfileDetails)
    {
        var config = LoadConfig(configFilePath);

        ValidateUserIds(userIds);
        EnsureValidDirectoryPaths();

        var tasks = new List<Task>();

        foreach (var userId in userIds)
        {
            tasks.Add(UpdateUserProfileForUser(userId, updatedProfileDetails));
        }

        await Task.WhenAll(tasks);
    }

    private void ValidateUserIds(List<int> userIds)
    {
        // Implement user ID validation logic
    }

    private void EnsureValidDirectoryPaths()
    {
        // Check and validate directory paths
    }

    private async Task UpdateUserProfileForUser(int userId, Dictionary<string, string> updatedProfileDetails)
    {
        var cacheKey = $"profile_{userId}";

        if (!_cache.TryGetValue(cacheKey, out var cachedData))
        {
            var retryPolicy = Policy.Handle<HttpRequestException>()
                .WaitAndRetryAsync(new[]
                {
                    TimeSpan.FromSeconds(1),
                    TimeSpan.FromSeconds(2),
                    TimeSpan.FromSeconds(4)
                }, (exception, timeSpan, context) =>
                {
                    _logger.Log($"Retrying due to: {exception.Message}");
                });

            var profileUpdateTask = retryPolicy.ExecuteAsync(async () =>
            {
                // Prioritize critical updates
                if (updatedProfileDetails.ContainsKey("Email") || updatedProfileDetails.ContainsKey("Phone"))
                {
                    await UpdateCriticalFields(userId, updatedProfileDetails);
                }

                foreach (var field in updatedProfileDetails.Keys)
                {
                    var apiUrl = GetApiUrl(field); 
                    _logger.Log($"Updating {field} for user {userId}");

                    if (!string.IsNullOrEmpty(apiUrl))
                    {
                        var response = await httpClient.PutAsync(apiUrl, new StringContent(JsonConvert.SerializeObject(updatedProfileDetails), System.Text.Encoding.UTF8, "application/json"));

                        if (response.IsSuccessStatusCode)
                        {
                            _logger.Log($"Successfully updated {field} for user {userId}");
                        }
                        else
                        {
                            _logger.LogError($"Failed to update {field} for user {userId}. Status: {response.StatusCode}");
                        }
                    }
                }

                cachedData = "Updated";
                _cache.Set(cacheKey, cachedData);
            });

            await profileUpdateTask;
        }
    }

    private async Task UpdateCriticalFields(int userId, Dictionary<string, string> updatedProfileDetails)
    {
        foreach (var field in new List<string> { "Email", "Phone" })
        {
            if (updatedProfileDetails.ContainsKey(field))
            {
                var apiUrl = GetApiUrl(field);

                if (!string.IsNullOrEmpty(apiUrl))
                {
                    var response = await httpClient.PutAsync(apiUrl, new StringContent(JsonConvert.SerializeObject(new { userId, [field] = updatedProfileDetails[field] }), System.Text.Encoding.UTF8, "application/json"));

                    if (response.IsSuccessStatusCode)
                    {
                        _logger.Log($"Successfully updated {field} for user {userId}");
                    }
                    else
                    {
                        _logger.LogError($"Failed to update {field} for user {userId}. Status: {response.StatusCode}");
                    }
                }
            }
        }
    }

    private string GetApiUrl(string field)
    {
        // Map profile fields to corresponding API URLs
        return field switch
        {
            "Email" => "https://api.example.com/update-email",
            "Phone" => "https://api.example.com/update-phone",
            _ => null,
        };
    }

    private dynamic LoadConfig(string configFilePath)
    {
        if (!File.Exists(configFilePath))
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        var configFileContent = File.ReadAllText(configFilePath);
        return JsonConvert.DeserializeObject<dynamic>(configFileContent);
    }

    public void ShowHelp()
    {
        Console.WriteLine("Usage: UpdateUserProfile <ConfigFilePath> <UserIdList> <ProfileDetails>");
        Console.WriteLine("<ConfigFilePath>: Path to configuration file");
        Console.WriteLine("<UserIdList>: Comma-separated list of user IDs");
        Console.WriteLine("<ProfileDetails>: JSON string with fields such as Email, Phone, Address, etc.");
    }
}

