import java.io.*;
import java.nio.file.*;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private static final String CONFIG_FILE = "config.txt";
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        if (Files.exists(Paths.get(CONFIG_FILE))) {
            try {
                Files.delete(Paths.get(CONFIG_FILE));
            } catch (IOException e) {
                logError("Failed to delete config file: %s", e.getMessage());
            }
        }

        String[] commands = {"echo Hello, World!", "ls -l", "ping localhost"};

        for (String command : commands) {
            executeCommandWithRetry(command);
        }
    }

    private static void executeCommandWithRetry(String command) {
        int attempt = 0;
        boolean success = false;

        while (attempt < MAX_RETRIES && !success) {
            try {
                Process process = Runtime.getRuntime().exec(command);

                readStream(process.getInputStream(), "OUTPUT");
                readStream(process.getErrorStream(), "ERROR");

                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    success = true;
                } else {
                    throw new IOException("Command failed with exit code: " + exitCode);
                }
            } catch (IOException | InterruptedException e) {
                logError("Attempt %d for command '%s' failed: %s", attempt + 1, command, e.getMessage());

                if (++attempt < MAX_RETRIES) {
                    try {
                        long backoffTime = (long) Math.pow(2, attempt);
                        TimeUnit.SECONDS.sleep(backoffTime);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }

        if (!success) {
            logError("Command '%s' failed after %d attempts", command, MAX_RETRIES);
        }
    }

    private static void readStream(InputStream stream, String type) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(stream));
        String line;
        while ((line = reader.readLine()) != null) {
            logInfo("%s: %s", type, line);
        }
        reader.close();
    }

    private static void logError(String format, Object... args) {
        String message = String.format(format, args);
        System.err.println(message); // Replace with actual logging
    }

    private static void logInfo(String format, Object... args) {
        String message = String.format(format, args);
        System.out.println(message); // Replace with actual logging
    }
}
