<?php

class RateLimiter {
    private $bucket;
    private $capacity;
    private $refillRate;
    private $lastChecked;

    public function __construct($capacity = 5, $interval = 60) {
        $this->capacity = $capacity;
        $this->refillRate = $capacity / $interval;
        $this->bucket = $capacity;
        $this->lastChecked = microtime(true);
    }

    private function refill() {
        $now = microtime(true);
        $elapsed = $now - $this->lastChecked;
        $tokensToAdd = floor($elapsed * $this->refillRate);

        if ($tokensToAdd > 0) {
            $this->bucket = min($this->capacity, $this->bucket + $tokensToAdd);
            $this->lastChecked = $now;
        }
    }

    public function consume() {
        $this->refill();

        if ($this->bucket >= 1) {
            --$this->bucket;
            return true;
        }

        return false;
    }
}

function logError($message) {
    file_put_contents('error_log.txt', date('[Y-m-d H:i:s] ') . $message . PHP_EOL, FILE_APPEND);
}

function verifyClinicDetails($clinic_id) {
