        $stmt->execute([$new_status, $last_modified_ip, $clinic_id]);

        return 'Clinic status updated successfully.';
    } catch (PDOException $e) {
        logError("Database error: " . $e->getMessage());
        return 'An error occurred while updating the clinic status.';
    }
}

