from dotenv import load_dotenv
from pathlib import Path
from cachetools import TTLCache, cached
from retrying import retry
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
import threading

# Load environment variables
def load_environment():
    env_path = Path('.') / '.env'
    local_env_path = Path('.') / '.env.local'

    if local_env_path.exists():
        load_dotenv(local_env_path)
    elif env_path.exists():
        load_dotenv(env_path)

    return os.getenv('ENVIRONMENT', 'development')

# Database Connection with Retry
class DatabaseManager:
    def __init__(self):
        self.lock = threading.Lock()
        self.engine = None

    @retry(wait_exponential_multiplier=1000, wait_exponential_max=10000)
    def connect(self, db_url):
        with self.lock:
            if not self.engine:
                self.engine = create_engine(db_url, echo=True)
            return sessionmaker(bind=self.engine)()

    def get_session(self, db_type='sqlite'):
        db_urls = {
            'sqlite': f'sqlite:///{os.getenv("DATABASE_URL", "db.sqlite")}',
            'mysql': os.getenv('MYSQL_DATABASE_URL'),
            'postgresql': os.getenv('POSTGRESQL_DATABASE_URL')
        }

        if not db_urls[db_type]:
            raise ValueError(f"No database URL found for {db_type}")

        return self.connect(db_urls[db_type])

# Caching Strategy
class CacheManager:
    def __init__(self, maxsize=100, ttl=300):
        self.cache = TTLCache(maxsize=maxsize, ttl=ttl)

    @cached(cache=lambda self: self.cache)
    def get(self, key, default=None):
        return self.cache.get(key, default)

    def set(self, key, value, ttl=None):
        self.cache[key] = value
        if ttl:
            self.cache.expire_time[key] = time.time() + ttl

