```php
<?php

class SecurePasswordManager {
    private $redis;
    private $logFile = 'error_log.txt';
    private $rateLimitKeyPrefix = 'password_gen_rate_';

    public function __construct($redis) {
        $this->redis = $redis;
    }

    public function generateSecurePassword($length, $charSet, $algorithm = PASSWORD_DEFAULT, $customSaltPrefix = '', $customSaltSuffix = '') {
        if (!$this->validateInputs($length, $charSet, $algorithm)) {
            return null; // Input validation failed
        }

        try {
            // Check rate limit
            if ($this->isRateLimited()) {
                throw new Exception("Rate limit exceeded");
            }

            $salt = $this->generateSalt($length, $charSet, $customSaltPrefix, $customSaltSuffix);
            $password = $this->generatePassword($length, $charSet);

            if (!$this->validatePasswordStrength($password)) {
                throw new Exception("Generated password does not meet strength requirements");
            }

            $hashedPassword = $this->hashPasswordWithSalt($password, $salt, $algorithm);

            // Store in Redis
            $this->storeInRedis($salt, $hashedPassword);

            return ['password' => $password, 'salt' => $salt, 'hash' => $hashedPassword];
        } catch (Exception $e) {
            $this->logError($e);
            return null;
        }
    }

    public function validatePassword($password, $hashedPassword, $algorithm = PASSWORD_DEFAULT) {
        try {
            if (!$this->isRateLimited()) {
                throw new Exception("Rate limit exceeded");
            }

            // Extract salt from hashed password
            $salt = substr($hashedPassword, 0, strlen($password));
            return password_verify($password . $salt, $hashedPassword);
        } catch (Exception $e) {
            $this->logError($e);
            return false;
        }
    }

    private function validateInputs($length, $charSet, $algorithm) {
        if ($length < 8 || $length > 64 || !is_string($charSet) || empty($charSet) || !in_array($algorithm, [PASSWORD_DEFAULT, PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
            return false;
        }
        return true;
    }

    private function isRateLimited() {
        $userId = $_SERVER['REMOTE_ADDR']; // Example identifier
        $key = $this->rateLimitKeyPrefix . $userId;
        $attempts = (int)$this->redis->get($key) ?: 0;

        if ($attempts >= 10) { // Allow max 10 requests per minute
            return true;
        }

        $this->redis->incr($key);
        $this->redis->expire($key, 60);

        return false;
    }

    private function generateSalt($length, $charSet, $prefix, $suffix) {
        $salt = '';
        for ($i = 0; $i < $length; $i++) {
            $salt .= $charSet[random_int(0, strlen($charSet) - 1)];
        }
        return $prefix . $salt . $suffix;
    }

    private function generatePassword($length, $charSet) {
        $password = '';
        for ($i = 0; $i < $length; $i++) {
            $password .= $charSet[random_int(0, strlen($charSet) - 1)];
        }
        return $password;
    }

    private function hashPasswordWithSalt($password, $salt, $algorithm) {
        $options = [];
        if ($algorithm === PASSWORD_BCRYPT || $algorithm === PASSWORD_ARGON2ID) {
            $options['cost'] = 12; // Customize as needed
        }
        return password_hash($password . $salt, $algorithm, $options);
    }

    private function validatePasswordStrength($password) {
        return strlen($password) >= 8 &&
               preg_match('/[A-Z]/', $password) && 
               preg_match('/[a-z]/', $password) && 
               preg_match('/\d/', $password) && 
               preg_match('/[\W_]/', $password);
    }

    private function storeInRedis($salt, $hashedPassword) {
        $this->redis->set("salt:{$salt}", $hashedPassword);
    }

    private function logError(Exception $e) {
        file_put_contents($this->logFile, '[' . date('Y-m-d H:i:s') . '] ' . $e->getMessage() . PHP_EOL, FILE_APPEND);
    }
}

// Unit Tests (Example using PHPUnit)
class SecurePasswordManagerTest extends \PHPUnit\Framework\TestCase {

    private $redisMock;

    protected function setUp(): void {
        $this->redisMock = $this->createMock(\Redis::class);
        $this->redisMock->method('get')->willReturn(5); // Example value
        $this->redisMock->method('incr')->will($this->returnCallback(function ($key) { return 6; }));
        $this->redisMock->method('expire')->willReturn(true);
    }

    public function testGenerateSecurePassword() {
        $manager = new SecurePasswordManager($this->redisMock);
        $result = $manager->generateSecurePassword(12, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$', PASSWORD_BCRYPT);
        $this->assertIsArray($result);
        $this->assertNotEmpty($result['password']);
        $this->assertNotEmpty($result['salt']);
        $this->assertNotEmpty($result['hash']);
    }

    public function testValidatePassword() {
        $manager = new SecurePasswordManager($this->redisMock);
        $testPassword = 'Test@1234';
        $salt = 'customSalt';
        $hashed = password_hash($testPassword . $salt, PASSWORD_BCRYPT);

        $isValid = $manager->validatePassword($testPassword, $hashed);
        $this->assertTrue($isValid);
    }

    public function testRateLimiting() {
        $manager = new SecurePasswordManager($this->redisMock);

        for ($i = 0; $i < 11; $i++) {
            $result = $manager->generateSecurePassword(12, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$', PASSWORD_BCRYPT);
            if ($i >= 10) {
                $this->assertNull($result); // Should be null due to rate limiting
            } else {
                $this->assertIsArray($result);
            }
        }
    }
}

