```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <mysql/mysql.h>

#define MAX_RECORDS 1000
#define MAX_KEY_VALUE_PAIRS 10

typedef struct {
    int id;
    long timestamp;
    int key_value_pairs[MAX_KEY_VALUE_PAIRS][2]; // [key, value]
    float weighted_average;
} Record;

typedef struct {
    MYSQL *connection;
    char *file_name;
} ThreadData;

void* process_file(void* arg) {
    ThreadData *data = (ThreadData*)arg;
    FILE *file = fopen(data->file_name, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Record records[MAX_RECORDS];
    int record_count = 0;

    while (!feof(file)) {
        char line[256];
        if (fgets(line, sizeof(line), file)) {
            Record rec;
            sscanf(line, "%d %ld", &rec.id, &rec.timestamp);

            // Parse key-value pairs
            for (int i = 0; i < MAX_KEY_VALUE_PAIRS && !feof(file); ++i) {
                if (fscanf(file, "%d %ld", &rec.key_value_pairs[i][0], &rec.key_value_pairs[i][1]) == 2) {
                    // Process more key-value pairs
                }
            }

            records[record_count++] = rec;
        }
    }

    fclose(file);

    for (int i = 0; i < record_count; ++i) {
        float total_weight = 0.0f;
        long weighted_sum = 0;

        for (int j = 0; j < MAX_KEY_VALUE_PAIRS && records[i].key_value_pairs[j][0] != 0; ++j) {
            int key = records[i].key_value_pairs[j][0];
            long value = records[i].key_value_pairs[j][1];

            // Assume weight is the key for simplicity
            weighted_sum += value * key;
            total_weight += key;
        }

        if (total_weight > 0) {
            records[i].weighted_average = (float)weighted_sum / total_weight;
        } else {
            records[i].weighted_average = 0.0f;
        }
    }

    // Example database interaction
    if (mysql_real_query(data->connection, "INSERT INTO records (id, timestamp, weighted_average) VALUES (...)", strlen("..."))) {
        fprintf(stderr, "%s\n", mysql_error(data->connection));
    }

    return NULL;
}

int main() {
    MYSQL *conn = mysql_init(NULL);
    conn = mysql_real_connect(conn, "host", "user", "password", "database", 0, NULL, 0);

    if (conn == NULL) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        return EXIT_FAILURE;
    }

    pthread_t threads[100];
    ThreadData thread_data[100];

    for (int i = 0; i < 10; ++i) { // Example: process 10 files concurrently
        thread_data[i].connection = conn;
        snprintf(thread_data[i].file_name, sizeof(thread_data[i].file_name), "file%d.txt", i);

        if (pthread_create(&threads[i], NULL, process_file, &thread_data[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    mysql_close(conn);
    return 0;
}
```

This code sets up a C program that reads from multiple files concurrently, calculates weighted averages of key-value pairs in records, and interacts with an external SQL server. It uses threads to handle concurrent file processing and ensures each thread manages its own database connection safely. Error handling is included for file operations and MySQL interactions. Adjustments can be made to accommodate different record structures or additional fields.

