import io.micronaut.context.annotation.Requires;
import io.micronaut.http.HttpResponse;
import io.micronaut.http.MediaType;
import io.micronaut.http.annotation.*;
import io.micronaut.security.annotation.Secured;
import io.micronaut.security.rules.SecurityRule;
import io.micronaut.configuration.kafka.annotation.EnableKafkaListener;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.bson.Document;

import javax.inject.Inject;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Requires(property = "spec.name", value = "report-microservice")
@EnableKafkaListener
@Controller("/reports")
public class ReportController {

    private final KafkaService kafkaService;
    private final DatabaseService databaseService;
    private final AuthService authService;
    private final EncryptionService encryptionService;
    private final RateLimiter rateLimiter;

    @Inject
    public ReportController(KafkaService kafkaService,
                            DatabaseService databaseService,
                            AuthService authService,
                            EncryptionService encryptionService,
                            RateLimiter rateLimiter) {
        this.kafkaService = kafkaService;
        this.databaseService = databaseService;
        this.authService = authService;
        this.encryptionService = encryptionService;
        this.rateLimiter = rateLimiter;
    }

    @Secured(SecurityRule.IS_AUTHENTICATED)
    @Get(value = "/generate", produces = MediaType.APPLICATION_JSON)
    public HttpResponse<Map<String, Object>> generateReport(@Header String userId,
                                                            @QueryValue("reportType") String reportType) {
        if (!rateLimiter.isAllowed(userId)) {
            return HttpResponse.status(429).body(Map.of("message", "Rate limit exceeded"));
        }

        authService.checkAuthorization(userId, reportType);

        Map<String, Object> aggregatedData = kafkaService.fetchLiveData();
        List<Document> mysqlData = databaseService.fetchFromMySQL();
        List<Document> postgresData = databaseService.fetchFromPostgreSQL();
        List<Document> mongoData = databaseService.fetchFromMongoDB();

        Map<String, Object> combinedData = combineData(aggregatedData, mysqlData, postgresData, mongoData);
        Map<String, Object> encryptedData = encryptionService.encrypt(combinedData);

        return HttpResponse.ok(encryptedData);
    }

    private Map<String, Object> combineData(Map<String, Object> kafkaData,
                                            List<Document> mysqlData,
                                            List<Document> postgresData,
                                            List<Document> mongoData) {
        // Logic to combine data from different sources
        Map<String, Object> combined = new ConcurrentHashMap<>(kafkaData);
        combined.put("mysql", mysqlData);
        combined.put("postgres", postgresData);
        combined.put("mongo", mongoData);
        return combined;
    }
}

