```rust
use std::fs;
use pest::Parser;
use log::{info, error};
use llvm_sys::*;
use llvm_sys::core::*;

// Define a simple grammar for demonstration using Pest
#[derive(Parser)]
#[grammar = "path/to/your.pest"] // Path to your grammar file
struct SimpleGrammar;

pub fn generate_llvm_ir(file_path: &str, debug_mode: bool) {
    if debug_mode {
        log::set_max_level(log::LevelFilter::Debug);
    } else {
        log::set_max_level(log::LevelFilter::Info);
    }

    // Read the file
    let input = match fs::read_to_string(file_path) {
        Ok(data) => data,
        Err(e) => {
            error!("Failed to read file: {}", e);
            return;
        }
    };

    // Initialize LLVM
    unsafe {
        LLVMDenseMapCreate(&c_int::from(0), None, &mut _ctx);
        LLVMLinkInMCJIT(None);
        let _ = LLVM_InitializeNativeTarget();
        let _ = LLVM_InitializeAllAsmPrinters();

        info!("LLVM initialized successfully");
    }

    // Parse the input
    match SimpleGrammar::parse(Rule::grammar, &input) {
        Ok(parsed_rules) => {
            let ast = build_ast(&parsed_rules); // Function to convert parsed rules into AST

            // Perform semantic analysis and optimizations
            let optimized_ast = optimize_ast(ast);

            // Generate LLVM IR
            let ir_code = generate_ir(optimized_ast, debug_mode);

            match fs::write(file_path.replace(".ext", ".ll"), ir_code) {
                Ok(_) => info!("LLVM IR code successfully written to file."),
                Err(e) => error!("Failed to write IR code: {}", e),
            }
        },
        Err(e) => {
            error!("Parsing error: {:?}", e);
        }
    }

    // Cleanup LLVM
    unsafe {
        LLVMDenseMapDispose(_ctx, None);
        LLVMShutdown();
    }
}

fn build_ast(parsed_rules: pest::iterators::Pair<Rule, Rule>) -> AstNode {
    // Implement logic to convert parsed rules into an AST
    unimplemented!()
}

fn optimize_ast(ast: AstNode) -> OptimizedAstNode {
    // Implement optimization passes on the AST
    unimplemented!()
}

fn generate_ir(optimized_ast: OptimizedAstNode, debug_mode: bool) -> String {
    let mut context = unsafe { LLVMContextCreate() };
    let module = unsafe { LLVMModuleCreateWithNameInContext("module", context) };

    // Implement logic to traverse `optimized_ast` and populate the LLVM module

    let mut out = llvm::bit_reader::LLVMBinaryWriterInitMemoryBuffer(&mut null_mut(), &mut null_mut()).unwrap();
    if debug_mode {
        unsafe {
            LLVMPrintModuleToString(module, &mut out);
        }
    } else {
        unsafe {
            LLVMPrintModuleToFile(module, "/dev/null");
            LLVMDisposeModule(module);
        }
    }

    let result = unsafe { llvm::bit_reader::LLVMBinaryWriterFinish(out, null_mut()) };
    if result.is_null() {
        error!("Failed to finish writing IR.");
        String::new()
    } else {
        unsafe {
            let mut buffer: Vec<u8> = Vec::with_capacity(LLVMGetBinaryBufferSize(result));
            llvm::bit_reader::LLVMBinaryReaderCopyBytes(result, &mut buffer);
            LLVMDisposeMemoryBuffer(result);

            String::from_utf8(buffer).unwrap_or_else(|_| "Invalid UTF-8 in IR".to_string())
        }
    }
}

struct AstNode;
struct OptimizedAstNode;

fn main() {
    // Enable logging
    env_logger::init();

    generate_llvm_ir("path/to/your/input.file", true);
}
