#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

// Callback function for writing data received from libcurl
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) {
        printf("Not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;

    return realsize;
}

// Function to download a file from a URL
static int DownloadFile(const char *url, MemoryStruct *chunk) {
    CURL *curl_handle;
    curl_global_init(CURL_GLOBAL_ALL);

    curl_handle = curl_easy_init();
    if (curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, url);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)chunk);

        CURLcode res = curl_easy_perform(curl_handle);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        curl_easy_cleanup(curl_handle);
    }

    curl_global_cleanup();
    return 0;
}

// Function to calculate SHA-256 hash
static int CalculateSHA256(const char *filename, unsigned char outputBuffer[SHA256_DIGEST_LENGTH]) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("fopen");
        return -1;
    }

    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    const int bufSize = 32768;
    char *buffer = malloc(bufSize);
    if (!buffer) {
        fclose(file);
        fprintf(stderr, "malloc failed\n");
        return -1;
    }

    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, 1, bufSize, file))) {
        SHA256_Update(&sha256, buffer, bytesRead);
    }

    SHA256_Final(outputBuffer, &sha256);

    fclose(file);
    free(buffer);
    return 0;
}

// Function to upload a file to the cloud storage API
static int UploadFileToCloudStorage(const char *bucket, const char *directory, const char *filename) {
    // Placeholder for uploading logic
    printf("Uploading %s to bucket: %s, directory: %s\n", filename, bucket, directory);

    return 0;
}

// Function to encrypt data using the specified cipher mode
static EVP_CIPHER_CTX* EncryptData(const unsigned char *plaintext, int plaintext_len,
                                   unsigned char *ciphertext, const EVP_CIPHER *cipher) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("EVP_CIPHER_CTX_new");
        return NULL;
    }

    int len;
    int ciphertext_len;

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        perror("EVP_EncryptInit_ex");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Encryption operation
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        perror("EVP_EncryptUpdate");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        perror("EVP_EncryptFinal_ex");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ctx; // Return the cipher context
}

// Main function that integrates all operations
int UploadEncryptedFile(const char *bucket, const char *directory, const char *file_path_or_url) {
    unsigned char sha256_hash[SHA256_DIGEST_LENGTH];

    // Validate file metadata by calculating SHA-256 hash
    if (CalculateSHA256(file_path_or_url, sha256_hash) != 0) {
        fprintf(stderr, "Failed to calculate SHA-256 hash\n");
        return -1;
    }

    printf("Calculated SHA-256 hash for the file.\n");

    // Check if the file exists in the specified bucket and directory
    // Placeholder for checking logic

    MemoryStruct chunk = { .data = malloc(1), .size = 0 };

    // If it's a URL, download the file asynchronously
    if (strstr(file_path_or_url, "http://") || strstr(file_path_or_url, "https://")) {
        pthread_t thread_id;
        int result = pthread_create(&thread_id, NULL, (void *(*)(void *))DownloadFile, (void *)file_path_or_url);
        if (result != 0) {
            perror("pthread_create");
            free(chunk.data);
            return -1;
        }

        pthread_join(thread_id, NULL);

        // Perform encryption on the downloaded data
        EVP_CIPHER_CTX *ctx = EncryptData((const unsigned char*)chunk.data, chunk.size, NULL, EVP_des_cbc());
        if (!ctx) {
            fprintf(stderr, "Encryption failed\n");
            free(chunk.data);
            return -1;
        }
    }

    // Upload the file to the cloud storage
    int upload_status = UploadFileToCloudStorage(bucket, directory, file_path_or_url);
    if (upload_status != 0) {
        fprintf(stderr, "Failed to upload file\n");
        EVP_CIPHER_CTX_free(ctx);
        free(chunk.data);
        return -1;
    }

    printf("File uploaded successfully.\n");

    EVP_CIPHER_CTX_free(ctx);
    free(chunk.data);
    return 0;
}

