```c
#include <stdio.h>
#include <stdlib.h>
import zip
import threading

// Resource structure to hold resource items and metadata
typedef struct {
    char *key;
    char *value;
    // Additional metadata fields can be added here
} ResourceItem;

// Thread-safe data structure for storing resources
typedef struct {
    ResourceItem **items;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread safety
} ResourceBundle;

// Function to load a resource bundle from a compressed file
size_t LoadResourceBundle(const char *filePath, ResourceBundle *bundle) {
    if (!filePath || !bundle) return 0;

    pthread_mutex_init(&bundle->lock, NULL);

    FILE *file = fopen(filePath, "rb");
    if (!file) {
        perror("Failed to open file");
        return 0;
    }

    // Read ZIP file header and handle errors
    struct zipFile zf = zip_open(file, 0, 'r');
    if (!zf) {
        fclose(file);
        perror("Failed to open ZIP archive");
        return 0;
    }

    int i, numEntries = zip_get_num_files(zf);
    char **filenames = (char **)malloc(numEntries * sizeof(char *));
    for (i = 0; i < numEntries; ++i) {
        filenames[i] = zip_get_name(zf, i, 0);
    }

    // Estimate memory and allocate resources
    bundle->items = (ResourceItem **)calloc(numEntries, sizeof(ResourceItem *));
    if (!bundle->items) {
        perror("Failed to allocate memory for resource items");
        goto cleanup;
    }

    for (i = 0; i < numEntries; ++i) {
        // Open and read file from zip
        FILE *fileInZip = zip_fopen(zf, filenames[i], 'r');
        if (!fileInZip) continue;

        char *buffer;
        int bufferSize = zip_fget_size(fileInZip);
        buffer = (char *)malloc(bufferSize + 1);

        if (zip_fread(fileInZip, buffer, bufferSize) == bufferSize) {
            buffer[bufferSize] = '\0'; // Null-terminate the string
            ResourceItem *item = malloc(sizeof(ResourceItem));
            item->key = filenames[i];
            item->value = strdup(buffer);

            pthread_mutex_lock(&bundle->lock);
            bundle->items[bundle->count++] = item;
            pthread_mutex_unlock(&bundle->lock);

        } else {
            perror("Failed to read file from ZIP");
        }

        free(buffer);
        zip_fclose(fileInZip);
    }

    free(filenames);

cleanup:
    if (zf) zip_close(zf);
    fclose(file);
    return bundle->count;
}

// Function to clean up the resource bundle
void FreeResourceBundle(ResourceBundle *bundle) {
    if (!bundle || !bundle->items) return;

    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }
    free(bundle->items);
    pthread_mutex_unlock(&bundle->lock);

    pthread_mutex_destroy(&bundle->lock);
}

// Unit tests for the LoadResourceBundle function
void TestLoadResourceBundle() {
    ResourceBundle bundle = {0};

    // Test loading a small bundle
    size_t itemCount = LoadResourceBundle("test_bundle.zip", &bundle);
    printf("Loaded %zu items from test_bundle.zip\n", itemCount);

    // Stress test with multiple threads
    const int NUM_THREADS = 10;
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))LoadResourceBundle, "test_large_bundle.zip") != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    FreeResourceBundle(&bundle);
}

int main() {
    TestLoadResourceBundle();
    return 0;
}
``` 

