```javascript
const axios = require('axios');
const { promisify } = require('util');
const readline = require('readline');
const fs = require('fs');

class TransactionReducer {
  constructor({ apiUrl, workerPoolSize = 100 }) {
    this.apiUrl = apiUrl;
    this.workerPoolSize = Math.min(workerPoolSize, 100);
    this.activeWorkers = 0;
  }

  async fetchTransactionDetails(transactionId) {
    const url = `${this.apiUrl}/transactions/${transactionId}`;
    let retries = 3;
    while (retries > 0) {
      try {
        return await axios.get(url, { timeout: 5000 });
      } catch (error) {
        if (!error.response || error.response.status === 429 || error.code === 'ECONNABORTED') {
          retries--;
          await this.exponentialBackoff(retries);
          continue;
        }
        throw new Error(`Failed to fetch transaction ${transactionId}: ${error.message}`);
      }
    }
    throw new Error(`Max retries reached for transaction ${transactionId}`);
  }

  async exponentialBackoff(attempt) {
    const delay = Math.pow(2, attempt - 1) * 100;
    return new Promise((resolve) => setTimeout(resolve, delay));
  }

  async processTransactions(transactionIds) {
    if (!Array.isArray(transactionIds)) throw new Error('Invalid input: expected an array of transaction IDs.');
    if (transactionIds.length === 0) return [];

    const results = [];
    const chunkSize = Math.ceil(transactionIds.length / this.workerPoolSize);
    for (let i = 0; i < transactionIds.length; i += chunkSize) {
      const chunk = transactionIds.slice(i, i + chunkSize);
      await this.processChunk(chunk).then(results.push.bind(results));
    }

    return results.flat();
  }

  async processChunk(chunk) {
    const promises = chunk.map((transactionId) => this.withConcurrencyLimit(() => this.fetchTransactionDetails(transactionId)));
    return Promise.all(promises);
  }

  withConcurrencyLimit(fn) {
    if (this.activeWorkers >= this.workerPoolSize) {
      return new Promise((resolve) => setTimeout(() => resolve(this.withConcurrencyLimit(fn)), 100));
    }

    return new Promise((resolve, reject) => {
      this.activeWorkers++;
      fn().then(resolve).catch(reject).finally(() => {
        this.activeWorkers--;
      });
    });
  }

  async calculateWeightedAverage(record) {
    const totalKeys = Object.keys(record).length;
    let weightedSum = 0;
    for (const [key, value] of Object.entries(record)) {
      if (typeof key === 'number' && typeof value === 'bigint') {
        weightedSum += Number(value);
      }
    }
    record.weightedAverage = totalKeys > 0 ? weightedSum / totalKeys : 0;
  }

  async processFile(filePath) {
    const fileStream = fs.createReadStream(filePath, { encoding: 'utf8' });
    const rl = readline.createInterface({ input: fileStream });

    for await (const line of rl) {
      try {
        const record = JSON.parse(line);
        await this.calculateWeightedAverage(record);
        console.log(`Processed record ${record.id}: Weighted Average - ${record.weightedAverage}`);
      } catch (error) {
        console.error(`Error processing record: ${error.message}`);
      }
    }
  }

  async handleNetworkFailures() {
    try {
      const transactionIds = [/* Simulated or fetched transaction IDs */];
      await this.processTransactions(transactionIds);
    } catch (error) {
      console.error(error.message);
      // Retry logic or other error handling can be implemented here.
    }
  }
}

