#include "ConfigParser.h"
#include <fstream>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

ConfigParser::ConfigParser(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) throw std::runtime_error("Could not open config file");

    json j;
    file >> j;

    for (auto& [key, value] : j.items()) {
        if (value.is_number_integer()) config_[key] = value.get<int>();
        else if (value.is_number_float()) config_[key] = value.get<double>();
        else if (value.is_string()) config_[key] = value.get<std::string>();
        else if (value.is_boolean()) config_[key] = value.get<bool>();
    }
}

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> ConfigParser::getConfig() const {
