#include "UnionFind.h"

UnionFind::UnionFind(size_t size) : parent_(size), rank_(size, 0) {
    for (size_t i = 0; i < size; ++i) parent_[i] = i;
}

void UnionFind::unionSets(int a, int b) {
    int rootA = find(a);
    int rootB = find(b);

    if (rootA != rootB) {
        if (rank_[rootA] > rank_[rootB]) {
            parent_[rootB] = rootA;
        } else if (rank_[rootA] < rank_[rootB]) {
            parent_[rootV] = rootB;
        } else {
            parent_[rootB] = rootA;
            ++rank_[rootA];
        }
    }
}

int UnionFind::find(int x) const {
    if (parent_[x] != x) parent_[x] = find(parent_[x]);
    return parent_[x];
}

std::unordered_set<int> UnionFind::getDisjointPairs() const {
    std::unordered_set<int> pairs;
    for (size_t i = 0; i < parent_.size(); ++i) {
        int root = find(i);
        if (root == i) pairs.insert(root);
    }
    return pairs;
}
