public class DynamicWeatherUpdaterMiddleware
{
    private readonly string _latitude;
    private readonly string _longitude;
    private ConcurrentDictionary<string, WeatherData> _weatherCache = new();
    private string _selectedDataSource;

    public enum DataSource { RealTimeSensors, HistoricalRecords, ExternalServices }

    public DynamicWeatherUpdaterMiddleware(string latitude, string longitude)
    {
        _latitude = latitude ?? throw new ArgumentNullException(nameof(latitude));
        _longitude = longitude ?? throw new ArgumentNullException(nameof(longitude));
        _selectedDataSource = DataSource.ExternalServices.ToString();
    }

    public async Task UpdateWeatherConditionsAsync(HttpRequest request, HttpResponse response, Func<Task> next)
    {
        try
        {
            if (request.Method == "GET" || request.Method == "POST")
            {
                string weatherDataJson = await FetchWeatherDataAsync(_selectedDataSource);
                _weatherCache["Current"] = JsonConvert.DeserializeObject<WeatherData>(weatherDataJson);

                response.StatusCode = 200;
                response.ContentType = "application/json";
                response.Write(weatherDataJson);
            }
            else
            {
                await next();
            }
        }
        catch (Exception ex)
        {
            response.StatusCode = 500;
            response.ContentType = "text/plain";
            response.Write($"Error: {ex.Message}");
        }
    }

    private async Task<string> FetchWeatherDataAsync(DataSource source)
    {
        switch (source)
        {
            case DataSource.RealTimeSensors:
                return await GetRealTimeSensorData();
            case DataSource.HistoricalRecords:
                return await GetHistoricalData();
            case DataSource.ExternalServices:
                return await GetExternalServiceData();
            default:
                throw new NotSupportedException("Invalid data source");
        }
    }

