```javascript
const { promisify } = require('util');
const stream = require('stream');
const pipeline = promisify(stream.pipeline);

// A utility function to copy bytes from data chunks into a new buffer.
async function copyBytesFromChunks(chunks, byteCount) {
    if (!Array.isArray(chunks)) throw new Error('Invalid input: Chunks must be an array.');
    if (typeof byteCount !== 'number' || byteCount < 0)
        throw new Error('Invalid input: byteCount should be a non-negative number.');

    const targetBuffer = Buffer.alloc(byteCount);
    let bytesCopied = 0;

    // A custom readable stream that emits provided chunks
    class CustomReadableStream extends stream.Readable {
        constructor(chunks) {
            super({ objectMode: false });
            this.chunks = chunks;
            this.currentChunkIndex = 0;
        }

        _read() {
            if (this.currentChunkIndex < this.chunks.length) {
                const chunk = this.chunks[this.currentChunkIndex++];
                process.nextTick(() => this.push(chunk));
            } else {
                this.push(null); // Signal end of stream
            }
        }
    }

    try {
        await pipeline(
            new CustomReadableStream(chunks),
            new stream.PassThrough({
                objectMode: false,
                transform(chunk, encoding, callback) {
                    if (bytesCopied + chunk.length > byteCount) {
                        const remaining = byteCount - bytesCopied;
                        targetBuffer.set(chunk.slice(0, remaining), bytesCopied);
                        bytesCopied += remaining;
                        this.push(null); // No more data to push
                        callback();
                    } else {
                        targetBuffer.set(chunk, bytesCopied);
                        bytesCopied += chunk.length;
                        callback();
                    }
                },
            })
        );
    } catch (error) {
        throw new Error(`Data streaming failed: ${error.message}`);
    }

    if (bytesCopied < byteCount)
        throw new Error('Not enough data was provided to fill the buffer');

    return targetBuffer.slice(0, bytesCopied); // Return only the filled part
}

// Example usage
(async () => {
    try {
        const chunks = [Buffer.from('Hello'), Buffer.from('World!')];
        const result = await copyBytesFromChunks(chunks, 11);
        console.log(result.toString()); // Output: HelloWorld!
    } catch (error) {
        console.error(error.message);
    }
})();
