```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <zip.h>
#include <string.h>

// Struct to hold metadata and resource data
typedef struct {
    char *resource_name;
    char *data;
    size_t size;
} ResourceItem;

// Struct for thread-safe resource bundle management
typedef struct {
    zip_t *archive;
    pthread_mutex_t lock;
    int is_open;
} ResourceBundle;

// Function declarations
int open_bundle(ResourceBundle *bundle, const char *filename);
void close_bundle(ResourceBundle *bundle);
ResourceItem *fetch_resource(ResourceBundle *bundle, const char *resource_name);
void free_resource_item(ResourceItem *item);

// Open a resource bundle
int open_bundle(ResourceBundle *bundle, const char *filename) {
    pthread_mutex_init(&bundle->lock, NULL);
    if ((bundle->archive = zip_open(filename, 0, NULL)) == NULL) {
        return -1; // Error opening file
    }
    bundle->is_open = 1;
    return 0;
}

// Close a resource bundle
void close_bundle(ResourceBundle *bundle) {
    pthread_mutex_lock(&bundle->lock);
    if (bundle->is_open) {
        zip_close(bundle->archive);
        bundle->is_open = 0;
    }
    pthread_mutex_unlock(&bundle->lock);
    pthread_mutex_destroy(&bundle->lock);
}

// Fetch a resource from the bundle
ResourceItem *fetch_resource(ResourceBundle *bundle, const char *resource_name) {
    ResourceItem *item = malloc(sizeof(ResourceItem));
    if (!item) return NULL; // Memory allocation failure

    pthread_mutex_lock(&bundle->lock);

    if (bundle->is_open) {
        zip_int64_t index = zip_name_locate(bundle->archive, resource_name, ZIP_FL_ENC_GUESS);
        if (index < 0) {
            free(item);
            pthread_mutex_unlock(&bundle->lock);
            return NULL; // Resource not found
        }

        struct zip_stat st;
        if (zip_stat_index(bundle->archive, index, 0, &st) != 0) {
            free(item);
            pthread_mutex_unlock(&bundle->lock);
            return NULL; // Error getting resource stats
        }

        item->resource_name = strdup(resource_name);
        item->size = st.size;
        item->data = malloc(st.size);

        if (!item->resource_name || !item->data) {
            free(item->resource_name);
            free(item->data);
            free(item);
            pthread_mutex_unlock(&bundle->lock);
            return NULL; // Memory allocation failure
        }

        zip_file_t *file = zip_fopen_index(bundle->archive, index, 0);
        if (zip_fread(file, item->data, st.size) < 0) {
            free(item->resource_name);
            free(item->data);
            free(item);
            zip_fclose(file);
            pthread_mutex_unlock(&bundle->lock);
            return NULL; // Error reading resource
        }
        zip_fclose(file);
    }

    pthread_mutex_unlock(&bundle->lock);
    return item;
}

// Free a ResourceItem
void free_resource_item(ResourceItem *item) {
    if (item) {
        free(item->resource_name);
        free(item->data);
        free(item);
    }
}

// Example unit tests
void test_open_close_bundle() {
    ResourceBundle bundle = {0};
    assert(open_bundle(&bundle, "test.zip") == 0);
    close_bundle(&bundle);
    printf("Open/Close Bundle Test Passed\n");
}

void test_fetch_resource() {
    ResourceBundle bundle = {0};
    open_bundle(&bundle, "test.zip");

    ResourceItem *item = fetch_resource(&bundle, "resource.txt");
    assert(item != NULL && item->data != NULL);

    free_resource_item(item);
    close_bundle(&bundle);
    printf("Fetch Resource Test Passed\n");
}

int main() {
    test_open_close_bundle();
    test_fetch_resource();

    // Add more tests for stress testing and error scenarios
    return 0;
}
```

This code provides a basic implementation of a thread-safe resource bundle manager using the `libzip` library to handle ZIP files. It includes functions to open and close bundles, fetch resources, and free memory. The unit tests demonstrate opening/closing bundles and fetching resources.

