import json
import os
import sqlite3
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime

def process_log_file(file_path):
    with open(file_path, 'r') as file:
        data = [json.loads(line) for line in file]

    # Assuming anomaly detection is based on a threshold
    def filter_anomalies(entry):
        return entry['value'] < 1000  # Example condition

    cleaned_data = [entry for entry in data if filter_anomalies(entry)]

    # Connect to SQLite database and store cleaned data
    conn = sqlite3.connect('iot_data.db')
    cursor = conn.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS sensor_data 
                      (timestamp TEXT, sensor_id TEXT, value REAL)''')

    for entry in cleaned_data:
        timestamp = datetime.fromisoformat(entry['timestamp']).strftime('%Y-%m-%d %H:%M:%S')
        cursor.execute('INSERT INTO sensor_data (timestamp, sensor_id, value) VALUES (?, ?, ?)',
                       (timestamp, entry['sensor_id'], entry['value']))

    conn.commit()
    conn.close()

def process_logs_concurrently(log_folder):
    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        for file_name in os.listdir(log_folder):
            if file_name.endswith('.log'):
                executor.submit(process_log_file, os.path.join(log_folder, file_name))

# To use the script
# process_logs_concurrently('/path/to/log/files')

