```javascript
async function fetchWeatherDataForCities(cities, updateUI) {
    const apiKey = 'YOUR_API_KEY'; // Replace with your API key
    const baseUrl = 'https://api.weather.com/v1/location';
    let attempts = 0;

    async function fetchData(city) {
        try {
            const response = await fetch(`${baseUrl}/${city}?apiKey=${apiKey}`);
            if (!response.ok) throw new Error('Failed to fetch weather data');

            const data = await response.json();
            return { city, weatherData: data };
        } catch (error) {
            attempts++;
            console.error(`Error fetching data for ${city}:`, error);
            if (attempts < 3) {
                console.log(`Retrying for ${city}, attempt ${attempts}`);
                return fetchData(city);
            }
            return null;
        }
    }

    const weatherPromises = cities.map(fetchData);

    Promise.allSettled(weatherPromises)
        .then(results => {
            results.forEach(result => {
                if (result.status === 'fulfilled' && result.value) {
                    updateUI(result.value.city, result.value.weatherData);
                } else if (result.status === 'rejected') {
                    console.error(`Failed to fetch weather data after retries for ${result.reason}`);
                }
            });
        })
        .catch(error => console.error('Error in fetching all promises:', error));
}

// Example usage
// fetchWeatherDataForCities(['New York', 'Los Angeles'], updateUIFunction);
