### JWT Service with AWS KMS

```java
@Service
public class JwtService {

    private final String secretKeyAlias = "your-key-alias";
    private final KmsClient kmsClient;
    private final RedisTemplate<String, String> redisTemplate;

    @Autowired
    public JwtService(KmsClient kmsClient, RedisTemplate<String, String> redisTemplate) {
        this.kmsClient = kmsClient;
        this.redisTemplate = redisTemplate;
    }

    public String generateToken(String userId) throws Exception {
        byte[] keyBytes = getKeyFromKMS();
        Key hmacKey = new SecretKeySpec(keyBytes, 0, keyBytes.length, "HS256");

        return Jwts.builder()
                .setSubject(userId)
                .signWith(SignatureAlgorithm.HS256, hmacKey)
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            Jws<Claims> claims = Jwts.parser().parseClaimsJws(token);
            return true;
        } catch (JwtException | IllegalArgumentException e) {
            return false;
        }
    }

    private byte[] getKeyFromKMS() throws Exception {
        String cachedKey = redisTemplate.opsForValue().get(secretKeyAlias);

        if (cachedKey != null) {
            return Base64.getDecoder().decode(cachedKey);
        } else {
            GetSecretValueRequest request = GetSecretValueRequest.builder()
                    .secretId(secretKeyAlias)
                    .build();

            GetSecretValueResponse response = kmsClient.getSecretValue(request);

            byte[] keyBytes = response.secretBinary();
            redisTemplate.opsForValue().set(secretKeyAlias, Base64.getEncoder().encodeToString(keyBytes), Duration.ofHours(1));

            return keyBytes;
        }
    }

    public String refreshToken(String oldToken) throws Exception {
        Claims claims = Jwts.parser().parseClaimsJws(oldToken).getBody();
        claims.setIssuedAt(new Date());
        return generateToken((String) claims.getSubject());
    }
}
```

