#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define LOG_FILE_PATH "path/to/logfile.log"
#define OUTPUT_FILE_PATH "output.txt"

typedef struct {
    char *timestamp;
    char *client_ip;
    char *request_method;
    char *url;
    char *http_version;
    int response_status;
    size_t response_size;
} LogEntry;

// Mutex for thread-safe file operations
pthread_mutex_t file_mutex = PTHREAD_MUTEX_INITIALIZER;

LogEntry* parse_log_entry(const char *line);
void write_transformed_data(LogEntry *entry, FILE *output_file);
void error_logging_service(const char *error_message);

void* process_log_file(void *arg) {
    FILE *log_file = fopen(LOG_FILE_PATH, "r");
    if (!log_file) {
        perror("Failed to open log file");
        return NULL;
    }

    FILE *output_file = fopen(OUTPUT_FILE_PATH, "a");
    if (!output_file) {
        perror("Failed to open output file");
        fclose(log_file);
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), log_file)) {
        pthread_mutex_lock(&file_mutex);

        LogEntry *entry = parse_log_entry(line);
        if (entry) {
            write_transformed_data(entry, output_file);
            free(entry->timestamp);
            free(entry->client_ip);
            free(entry->request_method);
            free(entry->url);
            free(entry->http_version);
            free(entry);
        } else {
            error_logging_service("Failed to parse log entry");
        }

        pthread_mutex_unlock(&file_mutex);
    }

    fclose(log_file);
    fclose(output_file);
    return NULL;
}

LogEntry* parse_log_entry(const char *line) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    // Simulate parsing; replace with actual parsing logic
    char *token = strtok(line, " ");
    entry->timestamp = strdup(token);
    token = strtok(NULL, " ");
    entry->client_ip = strdup(token);
    token = strtok(NULL, " ");
    entry->request_method = strdup(token);
    token = strtok(NULL, " ");
    entry->url = strdup(token);
    token = strtok(NULL, " ");
    entry->http_version = strdup(token);
    token = strtok(NULL, " ");
    entry->response_status = atoi(token);
    token = strtok(NULL, "\n");
    entry->response_size = strlen(token);

    return entry;
}

void write_transformed_data(LogEntry *entry, FILE *output_file) {
    fprintf(output_file, "%s %s %s %s %d %zu\n",
            entry->timestamp, entry->client_ip,
            entry->request_method, entry->url,
            entry->response_status, entry->response_size);
}

void error_logging_service(const char *error_message) {
    // Simulate logging to a third-party service
    fprintf(stderr, "Error: %s\n", error_message);
}

int main() {
    pthread_t threads[10];  // Adjust number of threads based on expected load

    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, process_log_file, NULL)) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
