```java
import java.io.*;
import java.nio.charset.Charset;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;
import java.util.zip.*;

public class AsyncFileProcessor {

    private final Path directoryPath;
    private final List<String> keywords;
    private final ExecutorService executorService;
    private final ReportingApi reportingApi;
    private final Logger logger;

    public AsyncFileProcessor(Path directoryPath, List<String> keywords, ReportingApi reportingApi, Logger logger) {
        this.directoryPath = directoryPath;
        this.keywords = Collections.unmodifiableList(keywords);
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.reportingApi = reportingApi;
        this.logger = logger;
    }

    public void processFiles() {
        try (Stream<Path> paths = Files.walk(directoryPath)) {
            List<Future<?>> futures = paths.filter(Files::isRegularFile)
                                          .filter(path -> path.toString().endsWith(".txt"))
                                          .map(path -> executorService.submit(() -> processFile(path)))
                                          .collect(Collectors.toList());

            for (Future<?> future : futures) {
                try {
                    future.get();
                } catch (InterruptedException | ExecutionException e) {
                    logger.error("Error processing file", e);
                }
            }
        } catch (IOException e) {
            logger.error("Directory reading error", e);
        }
    }

    private void processFile(Path filePath) {
        Charset detectedCharset = detectEncoding(filePath);

        try (BufferedReader reader = Files.newBufferedReader(filePath, detectedCharset)) {
            String line;
            List<String> summaryLines = new ArrayList<>();

            while ((line = reader.readLine()) != null) {
                for (String keyword : keywords) {
                    if (line.contains(keyword)) {
                        summaryLines.add(line);
                        break;
                    }
                }
            }

            generateSummaryReport(summaryLines, filePath);

        } catch (IOException e) {
            logger.error("File reading error", e);
        }
    }

    private Charset detectEncoding(Path path) throws IOException {
        // Implement a simple encoding detection logic or use a library like juniversalchardet
        return StandardCharsets.UTF_8;
    }

    private void generateSummaryReport(List<String> summaryLines, Path filePath) {
        String report = buildReport(summaryLines, filePath);

        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            try (ZipOutputStream zos = new ZipOutputStream(baos)) {
                ZipEntry entry = new ZipEntry(filePath.getFileName().toString() + ".txt");
                zos.putNextEntry(entry);

                zos.write(report.getBytes());
                zos.closeEntry();
            }

            byte[] compressedReport = baos.toByteArray();
            uploadToApi(compressedReport);

        } catch (IOException e) {
            logger.error("Error generating summary report", e);
        }
    }

    private String buildReport(List<String> summaryLines, Path filePath) {
        StringBuilder sb = new StringBuilder("Summary for: " + filePath.getFileName() + "\n");
        for (String line : summaryLines) {
            sb.append(line).append("\n");
        }
        return sb.toString();
    }

    private void uploadToApi(byte[] compressedReport) {
        int retryCount = 0;
        final int maxRetries = 3;

        while (retryCount < maxRetries) {
            try {
                reportingApi.upload(compressedReport);
                logger.info("Upload successful for report");
                return; // Exit if successful
            } catch (ReportingApiException e) {
                retryCount++;
                logger.warn("Failed to upload, attempt " + retryCount, e);

                if (retryCount >= maxRetries) {
                    logger.error("Max retries reached. Upload failed.", e);
                }

                try {
                    Thread.sleep(2000); // Backoff strategy
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    interface ReportingApi {
        void upload(byte[] data) throws ReportingApiException;
    }

    interface Logger {
        void debug(String message);
        void info(String message);
        void warn(String message, Throwable t);
        void error(String message, Throwable t);
    }

    static class ReportingApiException extends Exception {
        public ReportingApiException(String message, Throwable cause) {
            super(message, cause);
        }
    }

}
