        _binaryFilePath = binaryFilePath;
        _encryptionKey = encryptionKey;
        _outdatedThresholdSeconds = outdatedThresholdSeconds;
        _logger = logger;
        _databaseService = databaseService;

        // Start background thread for periodic checks
        Task.Run(() => BackgroundFileChecker());
    }

    public void LoadAndDeserialize()
    {
        try
        {
            if (!File.Exists(_binaryFilePath))
            {
                FallbackToDatabase();
                return;
            }

            var lastModifiedTime = File.GetLastWriteTimeUtc(_binaryFilePath);
            if ((DateTime.UtcNow - lastModifiedTime).TotalSeconds > _outdatedThresholdSeconds)
            {
                _logger.Log("Binary file outdated. Refreshing cache.");
                FallbackToDatabase();
                return;
            }

            using (var fileStream = new FileStream(_binaryFilePath, FileMode.Open))
            {
                var decompressedData = Decompress(fileStream);
                var decryptedData = Decrypt(decompressedData);

                // Deserialize data
                var data = Deserialize(decryptedData);

                // Validate integrity
                if (!ValidateChecksum(data))
                {
                    _logger.Log("Checksum validation failed. Using database fallback.");
                    FallbackToDatabase();
                    return;
                }

                // Cache the deserialized data
                CustomCache.Set(data); // Assuming a custom caching mechanism

                // Manage garbage collection
                GC.Collect(GC.MaxGeneration, GCCollectionMode.Forced);
            }
        }
        catch (Exception ex)
        {
            _logger.Log($"Error loading binary file: {ex.Message}");
            FallbackToDatabase();
        }
    }

    private void FallbackToDatabase()
    {
        var data = _databaseService.GetPreferences<T>();
        CustomCache.Set(data);
    }

    private byte[] Decompress(Stream inputStream)
    {
        using (var decompressionStream = new GZipStream(inputStream, CompressionMode.Decompress))
        using (var memoryStream = new MemoryStream())
        {
            decompressionStream.CopyTo(memoryStream);
            return memoryStream.ToArray();
        }
    }

    private byte[] Decrypt(byte[] data)
    {
        using var aes = Aes.Create();
        aes.Key = Encoding.UTF8.GetBytes(_encryptionKey);
        aes.IV = new byte[16]; // Assuming a zero IV for simplicity

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        return PerformCryptography(data, decryptor);
    }

    private byte[] Serialize(T data)
    {
        // Implement serialization logic
    }

    private T Deserialize(byte[] data)
    {
        // Implement deserialization logic
    }

    private bool ValidateChecksum(T data)
    {
        var checksum = _databaseService.GetChecksum();
        return ComputeChecksum(data) == checksum;
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using var memoryStream = new MemoryStream();
        using (var cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write))
        {
            cryptoStream.Write(data, 0, data.Length);
        }
        return memoryStream.ToArray();
    }

    private string ComputeChecksum(T data)
    {
        // Implement checksum computation
    }

    private void BackgroundFileChecker()
    {
        while (true)
        {
            LoadAndDeserialize();
            Thread.Sleep(TimeSpan.FromMinutes(5)); // Adjust as necessary
        }
    }

    public void InsertAfterFirstOccurrence(List<string> forwardList, string target, string toInsert)
    {
        var index = forwardList.IndexOf(target);
        if (index != -1)
        {
            forwardList.Insert(index + 1, toInsert);
        }
        else
        {
            forwardList.Add(toInsert);
        }

        // Limit list size
        const int maxAllowedSize = 100; // Example threshold
        while (forwardList.Count > maxAllowedSize)
        {
            forwardList.RemoveAt(0); // Remove oldest entries
        }
    }
}

