namespace fs = std::filesystem;

// Utility function to calculate SHA-256 hash of a file
std::string calculateFileSHA256(const std::string& filePath) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file for hashing");
    }

    char buffer[8192];
    while (file.read(buffer, sizeof(buffer)) || file.gcount()) {
        SHA256_Update(&sha256, buffer, file.gcount());
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &sha256);

    std::ostringstream oss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        oss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }

    return oss.str();
}

// Function to upload a file and monitor its progress
