#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h> // JSON parsing library

#define MAX_SCOPE_LENGTH 256
#define TOKEN_TYPE_BEARER "Bearer"
#define MAX_EXPIRES_IN 3600

// Mock token store for refresh tokens
typedef struct {
    char *refresh_token;
    int is_valid; // 1 if valid, 0 otherwise
} TokenStore;

TokenStore* get_refresh_token_store() {
    static TokenStore token_store = {"example_refresh_token", 1};
    return &token_store;
}

int validate_scope(const char *scope) {
    const char *valid_scopes[] = {"read", "write", NULL};
    for (const char **p = valid_scopes; *p != NULL; p++) {
        if (strcmp(*p, scope) == 0) return 1;
    }
    return 0;
}

int is_token_expired(const char* refresh_token) {
    TokenStore* store = get_refresh_token_store();
    return strcmp(store->refresh_token, refresh_token) == 0 && store->is_valid;
}

int verify_oauth2_token_response(const char *json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return 0;
    }

    // Check for required fields
    const char* access_token = json_string_value(json_object_get(root, "access_token"));
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    const char* token_type = json_string_value(json_object_get(root, "token_type"));

    if (!access_token || !token_type || expires_in <= 0) {
        fprintf(stderr, "Missing or invalid required fields\n");
        goto end;
    }

    // Validate 'token_type'
    if (strcmp(token_type, TOKEN_TYPE_BEARER) != 0) {
        fprintf(stderr, "'token_type' must be 'Bearer'\n");
        goto end;
    }

    // Validate 'expires_in'
    if (expires_in > MAX_EXPIRES_IN) {
        fprintf(stderr, "'expires_in' must be <= %d seconds\n", MAX_EXPIRES_IN);
        goto end;
    }

    // Optional: validate refresh_token
    const char* refresh_token = json_string_value(json_object_get(root, "refresh_token"));
    if (refresh_token && !is_token_expired(refresh_token)) {
        fprintf(stderr, "'refresh_token' is expired or invalid\n");
        goto end;
    }

    // Validate 'scope'
    const char *scope_str = json_string_value(json_object_get(root, "scope"));
    if (!scope_str) {
        fprintf(stderr, "Missing scope\n");
        goto end;
    }

    char* scope_token = strtok(strdup(scope_str), " ");
    while (scope_token != NULL) {
        if (!validate_scope(scope_token)) {
            fprintf(stderr, "'scope' contains invalid value: %s\n", scope_token);
            free(scope_token);
            goto end;
        }
        scope_token = strtok(NULL, " ");
    }

    // If all validations pass
    printf("Token is valid.\n");
    int result = 1;

end:
    json_decref(root);
    return result;
}

int main() {
    const char *json_str = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\",\"scope\":\"read write\"}";
    if (verify_oauth2_token_response(json_str)) {
        printf("Token verified successfully.\n");
    } else {
        printf("Token verification failed.\n");
    }
    return 0;
}
```

