```java
// WeatherApiService.java
import retrofit2.Call;
import retrofit2.http.GET;
import retrofit2.http.Query;

public interface WeatherApiService {
    @GET("weather")
    Call<WeatherData> getWeather(@Query("q") String location, @Query("appid") String apiKey);
}

// WeatherRepository.java
import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.util.concurrent.TimeUnit;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class WeatherRepository {
    private static final int CACHE_SIZE = 100;
    private static final long TTL_DURATION = TimeUnit.HOURS.toMillis(1);
    private final Cache<String, WeatherData> cache = CacheBuilder.newBuilder()
            .maximumSize(CACHE_SIZE)
            .expireAfterWrite(TTL_DURATION, TimeUnit.MILLISECONDS)
            .build();

    private final WeatherApiService weatherApiService;
    private int apiRequestCount = 0;
    private int cacheHits = 0;
    private int cacheMisses = 0;

    public WeatherRepository(WeatherApiService weatherApiService) {
        this.weatherApiService = weatherApiService;
    }

    public void getWeather(String location, String apiKey, Callback<WeatherData> callback) {
        WeatherData cachedData = cache.getIfPresent(location);

        if (cachedData != null) {
            cacheHits++;
            callback.onResponse(null, Response.success(cachedData));
        } else {
            cacheMisses++;
            Call<WeatherData> call = weatherApiService.getWeather(location, apiKey);

            call.enqueue(new Callback<WeatherData>() {
                @Override
                public void onResponse(Call<WeatherData> call, Response<WeatherData> response) {
                    if (response.isSuccessful() && response.body() != null) {
                        cache.put(location, response.body());
                    }
                    callback.onResponse(call, response);
                }

                @Override
                public void onFailure(Call<WeatherData> call, Throwable t) {
                    callback.onFailure(call, t);
                }
            });

            apiRequestCount++;
        }
    }

    public int getApiRequestCount() {
        return apiRequestCount;
    }

    public int getCacheHits() {
        return cacheHits;
    }

    public int getCacheMisses() {
        return cacheMisses;
    }
}

// WeatherData.java
public class WeatherData {
    // Assume this contains weather-related fields like temperature, humidity, etc.
}

// MockWeatherApiService.java
import retrofit2.Call;
import retrofit2.Callback;
import java.util.concurrent.TimeUnit;

public class MockWeatherApiService implements WeatherApiService {
    private final Cache<String, WeatherData> cache = CacheBuilder.newBuilder()
            .maximumSize(100)
            .expireAfterWrite(1, TimeUnit.HOURS)
            .build();

    @Override
    public Call<WeatherData> getWeather(String location, String apiKey) {
        return new MockCall<>(cache.getIfPresent(location));
    }

    private static class MockCall<T> implements Call<T> {
        private final T data;

        MockCall(T data) {
            this.data = data;
        }

        @Override
        public Response<T> execute() throws IOException {
            return Response.success(data);
        }

        @Override
        public void enqueue(Callback<T> callback) {
            if (data != null) {
                callback.onResponse(this, Response.success((T) data));
            } else {
                callback.onFailure(this, new RuntimeException("Network error"));
            }
        }

        // Other required methods for Call interface are left unimplemented
    }
}

// WeatherServiceTest.java
