public class WeatherServiceTest {
    private MockWeatherApiService mockApiService;
    private WeatherRepository weatherRepository;

    @Before
    public void setUp() {
        mockApiService = new MockWeatherApiService();
        weatherRepository = new WeatherRepository(mockApiService);
    }

    @Test
    public void testCacheHitAndMiss() throws InterruptedException {
        String location = "London";
        String apiKey = "dummy_key";

        // First call should be a cache miss and an API request
        weatherRepository.getWeather(location, apiKey, (call, response) -> {});

        Thread.sleep(100);  // Give time for the asynchronous task to complete

        // Second call should be a cache hit
        weatherRepository.getWeather(location, apiKey, (call, response) -> {});

        assert weatherRepository.getApiRequestCount() == 1;
        assert weatherRepository.getCacheHits() == 1;
        assert weatherRepository.getCacheMisses() == 1;
    }
}
