```javascript
require('dotenv').config();
const yargs = require('yargs');
const { KafkaConsumer } = require('./kafkaConsumer');
const { Encryptor, generateKey } = require('./encryptor');

let consumer;
let encryptor;

async function start() {
  const key = await generateKey();

  encryptor = new Encryptor(key);

  consumer = new KafkaConsumer('KAFKA_BROKER', 'KAFKA_TOPIC', encryptor.handleData);

  try {
    await consumer.connect();
    console.log('Consumer connected and started.');
  } catch (error) {
    console.error('Failed to connect the consumer:', error.message);
  }
}

function stop() {
  if (consumer) consumer.disconnect();
}

yargs
  .command('start', 'Start data collection and encryption process', {}, start)
  .command('stop', 'Stop data collection and encryption process', {}, stop)
  .demandCommand()
  .help()
  .argv;
```

### `src/kafkaConsumer.js`
```javascript
const kafka = require('kafka-node');
const { KafkaClient, Consumer } = kafka;

class KafkaConsumer {
  constructor(broker, topic, processData) {
    this.broker = broker;
    this.topic = topic;
    this.processData = processData;
    this.client = new KafkaClient({ brokers: [broker] });
    this.consumer = new Consumer(this.client, [{ topic, partition: 0 }], { autoCommit: true });
    this.running = false;
  }

  connect() {
    return new Promise((resolve, reject) => {
      this.consumer.on('error', (err) => reject(err));
      this.consumer.on('message', (message) => {
        if (!this.running) return;
        try {
          const data = message.value.toString();
          this.processData(data);
        } catch (e) {
          console.error('Error processing message:', e.message);
        }
      });

      this.running = true;
      resolve();
    });
  }

  disconnect() {
    this.running = false;
    return new Promise((resolve, reject) => {
      this.consumer.close(() => {
        this.client.close(false, (err) => {
          if (err) return reject(err);
          console.log('Consumer disconnected.');
          resolve();
        });
      });
    });
  }
}

module.exports = { KafkaConsumer };
```

### `src/encryptor.js`
```javascript
const crypto = require('crypto');

class Encryptor {
  constructor(key) {
    this.algorithm = 'aes-256-cbc';
    this.key = key;
    this.iv = crypto.randomBytes(16); // AES block size is 16 bytes
  }

  encrypt(data) {
    const cipher = crypto.createCipheriv(this.algorithm, this.key, this.iv);
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return { iv: this.iv.toString('hex'), data: encrypted };
  }

  handleData(data) {
    try {
      const encryptedData = this.encrypt(data);
      console.log('Encrypted Data:', JSON.stringify(encryptedData));
    } catch (e) {
      console.error('Encryption error:', e.message);
    }
  }
}

async function generateKey() {
  return crypto.randomBytes(parseInt(process.env.ENCRYPTION_KEY_SIZE, 10)).toString('hex');
}

module.exports = { Encryptor, generateKey };
```

