### 2. JWT Service for Key Management and Token Operations
```java
import com.amazonaws.services.kms.AWSKMS;
import com.amazonaws.services.kms.AWSKMSClientBuilder;
import com.amazonaws.services.kms.model.DecryptRequest;
import io.jsonwebtoken.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

import javax.crypto.SecretKey;
import java.util.Date;

@Service
public class JwtService {

    private final AWSKMS awsKms;

    @Value("${kms.key-id}")
    private String keyId;

    public JwtService() {
        this.awsKms = AWSKMSClientBuilder.defaultClient();
    }

    @Cacheable("jwtKeys")
    public SecretKey getPrivateKey() throws Exception {
        DecryptRequest decryptRequest = new DecryptRequest().withCiphertextBlob(/* encrypted key */);
        byte[] decryptedKeyBytes = awsKms.decrypt(decryptRequest).getPlaintext().array();
        return Jwts.parserBuilder().setSigningKey(new byte[0]).build().getKeyFactory().generateSecret(null, decryptedKeyBytes);
    }

    public String generateToken(String subject) {
        SecretKey key = getPrivateKey();
        return Jwts.builder()
                .setSubject(subject)
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + 3600000)) // 1 hour expiration
                .signWith(SignatureAlgorithm.HS256, key)
                .compact();
    }

    public Claims validateToken(String token) {
        SecretKey key = getPrivateKey();
        return Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token).getBody();
    }
}
```

