```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a structure for State
typedef struct State {
    int id;
    struct State* next;
} State;

// Logger function prototype
void log_error(const char *message);

// Thread-safe mechanism
pthread_mutex_t state_lock = PTHREAD_MUTEX_INITIALIZER;

State* generate_state_list(int* states, size_t num_states, State* fsa, int last_state) {
    if (!states || !fsa || num_states == 0) {
        log_error("Invalid input parameters: null pointers or zero states.");
        return NULL;
    }

    pthread_mutex_lock(&state_lock);

    // Allocate memory for the new state list
    State* head = (State*)malloc(num_states * sizeof(State));
    if (!head) {
        log_error("Memory allocation failed for state list.");
        pthread_mutex_unlock(&state_lock);
        return NULL;
    }

    // Populate the new state list
    for (size_t i = 0; i < num_states; ++i) {
        head[i].id = states[i];
        head[i].next = (i + 1 < num_states) ? &head[i + 1] : NULL;
    }

    // Find the last state in the original FSA
    State* current = fsa;
    while (current && current->id != last_state) {
        current = current->next;
    }

    if (!current) {
        log_error("Last state not found in the existing FSA.");
        free(head);
        pthread_mutex_unlock(&state_lock);
        return NULL;
    }

    // Integrate the new state list
    current->next = head;

    pthread_mutex_unlock(&state_lock);

    return head; // Return the head of the newly created state list
}

// Dummy logger function for demonstration purposes
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
```

### Explanation:
- The `generate_state_list` function takes an array of states, their count, a pointer to an FSA, and the last state id in the existing list.
- It uses dynamic memory allocation for creating the new state list, ensuring it's checked for failure and logs errors if any.
- Thread safety is ensured using a mutex lock while modifying shared data structures.
- Error handling includes checks for null pointers and invalid inputs, logging messages as necessary without impacting performance.
- The code is modular with clear separation between logic components, making testing easier.

```python
import os
import time
import random
import string
import jwt
from datetime import datetime, timedelta
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
from threading import Lock
from functools import wraps
from flask import Flask, request, jsonify

# Global rate limiting data
rate_limit_data = {}
rate_limit_lock = Lock()

app = Flask(__name__)

CLIENT_ID = 'your_client_id'
CLIENT_SECRET = 'your_client_secret'
TOKEN_URL = 'https://example.com/oauth/token'
OAUTH_SCOPE = ['read', 'write']
JWT_SECRET_KEY = os.environ.get('JWT_SECRET_KEY')

def generate_secure_token(length=32, high_entropy=False):
    if high_entropy:
        return ''.join(random.choices(string.ascii_letters + string.digits + '!@#$%^&*()', k=length))
    else:
        return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def rate_limit(max_requests_per_minute):
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            user_id = request.headers.get('Authorization')
            with rate_limit_lock:
                current_time = time.time()
                window_start = current_time - 60
                if user_id not in rate_limit_data or rate_limit_data[user_id]['window_start'] < window_start:
                    rate_limit_data[user_id] = {'count': 1, 'window_start': current_time}
                else:
                    rate_limit_data[user_id]['count'] += 1

                if rate_limit_data[user_id]['count'] > max_requests_per_minute:
                    return jsonify({'error': 'rate limit exceeded'}), 429

            return f(*args, **kwargs)
        return wrapped
    return decorator

def oauth2_token_request():
    client = BackendApplicationClient(client_id=CLIENT_ID)
    oauth = OAuth2Session(client=client)
    token = oauth.fetch_token(token_url=TOKEN_URL, client_id=CLIENT_ID, client_secret=CLIENT_SECRET, scope=OAUTH_SCOPE)
    return token

@app.route('/generate-token', methods=['POST'])
@rate_limit(max_requests_per_minute=60)
def generate_token():
    data = {
        'iss': request.json.get('iss'),
        'sub': request.json.get('sub'),
        'aud': request.json.get('aud', 'default_audience'),
        'exp': datetime.utcnow() + timedelta(minutes=30),
        'iat': datetime.utcnow(),
        'jti': generate_secure_token(length=48, high_entropy=True)
    }

    token = jwt.encode(data, JWT_SECRET_KEY, algorithm='HS256')
    return jsonify({'access_token': token}), 200

@app.route('/refresh-token', methods=['POST'])
@rate_limit(max_requests_per_minute=60)
def refresh_token():
    try:
        token = request.json.get('token')
        decoded = jwt.decode(token, JWT_SECRET_KEY, algorithms=['HS256'], options={'verify_exp': False})
        new_data = {
            'iss': decoded['iss'],
            'sub': decoded['sub'],
            'aud': decoded['aud'],
            'exp': datetime.utcnow() + timedelta(minutes=30),
            'iat': datetime.utcnow(),
            'jti': generate_secure_token(length=48)
        }

        refreshed_token = jwt.encode(new_data, JWT_SECRET_KEY, algorithm='HS256')
        return jsonify({'access_token': refreshed_token}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 401

@app.route('/revoke-token', methods=['POST'])
@rate_limit(max_requests_per_minute=10)
def revoke_token():
    try:
        token = request.json.get('token')
        # Assuming a simple blacklist mechanism for demonstration
        jwt.decode(token, JWT_SECRET_KEY, algorithms=['HS256'])  # Just verifying the existence here.
        return jsonify({'message': 'Token revoked'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/introspect-token', methods=['POST'])
def introspect_token():
    token = request.json.get('token')
    try:
        decoded = jwt.decode(token, JWT_SECRET_KEY, algorithms=['HS256'], options={'verify_exp': False})
        # Perform additional security checks as needed
        return jsonify({'active': True, 'data': decoded}), 200
    except jwt.ExpiredSignatureError:
        return jsonify({'active': False, 'error': 'Token expired'}), 401
    except Exception as e:
        return jsonify({'active': False, 'error': str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True)
```

