Below is a simplified PHP-based deployment script that addresses the given requirements. Note that this script provides a basic framework, and you may need to customize it further based on your specific environment and orchestration service APIs.

```php
<?php

require 'vendor/autoload.php';

use Symfony\Component\Yaml\Yaml;
use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;

class DeploymentScript {
    private $k8sApiUrl;
    private $authToken;
    private $configFilePath;
    private $client;

    public function __construct($k8sApiUrl, $authToken, $configFilePath) {
        $this->k8sApiUrl = $k8sApiUrl;
        $this->authToken = $authToken;
        $this->configFilePath = $configFilePath;
        $this->client = new Client([
            'base_uri' => $k8sApiUrl,
            'headers' => ['Authorization' => "Bearer {$this->authToken}"]
        ]);
    }

    public function deploy($envVariables) {
        try {
            $config = Yaml::parseFile($this->configFilePath);
            $deploymentConfig = array_merge($config['default'], $envVariables);

            $response = $this->client->post('/api/v1/namespaces/default/deployments', [
                'json' => $deploymentConfig,
                'timeout' => 10
            ]);

            if ($response->getStatusCode() === 200) {
                echo "Deployment successful.\n";
            } else {
                throw new Exception("Failed to deploy. Status code: {$response->getStatusCode()}.");
            }
        } catch (RequestException $e) {
            $this->handleError($e);
        } catch (Exception $e) {
            echo "Error: " . $e->getMessage() . "\n";
        }
    }

    private function handleError(RequestException $e) {
        if ($e->hasResponse()) {
            echo "HTTP Request failed with response: " . $e->getResponse()->getBody() . "\n";
        } else {
            echo "Request exception: " . $e->getMessage() . "\n";
        }
    }

    public static function main($argv) {
        if (count($argv) < 4) {
            echo "Usage: php deploy.php <k8s_api_url> <auth_token> <config_file_path> [env_vars]\n";
            exit(1);
        }

        $k8sApiUrl = $argv[1];
        $authToken = $argv[2];
        $configFilePath = $argv[3];
        $envVariables = array_slice($argv, 4);

        $envVarsArray = [];
        foreach ($envVariables as $var) {
            list($key, $value) = explode('=', $var, 2);
            $envVarsArray[$key] = $value;
        }

        $deployer = new DeploymentScript($k8sApiUrl, $authToken, $configFilePath);
        $deployer->deploy($envVarsArray);
    }
}

DeploymentScript::main($argv);

