```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.concurrent.*;
import java.util.logging.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class FileUploaderService {

    private static final Logger LOGGER = Logger.getLogger(FileUploaderService.class.getName());
    private final Map<String, CloudStorageClient> cloudClients;
    private final ConcurrentHashMap<String, String> cache;

    public FileUploaderService(Map<String, CloudStorageClient> cloudClients) {
        this.cloudClients = cloudClients;
        this.cache = new ConcurrentHashMap<>();
    }

    public void uploadFile(String filePath, String bucketName, String dirPath, String serviceType) throws IOException {
        String hash = calculateSHA256(filePath);

        if (isFilePresentInCache(hash)) {
            LOGGER.info("File already present in the cache: " + filePath);
            return;
        }

        validateMetadata(filePath);

        CloudStorageClient client = cloudClients.get(serviceType.toLowerCase());

        if (client == null) {
            throw new IllegalArgumentException("Unsupported cloud storage service: " + serviceType);
        }

        File file = new File(filePath);
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        try {
            Future<?> uploadTask = executor.submit(() -> client.upload(file, bucketName, dirPath));
            uploadTask.get(); // Wait for completion

            addToCache(hash);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error uploading file: " + filePath, e);
            throw new IOException("Failed to upload the file", e);
        } finally {
            executor.shutdown();
        }
    }

    private boolean isFilePresentInCache(String hash) {
        return cache.containsKey(hash);
    }

    private void addToCache(String hash) {
        cache.put(hash, "cached");
        // Optionally implement a size limit and eviction policy
    }

    private String calculateSHA256(String filePath) throws IOException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");

        try (InputStream fis = new FileInputStream(filePath)) {
            byte[] byteArray = new byte[1024];
            int bytesCount;

            while ((bytesCount = fis.read(byteArray)) != -1) {
                digest.update(byteArray, 0, bytesCount);
            }
        }

        return bytesToHex(digest.digest());
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void validateMetadata(String filePath) throws IOException {
        File file = new File(filePath);

        if (!file.exists()) {
            throw new FileNotFoundException("File not found: " + filePath);
        }

        long fileSize = file.length();
        LOGGER.info("Validating metadata for file: " + filePath);

        // Example of validating size
        if (fileSize > 50 * 1024 * 1024) { // Limit to 50MB for demonstration
            throw new IOException("File exceeds the allowed size limit.");
        }

        // Further content type validation can be done using libraries like Apache Tika
    }
}

