    /**
     * Executes a given operation with retries and exponential backoff.
     *
     * @param operation The operation to execute.
     */
    private void executeWithRetry(Runnable operation) {
        int maxAttempts = 3;
        long initialBackoff = 100; // milliseconds

        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                operation.run();
                return;
            } catch (Exception e) {
                logger.warn("Attempt " + attempt + " failed: ", e);
                if (attempt == maxAttempts || isCriticalFailure(e)) {
                    throw new RuntimeException("Max retry attempts reached", e);
                }
                long backoff = initialBackoff * (1L << (attempt - 1));
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    private boolean isCriticalFailure(Exception e) {
        // Define logic to determine if an exception is critical
        return false;
    }

    /**
     * Transaction scope for managing atomic operations.
     */
    static class TransactionScope implements AutoCloseable {
        public void commit() {
            // Commit the transaction
        }

        @Override
        public void close() {
            // Rollback in case of an exception
        }
    }
}
