```python
import os
import json
import threading
from queue import Queue
import numpy as np
from scipy.stats import zscore
import gc

# Simulate database connection for demonstration purposes
class DistributedDatabase:
    def __init__(self):
        self.storage = {}

    def insert(self, key, data):
        if key not in self.storage:
            self.storage[key] = []
        self.storage[key].append(data)

def process_log_file(file_path, db_connection):
    with open(file_path, 'r') as file:
        for line in file:
            data = json.loads(line)
            # Assuming the structure contains a 'sensor_id' and 'value'
            sensor_data = np.array(data['values'])
            z_scores = zscore(sensor_data)
            filtered_data = sensor_data[np.abs(z_scores) < 3]  # Filter anomalies
            db_connection.insert(file_path, {'filtered_data': filtered_data.tolist()})
    gc.collect()  # Explicit garbage collection

def worker(log_queue, db_connection):
    while True:
        log_file = log_queue.get()
        if log_file is None:
            break
        process_log_file(log_file, db_connection)
        log_queue.task_done()

def main(log_directory, num_threads=4):
    db_connection = DistributedDatabase()
    log_files = [os.path.join(log_directory, f) for f in os.listdir(log_directory) if f.endswith('.log')]

    log_queue = Queue(maxsize=num_threads * 2)
    threads = []

    # Start worker threads
    for _ in range(num_threads):
        t = threading.Thread(target=worker, args=(log_queue, db_connection))
        t.start()
        threads.append(t)

    # Enqueue log files
    for log_file in log_files:
        log_queue.put(log_file)

    # Block until all tasks are done
    log_queue.join()

    # Stop workers
    for _ in range(num_threads):
        log_queue.put(None)
    for t in threads:
        t.join()

if __name__ == '__main__':
    main('/path/to/log/directory')

