async function fetchWeatherData(cities, updateUIFunction) {
    const apiKey = 'YOUR_API_KEY'; // Replace with your API key
    const baseUrl = 'https://api.weatherapi.com/v1/current.json';
    const cache = new Map();
    const maxRetries = 3;
    const delayBetweenRetries = 1000; // in milliseconds

    async function fetchWithRetry(city, retries) {
        if (cache.has(city)) {
            return cache.get(city);
        }

        try {
            const response = await fetch(`${baseUrl}?key=${apiKey}&q=${city}`);
            if (!response.ok) throw new Error(`API error: ${response.status}`);

            const data = await response.json();
            cache.set(city, data); // Cache the result
            return data;
        } catch (error) {
            console.error(`Error fetching weather for ${city}:`, error);
            if (retries > 0) {
                await new Promise(res => setTimeout(res, delayBetweenRetries));
                return fetchWithRetry(city, retries - 1);
            }
            throw error; // Propagate the error after final retry
        }
    }

    async function processCities() {
        const results = await Promise.all(cities.map(city => 
            fetchWithRetry(city, maxRetries).catch(error => ({ city, error }))
        ));
        updateUIFunction(results);
    }

    processCities();
}

// Example usage:
function updateUI(weatherData) {
    weatherData.forEach(data => {
        if (data.error) {
            console.log(`Failed to fetch data for ${data.city}:`, data.error);
        } else {
            console.log(`${data.city} - Temperature: ${data.current.temp_c}°C`);
        }
    });
}

// Call the function with an array of city names
fetchWeatherData(['New York', 'London', 'Tokyo'], updateUI);
