#include <stdarg.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_THREADS 10

typedef struct {
    char* message;
} LogEntry;

void log_message(const char* level, const char* format, ...) {
    va_list args;
    char buffer[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    if (strcmp(level, "ERROR") == 0) {
        printf("[%s] ", level); // Error logs are prioritized
    } else if (strcmp(level, "DEBUG") == 0) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s][%s] ", buffer, level); // Timestamped debug logs
    }

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    printf("%s\n", buffer);
}

void* handle_request(void* arg) {
    // Simulate handling a request with logging
    LogEntry* entry = (LogEntry*)arg;
    log_message("DEBUG", "Handling request: %s", entry->message);

    // Add code for loading JavaScript files, database interactions, etc.

    log_message("ERROR", "Simulated error in processing");

    free(entry);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    while (thread_count < MAX_THREADS) {
        LogEntry* entry = malloc(sizeof(LogEntry));
        if (!entry) break;

        snprintf(entry->message, sizeof(char*) * 256, "Request #%d", thread_count + 1);

        if (pthread_create(&threads[thread_count], NULL, handle_request, entry)) {
            perror("Failed to create thread");
            free(entry);
        }

        thread_count++;
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
