#include <pthread.h>
#include <zlib.h> // For decompression, ensure zlib is installed
#include "third_party_logging_service.h" // Placeholder for actual logging library
#include "config_parser.h"
#include "file_processor.h"

#define MAX_THREADS 4

typedef struct {
    char *filename;
} FileTask;

// Global parser configuration
ParserConfig config;

void* process_file(void* arg) {
    FileTask task = *(FileTask*)arg;
    gzFile compressed_file = gzopen(task.filename, "rb");

    if (!compressed_file) {
        log_error("Failed to open file %s", task.filename);
        return NULL;
    }

    char buffer[4096];
    int ret;

    while ((ret = gzread(compressed_file, buffer, sizeof(buffer))) > 0) {
        // Process the data according to the parsing rules
        process_data(buffer, ret, &config);
    }

    if (ret < 0) {
        log_error("Error reading from file %s: %s", task.filename, gzerror(compressed_file, NULL));
    }

    gzclose(compressed_file);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s config_file [file1.gz file2.gz ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Load configuration from external file
    if (!load_parser_config(argv[1], &config)) {
        log_error("Failed to load parsing rules.");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    int num_files = argc - 2;
    FileTask tasks[num_files];

    for (int i = 0; i < num_files; ++i) {
        tasks[i].filename = argv[i + 2];
    }

    // Create worker threads
    for (int i = 0; i < num_files && i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, &tasks[i])) {
            log_error("Failed to create thread for file %s", tasks[i].filename);
        }
    }

    // Join threads
    for (int i = 0; i < num_files && i < MAX_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            log_error("Failed to join thread for file %s", tasks[i].filename);
        }
    }

    free_parser_config(&config); // Ensure resources are freed
    return EXIT_SUCCESS;
}
