<?php

session_start();

// Dependencies: You might need packages like GuzzleHTTP for asynchronous requests.
require 'vendor/autoload.php';

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;

class OAuth2Authenticator {
    private $client;
    private $rateLimiterClient; // Assuming a Rate Limiter client is integrated
    private $tokenStorageService; // External service to store tokens

    public function __construct($tokenStorageService, $rateLimiterClient) {
        $this->client = new Client();
        $this->tokenStorageService = $tokenStorageService;
        $this->rateLimiterClient = $rateLimiterClient;
    }

    private function getAuthUrl($provider) {
        switch ($provider) {
            case 'google':
                return 'https://accounts.google.com/o/oauth2/v2/auth';
            case 'facebook':
                return 'https://www.facebook.com/v10.0/dialog/oauth';
            case 'github':
                return 'https://github.com/login/oauth/authorize';
        }
    }

    public function initiateAuth($provider) {
        $authUrl = $this->getAuthUrl($provider);

        // Redirect user to auth provider
        header("Location: $authUrl");
        exit;
    }

    private function handleAsyncRequest($promise) {
        try {
            $response = $promise->wait();
            return json_decode($response->getBody(), true);
        } catch (RequestException $e) {
            if ($e->getCode() == 429) { // Rate limit exceeded
                throw new Exception('Rate limit exceeded. Please try again later.');
            }
            throw new Exception('Network error or invalid request.');
        }
    }

    public function completeAuth($provider, $code) {
        switch ($provider) {
            case 'google':
                $tokenUrl = 'https://oauth2.googleapis.com/token';
                break;
            case 'facebook':
                $tokenUrl = 'https://graph.facebook.com/v10.0/oauth/access_token';
                break;
            case 'github':
                $tokenUrl = 'https://github.com/login/oauth/access_token';
                break;
        }

        if ($this->rateLimiterClient->isRateLimited()) {
            throw new Exception('Too many requests. Please try again later.');
        }

        $promise = $this->client->postAsync($tokenUrl, [
            'form_params' => [
                'code' => $code,
                // Add other necessary parameters like client_id, client_secret
            ]
        ]);

        $response = $this->handleAsyncRequest($promise);

        if (isset($response['error'])) {
            throw new Exception('Invalid credentials provided.');
        }

        // Assuming tokenStorageService has a method to securely store tokens.
        $this->rateLimiterClient->incrementCounter();
        $this->tokenStorageService->storeToken(session_id(), $provider, $response['access_token']);

        $_SESSION[$provider . '_access_token'] = $response['access_token'];
    }

    public function authenticateUser($provider) {
        if (isset($_SESSION[$provider . '_access_token'])) {
            return true; // User is already authenticated
        }

        if (!isset($_GET['code'])) {
            $this->initiateAuth($provider);
        } else {
            try {
                $this->completeAuth($provider, $_GET['code']);
            } catch (Exception $e) {
                echo 'Authentication error: ' . htmlspecialchars($e->getMessage(), ENT_QUOTES, 'UTF-8');
            }
        }

        return isset($_SESSION[$provider . '_access_token']);
    }
}

// Example usage
$authenticator = new OAuth2Authenticator(new TokenStorageService(), new RateLimiterClient());
$authenticator->authenticateUser('google'); // Replace 'google' with the desired provider

```

