public class ReportGenerator {

    private final String directoryPath;
    private final Set<String> keywords;
    private final Pattern pattern;
    private final ExecutorService executorService;
    private final ScheduledExecutorService scheduler;
    private final Map<String, List<String>> cache = new ConcurrentHashMap<>();
    private static final Logger logger = Logger.getLogger(ReportGenerator.class.getName());

    public ReportGenerator(String directoryPath, Set<String> keywords) {
        this.directoryPath = directoryPath;
        this.keywords = keywords;
        this.pattern = Pattern.compile("(?i)" + String.join("|", keywords));
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public void generateReportAsync() {
        try {
            Files.walk(Paths.get(directoryPath))
                    .filter(Files::isRegularFile)
                    .forEach(file -> executorService.submit(() -> processFile(file)));

            // Schedule regular report generation
            scheduler.scheduleAtFixedRate(this::generateScheduledReports, 0, 1, TimeUnit.DAYS);
        } catch (IOException e) {
            logger.severe("Error accessing directory: " + e.getMessage());
        }
    }

    private void processFile(Path file) {
        try (BufferedReader reader = Files.newBufferedReader(file)) {
            String line;
            List<String> filteredLines = new ArrayList<>();

            while ((line = reader.readLine()) != null) {
                Matcher matcher = pattern.matcher(line);
                if (matcher.find()) {
                    filteredLines.add(line);
                }
            }

            synchronized (cache) {
                cache.put(file.toString(), filteredLines);
            }

            String reportContent = generateReport(filteredLines);
            sendReportToBrowser(reportContent);

        } catch (IOException e) {
            logger.severe("Error reading file " + file + ": " + e.getMessage());
        }
