using System;
using System.Collections.Generic;
using System.Threading;
using System.Xml.Linq;
using System.IO;

public class ConfigurationSettings
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }

    // Additional properties for fallback and logging can be added here.
}

public interface IConfigurationLoader
{
    ConfigurationSettings LoadConfiguration(string filePath);
}

public class XmlConfigurationLoader : IConfigurationLoader
{
    private readonly ILogger _logger;

    public XmlConfigurationLoader(ILogger logger)
    {
        _logger = logger;
    }

    public ConfigurationSettings LoadConfiguration(string filePath)
    {
        try
        {
            XDocument doc = XDocument.Load(filePath);
            var settings = new ConfigurationSettings();

            settings.TileSize = ParseInt(doc, "TileSize", 32); // default value
            settings.WorldWidth = ParseInt(doc, "WorldDimensions/Width", 1000);
            settings.WorldHeight = ParseInt(doc, "WorldDimensions/Height", 800);
            settings.CameraSpeed = ParseFloat(doc, "CameraSpeed", 1.0f);

            _logger.Log($"Configuration loaded from {filePath}");
            return settings;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error loading configuration from {filePath}");
            throw;
        }
    }

    private int ParseInt(XDocument doc, string path, int defaultValue)
    {
        var element = doc.Element(path);
        if (element == null || !int.TryParse(element.Value, out var result))
        {
            _logger.LogWarning($"Invalid or missing value for {path}. Using default: {defaultValue}");
            return defaultValue;
        }
        return result;
    }

    private float ParseFloat(XDocument doc, string path, float defaultValue)
    {
        var element = doc.Element(path);
        if (element == null || !float.TryParse(element.Value, out var result))
        {
            _logger.LogWarning($"Invalid or missing value for {path}. Using default: {defaultValue}");
            return defaultValue;
        }
        return result;
    }
}

public interface ILogger
{
    void Log(string message);
    void LogError(Exception ex, string message);
    void LogWarning(string message);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message) => Console.WriteLine($"[INFO] {message}");
    public void LogError(Exception ex, string message)
    {
        Console.WriteLine($"[ERROR] {message}: {ex.Message}");
    }
    public void LogWarning(string message) => Console.WriteLine($"[WARNING] {message}");
}

public class ConfigurationManager
{
    private readonly ILogger _logger;
    private readonly List<IConfigurationLoader> _loaders;
    private ConfigurationSettings _currentSettings;

    public ConfigurationManager(ILogger logger)
    {
        _logger = logger;
        _loaders = new List<IConfigurationLoader>();
        _currentSettings = new ConfigurationSettings();
        Thread.MemoryBarrier(); // Ensure visibility of initial settings
    }

    public void RegisterLoader(IConfigurationLoader loader) => _loaders.Add(loader);

    public ConfigurationSettings GetCurrentSettings()
    {
        lock (_loaders)
        {
            return (ConfigurationSettings)_currentSettings.Clone();
        }
    }

    public void LoadConfigurations(params string[] filePaths)
    {
        foreach (var path in filePaths)
        {
            foreach (var loader in _loaders)
            {
                var newSettings = loader.LoadConfiguration(path);

                // Merge settings, preferring non-default values from the latest configuration
                if (_currentSettings.TileSize == 32 && newSettings.TileSize != 32) _currentSettings.TileSize = newSettings.TileSize;
                if (_currentSettings.WorldWidth == 1000 && newSettings.WorldWidth != 1000) _currentSettings.WorldWidth = newSettings.WorldWidth;
                if (_currentSettings.WorldHeight == 800 && newSettings.WorldHeight != 800) _currentSettings.WorldHeight = newSettings.WorldHeight;
                if (Math.Abs(_currentSettings.CameraSpeed - 1.0f) > float.Epsilon && Math.Abs(newSettings.CameraSpeed - 1.0f) > float.Epsilon)
                    _currentSettings.CameraSpeed = newSettings.CameraSpeed;

                _logger.Log($"Configuration updated from {path}");
            }
        }
    }

    public void UpdateConfiguration(string filePath)
    {
        LoadConfigurations(filePath);
        // Notify systems about the configuration change if necessary
    }

    private class ConfigurationSettingsCloner : ICloneable
    {
        private readonly object _settings;

        public ConfigurationSettingsCloner(object settings)
        {
            _settings = settings;
