### C Program

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <curl/curl.h>

// Define a structure to hold stream data
typedef struct {
    char *data;
    size_t size;
} StreamData;

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Callback function for libcurl write data
size_t write_callback(void *buffer, size_t size, size_t nmemb, void *userp) {
    StreamData *data = (StreamData *)userp;
    char *ptr = realloc(data->data, data->size + size * nmemb);
    if (!ptr) handle_error("Memory allocation failed");
    memcpy(ptr + data->size, buffer, size * nmemb);
    data->size += size * nmemb;
    data->data = ptr;
    return size * nmemb;
}

// Function to read from a network stream
void* read_stream(void *url) {
    CURL *curl;
    CURLcode res;
    StreamData data = {NULL, 0};

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, (char *)url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            handle_error(curl_easy_strerror(res));

        // Process data here
        printf("Received %zu bytes\n", data.size);

        free(data.data);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return NULL;
}

// Main function to manage multiple streams
int main(int argc, char *argv[]) {
    pthread_t threads[10];
    const char *urls[] = {"http://example.com/stream1", "http://example.com/stream2"};
    int num_urls = sizeof(urls) / sizeof(urls[0]);

    for (int i = 0; i < num_urls; ++i) {
        if (pthread_create(&threads[i], NULL, read_stream, (void *)urls[i])) {
            handle_error("Failed to create thread");
        }
    }

    for (int i = 0; i < num_urls; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
