```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class AesDecryptor
{
    private const int KeySize = 256; // AES-256

    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, string mode)
    {
        if (string.Equals(mode, "CBC", StringComparison.OrdinalIgnoreCase))
            return DecryptCbc(ciphertext, key, iv);
        else if (string.Equals(mode, "GCM", StringComparison.OrdinalIgnoreCase))
            return DecryptGcm(ciphertext, key, iv);
        else
            throw new ArgumentException("Unsupported mode. Use 'CBC' or 'GCM'.");
    }

    private byte[] DecryptCbc(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.KeySize = KeySize;
            aes.BlockSize = 128; // AES block size
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            aes.Key = key;
            aes.IV = iv;

            using (ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            {
                return PerformDecryption(ciphertext, decryptor);
            }
        }
    }

    private byte[] DecryptGcm(byte[] ciphertextWithTag, byte[] key, byte[] iv)
    {
        if (ciphertextWithTag.Length < 16) // GCM tag size is 128 bits
            throw new ArgumentException("Ciphertext with GCM must be at least 16 bytes long for the tag.");

        using (AesGcm aesGcm = new AesGcm(key))
        {
            byte[] ciphertext = new byte[ciphertextWithTag.Length - 16];
            Array.Copy(ciphertextWithTag, ciphertext, ciphertext.Length);

            byte[] tag = new byte[16];
            Array.Copy(ciphertextWithTag, ciphertext.Length, tag, 0, tag.Length);

            byte[] plaintext = new byte[ciphertext.Length];
            aesGcm.Decrypt(iv, ciphertext, tag, plaintext);

            return plaintext;
        }
    }

    private byte[] PerformDecryption(byte[] data, ICryptoTransform decryptor)
    {
        using (MemoryStream msDecrypt = new MemoryStream())
        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
        {
            csDecrypt.Write(data, 0, data.Length);
            csDecrypt.FlushFinalBlock();
            return msDecrypt.ToArray();
        }
    }

    public static byte[] GenerateSecureRandomBytes(int length)
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] randomBytes = new byte[length];
            rng.GetBytes(randomBytes);
            return randomBytes;
        }
    }
}
```

This class `AesDecryptor` supports AES-CBC and AES-GCM decryption modes. It includes methods for decrypting ciphertexts using either mode, handles padding for CBC, and manages the GCM tag properly. The class also provides a method to generate secure random bytes for key or IV generation if needed.

```java
import java.io.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.commons.configuration2.Configuration;
import org.apache.commons.configuration2.builder.fluent.Configurations;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ObjectDeserializer {

    private static final Logger logger = LoggerFactory.getLogger(ObjectDeserializer.class);
    private static final Map<String, String> classNameCache = new ConcurrentHashMap<>();

    // Load configuration from an external database or file
    private Configuration loadConfiguration() {
        Configurations configs = new Configurations();
        try {
            return configs.properties("deserializationConfig.properties");
        } catch (Exception e) {
            throw new RuntimeException("Failed to load configuration: " + e.getMessage(), e);
        }
    }

    public static <T> T deserialize(byte[] data) {
        if (data == null || data.length == 0) {
            throw new IllegalArgumentException("Data cannot be null or empty");
        }

        String className;
        try (ObjectInputStream ois = createObjectInputStream(data)) {
            Class<?> clazz = getDeserializationClass(ois);
            Object deserializedObject = ois.readObject();

            if (!(deserializedObject instanceof T)) {
                throw new IllegalArgumentException("Deserialized object is not of expected type");
            }

            return (T) deserializedObject;
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Deserialization failed: " + e.getMessage(), e);
            throw new RuntimeException("Failed to deserialize data", e);
        }
    }

    private static ObjectInputStream createObjectInputStream(byte[] data)
            throws IOException, InvalidClassException, StreamCorruptedException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        try (ObjectInputStream ois = new ObjectInputStream(bais)) {
            // Handle potential backward compatibility
            ois.acceptValidation();
            return ois;
        }
    }

    private static Class<?> getDeserializationClass(ObjectInputStream ois) throws IOException, ClassNotFoundException {
        String className = fetchClassName(ois);

        if (className == null || className.isEmpty()) {
            throw new RuntimeException("No class name provided for deserialization");
        }

        try {
            return Class.forName(className);
        } catch (ClassNotFoundException e) {
            logger.error("Class not found: " + className, e);
            throw new RuntimeException("Deserialized object's class could not be found", e);
        }
    }

    private static String fetchClassName(ObjectInputStream ois) throws IOException, ClassNotFoundException {
        // Attempt to retrieve class name from stream if available
        ObjectStreamClass osc = ois.readObjectOverride();
        if (osc != null && osc.getName() != null) {
            return classNameCache.computeIfAbsent(osc.getName(), k -> osc.getName());
        }

        // Fallback to external configuration
        Configuration config = loadConfiguration();
        String classNameFromConfig = config.getString("className");

        if (classNameFromConfig == null || classNameFromConfig.isEmpty()) {
            throw new RuntimeException("Class name not found in configuration");
        }

        return classNameCache.computeIfAbsent(classNameFromConfig, k -> classNameFromConfig);
    }

    // Example unit test using JUnit
    public static void main(String[] args) {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {

            // Mock serialization for testing
            String mockData = "test data";
            oos.writeObject(mockData);
            oos.flush();

            byte[] serializedData = baos.toByteArray();
            String deserializedData = deserialize(String.class, serializedData);

            System.out.println("Deserialized Data: " + deserializedData);
        } catch (Exception e) {
            logger.error("Test failed", e);
        }
    }

}
```

