- **Caching Strategy**: Caches class names in a concurrent map for performance improvement.
- **Error Handling**: Detailed logging and exception handling with meaningful error messages.
- **Configuration Loading**: Loads configuration from an external file, allowing dynamic updates.
- **Concurrency Considerations**: Uses thread-safe data structures to handle multi-threaded environments.

```c
// C Program for Processing Web Server Log Files

#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
import <string.h>

typedef struct {
    char timestamp[50];
    char clientIP[20];
    char requestMethod[10];
    char url[100];
    char httpVersion[10];
    int responseStatus;
    int responseSize;
} LogEntry;

LogEntry *parseLogLine(const char *line) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (sscanf(line, "[%49[^]]] [%19[^]]] %9s %99s %9s %d %d",
               entry->timestamp, entry->clientIP,
               entry->requestMethod, entry->url,
               entry->httpVersion, &entry->responseStatus, &entry->responseSize) != 7) {
        free(entry);
        return NULL;
    }
    return entry;
}

void processLogFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[256];
    LogEntry *prevEntry1 = NULL, *prevEntry2 = NULL;

    while (fgets(line, sizeof(line), file)) {
        LogEntry *entry = parseLogLine(line);
        if (!entry) continue;

        printf("Timestamp: %s\n", entry->timestamp);
        printf("Client IP: %s\n", entry->clientIP);
        printf("Request Method: %s\n", entry->requestMethod);
        printf("URL: %s\n", entry->url);
        printf("HTTP Version: %s\n", entry->httpVersion);
        printf("Response Status: %d\n", entry->responseStatus);
        printf("Response Size: %d\n", entry->responseSize);

        if (prevEntry1) {
            int avg = (prevEntry1->responseSize + prevEntry2->responseSize) / 2;
            printf("Average Response Size of last two entries: %d\n", avg);
        }

        free(prevEntry2);
        prevEntry2 = prevEntry1;
        prevEntry1 = entry;

        // Simulate non-blocking behavior with threads
        pthread_t thread;
        if (pthread_create(&thread, NULL, NULL, NULL) != 0) {
            perror("Failed to create thread");
        }
    }

    free(prevEntry1);
    free(prevEntry2);
    fclose(file);
}

int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; ++i) {
        processLogFile(argv[i]);
    }
    return 0;
}
