// AngularJS JavaScript Function for Dialog Field Refresh

angular.module('myApp').controller('dialogController', ['$scope', function($scope) {

    $scope.refreshFields = function(dialogFields, namesToRefresh) {
        dialogFields.forEach(function(field) {
            if (namesToRefresh.includes(field.name)) {
                try {
                    const result = sendMessageToParentWindow(field.name);
                    if (result.success) {
                        field.value = result.data;
                    }
                } catch (error) {
                    console.error("Error refreshing field:", error);
                    // Implement logic to restart from the last processed line
                }
            }
        });
    };

    function sendMessageToParentWindow(fieldName) {
        return new Promise((resolve, reject) => {
            const message = { type: 'refreshField', fieldName };
            window.parent.postMessage(message, '*');

            window.addEventListener('message', (event) => {
                if (event.data.type === 'response' && event.data.fieldName === fieldName) {
                    window.removeEventListener('message', arguments.callee);
                    resolve(event.data.response ? { success: true, data: event.data.value } : { success: false });
                }
            });

            setTimeout(() => reject(new Error("Timeout waiting for response")), 5000);
        });
    }

}]);
