    }

    status = TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    if (status) {
        printf("Samples per pixel: %u\n", samples_per_pixel);
    } else {
        log_error("Failed to get samples per pixel.");
    }

    // Additional error checking and logging could be added here

