int process_file(FileTask* task, int attempt) {
    if (attempt > RETRY_LIMIT) {
        log_error("Max retry limit reached.");
        return -1;
    }

    FILE* compressed_file = fopen(task->file_path, "rb");
    if (!compressed_file) {
        log_error("Failed to open file.");
        return -1;
    }

    // Custom decompression logic
    DecompressedData data;
    int status = custom_decompress(compressed_file, &data);
    fclose(compressed_file);

    if (status != 0) {
        sleep(1 << attempt); // Exponential backoff
        log_error("Decompression failed, retrying...");
        return process_file(task, attempt + 1);
    }

    // Parsing logic using the dynamically loaded rules from config
    ParsedData parsed_data;
    status = parse_data(&data, &parsed_data, &task->config);

    if (status != 0) {
        log_error("Parsing failed.");
        return -1;
    }

    FILE* output_file = fopen(task->output_file, "wb");
    if (!output_file) {
        log_error("Failed to create output file.");
        return -1;
    }

    write_parsed_data(output_file, &parsed_data);
    fclose(output_file);

    log_info("File processed successfully.");

    free(data.buffer);
    return 0;
}

void* worker_thread(void* arg) {
    FileTask* task = (FileTask*)arg;

    int status = process_file(task, 1);
    if (status != 0) {
        // Handle persistent failure
    }

    pthread_exit(NULL);
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file> <output_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ParsingConfig config = load_config(argv[1]);

    pthread_t threads[MAX_THREADS];
    FileTask tasks[MAX_THREADS];

    // Load file paths (omitted for brevity)
    int num_files = load_task_list(tasks, MAX_THREADS);

    for (int i = 0; i < num_files && i < MAX_THREADS; ++i) {
        snprintf(tasks[i].output_file, sizeof(tasks[i].output_file), "%s/processed_%d.bin", argv[2], i);
        pthread_create(&threads[i], NULL, worker_thread, &tasks[i]);
    }

    for (int i = 0; i < num_files && i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}

