#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1000000
#define RANGE_START 1
#define RANGE_END 10000

typedef struct {
    int key;
    long offset_value;
} Record;

Record *records;
int initialized = 0;
pthread_mutex_t lock;

void initialize_records() {
    pthread_mutex_lock(&lock);

    if (initialized) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Simulate reading from configuration file
    char config_file[] = "config.txt";
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Could not open configuration file");
        exit(EXIT_FAILURE);
    }

    int random_value;
    if (fscanf(file, "%d", &random_value) != 1) {
        fprintf(stderr, "Failed to read initial value from config\n");
        fclose(file);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    records = malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        fclose(file);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i].key = i;
        records[i].offset_value = random_value + i % (RANGE_END - RANGE_START + 1) + RANGE_START;
    }

    initialized = 1;

    fclose(file);
    pthread_mutex_unlock(&lock);

    printf("Records initialized with initial value: %d\n", random_value);
}

