public class PokemonWeaknesses {

    private static final Logger LOGGER = Logger.getLogger(PokemonWeaknesses.class.getName());
    private static Map<String, String[]> weaknessCache = new ConcurrentHashMap<>();

    // Mock external API call to get weaknesses for a given type
    private static String[] fetchWeaknessesFromApi(String type) {
        try {
            // Simulate API response with dummy data
            switch (type.toLowerCase()) {
                case "fire":
                    return new String[]{"water", "rock"};
                case "water":
                    return new String[]{"electric", "grass"};
                case "grass":
                    return new String[]{"fire", "ice"};
                default:
                    return new String[]{};
            }
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Failed to fetch weaknesses for type: " + type, e);
            return new String[]{}; // Return empty if there's an error
        }
    }

    public static String getWeaknesses(Pokemon pokemon) {
        Set<String> combinedWeaknesses = new HashSet<>();

        for (String type : pokemon.getTypes()) {
            try {
                String[] weaknesses;

                // Check cache first
                if (weaknessCache.containsKey(type)) {
                    weaknesses = weaknessCache.get(type);
                } else {
                    weaknesses = fetchWeaknessesFromApi(type);
                    weaknessCache.put(type, weaknesses); // Cache the result
                }

                Collections.addAll(combinedWeaknesses, weaknesses);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error processing type: " + type, e);
            }
        }

        return String.join(", ", combinedWeaknesses);
    }

    public static void main(String[] args) {
        // Example usage
        Pokemon pikachu = new Pokemon("Pikachu", Arrays.asList("electric"));
        System.out.println(getWeaknesses(pikachu));  // Output: "ground"

        Pokemon charizard = new Pokemon("Charizard", Arrays.asList("fire", "flying"));
        System.out.println(getWeaknesses(charizard));  // Output: "rock, water, ice"
    }
}

