ParsingRule* load_parsing_rules(const char *json_config_path, int *rule_count) {
    FILE *file = fopen(json_config_path, "r");
    if (!file) {
        perror("Failed to open JSON config file");
        return NULL;
    }

    struct json_object *parsed_json;
    struct json_object *rules_array;

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *json_string = malloc(length + 1);
    fread(json_string, 1, length, file);
    fclose(file);

    parsed_json = json_tokener_parse(json_string);
    free(json_string);

    if (!parsed_json || !json_object_object_get_ex(parsed_json, "rules", &rules_array)) {
        fprintf(stderr, "Invalid JSON configuration\n");
        return NULL;
    }

    size_t rule_size = json_object_array_length(rules_array);
    ParsingRule *rules = malloc(sizeof(ParsingRule) * rule_size);

    for (size_t i = 0; i < rule_size; ++i) {
        struct json_object *rule_obj = json_object_array_get_idx(rules_array, i);
        const char *name;
        if (!json_object_object_get_ex(rule_obj, "name", &name)) {
            fprintf(stderr, "Invalid parsing rule format\n");
            free(rules);
            return NULL;
        }
        strcpy(rules[i].rule_name, name);

        // Load parse_function based on the name or some mapping
        rules[i].parse_function = NULL;  // Assign appropriate function pointers
    }

    *rule_count = (int)rule_size;
    return rules;
}

