void process_data(void *input_handle, void *output_handle, ParsingRule *rules, int rule_count) {
    const size_t BUFFER_SIZE = 1024 * 1024; // 1 MB buffer size for processing
    char *buffer = malloc(BUFFER_SIZE);

    while (size_t bytes_read = read_from_cloud(input_handle, buffer, BUFFER_SIZE)) {
        for (int i = 0; i < rule_count; ++i) {
            if (rules[i].parse_function) {
                rules[i].parse_function(buffer, bytes_read, NULL);
            }
        }

        // Write the processed data to output
        write_to_cloud(output_handle, buffer, bytes_read);
    }

    free(buffer);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_path> <output_path> <config_json>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_path = argv[1];
    const char *output_path = argv[2];
    const char *json_config_path = argv[3];

    void *input_handle = authenticate_and_open_remote_file(input_path);
    if (!input_handle) {
        fprintf(stderr, "Failed to open input file\n");
        return EXIT_FAILURE;
    }

    void *output_handle = authenticate_and_create_local_file(output_path);
    if (!output_handle) {
        close_remote_file(input_handle);
        fprintf(stderr, "Failed to create output file\n");
        return EXIT_FAILURE;
    }

    int rule_count = 0;
    ParsingRule *rules = load_parsing_rules(json_config_path, &rule_count);
    if (!rules) {
        close_local_file(output_handle);
        close_remote_file(input_handle);
        fprintf(stderr, "Failed to load parsing rules\n");
        return EXIT_FAILURE;
    }

    process_data(input_handle, output_handle, rules, rule_count);

    free(rules);
    close_local_file(output_handle);
    close_remote_file(input_handle);

    return EXIT_SUCCESS;
}
