    system(command);

    logMessage("Conversion completed.");
    return NULL;
}

// Main function to handle file conversion
void convertFiles(const FileInfo* files, int count) {
    pthread_t threads[MAX_THREADS];
    int threadCount = 0;

    for (int i = 0; i < count; ++i) {
        if (threadCount >= maxConcurrentThreads) {
            // Wait for any thread to finish
            pthread_mutex_lock(&logMutex);
            pthread_cond_wait(NULL, &logMutex);
            pthread_mutex_unlock(&logMutex);
        }

        FileInfo* fileInfo = malloc(sizeof(FileInfo));
        memcpy(fileInfo, &files[i], sizeof(FileInfo));

        if (pthread_create(&threads[threadCount++], NULL, processFile, fileInfo) != 0) {
            logMessage("Failed to create thread.");
            free(fileInfo);
        }
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }
}

