#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Thread-safe structure for storing environment variables
typedef struct {
    char *key;
    char *value;
} EnvVar;

typedef struct {
    pthread_rwlock_t lock;
    EnvVar *env_vars;
    size_t count;
} EnvManager;

EnvManager env_manager = {PTHREAD_RWLOCK_INITIALIZER, NULL, 0};

// Function to initialize environment manager
void init_env_manager() {
    pthread_rwlock_init(&env_manager.lock, NULL);
}

// Function to load and parse .env files
void load_env_files(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Split key-value pair
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "");

        if (key && value) {
            pthread_rwlock_wrlock(&env_manager.lock);

            EnvVar new_var = {strdup(key), strdup(value)};
            env_manager.env_vars = realloc(env_manager.env_vars,
                                           (env_manager.count + 1) * sizeof(EnvVar));
            env_manager.env_vars[env_manager.count++] = new_var;

            pthread_rwlock_unlock(&env_manager.lock);
        }
    }

    fclose(file);
}

// Function to get environment variable
char* get_env_variable(const char *key) {
    pthread_rwlock_rdlock(&env_manager.lock);

    for (size_t i = 0; i < env_manager.count; ++i) {
        if (strcmp(env_manager.env_vars[i].key, key) == 0) {
            char *value = strdup(env_manager.env_vars[i].value);
            pthread_rwlock_unlock(&env_manager.lock);
            return value;
        }
    }

    pthread_rwlock_unlock(&env_manager.lock);
    return NULL; // Return NULL if variable not found
}

