```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <unistd.h>
#include <sys/stat.h>

#ifdef _WIN32
#include <windows.h>
#define PATH_SEPARATOR '\\'
#else
#define PATH_SEPARATOR '/'
#endif

static char *cwd_cache = NULL;

// Function to get the current working directory, with caching.
char* get_current_working_directory() {
    if (cwd_cache) return cwd_cache;

    size_t path_size = PATH_MAX;
    char *path = malloc(path_size);
    if (!path) return NULL;

    if (getcwd(path, path_size) == NULL) {
        free(path);
        return NULL;
    }

    // Cache the result.
    cwd_cache = strdup(path);
    free(path);

    return cwd_cache;
}

// Function to replace environment variables in a path with their actual values.
char* expand_env_vars(const char *path) {
    if (strchr(path, '~') == NULL) return strdup(path);

    size_t len = strlen(path);
    char *expanded_path = malloc(len + 1);
    if (!expanded_path) return NULL;

    const char *home_start = getenv("HOME");
    if (!home_start) home_start = getpwuid(getuid())->pw_dir;

    size_t home_len = strlen(home_start);

    char *src = (char *)path, *dst = expanded_path;
    while (*src) {
        if (*src == '~') {
            if (*(src + 1) == '/' || *(src + 1) == '\0') {
                strncpy(dst, home_start, home_len);
                dst += home_len;
                src++;
            } else {
                *dst++ = *src++;
            }
        } else {
            *dst++ = *src++;
        }
    }

    *dst = '\0';
    return expanded_path;
}

// Function to resolve symbolic links in a path.
char* resolve_symlinks(const char *path) {
    struct stat st;
    if (lstat(path, &st) != 0 || S_ISLNK(st.st_mode)) {
        char resolved_path[PATH_MAX];
        ssize_t len = readlink(path, resolved_path, sizeof(resolved_path) - 1);
        if (len != -1) {
            resolved_path[len] = '\0';
            return strdup(resolved_path);
        }
    }
    return strdup(path);
}

// Function to append a directory to the path.
char* append_directory(const char *base, const char *directory) {
    size_t base_len = strlen(base);
    size_t dir_len = strlen(directory);

    if (base[base_len - 1] != PATH_SEPARATOR) {
        base_len++;
    }

    char *full_path = malloc(base_len + dir_len + 1);
    if (!full_path) return NULL;

    strcpy(full_path, base);
    strcat(full_path, directory);

    return full_path;
}

char* validate_and_construct_full_path(const char *file_path, int max_buffer_size, bool is_absolute, const char *custom_cwd, char *error_message) {
    // Check path length
    if (strlen(file_path) >= max_buffer_size) {
        snprintf(error_message, sizeof(error_message), "Path exceeds maximum buffer size.");
        return NULL;
    }

    // Expand environment variables like ~ to home directory.
    char *expanded_path = expand_env_vars(file_path);
    if (!expanded_path) {
        snprintf(error_message, sizeof(error_message), "Failed to expand environment variables.");
        return NULL;
    }

    // Resolve symbolic links
    char *resolved_path = resolve_symlinks(expanded_path);
    free(expanded_path);
    if (!resolved_path) {
        snprintf(error_message, sizeof(error_message), "Failed to resolve symbolic links.");
        return NULL;
    }

    // Check path validity (POSIX and Windows)
    struct stat st;
    if (stat(resolved_path, &st) != 0) {
        free(resolved_path);
        snprintf(error_message, sizeof(error_message), "Invalid file path format.");
        return NULL;
    }

    // Determine current working directory
    char *working_directory = custom_cwd ? strdup(custom_cwd) : get_current_working_directory();
    if (!working_directory && !custom_cwd) {
        free(resolved_path);
        snprintf(error_message, sizeof(error_message), "Failed to determine the current working directory.");
        return NULL;
    }

    // If path is not absolute and requires appending the current working directory
    char *full_path = resolved_path;
    if (!is_absolute && !strchr(resolved_path, PATH_SEPARATOR)) {
        full_path = append_directory(working_directory, resolved_path);
        free(working_directory);
        if (!full_path) {
            snprintf(error_message, sizeof(error_message), "Failed to append directory.");
            return NULL;
        }
    } else {
        free(working_directory);
    }

    // Clean up
    free(resolved_path);

    return full_path;
}
```

```c
#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <errno.h>

// Structure to hold semaphore information and tracking data
typedef struct {
    sem_t *sem;
    int acquired_count;
    int released_count;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int initial_value) {
    // Create a structure for managing the semaphore
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed for SemaphoreManager\n");
        return NULL;
    }

    manager->sem = sem_open("my_semaphore", O_CREAT | O_EXCL, 0644, initial_value);
    if (manager->sem == SEM_FAILED) {
        perror("Semaphore creation failed");

        // Handle open error if already exists
        manager->sem = sem_open("my_semaphore", 0);
        if (manager->sem == SEM_FAILED) {
            fprintf(stderr, "Error opening existing semaphore: %s\n", strerror(errno));
            free(manager);
            return NULL;
        }
    }

    manager->acquired_count = 0;
    manager->released_count = 0;

    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (manager) {
        sem_close(manager->sem);

        // Unlink the semaphore to delete it
        if (sem_unlink("my_semaphore") != 0) {
            perror("Semaphore unlink failed");
        }

        free(manager);
    }
}

void acquire_semaphore(SemaphoreManager *manager) {
    if (!manager || !manager->sem) return;

    int result = sem_wait(manager->sem);
    if (result == -1 && errno != EINTR) { // Allow interruption by signals
        perror("Semaphore acquisition failed");
    } else {
        manager->acquired_count++;
    }
}

void release_semaphore(SemaphoreManager *manager) {
    if (!manager || !manager->sem) return;

    int result = sem_post(manager->sem);
    if (result == -1) {
        perror("Semaphore release failed");
    } else {
        manager->released_count++;
    }
}

// Function to get semaphore acquisition/release count for monitoring
void get_semaphore_stats(SemaphoreManager *manager, int *acquired, int *released) {
    if (!manager || !acquired || !released) return;

    *acquired = manager->acquired_count;
    *released = manager->released_count;
}

// Example of how to use the semaphore in a threaded environment
void* thread_function(void *arg) {
    SemaphoreManager *manager = (SemaphoreManager *)arg;

    for (int i = 0; i < 5; ++i) {
        acquire_semaphore(manager);
        // Critical section: access shared resource here
        printf("Thread %ld accessing shared resource\n", pthread_self());
        release_semaphore(manager);
    }

    return NULL;
}

// Example main function demonstrating usage
int main() {
    SemaphoreManager *manager = create_semaphore_manager(1);
    if (!manager) {
        fprintf(stderr, "Failed to create semaphore manager\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, thread_function, (void *)manager);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    int acquired, released;
    get_semaphore_stats(manager, &acquired, &released);

    printf("Semaphore was acquired %d times and released %d times\n", acquired, released);

    destroy_semaphore_manager(manager);
    return EXIT_SUCCESS;
}
```

### Documentation

- **create_semaphore_manager(int initial_value)**: Creates a semaphore manager with an initial value. Handles errors in creation or opening an existing semaphore.

- **destroy_semaphore_manager(SemaphoreManager *manager)**: Destroys the semaphore, closing and unlinking it from the system.

- **acquire_semaphore(SemaphoreManager *manager)**: Acquires the semaphore if available, increments the acquired count.

- **release_semaphore(SemaphoreManager *manager)**: Releases the semaphore, increments the released count. Handles any errors gracefully.

- **get_semaphore_stats(SemaphoreManager *manager, int *acquired, int *released)**: Retrieves acquisition and release statistics for monitoring.

This code manages a semaphore efficiently with error handling, tracking operations, and ensures thread safety using POSIX semaphores, suitable for high concurrency scenarios.

