using System;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class PageElementService
{
    private readonly string _connectionString;
    private readonly IMemoryCache _cache;
    private readonly ILogger<PageElementService> _logger;

    public PageElementService(string connectionString, IMemoryCache cache, ILogger<PageElementService> logger)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<ResponseMessage> UpdateElementAsync(Guid pageSectionId, Guid elementId, string htmlContent, User user)
    {
        if (!ValidateIds(pageSectionId, elementId))
        {
            return ResponseMessage.Fail("Invalid IDs provided.");
        }

        if (!await HasPermissionAsync(user, pageSectionId, elementId))
        {
            _logger.LogWarning($"User {user.Id} attempted unauthorized update on Element {elementId}");
            return ResponseMessage.Fail("User does not have permission to update this element.");
        }

        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                var transaction = await connection.BeginTransactionAsync();
                try
                {
                    // Check current version for conflict resolution
                    var currentVersion = await GetElementVersionAsync(connection, transaction, elementId);

                    if (!ValidateUpdate(htmlContent, currentVersion))
                    {
                        _logger.LogInformation($"Conflict detected on Element {elementId} by User {user.Id}");
                        return ResolveConflict(currentVersion, htmlContent);
                    }

                    // Update the element
                    var success = await UpdateElementAsync(connection, transaction, elementId, htmlContent, currentVersion);

                    if (success)
                    {
                        transaction.Commit();
                        _logger.LogInformation($"User {user.Id} successfully updated Element {elementId}");

                        // Invalidate cache to ensure freshness
                        _cache.Remove(elementId.ToString());

                        return ResponseMessage.Success("Page should be refreshed.");
                    }
                }
                catch (SqlException ex)
                {
                    _logger.LogError(ex, "SQL error occurred during the update operation.");
                    transaction?.Rollback();
                    throw;
                }
            }
        }
        catch (Exception ex) when (ex is SqlException || ex is InvalidOperationException)
        {
            _logger.LogError(ex, "An error occurred while updating the element. Transaction failed.");
            return ResponseMessage.Fail("Update failed due to an internal error.");
        }

        return ResponseMessage.Fail("Unexpected failure during update operation.");
    }

    private bool ValidateIds(Guid pageSectionId, Guid elementId) => 
        pageSectionId != Guid.Empty && elementId != Guid.Empty;

