Here's an implementation of the `TransactionReducer` class in JavaScript:

```javascript
class TransactionReducer {
  constructor(apiClient, workerPoolSize = 5) {
    this.apiClient = apiClient;
    this.workerPoolSize = Math.min(workerPoolSize, 100);
    this.queue = [];
    this.activeWorkers = 0;
  }

  async fetchTransactionDetails(transactionId) {
    let attempts = 0;
    const maxAttempts = 5;

    while (attempts < maxAttempts) {
      try {
        return await this.apiClient.getTransaction(transactionId);
      } catch (error) {
        if (this.isRetryableError(error)) {
          attempts++;
          await this.exponentialBackoff(attempts);
        } else {
          throw error;
        }
      }
    }

    throw new Error(`Failed to fetch transaction details for ID: ${transactionId}`);
  }

  isRetryableError(error) {
    return ['NetworkError', 'RateLimitExceeded', 'Timeout'].includes(error.type);
  }

  exponentialBackoff(attempt) {
    const delay = Math.pow(2, attempt) * 100;
    return new Promise(resolve => setTimeout(resolve, delay));
  }

  async processTransactions(transactionIds) {
    this.queue = transactionIds;

    while (this.queue.length > 0 && this.activeWorkers < this.workerPoolSize) {
      const transactionId = this.queue.shift();
      this.activeWorkers++;
      fetchTransactionDetails(transactionId).then(
        record => this.handleRecord(record),
        error => this.handleError(error)
      ).finally(() => {
        this.activeWorkers--;
        if (this.queue.length > 0) {
          process.nextTick(this.processTransactions.bind(this));
        }
      });
    }

    console.log('Processing complete.');
  }

  handleRecord(record) {
    // Implement weighted average calculation and store in record
    console.log(`Processed record: ${record.id}`);
  }

  handleError(error) {
    console.error(`Error processing transaction: ${error.message}`);
  }
}

// Simulated API client
class ApiClient {
  async getTransaction(transactionId) {
    // Simulate network call
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (Math.random() < 0.8) { // Simulate success rate
          resolve({ id: transactionId, data: 'Sample Data' });
        } else {
          reject(new Error('NetworkError'));
        }
      }, Math.random() * 100);
    });
  }
}

// Usage
const apiClient = new ApiClient();
const reducer = new TransactionReducer(apiClient, 10);
reducer.processTransactions([1, 2, 3, 4, 5]);
