<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp) {
    try {
        // Database connection setup (replace with actual connection parameters)
        $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Prepare the SQL statement
        $stmt = $pdo->prepare("
            UPDATE clinics 
            SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() 
            WHERE id = :id
        ");

        // Bind parameters
        $stmt->bindParam(':status', $newStatus);
        $stmt->bindParam(':ip', $lastModifiedIp);
        $stmt->bindParam(':id', $clinicId);

        // Execute the statement
        if ($stmt->execute()) {
            echo "Clinic status updated successfully.\n";
        } else {
            throw new Exception("Failed to update clinic status.");
        }
    } catch (PDOException $e) {
        error_log("Database error: " . $e->getMessage());
        echo "Error updating clinic status: " . $e->getMessage() . "\n";
    } catch (Exception $e) {
        error_log("General error: " . $e->getMessage());
        echo "Error: " . $e->getMessage() . "\n";
    }
}

