public class PaymentProcessor {

    private static final String KEY_ALIAS = "my-key-alias";
    private static final long TOKEN_EXPIRATION_TIME_MS = 3600000; // 1 hour
    private static final int TIMEOUT_MILLIS = 5000;

    public CompletableFuture<String> generateAndProcessJWT(String credentials, boolean async) {
        try {
            validateCredentials(credentials);

            SecretKey privateKey = retrievePrivateKeyFromKMS(KEY_ALIAS);

            JSONObject userPayload = new JSONObject();
            userPayload.put("username", "exampleUser");
            userPayload.put("roles", new String[]{"admin"});
            userPayload.put("permissions", new String[]{"transaction:process"});

            String jwtToken;

            if (async) {
                jwtToken = CompletableFuture.supplyAsync(() -> generateJWT(userPayload, privateKey))
                        .get(TIMEOUT_MILLIS);
            } else {
                jwtToken = generateJWT(userPayload, privateKey);
            }

            handlePaymentMethod(jwtToken);

            logTransaction("JWT generated and processed", credentials);

            return CompletableFuture.completedFuture(jwtToken);
        } catch (Exception e) {
            handleError(e);
            return CompletableFuture.failedFuture(e);
        }
    }

