### Java: `fileUploaderService`

```java
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import java.util.logging.*;

public class CloudStorageUploader {

    private static final Logger LOGGER = Logger.getLogger(CloudStorageUploader.class.getName());
    private static final int CHUNK_SIZE = 1024 * 1024; // 1MB

    public enum CloudService {
        S3, AZURE_BLOB_STORAGE, GOOGLE_CLOUD_STORAGE
    }

    public void fileUploaderService(String filePath, String bucketName, String directoryPath,
                                    CloudService cloudService) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newCachedThreadPool();
        File file = new File(filePath);
        long fileSize = file.length();

        // Validate metadata
        if (!validateMetadata(file)) {
            LOGGER.severe("File validation failed");
            return;
        }

        String hash = calculateSHA256Hash(file);

        // Check if the file already exists using the cloud service API
        boolean exists = checkIfExistsInCloud(cloudService, bucketName, directoryPath, hash);
        if (exists) {
            LOGGER.info("File already exists in cloud storage");
            return;
        }

        // Upload the file in chunks
        try (InputStream inputStream = new FileInputStream(file)) {
            byte[] buffer = new byte[CHUNK_SIZE];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                executor.submit(() -> uploadChunk(cloudService, bucketName, directoryPath, buffer, 0, bytesRead));
            }
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error during file upload", e);
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException ex) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private boolean validateMetadata(File file) {
        // Implement validation logic for size and content type
        return true;
    }

    private String calculateSHA256Hash(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream fis = new FileInputStream(file)) {
            byte[] byteArray = new byte[1024];
            int bytesCount;
            while ((bytesCount = fis.read(byteArray)) != -1) {
                digest.update(byteArray, 0, bytesCount);
            }
        }
        return bytesToHex(digest.digest());
    }

    private boolean checkIfExistsInCloud(CloudService cloudService, String bucketName,
                                         String directoryPath, String hash) {
        // Implement logic to check file existence in the specified cloud service
        return false;
    }

    private void uploadChunk(CloudService cloudService, String bucketName, String directoryPath,
                             byte[] data, int offset, int length) {
        // Implement chunk upload logic for each cloud service
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
