### C: `createNFAPI_CRC_INDICATION_PDU_T`

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void createNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t list_size) {
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < list_size; ++i) {
        pdu_list[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].crc_indication_rel8_tag.RNTI = rand();
        pdu_list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }
}

int main() {
    size_t list_size = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdu_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    createNFAPI_CRC_INDICATION_PDU_T(pdu_list, list_size);

    for (size_t i = 0; i < list_size; ++i) {
        printf("PDU %zu: RX_UE_INFORMATION_TAG = %u, RNTI = %u, CRCFLAG = %d\n",
               i, pdu_list[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG,
               pdu_list[i].crc_indication_rel8_tag.RNTI, pdu_list[i].CRCFLAG);
    }

    free(pdu_list);
    return 0;
}
