```c
// crypto_lib.c

#include "crypto_lib.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void load_plugin(const char *plugin_name, PluginManager *pm) {
    void *handle = dlopen(plugin_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load plugin: %s\n", dlerror());
        return;
    }

    AlgorithmPlugin init_func = (AlgorithmPlugin)dlsym(handle, "plugin_init");
    const char *err = dlerror();
    if (err != NULL) {
        fprintf(stderr, "Error loading symbol 'plugin_init': %s\n", err);
        dlclose(handle);
        return;
    }

    // Add the plugin to the manager
    pthread_mutex_lock(&pm->plugins_mutex);
    size_t index = pm->plugin_count++;
    pm->plugins = realloc(pm->plugins, sizeof(AlgorithmPlugin*) * pm->plugin_count);
    if (!pm->plugins) {
        perror("Failed to allocate memory for plugins");
        exit(EXIT_FAILURE);
    }
    pm->plugins[index] = &init_func;
    pthread_mutex_unlock(&pm->plugins_mutex);

    dlclose(handle);
}

int load_configuration(const char *config_file_path, PluginManager *plugin_manager) {
    json_error_t error;
    json_t *root = json_load_file(config_file_path, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing configuration file: %s\n", error.text);
        return -1;
    }

    const char *alg_name;
    json_array_foreach(json_object_get(root, "algorithms"), i, val) {
        alg_name = json_string_value(val);
        if (alg_name != NULL) {
            load_plugin(alg_name, plugin_manager); // Load dynamically
        }
    }

    json_decref(root);
    return 0;
}

void unload_library(PluginManager *plugin_manager) {
    pthread_mutex_lock(&plugin_manager->plugins_mutex);
    for (size_t i = 0; i < plugin_manager->plugin_count; ++i) {
        if (plugin_manager->plugins[i]) {
            dlclose(plugin_manager->plugins[i]);
        }
    }
    free(plugin_manager->plugins);
    pthread_mutex_unlock(&plugin_manager->plugins_mutex);
}

int perform_encryption(CryptoContext *ctx, const unsigned char *plaintext,
                       int plaintext_len, unsigned char *ciphertext) {
    // Implementation of encryption logic using loaded plugins
    return 0;
}

int perform_decryption(CryptoContext *ctx, const unsigned char *ciphertext,
                       int ciphertext_len, unsigned char *plaintext) {
    // Implementation of decryption logic using loaded plugins
    return 0;
}
