// Function to calculate MD5 hash of a file or URL in chunks.
void md5_hash(const char* filepath_or_url) {
    unsigned char c[MD5_DIGEST_LENGTH];
    FILE *file = fopen(filepath_or_url, "rb");

    if (!file) {
        fprintf(stderr, "Unable to open %s\n", filepath_or_url);
        return;
    }

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    MD5_Init(&mdContext);

    while ((bytes = fread(data, 1, sizeof(data), file)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }

    MD5_Final(c, &mdContext);

    fclose(file);

    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", c[i]);
    }

    printf("\n");
}

