<?php

function updateClinicStatus($clinic_id, $new_status, $last_modified_ip, $lastModifiedByUserId) {
    // Constants for validation
    $VALID_STATUSES = ['active', 'inactive', 'pending'];
    $RATE_LIMIT_KEY = "update_limit_{$last_modified_ip}";
    $RATE_LIMIT_MAX = 5;

    // Validate inputs
    if (!is_int($clinic_id) || $clinic_id <= 0 || !in_array($new_status, $VALID_STATUSES)) {
        return ['success' => false, 'error' => 'Invalid input parameters'];
    }

    // Check rate limit (using a simple file-based store for demonstration)
    $current_time = time();
    if (!file_exists("{$RATE_LIMIT_KEY}.txt")) {
        file_put_contents("{$RATE_LIMIT_KEY}.txt", json_encode([['timestamp' => $current_time]]));
    } else {
        $log = json_decode(file_get_contents("{$RATE_LIMIT_KEY}.txt"), true);
        // Filter out old entries
        $log = array_filter($log, function ($entry) use ($current_time) {
            return ($current_time - strtotime($entry['timestamp'])) < 60;
        });
        if (count($log) >= $RATE_LIMIT_MAX) {
            return ['success' => false, 'error' => 'Rate limit exceeded'];
        }
    }

    // Connect to database
    $pdo = new PDO('mysql:host=your_host;dbname=your_db', 'username', 'password');
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    try {
        // Begin transaction
        $pdo->beginTransaction();

        // Fetch current status
        $stmt = $pdo->prepare("SELECT status FROM clinics WHERE id = :clinic_id FOR UPDATE");
        $stmt->execute([':clinic_id' => $clinic_id]);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$row) {
            throw new Exception('Clinic not found');
        }

        // Prepare update statement
        $stmt = $pdo->prepare("UPDATE clinics SET status = :new_status, last_modified_ip = :last_modified_ip, last_modified_date = NOW() WHERE id = :clinic_id");
        $result = $stmt->execute([
            ':new_status' => $new_status,
            ':last_modified_ip' => $last_modified_ip,
            ':clinic_id' => $clinic_id
        ]);

        if (!$result) {
            throw new Exception('Failed to update clinic status');
        }

        // Log audit information
        auditLog($lastModifiedByUserId, $clinic_id, $row['status'], $new_status);

        // Send email notification (dummy function for demonstration)
        sendEmailNotification($clinic_id, $lastModifiedByUserId, $new_status);

        // Commit transaction
        $pdo->commit();

        // Update rate limiting log
        $log[] = ['timestamp' => date('Y-m-d H:i:s', $current_time)];
        file_put_contents("{$RATE_LIMIT_KEY}.txt", json_encode($log));

        // Return success response
        return [
            'success' => true,
            'details' => [
                'clinic_id' => $clinic_id,
                'new_status' => $new_status,
                'last_modified_ip' => $last_modified_ip,
                'last_modified_date' => date('Y-m-d H:i:s')
            ]
        ];
    } catch (Exception $e) {
        // Log error
        logError($e->getMessage());

        // Rollback transaction in case of error
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }

        return ['success' => false, 'error' => $e->getMessage()];
    }
}

function auditLog($userId, $clinicId, $oldStatus, $newStatus) {
    // Dummy function to simulate an external audit log
    file_put_contents('audit_log.txt', "User {$userId} updated clinic {$clinicId} from {$oldStatus} to {$newStatus}\n", FILE_APPEND);
}

function sendEmailNotification($clinicId, $userId, $status) {
    // Dummy email sending function for demonstration
    mail('admin@example.com', "Clinic Status Update", "Clinic ID: {$clinicId}, User ID: {$userId}, New Status: {$status}");
}

function logError($message) {
    file_put_contents('error_log.txt', date('Y-m-d H:i:s') . ' - ERROR: ' . $message . "\n", FILE_APPEND);
}

// Additional helper function to clean old logs
function cleanOldLogs() {
    $files = glob('*_log.txt');
    foreach ($files as $file) {
        if (filemtime($file) < strtotime('-30 days')) {
            unlink($file);
        }
    }
}
