<?php

function generateRandomStringAndHashPassword(
    int $length,
    string $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?',
    string $hashAlgorithm = 'bcrypt',
    int $rounds = 10,
    array $authServices = ['ldap', 'jwt', 'oauth2'],
    bool $validateRandomness = false
): array {
    // Error Handling for invalid inputs
    if ($length <= 0) {
        throw new InvalidArgumentException("Length must be a positive integer.");
    }

    if (empty($characterSet)) {
        throw new InvalidArgumentException("Character set cannot be empty.");
    }

    $uppercase = preg_match('/[A-Z]/', $characterSet);
    $lowercase = preg_match('/[a-z]/', $characterSet);
    $digit = preg_match('/\d/', $characterSet);
    $specialChar = preg_match('/[^a-zA-Z0-9]/', $characterSet);

    if (!$uppercase || !$lowercase || !$digit || !$specialChar) {
        throw new InvalidArgumentException("Character set must include at least one uppercase letter, lowercase letter, digit, and special character.");
    }

    // Generate a random string
    function getRandomString(int $length, string $characterSet): string {
        $output = '';
        $maxIndex = strlen($characterSet) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randIdx = random_int(0, $maxIndex);
            $output .= $characterSet[$randIdx];
        }

        return $output;
    }

    // Hash a password
    function hashPassword(string $password, string $hashAlgorithm, int $rounds): string {
        switch ($hashAlgorithm) {
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT, ['cost' => $rounds]);
            case 'sha256':
                return hash('sha256', $password);
            default:
                throw new InvalidArgumentException("Unsupported hash algorithm.");
