# Python API Implementation

from flask import Flask, request, jsonify
import logging
import requests

app = Flask(__name__)

resources = {}
cache = {}

NOTIFICATION_URL = "https://example.com/notify"

def notify(action, resource_id):
    try:
        response = requests.post(NOTIFICATION_URL, json={"action": action, "id": resource_id})
        response.raise_for_status()
    except requests.RequestException as e:
        logging.error(f"Notification failed: {e}")

@app.route('/update/<resource_id>', methods=['PUT'])
def update_resource(resource_id):
    try:
        data = request.get_json()

        if resource_id not in resources:
            return jsonify({"error": "Resource not found"}), 404

        # Update only specific fields
        for key, value in data.items():
            if key in resources[resource_id]:
                resources[resource_id][key] = value

        # Cache update
        cache[resource_id] = resources[resource_id]

        # Notify external system
        notify("update", resource_id)

        return jsonify(resources[resource_id])

    except Exception as e:
        logging.error(f"Update failed: {e}")
        return jsonify({"error": "Internal server error"}), 500

@app.route('/delete/<resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    try:
        if resource_id not in resources:
            return jsonify({"error": "Resource not found"}), 404

        # Cascade deletion
        related_resources = [key for key, value in resources.items() if value.get('related_id') == resource_id]

        for rid in related_resources:
            del resources[rid]

        del resources[resource_id]

        # Create new default resource
        resources['default'] = {"id": "default", "value": "Default"}

        # Notify external system
        notify("delete", resource_id)

        return jsonify(resources['default'])

    except Exception as e:
        logging.error(f"Deletion failed: {e}")
        return jsonify({"error": "Internal server error"}), 500

