```javascript
const { exec } = require('child_process');
const axios = require('axios');
const { createServer } = require('http');
const { pipeline } = require('stream');
const { Writable } = require('stream');

class ShellExecutor {
  constructor(apiConfig) {
    this.apiBaseUrl = apiConfig.baseUrl;
    this.authToken = apiConfig.token;
    this.concurrencyLimit = 100;
    this.activeTasks = new Set();
    this.logStream = new LogWritable();
  }

  authenticate() {
    return axios.post(`${this.apiBaseUrl}/authenticate`, { token: this.authToken });
  }

  executeCommand(serverId, command) {
    return new Promise((resolve, reject) => {
      const serverUrl = `${this.apiBaseUrl}/servers/${serverId}/exec`;

      if (this.activeTasks.size >= this.concurrencyLimit) {
        resolve({ status: 'queued' });
        setTimeout(() => this.executeCommand(serverId, command), 1000);
        return;
      }

      exec(`ssh user@${serverUrl} '${command}'`, { timeout: 30000 }, (error, stdout, stderr) => {
        const response = error ? { status: 'failed', error } : { status: 'success', output: stdout };
        this.logExecution(serverId, command, response);
        this.activeTasks.delete(`${serverId}-${Date.now()}`);

        resolve(response);
      });

      this.activeTasks.add(`${serverId}-${Date.now()}`);
    });
  }

  logExecution(serverId, command, result) {
    const logEntry = { serverId, command, result, timestamp: new Date().toISOString() };
    this.logStream.write(logEntry);
  }
}

class LogWritable extends Writable {
  _write(chunk, encoding, callback) {
    console.log(`Log Entry: ${JSON.stringify(chunk.toString())}`);
    callback();
  }
}

const server = createServer((req, res) => {
  const { serverId, command } = JSON.parse(req.body);

  new ShellExecutor({ baseUrl: 'https://api.example.com', token: 'your-token' })
    .executeCommand(serverId, command)
    .then(result => {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    })
    .catch(error => {
      res.writeHead(500);
      res.end('Internal Server Error');
    });
});

server.listen(3000, () => console.log('Server listening on port 3000'));

