Below is a simplified C++ code example that outlines the key components of the described utility. This includes reading from a binary file, parsing JSON configurations, using a Union-Find data structure for disjoint set operations, integrating with an external API, and providing a command-line interface.

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <nlohmann/json.hpp> // Include the JSON library
#include <curl/curl.h>
#include <cstring>

// Union-Find structure with path compression and union by rank
class UnionFind {
public:
    UnionFind(size_t size) : parent(size), rank(size, 0) {
        for (size_t i = 0; i < size; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void union_sets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                ++rank[rootX];
            }
        }
    }

private:
    std::vector<int> parent, rank;
};

// Function to read a binary file into an integer array
std::vector<int> readBinaryFile(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Unable to open file: " + filePath);
    }

    std::vector<char> buffer(std::istreambuf_iterator<char>(file), {});
    std::vector<int> data(buffer.size() / sizeof(int));
    std::memcpy(data.data(), buffer.data(), buffer.size());
    return data;
}

// Function to parse JSON configuration
nlohmann::json parseConfig(const std::string& configFilePath) {
    std::ifstream configFile(configFilePath);
    if (!configFile.is_open()) {
        throw std::runtime_error("Unable to open config file: " + configFilePath);
    }

    nlohmann::json config;
    configFile >> config;
    return config;
}

// Function to perform API call with retry logic
std::string fetchMetadata(const std::string& endpoint) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        throw std::runtime_error("CURL initialization failed");
    }

    // Implement retry logic and error handling
    int retries = 3;
    while (retries--) {
        curl_easy_setopt(curl, CURLOPT_URL, endpoint.c_str());
        CURLcode res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            std::string response(128);
            curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &response.size());
            return response;
        }
    }

    curl_easy_cleanup(curl);
    throw std::runtime_error("Failed to fetch metadata after retries");
}

// Thread-safe function to process data
void processData(const std::vector<int>& data, const nlohmann::json& config) {
    UnionFind uf(data.size());

    // Process data according to configuration
    for (size_t i = 0; i < data.size() - 1; ++i) {
        if ((data[i] % config["pair_modulo"]) == (data[i + 1] % config["pair_modulo"])) {
            uf.union_sets(i, i + 1);
        }
    }

    // Fetch metadata from API
    std::string metadata = fetchMetadata(config["api_endpoint"]);

    // Further processing...
}

// Command-line interface function
void runUtility(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <binary_file> <config_file> <output_file>" << std::endl;
        return;
    }

    std::string binaryFilePath = argv[1];
    std::string configFilePath = argv[2];

    try {
        auto data = readBinaryFile(binaryFilePath);
        auto config = parseConfig(configFilePath);

        // Multi-threaded processing
        std::vector<std::thread> threads;
        for (size_t i = 0; i < data.size() / 10000 + 1; ++i) { // Adjust chunk size as needed
            threads.emplace_back(processData, std::ref(data), std::cref(config));
        }

        for (auto& t : threads) {
            if (t.joinable()) {
                t.join();
            }
        }

        std::cout << "Processing completed successfully." << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
}

// Unit test function
void runTests() {
    // Implement unit tests for various edge cases
}

int main(int argc, char* argv[]) {
    runUtility(argc, argv);
    return 0;
}
