```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <pthread.h>

#define CHUNK_SIZE 4096

typedef struct {
    char *file_name;
    size_t file_size;
} FileMetadata;

typedef enum { ECB, EDE, EDE3, CFB, NULL_CIPHER } CipherMode;

// Function prototypes
EVP_CIPHER* select_cipher(CipherMode mode);
void encrypt_and_upload(const char* local_path, const char* bucket_name, const char* directory, CipherMode cipher_mode);
char* calculate_sha256_hash(const char* file_path);
int validate_metadata(FileMetadata metadata);
void log_info(const char *message);
void log_error(const char *message);

// Global mutex for thread safety
pthread_mutex_t upload_mutex = PTHREAD_MUTEX_INITIALIZER;

EVP_CIPHER* select_cipher(CipherMode mode) {
    switch (mode) {
        case ECB: return EVP_des_ecb();
        case EDE: return EVP_des_ede3();
        case EDE3: return EVP_des_ede3_cbc();
        case CFB: return EVP_des_cfb64();
        default: return NULL;
    }
}

char* calculate_sha256_hash(const char* file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        log_error("Failed to open file for hashing.");
        return NULL;
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    const int read_size = CHUNK_SIZE;
    unsigned char *buffer = malloc(read_size);
    if (!buffer) {
        log_error("Failed to allocate memory for hashing.");
        fclose(file);
        return NULL;
    }

    int bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, read_size, file))) {
        SHA256_Update(&sha256, buffer, bytes_read);
    }
    free(buffer);

