# Python Function: Read, Sort, Extract Sequence Number from Last Line

def read_sort_extract_sequence(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        # Sorting the lines
        sorted_lines = sorted(lines)

        if not sorted_lines:
            raise ValueError("The file is empty.")

        # Extracting sequence number from the last line
        last_line = sorted_lines[-1].strip()
        if not last_line.endswith('.'):
            raise ValueError("Last line does not end with a period or sequence number.")

        sequence_number = int(last_line.split()[-1][:-1])
        return sequence_number

    except FileNotFoundError:
        print(f"Error: The file at {file_path} was not found.")
    except ValueError as ve:
        print(f"Value Error: {ve}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


