```cpp
#include <vector>
#include <algorithm>
#include <cmath>
#include <limits>

class KDTree {
public:
    struct Node {
        std::vector<double> point;
        int axis;
        Node* left = nullptr;
        Node* right = nullptr;

        Node(const std::vector<double>& pt, int ax) : point(pt), axis(ax) {}
    };

    KDTree(int dimensions, size_t maxCapacity)
        : dimensions(dimensions), maxCapacity(maxCapacity), root(nullptr) {}

    ~KDTree() {
        deleteNode(root);
    }

    bool initialize_kdtree(const std::vector<std::vector<double>>& points) {
        if (points.size() > static_cast<size_t>(maxCapacity)) return false;
        for (const auto& point : points) {
            if (point.size() != dimensions) return false;
        }
        root = build(points, 0);
        return true;
    }

    void insert(const std::vector<double>& point) {
        if (point.size() != dimensions || nodes.size() >= maxCapacity) return;
        root = insert(root, point, 0);
        nodes.push_back(point);
    }

    bool remove(const std::vector<double>& point) {
        if (point.size() != dimensions) return false;
        root = remove(root, point, 0);
        auto it = std::find(nodes.begin(), nodes.end(), point);
        if (it != nodes.end()) {
            nodes.erase(it);
            return true;
        }
        return false;
    }

    std::vector<double> nearestNeighbor(const std::vector<double>& query) const {
        Node* best = nullptr;
        double bestDist = std::numeric_limits<double>::max();
        nearestNeighbor(root, query, 0, best, bestDist);
        if (best) return best->point;
        return {};
    }

private:
    int dimensions;
    size_t maxCapacity;
    Node* root;
    mutable std::vector<std::vector<double>> nodes;

    void deleteNode(Node* node) {
        if (!node) return;
        deleteNode(node->left);
        deleteNode(node->right);
        delete node;
    }

    Node* build(const std::vector<std::vector<double>>& points, int depth) const {
        if (points.empty()) return nullptr;

        size_t axis = depth % dimensions;
        auto sortedPoints = points;
        std::sort(sortedPoints.begin(), sortedPoints.end(),
                  [axis](const std::vector<double>& a, const std::vector<double>& b) {
                      return a[axis] < b[axis];
                  });

        size_t medianIndex = sortedPoints.size() / 2;
        Node* node = new Node(sortedPoints[medianIndex], axis);

        std::vector<std::vector<double>> leftPoints(sortedPoints.begin(), sortedPoints.begin() + medianIndex);
        std::vector<std::vector<double>> rightPoints(sortedPoints.begin() + medianIndex + 1, sortedPoints.end());

        node->left = build(leftPoints, depth + 1);
        node->right = build(rightPoints, depth + 1);

        return node;
    }

    Node* insert(Node* node, const std::vector<double>& point, int depth) {
        if (!node) return new Node(point, depth % dimensions);

        size_t axis = depth % dimensions;
        if (point[axis] < node->point[axis]) {
            node->left = insert(node->left, point, depth + 1);
        } else {
            node->right = insert(node->right, point, depth + 1);
        }

        return node;
    }

    Node* remove(Node* node, const std::vector<double>& point, int depth) {
        if (!node) return nullptr;

        size_t axis = depth % dimensions;
        if (point == node->point) {
            if (node->right) {
                auto minNode = findMin(node->right, axis);
                node->point = minNode->point;
                node->right = remove(node->right, minNode->point, depth + 1);
            } else if (node->left) {
                auto minNode = findMin(node->left, axis);
                node->point = minNode->point;
                node->right = remove(node->left, minNode->point, depth + 1);
                node->left = nullptr;
            } else {
                delete node;
                return nullptr;
            }
        } else if (point[axis] < node->point[axis]) {
            node->left = remove(node->left, point, depth + 1);
        } else {
            node->right = remove(node->right, point, depth + 1);
        }

        return node;
    }

    Node* findMin(Node* node, size_t axis) const {
        if (!node) return nullptr;

        size_t currentAxis = node->axis;
        if (currentAxis == axis) {
            if (!node->left) return node;
            return findMin(node->left, axis);
        }

        auto leftMin = findMin(node->left, axis);
        auto rightMin = findMin(node->right, axis);

        Node* minNode = node;
        double minValue = node->point[axis];

        if (leftMin && leftMin->point[axis] < minValue) {
            minNode = leftMin;
            minValue = leftMin->point[axis];
        }

        if (rightMin && rightMin->point[axis] < minValue) {
            minNode = rightMin;
        }

        return minNode;
    }

    void nearestNeighbor(Node* node, const std::vector<double>& query,
                         int depth, Node*& best, double& bestDist) const {
        if (!node) return;

        double dist = squaredDistance(node->point, query);
        size_t axis = depth % dimensions;

        Node* nextNode = nullptr;
        Node* otherNode = nullptr;

        if (query[axis] < node->point[axis]) {
            nextNode = node->left;
            otherNode = node->right;
        } else {
            nextNode = node->right;
            otherNode = node->left;
        }

        nearestNeighbor(nextNode, query, depth + 1, best, bestDist);

        if (dist < bestDist) {
            bestDist = dist;
            best = node;
        }

        double planeDist = std::pow(query[axis] - node->point[axis], 2);
        if (planeDist < bestDist) {
            nearestNeighbor(otherNode, query, depth + 1, best, bestDist);
        }
    }

    static double squaredDistance(const std::vector<double>& a, const std::vector<double>& b) {
        double dist = 0.0;
        for (size_t i = 0; i < a.size(); ++i) {
            double diff = a[i] - b[i];
            dist += diff * diff;
        }
        return dist;
    }
};
