// Setup logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console()
  ]
});

// Exponential backoff function
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function fetchAndUploadFile(url, metadata = {}, providerConfig) {
  const { maxRetries, initialDelay } = { maxRetries: 3, initialDelay: 1000 };

  async function fetchWithRetry(attempt) {
    try {
      return await axios({
        method: url.startsWith('https') ? 'https' : 'http',
        url,
        responseType: 'stream'
      });
    } catch (error) {
      if (attempt < maxRetries) {
        const delayTime = initialDelay * Math.pow(2, attempt);
        logger.warn(`Fetch failed. Retrying in ${delayTime}ms...`, { error, attempt });
        await delay(delayTime);
        return fetchWithRetry(attempt + 1);
      }
      throw new Error('Failed to fetch file after retries');
    }
  }

  function uploadFile(fileStream, chunkSize = 5 * 1024 * 1024) {
    const size = Number.parseInt((fileStream.headers['content-length'] || 0), 10);

    if (size > 50 * 1024 * 1024) {
      return handleLargeFileUpload(fileStream, chunkSize, size);
    }

    return uploadChunked(fileStream);
  }

  async function handleLargeFileUpload(fileStream, chunkSize, totalSize) {
    const totalChunks = Math.ceil(totalSize / chunkSize);
    logger.info(`Starting large file upload in ${totalChunks} chunks`, { totalSize });

    for (let i = 0; i < totalChunks; i++) {
      let start = i * chunkSize;
      let end = Math.min(start + chunkSize, totalSize);

      const rangeStream = fileStream.pipe(new require('stream').PassThrough({
        highWaterMark: chunkSize
      })).pipe(
        new require('stream').Transform({
          transform(chunk, encoding, callback) {
            if (start < chunk.length) {
              this.push(chunk.slice(start - chunk.offset));
              start += chunk.length;
            }
            callback();
          }
        })
      );

      await uploadChunked(rangeStream);
    }

    logger.info('Completed large file upload');
  }

  async function uploadChunked(stream) {
    const { cloudProvider, region, bucketName } = providerConfig;

    // Mocking the upload process with a promise
    return new Promise((resolve, reject) => {
      try {
        streamPipeline(
          stream,
          fs.createWriteStream('/tmp/upload.tmp'),
          async (err) => {
            if (err) {
              logger.error('Upload failed', { error: err });
              return reject(err);
            }

            // Simulate a cloud provider's upload function
            const fileName = path.basename(url);
            logger.info(`Uploading file to ${cloudProvider}...`, { fileName, bucketName });

            // Example of calling an SDK (e.g., AWS S3) would be placed here.
            setTimeout(() => {
              fs.unlinkSync('/tmp/upload.tmp');
              logger.info('File uploaded successfully', { fileName });
              resolve();
            }, 1000); // Simulated upload time
          }
        );
      } catch (error) {
        reject(error);
      }
    });
  }

  try {
    const response = await fetchWithRetry(0);

    if (!response.headers['content-length']) {
      throw new Error('No content length header received');
    }

    return await uploadFile(response.data, metadata.chunkSize || undefined);
  } catch (error) {
    logger.error('Failed to complete the file upload process', { error });
    throw error;
  }
}

