import <stdbool.h>
#include <string.h>
#include <jansson.h> // JSON parsing library
#include <pthread.h> // For thread safety
#include <time.h>    // For timestamping logs
#include "distributed_cache.h" // Placeholder for distributed cache integration
#include "logging.h" // Placeholder for logging mechanism
#include "rate_limit.h" // Placeholder for rate limiting
#include "jwt_validator.h" // Placeholder for JWT validation

#define MAX_REQUESTS_PER_MINUTE 100
#define VALID_TOKEN_TYPE_BEARER "Bearer"
#define VALID_TOKEN_TYPE_MAC "MAC"
#define MAX_EXPIRES_IN_SECONDS 3600

// Predefined set of valid scopes
const char *valid_scopes[] = {"read", "write", "delete"};
size_t num_valid_scopes = sizeof(valid_scopes) / sizeof(valid_scopes[0]);

// Function to check if a scope is valid
bool is_scope_valid(const char* scope) {
    for (size_t i = 0; i < num_valid_scopes; ++i) {
        if (strcmp(scope, valid_scopes[i]) == 0) {
            return true;
        }
    }
    return false;
}

// Function to verify the token response
bool verify_oauth2_token_response(const char* json_str, const char* ip_address) {
    // Initialize rate limiter and log attempt
    if (!rate_limiter_check(ip_address, MAX_REQUESTS_PER_MINUTE)) {
        log_attempt(ip_address, "Rate limit exceeded", false);
        return false;
    }

    // Parse JSON object
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if (!root) {
        log_attempt(ip_address, "Invalid JSON format", false);
        return false;
    }

    bool is_valid = true;

    // Check for required fields and their values
    const char* access_token = json_string_value(json_object_get(root, "access_token"));
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    const char* token_type = json_string_value(json_object_get(root, "token_type"));
    const char* refresh_token_str = json_string_value(json_object_get(root, "refresh_token"));
    json_t *scope_array = json_object_get(root, "scope");

    // Validate access_token
    if (!access_token) {
        log_attempt(ip_address, "Missing 'access_token'", false);
        is_valid = false;
    }

    // Validate expires_in
    if (expires_in <= 0 || expires_in > MAX_EXPIRES_IN_SECONDS) {
        log_attempt(ip_address, "'expires_in' value out of range", false);
        is_valid = false;
    }

    // Validate token_type
    bool token_type_valid = false;
    if (token_type && strcmp(token_type, VALID_TOKEN_TYPE_BEARER) == 0) {
        token_type_valid = true;
    } else if (token_type && strcmp(token_type, VALID_TOKEN_TYPE_MAC) == 0) {
        // Add MAC specific validation here
        token_type_valid = true;
    }

    if (!token_type_valid) {
        log_attempt(ip_address, "Invalid 'token_type'", false);
        is_valid = false;
    }

    // Validate refresh_token (if present)
    if (refresh_token_str && !distributed_cache_verify_refresh_token(refresh_token_str)) {
        log_attempt(ip_address, "Refresh token invalid or expired", false);
        is_valid = false;
    }

    // Validate scope
    if (!json_is_array(scope_array) || json_array_size(scope_array) == 0) {
        log_attempt(ip_address, "Missing or empty 'scope'", false);
        is_valid = false;
    } else {
        for (size_t i = 0; i < json_array_size(scope_array); ++i) {
            const char* scope = json_string_value(json_array_get(scope_array, i));
            if (!scope || !is_scope_valid(scope)) {
                log_attempt(ip_address, "Invalid 'scope'", false);
                is_valid = false;
                break;
            }
        }
    }

    // JWT validation (if token_type is Bearer)
    if (strcmp(token_type, VALID_TOKEN_TYPE_BEARER) == 0 && !jwt_validate(access_token)) {
        log_attempt(ip_address, "JWT signature verification failed", false);
        is_valid = false;
    }

    // Log attempt
    log_attempt(ip_address, is_valid ? "Token verified successfully" : "Token verification failed", is_valid);

    // Clean up JSON object
    json_decref(root);

    return is_valid;
}

// Thread-safe wrapper function
bool verify_token(const char* json_str, const char* ip_address) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);
    bool result = verify_oauth2_token_response(json_str, ip_address);
    pthread_mutex_unlock(&lock);

    return result;
