```csharp
using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static XmlNode ParseXmlAndGetElement(string xmlContent, string xpath)
    {
        XmlDocument doc = new XmlDocument();
        doc.LoadXml(xmlContent);

        XPathNavigator nav = doc.CreateNavigator();
        XPathNodeIterator nodes = nav.Select(xpath);

        if (nodes.Count == 0)
            throw new Exception("No matching elements found.");
        if (nodes.Count > 1)
            throw new Exception("Multiple matching elements found.");

        return nodes.Current?.OuterXml != null ? nodes.Current as XmlNode : null;
    }
}
```

