#include <stdio.h>
#include <string.h>

char* appendSlashIfNeeded(char *str, size_t maxSize)
{
    size_t len = strlen(str);
    if (len >= maxSize - 1) return NULL;

    str[len] = '/';
    str[len + 1] = '\0';
    return str;
}
