```python
import json
import os
from concurrent.futures import ThreadPoolExecutor, as_completed
import pandas as pd
from scipy.stats import zscore
from sqlalchemy import create_engine

def process_log_file(file_path):
    with open(file_path, 'r') as file:
        data = json.load(file)

    df = pd.DataFrame(data)
    df['z_score'] = zscore(df['sensor_value'])
    filtered_df = df[df['z_score'].abs() < 3]

    # Assuming database setup is done and engine is configured
    engine = create_engine('postgresql://username:password@localhost/dbname')
    filtered_df.to_sql('cleaned_sensor_data', con=engine, if_exists='append')

def process_logs(directory):
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(process_log_file, os.path.join(directory, file))
                   for file in os.listdir(directory) if file.endswith('.log')]

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                print(f"Error processing log: {e}")

if __name__ == "__main__":
    process_logs("/path/to/log/files")
```

### JavaScript Function: Fetch Weather Data

```javascript
async function fetchWeatherData(cities, apiKey) {
    const cache = new Map();
    const maxRetries = 3;

    async function fetchCityWeather(city) {
        if (cache.has(city)) return cache.get(city);

        let url = `https://api.weather.com/v1/location/${city}/observations.json?apiKey=${apiKey}`;

        for (let attempt = 0; attempt < maxRetries; attempt++) {
            try {
                const response = await fetch(url);

                if (!response.ok) {
                    if ([429, 503].includes(response.status)) { 
                        // Handle rate limiting and service unavailable
                        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
                        continue;
                    }
                    throw new Error(`Error: ${response.statusText}`);
                }

                const data = await response.json();
                cache.set(city, data);
                return data;

            } catch (error) {
                console.error(`Attempt ${attempt + 1} failed for ${city}:`, error.message);
                if (attempt === maxRetries - 1) throw new Error('Max retries reached');
            }
        }
    }

    const weatherDataPromises = cities.map(fetchCityWeather);

    try {
        const results = await Promise.all(weatherDataPromises);

        // Update UI with fetched data
        updateUI(results); 

    } catch (error) {
        console.error("Failed to fetch weather data:", error.message);
    }
}

function updateUI(data) {
    // Implement the logic to update your application's UI
}
