const express = require('express');
const axios = require('axios');
const NodeCache = require('node-cache');

// Initialize cache with a TTL of 10 minutes
const apiCache = new NodeCache({ stdTTL: 600 });

// Placeholder API keys and base URLs for different services
const WEATHER_API_KEY_1 = 'your_primary_weather_api_key';
const FORECAST_API_KEY_2 = 'your_forecast_api_key';
const CLIMATE_API_KEY_3 = 'your_climate_api_key';

const PRIMARY_WEATHER_URL = `https://api.weather.com/v3/wx/conditions/current?apiKey=${WEATHER_API_KEY_1}&`;
const FALLOUT_WEATHER_URL = `https://fallback.api/weather?apiKey=secondary_key&`;

const FORECAST_URL = `https://api.forecast.io/v1/hourly?apiKey=${FORECAST_API_KEY_2}`;
const CLIMATE_URL = `https://api.climate.com/v3/stats?apiKey=${CLIMATE_API_KEY_3}`;

const app = express();
app.use(express.json());

// Utility function to fetch data with retries
async function fetchDataWithRetry(url, retries = 3) {
    try {
        const response = await axios.get(url);
        return response.data;
    } catch (error) {
        if (retries > 0 && error.response && error.response.status >= 500) {
            return fetchDataWithRetry(url, retries - 1);
        }
        throw new Error(`Failed to fetch data: ${error.message}`);
    }
}

// API route to get weather data
app.get('/weather', async (req, res) => {
    const { lat, lon } = req.query;
    if (!lat || !lon) {
        return res.status(400).json({ error: 'Latitude and longitude are required' });
    }

    const cacheKey = `weather-${lat}-${lon}`;
    let weatherData = apiCache.get(cacheKey);

    if (!weatherData) {
        try {
            const primaryWeatherUrl = `${PRIMARY_WEATHER_URL}geocode=${lat},${lon}&format=json`;

            // Attempt to fetch from the primary API
            weatherData = await fetchDataWithRetry(primaryWeatherUrl);
            if (weatherData.status !== 'success') {
                // If primary fails, attempt fallback
                const falloutWeatherUrl = `${FALLOUT_WEATHER_URL}geocode=${lat},${lon}&format=json`;
                weatherData = await fetchDataWithRetry(falloutWeatherUrl);
            }

            // Cache the result for subsequent requests
            apiCache.set(cacheKey, weatherData);

        } catch (error) {
            return res.status(500).json({ error: 'Failed to fetch weather data' });
        }
    }

    const forecastUrl = `${FORECAST_URL}&geocode=${lat},${lon}`;
    const climateUrl = `${CLIMATE_URL}&geocode=${lat},${lon}`;

    try {
        const [forecastData, climateData] = await Promise.all([
            fetchDataWithRetry(forecastUrl),
            fetchDataWithRetry(climateUrl)
        ]);

        res.json({
            currentWeather: weatherData,
            hourlyForecast: forecastData.hourly.data,
            monthlyClimateStats: climateData.stats,
            satelliteImageryLink: `https://satellite.api/imagery?lat=${lat}&lon=${lon}` // Placeholder link
        });

    } catch (error) {
        res.status(500).json({ error: 'Failed to fetch additional data' });
    }
});

// Error handling middleware
app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
```

