public class PreferencesLoader
{
    private readonly string _binaryFilePath;
    private readonly IMemoryCache _cache;
    private readonly ILogger _logger; // Assuming a logger is injected that adheres to an interface

    public PreferencesLoader(string binaryFilePath, IMemoryCache cache, ILogger logger)
    {
        _binaryFilePath = binaryFilePath ?? throw new ArgumentNullException(nameof(binaryFilePath));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    // Method to load preferences
    public async Task<UserPreferences> LoadUserPreferencesAsync(int userId)
    {
        try
        {
            string cacheKey = $"UserPreferences_{userId}";

            if (_cache.TryGetValue(cacheKey, out UserPreferences cachedPreferences))
            {
                return cachedPreferences;
            }

            // Attempt to read from binary file
            var preferences = await ReadFromFileAsync(userId);
            if (preferences != null)
            {
                _cache.Set(cacheKey, preferences, TimeSpan.FromMinutes(10)); // Cache for 10 minutes
                return preferences;
            }

            // Fallback to database
            var dbPreferences = await FetchFromDatabaseAsync(userId);
            if (dbPreferences != null)
            {
                _cache.Set(cacheKey, dbPreferences, TimeSpan.FromMinutes(10));
                return dbPreferences;
            }

            throw new CacheException("User preferences could not be loaded.");
        }
        catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException || ex is CacheException)
        {
            _logger.LogError(ex, "Error loading user preferences for userId: {UserId}", userId);
            throw; // Re-throw after logging
        }
    }

    private async Task<UserPreferences> ReadFromFileAsync(int userId)
    {
        if (!File.Exists(_binaryFilePath))
        {
            _logger.LogWarning("Binary file not found.");
            return null;
        }

        try
        {
            using (var stream = new FileStream(_binaryFilePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
            {
                // Assuming BinaryFormatter or a similar serializer/deserializer is used here
                var formatter = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
                var allPreferences = (Dictionary<int, UserPreferences>)formatter.Deserialize(stream);

                return allPreferences.TryGetValue(userId, out var preferences) ? preferences : null;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error reading from binary file.");
            throw new IOException("Binary file corrupted or unreadable.", ex);
        }
    }

    private async Task<UserPreferences> FetchFromDatabaseAsync(int userId)
    {
        // Use a secure connection string
        var connectionString = ""; // Assume this is securely loaded
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            var commandText = "SELECT Preferences FROM UserPreferences WHERE UserId = @UserId";

            using (var command = new SqlCommand(commandText, connection))
            {
                command.Parameters.AddWithValue("@UserId", userId);

                var result = await command.ExecuteScalarAsync() as string;
                if (!string.IsNullOrEmpty(result))
                {
                    return JsonConvert.DeserializeObject<UserPreferences>(result);
                }
            }
        }

        _logger.LogWarning("No preferences found in database for userId: {UserId}", userId);
        return null;
    }
}

