```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using Azure.Storage.Blobs;
using System.Threading.Tasks;

public class CloudStorageService
{
    private readonly ILogger<CloudStorageService> _logger;
    private const int KeySize = 256; // bits
    private const int IvSize = 128;  // bits

    public CloudStorageService(ILogger<CloudStorageService> logger)
    {
        _logger = logger;
    }

    public async Task<string> DecryptAndUpload(
        string filePath, 
        byte[] key, 
        byte[] iv, 
        string bucketName, 
        string paddingScheme = "PKCS7", 
        int chunkSize = 8192)
    {
        ValidateKeyAndIv(key, iv);

        string decryptedContent;
        try
        {
            using (var aesAlg = CreateAesAlgorithm(key, iv, paddingScheme))
            {
                decryptedContent = await DecryptFile(filePath, aesAlg.CreateDecryptor(), chunkSize);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed for file: {FilePath}", filePath);
            throw;
        }

        string hashHex = CalculateSha256Hash(decryptedContent);

        await UploadToCloudStorage(bucketName, decryptedContent, hashHex);

        return hashHex;
    }

    private void ValidateKeyAndIv(byte[] key, byte[] iv)
    {
        if (key == null || iv == null)
            throw new ArgumentException("Key and IV cannot be null.");

        if (key.Length * 8 != KeySize)
            throw new ArgumentException($"Invalid key size. Expected: {KeySize} bits.");

        if (iv.Length * 8 != IvSize)
            throw new ArgumentException($"Invalid IV size. Expected: {IvSize} bits.");
    }

    private Aes CreateAesAlgorithm(byte[] key, byte[] iv, string paddingScheme)
    {
        var aesAlg = Aes.Create();
        aesAlg.Key = key;
        aesAlg.IV = iv;

        switch (paddingScheme.ToUpper())
        {
            case "PKCS7":
                aesAlg.Padding = PaddingMode.PKCS7;
                break;
            case "ANSIX923":
                aesAlg.Padding = PaddingMode.ANSIX923;
                break;
            case "NOPADDING":
                aesAlg.Padding = PaddingMode.None;
                break;
            default:
                throw new ArgumentException("Unsupported padding scheme.");
        }

        return aesAlg;
    }

    private async Task<string> DecryptFile(string filePath, ICryptoTransform decryptor, int chunkSize)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException($"File not found: {filePath}");

        using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read);
        using var cryptoStream = new CryptoStream(fileStream, decryptor, CryptoStreamMode.Read);
        using var memoryStream = new MemoryStream();

        byte[] buffer = new byte[chunkSize];
        int bytesRead;
        while ((bytesRead = await cryptoStream.ReadAsync(buffer, 0, chunkSize)) > 0)
        {
            memoryStream.Write(buffer, 0, bytesRead);
        }

        return Encoding.UTF8.GetString(memoryStream.ToArray());
    }

    private string CalculateSha256Hash(string input)
    {
        using var sha256 = SHA256.Create();
        byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        StringBuilder builder = new StringBuilder();

        foreach (byte b in bytes)
        {
            builder.Append(b.ToString("x2"));
        }

        return builder.ToString();
    }

    private async Task UploadToCloudStorage(string bucketName, string content, string hashHex)
    {
        var connectionString = "YourAzureBlobConnectionString";
        var blobServiceClient = new BlobServiceClient(connectionString);
        var containerClient = blobServiceClient.GetBlobContainerClient(bucketName);

        await containerClient.CreateIfNotExistsAsync();

        using var memoryStream = new MemoryStream(Encoding.UTF8.GetBytes(content));
        var blobClient = containerClient.GetBlobClient($"decrypted-{Guid.NewGuid()}.txt");

        try
        {
            await blobClient.UploadAsync(memoryStream, new BlobHttpHeaders { ContentType = "text/plain" });

            _logger.LogInformation("File uploaded successfully. Hash: {Hash}", hashHex);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to upload file to cloud storage.");
            throw;
        }
    }
}
```

