    }

    private static void loadConfig() {
        try (BufferedReader reader = Files.newBufferedReader(Paths.get("config.properties"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("infoLogPath=")) {
                    infoLogFilePath = line.split("=")[1];
                } else if (line.startsWith("errorLogPath=")) {
                    errorLogFilePath = line.split("=")[1];
                } else if (line.startsWith("logLevel=")) {
                    logLevel = Integer.parseInt(line.split("=")[1]);
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading config file.");
        }
    }

    private static boolean isFileExists(String filePath) {
        return Files.exists(Paths.get(filePath));
    }

    private static void deleteFileIfExists(String filePath) {
        try {
            Files.delete(Paths.get(filePath));
        } catch (IOException e) {
            System.err.println("Error deleting file: " + e.getMessage());
        }
    }

    private static void executeCommands() {
        String[] commands = {"echo Hello", "ls /nonexistent"};

        for (String command : commands) {
            try {
                ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
                Process process = processBuilder.start();

                logOutput(process.getInputStream(), "INFO");
                logOutput(process.getErrorStream(), "ERROR");

                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    logMessage("ERROR", String.format("Command '%s' failed with exit code %d", command, exitCode));
                }
            } catch (IOException | InterruptedException e) {
                logMessage("ERROR", "Exception during command execution: " + e.getMessage());
                Thread.currentThread().interrupt();
            }
        }
    }

    private static void logOutput(InputStream stream, String severity) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logMessage(severity, line);
            }
        }
    }

    private static void logMessage(String severity, String message) {
        if ((severity.equals("INFO") && logLevel <= 1) || (severity.equals("ERROR") && logLevel <= 2)) {
            String timestamp = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date());
            String formattedMessage = String.format("%s [%s] %s%n", timestamp, severity, message);

            try {
                Files.write(Paths.get(severity.toLowerCase() + "Log.txt"), (formattedMessage).getBytes(), 
                            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            } catch (IOException e) {
                System.err.println("Error writing to log file: " + e.getMessage());
            }
        }
    }
}
