// Import necessary modules
const crypto = require('crypto');
const WebSocket = require('ws');

class DataCollector {
  constructor(wsUrl, config) {
    this.wsUrl = wsUrl;
    this.config = config;
    this.dataArray = [];
    this.paused = false;
    this.ws = null;

    // Encryption setup
    const { key, salt, iv } = this.setupEncryption();

    this.encryptData = (data) => {
      try {
        const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), Buffer.from(iv));
        let encrypted = cipher.update(data);
        encrypted = Buffer.concat([encrypted, cipher.final()]);
        return encrypted.toString('hex');
      } catch (err) {
        console.error("Encryption error:", err.message);
      }
    };

    // Derived encryption key
    this.encryptionKey = key;
  }

  setupEncryption() {
    const { passphrase, salt, ivLength } = this.config;

    const key = crypto.scryptSync(passphrase, Buffer.from(salt), 32); // Key derivation
    const iv = crypto.randomBytes(ivLength); // Initialization vector

    console.log("Encryption setup complete.");

    return { key, salt, iv };
  }

  startCollection() {
    this.ws = new WebSocket(this.wsUrl);

    this.ws.on('open', () => {
      console.log("WebSocket connection established.");
    });

    this.ws.on('message', (data) => {
      if (this.paused) return;

      try {
        const message = JSON.parse(data.toString());
        if (this.isRelevant(message)) {
          const encryptedData = this.encryptData(JSON.stringify(message));
          this.dataArray.push(encryptedData);
          console.log("Message collected and encrypted:", encryptedData);
        }
      } catch (err) {
        console.error("Error processing message:", err.message);
      }
    });

    this.ws.on('close', () => {
      console.log("WebSocket connection closed.");
    });

    this.ws.on('error', (err) => {
      console.error("WebSocket error:", err.message);
    });
  }

  isRelevant(message) {
    const { contentType } = message;
    return contentType === 'relevant'; // Example filter condition
  }

  pause() {
    this.paused = true;
    console.log("Data collection paused.");
  }

  resume() {
    this.paused = false;
    console.log("Data collection resumed.");
  }
}

