#include <openssl/rand.h>
#include <pthread.h>

#define KEY_SIZE_DES 8 // DES key size in bytes
#define IV_SIZE_CFB_DES 8 // CFB mode uses a block-size of 8 bytes for DES

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock; // For thread safety
} CryptoContext;

// Function to initialize logging mechanism
void log_operation(const char *operation, const char *cipher_name) {
    printf("[LOG] Operation: %s, Cipher: %s\n", operation, cipher_name);
}

// Secure key storage and retrieval functions (stubbed for demonstration)
int fetch_key_from_kms(unsigned char **key_out) {
    // Placeholder for KMS interaction
    *key_out = malloc(KEY_SIZE_DES);
    if (!(*key_out)) return 0;
    RAND_bytes(*key_out, KEY_SIZE_DES); // Simulate key retrieval with random bytes
    return 1;
}

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Initialize a CryptoContext for DES ciphers
CryptoContext* init_crypto_context(const char *cipher_name, const unsigned char *key, size_t key_len, const unsigned char *iv, int iv_len) {
    CryptoContext *crypto_ctx = malloc(sizeof(CryptoContext));
    if (!crypto_ctx) return NULL;

    pthread_mutex_init(&crypto_ctx->lock, NULL);
    crypto_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!crypto_ctx->ctx) {
        handle_error("Failed to create cipher context");
        free(crypto_ctx);
        return NULL;
    }

    const EVP_CIPHER *cipher;
    if (strcmp(cipher_name, "DES_ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(cipher_name, "DES_EDE_CBC") == 0) {
        cipher = EVP_des_ede3_cbc();
        if (iv_len != IV_SIZE_CFB_DES) return NULL; // Ensure correct IV size
    } else if (strcmp(cipher_name, "DES_EDE3") == 0) {
        cipher = EVP_des_ede3_cbc();
    } else if (strcmp(cipher_name, "DES_CFB") == 0) {
        cipher = EVP_des_cfb64(); // Assuming 64-bit CFB mode
        if (iv_len != IV_SIZE_CFB_DES) return NULL; // Ensure correct IV size
    } else {
        handle_error("Unsupported cipher");
        EVP_CIPHER_CTX_free(crypto_ctx->ctx);
        free(crypto_ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(crypto_ctx->ctx, cipher, NULL, key, iv)) {
        handle_error("Cipher initialization failed");
        EVP_CIPHER_CTX_free(crypto_ctx->ctx);
        free(crypto_ctx);
        return NULL;
    }

    log_operation("Initialization", cipher_name);

    return crypto_ctx;
}

// Destroy a CryptoContext
void destroy_crypto_context(CryptoContext *crypto_ctx) {
    if (crypto_ctx) {
        pthread_mutex_destroy(&crypto_ctx->lock);
        EVP_CIPHER_CTX_free(crypto_ctx->ctx);
        free(crypto_ctx);
    }
}

// Encrypt/Decrypt function stub
int crypto_operation(CryptoContext *crypto_ctx, const unsigned char *input, int input_len, unsigned char *output) {
    if (!crypto_ctx || !input || !output) return 0;

    pthread_mutex_lock(&crypto_ctx->lock);

    int outlen = 0;
    int ret = EVP_EncryptUpdate(crypto_ctx->ctx, output, &outlen, input, input_len);
    if (ret <= 0) {
        handle_error("Encryption/Decryption update failed");
        pthread_mutex_unlock(&crypto_ctx->lock);
        return 0;
    }

    int final_outlen = 0;
    ret = EVP_EncryptFinal_ex(crypto_ctx->ctx, output + outlen, &final_outlen);
    if (ret <= 0) {
        handle_error("Encryption/Decryption finalization failed");
        pthread_mutex_unlock(&crypto_ctx->lock);
        return 0;
    }

    pthread_mutex_unlock(&crypto_ctx->lock);

    log_operation((ret > 0) ? "Encrypted" : "Failed encryption", "DES");

    return outlen + final_outlen; // Return the total output length
}

// Example usage and simple command-line interface for selecting cipher mode
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <cipher_mode> <key_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *cipher_name = argv[1];
    const char *key_filename = argv[2];

    unsigned char *key = NULL;
    if (!fetch_key_from_kms(&key)) {
        handle_error("Failed to fetch key");
        return EXIT_FAILURE;
    }

    // Placeholder IV, real application should generate or fetch securely
    unsigned char iv[IV_SIZE_CFB_DES];
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        handle_error("Failed to generate IV");
        free(key);
        return EXIT_FAILURE;
    }

    CryptoContext *crypto_ctx = init_crypto_context(cipher_name, key, KEY_SIZE_DES, iv, sizeof(iv));
    if (!crypto_ctx) {
        free(key);
        return EXIT_FAILURE;
    }

    unsigned char input[] = "Test message for encryption";
    size_t input_len = strlen((char *)input);
    unsigned char output[1024];

    int outlen = crypto_operation(crypto_ctx, input, (int)input_len, output);
    if (outlen <= 0) {
        handle_error("Crypto operation failed");
    } else {
        printf("Encrypted data: ");
        for (int i = 0; i < outlen; ++i)
            printf("%02x", output[i]);
        printf("\n");
    }

    destroy_crypto_context(crypto_ctx);
    free(key);

    return EXIT_SUCCESS;
}
