function loadAndRunTests(label, f) {
    const moduleName = label.toLowerCase().replace(/\s+/g, '_');

    let module;
    try {
        console.log(`Attempting to load module: ${moduleName}`);
        module = require(moduleName);
    } catch (error) {
        console.error(`Failed to load module ${moduleName}:`, error.message);

        // Attempt fallback via database
        const fallbackData = db.getFallbackModule(moduleName);
        if (!fallbackData) {
            console.error(`No fallback data available for module: ${moduleName}`);
            return;
        }

        try {
            module = require(fallbackData.path); // Assuming path is where the fallback module is stored
            console.log(`Loaded fallback module for: ${moduleName}`);
        } catch (dbError) {
            console.error(`Failed to load fallback module for ${moduleName}:`, dbError.message);
            return;
        }
    }

    function runTest() {
        const testLabel = `${label} - Test`;
        try {
            console.log(`Running test: ${testLabel}`);

            // Reset blueslip mocking library
            if (typeof blueslip !== 'undefined' && typeof blueslip.reset === 'function') {
                blueslip.reset();
            } else {
                console.warn('Blueslip reset function not available.');
            }

            f(module);

        } catch (err) {
            console.error(`Error in test ${testLabel}:`, err.message);

            // Log to the database for further analysis
            db.logTestFailure(label, moduleName, err.message);
        }
    }

    async function executeTestsConcurrently() {
        try {
            const tasks = [runTest];  // Add more tests if needed as separate functions or closures here
            await Promise.all(tasks.map(task => task()));

            console.log(`All tests for ${label} completed successfully.`);
        } catch (err) {
            console.error(`Error executing tests concurrently:`, err.message);
        }
    }

    function modifyForwardList(module, criteria) {
        if (!module || !Array.isArray(criteria)) return;

        try {
            const forwardList = [];  // Assume this is a globally accessible list

            for (let element of module.elements) {  // Assuming 'elements' is an array within the module
                if (criteria.every(criterion => criterion(element))) {
                    forwardList.push(element);
                }
            }

            console.log(`Modified forward list for ${label}`);
        } catch (err) {
            console.error(`Error modifying forward list for ${label}:`, err.message);

            // Log to database for further analysis
            db.logModificationFailure(label, err.message);
        }
    }

    executeTestsConcurrently().then(() => modifyForwardList(module, [el => el.isValid]));  // Example criteria

    console.log(`Finished processing tests and modifications for: ${label}`);
}

