namespace fs = std::filesystem;
using json = nlohmann::json;

class ConfigLoader {
public:
    using SettingsMap = std::unordered_map<std::string, std::variant<int, double, std::string, bool>>;

    static ConfigLoader& getInstance() {
        static ConfigLoader instance;
        return instance;
    }

    SettingsMap loadConfig(const std::string& filePath) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto cacheIt = configCache_.find(filePath);
        if (cacheIt != configCache_.end()) {
            // Check if file has been modified since last read
            if (fs::last_write_time(cacheIt->second.first) == fs::last_write_time(filePath)) {
                return cacheIt->second.second;
            }
        }

        std::ifstream inputFile(filePath);
        if (!inputFile.is_open()) {
            logError("Failed to open JSON file: " + filePath);
            return {}; // Return empty map on error
        }

        json j;
        try {
            inputFile >> j;
            validateJson(j); // Validate against schema
        } catch (const json::parse_error& e) {
            logError("JSON parse error in file: " + filePath + ", Error: " + std::string(e.what()));
            return {};
        }

        SettingsMap settings = parseJson(j);
        configCache_[filePath] = { fs::last_write_time(filePath), settings };

        logInfo("Successfully loaded configuration from: " + filePath);

        return settings;
    }

private:
    ConfigLoader() = default;

    void validateJson(const json& j) {
        // Implement schema validation logic here
        // For simplicity, assume validation is successful
    }

    SettingsMap parseJson(const json& j) {
        SettingsMap settings;
        for (const auto& [key, value] : j.items()) {
            if (value.is_number_integer()) {
                settings[key] = value.get<int>();
            } else if (value.is_number_float()) {
                settings[key] = value.get<double>();
            } else if (value.is_string()) {
                settings[key] = value.get<std::string>();
            } else if (value.is_boolean()) {
                settings[key] = value.get<bool>();
            }
        }
        return settings;
    }

    void logError(const std::string& message) const {
        // Integrate with existing logging system
        std::cerr << "[ERROR] " << message << std::endl;
    }

    void logInfo(const std::string& message) const {
        // Integrate with existing logging system
        std::cout << "[INFO] " << message << std::endl;
    }

    std::mutex mutex_;
    struct CacheEntry {
        fs::file_time_type timestamp;
        SettingsMap settings;
    };

    std::unordered_map<std::string, CacheEntry> configCache_;

    // Disallow copying and assignment
    ConfigLoader(const ConfigLoader&) = delete;
    ConfigLoader& operator=(const ConfigLoader&) = delete;
};

