```csharp
using System;
using System.Data;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;

public class FileHasherCSharp
{
    public async Task<string> CalculateMD5HashFromFileAsync(string filePath)
    {
        using (var md5 = new System.Security.Cryptography.MD5CryptoServiceProvider())
        {
            try
            {
                byte[] fileBytes = await ReadFileInChunksAsync(filePath);
                return BitConverter.ToString(md5.ComputeHash(fileBytes)).Replace("-", "").ToLowerInvariant();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error calculating hash: {ex.Message}");
                return null;
            }
        }
    }

    private async Task<byte[]> ReadFileInChunksAsync(string filePath)
    {
        var fileBytes = new System.Collections.Generic.List<byte>();
        using (var stream = await System.IO.File.OpenReadAsync(filePath))
        {
            const int bufferSize = 8192; // 8 KB chunks
            byte[] buffer = new byte[bufferSize];
            int bytesRead;
            while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                fileBytes.AddRange(buffer.AsSpan(0, bytesRead));
            }
        }
        return fileBytes.ToArray();
    }

    public async Task<DataTableReader> ExecuteQueryAndReturnResultAsync(byte[] queryData, string connectionString)
    {
        try
        {
            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(queryData))
                {
                    command.Connection = connection;
                    var reader = await command.ExecuteReaderAsync();
                    return reader.AsDataSet().Tables[0].CreateDataReader(); // Assuming result is in first table
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error executing query: {ex.Message}");
            throw;
        }
    }
}
