public class UserProcessor {

    private static final Logger logger = LoggerFactory.getLogger(UserProcessor.class);

    public static List<User> readCsvFile(String filePath) {
        List<User> users = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] values = line.split(",");
                if (values.length == 3) {
                    User user = new User(values[0], values[1], Integer.parseInt(values[2]));
                    users.add(user);
                } else {
                    logger.error("Invalid CSV format: " + line);
                }
            }
        } catch (IOException e) {
            logger.error("Error reading file", e);
        }
        return users;
    }

    public static void fetchUserDetails(ApiClient apiClient, List<User> users) {
        for (User user : users) {
            try {
                UserDetails userDetails = apiClient.fetchUserDetails(user.getEmail());
                user.setAddress(userDetails.getAddress());
                user.setPhoneNumber(userDetails.getPhoneNumber());
            } catch (Exception e) {
                logger.error("Error fetching details for " + user.getEmail(), e);
            }
        }
    }

    public static void printOldestUser(List<User> users) {
        if (!users.isEmpty()) {
            User oldest = users.stream()
                    .max(Comparator.comparingInt(User::getAge))
                    .orElseThrow(() -> new RuntimeException("No valid users found"));
            System.out.println("Oldest user: " + oldest);
        } else {
            logger.warn("User list is empty");
        }
    }

    public static void main(String[] args) {
        List<User> users = readCsvFile("users.csv");
        ApiClient apiClient = new RealApiClient(); // Assume this is the real API client
        fetchUserDetails(apiClient, users);
        printOldestUser(users);
    }
}

