// Function to append a slash if the string length is within size limit
char* append_slash_if_within_limit(const char *input, size_t size_limit) {
    size_t input_length = strlen(input);

    // Check if appending a slash would exceed the size limit
    if (input_length + 1 > size_limit) {
        return NULL;
    }

    // Allocate memory for new string with additional slash and null terminator
    char *result = malloc(size_limit + 1); 
    if (!result) {
        return NULL; // Allocation failed
    }

    // Copy input to result and append a slash at the end
    strcpy(result, input);
    strcat(result, "/");

    return result;
}
