```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "zlib.h"
#include "bzlib.h"
#include "tar.h" // Assume this is a library for handling .tar.gz files
#include "rar.h" // Assume this is a library for handling .rar files

// Error logging mechanism
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Mutex for thread safety
pthread_mutex_t resource_bundle_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    void *data;
    size_t length;
} ResourceData;

typedef struct {
    const char *filename;
    int format; // 0: ZIP, 1: BZIP2, 2: TAR.GZ, 3: RAR
} CompressionFormat;

// Function to load resource bundle from a file
ResourceData* load_resource_bundle(const char *filepath, int compression_format) {
    if (filepath == NULL) return NULL;

    pthread_mutex_lock(&resource_bundle_lock);

    FILE *file = fopen(filepath, "rb");
    if (!file) {
        log_error("Failed to open file");
        pthread_mutex_unlock(&resource_bundle_lock);
        return NULL;
    }

    ResourceData *bundle_data = malloc(sizeof(ResourceData));
    if (!bundle_data) {
        fclose(file);
        log_error("Memory allocation failed for resource data");
        pthread_mutex_unlock(&resource_bundle_lock);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    bundle_data->data = malloc(file_size);
    if (!bundle_data->data) {
        log_error("Memory allocation failed for resource data buffer");
        free(bundle_data);
        fclose(file);
        pthread_mutex_unlock(&resource_bundle_lock);
        return NULL;
    }

    fread(bundle_data->data, 1, file_size, file);
    fclose(file);

    // Decompression based on the format
    switch (compression_format) {
        case 0: { // ZIP
            unzFile uf = unzOpenMem((unsigned char*)bundle_data->data, file_size);
            if (!uf) {
                log_error("Failed to open zip archive");
                free(bundle_data->data);
                free(bundle_data);
                pthread_mutex_unlock(&resource_bundle_lock);
                return NULL;
            }
            // Handle ZIP decompression...
        } break;

        case 1: { // BZIP2
            int result = BZ2_bzBuffToBuffDecompress((char *)bundle_data->data, &file_size,
                                                     (char *)bundle_data->data, file_size, 0, NULL);
            if (result != BZ_OK) {
                log_error("BZIP2 decompression failed");
                free(bundle_data->data);
                free(bundle_data);
                pthread_mutex_unlock(&resource_bundle_lock);
                return NULL;
            }
        } break;

        case 2: { // TAR.GZ
            int result = tar_gz_decompress((char *)bundle_data->data, &file_size);
            if (result != TAR_GZ_SUCCESS) {
                log_error("TAR.GZ decompression failed");
                free(bundle_data->data);
                free(bundle_data);
                pthread_mutex_unlock(&resource_bundle_lock);
                return NULL;
            }
        } break;

        case 3: { // RAR
            int result = rar_decompress((char *)bundle_data->data, &file_size);
            if (result != RAR_SUCCESS) {
                log_error("RAR decompression failed");
                free(bundle_data->data);
                free(bundle_data);
                pthread_mutex_unlock(&resource_bundle_lock);
                return NULL;
            }
        } break;

        default:
            log_error("Unsupported compression format");
            free(bundle_data->data);
            free(bundle_data);
            pthread_mutex_unlock(&resource_bundle_lock);
            return NULL;
    }

    bundle_data->length = file_size; // Adjusted after decompression

    pthread_mutex_unlock(&resource_bundle_lock);

    return bundle_data;
}

// Function to free the resource data
void free_resource_bundle(ResourceData *bundle_data) {
    if (bundle_data && bundle_data->data) {
        free(bundle_data->data);
        free(bundle_data);
    }
}

// Sample unit test function for validation
void test_load_resource_bundle() {
    const char *test_file_zip = "test.zip";
    ResourceData *zip_data = load_resource_bundle(test_file_zip, 0);

    if (zip_data) {
        printf("Loaded ZIP resource bundle of size: %zu\n", zip_data->length);
        free_resource_bundle(zip_data);
    } else {
        log_error("Failed to load ZIP resource bundle");
    }

    // Add additional test cases for BZIP2, TAR.GZ, RAR...
}

int main() {
    test_load_resource_bundle();
    return 0;
}
```

### Notes:
- This code assumes the existence of libraries for handling `.tar.gz` and `.rar` formats (`tar.h`, `rar.h`) which you would need to implement or link against.
- Error logging is basic; consider integrating with a more robust logging framework if needed.
- The decompression logic for ZIP, BZIP2, TAR.GZ, and RAR are placeholders. You should fill in the actual decompression routines using appropriate libraries like zlib, bzip2, etc.
- The function `load_resource_bundle` is designed to handle different formats by passing an integer indicating the format type.
- Thread safety is ensured using a mutex lock around critical sections.
