// Mock function to simulate database fetch
bool fetchFromDatabase(int *rx_ue_tag, int *rnti, const char *db_conn_details) {
    // Simulate fetching data from the database
    if (rand() % 2 == 0) { // Random failure simulation
        return false;
    }
    *rx_ue_tag = rand();
    *rnti = rand();
    return true;
}

void logError(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void logInfo(const char *message) {
    printf("INFO: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateList(size_t num_elements, const char *db_conn_details, bool enable_logging) {
    if (num_elements <= 0 || num_elements > MAX_ELEMENTS) {
        logError("Invalid number of elements specified.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        logError("Memory allocation failed.");
        return NULL;
    }

    pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_elements; ++i) {
        int rx_ue_tag, rnti;
        pthread_mutex_lock(&db_lock);
        if (!fetchFromDatabase(&rx_ue_tag, &rnti, db_conn_details)) {
            logError("Failed to fetch data from database.");
            free(list);
            return NULL;
        }
        pthread_mutex_unlock(&db_lock);

        list[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
        list[i].RNTI = rnti;

        int crcflag = rand() % 3; // Randomly set CRCFLAG to 0, 1, or 2
        if (crcflag != 0 && crcflag != 1) {
            if (enable_logging) logError("Invalid CRCFLAG value encountered.");
            continue;
        }

        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        if (enable_logging) {
            logInfo("Populated element with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d",
                    rx_ue_tag, rnti, crcflag);
        }
    }

    pthread_mutex_destroy(&db_lock);
    return list;
}

void freeList(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <num_elements> <db_conn_details> <enable_logging>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_elements = strtoul(argv[1], NULL, 10);
    const char *db_conn_details = argv[2];
    bool enable_logging = atoi(argv[3]);

    NFAPI_CRC_INDICATION_PDU_T* list = createAndPopulateList(num_elements, db_conn_details, enable_logging);

    if (list) {
        // Use the list for further processing
        freeList(list);
    }

    return EXIT_SUCCESS;
}
