```csharp
using System;
using System.Diagnostics;
using System.IO;
using System.Collections.Concurrent;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class WebsiteManager
{
    private static readonly ConcurrentDictionary<string, Process> RunningSites = new();
    private IConfiguration Configuration { get; }
    private ILogger Logger { get; }

    public WebsiteManager(IConfiguration configuration, ILogger<WebsiteManager> logger)
    {
        Configuration = configuration;
        Logger = logger;
    }

    public string AddAndStartSite(string directoryPath, string siteName)
    {
        if (string.IsNullOrWhiteSpace(directoryPath) || !Directory.Exists(directoryPath))
        {
            LogAction($"Invalid or non-existent directory path: {directoryPath}");
            return "The specified directory path is invalid.";
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            LogAction("Missing web.config file.");
            return null;
        }

        if (IsSiteRunning(siteName))
        {
            LogAction($"Site {siteName} is already running.");
            return $"{siteName} is already running.";
        }

        string serverType = DetectWebServer(directoryPath);

        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = GetProcessExecutable(serverType),
                Arguments = BuildArguments(directoryPath, siteName, serverType)
            };

            Process process = new()
            {
                EnableRaisingEvents = true,
                StartInfo = startInfo
            };
            process.Exited += (sender, args) => OnProcessExited(sender as Process);
            RunningSites.TryAdd(siteName, process);

            if (!process.Start())
            {
                LogAction($"Failed to start site {siteName}: {process.StandardError.ReadToEnd()}");
                return $"Failed to start site {siteName} due to an error.";
            }

            LogAction($"Started site {siteName} successfully.");
            ConfigurationManager.AddSiteDetails(directoryPath, siteName);
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error starting website");
            LogAction("Error occurred while trying to start the website.");
            return $"An error occurred: {ex.Message}";
        }

        return null;
    }

    private void OnProcessExited(Process process)
    {
        if (process != null && RunningSites.TryRemove(process.StartInfo.Arguments.Split(' ')[1], out _))
        {
            LogAction($"Process for {process.StartInfo.Arguments.Split(' ')[1]} has exited.");
        }
    }

    private bool IsSiteRunning(string siteName) => RunningSites.ContainsKey(siteName);

    private string DetectWebServer(string directoryPath)
    {
        if (File.Exists(Path.Combine(directoryPath, "applicationHost.config")))
            return "IIS";
        else if (File.Exists(Path.Combine(directoryPath, "httpd.conf")))
            return "Apache";

        return null;
    }

    private string GetProcessExecutable(string serverType) =>
        serverType == "IIS" ? "iisreset.exe" : "httpd.exe";

    private string BuildArguments(string directoryPath, string siteName, string serverType)
    {
        if (serverType == "IIS")
            return $"/start /site:{siteName}";

        // Placeholder for Apache process arguments
        return $"-f {directoryPath}/httpd.conf -k start";
    }

    private void LogAction(string message) => Logger.LogInformation(message);

    public void ShutdownAllSites()
    {
        foreach (var kvp in RunningSites)
        {
            if (!kvp.Value.HasExited)
                kvp.Value.Kill();
            LogAction($"Shutdown site {kvp.Key}");
        }
        RunningSites.Clear();
    }
}

public static class ConfigurationManager
{
    private static readonly ConcurrentDictionary<string, (string DirectoryPath, string SiteName)> Sites = new();

    public static void AddSiteDetails(string directoryPath, string siteName)
    {
        Sites.TryAdd(siteName, (directoryPath, siteName));
    }

    public static (string DirectoryPath, string SiteName)? GetSiteDetails(string siteName) =>
        Sites.TryGetValue(siteName, out var details) ? (details.DirectoryPath, details.SiteName) : null;
}

// Unit tests would be implemented using a testing framework like NUnit or xUnit.
// Example test methods could include:
/*
