        self.cache_size = cache_size

    def get_md5(self, image_path):
        hasher = hashlib.md5()
        with open(image_path, 'rb') as img_file:
            buf = img_file.read()
            hasher.update(buf)
        return hasher.hexdigest()

    def validate_image_metadata(self, image_path):
        try:
            with Image.open(image_path) as img:
                width, height = img.size
                format = img.format
            if not (format in ['JPEG', 'PNG']):
                raise ValueError("Unsupported image format")
            logger.debug(f"Image metadata: {width}x{height}, Format: {format}")
        except Exception as e:
            logger.error(f"Metadata validation error: {e}")
            raise

    def cache_image(self, md5_hash, data):
        if len(self.cache) >= self.cache_size:
            self.cache.pop(next(iter(self.cache)))  # Remove oldest entry
        self.cache[md5_hash] = data

    def process_image(self, image_path, transformation_params):
        with Image.open(image_path) as img:
            for param, value in transformation_params.items():
                if hasattr(img, param):
                    getattr(img, f"{param}")(value)
            byte_arr = BytesIO()
            img.save(byte_arr, format=img.format)
            return byte_arr.getvalue()

