    def imageProcessorService(self, image_path, transformation_params, target_service):
        md5_hash = self.get_md5(image_path)

        if md5_hash in self.cache:
            logger.info(f"Using cached version for: {md5_hash}")
            return self.cache[md5_hash]

        self.validate_image_metadata(image_path)

