```c
#include <openssl/evp.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, ERR_error_string(ERR_get_error(), NULL));
}

// Function to load cryptographic primitives based on configuration file
int load_crypto_primitives(const char *config_file) {
    CONF *conf = NULL;
    const CONF_VALUE *val = NULL;
    int ret = 0;

    // Initialize OpenSSL
    OpenSSL_add_all_algorithms();

    // Load the configuration file
    conf = CONF_new();
    if (!conf || !CONF_load(conf, config_file, NULL)) {
        handle_error("Failed to load configuration");
        return -1;
    }

    // Iterate through sections and options in the configuration file
    for (const char *section_name = "openssl"; section_name; 
         section_name = OBJ_nid2sn(OBJ_txt2nid(section_name))) {

        for (val = conf_get_section(conf, section_name); val != NULL; val = val->next) {

            if (strcmp(val->name, "crypto") == 0 && strcmp(val->data, "dynamic") == 0) {
                // Enable dynamic engine loading
                ENGINE_load_builtin_engines();
            } else if (strncmp(val->name, "dynamic_", 8) == 0) {
                const char *cipher_name = val->name + 8;

                // Load each specified primitive dynamically
                if (!ENGINE_by_id(cipher_name)) {
                    handle_error("Failed to load engine");
                    ret = -1;
                }
            }

            // Additional configurations can be added here for other primitives

        }
    }

    CONF_free(conf);
    return ret;
}

// Main function for testing the loading of cryptographic primitives
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int result = load_crypto_primitives(argv[1]);

    // Check for errors during the loading process
    if (result != 0) {
        handle_error("Error in loading cryptographic primitives");
        EVP_cleanup();
        ERR_free_strings();
        exit(EXIT_FAILURE);
    }

    printf("Successfully loaded cryptographic primitives.\n");

    // Cleanup OpenSSL before exiting
    EVP_cleanup();
    ERR_free_strings();

    return EXIT_SUCCESS;
}
```

