using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.XPath;
using MongoDB.Bson;
using MongoDB.Driver;

namespace IoTDeviceDataProcessor
{
    public class DeviceDataProcessor
    {
        private readonly IMongoCollection<BsonDocument> _collection;
        private static ConcurrentQueue<string> _xmlDocuments = new ConcurrentQueue<string>();

        public DeviceDataProcessor(string connectionString, string databaseName, string collectionName)
        {
            var client = new MongoClient(connectionString);
            var database = client.GetDatabase(databaseName);
            _collection = database.GetCollection<BsonDocument>(collectionName);
        }

        public void AddXmlDocument(string xmlContent)
        {
            _xmlDocuments.Enqueue(xmlContent);
        }

        public async Task ProcessDocumentsAsync()
        {
            while (!_xmlDocuments.IsEmpty || IsProcessing())
            {
                if (_xmlDocuments.TryDequeue(out string xmlContent))
                {
                    try
                    {
                        var document = new XmlDocument();
                        document.LoadXml(xmlContent);

                        var sensorReadings = ExtractSensorData(document);
                        await StoreInDatabaseAsync(sensorReadings);
                    }
                    catch (Exception ex)
                    {
                        // Log and handle exceptions (e.g., XML parsing errors, network issues)
                        Console.WriteLine($"Error processing document: {ex.Message}");
                    }
                }

                // Simulate waiting for new documents
                await Task.Delay(100);
            }
        }

        private IDictionary<string, object> ExtractSensorData(XmlDocument xmlDoc)
        {
            var sensorReadings = new ConcurrentDictionary<string, object>();

            try
            {
                var deviceNodes = xmlDoc.SelectNodes("//Device");
                foreach (XmlNode node in deviceNodes)
                {
                    string deviceId = node.Attributes["id"]?.Value;
                    if (!string.IsNullOrEmpty(deviceId))
                    {
                        // Extract the most recent reading using XPath
                        var readingNode = node.SelectSingleNode(".//Reading[last()]");
                        if (readingNode != null)
                        {
                            var timestamp = readingNode.Attributes["timestamp"]?.Value;
                            var value = readingNode.InnerText;

                            sensorReadings[deviceId] = new { Timestamp = timestamp, Value = value };
                        }
                    }
                }
            }
            catch (XPathException ex)
            {
                // Handle discrepancies in XML structure
                Console.WriteLine($"XPath error: {ex.Message}");
            }

            return sensorReadings.ToDictionary(kvp => kvp.Key, kvp => BsonDocument.Parse(BsonSerializer.SerializeToBson(new BsonDocument("Timestamp", kvp.Value.Timestamp), new BsonDocument("Value", kvp.Value))))
                                .Select(kvp => BsonDocument
                                    .Create(
                                        "DeviceId", kvp.Key,
                                        "SensorData", kvp.Value));
        }

        private async Task StoreInDatabaseAsync(IEnumerable<BsonDocument> sensorReadings)
        {
            try
            {
                if (sensorReadings.Any())
                {
                    await _collection.InsertManyAsync(sensorReadings);
                }
            }
            catch (MongoException ex)
            {
                // Handle database connectivity issues
                Console.WriteLine($"Database error: {ex.Message}");
            }
        }

        private bool IsProcessing()
        {
            return Task.Run(async () => await ProcessDocumentsAsync()).IsCompleted;
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var processor = new DeviceDataProcessor("your-mongodb-connection-string", "IoTDatabase", "SensorReadings");

            // Simulate adding XML documents to the queue
            processor.AddXmlDocument("<Devices><Device id='1'><Reading timestamp='2023-10-01T12:00:00'>24.5</Reading></Device></Devices>");

            await processor.ProcessDocumentsAsync();
        }
    }
}
```

### Key Considerations:
- **Concurrency**: The use of `ConcurrentQueue` and `ConcurrentDictionary` helps manage concurrent access.
- **Error Handling**: Basic error handling is included for XML parsing, XPath issues, and database operations. More comprehensive logging should be implemented in production.
- **Scalability**: MongoDB provides scalability and flexibility to handle large volumes of data.
- **Maintainability**: The code structure allows for easy extension, such as adding machine learning models for anomaly detection or handling dynamic updates.
- **Optimization**: Consider using async/await patterns and optimizing XPath queries based on your specific XML structures.

