import java.util.concurrent.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.io.IOException;
import java.util.logging.Logger;

public class DynamicCloudStorageManager {
    private static final Logger logger = Logger.getLogger(DynamicCloudStorageManager.class.getName());
    private final ExecutorService executorService;
    private final CloudStorageProviderSelector providerSelector;
    private final MetadataCache metadataCache;

    public DynamicCloudStorageManager() {
        this.executorService = Executors.newCachedThreadPool();
        this.providerSelector = new CloudStorageProviderSelector();
        this.metadataCache = new InMemoryMetadataCache(); // Implement caching strategy
    }

    public CompletableFuture<Void> uploadFile(Path filePath, String contentType) {
        return CompletableFuture.supplyAsync(() -> {
            validateFile(filePath);
            String providerName = providerSelector.selectProvider(fileCriteria());

            try (CloudStorageProvider provider = CloudStorageProviderFactory.getProvider(providerName)) {
                logger.info("Uploading file to " + providerName);
                return provider.uploadFile(filePath, contentType);
            } catch (Exception e) {
                logger.severe("Upload failed: " + e.getMessage());
                throw new CompletionException(e);
            }
        }, executorService);
    }

    public CompletableFuture<Path> downloadFile(String fileId) {
        return CompletableFuture.supplyAsync(() -> {
            String providerName = providerSelector.selectProvider(fileCriteria());

            try (CloudStorageProvider provider = CloudStorageProviderFactory.getProvider(providerName)) {
                logger.info("Downloading file from " + providerName);
                return provider.downloadFile(fileId, metadataCache);
            } catch (Exception e) {
                logger.severe("Download failed: " + e.getMessage());
                throw new CompletionException(e);
            }
        }, executorService);
    }

    private void validateFile(Path filePath) throws IOException {
        String hash = calculateSHA256(filePath);
        if (!metadataCache.containsHash(hash)) {
            metadataCache.storeMetadata(filePath, hash);
        }
        // Add further validation logic as needed
    }

    private String fileCriteria() {
        // Implement logic to determine criteria for selecting provider
        return "default";
    }

    private static String calculateSHA256(Path filePath) throws IOException {
        try (MessageDigest digest = MessageDigest.getInstance("SHA-256")) {
            Files.stream(filePath, 0, Long.MAX_VALUE)
                 .map(byteBuffer -> byteBuffer.array())
                 .forEach(digest::update);
            return bytesToHex(digest.digest());
        }
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    // Shutdown the executor service on application exit
    public void shutdown() {
        executorService.shutdown();
    }

    // CloudStorageProvider and its implementations for AWS S3, Azure Blob Storage, Google Cloud Storage

    // MetadataCache interface and InMemoryMetadataCache implementation

    // ProviderSelector interface and CloudStorageProviderSelector implementation

    // Factory class for creating CloudStorageProvider instances
}
