```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENV_VARS 100
#define ENV_VAR_SIZE 256

typedef struct {
    char key[ENV_VAR_SIZE];
    char value[ENV_VAR_SIZE];
} EnvVar;

EnvVar env_vars[MAX_ENV_VARS];
int env_var_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    pthread_mutex_lock(&lock);
    printf("[%s] ERROR: %s\n", __TIME__, message);
    pthread_mutex_unlock(&lock);
}

void parse_tiff_image(const char *file_path, int *bits_per_sample, int *samples_per_pixel) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        log_error("Failed to open TIFF file.");
        return;
    }

    unsigned short byte_order;
    fread(&byte_order, sizeof(byte_order), 1, file);

    if (byte_order == 0x4949) { // Little-endian
        int offset = 0x002A; // Assuming standard TIFF header
        fseek(file, offset, SEEK_SET);
        unsigned short count;
        fread(&count, sizeof(count), 1, file);

        for (int i = 0; i < count; ++i) {
            unsigned short tag;
            fread(&tag, sizeof(tag), 1, file);

            if (tag == 0x0103) { // BitsPerSample
                unsigned short bits_per_sample_count;
                fread(&bits_per_sample_count, sizeof(bits_per_sample_count), 1, file);
                unsigned int offset_to_bits_per_sample;
                fread(&offset_to_bits_per_sample, sizeof(offset_to_bits_per_sample), 1, file);

                fseek(file, offset + offset_to_bits_per_sample, SEEK_SET);
                for (int j = 0; j < bits_per_sample_count; ++j) {
                    unsigned short sample_value;
                    fread(&sample_value, sizeof(sample_value), 1, file);
                    if (i == 0) *bits_per_sample = sample_value;
                }
            } else if (tag == 0x0115) { // SamplesPerPixel
                fseek(file, offset + 8, SEEK_SET); // Offset to value
                fread(samples_per_pixel, sizeof(unsigned short), 1, file);
            }
        }

        fclose(file);

        if (*bits_per_sample != 1 && *bits_per_sample != 2 &&
            *bits_per_sample != 4 && *bits_per_sample != 8 && *bits_per_sample != 16) {
            log_error("Unsupported bits per sample.");
        }
    } else {
        log_error("Unsupported TIFF byte order.");
    }
}

void read_env_vars_from_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) return;

    char line[ENV_VAR_SIZE];
    while (fgets(line, sizeof(line), file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key && value) {
            pthread_mutex_lock(&lock);

            for (int i = 0; i < env_var_count; ++i) {
                if (strcmp(env_vars[i].key, key) == 0) {
                    strcpy(env_vars[i].value, value);
                    pthread_mutex_unlock(&lock);
                    return;
                }
            }

            if (env_var_count < MAX_ENV_VARS) {
                strncpy(env_vars[env_var_count].key, key, ENV_VAR_SIZE - 1);
                strncpy(env_vars[env_var_count].value, value, ENV_VAR_SIZE - 1);
                env_var_count++;
            }

            pthread_mutex_unlock(&lock);
        }
    }

    fclose(file);
}

void get_env_var(const char *key, char *buffer, size_t buffer_size) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < env_var_count; ++i) {
        if (strcmp(env_vars[i].key, key) == 0) {
            strncpy(buffer, env_vars[i].value, buffer_size);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Default values
    if (strcmp(key, "DB_ENV") == 0) strcpy(buffer, "production");
    else if (strcmp(key, "CACHE_TYPE") == 0) strcpy(buffer, "redis");

    pthread_mutex_unlock(&lock);
}

void initialize_database_connection() {
    char db_env[ENV_VAR_SIZE];
    get_env_var("DB_ENV", db_env, sizeof(db_env));

    // Pseudo code for database connection based on environment
    if (strcmp(db_env, "development") == 0) {
        printf("Connecting to development database...\n");
    } else if (strcmp(db_env, "testing") == 0) {
        printf("Connecting to testing database...\n");
    } else {
        printf("Connecting to production database...\n");
    }
}

void initialize_caching_mechanism() {
    char cache_type[ENV_VAR_SIZE];
    get_env_var("CACHE_TYPE", cache_type, sizeof(cache_type));

    if (strcmp(cache_type, "redis") == 0) {
        printf("Initializing Redis caching mechanism...\n");
    } else if (strcmp(cache_type, "memcached") == 0) {
        printf("Initializing Memcached...\n");
    }
}

void initialize_application() {
    read_env_vars_from_file(".env");

    char db_name[ENV_VAR_SIZE], host[ENV_VAR_SIZE], port[ENV_VAR_SIZE],
         user[ENV_VAR_SIZE], password[ENV_VAR_SIZE];

    get_env_var("DB_NAME", db_name, sizeof(db_name));
    get_env_var("DB_HOST", host, sizeof(host));
    get_env_var("DB_PORT", port, sizeof(port));
    get_env_var("DB_USER", user, sizeof(user));
    get_env_var("DB_PASSWORD", password, sizeof(password));

    printf("Database: %s, Host: %s, Port: %s, User: %s\n",
           db_name, host, port, user);

    initialize_database_connection();
    initialize_caching_mechanism();

    // Additional initialization for third-party services and logging
}

int main() {
    initialize_application();

    int bits_per_sample, samples_per_pixel;
    parse_tiff_image("example.tiff", &bits_per_sample, &samples_per_pixel);

    printf("Bits per Sample: %d, Samples per Pixel: %d\n",
           bits_per_sample, samples_per_pixel);

    return 0;
}
