# payment_gateway.py

import logging
from abc import ABC, abstractmethod
import requests
from cachetools import TTLCache
from functools import wraps
import time

# Setup basic configuration for logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class PaymentGateway(ABC):
    @abstractmethod
    def process_transaction(self, amount, currency):
        pass

def retry_on_failure(max_retries=3, delay=2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_retries:
                try:
                    return func(*args, **kwargs)
                except requests.RequestException as e:
                    logger.error(f"Request failed: {e}")
                    time.sleep(delay)
                    attempts += 1
            raise Exception("Max retries reached")
        return wrapper
    return decorator

class PaymentProcessor:
    def __init__(self):
        self.cache = TTLCache(maxsize=100, ttl=300)  # Cache for 5 minutes
        self.api_requests_count = 0

    @retry_on_failure()
    def process(self, gateway: PaymentGateway, amount, currency):
        cache_key = (amount, currency)
        if cache_key in self.cache:
            logger.info("Cache hit")
            return self.cache[cache_key]

        logger.info("API request")
        result = gateway.process_transaction(amount, currency)
        self.api_requests_count += 1

        # Cache the result
        self.cache[cache_key] = result
        logger.info(f"Transaction processed: {result}")
        return result

class ExamplePaymentGateway(PaymentGateway):
    BASE_URL = "https://api.example.com/transaction"

    @retry_on_failure()
    def process_transaction(self, amount, currency):
        response = requests.post(self.BASE_URL, json={"amount": amount, "currency": currency})

        if response.status_code == 200:
            return response.json()
        elif response.status_code in {500, 502, 503, 504}:
            logger.warning(f"Server error: {response.status_code}")
            raise requests.RequestException("Temporary server issue")
        else:
            response.raise_for_status()

# plugin_manager.py

class PaymentGatewayPluginManager:
    def __init__(self):
        self.gateways = {}

    def register_gateway(self, name, gateway_cls):
        if not issubclass(gateway_cls, PaymentGateway):
            raise ValueError("Gateway must be a subclass of PaymentGateway")
        self.gateways[name] = gateway_cls

    def get_gateway(self, name):
        return self.gateways.get(name)()

# main.py

if __name__ == "__main__":
    manager = PaymentGatewayPluginManager()
    manager.register_gateway("example", ExamplePaymentGateway)

    processor = PaymentProcessor()

    try:
        result = processor.process(manager.get_gateway("example"), 100, "USD")
        print(result)
    except Exception as e:
        logger.error(f"Failed to process transaction: {e}")

# tests.py

import unittest
from unittest.mock import patch, MagicMock
from payment_processor import PaymentProcessor
from plugin_manager import PaymentGatewayPluginManager

class TestPaymentProcessing(unittest.TestCase):

    @patch('payment_gateway.requests.post')
    def test_process_transaction_success(self, mock_post):
        mock_response = MagicMock()
        mock_response.status_code = 200
        mock_response.json.return_value = {"status": "success"}
        mock_post.return_value = mock_response

        manager = PaymentGatewayPluginManager()
        manager.register_gateway("test", ExamplePaymentGateway)

        processor = PaymentProcessor()

        result = processor.process(manager.get_gateway("test"), 100, "USD")

        self.assertEqual(result["status"], "success")

    @patch('payment_gateway.requests.post')
    def test_process_transaction_failure(self, mock_post):
        mock_response = MagicMock()
        mock_response.status_code = 400
        mock_post.return_value = mock_response

        manager = PaymentGatewayPluginManager()
        manager.register_gateway("test", ExamplePaymentGateway)

        processor = PaymentProcessor()

        with self.assertRaises(requests.HTTPError):
            processor.process(manager.get_gateway("test"), 100, "USD")

    @patch('payment_processor.requests.RequestException')
    def test_retry_mechanism(self, mock_request_exception):
        mock_request_exception.side_effect = requests.RequestException

        manager = PaymentGatewayPluginManager()
        manager.register_gateway("retry_test", ExamplePaymentGateway)

        processor = PaymentProcessor()

        with self.assertRaises(Exception) as context:
            processor.process(manager.get_gateway("retry_test"), 100, "USD")

        self.assertTrue('Max retries reached' in str(context.exception))

if __name__ == '__main__':
    unittest.main()
```

