```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Azure.Storage.Blobs;
using System.Runtime.Serialization.Formatters.Binary;

public class TransactionRecordV1 { /* Define fields for version 1 */ }
public class TransactionRecordV2 : TransactionRecordV1 { /* Define additional fields for version 2 */ }

public interface ITransactionDeserializer
{
    object Deserialize(byte[] data, int version);
}

public class TransactionDeserializer : ITransactionDeserializer
{
    public object Deserialize(byte[] data, int version)
    {
        switch (version)
        {
            case 1:
                using var ms = new MemoryStream(data);
                return new BinaryFormatter().Deserialize(ms) as TransactionRecordV1;
            case 2:
                using var ms2 = new MemoryStream(data);
                return new BinaryFormatter().Deserialize(ms2) as TransactionRecordV2;
            default:
                throw new NotSupportedException("Unsupported version");
        }
    }
}

public class DataValidator
{
    private readonly HttpClient _httpClient;

    public DataValidator(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<bool> ValidateAsync(object data)
    {
        try
        {
            var jsonContent = JsonConvert.SerializeObject(data);
            var response = await _httpClient.PostAsync("https://validation.service/validate", new StringContent(jsonContent));
            return response.IsSuccessStatusCode && (await response.Content.ReadAsStringAsync()) == "true";
        }
        catch (HttpRequestException ex) when (!ex.Message.Contains("503"))
        {
            // Handle network issues, retry logic can be implemented here
            Console.WriteLine($"Validation error: {ex.Message}");
            return false;
        }
    }
}

public class Logger
{
    public void Log(string message)
    {
        Console.WriteLine($"{DateTime.Now}: {message}");
    }

    public void Error(Exception ex)
    {
        Console.Error.WriteLine($"{DateTime.Now}: ERROR: {ex.Message}");
    }
}

public class TransactionProcessor
{
    private readonly BlobServiceClient _blobServiceClient;
    private readonly ITransactionDeserializer _deserializer;
    private readonly DataValidator _validator;
    private readonly Logger _logger;

    public TransactionProcessor(BlobServiceClient blobServiceClient, 
                                ITransactionDeserializer deserializer,
                                DataValidator validator,
                                Logger logger)
    {
        _blobServiceClient = blobServiceClient;
        _deserializer = deserializer;
        _validator = validator;
        _logger = logger;
    }

    public async Task ProcessFilesAsync(string containerName)
    {
        var client = _blobServiceClient.GetBlobContainerClient(containerName);
        var blobs = client.GetBlobs();

        ConcurrentBag<Task> tasks = new ConcurrentBag<Task>();

        foreach (var blob in blobs)
        {
            tasks.Add(Task.Run(async () =>
            {
                try
                {
                    _logger.Log($"Processing blob: {blob.Name}");
                    var stream = await blob.OpenReadAsync();
                    using var ms = new MemoryStream();
                    stream.CopyTo(ms);

                    // Assume a mechanism to get version number from metadata or filename
                    int version = GetVersion(blob.Metadata);

                    var data = _deserializer.Deserialize(ms.ToArray(), version);
                    bool isValid = await _validator.ValidateAsync(data);

                    if (isValid)
                    {
                        _logger.Log($"Blob {blob.Name} validated successfully.");
                    }
                    else
                    {
                        _logger.Error(new Exception($"Validation failed for blob: {blob.Name}"));
                    }
                }
                catch (Exception ex)
                {
                    _logger.Error(ex);
                }
            }));
        }

        await Task.WhenAll(tasks);
    }

    private int GetVersion(IDictionary<string, string> metadata) => Convert.ToInt32(metadata["version"] ?? "1");
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var logger = new Logger();
        var httpClient = new HttpClient();
        var validator = new DataValidator(httpClient);

        var blobServiceClient = new BlobServiceClient("YourAzureStorageConnectionString");
        var deserializer = new TransactionDeserializer();

        var processor = new TransactionProcessor(blobServiceClient, deserializer, validator, logger);

        await processor.ProcessFilesAsync("your-blob-container");

        httpClient.Dispose();
    }
}
```

### Key Points:
- **Versioning**: Handled by `ITransactionDeserializer` with different classes for each version.
- **Concurrency and Scalability**: Uses `ConcurrentBag<Task>` to process files concurrently.
- **Error Handling**: Includes try-catch blocks with logging of errors and exceptions.
- **External Validation Service**: Integrated using an HTTP client for REST API calls.
- **Resource Management**: Ensures disposal of streams and HTTP clients.
- **Logging**: Simple console-based logger implemented in the `Logger` class.

