// Hypothetical logging functions
void logError(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void logTruncation(const char* originalLength) {
    printf("INFO: Truncated string from length %s.\n", originalLength);
}

int safeStringCopy(char *dest, const char *src, size_t destSize) {
    if (dest == NULL || src == NULL || destSize == 0) {
        logError("Null pointer or zero-sized destination buffer provided.");
        return -1;
    }

    size_t srcLength = strlen(src);

    // Check for overflow and decide how many characters to copy
    if (srcLength >= destSize) {
        // Truncate the source string to fit in dest
        logTruncation(srcLength ? ((long long int)srcLength + 1): "0");
        strncpy(dest, src, destSize - 1);
        dest[destSize - 1] = '\0';  // Ensure null termination
        return (int)destSize;       // Return the full size including null terminator
    }

    // Copy string if it fits safely within destSize
    strcpy(dest, src); 
    return (int)(srcLength + 1);  // Include the null terminator in the count
}
```

