// server.js

const express = require('express');
const { ApolloServer, gql } = require('apollo-server-express');
const axios = require('axios');
const redis = require('ioredis');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const speakeasy = require('speakeasy');
const { Worker } = require('worker_threads');
const bodyParser = require('body-parser');

// Configuration and environment variables
require('dotenv').config();
const { PORT, OPENWEATHER_API_KEY, CLIMATE_API_KEY, REDIS_URL, JWT_SECRET } = process.env;

// Express setup
const app = express();
app.use(bodyParser.json());

// Rate limiter middleware
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});

// Redis client for caching
const redisClient = new redis(REDIS_URL);

// Authentication Middleware
function authenticateToken(req, res, next) {
  const token = req.headers['authorization'];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// MFA Verification
function verifyMfa(req, res, next) {
  const token = req.body.token;
  const verified = speakeasy.totp.verify({
    secret: req.user.mfaSecret,
    encoding: 'base32',
    token,
  });

  if (!verified) return res.status(403).json({ message: 'MFA verification failed' });

  next();
}

// GraphQL Schema
const typeDefs = gql`
  type Weather {
    condition: String
    temperature: Float
    description: String
  }

  type Query {
    getWeather(location: String!): Weather
    getClimateStats(location: String!, month: Int!): [Float]
  }
`;

// Resolvers
const resolvers = {
  Query: {
    async getWeather(_, { location }) {
      // Check cache first
      const cachedData = await redisClient.get(`weather:${location}`);
      if (cachedData) return JSON.parse(cachedData);

      // Fetch from external API
      try {
        const [openWeatherResponse, climateResponse] = await Promise.all([
          axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${location}&appid=${OPENWEATHER_API_KEY}`),
          axios.get(`https://climate.api/location/${location}`, {
            headers: { 'Authorization': `Bearer ${CLIMATE_API_KEY}` }
          })
        ]);

        const weatherData = openWeatherResponse.data;
        const climateData = climateResponse.data;

        // Combine data and cache result
        const combinedData = {
          condition: weatherData.weather[0].main,
          temperature: (weatherData.main.temp - 273.15).toFixed(2),
          description: weatherData.weather[0].description,
        };

        await redisClient.set(`weather:${location}`, JSON.stringify(combinedData), 'EX', 3600);
        return combinedData;
      } catch (error) {
        console.error(error);
        throw new Error('Failed to fetch weather data');
      }
    },

    async getClimateStats(_, { location, month }) {
      try {
        const response = await axios.get(`https://climate.api/stats/${location}/${month}`, {
          headers: { 'Authorization': `Bearer ${CLIMATE_API_KEY}` }
        });

        return response.data.temperatures;
      } catch (error) {
        console.error(error);
        throw new Error('Failed to fetch climate statistics');
      }
    },
  },
};

// Apollo Server Setup
const server = new ApolloServer({ typeDefs, resolvers });
server.applyMiddleware({ app });

// Worker thread example for async processing
function runWorker(data) {
  return new Promise((resolve, reject) => {
    const worker = new Worker('./worker.js', { workerData: data });

    worker.on('message', resolve);
    worker.on('error', reject);
    worker.on('exit', (code) => {
      if (code !== 0)
        reject(new Error(`Worker stopped with exit code ${code}`));
    });
  });
}

// API Routes
app.post('/authenticate', async (req, res) => {
  const { username, password } = req.body;

  // Validate credentials and generate JWT
  if (username === 'user' && password === 'pass') {
    const token = jwt.sign({ username }, JWT_SECRET);
    return res.json({ token });
  }

  res.status(401).json({ message: 'Invalid credentials' });
});

app.post('/mfa', authenticateToken, verifyMfa, async (req, res) => {
  res.json({ message: 'MFA Successful' });
});

// Start Server
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

