```javascript
const fs = require('fs').promises;
const path = require('path');

async function readDirectoryAndListFiles(directoryPath) {
    try {
        const entries = await fs.readdir(directoryPath, { withFileTypes: true });

        const promises = entries.map(async (entry) => {
            if (entry.name.startsWith('.')) return; // Skip hidden files

            const fullPath = path.join(directoryPath, entry.name);

            if (entry.isDirectory()) {
                try {
                    return readDirectoryAndListFiles(fullPath); // Recurse into subdirectories
                } catch (error) {
                    console.warn(`Failed to read directory: ${fullPath} -`, error);
                }
            } else if (entry.isFile()) {
                try {
                    const stats = await fs.stat(fullPath);

                    if (stats.size > 1 * 1024 * 1024) { // Skip files larger than 1MB
                        return;
                    }

                    const content = await fs.readFile(fullPath, 'utf8');
                    return { filename: entry.name, content };
                } catch (error) {
                    console.warn(`Failed to read file: ${fullPath} -`, error);
                }
            }
        });

        // Flatten the results and filter out undefined values
        const results = await Promise.all(promises).then(flattenAndFilter);

        return results;
    } catch (error) {
        console.error(`Failed to read directory: ${directoryPath} -`, error);
    }
}

function flattenAndFilter(arrays) {
    return arrays.reduce((acc, val) => acc.concat(Array.isArray(val) ? flattenAndFilter(val) : val), []).filter(Boolean);
}

module.exports = { readDirectoryAndListFiles };
```

This code defines an asynchronous function `readDirectoryAndListFiles` that reads a directory and lists all non-hidden files and subdirectories. It filters out hidden files, skips reading files larger than 1MB, handles errors gracefully, and ensures proper resource management by using promises and recursion.

