        if farm_name not in self._farm_locations:
            raise ValueError(f"No such farm '{farm_name}' found.")

        # Switch scenarios
        if scenario is not None:
            self._current_scenario = scenario

        try:
            historical_data = self._weather_data_cache.get(farm_name, {})
            # Implement probabilistic forecasting here using historical_data and current scenario
            forecast = {
                "temperature": 20.0,
                "humidity": 60.0,
                "wind_speed": 15.0,
                "precipitation_level": 5.0
            }
            return forecast
        except Exception as e:
            print(f"Error predicting weather for {farm_name}: {e}")
            return None

    def __str__(self):
