using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Caching.Memory;
using System;
using System.Data;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json.Linq;

public class ClinicStatusUpdateMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IMemoryCache _cache;
    private readonly HttpClient _httpClient;
    private const int MaxRequestsPerMinute = 5;

    public ClinicStatusUpdateMiddleware(RequestDelegate next, IMemoryCache cache)
    {
        _next = next;
        _cache = cache;
        _httpClient = new HttpClient();
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!context.Request.Method.Equals("POST", StringComparison.OrdinalIgnoreCase))
        {
            await _next(context);
            return;
        }

        try
        {
            var rateLimiterKey = $"{context.Connection.RemoteIpAddress}-{DateTime.UtcNow.Minute}";
            if (!_cache.TryGetValue(rateLimiterKey, out int requestCount) || requestCount >= MaxRequestsPerMinute)
            {
                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                await context.Response.WriteAsync("Rate limit exceeded. Try again later.");
                return;
            }

            _cache.Set(rateLimiterKey, ++requestCount, TimeSpan.FromMinutes(1));

            var clinicId = context.Request.Form["clinicId"];
            var newStatus = context.Request.Form["newStatus"];
            var lastModifiedIp = context.Connection.RemoteIpAddress.ToString();
            var userId = context.User.Identity.Name;

            if (string.IsNullOrWhiteSpace(clinicId) || string.IsNullOrWhiteSpace(newStatus))
            {
                context.Response.StatusCode = StatusCodes.Status400BadRequest;
                await context.Response.WriteAsync("Invalid input parameters.");
                return;
            }

            using (var connection = new SqlConnection("YourConnectionString"))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    try
                    {
                        var oldStatusCmd = new SqlCommand("SELECT status FROM Clinics WHERE ClinicId = @ClinicId", connection, transaction);
                        oldStatusCmd.Parameters.AddWithValue("@ClinicId", clinicId);

                        string oldStatus;
                        using (var reader = oldStatusCmd.ExecuteReader())
                        {
                            if (!reader.Read())
                            {
                                throw new Exception("Clinic not found.");
                            }
                            oldStatus = reader["status"].ToString();
                        }

                        var updateCmd = new SqlCommand(
                            "UPDATE Clinics SET Status = @NewStatus, LastModifiedIp = @LastModifiedIp, LastModifiedByUserId = @LastModifiedByUserId WHERE ClinicId = @ClinicId",
                            connection, transaction);
                        updateCmd.Parameters.AddWithValue("@NewStatus", newStatus);
                        updateCmd.Parameters.AddWithValue("@LastModifiedIp", lastModifiedIp);
                        updateCmd.Parameters.AddWithValue("@LastModifiedByUserId", userId);
                        updateCmd.Parameters.AddWithValue("@ClinicId", clinicId);

                        updateCmd.ExecuteNonQuery();

                        // Integrate with CMS
                        var cmsUpdateResult = await UpdateCMSAsync(clinicId, newStatus);
                        if (!cmsUpdateResult.IsSuccessStatusCode)
                        {
                            throw new Exception("Failed to update CMS.");
                        }

                        transaction.Commit();

                        LogAudit(userId, clinicId, oldStatus, newStatus);

                        SendEmailNotification(clinicId, userId, newStatus);

                        await context.Response.WriteAsync(JsonConvert.SerializeObject(new { success = true, message = "Clinic status updated successfully." }));
                    }
                    catch (Exception ex)
                    {
                        transaction.Rollback();
                        LogError(ex);
                        context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                        await context.Response.WriteAsync("An error occurred while updating the clinic status.");
                    }
                }
            }
        }
        finally
        {
            await _next(context);
        }
    }

    private async Task<HttpResponseMessage> UpdateCMSAsync(string clinicId, string newStatus)
    {
        var cmsUrl = $"https://cms.example.com/update?clinicId={clinicId}&status={newStatus}";

        try
        {
            return await _httpClient.GetAsync(cmsUrl);
        }
        catch (HttpRequestException ex)
        {
            LogError(ex);
            throw;
        }
    }

    private void SendEmailNotification(string clinicId, string userId, string newStatus)
    {
        // Implement email sending logic
    }

    private void LogAudit(string userId, string clinicId, string oldStatus, string newStatus)
    {
        // Implement audit logging
    }

    private void LogError(Exception ex)
    {
        // Implement error logging to a separate file or external service
    }
}
