// Function to validate configuration settings
int validate_config(const Config *config) {
    if (!config || !config->base_url || strlen(config->base_url) == 0) return 0;
    if (config->timeout <= 0) return 0;

    // Validate headers (e.g., check format and presence)
    for (int i = 0; config->headers[i]; ++i) {
        if (!config->headers[i] || strlen(config->headers[i]) == 0) return 0;
    }

    return 1;
}

// Function to cache configuration settings
void cache_config(ConfigCache *cache, const Config *config) {
    free_config(cache->config_data);

    // Duplicate the config data for caching
    cache->config_data = malloc(sizeof(Config));
    if (cache->config_data == NULL) return;

    cache->config_data->base_url = strdup(config->base_url);
    cache->config_data->timeout = config->timeout;
    cache->config_data->headers = malloc((sizeof(char *) * (strlen(config->headers[0]) + 1)));

    for (int i = 0; config->headers[i]; ++i) {
        cache->config_data->headers[i] = strdup(config->headers[i]);
    }
    cache->config_data->headers[strlen(config->headers)] = NULL;

    cache->last_fetch_time = time(NULL);
}

// Function to load cached configuration if valid
Config* load_cached_config_if_valid(ConfigCache *cache) {
    if (difftime(time(NULL), cache->last_fetch_time) < cache->cache_duration) {
        return cache->config_data;
    }
    return NULL;
}

// Logging function for errors and debug information
