}

// Function to free configuration memory safely
void free_config(Config *config) {
    if (!config) return;

    free(config->base_url);
    for (int i = 0; config->headers[i]; ++i) {
        free(config->headers[i]);
    }
    free(config->headers);
    free(config);
}

// Initialization function to set up the cache
void init_cache(ConfigCache *cache) {
    pthread_mutex_init(&cache->lock, NULL);
    cache->config_data = NULL;
    cache->last_fetch_time = 0;
}
