    }

    return NULL;
}

// Main Function to Simulate Requests Handling
int main() {
    init_thread_pool();

    pthread_t threads[10000];
    for (int i = 0; i < 10000; ++i) {
        Request request;
        request.id = i;
        request.user_id = "user123";
        request.data_source = "MySQL";

        if (pthread_create(&threads[i], NULL, worker_function, &request)) {
