```java
import java.io.*;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.regex.*;
import java.util.logging.*;

public class FileProcessingSystem {

    private static final Logger logger = Logger.getLogger(FileProcessingSystem.class.getName());
    private final Path directoryToWatch;
    private final ExecutorService executorService;
    private final Pattern keywordPattern;
    private final String apiUrl;

    public FileProcessingSystem(Path directory, String[] keywords, int maxThreads, String reportingApiUrl) {
        this.directoryToWatch = directory;
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.keywordPattern = Pattern.compile(Pattern.quote(keywords[0]) + "|" + 
                                             Pattern.quote(keywords[1]));
        this.apiUrl = reportingApiUrl;

        // Set up logging to a third-party service
        setupLogging();
    }

    private void setupLogging() {
        try {
            LogManager.getLogManager().readConfiguration(new FileInputStream("logging.properties"));
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Could not set up log configuration", e);
        }
    }

    public void startWatchingDirectory() throws IOException, InterruptedException {
        WatchService watchService = FileSystems.getDefault().newWatchService();
        directoryToWatch.register(watchService, StandardWatchEventKinds.ENTRY_CREATE);

        while (true) {
            WatchKey key = watchService.take();
            for (WatchEvent<?> event : key.pollEvents()) {
                if (event.kind() == StandardWatchEventKinds.ENTRY_CREATE) {
                    Path filePath = directoryToWatch.resolve((Path) event.context());
                    executorService.submit(() -> processFile(filePath));
                }
            }
            boolean valid = key.reset();
            if (!valid) {
                break;
            }
        }

        watchService.close();
    }

    private void processFile(Path filePath) {
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            String line;
            List<String> matchedLines = new ConcurrentSkipListSet<>();

            while ((line = reader.readLine()) != null) {
                if (keywordPattern.matcher(line).find()) {
                    matchedLines.add(line);
                }
            }

            // Generate and send report
            if (!matchedLines.isEmpty()) {
                String report = generateReport(matchedLines);
                logAndUpload(report);

                // Save results to the database
                saveToDatabase(filePath, matchedLines);
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error processing file: " + filePath, e);
        }
    }

    private String generateReport(List<String> lines) {
        return String.join("\n", lines);
    }

    private void logAndUpload(String report) {
        logger.info("Uploading report...");

        // Simulate API upload
        try (BufferedWriter writer = new BufferedWriter(new FileWriter("report.log", true))) {
            writer.write(report);
            notifyExternalApi(report);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to write or send report", e);
        }
    }

    private void notifyExternalApi(String report) {
        // Placeholder for external API call
        System.out.println("Report sent to: " + apiUrl + "\n" + report);
    }

    private void saveToDatabase(Path filePath, List<String> lines) {
        // Simulate database saving logic
        logger.info("Saving results for file: " + filePath + " with " + lines.size() + " matches");
        // Assume a function that interacts with a database connection to store data
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        Path directory = Paths.get("/path/to/directory");
        String[] keywords = {"error", "warning"};
        int maxThreads = 10;
        String apiUrl = "https://api.reporting.service/upload";

        FileProcessingSystem system = new FileProcessingSystem(directory, keywords, maxThreads, apiUrl);
        system.startWatchingDirectory();
    }
}
```

**Notes:**
- This implementation uses a `WatchService` to monitor the directory for file creation events.
- A fixed thread pool is used to process files asynchronously and efficiently.
- The use of `ConcurrentSkipListSet` ensures that matched lines are stored in a concurrent collection suitable for multi-threaded access.
