}

public class CsvDataParser : IDataParser<dynamic>
{
    public dynamic Parse(string data)
    {
        using var reader = new StringReader(data);
        using var csv = new CsvReader(reader, new CsvHelper.Configuration.CsvConfiguration(System.Globalization.CultureInfo.InvariantCulture));
        return csv.GetRecords<dynamic>().GetEnumerator().Current;
    }
}

public class XmlDataParser : IDataParser<XmlRoot>
{
