    public DatabaseService(string connectionString, string databaseName, string collectionName)
    {
        var client = new MongoClient(connectionString);
        var database = client.GetDatabase(databaseName);
        _collection = database.GetCollection<BsonDocument>(collectionName);

        // Implement auto-scaling and load balancing setup here
    }

    public async Task StoreDataAsync(object data)
    {
        var policy = Policy.Handle<MongoWriteException>()
            .WaitAndRetryAsync(new[] { TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(5) });

        await policy.ExecuteAsync(async () =>
        {
            await _collection.InsertOneAsync(BsonDocument.Parse(data.ToString()));
        });
    }
}

public class DataReceiver
{
    private readonly ConcurrentQueue<string> _dataQueue = new ConcurrentQueue<string>();
    private readonly IServiceProvider _serviceProvider;

    public DataReceiver(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider;
    }

    public void ReceiveData(string data, string protocol)
    {
        var parsedData = ParseData(data, protocol);
        if (parsedData != null)
            _dataQueue.Enqueue(parsedData);

        ProcessQueue();
    }

    private object ParseData(string data, string protocol)
    {
        switch (protocol.ToLower())
        {
            case "json":
                return new JsonDataParser().Parse(data);
            case "csv":
                return new CsvDataParser().Parse(data);
            case "xml":
                return new XmlDataParser().Parse(data);
            default:
                throw new NotSupportedException("Protocol not supported");
        }
    }

    private void ProcessQueue()
    {
        while (_dataQueue.TryDequeue(out var data))
        {
            using (var scope = _serviceProvider.CreateScope())
            {
                var processor = scope.ServiceProvider.GetRequiredService<IDeviceDataProcessor>();
                processor.ProcessDeviceData(data);
            }
        }
    }
}

