public class UserProfileUpdater
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<UserProfileUpdater> _logger;
    private static Dictionary<string, string> _cache = new();

    public UserProfileUpdater(HttpClient httpClient, ILogger<UserProfileUpdater> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task UpdateUserProfileAsync(string configFilePath, List<int> userIds, Dictionary<string, object> updatedDetails)
    {
        var tenantsConfig = LoadConfiguration(configFilePath);

        foreach (var tenant in tenantsConfig.Tenants)
        {
            await ProcessTenantUpdates(tenant, userIds, updatedDetails).ConfigureAwait(false);
        }
    }

    private async Task ProcessTenantUpdates(Tenant tenant, List<int> userIds, Dictionary<string, object> updatedDetails)
    {
        foreach (var userId in userIds)
        {
            if (!ValidateUserId(userId))
            {
                _logger.LogWarning($"Invalid user ID {userId} for tenant {tenant.Name}");
                continue;
            }

            var updatePriority = DetermineUpdatePriority(updatedDetails);

            try
            {
                await PerformUpdates(tenant, userId, updatedDetails, updatePriority).ConfigureAwait(false);
                NotifyStakeholders(tenant, userId, updatedDetails);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error updating profile for user ID {userId} in tenant {tenant.Name}");
            }
        }
    }

    private async Task PerformUpdates(Tenant tenant, int userId, Dictionary<string, object> updatedDetails, List<string> updatePriority)
    {
        foreach (var field in updatePriority)
        {
            if (!updatedDetails.ContainsKey(field)) continue;

            var apiUrl = tenant.GetApiUrlForField(field);
            var payload = JsonConvert.SerializeObject(updatedDetails[field]);
            var content = new StringContent(payload, Encoding.UTF8, "application/json");

            // Encrypt data for sensitive fields
            if (field == "email" || field == "phoneNumber")
                content.Headers.Add("Encryption", "AES-256");

            await _httpClient.PutAsync(apiUrl + $"/users/{userId}/{field}", content).ConfigureAwait(false);
        }
    }

    private List<string> DetermineUpdatePriority(Dictionary<string, object> updatedDetails)
    {
        var priorityFields = new List<string> { "email", "phoneNumber" };
        return updatedDetails.Keys.OrderBy(k => !priorityFields.Contains(k)).ToList();
    }

    private bool ValidateUserId(int userId)
    {
        if (_cache.ContainsKey($"userId_{userId}")) return true;

        // Simulate user ID validation logic
        _cache[$"userId_{userId}"] = "valid";
        return true;
    }

    private void NotifyStakeholders(Tenant tenant, int userId, Dictionary<string, object> updatedDetails)
    {
        var notificationService = new NotificationService(tenant.NotificationSettings);
        foreach (var detail in updatedDetails)
        {
            notificationService.Notify($"User {userId} profile update: {detail.Key} changed to {detail.Value}");
        }
    }

    private Configuration LoadConfiguration(string configFilePath)
    {
        if (!File.Exists(configFilePath))
            throw new FileNotFoundException("Configuration file not found.");

        var json = File.ReadAllText(configFilePath);
        return JsonConvert.DeserializeObject<Configuration>(json);
    }

    public void ShowHelpMenu()
    {
        Console.WriteLine("Usage: UpdateUserProfile <configFilePath> <userId1, userId2, ...> {email=..., phoneNumber=...}");
    }
}

