        this.anomalyDetectionService = anomalyDetectionService;
    }

    @AsyncMqttMessageListener(topic = "#", containerFactory = "mqttContainerFactory")
    public void handleMqttMessage(String topic, MqttMessage message) throws Exception {
        SensorData data = parseSensorData(message);
        anomalyDetectionService.processData(data);
    }

