@Service
public class AnomalyDetectionService {

    private final ModelRepository modelRepository;
    private final NotificationService notificationService;

    @Autowired
    public AnomalyDetectionService(ModelRepository modelRepository, NotificationService notificationService) {
        this.modelRepository = modelRepository;
        this.notificationService = notificationService;
    }

    public void processData(SensorData data) throws Exception {
        Model model = modelRepository.getModelForDevice(data.getDeviceId());
        if (model == null) throw new IllegalStateException("Model not found for device: " + data.getDeviceId());

        boolean isAnomaly = model.predict(data);
        if (isAnomaly) {
            notificationService.notify(data.getDeviceId(), data);
        }
    }
}

