#define MAX_ENV_VARS 100
#define BUFFER_SIZE 256

typedef enum { DEBUG, INFO, WARN, ERROR } LogLevel;
typedef void (*LogCallback)(LogLevel level, const char* message);

typedef struct {
    char key[BUFFER_SIZE];
    char value[BUFFER_SIZE];
} EnvVar;

typedef struct {
    char server_id[BUFFER_SIZE];
    LogLevel log_level;
    LogCallback callback;
} LoggingConfig;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t current_size;
    EnvVar* cache; // Simplified for LRU caching
} Cache;

typedef struct {
    char db_name[BUFFER_SIZE];
    char user[BUFFER_SIZE];
    char password[BUFFER_SIZE];
    int port;
    char host[BUFFER_SIZE];
} DBConfig;

void log_message(LoggingConfig config, LogLevel level, const char* message) {
    if (config.callback != NULL) {
        time_t now = time(NULL);
        struct tm* t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        char log_entry[BUFFER_SIZE];
        snprintf(log_entry, sizeof(log_entry),
                 "[%s] Server ID: %s Level: %d Message: %s\n",
                 timestamp, config.server_id, level, message);

        if (level >= config.log_level) {
            config.callback(level, log_entry);
        }
    }
}

void to_lower(char* str) {
    while (*str) {
        *str = tolower((unsigned char)*str);
        str++;
    }
}

