        } else if (strcmp(keys[i], "type2") == 0) {
            rule.process = process_type2;
        }

        *rules = realloc(*rules, (*num_rules + 1) * sizeof(ParsingRule));
        (*rules)[*num_rules++] = rule;
    }

    json_decref(root);
}

void process_file(ThreadData* data) {
    size_t file_size;
    unsigned char* buffer = read_binary_data(data->input_file, &file_size);

    // Apply parsing rules
    for (int i = 0; i < data->num_rules; ++i) {
