// Function to find the largest integer in a vector
int findLargestInteger(const std::vector<int>& numbers) {
    return *std::max_element(numbers.begin(), numbers.end());
}

// Logging function for errors
void logError(const std::string& message, const std::string& logFile) {
    std::ofstream log(logFile, std::ios_base::app);
    if (log.is_open()) {
        log << message << std::endl;
    }
}

// Function to initialize cryptographic algorithms using OpenSSL
bool initializeCrypto(const std::string& config, const std::string& logFile) {
    int ret = 1; // Assume success by default

    // Load OpenSSL algorithms based on the configuration string
    if (config == "AES-256") {
        EVP_add_cipher(EVP_aes_256_cbc());
    } else if (config == "ChaCha20") {
        EVP_add_cipher(EVP_chacha20());
    }

    if (config.find("SHA-256") != std::string::npos) {
        EVP_add_digest(EVP_sha256());
    }
    if (config.find("SHA-384") != std::string::npos) {
        EVP_add_digest(EVP_sha384());
    }
    if (config.find("SHA-512") != std::string::npos) {
        EVP_add_digest(EVP_sha512());
    }

    // Check for errors in initialization
    if (!EVP_supported() || !EVP_available()) {
        logError("Failed to initialize cryptographic algorithms.", logFile);
        ret = 0; // Failure
    }

    return ret;
}

