    {
        var now = DateTime.UtcNow;

        if (_rateLimits.TryGetValue(key, out var lastAccess))
        {
            if ((now - lastAccess).TotalSeconds < 1) // Simple rate limit: 1 request per second
                return false;

            _rateLimits[key] = now;
            return true;
        }

        _rateLimits.TryAdd(key, now);
        return true;
    }
}

