import json
from jsonschema import validate, ValidationError
from threading import Lock

class JSONParser:
    _registry = {}
    _lock = Lock()

    def __init__(self):
        self.schema = None

    @classmethod
    def add_factory(cls, id_, factory_function):
        with cls._lock:
            cls._registry[id_] = factory_function

    @classmethod
    def remove_factory(cls, id_):
        with cls._lock:
            if id_ in cls._registry:
                del cls._registry[id_]

    @classmethod
    def create_instance(cls, id_, json_data):
        with cls._lock:
            factory_function = cls._registry.get(id_)
            if not factory_function:
                raise ValueError(f"No factory function registered for ID '{id_}'")
            try:
                parsed_data = cls.deserialize(json_data)
                cls.validate(parsed_data)
                return factory_function(parsed_data)
            except (json.JSONDecodeError, ValidationError) as e:
                raise ValueError(f"Invalid JSON data: {e}")

    @staticmethod
    def deserialize(json_string):
        return json.loads(json_string)

    @classmethod
    def validate(cls, data):
        if cls.schema is None:
            raise ValueError("Schema not set for validation.")
        try:
            validate(instance=data, schema=cls.schema)
        except ValidationError as e:
            raise ValueError(f"JSON validation error: {e.message}")

    @classmethod
    def set_schema(cls, schema):
        cls.schema = schema

    def __del__(self):
        # Implement resource cleanup if necessary.
        pass

