class CassandraConnectionManager {
    public void connect() {
        // Implement connection logic with retries
    }

    public void retryOperation(Runnable operation) throws Exception {
        int attempts = 0;
        while (attempts < 3) {
            try {
                operation.run();
                return; 
            } catch (Exception e) {
                Thread.sleep((long) Math.pow(2, attempts++) * 1000); // Exponential backoff
            }
        }
    }
}

