// Assume this external logging API is provided elsewhere.
extern void logMessage(const char *message, int level);

#define LOG_LEVEL_INFO 1

void logCondition(int condition, const char *format, ...) {
    if (!condition) return;

    // Buffer for the formatted message
    char buffer[256];
    va_list args;

    // Initialize variable argument list
    va_start(args, format);

    // Format the string into the buffer with error checking
    int length = vsnprintf(buffer, sizeof(buffer), format, args);

    // End variable argument processing
    va_end(args);

    if (length < 0 || length >= sizeof(buffer)) {
        // Handle error: log message overflow or encoding issue
        const char *error_message = "Log message formatting error";
        logMessage(error_message, LOG_LEVEL_INFO);
        return;
    }

    // Call the external logging system with the formatted string
    logMessage(buffer, LOG_LEVEL_INFO);
}

