```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class SecureMessageProcessor : IDisposable
{
    private readonly ConcurrentDictionary<string, string> _decryptedCache = new ConcurrentDictionary<string, string>();
    private static readonly object _logLock = new object();

    public string DecryptMessage(string encodedMessage, byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 24 || iv == null || iv.Length != 8)
            throw new ArgumentException("Invalid Key or IV length. Key must be 24 bytes and IV must be 8 bytes.");

        string cacheKey = $"{Convert.ToBase64String(key)}:{Convert.ToBase64String(iv)}";

        if (_decryptedCache.TryGetValue(cacheKey, out var cachedMessage))
        {
            return cachedMessage;
        }

        try
        {
            using (var tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;
                tripleDes.Mode = CipherMode.CBC;
                tripleDes.Padding = PaddingMode.PKCS7;

                byte[] encryptedData = Convert.FromBase64String(encodedMessage);
                using (var decryptor = tripleDes.CreateDecryptor())
                using (var msDecrypt = new MemoryStream(encryptedData))
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                using (var srDecrypt = new StreamReader(csDecrypt))
                {
                    string decryptedMessage = srDecrypt.ReadToEnd();
                    _decryptedCache[cacheKey] = decryptedMessage;
                    return decryptedMessage;
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw new InvalidOperationException("Decryption failed.", ex);
        }
    }

    public byte[] EncryptMessage(string message, byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 24 || iv == null || iv.Length != 8)
            throw new ArgumentException("Invalid Key or IV length. Key must be 24 bytes and IV must be 8 bytes.");

        try
        {
            using (var tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = key;
                tripleDes.IV = iv;
                tripleDes.Mode = CipherMode.CBC;
                tripleDes.Padding = PaddingMode.PKCS7;

                using (var encryptor = tripleDes.CreateEncryptor())
                using (var msEncrypt = new MemoryStream())
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                using (var swEncrypt = new StreamWriter(csEncrypt))
                {
                    swEncrypt.Write(message);
                    swEncrypt.Flush();
                    csEncrypt.FlushFinalBlock();
                    return msEncrypt.ToArray();
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw new InvalidOperationException("Encryption failed.", ex);
        }
    }

    private void LogError(Exception ex)
    {
        lock (_logLock)
        {
            // Replace with actual logging implementation
            Console.WriteLine($"[ERROR] {DateTime.Now}: {ex.Message}");
        }
    }

    public void Dispose()
    {
        _decryptedCache.Clear();
    }
}

