using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using System;
using System.Collections.Concurrent;
using System.Net.Mail;
using System.Text.Json;
using System.Threading.Tasks;

public class ClinicStatusMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ClinicStatusMiddleware> _logger;
    private readonly IRateLimiter _rateLimiter;
    private readonly IDatabaseService _databaseService;
    private readonly IAuditService _auditService;
    private readonly IEmailService _emailService;
    private readonly ICacheService _cacheService;

    public ClinicStatusMiddleware(RequestDelegate next, ILogger<ClinicStatusMiddleware> logger, 
                                  IRateLimiter rateLimiter, IDatabaseService databaseService,
                                  IAuditService auditService, IEmailService emailService,
                                  ICacheService cacheService)
    {
        _next = next;
        _logger = logger;
        _rateLimiter = rateLimiter;
        _databaseService = databaseService;
        _auditService = auditService;
        _emailService = emailService;
        _cacheService = cacheService;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (context.Request.Method != HttpMethods.Post)
        {
            context.Response.StatusCode = StatusCodes.Status405MethodNotAllowed;
            return;
        }

        try
        {
            var requestBody = await new StreamReader(context.Request.Body).ReadToEndAsync();
            var requestPayload = JsonSerializer.Deserialize<ClinicUpdateRequest>(requestBody);

            if (requestPayload == null || !_rateLimiter.AllowRequest(requestPayload.IPAddress))
            {
                context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
                return;
            }

            var transactionResult = await _databaseService.UpdateClinicStatusAsync(
                requestPayload.ClinicId, 
                requestPayload.NewStatus, 
                requestPayload.LastModifiedByUserId,
                requestPayload.IPAddress
            );

            if (transactionResult.Success)
            {
                await _auditService.LogAuditInfoAsync(transactionResult.AuditInfo);
                await SendEmailNotification(requestPayload, transactionResult.UpdatedClinic);

                context.Response.StatusCode = StatusCodes.Status200OK;
                var responsePayload = new ClinicUpdateResponse { Success = true, UpdatedDetails = transactionResult.UpdatedClinic };
                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(JsonSerializer.Serialize(responsePayload));
            }
            else
            {
                context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                var responsePayload = new ClinicUpdateResponse { Success = false, ErrorMessage = transactionResult.ErrorMessage };
                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(JsonSerializer.Serialize(responsePayload));
            }

        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing clinic status update.");
            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            var responsePayload = new ClinicUpdateResponse { Success = false, ErrorMessage = "Internal server error." };
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsync(JsonSerializer.Serialize(responsePayload));
        }
    }

    private async Task SendEmailNotification(ClinicUpdateRequest request, ClinicDetails updatedClinic)
    {
        var messageBody = $"Clinic ID {request.ClinicId} has been updated to status '{updatedClinic.Status}' by user {request.LastModifiedByUserId}.";
        try
        {
            await _emailService.SendEmailAsync("admin@example.com", "Clinic Status Update", messageBody);
        }
        catch (SmtpException ex)
        {
            _logger.LogWarning(ex, "Failed to send email notification.");
        }
    }

    // Define additional classes and interfaces used in the middleware
}

public class ClinicUpdateRequest
{
    public string ClinicId { get; set; }
    public string NewStatus { get; set; }
    public string LastModifiedByUserId { get; set; }
    public string IPAddress { get; set; }
}

