import os
import logging
from contextlib import contextmanager
import fcntl
import time

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

class FileIOManagerConfig:
    def __init__(self):
        self.supported_modes = {'r', 'w', 'a', 'rb', 'wb', 'ab'}
        self.timeout = 5.0  # Default timeout in seconds

    def set_supported_modes(self, modes):
        if isinstance(modes, set):
            self.supported_modes = modes
        else:
            raise ValueError("Supported modes must be a set of strings.")

    def set_timeout(self, timeout: float):
        if isinstance(timeout, (int, float)) and timeout > 0:
            self.timeout = float(timeout)
        else:
            raise ValueError("Timeout must be a positive number.")


config = FileIOManagerConfig()

def _expand_env_variables(path):
    return os.path.expandvars(path)

def _validate_file_path(path):
    if len(path.encode('utf-8')) > 1024:
        raise ValueError(f"File path '{path}' exceeds maximum buffer size of 1024 bytes.")

def _check_supported_mode(mode):
    if mode not in config.supported_modes:
        raise ValueError(f"Mode '{mode}' is not supported. Supported modes are: {config.supported_modes}")

@contextmanager
def dynamic_safe_file_open(file_path, mode, timeout=None):
    # Set the timeout to default configuration value if none provided
    timeout = timeout or config.timeout

    try:
        # Expand environment variables in file path
        full_path = _expand_env_variables(file_path)

        # Validate the file path length
        _validate_file_path(full_path)

        # Check if mode is supported
        _check_supported_mode(mode)

        logging.info(f"Attempting to open '{full_path}' with mode '{mode}'.")

        # Initialize variables for handling file access and lock attempts
        attempt = 0
        max_attempts = int(timeout) + 1

        while attempt < max_attempts:
            try:
                # Open the file safely using a context manager
                with open(full_path, mode) as file_obj:

                    # Attempt to acquire an exclusive lock on Unix systems (non-blocking)
                    if os.name != 'nt':  # Windows does not support fcntl
                        fcntl.flock(file_obj.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)

                    logging.info(f"Successfully opened and locked file '{full_path}'.")

                    yield file_obj

                    # Release the lock (only on Unix systems)
                    if os.name != 'nt':
                        fcntl.flock(file_obj.fileno(), fcntl.LOCK_UN)

                return  # Exit after successful open and operations
            except (OSError, IOError) as e:
                attempt += 1
                logging.error(f"Error opening file '{full_path}': {e}. Retrying in {timeout / max_attempts:.2f} seconds...")

                time.sleep(timeout / max_attempts)

        # Raise an error if timeout exceeded without successful open
        raise TimeoutError(f"Failed to acquire lock on file '{full_path}' within the specified timeout of {timeout}s.")

    except Exception as e:
        logging.error(f"An error occurred: {e}")
        raise

# Example usage for setting custom configuration (could be expanded to allow user input)
def configure_file_io_manager(modes=None, timeout=None):
    if modes is not None:
        config.set_supported_modes(modes)

    if timeout is not None:
        config.set_timeout(timeout)

