@Component
public class SensorDataStreamProcessor {

    @Autowired
    private Sink<List<SensorData>> sink;

    public Flux<Void> processSensorStream(Flux<SensorData> sensorFlux) {
        return sensorFlux
            .bufferTimeout(Duration.ofMillis(100))
            .flatMap(this::processBatch)
            .then();
    }

    private Mono<Void> processBatch(List<SensorData> batch) {
        // Filter and aggregate data based on rules
        List<SensorData> filtered = filterAndAggregate(batch);

        // Geolocate events using GIS API
        Flux<SensorData> geolocated = filtered.stream()
            .map(this::geolocate)
            .collectList().flatMapMany(Flux::fromIterable);

        // Send to distributed message queue (Kafka)
        return Flux.fromIterable(geolocated)
            .flatMap(data -> sendDataToQueue(data))
            .then();
    }

    private List<SensorData> filterAndAggregate(List<SensorData> batch) {
        // Implement filtering and aggregation logic
