    }

    private SensorData geolocate(SensorData data) {
        // Call GIS API to add latitude/longitude if not present
        return data;
    }

    private Mono<Void> sendDataToQueue(SensorData data) {
        return Mono.fromRunnable(() -> sink.output().send(Flux.just(data)));
    }
