### Python Script

```python
import json
import threading
from concurrent.futures import ThreadPoolExecutor
import os
import glob
import logging
import requests
from datetime import datetime, timezone
import pandas as pd
from sklearn.ensemble import IsolationForest
import sqlite3

# Configuration loading
def load_config(config_path):
    with open(config_path, 'r') as file:
        return json.load(file)

config = load_config('config.json')

# Anomaly detection using statistical model
def detect_anomalies(data):
    iforest = IsolationForest(contamination=0.1)
    data_array = pd.DataFrame.from_dict(data).values
    predictions = iforest.fit_predict(data_array)
    return [data[i] for i in range(len(data)) if predictions[i] == 1]

# Validate sensor data
def validate_data(sensor_data, rules):
    # Implement validation logic based on rules
    valid_data = []
    for entry in sensor_data:
        if all(rule(entry) for rule in rules):
            valid_data.append(entry)
    return valid_data

# Process a single log file
def process_log_file(file_path, db_conn, config_rules):
    with open(file_path, 'r') as file:
        data = json.load(file)

    # Validate data
    validated_data = validate_data(data['sensor_data'], config_rules)

    # Detect anomalies
    cleaned_data = detect_anomalies(validated_data)

    # Store in database
    cursor = db_conn.cursor()
    for entry in cleaned_data:
        cursor.execute("INSERT INTO sensor_data VALUES (?, ?, ?)", (entry['timestamp'], entry['value'], entry['sensor_id']))
    db_conn.commit()

# Main processing function with threading
def main():
    logging.basicConfig(level=logging.INFO)
    config_rules = [lambda x: x.get('sensor_id') is not None, lambda x: isinstance(x['value'], (int, float))]

    # Connect to the database
    db_conn = sqlite3.connect('sensor_data.db')
    cursor = db_conn.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS sensor_data 
                      (timestamp TEXT, value REAL, sensor_id TEXT)''')

    log_files = glob.glob('logs/*.json')

    with ThreadPoolExecutor(max_workers=5) as executor:
        for file_path in log_files:
            executor.submit(process_log_file, file_path, db_conn, config_rules)

if __name__ == "__main__":
    main()
```

