async function fetchWeatherData(cities, updateUI, cacheDuration = 300000) {
    const apiKey = 'YOUR_API_KEY';
    const weatherCache = new Map();

    async function fetchWithRetry(url, retries = 3) {
        for (let attempt = 0; attempt < retries; attempt++) {
            try {
                const response = await fetch(url);
                if (!response.ok) throw new Error(`API error: ${response.statusText}`);
                return await response.json();
            } catch (error) {
                console.error(`Attempt ${attempt + 1} failed:`, error.message);
                if (attempt === retries - 1) throw error;
                await new Promise(resolve => setTimeout(resolve, 1000));
            }
        }
    }

    async function fetchWeather(city, units = 'metric') {
        const cacheKey = `${city}-${units}`;
        const cachedData = weatherCache.get(cacheKey);

        if (cachedData && Date.now() - cachedData.timestamp < cacheDuration) {
            console.log(`Using cached data for ${city}`);
            return cachedData.data;
        }

        const url = `https://api.weather.com/v3/wx/conditions/current?apiKey=${apiKey}&format=json&language=en-US&units=${units}&location=${encodeURIComponent(city)}&details=true`;

        try {
            const data = await fetchWithRetry(url);
            weatherCache.set(cacheKey, { timestamp: Date.now(), data });
            return data;
        } catch (error) {
            console.error(`Failed to fetch data for ${city}:`, error.message);
            return null;
        }
    }

    async function updateWeatherData(cities, units = 'metric') {
        const results = await Promise.all(cities.map(city => fetchWeather(city, units)));

        // Filter out failed requests
        const successfulResults = cities.filter((_, index) => results[index] !== null);

        updateUI(successfulResults.map((result, index) => ({
            city: cities[index],
            weather: result
        })));

        console.log('Weather data updated successfully.');
    }

    await updateWeatherData(cities);

