import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import time
import logging
import jsonschema
import threading
from random import uniform

# Configure logging
logging.basicConfig(filename='update_logs.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

API_ENDPOINTS = {
    "service1": {"url": "https://api.service1.com/update", "rate_limit": 5},
    "service2": {"url": "https://api.service2.com/profile", "rate_limit": 10}
}

SCHEMA = {
    "type": "object",
    "properties": {
        "email": {"type": "string", "format": "email"},
        "phone_number": {"type": "string", "pattern": r"^\+?[1-9]\d{1,14}$"},
        "address": {"type": "string"},
        "date_of_birth": {"type": "string", "format": "date"},
        "employment_status": {"type": "string"}
    },
    "required": ["email", "phone_number", "date_of_birth"]
}

MAX_RETRIES = 5
BASE_DELAY = 1  # seconds

lock = threading.Lock()

def validate_data(data):
    try:
        jsonschema.validate(instance=data, schema=SCHEMA)
        return True
    except jsonschema.exceptions.ValidationError as err:
        logging.error(f"Validation error: {err.message}")
        return False

def exponential_backoff_with_jitter(retry_count):
    delay = BASE_DELAY * (2 ** retry_count) + uniform(0, 1)
    time.sleep(delay)

def update_profile(service_name, endpoint_info, user_data, api_key):
    url = endpoint_info["url"]
    headers = {"Authorization": f"Bearer {api_key}"}
    for attempt in range(MAX_RETRIES):
        try:
            response = requests.put(url, json=user_data, headers=headers)

            if response.status_code == 200:
                logging.info(f"{service_name} update successful.")
                return True

            if 'Retry-After' in response.headers:
                delay = int(response.headers['Retry-After'])
                time.sleep(delay)

        except requests.exceptions.RequestException as e:
            logging.error(f"Network error on {service_name}: {e}")

        exponential_backoff_with_jitter(attempt)

    return False

def update_user_profiles(user_data, api_keys):
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = []
        for service_name, endpoint_info in API_ENDPOINTS.items():
            api_key = api_keys.get(service_name)
            if not validate_data(user_data):
                notify_user("Profile update failed due to invalid data.")
                continue

            future = executor.submit(update_profile, service_name, endpoint_info, user_data, api_key)
            futures.append(future)

        results = {service: f.result() for service, f in zip(API_ENDPOINTS.keys(), as_completed(futures))}

    if not all(results.values()):
        notify_user("Some services could not update the profile.")

def notify_user(message):
    logging.info(f"User notification: {message}")
    # Add user feedback mechanism here (e.g., email, SMS)

# Example usage
user_data = {
    "email": "user@example.com",
    "phone_number": "+1234567890",
    "address": "123 Main St",
    "date_of_birth": "1990-01-01",
    "employment_status": "Employed"
}

api_keys = {
    "service1": "apikey_for_service1",
    "service2": "apikey_for_service2"
}

update_user_profiles(user_data, api_keys)
