### C Code: File Reading and Data Processing

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    float offset;
    float key;
} Record;

Record* read_file(const char *filename, size_t *record_count) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    char line[256];
    size_t count = 0;
    Record *records = NULL;

    while (fgets(line, sizeof(line), file)) {
        records = realloc(records, (count + 1) * sizeof(Record));
        sscanf(line, "%d %f %f", &records[count].id, &records[count].offset, &records[count].key);
        count++;
    }

    fclose(file);
    *record_count = count;
    return records;
}

float calculate_average_offset(Record *records, size_t count) {
    float sum = 0.0;
    for (size_t i = 0; i < count; i++) {
        sum += records[i].offset;
    }
    return count ? sum / count : 0.0;
}

float calculate_average_key(Record *records, size_t count) {
    float sum = 0.0;
    for (size_t i = 0; i < count; i++) {
        sum += records[i].key;
    }
    return count ? sum / count : 0.0;
}
