### PHP Code: RESTful API and Password Hashing

```php
<?php
// Include necessary libraries for RESTful API
require 'vendor/autoload.php';

use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use Slim\Factory\AppFactory;

$app = AppFactory::create();

// Hash password with configurable rounds
function hash_password($password, $rounds = 10) {
    return password_hash($password, PASSWORD_BCRYPT, ['cost' => $rounds]);
}

// Securely hash a given password via RESTful API
$app->post('/hash', function (Request $request, Response $response, array $args) {
    $data = json_decode($request->getBody(), true);
    $password = $data['password'] ?? '';
    $rounds = $data['rounds'] ?? 10;

    if (!filter_var($password, FILTER_VALIDATE_STRING)) {
        return $response->withStatus(400)->write('Invalid password input.');
    }

    try {
        $hashedPassword = hash_password($password, $rounds);
        $response->getBody()->write(json_encode(['hash' => $hashedPassword]));
    } catch (Exception $e) {
        return $response->withStatus(500)->write('Error hashing password.');
    }

    return $response->withHeader('Content-Type', 'application/json');
});

// Run the Slim application
$app->run();
```

