// Thread handling function
void *handleRequest(void *arg) {
    while (1) {
        sem_wait(&pool.tasksAvailable);

        const char *request = *((const char**) arg);

        if (fetchAndProcessData(request)) {
            logError("Failed to process data");
        } else {
            logDebug("Successfully processed data for request: %s", request);
        }

        free(arg); // Cleanup
    }
    return NULL;
}

// Initialize the thread pool
void setupThreadpool(ThreadPool *pool) {
    sem_init(&pool->tasksAvailable, 0, 0);
    sem_init(&pool->slotsAvailable, 0, MAX_THREADS);

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&pool->threads[i], NULL, handleRequest, NULL);
    }
}

// Cleanup the thread pool
void teardownThreadpool(ThreadPool *pool) {
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(pool->threads[i], NULL);
    }
    sem_destroy(&pool->tasksAvailable);
    sem_destroy(&pool->slotsAvailable);
}

// Main function to demonstrate usage
int main() {
    setupThreadpool(&pool);

    for (int i = 0; i < MAX_REQUESTS; ++i) {
        const char *requestData = "example_request";

        sem_wait(&pool.slotsAvailable);

        char *threadArg = strdup(requestData);
        pthread_t thread;

        if (pthread_create(&thread, NULL, handleRequest, (void *)threadArg)) {
            logError("Failed to create thread");
        } else {
            // Detach the thread as we manage our own pool
            pthread_detach(thread);
        }
    }

    // Graceful shutdown
    teardownThreadpool(&pool);

    return 0;
}
