class RateLimiter {
public:
    RateLimiter(size_t maxRequestsPerSecond) : maxRequestsPerSecond(maxRequestsPerSecond), currentRequests(0) {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mtx);
        if (currentRequests >= maxRequestsPerSecond) {
            cond.wait_for(lock, std::chrono::seconds(1));
            currentRequests = 0;
        }
        ++currentRequests;
    }

private:
    size_t maxRequestsPerSecond;
    size_t currentRequests;
    std::mutex mtx;
    std::condition_variable cond;
};

size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::vector<char>*)userp)->insert(((std::vector<char>*)userp)->end(), static_cast<char*>(contents), static_cast<char*>(contents) + size * nmemb);
    return size * nmemb;
}

bool downloadFile(const std::string& url, std::vector<char>& buffer, const Config& config) {
    CURL* curl = curl_easy_init();
    if (!curl) return false;

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &buffer);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        std::cerr << "CURL error: " << curl_easy_strerror(res) << std::endl;
        curl_easy_cleanup(curl);
        return false;
    }

    curl_easy_cleanup(curl);
    return true;
}

std::string calculateSHA256(const std::vector<char>& data) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, data.data(), data.size());
    SHA256_Final(hash, &sha256);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }
    return ss.str();
}

