public class SecureFileUploaderService {

    private static final Logger logger = Logger.getLogger(SecureFileUploaderService.class.getName());
    private static Map<String, String> metadataCache = new ConcurrentHashMap<>();

    public CompletableFuture<Void> secureFileUploaderService(String filePath, String bucketName, 
                                                              String directoryPath, CloudStorageService service) {
        return CompletableFuture.runAsync(() -> {
            try (Socket socket = createSecureSocket()) {
                Path file = Paths.get(filePath);
                long fileSize = Files.size(file);

                if (!validateMetadata(file, fileSize)) {
                    throw new IOException("Invalid metadata");
                }

                String fileHash = calculateSHA256(file);
                if (isFileAlreadyUploaded(fileHash, bucketName, directoryPath, service)) {
                    logger.info("File already exists in the cloud storage.");
                    return;
                }

                switch (service) {
                    case S3:
                        uploadToS3(filePath, bucketName, directoryPath);
                        break;
                    case AZURE:
                        uploadToAzure(filePath, bucketName, directoryPath);
                        break;
                    case GOOGLE_CLOUD:
                        uploadToGoogleCloud(filePath, bucketName, directoryPath);
                        break;
                }
            } catch (Exception e) {
                logger.severe("Error during file upload: " + e.getMessage());
            }
        });
    }

    private Socket createSecureSocket() throws IOException {
        SSLContext sslContext = SSLContext.getInstance("TLS");
        // Initialize with a key manager and trust manager
        sslContext.init(null, null, new java.security.SecureRandom());
        return sslContext.getSocketFactory().createSocket();
    }

    private boolean validateMetadata(Path file, long fileSize) throws IOException {
        if (fileSize > 10 * 1024 * 1024) { // Example size limit
            return false;
        }

        String contentType = Files.probeContentType(file);
        if (!"application/pdf".equals(contentType)) { // Example type check
            return false;
        }

        metadataCache.put(file.toString(), "Validated");
        return true;
    }

    private boolean isFileAlreadyUploaded(String fileHash, String bucketName, 
                                          String directoryPath, CloudStorageService service) {
        // Mock method to check if the file exists using hash
        return !metadataCache.containsKey(fileHash);
    }

    private String calculateSHA256(Path path) throws IOException {
        try (InputStream fis = Files.newInputStream(path)) {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] buffer = new byte[8192];
            int read;

            while ((read = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, read);
            }
            return bytesToHex(digest.digest());
        }
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

