# Expanded JWT Generation Functionality with Key Rotation, RBAC, Rate Limiting, Custom Claims, and Enhanced Refresh

import jwt
from datetime import datetime, timedelta
import requests
from cachetools import TTLCache
from functools import wraps
import threading
import time
import random

class RateLimiter:
    def __init__(self, max_calls, period):
        self.calls = TTLCache(maxsize=max_calls, ttl=period)
        self.lock = threading.Lock()

    def is_allowed(self, key):
        with self.lock:
            if key in self.calls:
                return False
            self.calls[key] = time.time()
            return True

def rate_limited(max_calls, period):
    limiter = RateLimiter(max_calls, period)

    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            user_id = args[0].get('user_id')
            if not limiter.is_allowed(user_id):
                raise Exception("Rate limit exceeded")
            return func(*args, **kwargs)

        return wrapped
    return decorator

def get_private_key_from_kms(key_id):
    # Simulate fetching the private key from a Key Management System (KMS)
    kms_url = "https://kms.example.com/get-key"
    response = requests.get(f"{kms_url}?key_id={key_id}")
    if response.status_code == 200:
        return response.json().get('private_key')
    else:
        raise Exception("Failed to fetch key from KMS")

def jwt_generator(user_data, role='user', context={}):
    key_ids = ['key1', 'key2']  # List of key IDs for rotation
    private_key = get_private_key_from_kms(random.choice(key_ids))

    claims = {
        "exp": datetime.utcnow() + timedelta(minutes=30),
        "iat": datetime.utcnow(),
        "sub": user_data.get("user_id"),
        "role": role,
        "context": context,
        "metadata": {"last_login_time": datetime.utcnow().isoformat()}
    }

    if 'sensitive' in context and context['sensitive']:
        claims["encrypted_profile"] = jwt.encrypt(user_data.get('profile'), private_key)

    token = jwt.encode(claims, private_key, algorithm="HS256")
    return token

@rate_limited(max_calls=5, period=60)  # Limit to 5 requests per minute
def access_protected_resource(token):
    decoded_token = jwt.decode(token, options={"verify_signature": False})
    if decoded_token['role'] != 'admin':
        raise Exception("Access denied: insufficient permissions")
    return "Access granted"

# Example usage
user_data = {"user_id": 12345, "profile": "Sensitive data"}
token = jwt_generator(user_data, context={'sensitive': True})

try:
    print(access_protected_resource(token))
except Exception as e:
    print(e)
