# Sensor Data Processing with Real-time Validation, Distributed Caching, and Aggregation

import numpy as np
from sklearn.ensemble import IsolationForest
from cachetools import cached, TTLCache
import queue
import threading
import time

class DataProcessor:
    def __init__(self):
        self.model = IsolationForest()
        self.cache = TTLCache(maxsize=1000, ttl=300)  # Cache for validation schema
        self.data_queue = queue.PriorityQueue()
        self.lock = threading.Lock()

    @cached(cache)
    def get_validation_schema(self, sensor_type):
        # Simulate fetching a validation schema from a distributed cache
        return {"type": "object", "properties": {"temperature": {"type": "number"}}}

    def validate_sensor_data(self, data):
        sensor_type = data.get("sensor_type")
        schema = self.get_validation_schema(sensor_type)

        if not isinstance(data['temperature'], float):
            raise ValueError("Invalid temperature value")

        # Anomaly detection
        is_anomalous = self.model.predict([data['temperature']])[0] == -1
        return not is_anomalous

    def process_data(self, data):
        priority = self.calculate_priority(data)
        self.data_queue.put((priority, data))

    def calculate_priority(self, data):
        # Priority based on urgency or importance
        return 1 if data.get('urgent') else 5

    def aggregate_sensor_data(self):
        while True:
            time.sleep(300)  # Aggregate every 5 minutes
            aggregated_data = []

            while not self.data_queue.empty():
                _, data = self.data_queue.get()
                aggregated_data.append(data)

            if aggregated_data:
                avg_temperature = np.mean([d['temperature'] for d in aggregated_data])
                print(f"Aggregated Temperature: {avg_temperature}")

    def start(self):
        threading.Thread(target=self.aggregate_sensor_data, daemon=True).start()

# Example usage
processor = DataProcessor()
processor.start()

sensor_data = {"sensor_id": 1, "temperature": 23.5, "urgent": True}
if processor.validate_sensor_data(sensor_data):
    processor.process_data(sensor_data)
