# Distributed Database Connection Manager with Pooling, Fault Tolerance, and Schema Detection

import psycopg2
from psycopg2 import pool
import threading
import time

class DistributedDBManager:
    def __init__(self, dsn_list):
        self.pool = None
        self.dsn_list = dsn_list
        self.active_dsn_index = 0
        self.lock = threading.Lock()

        # Initialize connection pooling
        self.initialize_pool()

    def initialize_pool(self):
        try:
            self.pool = pool.SimpleConnectionPool(1, 10, dsn=self.dsn_list[self.active_dsn_index])
        except Exception as e:
            print(f"Failed to create initial pool: {e}")

    def get_connection(self):
        with self.lock:
            if not self.pool:
                raise Exception("No available database connections")
            return self.pool.getconn()

    def release_connection(self, conn):
        try:
            self.pool.putconn(conn)
        except Exception as e:
            print(f"Failed to release connection: {e}")

    def execute_query(self, query, params=None):
        conn = None
        try:
            conn = self.get_connection()
            cursor = conn.cursor()
            cursor.execute(query, params)
            result = cursor.fetchall()
            return result
        except Exception as e:
            print(f"Query failed: {e}")
            self.handle_failure(conn)
        finally:
            if conn:
                self.release_connection(conn)

    def handle_failure(self, conn):
        try:
            if conn:
                conn.close()
            self.active_dsn_index = (self.active_dsn_index + 1) % len(self.dsn_list)
            self.initialize_pool()  # Reinitialize with a new DSN
        except Exception as e:
            print(f"Failed to handle connection failure: {e}")

    def detect_schema_change(self, conn):
        try:
            cursor = conn.cursor()
            cursor.execute("SELECT column_name FROM information_schema.columns WHERE table_name='my_table'")
            current_columns = [row[0] for row in cursor.fetchall()]

            with open('schema_version.txt', 'r') as file:
                stored_columns = file.read().splitlines()

            if current_columns != stored_columns:
                print("Schema change detected!")
                with open('schema_version.txt', 'w') as file:
                    file.write("\n".join(current_columns))
        except Exception as e:
            print(f"Failed to detect schema changes: {e}")

# Example usage
dsn_list = ["dbname=test user=postgres", "dbname=test2 user=postgres"]
db_manager = DistributedDBManager(dsn_list)
result = db_manager.execute_query("SELECT * FROM my_table")
print(result)

conn = db_manager.get_connection()
db_manager.detect_schema_change(conn)
db_manager.release_connection(conn)
