#include <forward_list>
#include <string>
#include <iostream>

void insertWithLimits(std::forward_list<std::string>& flist, 
                      const std::string& searchString,
                      const std::string& insertionString,
                      int maxInsertions) {
    if (flist.empty()) {
        throw std::invalid_argument("The input list is empty.");
    }

    // Truncate the insertion string to a maximum of 100 characters
    std::string truncatedInsertion = (insertionString.length() > 100)
                                     ? insertionString.substr(0, 100)
                                     : insertionString;

    int foundCount = 0;
    auto it = flist.before_begin();
    for (auto currIt = flist.begin(); currIt != flist.end() && foundCount < maxInsertions; ++currIt) {
        if (*currIt == searchString) {
            // Truncate current string if necessary
            if ((*currIt).length() > 100) {
                *currIt = (*currIt).substr(0, 100);
            }
            it = currIt;
            foundCount++;
            break;
        } else {
            // Truncate each element while iterating to maintain constraints
            if (currIt->length() > 100) {
                *currIt = currIt->substr(0, 100);
            }
        }
    }

    if (foundCount == 0 && it != flist.before_begin()) {
        // Insert at the end of list if not found within first maxInsertions
        flist.insert_after(it, truncatedInsertion);
    } else if (it != flist.before_begin()) {
        flist.insert_after(it, truncatedInsertion);
    }
}

int main() {
    std::forward_list<std::string> myFList = {"apple", "banana", "cherry"};
    try {
        insertWithLimits(myFList, "banana", "kiwi", 1);

        for (const auto& item : myFList) {
            std::cout << item << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
