[Serializable]
public class VersionedFinancialTransactionList
{
    public int SchemaVersion { get; set; }
    public List<FinancialTransaction> Transactions { get; set; } = new List<FinancialTransaction>();

    public void Serialize(string filePath)
    {
        using var fileStream = new FileStream(filePath, FileMode.Create);
        using var formatter = new BinaryFormatter();
        formatter.Serialize(fileStream, this);
    }

    public static VersionedFinancialTransactionList Deserialize(string filePath)
    {
        using var fileStream = new FileStream(filePath, FileMode.Open);
        using var formatter = new BinaryFormatter();
        return (VersionedFinancialTransactionList)formatter.Deserialize(fileStream);
    }
}

public class TransactionDataLoader
{
    private readonly HttpClient _httpClient;

    public TransactionDataLoader(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<VersionedFinancialTransactionList> LoadAndValidateTransactionsAsync(string filePath, string apiEndpoint)
    {
        var transactionData = await DeserializeWithStreaming(filePath);
        if (transactionData == null) throw new InvalidOperationException("Deserialization failed.");

        bool isValid = await ValidateWithExternalAPIAsync(transactionData, apiEndpoint);
        if (!isValid) throw new Exception("Schema validation failed.");

        LogProgress("Transactions loaded and validated successfully.");
        return transactionData;
    }

    private async Task<VersionedFinancialTransactionList> DeserializeWithStreaming(string filePath)
    {
        try
        {
            using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read);
            using var formatter = new BinaryFormatter();

            // Use a buffer and read in chunks to handle large files.
            const int bufferSize = 1024 * 1024; // 1MB buffer size for efficient reading
            byte[] buffer = new byte[bufferSize];
            var memoryStream = new MemoryStream();

            while (true)
            {
                int bytesRead = await fileStream.ReadAsync(buffer, 0, bufferSize);
                if (bytesRead == 0) break;
                memoryStream.Write(buffer, 0, bytesRead);
            }

            memoryStream.Seek(0, SeekOrigin.Begin);
            return (VersionedFinancialTransactionList)formatter.Deserialize(memoryStream);
        }
        catch (Exception ex)
        {
            LogError("Deserialization error: " + ex.Message);
            return null;
        }
    }

    private async Task<bool> ValidateWithExternalAPIAsync(VersionedFinancialTransactionList data, string apiEndpoint)
    {
        try
        {
            var response = await _httpClient.PostAsJsonAsync(apiEndpoint, data);

            if (!response.IsSuccessStatusCode) 
            {
                LogError("API validation failed: " + response.ReasonPhrase);
                return false;
            }

            var validationResult = await response.Content.ReadAsAsync<bool>();
            return validationResult ?? false;
        }
        catch (HttpRequestException ex)
        {
            LogError("Network error during API call: " + ex.Message);
            // Implement retry with exponential backoff
            await Task.Delay(TimeSpan.FromSeconds(2)); // Placeholder for actual implementation
            return await ValidateWithExternalAPIAsync(data, apiEndpoint); // Retry logic.
        }
    }

    private void LogProgress(string message)
    {
        Console.WriteLine("[INFO] " + message);
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine("[ERROR] " + message);
    }
}

// Example Usage:
