// JavaScript code to load and execute a specified file within a web page context

function loadAndExecuteScript(url) {
    return new Promise((resolve, reject) => {
        const script = document.createElement('script');

        script.src = url;
        script.async = true;

        script.onload = () => resolve(`Successfully loaded ${url}`);
        script.onerror = () => reject(new Error(`Failed to load the script: ${url}`));

        // Append to head to start loading
        document.head.appendChild(script);
    });
}

async function loadScriptsInOrder(urls) {
    for (const url of urls) {
        try {
            const message = await loadAndExecuteScript(url);
            console.log(message);
        } catch (error) {
            console.error(error.message);
        }
    }
}
