// mylib.c

#include "mylib.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* append_slash_if_within_limit(const char *str, size_t max_length) {
    if (str == NULL || strlen(str) + 1 > max_length) {
        return NULL;
    }

    size_t new_len = strlen(str) + 2; // +1 for slash and null terminator
    char *result = malloc(new_len);
    if (!result) {
        return NULL;
    }

    snprintf(result, new_len, "%s/", str);
    return result;
}

void log_error_message(const char *condition, const char *message, ...) {
    if (strcmp(condition, "true") == 0) { // Example condition check
        va_list args;
        va_start(args, message);

        static FILE *log_file = NULL;
        if (!log_file) {
            log_file = fopen("error_log.txt", "a");
            if (!log_file) {
                perror("Failed to open error log file");
                return;
            }
        }

        char buffer[1024];
        vsnprintf(buffer, sizeof(buffer), message, args);
        fprintf(log_file, "%s\n", buffer);

        va_end(args);
    }
}

