#include <iostream>
#include <fstream>
#include <limits>
#include <string>
#include <sstream>
#include <vector>

void logMessage(const std::string& message) {
    std::ofstream logFile("process_log.txt", std::ios_base::app);
    if (logFile.is_open()) {
        logFile << message << std::endl;
    } else {
        std::cerr << "Unable to open log file for writing." << std::endl;
    }
}

bool readFile(const std::string& filename, std::vector<float>& data) {
    std::ifstream inputFile(filename);
    if (!inputFile.is_open()) {
        logMessage("Error: Unable to open input file.");
        return false;
    }

    float value;
    while (inputFile >> value) {
        data.push_back(value);
    }

    if (inputFile.bad()) {
        logMessage("Error: Read error occurred in the input file.");
        return false;
    }

    inputFile.close();
    return true;
}

bool writeFile(const std::string& filename, float minVal, float maxVal) {
    std::ofstream outputFile(filename);
    if (!outputFile.is_open()) {
        logMessage("Error: Unable to open output file for writing.");
        return false;
    }

    outputFile << "Min value: " << minVal << "\n";
    outputFile << "Max value: " << maxVal << "\n";

    outputFile.close();
    return true;
}

void findMinMax(const std::vector<float>& data, float& minValue, float& maxValue) {
    if (data.empty()) {
        logMessage("Error: Dataset is empty.");
        minValue = std::numeric_limits<float>::quiet_NaN();
        maxValue = std::numeric_limits<float>::quiet_NaN();
        return;
    }

    minValue = data[0];
    maxValue = data[0];

    for (size_t i = 1; i < data.size(); ++i) {
        if (data[i] < minValue)
            minValue = data[i];
        if (data[i] > maxValue)
            maxVal = data[i];
    }
}

int main() {
    std::vector<float> dataset;
    float minVal, maxVal;

    logMessage("Program started.");

    if (!readFile("input_data.txt", dataset)) {
        return EXIT_FAILURE;
    }

    logMessage("Data read successfully.");

    findMinMax(dataset, minVal, maxVal);

    if (std::isnan(minVal) || std::isnan(maxVal)) {
        logMessage("Error: Unable to compute min/max values due to empty data or errors.");
        return EXIT_FAILURE;
    }

    logMessage("Min and Max values calculated.");

    if (!writeFile("output_stats.txt", minVal, maxVal)) {
        return EXIT_FAILURE;
    }

    logMessage("Statistics written successfully.");
    logMessage("Program completed successfully.");

    return EXIT_SUCCESS;
}
