```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class GitIntegration {
    private static final String GIT_LOG_COMMAND = "git log -1 --pretty=%B";
    private static final int TIMEOUT_SECONDS = 30;
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        if (args.length < 3) {
            System.err.println("Usage: java GitIntegration <repoPath> <branchName> <outputFilePath>");
            System.exit(1);
        }

        String repoPath = args[0];
        String branchName = args[1];
        String outputFilePath = args[2];

        File repositoryDir = new File(repoPath);
        if (!repositoryDir.exists() || !repositoryDir.isDirectory()) {
            System.err.println("Invalid repository path.");
            System.exit(1);
        }

        deleteOutputFile(outputFilePath);

        try {
            int exitValue;
            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                long startTime = System.currentTimeMillis();
                ProcessBuilder processBuilder = new ProcessBuilder(
                        "git", "checkout", branchName, "--quiet",
                        "&&", "git", "fetch", "--quiet",
                        "&&", "git", GIT_LOG_COMMAND)
                        .directory(repositoryDir)
                        .redirectErrorStream(true);

                try (Process process = processBuilder.start()) {
                    ExecutorService executor = Executors.newSingleThreadExecutor();
                    Future<String> futureOutput = executor.submit(() -> readStream(process.getInputStream()));
                    Future<String> futureError = executor.submit(() -> readStream(process.getErrorStream()));

                    exitValue = waitForCompletion(process, TIMEOUT_SECONDS);

                    String output = futureOutput.get();
                    String error = futureError.get();

                    logExecutionDetails(startTime, System.currentTimeMillis(), exitValue, output, error);

                    if (exitValue == 0) {
                        try (PrintWriter writer = new PrintWriter(Files.newBufferedWriter(Paths.get(outputFilePath)))) {
                            writer.println(output);
                        }
                        break;
                    } else {
                        System.err.println("Command failed: " + error);
                    }
                } catch (TimeoutException e) {
                    process.destroy();
                    System.err.println("Operation timed out.");
                } catch (InterruptedException | ExecutionException e) {
                    System.err.println("An error occurred during execution.");
                }
            }

        } catch (IOException | InterruptedException | ExecutionException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static void deleteOutputFile(String outputFilePath) throws IOException {
        File outputFile = new File(outputFilePath);
        if (outputFile.exists()) {
            if (!outputFile.delete()) {
                throw new IOException("Failed to delete existing output file.");
            }
        }
    }

    private static String readStream(InputStream inputStream) throws IOException {
        StringBuilder result = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                result.append(line).append(System.lineSeparator());
            }
        }
        return result.toString().trim();
    }

    private static int waitForCompletion(Process process, int timeoutSeconds)
            throws TimeoutException, InterruptedException {
        if (process.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
            return process.exitValue();
        } else {
            throw new TimeoutException("Process did not complete within the timeout period.");
        }
    }

    private static void logExecutionDetails(long startTime, long endTime, int exitValue, String output, String error) {
        System.out.println("Start Time: " + (new java.util.Date(startTime)));
        System.out.println("End Time: " + (new java.util.Date(endTime)));
        System.out.println("Duration: " + ((endTime - startTime) / 1000.0) + " seconds");
        System.out.println("Exit Value: " + exitValue);
        System.out.println("Output: " + output);
        if (!error.isEmpty()) {
            System.err.println("Error: " + error);
        }
    }
}
