const fs = require('fs');
const path = require('path');

// Mock package manager to resolve module dependencies
function resolveDependencies(modules) {
  // This function should return an array of modules sorted by their dependencies.
  // For simplicity, assume it returns the input as-is. In practice, this would use npm or similar.
  return modules;
}

async function loadModule(filename) {
  const modulePath = path.resolve(__dirname, filename);
  if (!fs.existsSync(modulePath)) {
    throw new Error(`Module not found: ${filename}`);
  }

  try {
    const moduleCode = fs.readFileSync(modulePath, 'utf-8');
    const context = { exports: {} };

    // Function to simulate `require`
    function require(filename) {
      return loadModule(path.join(path.dirname(modulePath), filename));
    }

    new Function('exports', 'require', moduleCode)(context.exports, require);
    return context.exports;
  } catch (error) {
    throw new Error(`Failed to load module: ${filename}. Error: ${error.message}`);
  }
}

async function executeModules(modules) {
  const sortedModules = resolveDependencies(modules);

  for (const filename of sortedModules) {
    try {
      console.log(`Loading module: ${filename}`);
      const moduleExports = await loadModule(filename);

      if (typeof moduleExports === 'function') {
        console.log(`Executing module function from: ${filename}`);
        await moduleExports();
      } else {
        console.log(`No executable function found in: ${filename}`);
      }
    } catch (error) {
      console.error(error.message);
    }
  }
}

