class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& io_context, const std::string& server_address)
        : resolver_(io_context), socket_(io_context) {}

    void SendAsyncRequest(const std::string& request, boost::system::error_code& ec) {
        tcp::resolver::query query(server_address_, "http");
        auto endpoints = resolver_.resolve(query);
        boost::asio::async_connect(socket_, endpoints,
            [this, request](const boost::system::error_code& error, const tcp::endpoint&) mutable {
                if (!error) {
                    // Send the HTTP GET request
                    std::string message = "GET /" + request + " HTTP/1.0\r\nHost: " + server_address_ + "\r\n\r\n";
                    boost::asio::write(socket_, boost::asio::buffer(message));
                } else {
                    ec = error;
                }
            });
    }

private:
