```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public class SecureEncryptionManager
{
    private static readonly byte[] KeySize128 = new byte[16];
    private static readonly byte[] IvSize16 = new byte[16];

    public byte[] DecryptAesCbc(byte[] ciphertext, byte[] key = null, byte[] iv = null, PaddingMode paddingMode = PaddingMode.PKCS7)
    {
        if (ciphertext == null || ciphertext.Length < 16) throw new ArgumentException("Invalid ciphertext.");

        using (var aesAlg = Aes.Create())
        {
            aesAlg.KeySize = 128;
            aesAlg.Mode = CipherMode.CBC;

            key ??= GenerateSecureRandomBytes(KeySize128);
            iv ??= GenerateSecureRandomBytes(IvSize16);

            if (key.Length != KeySize128.Length || iv.Length != IvSize16.Length)
                throw new ArgumentException("Invalid key or IV size.");

            aesAlg.Key = key;
            aesAlg.IV = iv;

            using var decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
            var paddingModeFlag = (int)paddingMode switch
            {
                (int)PaddingMode.PKCS7 => PaddingMode.PKCS7,
                _ => throw new ArgumentException("Unsupported padding mode."),
            };

            using var msDecrypt = new System.IO.MemoryStream(ciphertext);
            using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);

            var plaintextBytes = new byte[ciphertext.Length];
            int decryptedByteCount = csDecrypt.Read(plaintextBytes, 0, plaintextBytes.Length);

            // Remove padding
            if (paddingMode == PaddingMode.PKCS7)
            {
                int paddingLength = plaintextBytes[decryptedByteCount - 1];
                if (paddingLength < 1 || paddingLength > aesAlg.BlockSize / 8)
                    throw new CryptographicException("Invalid padding.");

                decryptedByteCount -= paddingLength;
            }

            byte[] plaintext = new byte[decryptedByteCount];
            Array.Copy(plaintextBytes, plaintext, decryptedByteCount);

            return plaintext;
        }
    }

    public byte[] DecryptAesGcm(byte[] ciphertext, byte[] key = null, byte[] iv = null, byte[] tag = null)
    {
        if (ciphertext == null || (tag != null && tag.Length != 16) || ciphertext.Length < 16) throw new ArgumentException("Invalid ciphertext or tag.");

        using var aesGcm = new AesGcm(key ?? GenerateSecureRandomBytes(KeySize128));

        iv ??= GenerateSecureRandomBytes(IvSize16);
        if (iv.Length != IvSize16.Length)
            throw new ArgumentException("Invalid IV size.");

        byte[] plaintext = new byte[ciphertext.Length - tag?.Length];
        aesGcm.Open(iv, tag, ciphertext, plaintext);

        return plaintext;
    }

    private static byte[] GenerateSecureRandomBytes(byte[] data)
    {
        using var rng = RandomNumberGenerator.Create();
        rng.GetBytes(data);
        return data;
    }
}
```

### Explanation:

- **AES-CBC Decryption**: Handles decryption of a given ciphertext in AES-CBC mode with support for PKCS7 padding. Generates random IV and key if not provided.
- **AES-GCM Decryption**: Supports decryption using AES-GCM, which does not require padding but uses an authentication tag to verify the integrity of the data.
- **Error Handling**: Ensures various checks such as ciphertext length, key size, and IV size are in place to prevent cryptographic errors.
- **Secure Random Generation**: Uses `RandomNumberGenerator` for secure generation of random keys and IVs if they are not supplied.

