using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using UnityEngine;

public enum DistributionType { Uniform, Gaussian, Exponential }

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, (DistributionType type, float[] parameters)> _distributions = new();
    private readonly ConcurrentDictionary<string, object> _cache = new();
    private const int MaxCacheSize = 100;
    private string _currentConfigKey;

    public void SetConfiguration(string key, DistributionType type, float[] parameters)
    {
        if (key == null) throw new ArgumentNullException(nameof(key));
        if (parameters == null || parameters.Length < 1) throw new ArgumentException("Parameters must have at least one value.", nameof(parameters));

        _distributions[key] = (type, parameters);
        InvalidateCache();
    }

    public void SetCurrentConfiguration(string key)
    {
        if (!_distributions.ContainsKey(key)) throw new InvalidOperationException($"Configuration '{key}' not found.");

        _currentConfigKey = key;
        InvalidateCache();
    }

    private void InvalidateCache()
    {
        _cache.Clear();
    }

    public float GetRandomValue(float min, float max, bool inclusive)
    {
        string cacheKey = $"{_currentConfigKey}:{min}:{max}:{inclusive}";

        if (!_cache.TryGetValue(cacheKey, out var cachedResult))
        {
            (DistributionType type, float[] parameters) distribution = _distributions[_currentConfigKey];

            float result;
            switch (type)
            {
                case DistributionType.Uniform:
                    result = UnityEngine.Random.Range(min, max);
                    break;

                case DistributionType.Gaussian:
                    float mean = min + (max - min) / 2;
                    float stddev = parameters[0] > 0 ? parameters[0] : 1.0f; // fallback
                    result = Mathf.Max(min, Mathf.Min(max, UnityEngine.Random.value * stddev + mean));
                    break;

                case DistributionType.Exponential:
                    float lambda = parameters[0] > 0 ? parameters[0] : 1.0f; // fallback
                    result = min + (-Mathf.Log(1 - UnityEngine.Random.value) / lambda);
                    if (!inclusive && result >= max)
                        result -= (max - min) * 0.001f;
                    break;

                default:
                    throw new NotSupportedException($"Distribution type '{type}' is not supported.");
            }

            cachedResult = result;
            _cache[cacheKey] = result;

            // Implement LRU eviction
            if (_cache.Count > MaxCacheSize)
            {
                var leastRecentlyUsedKey = (from kvp in _cache orderby kvp.Value ascending select kvp.Key).FirstOrDefault();
                if (!string.IsNullOrEmpty(leastRecentlyUsedKey))
                    _cache.TryRemove(leastRecentlyUsedKey, out _);
            }
        }

        return (float)cachedResult;
    }

    public int GetRandomInteger(int min, int max)
    {
        string cacheKey = $"{_currentConfigKey}:{min}:{max}";

        if (!_cache.TryGetValue(cacheKey, out var cachedResult))
        {
            float randomValue = GetRandomValue(min, max + 1, true);
            cachedResult = Mathf.Round(randomValue);

            _cache[cacheKey] = cachedResult;

            // Implement LRU eviction
            if (_cache.Count > MaxCacheSize)
            {
                var leastRecentlyUsedKey = (from kvp in _cache orderby kvp.Value ascending select kvp.Key).FirstOrDefault();
                if (!string.IsNullOrEmpty(leastRecentlyUsedKey))
                    _cache.TryRemove(leastRecentlyUsedKey, out _);
            }
        }

        return (int)cachedResult;
    }

    public override string ToString()
    {
        var config = _distributions[_currentConfigKey];
        return $"Current Configuration: {_currentConfigKey}, Distribution Type: {config.type}, Parameters: {string.Join(", ", config.parameters)}";
    }
}

public class MultiDimensionalDistribution
{
    private readonly List<float[]> _points;
    private readonly float[,] _correlationMatrix;

    public MultiDimensionalDistribution(int dimensions, float correlation)
    {
        if (dimensions < 2) throw new ArgumentException("At least two dimensions are required.");

        _points = new List<float[]>();
        _correlationMatrix = new float[dimensions, dimensions];

        for (int i = 0; i < dimensions; i++)
            for (int j = 0; j < dimensions; j++)
                _correlationMatrix[i, j] = (i == j) ? 1.0f : correlation;
    }

    public void AddPoint(float[] point)
    {
        if (point.Length != _correlationMatrix.GetLength(0)) throw new ArgumentException("Point dimensionality must match the distribution.");
        _points.Add(point);
    }

    public float[] GenerateRandomValue()
    {
        int dimensions = _points[0].Length;
        var means = new float[dimensions];

        for (int i = 0; i < dimensions; i++)
            means[i] = UnityEngine.Random.Range(-1f, 1f); // Random means

        var randomValues = GaussianRandomVector(means, _correlationMatrix);
        return randomValues;
    }

    private float[] GaussianRandomVector(float[] mean, float[,] covariance)
    {
        int dimensions = mean.Length;

        if (dimensions != covariance.GetLength(0) || dimensions != covariance.GetLength(1))
            throw new InvalidOperationException("Dimensions of mean and covariance matrix must match.");

        var result = new float[dimensions];

        for (int i = 0; i < dimensions; i++)
            result[i] = UnityEngine.Random.value * Mathf.Sqrt(covariance[i, i]) + mean[i];

        return result;
    }
}

