namespace http = boost::beast::http;
using tcp = boost::asio::ip::tcp;

class SandeshClient {
public:
    SandeshClient(const std::string& host, const std::string& port, int maxRetries)
        : resolver_(io_context_), max_retries_(maxRetries) {
        connect(host, port);
    }

    void sendGetRequest(const std::string& path) {
        std::thread([this, path]() { doSend("GET", path); }).detach();
    }

    void sendPostRequest(const std::string& path, const std::string& body) {
        std::thread([this, path, body]() { doSend("POST", path, body); }).detach();
    }

    void startPeriodicStatusCheck() {
        std::thread([this]() { periodicStatusCheck(); }).detach();
    }

private:
    boost::asio::io_context io_context_;
    tcp::resolver resolver_;
    tcp::socket socket_{io_context_};
    std::mutex socket_mutex_;
    int max_retries_;

    void connect(const std::string& host, const std::string& port) {
        auto endpoints = resolver_.resolve(host, port);
        boost::asio::connect(socket_, endpoints.begin(), endpoints.end());
    }

    template <typename Method>
    void doSend(Method method, const std::string& path, const std::string& body = "") {
        std::unique_lock<std::mutex> lock(socket_mutex_);
        http::request<http::empty_body> req{method, path, 11};
        req.set(http::field::host, "example.com");
        if (!body.empty()) {
            req.body() = body;
            req.prepare_payload();
        }

        http::write(socket_, req);

        auto response = std::make_shared<http::response<http::dynamic_body>>();
        http::read(socket_, buffer_, *response);

        logRequest(method, path, response->result_int());
    }

    void periodicStatusCheck() {
        while (true) {
            sendGetRequest("/status");
            std::this_thread::sleep_for(std::chrono::seconds(10));
        }
    }

    static std::string findVmUuidFromMetadataIp(const std::string& ip) {
        // Mock implementation
        return "mock-uuid";
    }

    void logRequest(http::verb method, const std::string& path, int status_code) {
        std::cout << "Method: " << http::to_string(method)
                  << ", Path: " << path
                  << ", Status Code: " << status_code << "\n";
    }
};

int main() {
    SandeshClient client("example.com", "80", 3);
    client.sendGetRequest("/test");
    client.sendPostRequest("/submit", "{\"data\":\"value\"}");
    client.startPeriodicStatusCheck();

    boost::asio::steady_timer timer{client.io_context_, std::chrono::minutes(1)};
    timer.async_wait([](const boost::system::error_code& ec) {
        if (!ec) {
            std::cout << "Shutting down...\n";
        }
    });
    client.io_context_.run();
}
