std::chrono::steady_clock::time_point last_rotation_time;

enum LogLevel { DEBUG, INFO, WARN, ERROR, CRITICAL };

// Function to load configuration from JSON
void loadConfiguration(const std::string& configFile) {
    Json::Value root;
    std::ifstream configStream(configFile, std::ifstream::binary);
    configStream >> root;

    for (const auto& key : root.getMemberNames()) {
        const auto& value = root[key];
        if (value.isInt()) {
            config[key] = value.asInt();
        } else if (value.isDouble()) {
            config[key] = value.asDouble();
        } else if (value.isString()) {
            config[key] = value.asString();
        } else if (value.isTrue() || value.isFalse()) {
            config[key] = value.asBool();
        }
    }
}

