void rateLimiter(int maxMessagesPerSecond) {
    static std::chrono::steady_clock::time_point lastMessageTime;
    auto now = std::chrono::steady_clock::now();

    if (std::chrono::duration_cast<std::chrono::seconds>(now - lastMessageTime).count() < 1.0 / maxMessagesPerSecond) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Sleep to throttle
    }
    lastMessageTime = now;
}

