<?php

namespace PasswordManager;

use Exception;
use Psr\Log\LoggerInterface;
use Redis;

class PasswordManager
{
    private $logger;
    private $redisClient;
    private const MAX_REQUESTS_PER_MINUTE = 100;
    private $requestCounter = 0;
    private $startTime;

    public function __construct(LoggerInterface $logger, Redis $redisClient)
    {
        $this->logger = $logger;
        $this->redisClient = $redisClient;
        $this->startTime = time();
    }

    public function generatePasswordHash(string $password, string $algorithm = PASSWORD_DEFAULT): array
    {
        if ($this->isRateLimited()) {
            throw new Exception("Rate limit exceeded.");
        }

        $salt = $this->generateSalt();
        $options = $this->getOptionsForAlgorithm($algorithm);

        $hash = password_hash("$salt.$password", $algorithm, $options);

        if ($hash === false) {
            $this->logger->error("Password hashing failed for algorithm: $algorithm");
            throw new Exception("Hashing failed.");
        }

        $this->storeInDatabase($salt, $hash);

        $this->incrementRequestCounter();

        return ['salt' => $salt, 'hash' => $hash];
    }

    public function validatePassword(string $password, string $storedHash): bool
    {
        if ($this->isRateLimited()) {
            throw new Exception("Rate limit exceeded.");
        }

        [$salt, $hash] = explode('.', $storedHash, 2);

        $valid = password_verify("$salt.$password", $storedHash);

        $this->incrementRequestCounter();

        return $valid;
    }

    private function generateSalt(): string
    {
        // Dynamic salt generation logic here
        return bin2hex(random_bytes(16));
    }

    private function getOptionsForAlgorithm(string $algorithm): array
    {
        switch ($algorithm) {
            case PASSWORD_BCRYPT:
                return ['cost' => 12];
            case PASSWORD_ARGON2ID:
                return [
                    'memory_cost' => 1<<17,
                    'time_cost' => 4,
                    'threads' => 2
                ];
            default:
                return [];
        }
    }

    private function storeInDatabase(string $salt, string $hash): void
    {
        // Store salt and hash in Redis or another distributed database
        $this->redisClient->set("password:{$salt}", $hash);
    }

    private function isRateLimited(): bool
    {
        if (time() - $this->startTime >= 60) {
            $this->requestCounter = 0;
            $this->startTime = time();
        }

        return $this->requestCounter >= self::MAX_REQUESTS_PER_MINUTE;
    }

    private function incrementRequestCounter(): void
    {
        $this->requestCounter++;
    }
}

// Usage example with a PSR-3 compatible logger and Redis client

