```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

// Record structure definition
typedef struct {
    long id;
    double timestamp;
    char **tags;
    char **metadata;
} Record;

// Database server configuration
typedef struct {
    char *address;
    sqlite3 *connection;
    pthread_mutex_t lock; // Mutex for thread safety on connection
} DBServerConfig;

// Global variables for database servers and cache
DBServerConfig dbServers[10];
char* cache[(int)1e6]; // Example fixed-size cache

// Cache mutex
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the database server configuration
void init_db_server(DBServerConfig *server, const char *address) {
    server->address = strdup(address);
    if (sqlite3_open(server->address, &(server->connection)) != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(server->connection));
        exit(1);
    }
    pthread_mutex_init(&(server->lock), NULL);
}

// Function to clean up resources for a server
void cleanup_db_server(DBServerConfig *server) {
    sqlite3_close(server->connection);
    free((void*)server->address);
    pthread_mutex_destroy(&(server->lock));
}

// Database query function with error handling and caching
int db_query(DBServerConfig *server, const char *query, Record **result, int *count) {
    sqlite3_stmt *stmt;
    if (sqlite3_prepare_v2(server->connection, query, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(server->connection));
        return -1;
    }

    // Execute the query and populate result
    int rc = SQLITE_ROW;
    *count = 0;
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        (*count)++;
    }

    if (rc != SQLITE_DONE) {
        fprintf(stderr, "Query execution failed: %s\n", sqlite3_errmsg(server->connection));
        sqlite3_finalize(stmt);
        return -1;
    }

    // Allocate memory for results
    *result = malloc(sizeof(Record) * (*count));

    sqlite3_reset(stmt); // Reset to reuse the statement

    int i = 0;
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        (*result)[i].id = sqlite3_column_int64(stmt, 0);
        (*result)[i].timestamp = sqlite3_column_double(stmt, 1);

        // Allocate memory for tags and metadata
        int tag_count = sqlite3_column_count(stmt); // Assume two columns: id and timestamp
        (*result)[i].tags = malloc(sizeof(char*) * (tag_count - 2));
        (*result)[i].metadata = malloc(sizeof(char*) * (tag_count - 2));

        for (int j = 2; j < tag_count; ++j) {
            char* data = strdup((char*)sqlite3_column_text(stmt, j)); // Assume text columns
            if (j % 2 == 0) { // Assume even indices are tags
                (*result)[i].tags[(j - 2) / 2] = data;
            } else {
                (*result)[i].metadata[(j - 3) / 2] = data;
            }
        }

        i++;
    }
    sqlite3_finalize(stmt);
    return 0; // Success
}

// Example function to distribute load and balance queries
int balanced_query(DBServerConfig *servers, int server_count, const char *query, Record **result, int *count) {
    static int next_server = 0;

    pthread_mutex_lock(&cache_lock); 
    for (int i = 0; i < server_count; ++i) {
        if (next_server == i) {
            DBServerConfig *server = &servers[i];

            // Simple caching check
            pthread_mutex_lock(&(server->lock));
            int cache_hit = 0;
            char cache_key[256] = {0};
            snprintf(cache_key, sizeof(cache_key), "%s:%d", server->address, hash_query(query));

            for (int j = 0; j < (int)1e6; ++j) {
                if (cache[j] && strcmp(cache[j], cache_key) == 0) {
                    *result = fetch_from_cache(j); // Assume function to retrieve from cache
                    *count = get_cached_count(*result);
                    cache_hit = 1;
                    break;
                }
            }

            if (!cache_hit) {
                int rc = db_query(server, query, result, count);

                if (rc == 0) {
                    store_in_cache(cache_key, *result, *count); // Assume function to store in cache
                } else {
                    pthread_mutex_unlock(&(server->lock));
                    return -1;
                }
            }
            pthread_mutex_unlock(&(server->lock));
            next_server = (next_server + 1) % server_count;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return 0; // Success
}

// Example function to clean up all servers and cache resources
void cleanup_all(DBServerConfig *servers, int server_count) {
    for (int i = 0; i < server_count; ++i) {
        cleanup_db_server(&servers[i]);
    }
    pthread_mutex_destroy(&cache_lock);
}

// Main program or test function
void run_example() {
    DBServerConfig servers[2];

    init_db_server(&servers[0], "server1.sqlite");
    init_db_server(&servers[1], "server2.sqlite");

    Record *results = NULL;
    int count = 0;

    const char *query = "SELECT id, timestamp, tags, metadata FROM records";

    if (balanced_query(servers, 2, query, &results, &count) == 0) {
        for (int i = 0; i < count; ++i) {
            printf("Record ID: %ld, Timestamp: %.2f\n", results[i].id, results[i].timestamp);
            // Free memory allocated for tags and metadata
            for (int j = 0; j < (sqlite3_column_count(servers[0].connection) - 2); ++j) {
                free(results[i].tags[j]);
                free(results[i].metadata[j]);
            }
            free(results[i].tags);
            free(results[i].metadata);
        }
    } else {
        fprintf(stderr, "Failed to retrieve records\n");
    }

    cleanup_all(servers, 2);
}

int main() {
    run_example();
    return 0;
}
```

