```csharp
using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

public class WebsiteManager
{
    private static readonly object LockObj = new object();
    private static readonly string LogFilePath = "website_manager.log";

    public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            LogError($"Invalid directory path: {directoryPath}");
            return null;
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            LogInfo("Missing web.config file.");
            return null;
        }

        if (IsSiteAlreadyRunning(siteName))
        {
            LogInfo($"Site {siteName} is already running.");
            return $"Site '{siteName}' is already running.";
        }

        string serverType = DetectWebServer(directoryPath);
        if (string.IsNullOrEmpty(serverType))
        {
            LogError("Unable to detect web server type.");
            return null;
        }

        try
        {
            await StartWebServerAsync(directoryPath, siteName, serverType);
            SaveSiteDetails(directoryPath, siteName);
            LogInfo($"Successfully added and started site '{siteName}' using {serverType}.");
            return $"Site '{siteName}' successfully started.";
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            return null;
        }
    }

    private bool IsSiteAlreadyRunning(string siteName)
    {
        var processes = Process.GetProcessesByName("w3wp").ToList();
        foreach (var process in processes)
        {
            if (process.MainModule.FileName.Contains(siteName))
                return true;
        }
        return false;
    }

    private string DetectWebServer(string directoryPath)
    {
        if (File.Exists(Path.Combine(directoryPath, "applicationHost.config")))
        {
            return "IIS";
        }
        else if (File.Exists(Path.Combine(directoryPath, "httpd.conf")))
        {
            return "Apache";
        }
        return null;
    }

    private async Task StartWebServerAsync(string directoryPath, string siteName, string serverType)
    {
        lock (LockObj)
        {
            var startInfo = new ProcessStartInfo
            {
                FileName = DetermineExecutable(serverType),
                Arguments = $"{directoryPath} {siteName}",
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true
            };

            using (var process = new Process { StartInfo = startInfo })
            {
                process.EnableRaisingEvents = true;
                process.Exited += (sender, args) => OnProcessExit(sender, args);

                if (!process.Start())
                {
                    throw new InvalidOperationException("Failed to start web server.");
                }

                await Task.Run(() => process.WaitForExit());
            }
        }
    }

    private string DetermineExecutable(string serverType)
    {
        return serverType switch
        {
            "IIS" => "iisexpress.exe",
            "Apache" => "httpd.exe",
            _ => throw new InvalidOperationException("Unsupported web server type.")
        };
    }

    private void OnProcessExit(object sender, EventArgs e)
    {
        LogInfo($"Web server process exited: {sender}");
    }

    private void SaveSiteDetails(string directoryPath, string siteName)
    {
        // Configuration management system interaction
        File.AppendAllText("site_configurations.txt", $"{directoryPath},{siteName}\n");
    }

    private void LogInfo(string message) => Log(message, "INFO");

    private void LogError(string message) => Log(message, "ERROR");

    private void Log(string message, string level)
    {
        lock (LockObj)
        {
            File.AppendAllText(LogFilePath, $"{DateTime.Now} [{level}] {message}\n");
        }
    }
}
