public class WebsiteManagerTests
{
    [Fact]
    public async Task AddAndStartWebsite_WithValidInputs_ShouldSucceed()
    {
        var manager = new WebsiteManager();
        string result = await manager.AddAndStartWebsiteAsync("C:\\TestDirectory", "TestSite");

        Assert.NotNull(result);
        Assert.Contains("successfully started", result, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task AddAndStartWebsite_WithMissingWebConfig_ShouldReturnNull()
    {
        var manager = new WebsiteManager();
        string directoryPath = Path.Combine(Path.GetTempPath(), "TestWithoutWebConfig");
        Directory.CreateDirectory(directoryPath);

        string result = await manager.AddAndStartWebsiteAsync(directoryPath, "TestSite");

        Assert.Null(result);
    }

    [Fact]
    public async Task AddAndStartWebsite_WithAlreadyRunningSite_ShouldPreventDuplicateStartup()
    {
        var manager = new WebsiteManager();
        string directoryPath = Path.Combine(Path.GetTempPath(), "TestWithWebConfig");
        Directory.CreateDirectory(directoryPath);

        File.WriteAllText(Path.Combine(directoryPath, "web.config"), "<configuration></configuration>");

        // Simulate site already running
        Process.Start("iisexpress.exe", $"/path \"{directoryPath}\" /siteName \"TestSite\"").WaitForExit();

        string result = await manager.AddAndStartWebsiteAsync(directoryPath, "TestSite");

        Assert.NotNull(result);
        Assert.Contains("already running", result, StringComparison.OrdinalIgnoreCase);
    }
}
