```python
import os
import string
import secrets
import requests
from datetime import datetime, timedelta
from functools import lru_cache
from threading import Lock
from ratelimit import limits, sleep_and_retry
from jwt import encode as jwt_encode, decode as jwt_decode, PyJWTError
import redis

# Constants
TOKEN_LENGTH = 32
OAUTH2_TOKEN_URL = "https://example.com/oauth/token"
OAUTH2_INTROSPECTION_URL = "https://example.com/oauth/introspect"
RATE_LIMIT_REQUESTS = 100
RATE_LIMIT_PERIOD = 60  # seconds
REDIS_HOST = 'localhost'
REDIS_PORT = 6379

# Redis connection for rate limiting and caching
redis_client = redis.StrictRedis(host=REDIS_HOST, port=REDIS_PORT, db=0)

class APITokenManager:
    def __init__(self, client_id, client_secret):
        self.client_id = client_id
        self.client_secret = client_secret
        self.lock = Lock()

    @staticmethod
    def generate_secure_token(length=TOKEN_LENGTH):
        characters = string.ascii_letters + string.digits + string.punctuation
        return ''.join(secrets.choice(characters) for _ in range(length))

    @sleep_and_retry
    @limits(calls=RATE_LIMIT_REQUESTS, period=RATE_LIMIT_PERIOD)
    def request_oauth_token(self, scope="default"):
        with self.lock:
            data = {
                'grant_type': 'client_credentials',
                'client_id': self.client_id,
                'client_secret': self.client_secret,
                'scope': scope
            }
            response = requests.post(OAUTH2_TOKEN_URL, json=data)
            if response.status_code == 200:
                return response.json()
            else:
                raise Exception(f"Failed to get token: {response.text}")

    def refresh_oauth_token(self, refresh_token):
        with self.lock:
            data = {
                'grant_type': 'refresh_token',
                'refresh_token': refresh_token,
                'client_id': self.client_id,
                'client_secret': self.client_secret
            }
            response = requests.post(OAUTH2_TOKEN_URL, json=data)
            if response.status_code == 200:
                return response.json()
            else:
                raise Exception(f"Failed to refresh token: {response.text}")

    def revoke_oauth_token(self, token):
        with self.lock:
            data = {
                'token': token,
                'client_id': self.client_id,
                'client_secret': self.client_secret
            }
            response = requests.post(OAUTH2_TOKEN_URL + '/revoke', json=data)
            if response.status_code != 200:
                raise Exception(f"Failed to revoke token: {response.text}")

    def introspect_token(self, token):
        with self.lock:
            data = {
                'token': token
            }
            response = requests.post(OAUTH2_INTROSPECTION_URL, json=data)
            if response.status_code == 200:
                return response.json()
            else:
                raise Exception(f"Token introspection failed: {response.text}")

    def create_jwt(self, payload):
        secret_key = os.getenv('JWT_SECRET_KEY', 'default_secret')
        exp_time = datetime.utcnow() + timedelta(hours=1)
        payload.update({'exp': exp_time})
        return jwt_encode(payload, secret_key, algorithm='HS256')

    def decode_jwt(self, token):
        try:
            secret_key = os.getenv('JWT_SECRET_KEY', 'default_secret')
            return jwt_decode(token, secret_key, algorithms=['HS256'])
        except PyJWTError as e:
            raise Exception(f"Invalid JWT: {str(e)}")

    @staticmethod
    def blacklist_token(token):
        redis_client.setex(token, timedelta(hours=1), 'blacklisted')

    @lru_cache(maxsize=128)
    def check_token_blacklist(self, token):
        return redis_client.get(token) == b'blacklisted'

# Example Usage:
token_manager = APITokenManager(client_id='your-client-id', client_secret='your-client-secret')
access_token_info = token_manager.request_oauth_token(scope="read write")
print(access_token_info)
```

This code snippet provides a class `APITokenManager` that handles secure API token generation and OAuth 2.0 integration, including rate limiting and JWT management, with Redis for caching and blacklisting tokens.

