typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 1000

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, FILE *logFile) {
    if (!crcList || !listSize || maxStructures <= 0 || maxStructures > MAX_STRUCTURES || logFile == NULL) {
        fprintf(logFile, "Error: Invalid input parameters.\n");
        return -1;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    *crcList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crcList == NULL) {
        fprintf(logFile, "Error: Memory allocation failed.\n");
        pthread_mutex_destroy(&lock);
        return -1;
    }

    int uniqueTags[MAX_STRUCTURES] = {0};
    int uniqueRNTIs[MAX_STRUCTURES] = {0};

    for (int i = 0; i < maxStructures; ++i) {
        pthread_mutex_lock(&lock);

        int tag, rnti;
        do {
            tag = rand() % MAX_STRUCTURES + 1;
        } while (uniqueTags[tag - 1]);

        do {
            rnti = rand() % MAX_STRUCTURES + 1;
        } while (uniqueRNTIs[rnti - 1]);

        uniqueTags[tag - 1] = 1;
        uniqueRNTIs[rnti - 1] = 1;

        (*crcList)[i].RX_UE_INFORMATION_TAG = tag;
        (*crcList)[i].RNTI = rnti;
        (*crcList)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        pthread_mutex_unlock(&lock);
    }

    *listSize = maxStructures;

    pthread_mutex_destroy(&lock);
    return 0;
}
