// main.rs

mod lexer;
mod parser;
mod semantic_analysis;
mod optimizer;
mod code_generator;
mod cli;
mod logger;

use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: {} <input_file_path> [options]", args[0]);
        process::exit(1);
    }

    let input_path = &args[1];
    match cli::parse_arguments(&args) {
        Ok(config) => {
            logger::initialize_logging(config.debug_mode);

            if let Err(e) = run_compiler(input_path, config) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        Err(e) => {
            eprintln!("Invalid arguments: {}", e);
            process::exit(1);
        }
    }
}

fn run_compiler(input_path: &str, config: cli::Config) -> Result<(), String> {
    // Resource management using RAII pattern
    let input_file = std::fs::File::open(input_path).map_err(|e| format!("Failed to open file: {}", e))?;

    logger::log("Starting compilation process...");

    let tokens = lexer::Lexer::new(input_file).tokenize().map_err(|e| format!("Lexing error: {}", e))?;
    let ast = parser::Parser::new(tokens).parse().map_err(|e| format!("Parsing error: {}", e))?;

    logger::log("Performing semantic analysis...");
    semantic_analysis::analyze(&ast).map_err(|e| format!("Semantic analysis error: {}", e))?;

    logger::log("Optimizing AST...");
    let optimized_ast = optimizer::optimize(ast, config.custom_passes, config.optimization_level)
        .map_err(|e| format!("Optimization error: {}", e))?;

    logger::log("Generating LLVM IR code...");
    let llvm_ir_code = code_generator::generate_ir(&optimized_ast, config.output_format).map_err(|e| format!("Code generation error: {}", e))?;

    // Integration with external build systems and testing framework
    if let Err(e) = cli::integrate_with_external_systems(llvm_ir_code, &config) {
        return Err(format!("Integration error: {}", e));
    }

    logger::log("Compilation successful.");

    Ok(())
}

