// externalService.js
class ExternalService {
  async fetchNumber(id) {
    const retryDelay = (attempts) => Math.min(1000 * 2 ** attempts + Math.random() * 100, 8000);

    for (let attempt = 0; attempt < 5; attempt++) {
      try {
        // Simulate a database or API fetch
        return await this.simulatedFetch(id);
      } catch (error) {
        if (attempt === 4) throw error;
        console.error(`Fetch failed, retrying... Attempt ${attempt + 1}`);
        await new Promise((resolve) => setTimeout(resolve, retryDelay(attempt)));
      }
    }
  }

  simulatedFetch(id) {
    return new Promise((resolve, reject) => {
      const delay = Math.random() * 100;
      setTimeout(() => {
        if (Math.random() > 0.8) throw new Error('Network error');
        resolve(Math.floor(Math.random() * 100)); // Simulated data fetch
      }, delay);
    });
  }
