// asyncReduce.js
const externalService = new ExternalService();

async function asyncReduce(array, reducer, initialValue) {
  if (!Array.isArray(array)) throw new TypeError("Expected an array");
  const chunkSize = 10;

  async function processChunk(chunk) {
    for (let id of chunk) {
      try {
        const value = await externalService.fetchNumber(id);
        yield value;
      } catch (error) {
        console.error(`Error fetching number ${id}:`, error.message);
      }
    }
  }

  let result = initialValue;

  for (const chunk of Array.from({ length: Math.ceil(array.length / chunkSize)}, (_, i) => array.slice(i * chunkSize, i * chunkSize + chunkSize))) {
    const values = [];

    for await (const value of processChunk(chunk)) {
      if (typeof value === 'number') {
        result = reducer(result, value);
        values.push(value);
      }
    }

    console.log(`Processed chunk: ${values}`);
  }

  return result;
}

// Usage
(async () => {
  const numbers = Array.from({ length: 100 }, (_, i) => i + 1); // Simulated IDs
  try {
    const sum = await asyncReduce(numbers, (acc, num) => acc + num, 0);
    console.log(`Total Sum: ${sum}`);
  } catch (error) {
    console.error('Error during reduction:', error.message);
  }
})();
