}

// NotificationSystem.java
class NotificationSystem {
    private final ConcurrentHashMap<String, Integer> rateLimiter = new ConcurrentHashMap<>();

    public synchronized boolean canSendMessage(String userId) {
        int count = rateLimiter.getOrDefault(userId, 0);
        if (count < 5) { // Example limit of 5 messages per minute
            rateLimiter.put(userId, count + 1);
            return true;
        }
        return false;
    }

    public void clearRateLimit(String userId) {
        rateLimiter.remove(userId);
    }
}

