from cassandra.cluster import Cluster
from datetime import datetime

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def calculate_checksum(data):
    return hashlib.md5(json.dumps(data).encode('utf-8')).hexdigest()

def validate_data(sensor_data):
    # Implement logical checks for sensor data consistency
    if 'temperature' in sensor_data and (sensor_data['temperature'] < -50 or sensor_data['temperature'] > 150):
        logging.warning("Temperature anomaly detected: %s", sensor_data)
        return False
    # Add more validation rules as needed
    return True

def process_log_file(file_path, session):
    try:
        with open(file_path, 'r') as file:
            for line in file:
                data = json.loads(line.strip())
                checksum = calculate_checksum(data)

                if validate_data(data) and checksum == data.get('checksum', ''):
                    # Insert into Cassandra
                    query = "INSERT INTO sensor_data (device_id, timestamp, data, checksum) VALUES (%s, %s, %s, %s)"
                    session.execute(query, (data['device_id'], datetime.now(), json.dumps(data), checksum))
                else:
                    logging.error("Invalid data detected: %s", data)
    except Exception as e:
        logging.error("Error processing file %s: %s", file_path, str(e))

def monitor_resources():
    while True:
        cpu_usage = psutil.cpu_percent(interval=1)
        memory_usage = psutil.virtual_memory().percent
        io_counters = psutil.disk_io_counters()

        if cpu_usage > 80 or memory_usage > 80:
            logging.warning("High resource usage detected: CPU %s%%, Memory %s%%", cpu_usage, memory_usage)

        # Add any additional monitoring and alerting logic as needed

def main(log_files_directory):
    cluster = Cluster(['127.0.0.1'])
    session = cluster.connect('iot_keyspace')

    with ThreadPoolExecutor(max_workers=4) as executor:
        for file_name in os.listdir(log_files_directory):
            file_path = os.path.join(log_files_directory, file_name)
            if os.path.isfile(file_path):
                executor.submit(process_log_file, file_path, session)

    # Start resource monitoring in a separate thread
    monitor_thread = threading.Thread(target=monitor_resources, daemon=True)
    monitor_thread.start()

if __name__ == '__main__':
    main('/path/to/log/files')
