```javascript
// JavaScript function to fetch weather data and update UI

async function fetchWeatherData(cities, updateUIFunction) {
    const apiKey = 'YOUR_API_KEY';
    const baseUrl = 'https://api.weather.com/v1';

    async function fetchData(city, retries = 3, delay = 1000) {
        try {
            const response = await fetch(`${baseUrl}/current_conditions?location=${city}&apiKey=${apiKey}`);
            if (!response.ok && retries > 0) {
                const backoffDelay = delay * Math.pow(2, 3 - retries);
                await new Promise(res => setTimeout(res, backoffDelay));
                return fetchData(city, retries - 1, delay * 2);
            }
            const data = await response.json();
            logApiCall('success', city, response.headers.get('date'), response.status);
            updateUIFunction(city, data);
        } catch (error) {
            if (retries > 0) {
                const backoffDelay = delay * Math.pow(2, 3 - retries);
                await new Promise(res => setTimeout(res, backoffDelay));
                return fetchData(city, retries - 1, delay * 2);
            }
            logApiCall('error', city, new Date().toISOString(), 'Failed');
        }
    }

    const promises = cities.map(city => fetchData(city));
    await Promise.all(promises);

    function logApiCall(status, city, timestamp, statusCode) {
        console.log(`API Call - Status: ${status}, City: ${city}, Timestamp: ${timestamp}, Status Code: ${statusCode}`);
    }
}

// Example usage:
fetchWeatherData(['New York', 'Los Angeles'], (city, data) => {
    // Update UI with weather data
    console.log(`Weather for ${city}:`, data);
});
