const fs = require('fs').promises;
const path = require('path');
const cloudStorageClient = require('./cloudStorageClient'); // hypothetical cloud storage client

async function readDirectoryWithFilters(dirPath, options) {
    const { extensionFilter = '', timeout = 5000 } = options;

    async function readFileContents(filePath) {
        return new Promise((resolve, reject) => {
            fs.readFile(filePath)
                .then(content => resolve(content.toString()))
                .catch(error => {
                    console.warn(`Warning: Could not read file ${filePath}.`, error);
                    resolve(null); // Continue with null content
                });

            setTimeout(() => {
                if (!filePathReadDone) {
                    reject(new Error('File reading operation timed out.'));
                }
            }, timeout);

            let filePathReadDone = false;
            filePathReadDone = true; 
        });
    }

    async function processFiles(files, dirPath) {
        const tasks = files.map(async (file) => {
            if (!path.basename(file).startsWith('.') && file.slice(-1) !== path.sep && (extensionFilter === '' || file.endsWith(extensionFilter))) {
                const stats = await fs.stat(file);
                if (stats.size <= 1024 * 1024) { // Check if size is within limit
                    const content = await readFileContents(file);

                    if (content !== null) {
                        await cloudStorageClient.uploadFile(content, path.basename(file));
                    }
                }
            }
        });

        return Promise.allSettled(tasks);
    }

    async function exploreDirectory(directoryPath) {
        try {
            const entries = await fs.readdir(directoryPath, { withFileTypes: true });
            const filesAndDirs = [];

            for (const entry of entries) {
                if (entry.isDirectory()) {
                    filesAndDirs.push(...await exploreDirectory(path.join(directoryPath, entry.name)));
                } else if (!entry.name.startsWith('.')) {
                    filesAndDirs.push(path.join(directoryPath, entry.name));
                }
            }

            return filesAndDirs;
        } catch (error) {
            console.error(`Error reading directory ${directoryPath}:`, error);
            return [];
        }
    }

    const allFiles = await exploreDirectory(dirPath);
    await processFiles(allFiles, dirPath);

    return `Processed ${allFiles.length} entries in directory: ${dirPath}`;
}

module.exports = { readDirectoryWithFilters };
