function copyBytesFromStreams(buffers, byteCount) {
    const MAX_MEMORY = Math.min(100 * 1024 * 1024, (byteCount < 1 * 1024 * 1024 ? byteCount : 1 * 1024 * 1024)); // Limit to 100MB or lower for small requests
    let copiedBytes = Buffer.allocUnsafe(MAX_MEMORY);
    let totalCopied = 0;

    buffers.forEach(buffer => {
        let offset = 0;

        while (offset < buffer.length && totalCopied < byteCount) {
            try {
                const bytesToCopy = Math.min(buffer.length - offset, byteCount - totalCopied, MAX_MEMORY - totalCopied);
                copiedBytes.copy(copiedBytes.slice(totalCopied), 0, buffer, offset, offset + bytesToCopy);

                totalCopied += bytesToCopy;
                offset += bytesToCopy;
            } catch (e) {
                console.error('Encoding error encountered:', e.message);
                break; // Log the error and continue with other buffers
            }
        }

        if (totalCopied >= byteCount) return; // Exit early if we've copied enough data
    });

    const finalBuffer = Buffer.alloc(totalCopied);
    copiedBytes.copy(finalBuffer, 0, 0, totalCopied);

    return finalBuffer;
}

// Example usage:
const buffers = [Buffer.from('Hello'), Buffer.from('World! This is a test of large buffers.'), Buffer.from('Another buffer.')];
const byteCountToCopy = 50; // Number of bytes to copy
const result = copyBytesFromStreams(buffers, byteCountToCopy);
console.log(result.toString());
