std::string calculateSHA256(const std::string& filePath, size_t chunkSize = 1024 * 1024) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        log("Error: File cannot be opened.");
        throw std::runtime_error("File not accessible");
    }

    char buffer[chunkSize];
    while (file.read(buffer, chunkSize) || file.gcount()) {
        SHA256_Update(&sha256, buffer, file.gcount());
    }
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &sha256);

    std::ostringstream hexStream;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        hexStream << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }

    return hexStream.str();
}

std::string downloadFile(const std::string& url, const std::string& outputPath, size_t chunkSize = 1024 * 1024) {
    CURL* curl;
    FILE* fp;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        fp = fopen(outputPath.c_str(), "wb");
        if (!fp) return "";

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, fwrite);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

        res = curl_easy_perform(curl);
        fclose(fp);

        if (res != CURLE_OK) {
            log("CURL failed: " + std::string(curl_easy_strerror(res)));
            return "";
        }
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return outputPath;
}

std::string uploadFileToCloud(const std::string& filePath, const std::string& bucketName,
                              const std::map<std::string, std::string>& metadata) {
