    bool success = true; // Replace with actual API call logic
    if (!success) {
        throw std::runtime_error("API Error occurred during file upload");
    }

    return calculateSHA256(filePath); // Return hash after successful upload
}

std::string handleRemoteURL(const std::string& url, const std::string& bucketName,
                            const std::map<std::string, std::string>& metadata) {
    static std::mutex downloadMutex;
    std::lock_guard<std::mutex> lock(downloadMutex);

    std::filesystem::path tempDir = std::filesystem::temp_directory_path();
    std::string tempFilePath = (tempDir / "downloaded_file").string();

    auto result = std::async(std::launch::async, downloadFile, url, tempFilePath);
    try {
        if (!result.get().empty()) {
            return uploadFileToCloud(result.get(), bucketName, metadata);
        } else {
            throw std::runtime_error("Download failed");
        }
    } catch (const std::exception& e) {
        log(e.what());
    }

    return "";
}

std::string uploadAndMonitorFile(const std::string& filePathOrURL, const std::string& bucketName,
                                 const std::map<std::string, std::string>& metadata = {}) {

    try {
        if (filePathOrURL.rfind("http://", 0) == 0 || filePathOrURL.rfind("https://", 0) == 0) {
            return handleRemoteURL(filePathOrURL, bucketName, metadata);
        } else if (std::filesystem::exists(filePathOrURL)) {
            return uploadFileToCloud(filePathOrURL, bucketName, metadata);
        } else {
            log("Error: File not found at path " + filePathOrURL);
            return "";
        }
    } catch (const std::exception& e) {
        log(e.what());
        return "";
    }

    return ""; // In case of unexpected flow
}

