typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    pthread_mutex_t lock;
} PopulationResult;

int validateCRCFLAG(unsigned char crcFlag) {
    return (crcFlag == 0 || crcFlag == 1);
}

PopulationResult* populateNFAPICRCIndicationPDUList(size_t n, DBConfig dbConfigs, int retryThreshold, int enableLogging);

void logError(const char *message) {
    if (enableLogging) {
        fprintf(stderr, "ERROR: %s\n", message);
    }
}

PopulationResult* populateNFAPICRCIndicationPDUList(size_t n, DBConfig dbConfigs, int retryThreshold, int enableLogging) {
    if (n == 0 || n > MAX_ELEMENTS) {
        logError("Invalid number of elements specified.");
        return NULL;
    }

    PopulationResult *result = malloc(sizeof(PopulationResult));
    if (!result) {
        logError("Memory allocation failed for result structure.");
        return NULL;
    }

    pthread_mutex_init(&result->lock, NULL);
    result->list = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result->list) {
        free(result);
        logError("Memory allocation failed for NFAPI list.");
        return NULL;
    }
    result->count = 0;

    // Dummy database fetching logic
    int fetchSuccess = 1; // Replace with actual DB connection and data retrieval logic

    for (size_t i = 0; i < n && fetchSuccess; ++i) {
        pthread_mutex_lock(&result->lock);

        if (!fetchSuccess) {
            logError("Failed to fetch data from database.");
            break;
        }

        // Simulate fetching RX_UE_INFORMATION_TAG and RNTI
        int rxTag = rand() % 1000; // Replace with actual fetched value
        int rnti = rand() % 1000;  // Replace with actual fetched value

        if (rxTag <= 0 || rnti <= 0) {
            logError("Invalid RX_UE_INFORMATION_TAG or RNTI values received.");
            pthread_mutex_unlock(&result->lock);
            continue;
        }

        unsigned char crcFlag = rand() % 2; // Simulate random CRCFLAG

        if (!validateCRCFLAG(crcFlag)) {
            logError("Invalid CRCFLAG value, must be 0 or 1.");
            pthread_mutex_unlock(&result->lock);
            continue;
        }

        result->list[result->count].RX_UE_INFORMATION_TAG = rxTag;
        result->list[result->count].RNTI = rnti;
        result->list[result->count].CRCFLAG = crcFlag;

        ++result->count;
        pthread_mutex_unlock(&result->lock);
    }

    // Compress list before returning (dummy implementation)
    // Implement actual compression logic as needed

    return result;
}

void cleanup(PopulationResult *result) {
    if (result) {
        free(result->list);
        pthread_mutex_destroy(&result->lock);
        free(result);
    }
}

int main(int argc, char **argv) {
    size_t numElements = 100; // Example value
    DBConfig dbConfigs = { .connectionString1 = "db1_conn", .connectionString2 = "db2_conn" };
    int retryThreshold = 3;
    int enableLogging = 1;

    if (argc > 1) {
        numElements = strtoul(argv[1], NULL, 10);
    }
