    if (!valid || !verify_rsa_signature(&jwt_parsed, rsa_key)) {
        log_attempt("Invalid JWT signature");
        return 0;
    }

    // Additional claims validation can be added here

    return 1;
}

// Rate limiting check
int check_rate_limit() {
    pthread_mutex_lock(&rate_limiter.lock);
    time_t current_time = time(NULL);

    if (current_time - rate_limiter.last_attempt_time > RATE_LIMIT_INTERVAL) {
        rate_limiter.attempts = 0;
        rate_limiter.last_attempt_time = current_time;
    }

    int is_within_limit = rate_limiter.attempts < MAX_ATTEMPTS;
    pthread_mutex_unlock(&rate_limiter.lock);

    if (!is_within_limit) {
        log_attempt("Rate limit exceeded");
    }
    return is_within_limit;
}

