    @staticmethod
    def check_domain_existence(domain):
        resolver = Resolver()
        try:
            resolver.resolve(domain, 'MX')
            return True
        except NXDOMAIN:
            return False

    @staticmethod
    def validate_uniqueness(user_dao, user_id, new_email):
        existing_user = user_dao.get_user_by_email(new_email)
        if existing_user and existing_user.id != user_id:
            raise Exception("Email already in use by another account.")

def update_user_email(user_id, new_email, dao: UserDAO, email_service: EmailService):
    # Validate format
    if not EmailValidator.validate_format(new_email):
        return "Invalid email format."

    # Check domain existence
    domain = new_email.split('@')[1]
    if not EmailValidator.check_domain_existence(domain):
        return "Domain does not exist."

    # Check uniqueness
    try:
        EmailValidator.validate_uniqueness(dao, user_id, new_email)
    except Exception as e:
        return str(e)

    # Update email in the database
    try:
        dao.update_user_email(user_id, new_email)
    except Exception as e:
        return f"Database error: {str(e)}"

    # Send confirmation email
    try:
        subject = "Email Address Update Confirmation"
        message = f"Your email address has been updated to {new_email}."
        email_service.send_confirmation_email(new_email, subject, message)
    except Exception as e:
        return str(e)

    return "Email successfully updated and confirmed."

