import os
import time
import threading
import requests
from cachetools import TTLCache, cached
from functools import lru_cache

# Configure cache: maxsize 1000 entries, 1800 seconds (30 minutes) expiration time
cache = TTLCache(maxsize=1000, ttl=1800)

# Lock for thread safety
lock = threading.Lock()

class WeatherAPIError(Exception):
    pass

def get_api_credentials():
    api_name = os.getenv('WEATHER_API')
    if api_name == 'OpenWeatherMap':
        return {
            'api_key': os.getenv('OPENWEATHERMAP_API_KEY'),
            'base_url': 'https://api.openweathermap.org/data/2.5/'
        }
    elif api_name == 'WeatherAPI':
        return {
            'api_key': os.getenv('WEATHERAPI_API_KEY'),
            'base_url': 'http://api.weatherapi.com/v1/'
        }
    elif api_name == 'AccuWeather':
        return {
            'api_key': os.getenv('ACCUWEATHER_API_KEY'),
            'base_url': 'https://dataservice.accuweather.com/'
        }
    else:
        raise WeatherAPIError("Unsupported API")

def log(message, level='INFO'):
    # Custom logging logic
    print(f"[{level}] {time.strftime('%Y-%m-%d %H:%M:%S')} - {message}")

@cached(cache)
def fetch_weather(api_name, location):
    credentials = get_api_credentials()
    url = f"{credentials['base_url']}weather?query={location}"

    if api_name == 'OpenWeatherMap':
        params = {'appid': credentials['api_key']}
    elif api_name == 'WeatherAPI':
        params = {'key': credentials['api_key']}
    elif api_name == 'AccuWeather':
        url += f"&apikey={credentials['api_key']}"

    retries = 3
    delay = 1

    for attempt in range(retries):
        try:
            response = requests.get(url, params=params)
            if response.status_code == 200:
                return response.json()
            elif response.status_code == 429:  # Rate limit exceeded
                log(f"Rate limit hit. Sleeping for {delay} seconds.", 'WARNING')
                time.sleep(delay)
                delay *= 2  # Exponential backoff
            else:
                raise WeatherAPIError(response.text)
        except requests.exceptions.RequestException as e:
            if attempt < retries - 1:
                log(f"Network error: {e}. Retrying...", 'ERROR')
                time.sleep(delay)
                delay *= 2
            else:
                raise

def get_weather_data(locations):
    with lock:
        api_name = os.getenv('WEATHER_API')
        results = {}
        for location in locations:
            try:
                data = fetch_weather(api_name, location)
                results[location] = data
                log(f"Fetched weather data for {location}", 'INFO')
            except WeatherAPIError as e:
                log(f"Failed to fetch data for {location}: {e}", 'ERROR')
        return results

def main():
    locations = ['New York', 'London', 'Tokyo']
    weather_data = get_weather_data(locations)
    print(weather_data)

if __name__ == "__main__":
    main()
```

