using Microsoft.AspNetCore.Http;
using Newtonsoft.Json;
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class RealTimeClimateMiddleware
{
    private readonly RequestDelegate _next;
    private static readonly HttpClient httpClient = new HttpClient();
    private static readonly ConcurrentDictionary<string, string> cache = new ConcurrentDictionary<string, string>();
    private const int CacheDurationInMinutes = 10;

    public RealTimeClimateMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            if (context.Request.Path.StartsWithSegments("/climate-update"))
            {
                string climateData = await FetchRealTimeClimateData();
                context.Response.StatusCode = StatusCodes.Status200OK;
                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(climateData);
            }
            else
            {
                await _next(context);
            }
        }
        catch (Exception ex)
        {
            // Logging error for debugging and monitoring purposes
            LogError(ex);

            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            await context.Response.WriteAsync("An unexpected error occurred.");
        }
    }

    private async Task<string> FetchRealTimeClimateData()
    {
        string cacheKey = "climate_data";
        if (cache.TryGetValue(cacheKey, out var cachedResponse))
        {
            return cachedResponse;
        }

        var tasks = new[]
        {
            GetFromApi("https://api.climateAPI.com/data"),
            GetFromApi("https://api.meteostat.net/data"),
            GetFromApi("https://api.weatherDB.com/data")
        };

        var responses = await Task.WhenAll(tasks);
        string aggregatedData = AggregateResponses(responses);

        cache[cacheKey] = aggregatedData;
        StartCacheCleanupTimer(cacheKey);

        return aggregatedData;
    }

    private async Task<string> GetFromApi(string url)
    {
        try
        {
            HttpResponseMessage response = await httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            string data = await response.Content.ReadAsStringAsync();
            ApplyRateLimitingAndRetryPolicy(url); // Placeholder for handling rate limits and retries

            return data;
        }
        catch (HttpRequestException ex)
        {
            LogError(ex);
            return "{}";
        }
    }

    private string AggregateResponses(string[] responses)
    {
        var combinedData = new { Data = new[] { } };

        foreach (var response in responses)
        {
            dynamic jsonData = JsonConvert.DeserializeObject(response);
            Array.Resize(ref combinedData.Data, combinedData.Data.Length + 1);
            combinedData.Data[combinedData.Data.Length - 1] = jsonData;
        }

        return JsonConvert.SerializeObject(combinedData);
    }

    private void StartCacheCleanupTimer(string key)
    {
        Task.Delay(TimeSpan.FromMinutes(CacheDurationInMinutes)).ContinueWith(_ => cache.TryRemove(key, out _));
    }

    private void ApplyRateLimitingAndRetryPolicy(string url)
    {
        // Placeholder for implementing rate limiting and retry logic
    }

    private void LogError(Exception ex)
    {
        // Implement logging mechanism here
        Console.WriteLine(ex.ToString());
    }
}

