        }

        SSL_CTX_set_options(sslContext, SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3);
        SSL_CTX_set_cipher_list(sslContext, "AESGCM+CHACHA20POLY1305");

        // Load server certificate and private key
    }

