        return true;
    }

    void sendAlert(const uint8_t* data, size_t length) {
        try {
            asio::ssl::stream<asio::ip::tcp::socket> sslSocket(ioContext, sslContext);

            // Connect and communicate with the monitoring system via RESTful API using TLS
            logger->info("Sending alert...");

        } catch (const std::exception& e) {
            logger->error("Exception in sendAlert: {}", e.what());
        }
    }

    asio::io_context ioContext;

public:
