        switch (level) {
        case 0: logger->set_level(spdlog::level::trace); break;
        case 1: logger->set_level(spdlog::level::debug); break;
        case 2: logger->set_level(spdlog::level::info); break;
        case 3: logger->set_level(spdlog::level::warn); break;
        case 4: logger->set_level(spdlog::level::err); break;
        default: logger->set_level(spdlog::level::critical);
        }
    }

    std::vector<std::unique_ptr<uint8_t[]>> copySensorData(const uint8_t* source, size_t length) {
        std::vector<std::unique_ptr<uint8_t[]>> result;
        for (size_t i = 0; i < length; i += CHUNK_SIZE) {
            size_t chunkLength = std::min(CHUNK_SIZE, length - i);
            auto dataChunk = std::make_unique<uint8_t[]>(chunkLength);
            memcpy(dataChunk.get(), source + i, chunkLength);
            result.push_back(std::move(dataChunk));
        }
        return result;
    }

private:
    static constexpr size_t CHUNK_SIZE = 1024; // Example chunk size
};

