```csharp
using System;
using System.Collections.Generic;
using System.Threading;

public class CustomRandomGenerator
{
    private readonly object lockObj = new object();
    private int seed;
    private Random random;
    private bool isFloatRange;
    private double minValue;
    private double maxValue;

    public CustomRandomGenerator(int seed)
    {
        SetSeed(seed);
        random = new Random(seed);
        Log("CustomRandomGenerator initialized with seed: " + seed);
    }

    public void SetRange(double min, double max, bool isFloat)
    {
        lock (lockObj)
        {
            if (min >= max) throw new ArgumentException("Min value must be less than Max value.");
            isFloatRange = isFloat;
            minValue = min;
            maxValue = max;
            Log($"Range set to: {min} - {max} [Is Float Range: {isFloat}]");
        }
    }

    public void SetSeed(int seed)
    {
        lock (lockObj)
        {
            if (seed < 0) throw new ArgumentException("Seed must be non-negative.");
            this.seed = seed;
            random = new Random(seed);
            Log($"Seed set to: {seed}");
        }
    }

    public int GetSeed()
    {
        lock (lockObj)
        {
            return seed;
        }
    }

    public double Generate(double inclusiveMin, double exclusiveMax)
    {
        lock (lockObj)
        {
            if (inclusiveMin >= exclusiveMax) throw new ArgumentException("Inclusive min must be less than exclusive max.");

            var value = random.NextDouble() * (exclusiveMax - inclusiveMin) + inclusiveMin;
            Log($"Generated: {value}");
            return isFloatRange ? value : Math.Round(value);
        }
    }

    public double Generate(double inclusiveMin, double inclusiveMax)
    {
        lock (lockObj)
        {
            if (inclusiveMin > inclusiveMax) throw new ArgumentException("Inclusive min must be less than or equal to inclusive max.");

            var range = inclusiveMax - inclusiveMin;
            var value = random.NextDouble() * range + inclusiveMin;
            Log($"Generated: {value}");
            return isFloatRange ? value : Math.Round(value);
        }
    }

    public List<double> GenerateSequence(int count, bool inclusiveUpper)
    {
        lock (lockObj)
        {
            var sequence = new List<double>();
            for (int i = 0; i < count; i++)
            {
                sequence.Add(inclusiveUpper ? Generate(minValue, maxValue) : Generate(minValue, maxValue + 1e-9));
            }
            Log($"Generated Sequence of {count} values.");
            return sequence;
        }
    }

    public double GenerateNormal(double mean, double stdDev)
    {
        lock (lockObj)
        {
            if (stdDev <= 0) throw new ArgumentException("Standard deviation must be positive.");

            var u1 = (double)random.NextDouble();
            var u2 = (double)random.NextDouble();
            var z0 = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Cos(2.0 * Math.PI * u2);

            var value = mean + stdDev * z0;
            Log($"Generated Normal: {value} [Mean: {mean}, Std Dev: {stdDev}]");
            return isFloatRange ? value : Math.Round(value);
        }
    }

    public void Reset()
    {
        lock (lockObj)
        {
            random = new Random(seed);
            Log("Random generator reset.");
        }
    }

    public override string ToString()
    {
        lock (lockObj)
        {
            return $"CustomRandomGenerator [Seed: {seed}, Range: {minValue} - {maxValue} [{isFloatRange}], State: Active]";
        }
    }

    private void Log(string message)
    {
        // Simple logging mechanism
        Console.WriteLine($"[LOG] {DateTime.Now}: {message}");
    }
}
