```php
<?php

function updateClinicStatus($clinicId) {
    // Database connection configuration
    $dbConfig = [
        'host' => 'your_database_host',
        'dbname' => 'your_database_name',
        'username' => 'your_username',
        'password' => 'your_password'
    ];

    $maxRetries = 3;
    $retryDelay = 1; // in seconds

    for ($attempt = 0; $attempt < $maxRetries; $attempt++) {
        try {
            // Establish database connection
            $pdo = new PDO(
                "mysql:host={$dbConfig['host']};dbname={$dbConfig['dbname']}",
                $dbConfig['username'],
                $dbConfig['password']
            );
            $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

            // Begin transaction for atomic operation
            $pdo->beginTransaction();

            // Validate clinic ID
            if (!is_numeric($clinicId) || $clinicId <= 0) {
                throw new InvalidArgumentException("Invalid clinic ID provided.");
            }

            // Fetch current data of the clinic
            $stmt = $pdo->prepare("SELECT status, last_modified_ip FROM clinics WHERE id = :id FOR UPDATE");
            $stmt->execute([':id' => $clinicId]);

            if ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
                $currentStatus = $row['status'];
                $lastModifiedIp = $row['last_modified_ip'];

                // Simulate some check or condition to update the status
                $newStatus = 'Updated'; // Example new status
                $ipAddress = $_SERVER['REMOTE_ADDR']; // Get current IP address

                if (!filter_var($ipAddress, FILTER_VALIDATE_IP)) {
                    throw new InvalidArgumentException("Invalid IP Address.");
                }

                // Prepare and execute the update statement
                $updateStmt = $pdo->prepare(
                    "UPDATE clinics 
                     SET status = :status,
                         last_modified_ip = :last_modified_ip,
                         last_modified_timestamp = NOW()
                     WHERE id = :id AND status = :current_status"
                );

                $updateStmt->execute([
                    ':status' => $newStatus,
                    ':last_modified_ip' => $ipAddress,
                    ':id' => $clinicId,
                    ':current_status' => $currentStatus
                ]);

                // Commit transaction if update was successful
                if ($updateStmt->rowCount() > 0) {
                    $pdo->commit();
                    return true; // Success
                } else {
                    $pdo->rollBack(); // No rows updated, rollback
                    throw new Exception("No updates made to clinic status.");
                }
            } else {
                $pdo->rollBack(); // Clinic not found, rollback
                throw new InvalidArgumentException("Clinic with the specified ID does not exist.");
            }
        } catch (Exception $e) {
            // Handle retries in case of connection issues or timeouts
            if ($attempt < $maxRetries - 1 && ($e instanceof PDOException || $e->getCode() === 'HY000')) {
                error_log("Database update attempt {$attempt + 1} failed: " . $e->getMessage());
                sleep($retryDelay);
                continue;
            }

            // Log and rethrow any other exceptions
            error_log("Failed to update clinic status for ID {$clinicId}: " . $e->getMessage());
            throw $e; // Re-throw the exception
        } finally {
            if (isset($pdo) && !$pdo->inTransaction()) {
                $pdo = null;
            }
        }
    }

    return false; // If all attempts fail, return false
}

