import asyncio
import aiohttp
import logging

logging.basicConfig(level=logging.INFO)

async def fetch(session, url, timeout):
    try:
        async with session.get(url, timeout=timeout) as response:
            if response.status == 200:
                return await response.json()
            else:
                logging.error(f"Failed to fetch {url}: Status code {response.status}")
    except Exception as e:
        logging.error(f"Exception occurred while fetching {url}: {str(e)}")
    return None

async def process_data(api_urls, data_processor=None, timeout=10, max_concurrent_requests=5):
    async with aiohttp.ClientSession() as session:
        semaphore = asyncio.Semaphore(max_concurrent_requests)

        async def fetch_with_semaphore(url):
            async with semaphore:
                return await fetch(session, url, timeout)

        tasks = [fetch_with_semaphore(url) for url in api_urls]
        responses = await asyncio.gather(*tasks, return_exceptions=True)

        processed_data = []
        for response in responses:
            if isinstance(response, Exception):
                logging.error(f"Error occurred: {response}")
                continue

            if not response or 'expected_key' not in response:
                logging.warning("Incomplete data received")
                continue

            try:
                if data_processor:
                    processed_response = data_processor(response)
                else:
                    processed_response = response  # Default processing
                processed_data.append(processed_response)
            except Exception as e:
                logging.error(f"Data processor failed: {str(e)}")

        return processed_data

def fetchAndProcessData(api_urls, data_processor=None, timeout=10, max_concurrent_requests=5):
    return asyncio.run(process_data(api_urls, data_processor, timeout, max_concurrent_requests))

