use std::fs;
use llvm_sys::{core as llvm_core, prelude::*};
use lexer_and_parser; // Assume this is a module for lexing and parsing

pub fn generate_llvm_ir(file_path: &str, grammar_definition: &str) -> Result<String, Box<dyn std::error::Error>> {
    let file_contents = fs::read_to_string(file_path)?;

    // Example lexer and parser usage
    let tokens = lexer_and_parser::lex(&file_contents)?;
    let ast = lexer_and_parser::parse(tokens, grammar_definition)?;

    // Assuming `convert_ast_to_llvm_ir` transforms the AST to LLVM IR code
    let llvm_module = convert_ast_to_llvm_ir(&ast)?;

    let mut context = Context::new();
    unsafe {
        llvm_core::LLVMDisposeModule(llvm_module.into());
    }

    let ir_string = llvm_module_to_string(&llvm_module)?;
    Ok(ir_string)
}

fn convert_ast_to_llvm_ir(ast: &lexer_and_parser::Ast) -> Result<llvm_sys::core::LLVMModuleRef, Box<dyn std::error::Error>> {
    // Convert the AST to LLVM IR using the LLVM bindings
    unimplemented!()
}

fn llvm_module_to_string(module: &llvm_sys::core::LLVMModuleRef) -> Result<String, Box<dyn std::error::Error>> {
    unsafe {
        let mut err = std::ptr::null_mut();
        let raw_ir = llvm_core::LLVMPrintModuleToString(module, &mut err);

        if !err.is_null() {
            return Err(Box::new(std::ffi::CStr::from_ptr(llvm_core::LLVMGetLastErrorMsg(err)).to_str()?.into()));
        }

        std::str::from_utf8(std::slice::from_raw_parts(raw_ir as *const u8, llvm_core::LLVMPrintModuleToStringLen(module) as usize))
            .map(|s| s.to_string())
            .map_err(Into::into)
    }
}

