    private static class TokenBucketRateLimiter {
        private final int capacity;
        private final long refillPeriodMillis;
        private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

        public TokenBucketRateLimtter(int capacity, long refillPeriodMillis) {
            this.capacity = capacity;
            this.refillPeriodMillis = refillPeriodMillis;
        }

        public boolean allowRequest(String ip) {
            return buckets.computeIfAbsent(ip, k -> new Bucket(capacity)).consume();
        }

        private static class Bucket {
            private int tokens;
            private long lastRefillTimestamp;

            public Bucket(int capacity) {
                this.tokens = capacity;
                this.lastRefillTimestamp = System.currentTimeMillis();
            }

            public synchronized boolean consume() {
                refillTokens();
                if (tokens > 0) {
                    tokens--;
                    return true;
                }
                return false;
            }

            private void refillTokens() {
                long now = System.currentTimeMillis();
                if (now - lastRefillTimestamp >= refillPeriodMillis) {
                    int toAdd = (int) ((now - lastRefillTimestamp) / refillPeriodMillis);
                    tokens = Math.min(capacity, tokens + toAdd);
                    lastRefillTimestamp = now;
                }
            }
        }
    }

