This C code provides a basic framework for managing distributed database connections and handling records with thread safety. It includes mechanisms for caching, error logging, and both synchronous and asynchronous data retrieval. The function is designed to be scalable and adaptable to additional fields if needed.

```python
import json
import logging
import requests
from concurrent.futures import ThreadPoolExecutor
from contextlib import contextmanager
from psycopg2 import connect, sql
from psycopg2.extras import execute_values
import time
import threading

# Setup basic logging
logging.basicConfig(level=logging.INFO)

class SensorDataManager:
    def __init__(self, db_config):
        self.db_config = db_config
        self.lock = threading.Lock()

    @contextmanager
    def get_db_connection(self):
        conn = connect(**self.db_config)
        try:
            yield conn
        finally:
            conn.close()

    def collect_data(self, api_endpoints):
        collected_data = []
        with ThreadPoolExecutor(max_workers=len(api_endpoints)) as executor:
            future_to_url = {executor.submit(self.fetch_data, url): url for url in api_endpoints}
            for future in concurrent.futures.as_completed(future_to_url):
                try:
                    data = future.result()
                    if data:
                        collected_data.append(data)
                except Exception as e:
                    logging.error(f"Error collecting data: {e}")
        return collected_data

    def fetch_data(self, url):
        retries = 3
        delay = 1
        for attempt in range(retries):
            try:
                response = requests.get(url)
                response.raise_for_status()
                return self.parse_response(response)
            except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
                logging.warning(f"Attempt {attempt + 1} failed: {e}")
                time.sleep(delay)
                delay *= 2
        return None

    def parse_response(self, response):
        content_type = response.headers.get('Content-Type', '')
        if 'application/json' in content_type:
            return response.json()
        elif 'application/octet-stream' in content_type:
            return response.content
        else:
            logging.error(f"Unsupported content type: {content_type}")
            return None

    def validate_data(self, data, schema):
        try:
            jsonschema.validate(instance=data, schema=schema)
            return True, data
        except jsonschema.exceptions.ValidationError as e:
            logging.error(f"Validation error: {e.message}")
            return False, e.message

    def store_data(self, validated_data):
        with self.get_db_connection() as conn:
            with conn.cursor() as cur:
                # Assume we have a table named 'sensor_data' with columns for JSON data and binary data
                insert_query = sql.SQL("INSERT INTO sensor_data (json_data, binary_data) VALUES %s")
                records_to_insert = [(data['json'], data.get('binary', None)) for data in validated_data]
                execute_values(cur, insert_query, records_to_insert)
            conn.commit()

    def process_data(self, api_endpoints, json_schema):
        raw_data = self.collect_data(api_endpoints)
        valid_data = []

        for data in raw_data:
            if isinstance(data, dict):  # JSON format
                is_valid, result = self.validate_data(data, json_schema)
                if is_valid:
                    valid_data.append({'json': json.dumps(result)})
            elif isinstance(data, bytes):  # Binary format
                # Handle binary data validation separately or as needed
                valid_data.append({'binary': data})

        self.store_data(valid_data)

# Example usage
if __name__ == "__main__":
    db_config = {
        'dbname': 'iot_db',
        'user': 'db_user',
        'password': 'db_pass',
        'host': 'localhost'
    }

    api_endpoints = [
        "https://api.sensor1.com/data",
        "https://api.sensor2.com/data"
    ]

    json_schema = {
        # Example JSON schema
        "type": "object",
        "properties": {
            "sensor_id": {"type": "string"},
            "value": {"type": "number"}
        },
        "required": ["sensor_id", "value"]
    }

    manager = SensorDataManager(db_config)
    manager.process_data(api_endpoints, json_schema)
