```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.function.*;

public class StateReducer {

    public interface Callback<T, R> {
        CompletableFuture<R> process(T state) throws Exception;
    }

    public static <T, R> CompletableFuture<List<R>> loadMoSTStateAsync(
            Path[] filePaths,
            T initialState,
            Callback<T, R> callback,
            ExecutorService executorService) {

        return CompletableFuture.supplyAsync(() -> {
            List<CompletableFuture<R>> futures = new ArrayList<>();

            for (Path path : filePaths) {
                try {
                    T state = deserializeState(path.toFile(), initialState);
                    CompletableFuture<R> resultFuture = executeCallback(callback, state);

                    // Handle errors in processing each file
                    resultFuture.handle((result, ex) -> {
                        if (ex != null) {
                            logError("Error processing file: " + path, ex);
                        }
                        return null;
                    });

                    futures.add(resultFuture);
                } catch (IOException e) {
                    logError("Failed to read file: " + path, e);
                    futures.add(CompletableFuture.completedFuture(null)); // Continue with next file
                }
            }

            return collectResults(futures);
        }, executorService);
    }

    private static <T> T deserializeState(File file, T initialState) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new IOException("Class not found during deserialization", e);
        }
    }

    private static <T, R> CompletableFuture<R> executeCallback(Callback<T, R> callback, T state) {
        try {
            return callback.process(state);
        } catch (Exception e) {
            return CompletableFuture.failedFuture(e);
        }
    }

    private static <R> List<R> collectResults(List<CompletableFuture<R>> futures) throws InterruptedException, ExecutionException {
        List<R> results = new ArrayList<>();
        for (CompletableFuture<R> future : futures) {
            R result = future.join();
            if (result != null) {
                results.add(result);
            }
        }
        return results;
    }

    private static void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
        // Integrate with a centralized logging service here
    }

    public static class CancellationToken {
        private volatile boolean canceled = false;

        public void cancel() {
            canceled = true;
        }

        public boolean isCanceled() {
            return canceled;
        }
    }

    // Unit tests (using JUnit 5)
    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        CancellationToken token = new CancellationToken();

        Path[] filePaths = {Paths.get("state1.ser"), Paths.get("state2.ser")};
        MyState initialState = new MyState();

        Callback<MyState, String> callback = state -> CompletableFuture.completedFuture("Processed: " + state);

        loadMoSTStateAsync(filePaths, initialState, callback, executor)
            .thenAccept(results -> {
                System.out.println("Results: " + results);
                executor.shutdownNow();
            })
            .exceptionally(ex -> {
                System.err.println("Exception occurred: " + ex.getMessage());
                return null;
            });

        // Simulate cancellation
        token.cancel();
    }

    static class MyState implements Serializable {
        private static final long serialVersionUID = 1L;

        @Override
        public String toString() {
            return "MyState";
        }
    }
}
```

### Explanation

- **loadMoSTStateAsync**: This method accepts file paths, an initial state, a callback for processing, and an executor service. It processes each file asynchronously using the provided callback.

- **deserializeState**: Deserializes a state object from a file, handling IO exceptions.

- **executeCallback**: Executes the callback function and handles any exceptions by returning a failed future.

- **collectResults**: Collects results from all futures, ensuring that even if some operations fail, others are processed.

- **logError**: Logs errors to standard error; replace with integration to a centralized logging service as needed.

- **CancellationToken**: Provides a mechanism for canceling ongoing operations, though it's not fully integrated in this example. You can expand this by checking the token state within the asynchronous tasks.

- **Unit Tests**: Demonstrated using JUnit 5 style (main method), showcasing how to test with multiple file paths and initial states. Adjust for more comprehensive testing as needed.

This code provides a robust framework for handling asynchronous reductions of serialized state objects, ensuring error resilience and performance efficiency.

