    @Async
    public CompletableFuture<Map<String, Object>> getPokemonDetails(@PathVariable int id) {
        try {
            return CompletableFuture.completedFuture(fetchPokemonData(id));
        } catch (Exception e) {
            // Handle error gracefully and return meaningful message
            Map<String, String> response = new HashMap<>();
            response.put("error", "Failed to retrieve data for Pokemon ID: " + id);
            return CompletableFuture.completedFuture(response);
        }
    }

    @Cacheable(value = "pokemonData", unless = "#result == null")
    public Map<String, Object> fetchPokemonData(int id) {
