#### Password Update Function
```php
function update_password($pdo, $userId, $password) {
    if (!preg_match('/^(?=.*\d)(?=.*[A-Z])(?=.*[a-z]).{8,}$/', $password)) {
        throw new Exception("Password must contain at least one number, one uppercase and lowercase letter, and be at least 8 characters long.");
    }

    $hash = password_hash($password, PASSWORD_DEFAULT);
    $dao = new UserDAO($pdo);

    try {
        if ($dao->updatePassword($userId, $hash)) {
            error_log("Password updated successfully for user ID: {$userId}");
        } else {
            throw new Exception("Failed to update password.");
        }
    } catch (Exception $e) {
        error_log("Error updating password: " . $e->getMessage());
    }
}
```

### C Function for AES-256-GCM Initialization

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>

int initialize_aes_256_gcm(const char *password, const unsigned char *salt, size_t salt_len, unsigned char *key, unsigned char *iv) {
    EVP_KEYMGMT_CTX *ctx;
    if (EVP_PBE_keymgmt_new(&ctx, EVP_PBE_OPENSSL_KTLS1_5) != 1 ||
        EVP_PBE_set_params(ctx, EVP_sha256(), EVP_aes_256_gcm(), salt_len, salt) != 1 ||
        EVP_PBE_derive(ctx, key, sizeof(key), password, strlen(password)) != 1 ||
        RAND_bytes(iv, EVP_MAX_IV_LENGTH) != 1 ||  // Assuming using the maximum IV length supported
        EVP_PBE_free(ctx) != 1) {
        fprintf(stderr, "Failed to initialize AES-256-GCM.\n");
        return -1;
    }

    printf("AES-256-GCM initialized successfully.\n");
    return 0;
}

