    @org.junit.Test
    public void testPutAndGet() {
        DistributedCache cache = new DistributedCache();

        String key = "testKey";
        Object value = "testValue";

        cache.put(key, value);

        assert cache.get(key).equals(value) : "Get should return the same value as put.";
    }

    // Additional tests for error handling, concurrency, and synchronization

    @org.junit.Test
    public void testConcurrentAccess() {
        DistributedCache cache = new DistributedCache();

        ExecutorService executorService = Executors.newFixedThreadPool(100);

        Callable<Void> task = () -> {
            String key = "concurrentKey";
            Object value = ThreadLocalRandom.current().nextInt();

            cache.put(key, value);
            assert cache.get(key).equals(value) : "Concurrent get should return the same value as put.";
            return null;
        };

        List<Callable<Void>> tasks = new ArrayList<>();
