        mutable std::mutex lock;

        bool isValidSeed(unsigned int seed) const {
            return seed > 0;
        }

        void initializeDatabase() {
            sqlite3* db;
            if (sqlite3_open("weather_simulation.db", &db)) {
                throw std::runtime_error("Failed to open database");
            }
            // Setup the schema and initial configurations
            const char* createTableSQL = "CREATE TABLE IF NOT EXISTS seeds(seed INTEGER PRIMARY KEY, value INTEGER);";
            if (sqlite3_exec(db, createTableSQL, nullptr, nullptr, nullptr) != SQLITE_OK) {
                sqlite3_close(db);
                throw std::runtime_error("Failed to create database table");
            }
            sqlite3_close(db);
        }

        void storeSeed(unsigned int seed) {
            sqlite3* db;
            if (sqlite3_open("weather_simulation.db", &db)) {
                throw std::runtime_error("Failed to open database for storing seed");
            }
            const char* insertSQL = "INSERT INTO seeds(value) VALUES (?);";
            sqlite3_stmt* stmt;
            if (sqlite3_prepare_v2(db, insertSQL, -1, &stmt, nullptr) != SQLITE_OK) {
                sqlite3_close(db);
                throw std::runtime_error("Failed to prepare statement for storing seed");
            }
            sqlite3_bind_int(stmt, 1, seed);
            if (sqlite3_step(stmt) != SQLITE_DONE) {
                sqlite3_finalize(stmt);
                sqlite3_close(db);
                throw std::runtime_error("Failed to store seed in database");
            }
            sqlite3_finalize(stmt);
            sqlite3_close(db);
        }

        unsigned int retrieveSeed() {
            sqlite3* db;
            if (sqlite3_open("weather_simulation.db", &db)) {
                throw std::runtime_error("Failed to open database for retrieving seed");
            }
            const char* selectSQL = "SELECT value FROM seeds ORDER BY ROWID DESC LIMIT 1;";
            sqlite3_stmt* stmt;
            if (sqlite3_prepare_v2(db, selectSQL, -1, &stmt, nullptr) != SQLITE_OK) {
                sqlite3_close(db);
                throw std::runtime_error("Failed to prepare statement for retrieving seed");
            }
            unsigned int seed = 0;
            if (sqlite3_step(stmt) == SQLITE_ROW) {
                seed = sqlite3_column_int(stmt, 0);
            } else {
                sqlite3_finalize(stmt);
                sqlite3_close(db);
                throw std::runtime_error("Failed to retrieve seed from database");
            }
            sqlite3_finalize(stmt);
            sqlite3_close(db);
            return seed;
        }

        // Placeholder for API integration
