use std::env;
use std::fs::{self, File};
use std::io;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use log::{info, error};
use serde::{Deserialize, Serialize};
use toml;

const CONFIG_FILE: &str = "config.toml";

#[derive(Deserialize)]
struct Config {
    max_retries: u32,
    backoff_intervals: Vec<u64>,
}

impl Config {
    fn load() -> Self {
        let content = fs::read_to_string(CONFIG_FILE).expect("Failed to read config file");
        toml::from_str(&content).expect("Failed to parse config")
    }
}

fn validate_directory_name(name: &str) -> bool {
    // Add your specific validation logic here
    !name.contains(|c: char| !c.is_alphanumeric() && c != '_') && name.len() <= 255
}

struct DirectoryManager {
    lock: Arc<Mutex<()>>,
}

impl DirectoryManager {
    fn new() -> Self {
        DirectoryManager { lock: Arc::new(Mutex::new(())) }
    }

    fn create_directory(&self, dir_name: &str) -> io::Result<PathBuf> {
        if let Ok(env_var) = env::var("MY_DIR_PATH") {
            info!("Environment variable already set to {:?}", env_var);
            return Ok(PathBuf::from(env_var));
        }

        self.lock.lock().unwrap();

        for retry in 0..config.max_retries {
            match fs::create_dir(dir_name) {
                Ok(_) => {
                    let path = PathBuf::from(dir_name);
                    if set_env_variable("MY_DIR_PATH", &path).is_ok() {
                        info!("Successfully created and registered directory {:?}", path);
                        return Ok(path);
                    }
                },
                Err(e) => error!("Attempt {} failed to create directory: {:?}", retry + 1, e),
            }

            let sleep_duration = Duration::from_secs(config.backoff_intervals[retry as usize]);
            thread::sleep(sleep_duration);
        }

        error!("Failed to create directory after {} retries", config.max_retries);

        self.lock.unlock();
        Err(io::Error::new(io::ErrorKind::Other, "Exceeded maximum retry attempts"))
    }
}

fn set_env_variable(key: &str, value: &PathBuf) -> io::Result<()> {
    env::set_var(key, value.to_str().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "Invalid path"))?);
    Ok(())
}

fn main() {
    let config = Config::load();
    let dir_manager = DirectoryManager::new();

    match dir_manager.create_directory("example_dir") {
        Ok(_) => info!("Directory setup complete."),
        Err(e) => error!("Failed to set up directory: {:?}", e),
    }
}
