// Plugin Interface
class CryptoPlugin {
public:
    virtual void Initialize() = 0;
    virtual ~CryptoPlugin() {}
};

// Rate Limiter
class RateLimiter {
    using Clock = std::chrono::steady_clock;
    size_t maxOpsPerInterval;
    double intervalSeconds;
    size_t currentOps;
    Clock::time_point lastReset;

public:
    RateLimiter(size_t ops, double seconds) 
        : maxOpsPerInterval(ops), intervalSeconds(seconds), currentOps(0),
          lastReset(Clock::now()) {}

    bool AllowOperation() {
        auto now = Clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastReset).count() >= static_cast<long long>(intervalSeconds)) {
            currentOps = 0;
            lastReset = now;
        }

        if (currentOps < maxOpsPerInterval) {
            ++currentOps;
            return true;
        }

        return false;
    }
};

// Inlining function
std::vector<uint8_t> InlineCopyData(const std::vector<std::unique_ptr<uint8_t[]>>& dataChunks, size_t totalBytesToCopy, size_t chunkSize) {
    std::vector<uint8_t> result(totalBytesToCopy);
    size_t bytesCopied = 0;

    for (const auto& chunk : dataChunks) {
        if (bytesCopied >= totalBytesToCopy) break;

        size_t copyLength = std::min(chunkSize, totalBytesToCopy - bytesCopied);
        std::copy_n(chunk.get(), copyLength, result.begin() + bytesCopied);

        bytesCopied += copyLength;
    }

    return result;
}

