    public static XmlNode GetElementByName(XmlDocument doc, string elementName)
    {
        var nodes = doc.SelectNodes($"//{elementName}");

        if (nodes.Count == 0)
            throw new Exception("No elements found with the given name.");

        if (nodes.Count > 1)
            throw new Exception("Multiple elements found with the same name.");

        return nodes[0];
    }
