#include <stdio.h>
#include <stdlib.h>

char* AppendSlashIfNeeded(const char* str, size_t limit) {
    size_t len = strlen(str);
    if (len + 1 > limit)
        return NULL;

    char* newStr = malloc(limit + 1);
    if (!newStr)
        return NULL;

    strcpy(newStr, str);
    strcat(newStr, "/");
    return newStr;
}
