import hashlib

def calculate_file_md5(file_path, chunk_size=8192, progress_callback=None, storage_backend=None):
    try:
        md5 = hashlib.md5()

        def update_progress(offset, total_bytes):
            if progress_callback:
                completed_percentage = (offset / total_bytes) * 100
                progress_callback(completed_percentage)

        file_size = None
        with open(file_path, 'rb') as f:
            try:
                # Try to get the file size for progress reporting.
                file_size = f.seek(0, 2)  # Seek to end of file to get the size
                f.seek(0)  # Reset to start

                offset = 0
                while chunk := f.read(chunk_size):
                    md5.update(chunk)
                    offset += len(chunk)
                    update_progress(offset, file_size)

            except (IOError, OSError) as e:
                print(f"Error reading the file: {e}")
                return None

        hash_value = md5.hexdigest()

        if storage_backend:
            # Assuming `store_hash` is a method of storage backend instance.
            storage_backend.store_hash(file_path, hash_value)

        return hash_value

    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def read_and_sort_file_lines(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = sorted(file.readlines())

        if not lines:
            raise ValueError("File is empty.")

        last_line = lines[-1].strip()
        sequence_number = extract_sequence(last_line)
        return sequence_number

    except FileNotFoundError:
        print(f"File {file_path} does not exist.")
        return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def extract_sequence(line):
    import re
    match = re.search(r'(\d+)$', line)
    if match:
        return int(match.group(1))
    else:
        raise ValueError("No sequence number found in the last line.")
