import asyncio
import aiohttp
from abc import ABC, abstractmethod
from collections import deque
import logging
import threading

class TrendDetectionStrategy(ABC):
    @abstractmethod
    async def analyze(self, stock_data: list) -> dict:
        pass

class SimpleMovingAverage(TrendDetectionStrategy):
    def __init__(self, period: int = 20):
        self.period = period

    async def analyze(self, stock_data: list) -> dict:
        if len(stock_data) < self.period:
            return {"error": "Insufficient data for SMA analysis"}

        sma = sum(stock_data[-self.period:]) / self.period
        return {"simple_moving_average": sma}

class ExponentialMovingAverage(TrendDetectionStrategy):
    def __init__(self, period: int = 20):
        self.period = period

    async def analyze(self, stock_data: list) -> dict:
        if len(stock_data) < self.period:
            return {"error": "Insufficient data for EMA analysis"}

        ema = sum(stock_data[-self.period:]) / self.period
        # Simplified calculation, in practice use weighted average
        return {"exponential_moving_average": ema}

class RealTimeStockTrendAnalyzer:
    def __init__(self, api_url: str, api_key: str):
        self.api_url = api_url
        self.api_key = api_key
        self.cache_lock = threading.Lock()
        self.data_cache = {}
        self.strategy = None

    async def fetch_stock_data(self, symbol: str) -> list:
        if symbol in self.data_cache:
            return self.data_cache[symbol]

        headers = {"Authorization": f"Bearer {self.api_key}"}
        async with aiohttp.ClientSession() as session:
            try:
                async with session.get(f"{self.api_url}/stock/{symbol}", headers=headers) as response:
                    if response.status == 200:
                        data = await response.json()
                        self._cache_data(symbol, data)
                        return data['prices']
                    else:
                        logging.error("Failed to fetch stock data")
            except aiohttp.ClientError as e:
                logging.error(f"HTTP error: {e}")

        return []

    def _cache_data(self, symbol: str, data: list):
        with self.cache_lock:
            if len(self.data_cache) >= 100:  # Cache size limit
                self.data_cache.pop(next(iter(self.data_cache)))  # Evict oldest entry
            self.data_cache[symbol] = data

    def set_strategy(self, strategy: TrendDetectionStrategy):
        if not isinstance(strategy, TrendDetectionStrategy):
            raise ValueError("Invalid trend detection strategy")
        self.strategy = strategy

    async def generate_report(self, symbol: str) -> dict:
        stock_data = await self.fetch_stock_data(symbol)

        if not stock_data or not self.strategy:
            return {"error": "No data available or strategy not set"}

        try:
            analysis_result = await self.strategy.analyze(stock_data)
            return analysis_result
        except Exception as e:
            logging.error(f"Analysis error: {e}")
            return {"error": str(e)}

# Unit tests would be implemented using a testing framework like unittest or pytest

async def main():
    api_url = "https://api.example.com"
    api_key = "your_api_key_here"
    analyzer = RealTimeStockTrendAnalyzer(api_url, api_key)

    # Set strategy and generate report
    analyzer.set_strategy(SimpleMovingAverage(period=10))
    result = await analyzer.generate_report("AAPL")
    print(result)

if __name__ == "__main__":
    asyncio.run(main())
```

