import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.function.Predicate;
import java.util.List;
import java.util.ArrayList;
import java.util.stream.Collectors;

// Pluggable storage backend interface
interface StorageBackend {
    void saveFilteredData(List<String> filteredData, String outputPath) throws IOException;
}

class FileStorageBackend implements StorageBackend {
    @Override
    public void saveFilteredData(List<String> filteredData, String outputPath) throws IOException {
        Files.write(Paths.get(outputPath), filteredData);
    }
}

public class CsvFilter {

    public static void filterCsv(String file_path, Predicate<List<String>> filter_condition, 
                                String output_path, StorageBackend storageBackend, boolean logProgress) throws IOException {

        Path path = Paths.get(file_path);

        try (BufferedReader reader = Files.newBufferedReader(path)) {
            List<String> filteredData = new ArrayList<>();

            ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
            CompletionService<List<String>> completionService = 
                    new ExecutorCompletionService<>(executor);

            String line;
            int lineNumber = 0;

            while ((line = reader.readLine()) != null) {
                List<String> row = List.of(line.split(","));
                completionService.submit(() -> {
                    if (filter_condition.test(row)) {
                        return row;
                    }
                    return null;
                });

                lineNumber++;
                if (logProgress && lineNumber % 1000 == 0) {
                    System.out.println("Processed " + lineNumber + " lines.");
                }
            }

            executor.shutdown();

            try {
                while (!executor.isTerminated()) {
                    Future<List<String>> future = completionService.take();
                    List<String> result = future.get();
                    if (result != null) {
                        filteredData.add(String.join(",", result));
                    }
                }
            } catch (InterruptedException | ExecutionException e) {
                throw new IOException("Error processing CSV file.", e);
            }

            storageBackend.saveFilteredData(filteredData, output_path);

        } catch (FileNotFoundException e) {
            System.err.println("File not found: " + file_path);
        } catch (IOException e) {
            System.err.println("IO error while reading/writing files.");
            throw e;
        }
    }

    public static void main(String[] args) throws IOException {
        String filePath = "path/to/input.csv";
        String outputPath = "path/to/output.csv";

        filterCsv(filePath, row -> Integer.parseInt(row.get(0)) > 100, 
                  outputPath, new FileStorageBackend(), true);
    }
}
