import os
import csv
from concurrent.futures import ProcessPoolExecutor

def process_csv(file_path, filter_condition):
    try:
        with open(file_path, mode='r', newline='') as file:
            reader = csv.reader(file)
            filtered_data = [row for row in reader if filter_condition(row)]
        return filtered_data
    except Exception as e:
        print(f"Warning: Could not process {file_path} due to {e}")
        return []

def aggregate_csvs(directory_path, output_file, filter_condition):
    csv_files = [os.path.join(directory_path, f) for f in os.listdir(directory_path) if f.endswith('.csv')]

    with ProcessPoolExecutor() as executor:
        results = list(executor.map(lambda file: process_csv(file, filter_condition), csv_files))

    aggregated_data = [item for sublist in results if sublist for item in sublist]

    try:
        with open(output_file, mode='w', newline='') as out_file:
            writer = csv.writer(out_file)
            writer.writerows(aggregated_data)
    except Exception as e:
        print(f"Warning: Could not write to {output_file} due to {e}")

# Example usage
def example_filter_condition(row):
    return int(row[0]) > 100

directory_path = "path/to/csv/directory"
output_file = "path/to/aggregate_output.csv"

aggregate_csvs(directory_path, output_file, example_filter_condition)
