                    'anomalies': detected_anomalies
                })

# Worker function for concurrent processing
def worker(file_queue, result_list):
    while not file_queue.empty():
        filepath = file_queue.get()
        process_log_file(filepath, result_list)
        file_queue.task_done()

def analyze_logs(directory_path):
    log_files = [
        os.path.join(root, f) 
        for root, _, files in os.walk(directory_path) 
        for f in files if not f.startswith('.')
    ]

    anomaly_report = []
    file_queue = Queue()

    # Populate the queue
    for filepath in log_files:
        file_queue.put(filepath)

    threads = []

    for _ in range(min(10, len(log_files))):  # Max 10 concurrent threads
        t = threading.Thread(target=worker, args=(file_queue, anomaly_report))
        t.start()
        threads.append(t)

    for t in threads:
        t.join()

    return anomaly_report

