### 1. Inventory Management Service

```java
public class InventoryService {
    private final ProductRepository productRepo;
    private final CacheService cacheService;
    private final PaymentGateway paymentGateway;

    public InventoryService(ProductRepository productRepo, CacheService cacheService, PaymentGateway paymentGateway) {
        this.productRepo = productRepo;
        this.cacheService = cacheService;
        this.paymentGateway = paymentGateway;
    }

    public synchronized void updateStock(int productId, int quantityChange) {
        // Fetch from cache
        Product cachedProduct = cacheService.getProduct(productId);

        if (cachedProduct != null) {
            cachedProduct.setQuantity(cachedProduct.getQuantity() + quantityChange);
            cacheService.updateProduct(cachedProduct);

            // Update database
            productRepo.updateStock(productId, quantityChange);

            // Publish to Kafka for notification
            kafkaProducer.send(new StockUpdateEvent(productId, quantityChange));
        } else {
            // Fetch from DB if not in cache and update both
            Product dbProduct = productRepo.findById(productId).orElseThrow(() -> new RuntimeException("Product not found"));
            dbProduct.setQuantity(dbProduct.getQuantity() + quantityChange);

            productRepo.saveOrUpdate(dbProduct);
            cacheService.updateProduct(dbProduct);

            kafkaProducer.send(new StockUpdateEvent(productId, quantityChange));
        }
    }

    public void processPreOrder(int productId) {
        // Fetch pre-order queue and process
    }
}
```

