### 3. Caching Layer with Redis

```java
public class CacheService {
    private final JedisPool jedisPool;

    public CacheService(JedisPool jedisPool) {
        this.jedisPool = jedisPool;
    }

    public Product getProduct(int productId) {
        try (Jedis jedis = jedisPool.getResource()) {
            String productJson = jedis.get("product:" + productId);
            return productJson != null ? objectMapper.readValue(productJson, Product.class) : null;
        }
    }

    public void updateProduct(Product product) {
        try (Jedis jedis = jedisPool.getResource()) {
            String productJson = objectMapper.writeValueAsString(product);
            jedis.setex("product:" + product.getId(), 3600, productJson); // cache for 1 hour
        }
    }
}
```

