```java
package cache;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class ResponseCache {
    private ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();

    public String get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && !entry.isExpired()) {
            return entry.getData();
        }
        return null;
    }

    public void put(String key, String data, long ttl, TimeUnit unit) {
        cache.put(key, new CacheEntry(data, System.currentTimeMillis() + unit.toMillis(ttl)));
    }

    private static class CacheEntry {
        private final String data;
        private final long expiryTime;

        CacheEntry(String data, long expiryTime) {
            this.data = data;
            this.expiryTime = expiryTime;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expiryTime;
        }

        public String getData() {
            return data;
        }
    }
}
```

#### ApiClient.java

```java
package http;

import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Map;
import org.json.JSONObject; // Assume using a library like org.json for parsing

public class ApiClient {

    private static final int MAX_RETRIES = 3;
    private RateLimiter rateLimiter;
    private ResponseCache responseCache;

    public ApiClient(RateLimiter rateLimiter, ResponseCache cache) {
        this.rateLimiter = rateLimiter;
        this.responseCache = cache;
    }

    public String fetchData(String endpoint, Map<String, String> headers, Map<String, String> params) throws Exception {

        // Check cache first
        String cacheKey = generateCacheKey(endpoint, params);
        String cachedData = responseCache.get(cacheKey);
        if (cachedData != null) {
            return cachedData;
        }

        int attempts = 0;
        while (attempts < MAX_RETRIES) {
            try {
                rateLimiter.acquire();

                URL url = new URL(endpoint); // Assume params are handled in endpoint
                HttpURLConnection connection = (HttpURLConnection) url.openConnection();

                for (Map.Entry<String, String> header : headers.entrySet()) {
                    connection.setRequestProperty(header.getKey(), header.getValue());
                }

                int responseCode = connection.getResponseCode();
                if (responseCode == 200) {
                    // Handle different response formats
                    String responseData = readResponse(connection);
                    JSONObject json = new JSONObject(responseData); // Example parsing

                    responseCache.put(cacheKey, responseData, 60, TimeUnit.SECONDS);
                    return json.toString(); // Or handle as needed
                } else {
                    throw new Exception("HTTP error: " + responseCode);
                }
            } catch (Exception e) {
                Logger.log(e.getMessage());
                attempts++;
                if (attempts >= MAX_RETRIES) {
                    throw e;
                }
            }
        }

        return null; // Should not reach here
    }

    private String generateCacheKey(String endpoint, Map<String, String> params) {
        return endpoint + "?" + params.toString();
    }

    private String readResponse(HttpURLConnection connection) throws Exception {
        // Read and return the response data
        return ""; // Implement reading logic
    }
}
