Certainly! Below is a C function that integrates with a real-time chat application developed in Node.js using OpenSSL for secure communication. This function handles the creation of a cipher object based on command line options.

```c
#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to create and return an EVP_CIPHER_CTX pointer
EVP_CIPHER_CTX* create_cipher_context(const char* algorithm, const unsigned char* key, int key_len) {
    EVP_CIPHER_CTX *ctx = NULL;

    // Check for valid input parameters
    if (!algorithm || !key || key_len <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    // Create and initialize the cipher context
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create EVP_CIPHER_CTX.\n");
        return NULL;
    }

    // Determine algorithm type based on command line option
    const EVP_CIPHER *cipher_type = NULL;
    int block_size, key_len_expected;

    if (strcmp(algorithm, "AES-128-CBC") == 0) {
        cipher_type = EVP_aes_128_cbc();
        block_size = AES_BLOCK_SIZE;
        key_len_expected = 16;
    } else if (strcmp(algorithm, "AES-256-CBC") == 0) {
        cipher_type = EVP_aes_256_cbc();
        block_size = AES_BLOCK_SIZE;
        key_len_expected = 32;
    } else {
        fprintf(stderr, "Unsupported algorithm: %s\n", algorithm);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Check if the provided key length matches the expected key length
    if (key_len != key_len_expected) {
        fprintf(stderr, "Invalid key length for algorithm %s. Expected %d bytes.\n",
                algorithm, key_len_expected);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize encryption operation with given parameters
    if (!EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, NULL)) {
        fprintf(stderr, "Failed to initialize encryption context.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <algorithm> <key> <key_len>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* algorithm = argv[1];
    unsigned char key[(strlen(argv[2]) > 32) ? 32 : strlen(argv[2])];
    memcpy(key, argv[2], strlen(argv[2]));
    int key_len = atoi(argv[3]);

    EVP_CIPHER_CTX *cipher_ctx = create_cipher_context(algorithm, key, key_len);
    if (cipher_ctx != NULL) {
        printf("Cipher context created successfully.\n");

        // Clean up
        EVP_CIPHER_CTX_free(cipher_ctx);
    } else {
        printf("Failed to create cipher context.\n");
    }

    return EXIT_SUCCESS;
}
```

This code creates a cipher context for AES encryption using OpenSSL based on the provided algorithm. It supports `AES-128-CBC` and `AES-256-CBC`. The main function demonstrates how you would call this C function from a command line, which could be integrated into a Node.js application through native addons or similar mechanisms.

