class FileMetadataExtractor:
    def __init__(self, storage_service_url):
        self.storage_service_url = storage_service_url
        self.cache = TTLCache(maxsize=100, ttl=300)  # Cache with max size and time-to-live of 5 minutes
        self.session = None

    async def _create_session(self):
        if not self.session:
            self.session = aiohttp.ClientSession()

    async def _close_session(self):
        if self.session:
            await self.session.close()
            self.session = None

    async def extract_metadata(self, file_path):
        try:
            await self._create_session()
            schema = await self.get_file_schema(file_path)

            if not self.validate_format(file_path, schema):
                logging.error(f"Invalid file format for {file_path}")
                return None

            cached_metadata = self.cache.get(file_path)
            if cached_metadata:
                return cached_metadata

            async with self.session.get(f"{self.storage_service_url}/{file_path}") as response:
                if response.status != 200:
                    logging.error(f"Failed to retrieve file: {response.status}")
                    return None
                data = await response.read()
                metadata = self.parse_metadata(data, schema)

                # Cache the result
                self.cache[file_path] = metadata

            return metadata

        except Exception as e:
            logging.exception("An error occurred while extracting metadata")
