@Service
public class AsyncFileReader {

    @Autowired
    private ReactiveFilesService reactiveFilesService;

    public Flux<String> readFileAsync(Path filePath) {
        return Files.lines(filePath)
                    .flatMap(line -> processLine(line))
                    .onErrorResume(e -> Flux.empty());
    }

    private Mono<String> processLine(String line) {
        // Process each line, e.g., filter based on regex
        if (line.matches(".*(error|warning).*")) {
            return Mono.just(line);
        }
        return Mono.empty();
    }
}
