import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.scheduling.annotation.Async;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.web.bind.annotation.*;
import org.springframework.cloud.config.server.EnableConfigServer;

import java.util.concurrent.TimeUnit;

@SpringBootApplication
@EnableConfigServer
public class CacheMicroserviceApplication {

    public static void main(String[] args) {
        SpringApplication.run(CacheMicroserviceApplication.class, args);
    }

    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(connectionFactory);
        return template;
    }
}

@RestController
@RequestMapping("/api/cache")
class CacheController {

    private final RedisService cacheService;

    @Autowired
    public CacheController(RedisService cacheService) {
        this.cacheService = cacheService;
    }

    @GetMapping("/{key}")
    public Object getFromCache(@PathVariable String key) {
        return cacheService.retrieve(key);
    }

    @PostMapping("/insert")
    public void insertToCache(@RequestParam String key, @RequestBody Object value) {
        cacheService.insert(key, value);
    }

    @PutMapping("/update")
    public void updateCache(@RequestParam String key, @RequestBody Object value) {
        cacheService.update(key, value);
    }
}

@Service
class RedisService {

    private final RedisTemplate<String, Object> redisTemplate;
    private final ConcurrentHashMap<String, Long> timeoutMap = new ConcurrentHashMap<>();
    private static final long DEFAULT_TIMEOUT = 600; // Default timeout in seconds

    @Autowired
    public RedisService(RedisTemplate<String, Object> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    void insert(String key, Object value) {
        redisTemplate.opsForValue().set(key, value);
        manageTimeout(key, DEFAULT_TIMEOUT);
    }

    Object retrieve(String key) {
        if (timeoutMap.containsKey(key) && System.currentTimeMillis() > timeoutMap.get(key)) {
            redisTemplate.delete(key);
            timeoutMap.remove(key);
        }
        return redisTemplate.opsForValue().get(key);
    }

    void update(String key, Object value) {
        redisTemplate.opsForValue().set(key, value);
        manageTimeout(key, DEFAULT_TIMEOUT); // Reset timeout on update
    }

    private void manageTimeout(String key, long timeout) {
        Long expiryTime = System.currentTimeMillis() + TimeUnit.SECONDS.toMillis(timeout);
        timeoutMap.put(key, expiryTime);
    }
}

// TransactionService with async processing and error handling

@Service
public class TransactionService {

    @Async
    public CompletableFuture<String> processTransaction(Transaction transaction) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                // Simulate transaction logic
                if (Math.random() > 0.2) { // Simulating a success rate
                    return "SUCCESS";
                } else {
                    throw new RuntimeException("Transaction failed");
                }
            } catch (Exception e) {
                handleRetry(transaction);
                return "RETRY";
            }
        });
    }

    private void handleRetry(Transaction transaction) {
        int retryCount = 0;
        while (retryCount < 3) { // Retry logic
            try {
                if (Math.random() > 0.2) {
                    System.out.println("Transaction succeeded on retry");
                    break;
                }
            } catch (Exception ignored) {
            }
            retryCount++;
        }
    }
}

