<?php

use Illuminate\Support\Facades\Redis;
use Illuminate\Support\Facades\Log;

class PasswordManager {
    const DEFAULT_ALGORITHM = PASSWORD_ARGON2ID;
    private $redisClient;
    private $rateLimitWindow = 60; // seconds
    private $maxRequestsPerMinute = 50;

    public function __construct() {
        $this->redisClient = Redis::connection();
    }

    /**
     * Generate a dynamic salt with customizable prefix and suffix.
     */
    public function generateSalt(string $prefix = 'salt_', string $suffix = '_end'): string {
        return $prefix . bin2hex(random_bytes(16)) . $suffix;
    }

    /**
     * Hash the password using a specified algorithm and validate it if needed.
     */
    public function hashPassword(string $password, int $algorithm = self::DEFAULT_ALGORITHM): array {
        // Validate the algorithm
        if (!in_array($algorithm, [PASSWORD_DEFAULT, PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
            throw new \Exception("Unsupported hashing algorithm");
        }

        $options = ['cost' => 12];
        $salt = $this->generateSalt();

        $hash = password_hash($password . $salt, $algorithm, $options);
        if ($hash === false) {
            throw new \RuntimeException('Password hashing failed');
        }

        // Store the hash and salt in Redis
        $key = "user:{$userId}:password";
        $this->redisClient->set($key, ['hash' => $hash, 'salt' => $salt]);

        return ['hash' => $hash, 'salt' => $salt];
    }

    /**
     * Validate a password against the stored hash.
     */
    public function validatePassword(string $password, string $storedHash): bool {
        return password_verify($password, $storedHash);
    }

    /**
     * Rate limiting logic using Redis for multi-tenant support.
     */
    private function isRateLimited(string $identifier): bool {
        $key = "rate_limit:{$identifier}";
        $current = $this->redisClient->get($key) ?: 0;

        if ($current >= $this->maxRequestsPerMinute) {
            return true;
        }

        $this->redisClient->multi()
            ->incr($key)
            ->expire($key, $this->rateLimitWindow)
            ->exec();

        return false;
    }

    /**
     * Log operations with error handling.
     */
    private function logOperation(string $operation, bool $success): void {
        $status = $success ? 'SUCCESS' : 'FAILURE';
        Log::info("Operation: {$operation} | Status: {$status}");
    }
}

// Usage Example
$passwordManager = new PasswordManager();

try {
    if ($passwordManager->isRateLimited('tenant_1')) {
        throw new \Exception('Rate limit exceeded');
    }

    $hashedData = $passwordManager->hashPassword('user_password_here');
    $passwordManager->logOperation('Hashing', true);

} catch (\Exception $e) {
    Log::error("Error: " . $e->getMessage());
    $passwordManager->logOperation('Hashing', false);
}
