using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading;

public class AdvancedRandomGenerator : IDisposable
{
    private Random _random;
    private readonly object _lockObject = new();
    private double _rangeMin;
    private double _rangeMax;
    private string _distributionType;
    private static readonly ConcurrentQueue<string> LogMessages = new();

    public AdvancedRandomGenerator(double rangeMin, double rangeMax, int? seed = null)
    {
        SetRange(rangeMin, rangeMax);
        SetSeed(seed ?? Environment.TickCount);
        _distributionType = "Uniform";
    }

    public void SetRange(double min, double max, bool inclusive = true)
    {
        if (min > max) throw new ArgumentException("Minimum cannot be greater than maximum.");

        lock (_lockObject)
        {
            _rangeMin = inclusive ? min : min + Double.Epsilon;
            _rangeMax = inclusive ? max : max - Double.Epsilon;
        }
    }

    public void SetSeed(int seed)
    {
        if (seed < 0) throw new ArgumentException("Seed cannot be negative.");

        lock (_lockObject)
        {
            _random = new Random(seed);
        }
    }

    public int GetSeed() => _random?.Next() ?? -1;

    public void SetDistribution(string distributionType)
    {
        if (string.IsNullOrEmpty(distributionType)) throw new ArgumentException("Invalid distribution type.");

        lock (_lockObject)
        {
            _distributionType = distributionType;
        }
    }

    public double GenerateRandom()
    {
        lock (_lockObject)
        {
            switch (_distributionType.ToLower())
            {
                case "uniform":
                    return _random.NextDouble() * (_rangeMax - _rangeMin) + _rangeMin;

                case "normal":
                    return SampleNormalDistribution();

                case "exponential":
                    return SampleExponentialDistribution(1.0); // Example lambda

                default:
                    throw new ArgumentException("Unsupported distribution type.");
            }
        }
    }

    public double[] GenerateRandomSequence(int count)
    {
        var result = new double[count];
        for (int i = 0; i < count; i++)
        {
            result[i] = GenerateRandom();
        }

        Log($"Generated {count} random values using {_distributionType} distribution.");
        return result;
    }

    private double SampleNormalDistribution()
    {
        // Box-Muller transform for normal distribution
        double u1 = _random.NextDouble();
        double u2 = _random.NextDouble();

        double z0 = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Cos(2.0 * Math.PI * u2);
        double mean = (_rangeMax + _rangeMin) / 2;
        double stdDev = (_rangeMax - _rangeMin) / 6; // Approx. 99.7% values within range

        return z0 * stdDev + mean;
    }

    private double SampleExponentialDistribution(double lambda)
    {
        if (lambda <= 0) throw new ArgumentException("Lambda must be positive.");

        double u = _random.NextDouble();
        return -Math.Log(1 - u) / lambda;
    }

    public void Reset()
    {
        lock (_lockObject)
        {
            _random = new Random(GetSeed());
        }
    }

    private static void Log(string message)
    {
        LogMessages.Enqueue(message);
        Console.WriteLine($"[Log]: {message}");
    }

    public override string ToString()
    {
        return $"Range: [{_rangeMin}, {_rangeMax}], Seed: {GetSeed()}, Distribution: {_distributionType}";
    }

    public void LoadConfigurationFromFile(string filePath)
    {
        if (!File.Exists(filePath)) throw new FileNotFoundException("Configuration file not found.");

        var lines = File.ReadAllLines(filePath);
        foreach (var line in lines)
        {
            var parts = line.Split('=');
            switch (parts[0].Trim().ToLower())
            {
                case "range_min":
                    SetRange(double.Parse(parts[1]), _rangeMax);
                    break;

                case "range_max":
                    SetRange(_rangeMin, double.Parse(parts[1]));
                    break;

                case "seed":
                    SetSeed(int.Parse(parts[1]));
                    break;

                case "distribution":
                    SetDistribution(parts[1]);
                    break;
            }
        }
    }

    public void Dispose()
    {
        _random?.Dispose();
        GC.SuppressFinalize(this);
    }
}

// Example of CLI commands and tests can be implemented separately as needed.
