void modifyAndStoreList(std::forward_list<std::string>& flist, 
                        const std::string& searchString,
                        const std::string& insertionString,
                        size_t maxInsertionsAllowed) {
    bool inserted = false;
    size_t count = 0;

    for (auto it = flist.begin(); it != flist.end() && count < maxInsertionsAllowed; ++it, ++count) {
        if (*it == searchString) {
            // Truncate the insertion string to a maximum of 100 characters
            std::string safeInsertionString = insertionString.length() > 100 ? 
                                              insertionString.substr(0, 100) : insertionString;

            flist.insert_after(it, safeInsertionString);
            inserted = true;
            break;
        }
    }

    if (!inserted && count < maxInsertionsAllowed) {
        // Truncate the insertion string to a maximum of 100 characters
        std::string safeInsertionString = insertionString.length() > 100 ? 
                                          insertionString.substr(0, 100) : insertionString;

        flist.push_back(safeInsertionString);
    }

    // Ensure all elements are within the length limit
    for (auto& elem : flist) {
        if (elem.size() > 100) {
            elem = elem.substr(0, 100);
        }
    }

    Database db;

    {
        std::lock_guard<std::mutex> lock(dbMutex); // Ensure thread-safety for database operations
        storeListInDatabase(flist, db);
    }
}

// Comprehensive unit tests to cover edge cases and expected behavior.
