import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

public class ConfigManager<K, V> {
    private final Map<String, Supplier<V>> factoryRegistry = new ConcurrentHashMap<>();
    private final Yaml yamlParser = new Yaml(new Constructor(Map.class));

    public void addFactoryFunction(String id, Supplier<V> supplier) {
        if (supplier == null || id == null || id.isEmpty()) {
            throw new IllegalArgumentException("Invalid ID or supplier");
        }
        factoryRegistry.put(id, supplier);
    }

    public void removeFactoryFunction(String id) {
        if (!factoryRegistry.containsKey(id)) {
            throw new NoSuchElementException("Factory function not found for ID: " + id);
        }
        factoryRegistry.remove(id);
    }

    @SuppressWarnings("unchecked")
    public V createInstance(String id) {
        Supplier<V> supplier = (Supplier<V>) factoryRegistry.get(id);
        if (supplier == null) {
            throw new IllegalArgumentException("No factory function registered for ID: " + id);
        }
        return supplier.get();
    }

    public Map<String, Object> readYamlConfig(String filePath) throws IOException {
        String content = new String(Files.readAllBytes(Paths.get(filePath)));
        return (Map<String, Object>) yamlParser.load(content);
    }

    public void writeYamlConfig(Map<String, Object> configData, String filePath) throws IOException {
        Yaml yamlDumper = new Yaml();
        Files.write(Paths.get(filePath), yamlDumper.dump(configData).getBytes());
    }

    public Map<String, Object> mergeConfigs(List<Map<String, Object>> configs) {
        Map<String, Object> mergedConfig = new HashMap<>();
        for (Map<String, Object> config : configs) {
            mergedConfig.putAll(config);
        }
        return mergedConfig;
    }

    public boolean validateConfig(Map<String, Object> configData, Map<String, Class<?>> schema) throws ValidationException {
        for (String key : schema.keySet()) {
            if (!configData.containsKey(key)) {
                throw new ValidationException("Missing required configuration: " + key);
            }
            if (!(schema.get(key).isInstance(configData.get(key)))) {
                throw new ValidationException("Invalid type for configuration: " + key);
            }
        }
        return true;
    }

    public void cleanup() {
        factoryRegistry.clear();
    }

    public static class ValidationException extends Exception {
        public ValidationException(String message) {
            super(message);
        }
    }
}
