```php
class RateLimiter {
    private $attempts = [];
    private $maxAttempts = 3;
    private $timeWindow = 300; // 5 minutes in seconds

    public function canAttempt(string $ipAddress): bool {
        if (!isset($this->attempts[$ipAddress])) {
            $this->attempts[$ipAddress] = [['timestamp' => time()]];
            return true;
        }

        $currentTimestamp = time();
        // Filter attempts within the time window
        $validAttempts = array_filter(
            $this->attempts[$ipAddress],
            function ($attempt) use ($currentTimestamp, $timeWindow) {
                return $currentTimestamp - $attempt['timestamp'] <= $timeWindow;
            }
        );

        if (count($validAttempts) >= $this->maxAttempts) {
            return false;
        }

        // Add current attempt
        $validAttempts[] = ['timestamp' => $currentTimestamp];
        $this->attempts[$ipAddress] = $validAttempts;

        return true;
    }
}

