        $this->pdo = $pdo;
    }

    public function updatePassword(string $userId, string $hashedPassword): bool {
        $stmt = $this->pdo->prepare("UPDATE users SET password_hash = :passwordHash WHERE user_id = :userId");
        return $stmt->execute([':passwordHash' => $hashedPassword, ':userId' => $userId]);
    }
}

class PasswordValidator {
    public function validate(string $password, array $rules): bool {
        if (strlen($password) < $rules['minLength']) {
            return false;
        }

        if ($rules['uppercaseRequired'] && !preg_match('/[A-Z]/', $password)) {
            return false;
        }

        if ($rules['lowercaseRequired'] && !preg_match('/[a-z]/', $password)) {
            return false;
        }

        if ($rules['digitRequired'] && !preg_match('/\d/', $password)) {
            return false;
        }

        if ($rules['specialCharRequired'] && !preg_match('/[!@#$%^&*]/', $password)) {
            return false;
        }

        foreach ($rules['forbiddenSubstrings'] as $substring) {
            if (strpos($password, $substring) !== false) {
                return false;
            }
        }

        return true;
    }
}

class UserManager {
    private $userDAO;
    private $rateLimiter;
    private $logger;
    private $validator;

    public function __construct(PDO $pdo, RateLimiter $rateLimiter, Logger $logger, PasswordValidator $validator) {
        $this->userDAO = new UserDAO($pdo);
        $this->rateLimiter = $rateLimiter;
        $this->logger = $logger;
        $this->validator = $validator;
    }

    public function updateUserPassword(string $userId, string $newPassword, array $localeRules): bool {
        $ipAddress = $_SERVER['REMOTE_ADDR'];

        if (!$this->rateLimiter->canAttempt($ipAddress)) {
            $this->logger->log("Rate limit exceeded for IP: $ipAddress");
            return false;
        }

        $rules = $localeRules[$userId]; // Assuming user ID maps directly to locale key

        if (!$this->validator->validate($newPassword, $rules)) {
            $this->logger->log("Invalid password attempt for User ID: $userId from IP: $ipAddress");
            return false;
        }

        try {
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

            if ($this->userDAO->updatePassword($userId, $hashedPassword)) {
                return true;
            } else {
                $this->logger->log("Failed to update password for User ID: $userId");
                return false;
            }
        } catch (Exception $e) {
            $this->logger->log("Error updating password for User ID: $userId - " . $e->getMessage());
            return false;
        }
    }
}
