import java.util.function.Function;

// Define Configuration class to handle properties
class Config {
    private final Map<String, Object> properties = new ConcurrentHashMap<>();

    public void setProperty(String key, Object value) {
        properties.put(key, value);
    }

    public Object getProperty(String key) {
        return properties.get(key);
    }

    // Add more methods as needed for handling nested structures
}

// Define a factory function type
@FunctionalInterface
interface ConfigFactory<T> extends Function<Config, T> {}

// Main Configuration Manager Class
public class ConfigurationManager {

    private final Map<String, ConfigFactory<?>> factories = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final Yaml yamlParser = new Yaml();
    private final Cache<Config> configCache;

    public ConfigurationManager() {
        // Initialize cache with LRU policy
        this.configCache = Caffeine.newBuilder()
                .expireAfterWrite(10, TimeUnit.MINUTES)
                .maximumSize(100)
                .build();

        // Start a background task for real-time updates
        scheduler.scheduleAtFixedRate(this::fetchUpdatesFromService, 0, 1, TimeUnit.MINUTES);
    }

    public void registerFactory(String id, ConfigFactory<?> factory) {
        factories.put(id, factory);
    }

    public <T> T createConfigInstance(String id, Config config) {
        ConfigFactory<T> factory = (ConfigFactory<T>) factories.get(id);
        if (factory == null) throw new IllegalArgumentException("No factory registered for ID: " + id);

        return factory.apply(config);
    }

    private void fetchUpdatesFromService() {
        // Fetch updates from external service and update configurations
        try {
            URL configUrl = new URL("http://config-service/api/config");
            String configData = new Scanner(configUrl.openStream()).useDelimiter("\\A").next();

            Config config;
            if (isYaml(configData)) {
                config = yamlParser.loadAs(configData, Config.class);
            } else {
                config = objectMapper.readValue(configData, Config.class);
            }

            // Propagate changes to running instances
            updateConfigurations(config);

        } catch (IOException e) {
            logError("Failed to fetch configuration updates", e);
        }
    }

    private boolean isYaml(String data) {
        return data.trim().startsWith("---");
    }

    private void updateConfigurations(Config newConfig) {
        // Update configurations and notify instances
        configCache.put(new ConfigKey(), newConfig);
        // Notify running instances of changes
    }

    public <T> T getConfig(String key, Class<T> clazz) {
        return configCache.get(new ConfigKey(key), () -> fetchFromExternalService(key));
    }

    private <T> T fetchFromExternalService(String key) {
        // Fetch configuration from external service based on key
        try {
            URL url = new URL("http://config-service/api/config/" + key);
            String data = new Scanner(url.openStream()).useDelimiter("\\A").next();
            if (isYaml(data)) {
                return yamlParser.loadAs(data, clazz);
            } else {
                return objectMapper.readValue(data, clazz);
            }
        } catch (IOException e) {
            logError("Failed to fetch configuration for key: " + key, e);
            return null;
        }
    }

    private void logError(String message, Exception e) {
        // Log error with timestamp and stack trace
        System.err.println(message + ": " + e.getMessage());
        e.printStackTrace(System.err);
    }

    public static void main(String[] args) {
        ConfigurationManager manager = new ConfigurationManager();

        // Register factory functions
        manager.registerFactory("example", config -> new ExampleConfig(config));

        // CLI for user interaction (simplified)
        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.println("Enter command:");
            String command = scanner.nextLine();
            if ("exit".equalsIgnoreCase(command)) break;

            handleCommand(manager, command);
        }
    }

    private static void handleCommand(ConfigurationManager manager, String command) {
        // Handle CLI commands
        System.out.println("Executing: " + command);
        // Implement logic to add, remove, query factory functions, and view configurations
    }

    // Define a class for configuration keys
    private static class ConfigKey {
        private final String key;

        public ConfigKey(String key) {
            this.key = key;
        }

        public ConfigKey() {}

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            ConfigKey configKey = (ConfigKey) o;
            return Objects.equals(key, configKey.key);
        }

        @Override
        public int hashCode() {
            return Objects.hash(key);
        }
    }

    // Example configuration class
    static class ExampleConfig {
        private final Config config;

        public ExampleConfig(Config config) {
            this.config = config;
        }

        // Add methods for handling specific properties
    }
}
```

### Key Points:
- **Real-time Updates**: Periodically fetch updates from an external service.
- **Concurrency**: Use `ConcurrentHashMap` and `ExecutorService` for thread-safe operations.
- **Validation & Schema Loading**: Placeholder for schema validation logic, can be extended with a library like Hibernate Validator or custom logic.
- **Caching**: Uses Caffeine cache with LRU eviction policy.
- **Error Handling**: Logs errors with stack traces.
- **Extensibility**: Allows registration of factory functions.
- **CLI Interface**: Simple command-line interface for user interaction.

This is a basic framework and can be expanded with more detailed implementations, especially for validation, schema management, and CLI features.

