    void Library::start() {
        if (isRunning_) return;

        initializeMessageBrokerClient();
        isRunning_ = true;
        std::thread processingThread(&Library::processMessages, this);
        processingThread.detach();
    }

    void Library::stop() {
        if (!isRunning_) return;

        // Implement graceful shutdown
        isRunning_ = false;
    }

    void Library::initializeMessageBrokerClient() {
        brokerClient_ = std::make_unique<MessageBrokerClient>(config_);
        brokerClient_->connect();
    }

    void Library::processMessages() {
        Logger::getLoggerInstance()->log("Processing messages");

        while (isRunning_) {
            std::string message;
            if (brokerClient_->fetchMessage(message)) {
                for (const auto& rule : processingRules_)
                    rule(message);
            }
        }
    }

    void Library::handleErrors(const std::exception& e) {
        Logger::getLoggerInstance()->log("Error: " + std::string(e.what()));
    }

