int convertImagesToPDFs(const fs::path& inputDir, const std::vector<std::string>& imageFiles,
                        const fs::path& outputDir, int resizeWidth = -1) {

    int successfulConversions = 0;

    for (const auto& fileName : imageFiles) {
        fs::path inputFile = inputDir / fileName;
        fs::path outputFile = outputDir / (fileName + ".pdf");

        if (!fs::exists(inputFile)) {
            std::cerr << "Input file does not exist: " << inputFile.string() << '\n';
            continue;  // Skip non-existent files.
        }

        if (convertImageToPDF(inputFile.string(), outputFile.string())) {
            ++successfulConversions;
        } else {
            std::cerr << "Failed to convert file: " << fileName << '\n';
        }
    }

    return successfulConversions;
}
