public class FileSummaryProcessor {
    private static final Logger logger = Logger.getLogger(FileSummaryProcessor.class.getName());
    private ExecutorService executorService;
    private Map<String, String> fileCache = new ConcurrentHashMap<>();
    private List<Path> directoriesToScan;
    private Set<String> keywords;
    private Charset defaultCharset = StandardCharsets.UTF_8;

    public FileSummaryProcessor(int threadPoolSize, Path baseDir, Set<String> keywords) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.directoriesToScan = new ArrayList<>();
        directoriesToScan.add(baseDir);
        this.keywords = keywords;
        setupLogger();
    }

    private void setupLogger() {
        try {
            FileHandler fileHandler = new FileHandler("processor.log", true);
            fileHandler.setFormatter(new SimpleFormatter());
            logger.addHandler(fileHandler);
            logger.setLevel(Level.ALL);
        } catch (IOException e) {
            System.err.println("Failed to set up logging: " + e.getMessage());
        }
    }

    public void processFiles() throws InterruptedException, ExecutionException {
        for (Path dir : directoriesToScan) {
            Files.walkFileTree(dir, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                    if (!file.toString().endsWith(".txt")) return FileVisitResult.CONTINUE;
                    executorService.submit(() -> processFile(file));
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                    directoriesToScan.add(dir);
                    return FileVisitResult.CONTINUE;
                }
            });
        }

        executorService.shutdown();
        executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }

    private void processFile(Path file) {
        try {
            Charset charset = detectCharset(file);
            String content = new String(Files.readAllBytes(file), charset);

            if (fileCache.containsKey(file.toString())) {
                logger.info("Using cached result for " + file);
                return;
            }

            Map<String, Integer> keywordCount = countKeywords(content);
            saveToCache(file.toString(), keywordCount);
            uploadSummaryReport(file, keywordCount);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error processing file: " + file, e);
        }
    }

    private Charset detectCharset(Path file) throws IOException {
        try (InputStream fis = Files.newInputStream(file)) {
            BOMInputStream bis = new BOMInputStream(fis);
            Charset charset = bis.getEncoding();
            if (charset == null) {
                return defaultCharset;
            }
            return charset;
        }
    }

    private Map<String, Integer> countKeywords(String content) {
        Map<String, Integer> keywordCount = new HashMap<>();
        for (String keyword : keywords) {
            long count = Pattern.compile(keyword, Pattern.CASE_INSENSITIVE).matcher(content).results().count();
            keywordCount.put(keyword, (int) count);
        }
        return keywordCount;
    }

    private void saveToCache(String filePath, Map<String, Integer> summary) {
        fileCache.put(filePath, summary.toString());
        logger.info("Saved cache for " + filePath);
    }

    private void uploadSummaryReport(Path file, Map<String, Integer> summary) {
        // Placeholder for API integration logic
        try {
            // Simulate API call and retry mechanism
            boolean success = apiCallSimulator(file, summary);
            if (!success) {
                handleFailedUpload(file, summary);
            } else {
                logger.info("Successfully uploaded summary report for " + file);
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "API upload failed: " + file, e);
        }
    }

    private boolean apiCallSimulator(Path file, Map<String, Integer> summary) {
        // Simulated API call
        return true; // or false for retry logic simulation
    }

    private void handleFailedUpload(Path file, Map<String, Integer> summary) {
        int retries = 0;
        while (retries < 3) {  // Retry up to 3 times with backoff
            try {
                Thread.sleep((long) Math.pow(2, retries++) * 1000);
                boolean success = apiCallSimulator(file, summary);
                if (success) {
                    logger.info("Successfully uploaded on retry for " + file);
                    return;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        logger.severe("Failed to upload after retries: " + file);
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Set<String> keywords = new HashSet<>(Arrays.asList("error", "warning"));
        Path baseDir = Paths.get("/path/to/directory");
        FileSummaryProcessor processor = new FileSummaryProcessor(10, baseDir, keywords);
        processor.processFiles();
    }
}
