```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using MySql.Data.MySqlClient;
using Npgsql;
using Amazon.S3;
using Amazon.S3.Transfer;

public class CloudStorageService
{
    private readonly ILogger<CloudStorageService> _logger;
    private const int MaxSinglePartSize = 5 * 1024 * 1024; // 5MB for S3 example

    public CloudStorageService(ILogger<CloudStorageService> logger)
    {
        _logger = logger;
    }

    public async Task DecryptAndUploadAsync(
        string filePath, 
        string bucketName,
        byte[] key, 
        byte[] iv, 
        PaddingMode paddingMode,
        CancellationToken cancellationToken)
    {
        if (!ValidateKeyIV(key, iv))
            throw new ArgumentException("Invalid Key or IV length");

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Padding = GetPadding(paddingMode);

            try
            {
                string decryptedFilePath = await DecryptFileAsync(filePath, aes, cancellationToken);

                if (!File.Exists(decryptedFilePath))
                    throw new FileNotFoundException("Decrypted file not found");

                long fileSize = new FileInfo(decryptedFilePath).Length;

                // Calculate SHA-256 hash of the decrypted file in chunks
                using (FileStream fs = File.OpenRead(decryptedFilePath))
                {
                    var sha256 = SHA256.Create();
                    byte[] buffer = new byte[8192];
                    int bytesRead;

                    while ((bytesRead = await fs.ReadAsync(buffer, 0, buffer.Length, cancellationToken)) > 0)
                    {
                        sha256.TransformBlock(buffer, 0, bytesRead, null, 0);
                    }
                    sha256.TransformFinalBlock(buffer, 0, 0);

                    byte[] fileHash = sha256.Hash;
                }

                // Upload the decrypted file
                await UploadFileAsync(bucketName, decryptedFilePath, cancellationToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error during decryption and upload");
                throw;
            }
        }
    }

    private bool ValidateKeyIV(byte[] key, byte[] iv)
    {
        return key.Length == 16 || key.Length == 24 || key.Length == 32; // AES supports 128, 192, or 256 bits
        && iv.Length == 16; // CBC mode requires a 128-bit IV
    }

    private PaddingMode GetPadding(PaddingMode paddingMode)
    {
        switch (paddingMode)
        {
            case PaddingMode.PKCS7:
                return PaddingMode.PKCS7;
            case PaddingMode.ANSIX923:
                return PaddingMode.AnsiX923;
            case PaddingMode.None:
                return PaddingMode.None;
            default:
                throw new ArgumentOutOfRangeException(nameof(paddingMode), "Invalid padding mode");
        }
    }

    private async Task<string> DecryptFileAsync(string filePath, Aes aes, CancellationToken cancellationToken)
    {
        string decryptedFilePath = Path.Combine(Path.GetDirectoryName(filePath)!, $"{Path.GetFileNameWithoutExtension(filePath)}_decrypted{Path.GetExtension(filePath)}");

        using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
        using (var inputFileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
        using (var outputFileStream = new FileStream(decryptedFilePath, FileMode.Create, FileAccess.Write, FileShare.None, 4096, true))
        using (var cryptoStream = new CryptoStream(outputFileStream, decryptor, CryptoStreamMode.Write))
        {
            await inputFileStream.CopyToAsync(cryptoStream, 8192, cancellationToken);
        }

        return decryptedFilePath;
    }

    private async Task UploadFileAsync(string bucketName, string filePath, CancellationToken cancellationToken)
    {
        var s3Client = new AmazonS3Client();
        var fileTransferUtility = new TransferUtility(s3Client);

        long fileSize = new FileInfo(filePath).Length;

        if (fileSize <= MaxSinglePartSize)
        {
            await fileTransferUtility.UploadAsync(filePath, bucketName);
        }
        else
        {
            using (var request = new TransferUtilityUploadRequest
            {
                BucketName = bucketName,
                FilePath = filePath,
                Key = Path.GetFileName(filePath),
                PartSizeBytes = MaxSinglePartSize,
                CancellationToken = cancellationToken
            })
            {
                await fileTransferUtility.UploadAsync(request);
            }
        }

        _logger.LogInformation($"File {filePath} uploaded successfully to bucket {bucketName}");
    }

    // Additional methods for key rotation, logging, and handling multiple databases would be implemented here.
}

// Unit Tests would be written separately using a testing framework like xUnit or NUnit
