// string_processing.h
#ifndef STRING_PROCESSING_H
#define STRING_PROCESSING_H

#include <stddef.h>

char* append_slash_if_necessary(char *str, size_t max_length);

#endif // STRING_PROCESSING_H


// string_processing.c
#include "string_processing.h"
#include <stdlib.h>
#include <string.h>

char* append_slash_if_necessary(char *str, size_t max_length) {
    if (str == NULL || max_length <= 0) return str;

    size_t len = strlen(str);
    if (len > max_length - 1) {
        char *new_str = malloc(len + 2); // Allocate space for slash and null terminator
        if (!new_str) return str; // Return original string on allocation failure

        strncpy(new_str, str, len);
        new_str[len] = '\0';
    } else {
        char *new_str = realloc(str, len + 2); // Resize existing buffer to add slash and null terminator
        if (!new_str) return str; // Return original string on allocation failure
    }

    new_str[len] = '/';
    new_str[len + 1] = '\0';

    return new_str;
}


