class TransactionCache {
public:
    void put(const std::string& key, const std::string& value, int ttl_seconds) {
        auto expiry_time = std::chrono::steady_clock::now() + std::chrono::seconds(ttl_seconds);
        std::lock_guard<std::mutex> lock(cache_mutex_);
        cache_[key] = {value, expiry_time};
    }

    bool get(const std::string& key, std::string& value) {
        std::lock_guard<std::mutex> lock(cache_mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end() && it->second.second > std::chrono::steady_clock::now()) {
            value = it->second.first;
            return true;
        }
        return false;
    }

private:
