                std::this_thread::sleep_for(std::chrono::seconds(1 << retry_attempts));
                retry_attempts++;
            }
        } catch (const std::exception& e) {
            logger.log(Logger::ERROR, "Error during transaction: " + std::string(e.what()));
            std::this_thread::sleep_for(std::chrono::seconds(1 << retry_attempts));
