#include "BloomFilterMock.h" 

class TransactionAnalyzer {
public:
    TransactionAnalyzer(size_t size, double falsePositiveRate);

    void initialize();
    bool addTransaction(const std::string& transactionId);
    bool isDuplicate(const std::string& transactionId) const;
    void trackTimeForSuspiciousActivityCheck(std::function<void()> operation);

private:
    BloomFilterMock bloomFilter;
    mutable std::mutex mtx;
    size_t batchSize;

    // Function to simulate API call and handle errors
    nlohmann::json fetchTransactionMetadata(const std::string& transactionId);

    void retryFetchWithExponentialBackoff(std::function<nlohmann::json()> fetchFunction, int maxRetries = 3);

public:
    static void analyzeTransactionsFromFile(const std::string& filePath, const std::string& apiEndpoint);
};

TransactionAnalyzer::TransactionAnalyzer(size_t size, double falsePositiveRate)
    : bloomFilter(size, falsePositiveRate), batchSize(100) {}

void TransactionAnalyzer::initialize() {
    // Initialize any necessary resources
}

bool TransactionAnalyzer::addTransaction(const std::string& transactionId) {
    std::lock_guard<std::mutex> lock(mtx);
    return bloomFilter.add(transactionId);
}

bool TransactionAnalyzer::isDuplicate(const std::string& transactionId) const {
    std::lock_guard<std::mutex> lock(mtx);
    return bloomFilter.contains(transactionId);
}

void TransactionAnalyzer::trackTimeForSuspiciousActivityCheck(std::function<void()> operation) {
    auto start = std::chrono::high_resolution_clock::now();
    operation();
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> diff = end - start;
    std::cout << "Operation took: " << diff.count() << " seconds\n";
}

nlohmann::json TransactionAnalyzer::fetchTransactionMetadata(const std::string& transactionId) {
    // Simulate API call using cURL or similar
    CURL* curl;
    CURLcode res;

    nlohmann::json response;

    curl = curl_easy_init();
    if(curl) {
        std::string url = "https://api.paymentgateway.com/transaction/" + transactionId;

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp) -> size_t {
            ((std::string*)userp)->append((char*)contents, size * nmemb);
            return size * nmemb;
        });

        std::string responseString;
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &responseString);

        retryFetchWithExponentialBackoff([&]() -> nlohmann::json {
            if ((res = curl_easy_perform(curl)) == CURLE_OK) {
                return nlohmann::json::parse(responseString);
            } else {
                std::cerr << "API request failed: " << curl_easy_strerror(res) << "\n";
                return {};
            }
        });

        curl_easy_cleanup(curl);
    }

    return response;
}

void TransactionAnalyzer::retryFetchWithExponentialBackoff(std::function<nlohmann::json()> fetchFunction, int maxRetries) {
    nlohmann::json result;
    int attempts = 0;

    while (attempts < maxRetries && result.empty()) {
        try {
            result = fetchFunction();
        } catch (...) {
            std::cerr << "Error occurred during API request. Retrying...\n";
        }

        if (result.empty()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << attempts)));
            ++attempts;
        }
    }

    if (result.empty() && maxRetries > 0) {
        throw std::runtime_error("Failed to fetch transaction metadata after retries.");
    }
}

void TransactionAnalyzer::analyzeTransactionsFromFile(const std::string& filePath, const std::string& apiEndpoint) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        std::cerr << "Could not open file: " << filePath << "\n";
        return;
    }

    std::vector<std::thread> threads;
    std::queue<std::string> transactionQueue;

    // Load transactions into the queue
    std::string line;
    while (std::getline(file, line)) {
        transactionQueue.push(line);
    }
    file.close();

    auto worker = [&]() {
        while (!transactionQueue.empty()) {
            std::string transactionId;
            {
                std::lock_guard<std::mutex> lock(mtx);  // Ensure thread-safe access to the queue
                if (transactionQueue.empty()) continue;
                transactionId = transactionQueue.front();
                transactionQueue.pop();
            }

            bool mightBeDuplicate = isDuplicate(transactionId);
            trackTimeForSuspiciousActivityCheck([&]() {
                nlohmann::json metadata = fetchTransactionMetadata(transactionId);
                // Process metadata...

                if (mightBeDuplicate) {
                    std::cout << "Suspicious activity detected for transaction ID: " << transactionId << "\n";
                }
            });

            if (!mightBeDuplicate) {
                addTransaction(transactionId);
            }
        }
    };

    size_t numThreads = std::thread::hardware_concurrency();
    for (size_t i = 0; i < numThreads; ++i) {
        threads.emplace_back(worker);
    }

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

