function generateRandomStringAndHashPassword($length, $characterSet, $password, $hashAlgorithm = 'bcrypt', $rounds = 10) {
    // Validate inputs
    if ($length <= 0 || empty($characterSet) || !in_array($hashAlgorithm, ['bcrypt', 'sha256'])) {
