    }

    // Ensure character set requirements are met
    $requiredChars = ['A-Z', 'a-z', '0-9', '~!@#$%^&*()_+-=[]{}|;:,.<>?'];
    foreach ($requiredChars as $type) {
        if (preg_match($type, $characterSet) === 0) {
            throw new InvalidArgumentException("Character set must include at least one uppercase letter, lowercase letter, digit, and special character.");
        }
    }

    // Generate random string
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomCharIndex = random_int(0, strlen($characterSet) - 1);
        $randomString .= $characterSet[$randomCharIndex];
    }

    // Check randomness (simplified check here)
    if (!isRandom($randomString)) {
        throw new RuntimeException("Generated string failed randomness check.");
    }

    // Generate salt
    $salt = bin2hex(random_bytes(16));

    // Hash password with chosen algorithm
    switch ($hashAlgorithm) {
        case 'bcrypt':
            $options = ['cost' => $rounds];
            $hashedPassword = password_hash($password . $salt, PASSWORD_BCRYPT, $options);
            break;

        case 'sha256':
            for ($i = 0; $i < $rounds; $i++) {
                $password .= $salt;
                $password = hash('sha256', $password);
            }
            $hashedPassword = $password;
            break;
    }

    // Simulate logging error handling
    try {
        logError("Generated random string and hashed password successfully.");
    } catch (Exception $e) {
        logError($e->getMessage());
    }

    return json_encode([
        'randomString' => $randomString,
        'hashedPassword' => $hashedPassword
    ]);
}

function isRandom($string) {
