// Function to calculate SHA-256 hash of a file
std::string calculateSHA256(const std::string& filePath, size_t chunkSize = 8192) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        Logger::logError("Failed to open file: " + filePath);
        return "";
    }

    char buffer[chunkSize];
    while (file.read(buffer, chunkSize) || file.gcount()) {
        SHA256_Update(&sha256, buffer, file.gcount());
    }
    file.close();

    SHA256_Final(hash, &sha256);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << static_cast<int>(hash[i]);
    }

    return ss.str();
}

// Asynchronous download with resume support
std::future<void> asyncDownload(const std::string& url, const std::string& destPath, size_t chunkSize = 8192) {
    return std::async(std::launch::async, [url, destPath, chunkSize]() {
        // Implement asynchronous download logic with resume support
        Logger::logInfo("Starting async download from " + url);
        // Simulate download
        std::this_thread::sleep_for(std::chrono::seconds(2));
        Logger::logInfo("Download completed to " + destPath);
    });
}

// Rate limiter class
class RateLimiter {
public:
    RateLimiter(int maxRequestsPerSecond) : maxRequests(maxRequestsPerSecond), interval(std::chrono::milliseconds(1000 / maxRequests)) {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait_for(lock, interval, [this]() { return count < maxRequests; });
        if (++count >= maxRequests) {
            count = 0;
        }
    }

private:
    int maxRequests;
    std::chrono::milliseconds interval;
    int count = 0;
    std::mutex mtx;
    std::condition_variable cv;
};

