```python
import os
import requests
from PIL import Image
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
from functools import lru_cache

# Initialize logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ImageProcessingError(Exception):
    pass

def fetch_parameters_from_api():
    try:
        response = requests.get("https://example.com/api/parameters")
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        logger.error(f"Failed to fetch parameters: {e}")
        raise ImageProcessingError("Could not retrieve image processing parameters")

@lru_cache(maxsize=100)
def validate_image_file(file_path):
    try:
        with open(file_path, 'rb') as f:
            Image.open(f).verify()
        return True
    except Exception:
        logger.warning(f"Image file {file_path} is corrupted or invalid.")
        return False

def process_image(file_path, output_dir, params):
    if not validate_image_file(file_path):
        raise ImageProcessingError("Invalid image file")

    try:
        with Image.open(file_path) as img:
            # Resize while maintaining aspect ratio
            img.thumbnail((params['max_width'], params['max_height']))

            output_path = os.path.join(output_dir, os.path.basename(file_path))
            img.save(output_path, "JPEG", quality=params['quality'])

            logger.info(f"Processed image {file_path} and saved to {output_path}")
    except Exception as e:
        logger.error(f"Error processing image {file_path}: {e}", exc_info=True)
        raise ImageProcessingError(f"Failed to process image {file_path}")

def process_images(image_paths, output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    # Fetch external parameters
    try:
        params = fetch_parameters_from_api()
    except ImageProcessingError:
        logger.info("Using default processing parameters.")
        params = {'max_width': 800, 'max_height': 800, 'quality': 85}

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(process_image, file_path, output_dir, params)
                   for file_path in image_paths]

        for future in as_completed(futures):
            try:
                future.result()
            except ImageProcessingError as e:
                logger.warning(f"Processing failed: {e}")

def main():
    # Example usage
    image_files = ['path/to/image1.jpg', 'path/to/image2.png']
    output_directory = 'processed_images'

    process_images(image_files, output_directory)

if __name__ == "__main__":
    main()
