std::mutex listMutex;

void insertStringAfterSearch(
    std::forward_list<std::string>& flist,
    const std::string& searchStr,
    const std::string& insertionStr,
    size_t maxInsertions,
    DatabaseInterface* db) {

    static constexpr size_t maxLength = 100;
    std::mutex dbMutex;

    {
        std::lock_guard<std::mutex> lock(listMutex);

        bool inserted = false;
        auto it = flist.before_begin();
        for (auto currentIt = flist.begin(); currentIt != flist.end() && !inserted; ++currentIt) {
            if (*it == searchStr || std::distance(flist.before_begin(), it) + 1 >= maxInsertions) {
                flist.insert_after(it, insertionStr.substr(0, maxLength));
                inserted = true;
            }
            if (!inserted) {
                ++it; // Move iterator forward
            }
        }

        if (!inserted) {
            flist.push_back(insertionStr.substr(0, maxLength));
        }

        for (auto& str : flist) {
            if (str.length() > maxLength) {
                str = str.substr(0, maxLength);
            }
        }
    }

    // Save operation with thread safety
    std::lock_guard<std::mutex> dbLock(dbMutex);
    if (db) {
        for (const auto& item : flist) {
            try {
                db->save(item);
