using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class SecureMessageProcessor : IDisposable
{
    private readonly ConcurrentDictionary<string, string> _cache = new();
    private readonly object _lock = new();
    private static readonly Timer _cacheCleanerTimer;

    private readonly ILogger _logger; // Assuming an external logging interface is provided

    public SecureMessageProcessor(ILogger logger)
    {
        _logger = logger;
        var cacheTTL = TimeSpan.FromMinutes(5);
        _cacheCleanerTimer = new Timer(ClearCache, null, cacheTTL, cacheTTL);
    }

    private void ClearCache(object state)
    {
        lock (_lock)
        {
            var now = DateTime.UtcNow;
            foreach (var key in _cache.Keys)
            {
                if (DateTime.TryParse(key, out var entryTime) && now - entryTime > TimeSpan.FromMinutes(5))
                {
                    _cache.TryRemove(key, out _);
                }
            }
        }
    }

    public string DecryptMessage(string base64EncodedEncryptedMessage, byte[] key, byte[] iv)
    {
        ValidateKeyAndIV(key, iv);

        var cacheKey = $"{base64EncodedEncryptedMessage}:{Convert.ToBase64String(key)}:{Convert.ToBase64String(iv)}";

        if (_cache.TryGetValue(cacheKey, out var cachedDecryption))
        {
            return cachedDecryption;
        }

        try
        {
            using var aes = new AesManaged { Key = key, IV = iv };
            using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            var encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);
            using var msDecrypt = new MemoryStream(encryptedBytes);
            using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            using var srDecrypt = new StreamReader(csDecrypt);

            var decryptedText = srDecrypt.ReadToEnd();

            _cache[cacheKey] = $"{DateTime.UtcNow}: {decryptedText}";

            return decryptedText;
        }
        catch (Exception ex)
        {
            _logger.LogError($"Decryption failed: {ex.Message}");
            throw new InvalidOperationException("Failed to decrypt the message.", ex);
        }
    }

    public string EncryptMessage(string plainText, byte[] key, byte[] iv)
    {
        ValidateKeyAndIV(key, iv);

        try
        {
            using var aes = new AesManaged { Key = key, IV = iv };
            using var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            using var msEncrypt = new MemoryStream();
            using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
            {
                using var swEncrypt = new StreamWriter(csEncrypt);
                swEncrypt.Write(plainText);
            }

            return Convert.ToBase64String(msEncrypt.ToArray());
        }
        catch (Exception ex)
        {
            _logger.LogError($"Encryption failed: {ex.Message}");
            throw new InvalidOperationException("Failed to encrypt the message.", ex);
        }
    }

    private void ValidateKeyAndIV(byte[] key, byte[] iv)
    {
        if (key == null || iv == null)
            throw new ArgumentException("Key and IV must not be null.");

        if (key.Length != 24 && key.Length != 32) // Triple DES or AES
            throw new ArgumentException("Invalid key length.");

        if (iv.Length != 16)
            throw new ArgumentException("IV must be 128 bits long.");
    }

    public void Dispose()
    {
        _cacheCleanerTimer.Dispose();
    }

    private class DummyLogger : ILogger
    {
        public void LogError(string message) => Console.WriteLine($"ERROR: {message}");
    }
}

public interface ILogger
{
    void LogError(string message);
}
