from flask import Flask, jsonify, request, g
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from dotenv import load_dotenv
import os
import logging
import requests
from requests_oauthlib import OAuth2Session
from oauthlib.oauth2 import TokenExpiredError

# Load environment variables
load_dotenv()

app = Flask(__name__)
limiter = Limiter(
    key_func=get_remote_address,
    default_limits=["200 per day", "50 per hour"]
)

# Configurations based on environment
if os.getenv('FLASK_ENV') == 'development':
    app.config['DEBUG'] = True
else:
    app.config['DEBUG'] = False

# OAuth 2.0 Configuration
oauth_config = {
    'client_id': os.getenv('OAUTH_CLIENT_ID'),
    'client_secret': os.getenv('OAUTH_CLIENT_SECRET'),
    'authorization_base_url': os.getenv('OAUTH_AUTH_URL'),
    'token_url': os.getenv('OAUTH_TOKEN_URL')
}

def get_oauth_session(token=None):
    """Create an OAuth2 session and handle token refreshing."""
    session = OAuth2Session(
        oauth_config['client_id'],
        token=token,
    )

    try:
        # Automatically refresh the access token if expired
        session.refresh_token(oauth_config['token_url'], 
                              client_secret=oauth_config['client_secret'])
    except TokenExpiredError:
        logging.warning("Token expired. Attempting to refresh.")
        session.fetch_token(
            oauth_config['token_url'],
            client_id=oauth_config['client_id'],
            client_secret=oauth_config['client_secret']
        )

    return session

@app.route('/api/resource')
@limiter.limit('10 per minute', scope='standard_user')  # Example of role-based limiting
def get_resource():
    user_role = request.headers.get('User-Role', 'standard_user')

    if user_role == 'admin':
        limit_scope = 'admin'
    else:
        limit_scope = 'standard_user'

    @limiter.limit(f'5 per minute', scope=limit_scope)
    def _get_resource():
        session = get_oauth_session()
        response = session.get('https://api.example.com/resource')

        if response.status_code == 200:
            return jsonify(response.json())
        else:
            raise Exception("API Error", response.text)

    try:
        return _get_resource()
    except requests.exceptions.Timeout as e:
        app.logger.error(f"Timeout error: {e}")
        return jsonify({"error": "Request timed out"}), 504
    except TokenExpiredError:
        return jsonify({"error": "Access token expired. Please re-authenticate."}), 401
    except Exception as e:
        app.logger.exception("Unhandled exception occurred")
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    # Configure logging based on environment
    if app.config['DEBUG']:
        logging.basicConfig(level=logging.DEBUG)
    else:
        logging.basicConfig(filename='app.log', level=logging.INFO)

    app.run()

# Dependency installation script (not part of the application itself)
