using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using CloudStorageSDK; // Placeholder for actual cloud storage SDK

public class DecryptionAndUploadService
{
    private readonly ILogger<DecryptionAndUploadService> _logger;

    public DecryptionAndUploadService(ILogger<DecryptionAndUploadService> logger)
    {
        _logger = logger;
    }

    public async Task DecryptAndUploadAsync(string filePath, string bucketName, byte[] key, byte[] iv, string paddingScheme, IDictionary<string, string> metadataTags = null)
    {
        ValidateKeyIV(key, iv);

        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = key;
                aesAlg.IV = iv;

                PaddingMode mode = GetPaddingMode(paddingScheme);
                aesAlg.Padding = mode;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                {
                    using (CryptoStream cryptoStream = new CryptoStream(fileStream, decryptor, CryptoStreamMode.Read))
                    {
                        await ProcessAndUploadFileAsync(cryptoStream, bucketName, metadataTags);
                    }
                }
            }

            // Encrypt and store keys in hierarchical database
            StoreEncryptedKey(key);

        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error during decryption or upload.");
            throw;
        }
    }

    private void ValidateKeyIV(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 16 && key.Length != 24 && key.Length != 32)
            throw new ArgumentException("Invalid AES key length.");

        if (iv == null || iv.Length != 16)
            throw new ArgumentException("Invalid IV length for AES-CBC.");
    }

    private PaddingMode GetPaddingMode(string paddingScheme)
    {
        return paddingScheme switch
        {
            "PKCS7" => PaddingMode.PKCS7,
            "ANSIX923" => PaddingMode.AnsiX923,
            _ => PaddingMode.None, // NoPadding
        };
    }

    private async Task ProcessAndUploadFileAsync(Stream decryptedStream, string bucketName, IDictionary<string, string> metadataTags)
    {
        long fileSize = decryptedStream.Length;
        const int maxSinglePartSize = 5 * 1024 * 1024; // Example: 5MB
        bool isMultipartUpload = fileSize > maxSinglePartSize;

        if (isMultipartUpload)
            await MultipartUploadAsync(decryptedStream, bucketName, metadataTags);
        else
            await SinglePartUploadAsync(decryptedStream, bucketName, metadataTags);
    }

    private async Task SinglePartUploadAsync(Stream fileStream, string bucketName, IDictionary<string, string> metadataTags)
    {
        // Implement single part upload logic using cloud storage SDK
        _logger.LogInformation("Uploading as single part.");
        await Task.CompletedTask; // Placeholder for actual upload logic
    }

    private async Task MultipartUploadAsync(Stream fileStream, string bucketName, IDictionary<string, string> metadataTags)
    {
        const int chunkSize = 4 * 1024 * 1024; // Example: 4MB
        long position = 0;

        using (MemoryStream buffer = new MemoryStream())
        {
            byte[] chunkBuffer = new byte[chunkSize];
            int bytesRead;

            while ((bytesRead = await fileStream.ReadAsync(chunkBuffer, 0, chunkBuffer.Length)) > 0)
            {
                buffer.Write(chunkBuffer, 0, bytesRead);
                if (buffer.Position >= chunkSize)
                {
                    await UploadChunkAsync(buffer.ToArray(), bucketName, position, metadataTags);
                    position += chunkSize;
                    buffer.SetLength(0); // Reset memory stream
                }
            }

