Below is an example C++ program using AWS SDK for C++ to achieve the described functionality. This code demonstrates reading from S3, multi-threaded processing, and storing results in a simple SQLite database.

```cpp
#include <aws/core/Aws.h>
#include <aws/s3/S3Client.h>
#include <aws/s3/model/GetObjectRequest.h>
#include <sqlite3.h>
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <future>

const int MAX_THREADS = 4;

std::mutex db_mutex;

void processLine(const std::string& line, sqlite3* db) {
    std::istringstream ss(line);
    std::string value;
    std::vector<double> numbers;

    while (std::getline(ss, value, ',')) {
        try {
            numbers.push_back(std::stod(value));
        } catch (...) {}
    }

    if (numbers.size() >= 2) {
        double avg = (numbers[numbers.size()-1] + numbers[numbers.size()-2]) / 2.0;

        db_mutex.lock();
        char* errMsg = nullptr;
        std::string sql = "INSERT INTO Averages (average) VALUES (" + std::to_string(avg) + ");";
        if (sqlite3_exec(db, sql.c_str(), nullptr, nullptr, &errMsg) != SQLITE_OK) {
            std::cerr << "SQLite error: " << errMsg << std::endl;
            sqlite3_free(errMsg);
        }
        db_mutex.unlock();
    }
}

void processFile(const std::string& filePath, sqlite3* db) {
    std::ifstream file(filePath);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    std::vector<std::future<void>> futures;
    std::string line;

    while (std::getline(file, line)) {
        futures.emplace_back(std::async(std::launch::async, processLine, line, db));
        if (futures.size() >= MAX_THREADS) {
            for (auto& future : futures) {
                future.get();
            }
            futures.clear();
        }
    }

    for (auto& future : futures) {
        future.get();
    }
}

int main(int argc, char** argv) {
    if (argc != 5) {
        std::cerr << "Usage: <program> <bucket_name> <access_key> <secret_key> <output_db_path>\n";
        return 1;
    }

    Aws::SDKOptions options;
    Aws::InitAPI(options);

    auto bucketName = argv[1];
    auto accessKey = argv[2];
    auto secretKey = argv[3];
    auto outputDbPath = argv[4];

    Aws::Client::ClientConfiguration config;
    config.region = "us-west-2";
    Aws::Auth::AWSCredentials credentials(accessKey, secretKey);

    Aws::S3::S3Client s3_client(credentials, config);

    Aws::S3::Model::GetObjectRequest request;
    request.SetBucket(bucketName);
    request.SetKey("largefile.txt");

    auto outcome = s3_client.GetObject(request);

    if (!outcome.IsSuccess()) {
        std::cerr << "Failed to get object from S3: " << outcome.GetError().GetMessage() << std::endl;
        Aws::ShutdownAPI(options);
        return 1;
    }

    std::ofstream localFile("largefile.txt");
    localFile << outcome.GetResultWithOwnership().GetBody().rdbuf();
    localFile.close();

    sqlite3* db;
    if (sqlite3_open(outputDbPath.c_str(), &db) != SQLITE_OK) {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return 1;
    }

    char* errMsg = nullptr;
    const char* sqlCreateTable = 
        "CREATE TABLE IF NOT EXISTS Averages ("
        "id INTEGER PRIMARY KEY AUTOINCREMENT, "
        "average REAL);";

    if (sqlite3_exec(db, sqlCreateTable, nullptr, nullptr, &errMsg) != SQLITE_OK) {
        std::cerr << "SQL error: " << errMsg << std::endl;
        sqlite3_free(errMsg);
        return 1;
    }

    processFile("largefile.txt", db);

    sqlite3_close(db);
    Aws::ShutdownAPI(options);

    return 0;
}
