class TcpClient {
private:
    asio::io_context io_context_;
    std::unordered_map<std::string, tcp::socket> connections_;
    ConfigManager config_manager_;
    std::vector<std::thread> thread_pool_;
    size_t pool_size_;

public:
    TcpClient(size_t pool_size) : pool_size_(pool_size) {
        for (size_t i = 0; i < pool_size_; ++i) {
            thread_pool_.emplace_back([this] { io_context_.run(); });
        }
    }

    ~TcpClient() {
        io_context_.stop();
        for (auto& t : thread_pool_) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

    void connectToServers() {
        auto addresses = config_manager_.getServerAddresses();

        for (const auto& address : addresses) {
            try {
                tcp::resolver resolver(io_context_);
                asio::connect(tcp::socket(io_context_), resolver.resolve(address, "http"));
                std::cout << "Connected to: " << address << std::endl;
            } catch (std::exception& e) {
                std::cerr << "Connection failed for: " << address << ", Error: " << e.what() << std::endl;
            }
        }
    }

    void makeRequest(const std::string& server, const std::string& request_data) {
        try {
            if (connections_.find(server) == connections_.end()) {
                tcp::resolver resolver(io_context_);
                auto endpoints = resolver.resolve(server, "http");
                asio::connect(connections_[server], endpoints);
            }

            boost::asio::write(connections_[server], boost::asio::buffer(request_data));
        } catch (std::exception& e) {
            std::cerr << "Request failed for: " << server << ", Error: " << e.what() << std::endl;
        }
    }
};

