class ConfigLoader {
public:
    json loadConfig(const std::string& filePath) {
        std::ifstream configFile(filePath);
        if (!configFile.is_open()) {
            throw std::runtime_error("Could not open config file");
        }
        json config;
        configFile >> config;
        return config;
    }
};

class DataProcessor {
public:
    DataProcessor(const json& config)
        : maxConcurrentTasks(config["max_concurrent_tasks"].get<int>()) {}

    void processFiles(const std::vector<std::string>& filePaths) {
        std::vector<std::future<void>> futures;

        for (const auto& path : filePaths) {
            if (futures.size() >= maxConcurrentTasks) {
                for (auto&& future : futures)
                    future.get();
                futures.clear();
            }
            futures.emplace_back(std::async(std::launch::async, &DataProcessor::processFile, this, path));
        }

        for (auto&& future : futures)
            future.get();
    }

private:
    int maxConcurrentTasks;

    void processFile(const std::string& filePath) {
        // Decompress file
        std::vector<char> decompressedData = decompressFile(filePath);

        // Parse data according to rules from config
        json parsedData = parseData(decompressedData);

        // Encrypt and write the transformed data
        encryptAndWrite(parsedData, filePath + ".enc");

        logStatus("Processed file: " + filePath);
    }

    std::vector<char> decompressFile(const std::string& filePath) {
        // Use zlib or other library to handle decompression
        std::ifstream inFile(filePath, std::ios::binary);
        if (!inFile.is_open()) {
            throw std::runtime_error("Failed to open file for reading: " + filePath);
        }

        // Decompress logic (pseudo-code)
        std::vector<char> compressedData((std::istreambuf_iterator<char>(inFile)), std::istreambuf_iterator<char>());
        std::vector<char> decompressedData;

        // Assuming the use of zlib or similar
        int ret, flush = Z_FINISH;
        unsigned have;
        z_stream strm;
        static const unsigned CHUNK = 16384;
        char out[CHUNK];

        if (inflateInit(&strm) != Z_OK)
            throw std::runtime_error("Failed to initialize decompression");

        strm.avail_in = compressedData.size();
        strm.next_in = reinterpret_cast<Bytef*>(const_cast<char*>(compressedData.data()));

        do {
            strm.avail_out = CHUNK;
            strm.next_out = reinterpret_cast<Bytef*>(out);
            ret = inflate(&strm, flush);
            assert(ret != Z_STREAM_ERROR);
            switch (ret) {
                case Z_NEED_DICT:
                    ret = Z_DATA_ERROR;     // And fall through
                case Z_DATA_ERROR:
                case Z_MEM_ERROR:
                    (void)inflateEnd(&strm);
                    throw std::runtime_error("Decompression failed");
            }
            have = CHUNK - strm.avail_out;
            decompressedData.insert(decompressedData.end(), out, out + have);

        } while (strm.avail_out == 0);

        inflateEnd(&strm);

        return decompressedData;
    }

    json parseData(const std::vector<char>& data) {
        // Implement parsing logic according to rules
        // For example, using JSON or binary format conversion
        json parsedJson = json::parse(data.data()); // Assuming JSON for simplicity
        return parsedJson;
    }

    void encryptAndWrite(const json& data, const std::string& outputPath) {
        // Use OpenSSL or similar to handle encryption
        unsigned char key[AES_BLOCK_SIZE] = "0123456789abcdef";  // Example key
        unsigned char iv[AES_BLOCK_SIZE] = "abcdef9876543210";   // Initialization vector

        AES_KEY encryptKey;
        if (AES_set_encrypt_key(key, 128, &encryptKey) < 0)
            throw std::runtime_error("Failed to set encryption key");

        std::string encryptedData = data.dump(); // Convert json to string
        std::vector<unsigned char> cipherText(encryptedData.size() + AES_BLOCK_SIZE);

        int numBytesEncrypted = 0;
        AES_cbc_encrypt(reinterpret_cast<const unsigned char*>(encryptedData.data()), 
                        reinterpret_cast<unsigned char*>(&cipherText[0]), encryptedData.size(), &encryptKey, iv, AES_ENCRYPT);

        std::ofstream outFile(outputPath, std::ios::binary);
        if (!outFile.is_open()) {
            throw std::runtime_error("Failed to open output file: " + outputPath);
        }
        outFile.write(reinterpret_cast<char*>(cipherText.data()), cipherText.size());
    }

    void logStatus(const std::string& message) {
        // Use cURL or similar for logging service integration
        CURL* curl = curl_easy_init();
        if (curl) {
            struct curl_slist *headers = nullptr;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, message.c_str());

            CURLcode res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                std::cerr << "CURL failed with error: " << curl_easy_strerror(res) << '\n';
            }
            curl_easy_cleanup(curl);
        }
    }
};

