#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <time.h>

// External logging system interface
void log_message(const char *message) {
    printf("%s\n", message); // Replace with actual logging implementation
}

typedef struct {
    sem_t semaphore;
    int timeout; // Timeout in milliseconds for acquire operation
} Semaphore;

Semaphore* create_semaphore(int initial_value, int timeout) {
    if (initial_value < 0 || timeout < 0) {
        log_message("Invalid semaphore parameters");
        return NULL;
    }

    Semaphore *sem = malloc(sizeof(Semaphore));
    if (!sem) {
        log_message("Memory allocation failed for semaphore");
        return NULL;
    }

    sem_init(&sem->semaphore, 0, initial_value);
    sem->timeout = timeout;

    log_message("Semaphore created successfully");
    return sem;
}

int acquire_semaphore(Semaphore *sem) {
    if (!sem) {
        log_message("Invalid semaphore pointer");
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_nsec += (sem->timeout % 1000) * 1000000; // Convert ms to ns
    ts.tv_sec += sem->timeout / 1000;

    int result = sem_timedwait(&sem->semaphore, &ts);
    if (result == -1 && errno != ETIMEDOUT) {
        log_message("Semaphore acquire failed");
    }

    return result;
}

int release_semaphore(Semaphore *sem) {
    if (!sem) {
        log_message("Invalid semaphore pointer");
        return -1;
    }

    int result = sem_post(&sem->semaphore);
    if (result != 0) {
        log_message("Semaphore release failed");
    }

    return result;
}

void delete_semaphore(Semaphore **sem) {
    if (!sem || !*sem) {
        log_message("Invalid semaphore pointer for deletion");
        return;
    }

    sem_destroy(&(*sem)->semaphore);
    free(*sem);
    *sem = NULL;

    log_message("Semaphore deleted successfully");
}

// Example usage and unit test function
void *thread_function(void *arg) {
    Semaphore *sem = (Semaphore *)arg;

    if (acquire_semaphore(sem) == 0) {
        printf("Thread acquired semaphore\n");
        release_semaphore(sem);
    } else {
        printf("Thread failed to acquire semaphore\n");
    }

    return NULL;
}

void test_semaphore() {
    int initial_value = 1;
    int timeout = 1000; // 1 second
    Semaphore *sem = create_semaphore(initial_value, timeout);

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, thread_function, sem);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    delete_semaphore(&sem);
}

int main() {
    test_semaphore();
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread` and semaphores for thread synchronization.
- **Error Handling**: Checks for errors during semaphore operations and logs messages.
- **Race Conditions**: Managed using POSIX semaphores, which are atomic.
- **Low-Latency Optimization**: Uses `sem_timedwait` to minimize wait times.
- **Configuration**: Allows setting a timeout for acquiring the semaphore.
- **Logging Integration**: Placeholder function `log_message` is used for logging.
- **Resource Management**: Ensures proper cleanup with `delete_semaphore`.
- **User Interface**: Simple API functions (`create_semaphore`, `acquire_semaphore`, etc.).
- **Unit Tests**: Basic test in `test_semaphore` to demonstrate usage.

