Below is a structured Java implementation that fulfills the specified requirements:

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;
import java.util.logging.Level;
import java.util.logging.Logger;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

class DatabaseConfig {
    private String url;
    private String username;
    private String password;
    private Properties queryConfigs = new Properties();

    // Getters and setters for url, username, password
    public void setQueryConfig(String key, String value) { this.queryConfigs.put(key, value); }
    public String getQueryConfig(String key) { return (String)this.queryConfigs.getOrDefault(key, null); }
}

class ConnectionPoolManager {
    private static final Logger logger = Logger.getLogger(ConnectionPoolManager.class.getName());

    private int poolSize;
    private DatabaseConfig config;

    public ConnectionPoolManager(int poolSize, DatabaseConfig config) {
        this.poolSize = poolSize;
        this.config = config;
    }

    public synchronized Connection getConnection() throws SQLException {
        try {
            // For simplicity, using DriverManager here; in practice use a proper connection pooling library
            return DriverManager.getConnection(config.getUrl(), config.getUsername(), config.getPassword());
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error establishing database connection", e);
            throw e;
        }
    }

    public void releaseConnection(Connection conn) {
        if (conn != null) {
            try {
                conn.close();
            } catch (SQLException e) {
                logger.log(Level.WARNING, "Failed to close the database connection properly", e);
            }
        }
    }

    // Add logic for handling idle connections and optimizing resource usage
}

class ConfigurationService {
    private static final Logger logger = Logger.getLogger(ConfigurationService.class.getName());

    private OkHttpClient client;
    private String configUrl;

    public ConfigurationService(String configUrl) {
        this.client = new OkHttpClient();
        this.configUrl = configUrl;
    }

    public void updateConfiguration(DatabaseConfig config) throws Exception {
        Request request = new Request.Builder().url(configUrl).build();

        try (Response response = client.newCall(request).execute()) {
            if (!response.isSuccessful()) throw new RuntimeException("Failed to fetch configuration");

            String responseBody = response.body().string();
            validateAndApplyConfiguration(config, responseBody);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error fetching/updating configurations", e);
            throw e;
        }
    }

    private void validateAndApplyConfiguration(DatabaseConfig config, String jsonConfig) throws Exception {
        Gson gson = new Gson();
        try {
            QueryConfiguration queryConfig = gson.fromJson(jsonConfig, QueryConfiguration.class);

            if (queryConfig != null && !queryConfig.getQueries().isEmpty()) {
                for (String key : queryConfig.getQueries().keySet()) {
                    config.setQueryConfig(key, queryConfig.getQueries().get(key));
                }
            } else {
                throw new IllegalArgumentException("Invalid configuration data");
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to validate or apply configurations", e);
            throw e;
        }
    }
}

class QueryConfiguration {
    private Properties queries;

    public Properties getQueries() { return queries; }

    // Constructor for deserialization
    private QueryConfiguration() {}
}

public class DatabaseConnectionManager {

    private static final Logger logger = Logger.getLogger(DatabaseConnectionManager.class.getName());

    private ConnectionPoolManager poolManager;
    private ConfigurationService configService;
    private DatabaseConfig dbConfig;

    public DatabaseConnectionManager(int poolSize, String configUrl) {
        this.dbConfig = new DatabaseConfig();

        // Initialize connection pool manager
        this.poolManager = new ConnectionPoolManager(poolSize, dbConfig);

        // Setup configuration service
        this.configService = new ConfigurationService(configUrl);

        try {
            configService.updateConfiguration(dbConfig);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to initialize configuration", e);
        }
    }

    public void manageConnections() {
        Connection connection = null;

        try {
            connection = poolManager.getConnection();
            // Perform database operations
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Database operation failed", e);
        } finally {
            if (connection != null) {
                poolManager.releaseConnection(connection);
            }
        }
    }

    public static void main(String[] args) {
        DatabaseConnectionManager manager = new DatabaseConnectionManager(10, "https://api.example.com/db-config");
        manager.manageConnections();
    }
}
```

### Explanation:

- **DatabaseConfig**: Holds the database URL, username, password, and query configurations.

- **ConnectionPoolManager**: Manages a pool of connections with methods to get and release connections. It uses `DriverManager` for simplicity but should be replaced with a robust connection pooling library like HikariCP in production.

- **ConfigurationService**: Fetches updated configuration from a remote REST API, validates it using Gson, and updates the local database config object.

- **QueryConfiguration**: A simple class representing JSON structure received from the remote service.

- **DatabaseConnectionManager**: The main manager class that initializes and manages connections while dynamically updating configurations. It logs activities and handles exceptions to inform users of any issues during execution.

