### Jenkinsfile (Jenkins Pipeline Configuration)
```groovy
pipeline {
    agent any

    environment {
        DOCKER_IMAGE = "myapp:${env.BUILD_ID}"
        KUBECONFIG = credentials('kubeconfig')
        GITHUB_TOKEN = credentials('github-token')
        API_KEYS = readJSON(file: 'api-keys.json')
    }

    stages {
        stage('Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/your-repo.git'
            }
        }

        stage('Build Docker Image') {
            parallel {
                stage('Service A') {
                    steps {
                        script {
                            docker.build("${env.DOCKER_IMAGE}-service-a", './serviceA')
                        }
                    }
                }
                stage('Service B') {
                    steps {
                        script {
                            docker.build("${env.DOCKER_IMAGE}-service-b", './serviceB')
                        }
                    }
                }
            }
        }

        stage('Push Docker Image') {
            steps {
                script {
                    docker.withRegistry('', 'docker-credentials-id') {
                        sh "docker push ${env.DOCKER_IMAGE}-service-a"
                        sh "docker push ${env.DOCKER_IMAGE}-service-b"
                    }
                }
            }
        }

        stage('Deploy to Kubernetes') {
            when {
                anyOf {
                    branch 'main'
                    environment name: 'DEPLOY_ENV', value: 'production'
                }
            }
            steps {
                script {
                    kubernetesApply(file: "k8s/development.yaml", kubeconfigId: "${env.KUBECONFIG}")
                    if (env.DEPLOY_ENV == 'testing') {
                        kubernetesApply(file: "k8s/testing.yaml", kubeconfigId: "${env.KUBECONFIG}")
                    }
                    if (env.DEPLOY_ENV == 'production') {
                        kubernetesApply(file: "k8s/production.yaml", kubeconfigId: "${env.KUBECONFIG}")
                    }
                }
            }
        }

        stage('Monitor and Rollback') {
            steps {
                script {
                    def status = monitorDeployment()
                    if (status != 'healthy') {
                        rollbackDeployment()
                    }
                }
            }
        }
    }

    post {
        always {
            cleanWs()
        }
    }
}

def monitorDeployment() {
    // Implement health checks and return deployment status
    // For example, using kubectl and checking pod statuses or logs
    return 'healthy'  // or 'unhealthy'
}

def rollbackDeployment() {
    // Use Kubernetes commands to roll back the deployment if unhealthy
    sh "kubectl rollout undo -f k8s/production.yaml"
}
```

