Below is a C function that addresses the requirements outlined in your task. This implementation includes memory allocation and initialization for storing records of long-term offset values with associated integer keys. It ensures thread safety using mutexes, integrates with an external database API, retrieves initial random values from a configuration file, and incorporates logging and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

// Assume these are provided by the external libraries
extern int db_api_initialize();
extern int db_api_store(int key, long offset);
extern int db_api_retrieve(int key, long *offset);

// Define structure to hold record data
typedef struct {
    int key;
    long offset;
} Record;

// Configuration constants
#define MAX_RECORDS 1000000
#define KEY_RANGE_START 1
#define KEY_RANGE_END 10000

// Global variables and mutex for thread safety
Record records[MAX_RECORDS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Logger function prototype
void log_message(const char *message);

// Function to initialize records from a configuration file
int initialize_records_from_config(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        log_message("Error opening config file.");
        return errno;
    }

    srand(time(NULL));  // Seed random number generator

    int key;
    long offset;
    while (fscanf(file, "%d %ld", &key, &offset) == 2) {
        pthread_mutex_lock(&lock);
        if (key >= KEY_RANGE_START && key <= KEY_RANGE_END) {
            records[key - KEY_RANGE_START].key = key;
            records[key - KEY_RANGE_START].offset = offset;
        }
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return 0;
}

// Function to allocate and initialize records
int allocate_and_initialize_records(const char *config_file) {
    if (db_api_initialize() != 0) {
        log_message("Failed to initialize database API.");
        return errno;
    }

    if (initialize_records_from_config(config_file) != 0) {
        log_message("Error initializing records from config file.");
        return errno;
    }

    for (int i = 0; i < MAX_RECORDS; ++i) {
        int key = rand() % (KEY_RANGE_END - KEY_RANGE_START + 1) + KEY_RANGE_START;

        pthread_mutex_lock(&lock);
        if (records[key - KEY_RANGE_START].key == 0) { // Uninitialized record
            records[key - KEY_RANGE_START].key = key;
            records[key - KEY_RANGE_START].offset = rand(); // Random initial offset

            // Store to database
            if (db_api_store(key, records[key - KEY_RANGE_START].offset) != 0) {
                log_message("Failed to store record in database.");
                pthread_mutex_unlock(&lock);
                return errno;
            }
        }
        pthread_mutex_unlock(&lock);
    }

    log_message("Records allocated and initialized successfully.");
    return 0;
}

// Logger function implementation
void log_message(const char *message) {
    FILE *log_file = fopen("system_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
```

### Key Points:
- **Thread Safety**: The function uses a mutex to ensure that concurrent access by multiple threads is handled correctly.
- **Database Integration**: It interfaces with an external database API for storing and retrieving records.
- **Configuration File Reading**: Retrieves initial values from a configuration file.
- **Logging**: Logs messages to help in troubleshooting and performance analysis.
- **Error Handling**: Checks return codes and uses `errno` for error reporting.

