```rust
use std::time::{Duration, Instant};
use serde_json::Value;

pub fn db_command_executor(root: Vec<u8>, selector: &str, test_func: Option<fn(&String) -> String>) -> Result<Vec<String>, String> {
    let start_time = Instant::now();

    // Convert byte array to string
    if let Ok(input_str) = String::from_utf8(root) {
        // Parse input string as JSON
        let json_value: Value = serde_json::from_str(&input_str).map_err(|e| e.to_string())?;

        // Simulate DOM traversal (in practice, use a suitable Rust library)
        let result = traverse_and_execute(&json_value, selector, test_func);

        if start_time.elapsed() > Duration::new(1, 0) {
            return Err("Operation timed out".to_string());
        }

        Ok(result)
    } else {
        Err("Invalid byte array input".to_string())
    }
}

fn traverse_and_execute(json_value: &Value, selector: &str, test_func: Option<fn(&String) -> String>) -> Vec<String> {
    // Implement DOM traversal and command execution logic
    let mut results = vec![];

    match json_value {
        Value::Object(obj) => {
            for (key, value) in obj {
                if key == selector {
                    if let Some(func) = test_func {
                        results.push(func(&key.to_string()));
                    }
                }

                traverse_and_execute(value, selector, test_func.clone(), &mut results);
            }
        },
        _ => {}
    }

    results
}
```

