pub mod db_command_executor;

#[no_mangle]
pub extern "C" fn execute_db_command(root: Vec<u8>, selector: *const u8, len: usize, test_func: Option<extern "C" fn(&str) -> String>) -> Result<Vec<String>, &'static str> {
    let selector = unsafe { std::slice::from_raw_parts(selector as *const u8, len) };
    let selector_str = match std::str::from_utf8(selector) {
        Ok(v) => v,
        Err(_) => return Err("Invalid UTF-8 sequence"),
    };

    db_command_executor::db_command_executor(root, selector_str, test_func.map(|f| Box::new(f) as Box<dyn Fn(&String) -> String>))
}
