void log_message(int severity, const char* format, ...) {
    va_list args;
    va_start(args, format);

    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);

    if (severity == logging::trivial::error) {
        BOOST_LOG_SEV(logger, logging::trivial::error) << buffer;
    } else {
        std::ostringstream oss;
        oss << boost::posix_time::second_clock::local_time() << " - ";
        oss << buffer;
        BOOST_LOG_SEV(logger, logging::trivial::debug) << oss.str();
    }

    va_end(args);
}

