```python
import asyncio
import aiohttp
from collections import defaultdict

class PaymentAPI:
    def __init__(self, base_url):
        self.base_url = base_url
        self.session = None

    async def fetch_transaction(self, transaction_id):
        if not self.session:
            self.session = aiohttp.ClientSession()

        url = f"{self.base_url}/transactions/{transaction_id}"
        try:
            async with self.session.get(url) as response:
                if response.status == 200:
                    return await response.json()
                elif response.status in {429, 500}:
                    raise Exception("Rate limit hit or server error")
                else:
                    response.raise_for_status()
        except aiohttp.ClientError as e:
            print(f"Network error: {e}")
            return None

    async def close(self):
        if self.session:
            await self.session.close()

async def process_transactions(api, transactions, batch_size=1000):
    user_totals = defaultdict(float)

    for i in range(0, len(transactions), batch_size):
        batch = transactions[i:i + batch_size]
        tasks = [process_transaction(user_totals, api, txn) for txn in batch]
        await asyncio.gather(*tasks)

    return dict(user_totals)

async def process_transaction(user_totals, api, transaction):
    retries = 3
    delay = 1

    while retries > 0:
        details = await api.fetch_transaction(transaction['id'])

        if details:
            user_id = details.get('user_id')
            amount = details.get('amount', 0)

            if isinstance(user_id, int) and isinstance(amount, (int, float)):
                user_totals[user_id] += amount
            else:
                print(f"Invalid transaction data: {details}")
        else:
            retries -= 1
            await asyncio.sleep(delay)
            delay *= 2

    if retries == 0:
        print(f"Failed to process transaction {transaction['id']} after multiple attempts")

async def main():
    api = PaymentAPI("https://api.mockpaymentprocessor.com")

    # Sample dataset
    transactions = [{'id': i} for i in range(1, 10001)]

    try:
        result = await process_transactions(api, transactions)
        print(result)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        await api.close()

# Run the main function
if __name__ == "__main__":
    asyncio.run(main())
```

This code defines a `PaymentAPI` class to handle interactions with an external payment processing API. The main transaction processing is split into smaller batches, and transactions are processed concurrently using asynchronous tasks. Error handling includes retries for failed network requests, logging for invalid data, and careful resource management by closing the HTTP session after use.

