```cpp
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <cstring>

// Error codes
#define AES_SUCCESS 0
#define AES_ERR_NULL -1
#define AES_ERR_KEYGEN -2
#define AES_ERR_CIPHER_INIT -3

EVP_CIPHER_CTX* aes_encrypt_init(
    const unsigned char* key, int key_len,
    const unsigned char* iv, int iv_len,
    const unsigned char* password, int password_len,
    enum EVP_CipherType cipher_type,
    enum KDFType kdf_type,
    enum PaddingScheme padding_scheme) {

    if (!key || !password) return nullptr;

    // Key derivation
    unsigned char derived_key[EVP_MAX_KEY_LENGTH];
    unsigned char salt[16];  // Example salt size
    RAND_bytes(salt, sizeof(salt));
    int kdf_len = EVP_MAX_KEY_LENGTH;

    switch (kdf_type) {
        case PBKDF2:
            if (!PKCS5_PBKDF2_HMAC(password, password_len, 
                                   salt, sizeof(salt), 10000, 
                                   EVP_sha256(), key_len, derived_key)) {
                return nullptr; // Handle error
            }
            break;
        case HKDF:
            if (!HKDF_expand(EVP_sha256(), password, password_len,
                             salt, sizeof(salt),
                             derived_key, key_len)) {
                return nullptr; // Handle error
            }
            break;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return nullptr;

    switch (cipher_type) {
        case AES_ECB:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, derived_key, iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return nullptr;
            }
            break;
        case AES_CBC:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return nullptr;
            }
            break;
        case AES_GCM:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, derived_key, iv)) {
                EVP_CIPHER_CTX_free(ctx);
                return nullptr;
            }
            break;
    }

    switch (padding_scheme) {
        case PKCS7:
            EVP_CIPHER_CTX_set_padding(ctx, 1); // Enable padding
            break;
        case ANSI_X923:
        case ISO_10126:
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_PKCS7_SET_PADDING, 
                               padding_scheme == ANSI_X923 ? 2 : 3, NULL);
            break;
    }

    return ctx;  // Caller is responsible for freeing the context with EVP_CIPHER_CTX_free
}
```

