    public async Task<byte[]> DecryptAndUpdateUserProfile(byte[] ciphertext, string ivBase64, int userId)
    {
        ValidateUserId(userId);

        byte[] decryptedText = DecryptAesCbc(ciphertext, _encryptionKeyBase64, ivBase64);

        var userProfileUpdates = ExtractUserProfileUpdates(decryptedText);
        await UpdateUserProfilesConcurrently(userProfileUpdates);

        return decryptedText;
    }

    private void ValidateUserId(int userId)
    {
