            NewValues = update.FieldsToUpdate.Values
        };

        var jsonMessage = JsonConvert.SerializeObject(messageBody);
        var content = new StringContent(jsonMessage, Encoding.UTF8, "application/json");

        using var response = await _httpClient.PostAsync($"notify/{notificationType}", content);

        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError("Failed to send {NotificationType} notification for user ID {UserId}", notificationType, userId);
        }
    }

    private Dictionary<int, UserProfileUpdate> ExtractUserProfileUpdates(byte[] decryptedData)
    {
        // Example extraction logic
        return new Dictionary<int, UserProfileUpdate>
        {
            { 1, new UserProfileUpdate(new Dictionary<string, string>{{ "Email", "newemail@example.com" }}) }
        };
    }

