@RestController
class PokemonController {

    private final ClassProvider classProvider;
    private final ApiClient apiClient;
    private final CacheManager cacheManager;

    PokemonController(ClassProvider classProvider, ApiClient apiClient, CacheManager cacheManager) {
        this.classProvider = classProvider;
        this.apiClient = apiClient;
        this.cacheManager = cacheManager;
    }

    @GetMapping("/pokemon")
    public ResponseEntity<PokemonDetails> getPokemonDetails(@RequestParam int id) {
        try {
            String cacheKey = "Pokemon_" + id;
            PokemonDetails cachedData = cacheManager.get(cacheKey);
            if (cachedData != null) return ResponseEntity.ok(cachedData);

            List<String> weaknesses = apiClient.fetchWeaknesses(id).orElseGet(() -> fallbackFetchWeaknesses(id));
            EvolutionStages evolution = apiClient.fetchEvolution(id).orElseGet(() -> fallbackFetchEvolution(id));
            Habitat habitat = apiClient.fetchHabitat(id).orElseGet(() -> fallbackFetchHabitat(id));

            PokemonDetails details = new PokemonDetails(
                "Pokemon_" + id, 
                evolution.getCurrent().getName(), 
                weaknesses, 
                evolution.getNext(),
                habitat.getDescription()
            );

            cacheManager.put(cacheKey, details);
            return ResponseEntity.ok(details);

        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();
        }
    }
}

