```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR
} LogLevel;

LogLevel currentLogLevel = ERROR; // Default log level

// Mutex for thread-safe logging
static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void setLogLevel(LogLevel level) {
    currentLogLevel = level;
}

int shouldLog(LogLevel level) {
    return level >= currentLogLevel;
}

void logCondition(int condition, LogLevel level, const char *format, ...) {
    if (!condition || !shouldLog(level)) {
        return;
    }

    pthread_mutex_lock(&logMutex);

    // Maximum length for the log message
    size_t maxMessageLength = 1024;
    char *message = malloc(maxMessageLength);
    if (message == NULL) {
        pthread_mutex_unlock(&logMutex);
        fprintf(stderr, "Failed to allocate memory for log message\n");
        return;
    }

    va_list args;
    va_start(args, format);

    // Format the message with a limited buffer size
    vsnprintf(message, maxMessageLength, format, args);

    va_end(args);

    // Log the formatted message to stderr (or any other logging destination)
    fprintf(stderr, "[%s] %s\n", 
            level == DEBUG ? "DEBUG" : 
            level == INFO ? "INFO" :
            level == WARNING ? "WARNING" : "ERROR",
            message);

    free(message);
    pthread_mutex_unlock(&logMutex);
}
```

### Explanation:
- **LogLevel Enum**: Defines different logging levels.
- **currentLogLevel**: Stores the current log level, which can be set using `setLogLevel`.
- **shouldLog Function**: Determines if a given log level should be logged based on the current log level.
- **logCondition Function**: Logs a message only if the condition is met and the log level is appropriate. It uses variable arguments to format messages.
- **Thread Safety**: Uses a mutex (`pthread_mutex_t`) to ensure that logging from multiple threads does not cause data races.
- **Dynamic Memory Allocation**: Allocates memory for the formatted message, ensuring it doesn't exceed `maxMessageLength` to prevent buffer overflow.
- **Log Level Filtering**: Logs are printed only if their level is greater than or equal to the current log level.

