class LRUCache {
    private $capacity;
    private $cache;

    public function __construct($capacity = 1000) {
        $this->capacity = $capacity;
        $this->cache = [];
    }

    public function get($key) {
        if (!isset($this->cache[$key])) return null;

        // Move accessed key to the end
        unset($this->cache[$key]);
        $this->cache[$key] = array_pop($this->cache);

        return $this->cache[$key][1];
    }

    public function set($key, $value) {
        if (isset($this->cache[$key])) {
            // Remove existing
            unset($this->cache[$key]);
        } elseif (count($this->cache) >= $this->capacity) {
            // LRU eviction: remove the first element
            array_shift($this->cache);
        }

        // Add to cache
        $this->cache[$key] = [time(), $value];
    }

    public function has($key) {
        return isset($this->cache[$key]);
    }
}

