from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import redis
import requests
import time

app = Flask(__name__)
db = SQLAlchemy(app)
cache = redis.StrictRedis(host='localhost', port=6379, db=0)

# Models
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80))
    email = db.Column(db.String(120), unique=True)
    address = db.relationship('Address', backref='user', uselist=False)

class Address(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    street = db.Column(db.String(120))
    city = db.Column(db.String(80))
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'))

# Utility functions
def fetch_user_from_db(user_id):
    return User.query.get(user_id)

def update_cache(user_id, data):
    cache.set(f"user:{user_id}", json.dumps(data), ex=3600)

def invalidate_cache(user_id):
    cache.delete(f"user:{user_id}")

def exponential_backoff(retries):
    return min(2 ** retries, 60)

# API Endpoints
@app.route('/update_profile/<int:user_id>', methods=['PATCH'])
def update_profile(user_id):
    try:
        user = fetch_user_from_db(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404

        data = request.get_json()

        # Handle nested updates
        if 'name' in data:
            user.name = data['name']
        if 'email' in data:
            user.email = data['email']
        if 'address' in data:
            address_data = data['address']
            if not user.address:
                user.address = Address()
            if 'street' in address_data:
                user.address.street = address_data['street']
            if 'city' in address_data:
                user.address.city = address_data['city']

        db.session.commit()

        # Invalidate cache
        invalidate_cache(user_id)

        update_cache(user_id, user.to_dict())

        return jsonify({"message": "Profile updated successfully"}), 200

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/update_profiles', methods=['PATCH'])
def update_multiple_profiles():
    try:
        data = request.get_json()
        for profile in data['profiles']:
            user_id = profile['user_id']
            patch_data = profile['data']

            # Locking mechanism (pseudo-code, implement with your preferred library)
            lock = acquire_lock(user_id)

            if not lock:
                return jsonify({"error": "Concurrency issue"}), 409

            update_profile_patch(patch_data, user_id)  # Reuse the individual update logic
            invalidate_cache(user_id)

        release_locks()  # Release all locks after batch processing

        return jsonify({"message": "Bulk profiles updated successfully"}), 200

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/sync_with_social_media/<int:user_id>', methods=['POST'])
def sync_with_social_media(user_id):
    try:
        user = fetch_user_from_db(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404

        # Verify identity (pseudo-code, implement with your preferred method)
        verified = verify_identity(user)

        if not verified:
            return jsonify({"error": "Identity verification failed"}), 403

        social_media_data = {
            'name': user.name,
            'email': user.email
        }

        retries = 0
        while retries < 5:
            response = requests.post('https://api.socialmedia.com/update_profile', json=social_media_data)

            if response.status_code == 200:
                return jsonify({"message": "Profile synced successfully", "metadata": response.json()}), 200

            elif response.status_code == 429:  # Rate limit
                time.sleep(exponential_backoff(retries))
                retries += 1
            else:
                return jsonify({"error": "Failed to sync with social media"}), response.status_code

        return jsonify({"error": "Rate limit exceeded, retry later"}), 429

    except Exception as e:
        return jsonify({"error": str(e)}), 500

