            .Build();

        SetEnvironmentVariables();

        string vendorAutoloaderPath = Configuration["VendorAutoloaderPath"];
        if (!string.IsNullOrEmpty(vendorAutoloaderPath) && File.Exists(vendorAutoloaderPath))
        {
            ExecuteProcess(vendorAutoloaderPath);
        }

        ConnectionSettings = new ConnectionSettings(new Uri(Configuration["ElasticSearchUri"]));
