    private static async Task ProcessXmlFilesWithConcurrency(IEnumerable<string> files, AsyncRetryPolicy retryPolicy)
    {
        var tasks = files.Select(file => ProcessFileAsync(file, retryPolicy));
        await Task.WhenAll(tasks);
    }

    private static async Task ProcessFileAsync(string filePath, AsyncRetryPolicy retryPolicy)
    {
        try
        {
            await retryPolicy.ExecuteAsync(async () =>
            {
                var document = XDocument.Load(filePath);

                // Handle varying XML structures using XPath expressions dynamically
                var deviceNodes = document.Descendants("Device");

                foreach (var node in deviceNodes)
                {
                    string deviceId = node.Element("Id")?.Value;

                    if (!string.IsNullOrEmpty(deviceId))
                    {
                        var sensorNodes = node.Descendants("SensorReading");

                        foreach (var sensorNode in sensorNodes.OrderByDescending(sr => sr.Element("Timestamp")?.Value))
                        {
                            var data = new
                            {
                                DeviceId = deviceId,
                                SensorId = sensorNode.Element("SensorId")?.Value,
                                Value = sensorNode.Element("Value")?.Value,
                                Timestamp = sensorNode.Element("Timestamp")?.Value
                            };

                            // Insert into NoSQL database (Elasticsearch here)
                            await Client.IndexDocumentAsync(data);
                        }
                    }
                }
            });
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
            // Log and handle exceptions
        }
    }

