Below is a C++ implementation of the described functionality using modern features and external libraries such as `nlohmann/json` for JSON parsing. The function ensures thread-safety with concurrent read access by utilizing a mutex lock during data access.

```cpp
#include <iostream>
#include <fstream>
#include <unordered_map>
#include <variant>
#include <typeindex>
#include <mutex>
#include <string>
#include <nlohmann/json.hpp>

// Logger placeholder - replace this with your actual logging system.
void logError(const std::string& message) {
    // Implement actual logging logic here
    std::cerr << "Error: " << message << std::endl;
}

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> 
readAndValidateConfig(const std::string& filePath,
                      const std::unordered_map<std::string, std::type_index>& schema) {

    static std::mutex mtx; // Mutex for thread-safe access
    std::lock_guard<std::mutex> lock(mtx);

    std::ifstream inputFile(filePath);
    if (!inputFile.is_open()) {
        logError("Could not open file: " + filePath);
        throw std::runtime_error("File opening failed");
    }

    nlohmann::json jsonData;
    inputFile >> jsonData;

    // Result map to store the validated configurations
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> configMap;

    for (const auto& [key, expectedType] : schema) {
        if (jsonData.contains(key)) {
            const nlohmann::json& value = jsonData[key];
            try {
                if (expectedType == typeid(int) && value.is_number_integer()) {
                    configMap[key] = value.get<int>();
                } else if (expectedType == typeid(double) && value.is_number_float()) {
                    configMap[key] = value.get<double>();
                } else if (expectedType == typeid(std::string) && value.is_string()) {
                    configMap[key] = value.get<std::string>();
                } else if (expectedType == typeid(bool) && value.is_boolean()) {
                    configMap[key] = value.get<bool>();
                } else {
                    std::ostringstream oss;
                    oss << "Type mismatch for key: " << key
                        << ". Expected: " << expectedType.name() 
                        << ", but found: " << value.type_name();
                    logError(oss.str());
                }
            } catch (const nlohmann::json::exception& e) {
                logError("JSON parsing error for key '" + key + "': " + e.what());
            }
        } else {
            logError("Missing expected configuration setting: " + key);
        }
    }

    return configMap;
}
```

### Key Points:
- **Thread-Safety:** The function uses a `static std::mutex` to guard the read and map update operations, ensuring thread-safe access.
- **JSON Parsing & Validation:** Utilizes `nlohmann/json` library for parsing and type validation against the schema provided.
- **Error Handling:** Logs errors using a placeholder logging mechanism (`logError`). Replace this with your actual logging system integration.
- **Performance Considerations:** This implementation assumes reasonable JSON file sizes. For large files, consider streaming JSON parsers or memory-mapped file techniques.

Replace `nlohmann/json.hpp` include and logger function as per your project's setup and ensure that the `nlohmann/json` library is correctly linked to your project.

