class RateLimiter:
    def __init__(self, rate_limit: int):
        self.rate_limit = rate_limit
        self.tokens = rate_limit
        self.last_checked = datetime.now()

    async def wait(self):
        now = datetime.now()
        elapsed_time = (now - self.last_checked).total_seconds()
        self.last_checked = now

        # Refill tokens
        refill_amount = elapsed_time * (self.rate_limit / 60)
        self.tokens = min(self.rate_limit, self.tokens + refill_amount)

        if self.tokens >= 1:
            self.tokens -= 1
        else:
            await asyncio.sleep(1 - self.tokens)

