Below is an implementation of the `DeployWebsite` function in C#. This code includes handling for web.config checking, MD5 hashing with chunked reading, asynchronous remote file download with resumability, error logging, and a return of the hexdigest. It assumes some external classes/interfaces like `ILogger`, `IWebServerApi`, and a simple HTTP client setup.

```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class WebDeployer
{
    private readonly IWebServerApi _webServerApi;
    private readonly ILogger _logger;
    private const int DefaultChunkSize = 8192; // 8 KB

    public WebDeployer(IWebServerApi webServerApi, ILogger logger)
    {
        _webServerApi = webServerApi ?? throw new ArgumentNullException(nameof(webServerApi));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> DeployWebsite(string directoryPath, string siteName, string deploymentPackageSource, string expectedChecksum, int chunkSize = DefaultChunkSize)
    {
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            _logger.LogError($"Error: 'web.config' not found in the specified directory '{directoryPath}'.");
            return null;
        }

        var filePath = await EnsureLocalDeploymentPackage(deploymentPackageSource, chunkSize);

        try
        {
            using (var md5 = MD5.Create())
            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                var hashBytes = ComputeHashInChunks(md5, stream, chunkSize);
                string hexDigest = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

                if (!hexDigest.Equals(expectedChecksum.ToLowerInvariant(), StringComparison.OrdinalIgnoreCase))
                {
                    _logger.LogError($"Error: The MD5 checksum does not match for the deployment package '{filePath}'.");
                    return null;
                }

                await _webServerApi.DeploySiteAsync(directoryPath, siteName, filePath);
                _logger.LogInformation($"Successfully deployed {siteName} to {directoryPath}.");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error during deployment: {ex.Message}");
            return null;
        }

        return hexDigest;
    }

    private async Task<string> EnsureLocalDeploymentPackage(string source, int chunkSize)
    {
        if (Uri.IsWellFormedUriString(source, UriKind.Absolute))
        {
            var tempFilePath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            await DownloadFileWithResumeAsync(new Uri(source), tempFilePath, chunkSize);
            return tempFilePath;
        }
        else
        {
            return source; // Assume it's a local file path if not a valid URI.
        }
    }

    private async Task DownloadFileWithResumeAsync(Uri uri, string destinationPath, int chunkSize)
    {
        var httpClient = new HttpClient();
        long existingLength = 0;

        if (File.Exists(destinationPath))
        {
            existingLength = new FileInfo(destinationPath).Length;
            httpClient.DefaultRequestHeaders.Range = new System.Net.Http.Headers.RangeHeaderValue(existingLength, null);
        }

        try
        {
            using (var responseStream = await httpClient.GetStreamAsync(uri))
            {
                var fileStream = new FileStream(destinationPath, FileMode.Append, FileAccess.Write, FileShare.None);

                byte[] buffer = new byte[chunkSize];
                int bytesRead;

                while ((bytesRead = await responseStream.ReadAsync(buffer, 0, chunkSize)) > 0)
                {
                    fileStream.Write(buffer, 0, bytesRead);
                }

                fileStream.Close();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error downloading file: {ex.Message}");
            throw;
        }
    }

    private byte[] ComputeHashInChunks(MD5 md5, Stream inputStream, int chunkSize)
    {
        using var buffer = new MemoryStream();
        int bytesRead;

        byte[] readBuffer = new byte[chunkSize];
        while ((bytesRead = inputStream.Read(readBuffer, 0, readBuffer.Length)) > 0)
        {
            buffer.Write(readBuffer, 0, bytesRead);
            md5.TransformBlock(readBuffer, 0, bytesRead, null, 0);
        }

        buffer.Flush();
        md5.TransformFinalBlock(new byte[0], 0, 0);

        return md5.Hash;
    }
}

// Mock interfaces
public interface IWebServerApi
{
    Task DeploySiteAsync(string directoryPath, string siteName, string filePath);
}

public interface ILogger
{
    void LogError(string message);
    void LogInformation(string message);
}
```

