    }

    public function reloadConfiguration() {
        try {
            $remoteConfig = $this->fetchRemoteConfiguration();
            $localConfig = $this->loadLocalConfiguration();

            // Merge configurations with local overrides taking precedence
            $config = array_merge($remoteConfig, $localConfig);
            $this->cacheConfiguration($config);

            $this->log("Configuration reloaded for stage: {$this->stage}");
        } catch (Exception $e) {
            $this->log("Error reloading configuration: " . $e->getMessage());
