<?php

namespace EcommercePlatform;

use Psr\Log\LoggerInterface;
use Doctrine\DBAL\Connection;
use Symfony\Component\Cache\Adapter\FilesystemAdapter;
use Symfony\Contracts\Cache\ItemInterface;

interface PasswordPolicyInterface {
    public function getMinLength(): int;
    public function getAllowedCharacters(): string;
}

class TenantPasswordPolicy implements PasswordPolicyInterface {
    private $minLength;
    private $allowedChars;

    public function __construct($minLength, $allowedChars) {
        $this->minLength = $minLength;
        $this->allowedChars = $allowedChars;
    }

    public function getMinLength(): int {
        return $this->minLength;
    }

    public function getAllowedCharacters(): string {
        return $this->allowedChars;
    }
}

class PasswordManager {
    private $logger;
    private $dbConnection;
    private $cache;

    public function __construct(LoggerInterface $logger, Connection $dbConnection) {
        $this->logger = $logger;
        $this->dbConnection = $dbConnection;
        $this->cache = new FilesystemAdapter();
    }

    public function hashPassword($password, int $tenantId, string $algorithm = PASSWORD_DEFAULT): string {
        $policy = $this->getTenantPolicy($tenantId);

        if (strlen($password) < $policy->getMinLength()) {
            throw new \Exception("Password does not meet the minimum length requirement.");
        }

        if (!preg_match("/^{$policy-> getAllowedCharacters()}+$/", $password)) {
            throw new \Exception("Password contains disallowed characters.");
        }

        return password_hash($password, $algorithm);
    }

    public function verifyPassword(string $password, string $hash, int $tenantId): bool {
        return password_verify($password, $hash);
    }

    private function getTenantPolicy(int $tenantId): PasswordPolicyInterface {
        return $this->cache->get("tenant_policy_$tenantId", function (ItemInterface $item) use ($tenantId) {
            // Fetch and cache tenant-specific policy from the database
            $stmt = $this->dbConnection->executeQuery('SELECT minLength, allowedChars FROM tenant_policies WHERE id = ?', [$tenantId]);
            $policyData = $stmt->fetchAssociative();
            $item->expiresAfter(3600);  // Cache expires after 1 hour
            return new TenantPasswordPolicy($policyData['minLength'], $policyData['allowedChars']);
        });
    }
}

class RealTimeMonitor {
