        // Log the event with details
        $this->logger->info($event, $details);

        if ($this->isSuspiciousActivity($event)) {
            $this->alertAdmin($event, $details);
        }
    }

    private function isSuspiciousActivity(string $event): bool {
        return in_array($event, ['failed_login_attempt', 'password_reset_failure']);
    }

    private function alertAdmin(string $event, array $details): void {
        // Send alerts (e.g., email or SMS) to administrators
        $this->logger->alert("Suspicious activity detected: $event", $details);
    }
}

