```java
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

// External Session Management Service Stub
interface ExternalSessionService {
    String createSession(String userData);
    Optional<String> getSessionData(String sessionId);
    void updateSession(String sessionId, String userData);
    void deleteSession(String sessionId);
}

class CacheEntry {
    private final String data;
    private final long expiryTime;

    public CacheEntry(String data, long expiryTime) {
        this.data = data;
        this.expiryTime = expiryTime;
    }

    public boolean isExpired() {
        return System.currentTimeMillis() > expiryTime;
    }

    public String getData() {
        return data;
    }
}

public class SessionManager {

    private final ExternalSessionService sessionService;
    private final ConcurrentHashMap<String, CacheEntry> cache;

    public SessionManager(ExternalSessionService sessionService) {
        this.sessionService = sessionService;
        this.cache = new ConcurrentHashMap<>();
    }

    public String createOrUpdateSession(String userData) {
        String sessionId = generateSessionId();
        String cachedData = retrieveFromCache(sessionId);

        if (cachedData != null) {
            updateSessionInExternalService(sessionId, userData);
        } else {
            String sessionData = sessionService.createSession(userData);
            storeInCache(sessionId, sessionData);
        }

        return sessionId;
    }

    public Optional<String> getSession(String sessionId) {
        String cachedData = retrieveFromCache(sessionId);
        if (cachedData != null) {
            return Optional.of(cachedData);
        } else {
            return sessionService.getSessionData(sessionId).map(this::storeInCacheAndReturn);
        }
    }

    public void deleteSession(String sessionId) {
        cache.remove(sessionId);
        sessionService.deleteSession(sessionId);
    }

    private String retrieveFromCache(String sessionId) {
        CacheEntry entry = cache.get(sessionId);
        if (entry != null && !entry.isExpired()) {
            return entry.getData();
        }
        cache.remove(sessionId); // Cleanup expired entries
        return null;
    }

    private void storeInCache(String sessionId, String data) {
        long expiryTime = System.currentTimeMillis() + TimeUnit.MINUTES.toMillis(30);
        cache.put(sessionId, new CacheEntry(data, expiryTime));
    }

    private Optional<String> storeInCacheAndReturn(String data) {
        String sessionId = generateSessionFromData(data);
        storeInCache(sessionId, data);
        return Optional.of(data);
    }

    private void updateSessionInExternalService(String sessionId, String userData) {
        sessionService.updateSession(sessionId, userData);
        storeInCache(sessionId, userData);
    }

    private String generateSessionId() {
        // Implement a secure session ID generation logic
        return Long.toHexString(System.nanoTime());
    }

    private String generateSessionFromData(String data) {
        // Extract sessionId from stored data (assuming some format)
        return data.split(":")[0];
    }
}
```

