class TracingSystem {
    private Map<String, TracingBackend> backends = new HashMap<>();
    private double samplingRate;
    private final String fallbackLogFile;

    public TracingSystem(JsonNode config, String fallbackLogFile) throws IOException {
        this.fallbackLogFile = fallbackLogFile;
        ObjectMapper mapper = new ObjectMapper();

        for (JsonNode backend : config.get("backends")) {
            String type = backend.get("type").asText();
            String url = backend.get("url").asText();

            switch (type.toLowerCase()) {
                case "jaeger":
                    backends.put(type, new JaegerTracing(url));
                    break;
                case "zipkin":
                    backends.put(type, new ZipkinTracing(url));
                    break;
                case "otlp":
                    backends.put(type, new OTLPTracing(url));
                    break;
                default:
                    logError("Unsupported tracing backend: " + type);
            }
        }

        this.samplingRate = config.get("samplingRate").asDouble();
    }

    public void trace(String traceId, String data) {
        if (Math.random() > samplingRate) {
            return; // Skip based on sampling rate
        }

        for (TracingBackend backend : backends.values()) {
            try {
                backend.sendTraceData(traceId, encryptAndAnonymize(data));
            } catch (Exception e) {
                logError("Failed to send trace data: " + e.getMessage());
                continue;
            }
        }
    }

    private String encryptAndAnonymize(String data) {
        // Implement encryption and anonymization logic here
        return data; // Placeholder for processed data
    }

    private void logError(String message) {
        try (FileWriter fw = new FileWriter(fallbackLogFile, true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            bw.write(message + "\n");
        } catch (IOException e) {
            System.err.println("Failed to log error: " + e.getMessage());
        }
    }

    public void addBackend(String type, String url) throws IOException {
        switch (type.toLowerCase()) {
            case "jaeger":
                backends.put(type, new JaegerTracing(url));
                break;
            case "zipkin":
                backends.put(type, new ZipkinTracing(url));
                break;
            case "otlp":
                backends.put(type, new OTLPTracing(url));
                break;
            default:
                logError("Unsupported tracing backend: " + type);
        }
    }

    public void removeBackend(String type) {
        if (!backends.containsKey(type)) {
            logError("Trying to remove non-existing backend: " + type);
            return;
        }
        backends.remove(type);
    }
}

// Main class to load configuration and initialize the tracing system
public class TracingApp {
    public static void main(String[] args) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        JsonNode config = mapper.readTree(new File("config.json"));

        String fallbackLogFile = config.get("fallbackLogFilePath").asText("error.log");
        TracingSystem tracingSystem = new TracingSystem(config, fallbackLogFile);

        // Example usage
        tracingSystem.trace("traceId-123", "Transaction data example");
    }
}
