#include <iostream>
#include <fstream>
#include <string>

constexpr size_t MAX_FILE_PATH_LENGTH = 4096;

int safeFileAppend(const std::string& filePath, const char* buffer, size_t bufferSize) {
    if (filePath.empty() || filePath.length() > MAX_FILE_PATH_LENGTH) {
        std::cerr << "Invalid file path." << std::endl;
        return -1;
    }

    std::ofstream file(filePath, std::ios_base::app | std::ios_base::binary);

    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filePath << std::endl;
        return -1;
    }

    try {
        file.write(buffer, bufferSize);

        if (file.fail()) {
            throw std::runtime_error("Write operation failed.");
        }

        int bytesAppended = static_cast<int>(bufferSize);
        std::cout << "Successfully appended " << bytesAppended << " bytes to the file." << std::endl;

        return bytesAppended;
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
        return -1;
    }
}
