# Simplified architecture sketch for a distributed file storage system in Python using Flask as the RESTful API server.

from flask import Flask, request, jsonify
import hashlib
import json

app = Flask(__name__)

# Mock database of files and their metadata
files_db = {}
nodes = []  # list of available nodes

def get_node_for_file(file_id):
    # Hash-based consistent hashing for node assignment
    hash_value = int(hashlib.sha256(file_id.encode()).hexdigest(), 16)
    return nodes[hash_value % len(nodes)]

@app.route('/file/upload', methods=['POST'])
def upload_file():
    file_data = request.files['file']
    filename = file_data.filename
    content = file_data.read()

    # Save metadata and determine storage node
    file_id = hashlib.sha256(content).hexdigest()
    assigned_node = get_node_for_file(file_id)

    files_db[file_id] = {
        'filename': filename,
        'node': assigned_node,
        'content': content,
        'version': 1
    }

    return jsonify({'file_id': file_id, 'node': assigned_node})

@app.route('/file/download/<file_id>', methods=['GET'])
def download_file(file_id):
    if file_id in files_db:
        file_info = files_db[file_id]
        response = jsonify({'filename': file_info['filename'], 'content': file_info['content']})
        return response
    else:
        return jsonify({'error': 'File not found'}), 404

@app.route('/file/delete/<file_id>', methods=['DELETE'])
def delete_file(file_id):
    if file_id in files_db:
        del files_db[file_id]
        return jsonify({'message': 'File deleted'})
    else:
        return jsonify({'error': 'File not found'}), 404

# Additional routes for dynamic partitioning, rebalancing, authentication, etc., would be here.

if __name__ == '__main__':
    app.run(debug=True)
