<?php

class AuthenticationService {

    private $userApiUrl;
    private $defaultHashAlgorithm = PASSWORD_BCRYPT;
    private $defaultSaltLength = 16;

    public function __construct($apiUrl) {
        $this->userApiUrl = $apiUrl;
    }

    // Generates a secure random string for user salt
    public function generateSalt($length = null) {
        if ($length === null) {
            $length = $this->defaultSaltLength;
        }

        return bin2hex(random_bytes($length));
    }

    // Hashes the password using the specified algorithm, defaults to BCRYPT
    public function hashPassword($password, $algorithm = null) {
        if ($algorithm === null) {
            $algorithm = $this->defaultHashAlgorithm;
        }

        return password_hash($password, $algorithm);
    }

    // Registers a new user by interacting with the external API
    public function registerUser($username, $password, $email) {
        try {
            $salt = $this->generateSalt();
            $hashedPassword = $this->hashPassword($password);

            $userData = [
                'username' => $username,
                'password' => $hashedPassword,
                'salt'     => $salt,
                'email'    => $email
            ];

            $response = $this->apiRequest('POST', '/users/register', $userData);

            if ($response['status'] !== 200) {
                throw new Exception("Registration failed: " . json_encode($response));
            }

            return true;
        } catch (Exception $e) {
            // Log the error or handle it as needed
            error_log($e->getMessage());
            return false;
        }
    }

    // Authenticates a user by verifying their password via API
    public function authenticateUser($username, $password) {
        try {
            $response = $this->apiRequest('GET', "/users/{$username}");

            if ($response['status'] !== 200 || !isset($response['data']['password'])) {
                throw new Exception("User not found or error during retrieval");
            }

            return password_verify($password, $response['data']['password']);
        } catch (Exception $e) {
            // Log the error or handle it as needed
            error_log($e->getMessage());
            return false;
        }
    }

    // Regenerates a salt for an existing user and rehashes their password
    public function regenerateSaltForUser($username, $password) {
        try {
            $response = $this->apiRequest('GET', "/users/{$username}");

            if ($response['status'] !== 200 || !isset($response['data']['password'])) {
                throw new Exception("User not found or error during retrieval");
            }

            if (!password_verify($password, $response['data']['password'])) {
                throw new Exception("Invalid password for user: {$username}");
            }

            $newSalt = $this->generateSalt();
            $newHashedPassword = $this->hashPassword($password);

            $updateData = [
                'salt' => $newSalt,
                'password' => $newHashedPassword
            ];

            $apiResponse = $this->apiRequest('PUT', "/users/{$username}/regenerate-salt", $updateData);

            return $apiResponse['status'] === 200;
        } catch (Exception $e) {
            // Log the error or handle it as needed
            error_log($e->getMessage());
            return false;
        }
    }

    // Helper function to interact with the external user management API
    private function apiRequest($method, $endpoint, $data = null) {
        $url = $this->userApiUrl . $endpoint;

        $options = [
            'http' => [
                'header'  => "Content-type: application/json\r\n",
                'method'  => $method,
                'content' => json_encode($data),
            ],
        ];

        $context  = stream_context_create($options);
        $result   = file_get_contents($url, false, $context);

        if ($result === FALSE) {
            return ['status' => 500];
        }

        $response = json_decode($result, true);
        return [
            'status' => isset($http_response_header[0]) ? (int)explode(' ', $http_response_header[0])[1] : 500,
            'data'   => $response
        ];
    }
}
