public class XmlAndBinaryParser : IDisposable
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly ConcurrentDictionary<string, string> _xmlCache = new();
    private readonly string _cacheDirectory;

    public XmlAndBinaryParser(string cacheDirectory)
    {
        _cacheDirectory = cacheDirectory;
    }

    public async Task<string> FetchXmlContentAsync(string url)
    {
        try
        {
            if (_xmlCache.TryGetValue(url, out var cachedContent))
                return cachedContent;

            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            CacheXmlContent(url, content);
            return content;
        }
        catch (Exception ex)
        {
            LogError("Failed to fetch XML content", ex);
            throw new ApplicationException("Network error occurred.", ex);
        }
    }

    private void CacheXmlContent(string url, string content)
    {
        // Implement caching logic based on size and duration
        _xmlCache[url] = content;
        var cacheFilePath = Path.Combine(_cacheDirectory, GetFileNameFromUrl(url));
        File.WriteAllText(cacheFilePath, content);
    }

    public T ParseLargeXml<T>(string xmlContent, XPathExpression expression)
    {
        try
        {
            using (var stringReader = new StringReader(xmlContent))
            using (var xmlReader = XmlReader.Create(stringReader))
            {
                var navigator = new XPathDocument(xmlReader).CreateNavigator();
                var nodes = navigator.Select(expression);

                if (!nodes.MoveNext())
                    throw new ApplicationException("XPath evaluation returned no result.");

                // Assuming T is a simple type or can be deserialized from XML
                return (T)Convert.ChangeType(nodes.Current.Value, typeof(T));
            }
        }
        catch (Exception ex)
        {
            LogError("Failed to parse XML", ex);
            throw new ApplicationException("XML parsing error occurred.", ex);
        }
    }

    public byte[] LoadBinaryData(string filePath)
    {
        try
        {
            if (!File.Exists(filePath))
                return RetrieveFromDatabaseAsFallback(filePath);

            return File.ReadAllBytes(filePath);
        }
        catch (Exception ex)
        {
            LogError("Failed to load binary data", ex);
            throw new ApplicationException("File read error occurred.", ex);
        }
    }

    private byte[] RetrieveFromDatabaseAsFallback(string filePath)
    {
        // Implement database retrieval logic
        return Array.Empty<byte>();
    }

    public void InsertAfterFirst(List<string> list, string first, string second)
    {
        var index = list.IndexOf(first);
        if (index != -1)
            list.Insert(index + 1, second);
        else
            list.Add(second);
    }

    private void LogError(string message, Exception ex)
    {
        // Implement logging mechanism
        Console.WriteLine($"{message}: {ex.Message}");
    }

    public void Dispose()
    {
        _httpClient?.Dispose();
    }
}

