// Define a function pointer type for factory functions.
typedef void (*FactoryFunction)(const char*);

// Registry of factory functions keyed by ID.
pthread_mutex_t registry_lock = PTHREAD_MUTEX_INITIALIZER;
FactoryFunction* factory_registry = NULL;
size_t registry_size = 0;

// Structure to hold external configuration details
