    filterTransactions();  // Initialize and run the configuration management system.

    if (argc > 1) {
        const char* command = argv[1];

        if (strcmp(command, "add") == 0) {
            handleAddFactoryCommand();
        } else if (strcmp(command, "remove") == 0) {
            handleRemoveFactoryCommand();
        } else if (strcmp(command, "query") == 0) {
            handleQueryFactoryCommand();
        }
    }

    return 0;
}

// Implementation of functions

void filterTransactions() {
    // Initialize system, read initial configurations
    printf("Initializing Transaction Filter System...\n");

    ExternalConfigSource source = {"http://config-service.local/config", "secure-access-key"};
    fetchConfigurationFromService(source);
}

void addFactoryFunction(const char* id, FactoryFunction func) {
    pthread_mutex_lock(&registry_lock);

    if (registry_size >= 10) { // Assume a fixed size for simplicity
        printf("Registry full. Cannot add more factory functions.\n");
        pthread_mutex_unlock(&registry_lock);
        return;
    }

    // Add the new function to the registry.
    int index = -1;
    for(size_t i = 0; i < registry_size; ++i) {
        if(strcmp(factory_registry[i].id, id) == 0) {
            printf("Factory ID already exists.\n");
            pthread_mutex_unlock(&registry_lock);
            return;
        }
    }

    index = (int)registry_size;
    factory_registry[index] = func;
    registry_size++;

    pthread_mutex_unlock(&registry_lock);
}

void removeFactoryFunction(const char* id) {
    pthread_mutex_lock(&registry_lock);

    for(size_t i = 0; i < registry_size; ++i) {
        if(strcmp(factory_registry[i].id, id) == 0) {
            // Shift elements to the left
            memmove(&factory_registry[i], &factory_registry[i + 1],
                    (registry_size - i - 1) * sizeof(FactoryFunction));
            registry_size--;
            break;
        }
    }

    pthread_mutex_unlock(&registry_lock);
}

FactoryFunction getFactoryFunction(const char* id) {
    pthread_mutex_lock(&registry_lock);

    for(size_t i = 0; i < registry_size; ++i) {
        if(strcmp(factory_registry[i].id, id) == 0) {
            FactoryFunction func = factory_registry[i];
            pthread_mutex_unlock(&registry_lock);
            return func;
        }
    }

    pthread_mutex_unlock(&registry_lock);
    return NULL;
}

int fetchConfigurationFromService(ExternalConfigSource source) {
