Below is an example of how you might set up such a CI/CD pipeline using Node.js, Jenkins, Docker, Kubernetes, and monitoring tools like Prometheus and Grafana.

### Jenkinsfile

```groovy
pipeline {
    agent any
    environment {
        DOCKER_IMAGE = "your-docker-repo/your-app"
        KUBE_NAMESPACE = "${env.BRANCH_NAME == 'main' ? 'production' : env.BRANCH_NAME}"
        SERVICE_ACCOUNT_TOKEN = credentials('k8s-service-account-token')
    }
    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Build Docker Image') {
            parallel {
                stage('Frontend') {
                    agent { docker 'node:14' }
                    steps {
                        script {
                            def app = docker.build("${DOCKER_IMAGE}-frontend", "--cache-from=${DOCKER_IMAGE}-frontend:latest ./frontend")
                            app.push()
                        }
                    }
                }

                stage('Backend') {
                    agent { docker 'maven:3.8.4-jdk-11' }
                    steps {
                        script {
                            def app = docker.build("${DOCKER_IMAGE}-backend", "--cache-from=${DOCKER_IMAGE}-backend:latest ./backend")
                            app.push()
                        }
                    }
                }
            }
        }

        stage('Deploy to Kubernetes') {
            parallel {
                stage('Frontend Deployment') {
                    environment {
                        KUBECONFIG = credentials('k8s-config')
                    }
                    steps {
                        sh """
                            kubectl config use-context ${KUBE_NAMESPACE}-context
                            kubectl apply -f kubernetes/frontend-deployment.yaml
                        """
                    }
                }

                stage('Backend Deployment') {
                    environment {
                        KUBECONFIG = credentials('k8s-config')
                    }
                    steps {
                        sh """
                            kubectl config use-context ${KUBE_NAMESPACE}-context
                            kubectl apply -f kubernetes/backend-deployment.yaml
                        """
                    }
                }
            }
        }

        stage('Monitor and Rollback') {
            steps {
                script {
                    def metrics = sh(script: "curl -s http://prometheus-server/api/v1/query?query=... --silent", returnStdout: true).trim()
                    if (metrics.contains("high-error-rate")) {
                        echo "High error rate detected, rolling back..."
                        rollbackDeployments()
                    }
                }
            }
        }

        stage('Cleanup') {
            steps {
                script {
                    sh 'docker system prune -f'
                }
            }
        }
    }
}

def rollbackDeployments() {
    env.KUBECONFIG = credentials('k8s-config')
    sh """
        kubectl rollout undo deployment/frontend-deployment
        kubectl rollout undo deployment/backend-deployment
    """
}
```

