```python
import threading
from collections import OrderedDict
import requests
import os
import json
import time

class ThemeCache:
    def __init__(self, cache_dir='theme_cache', max_cache_size=10):
        self.cache_dir = cache_dir
        self.max_cache_size = max_cache_size
        self.lock = threading.Lock()
        self.cache = OrderedDict()
        self.metadata_file_path = os.path.join(cache_dir, 'metadata.json')
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir)
        self.load_metadata()

    def load_metadata(self):
        if os.path.exists(self.metadata_file_path):
            with open(self.metadata_file_path, 'r') as f:
                metadata = json.load(f)
                for theme_name, data in metadata.items():
                    self.cache[theme_name] = {
                        'bitmap': data['bitmap'],
                        'metadata': data['metadata']
                    }
        else:
            with open(self.metadata_file_path, 'w') as f:
                json.dump({}, f)

    def save_metadata(self):
        with self.lock:
            metadata = {name: {'bitmap': info['bitmap'], 'metadata': info['metadata']}
                        for name, info in self.cache.items()}
            with open(self.metadata_file_path, 'w') as f:
                json.dump(metadata, f)

    def get_theme(self, theme_name):
        with self.lock:
            if theme_name in self.cache:
                self.cache.move_to_end(theme_name)
                return self.cache[theme_name]
            else:
                bitmap, metadata = self.download_theme(theme_name)
                self.add_to_cache(theme_name, bitmap, metadata)
                return {'bitmap': bitmap, 'metadata': metadata}

    def download_theme(self, theme_name):
        try:
            response = requests.get(f'https://example.com/themes/{theme_name}.json')
            response.raise_for_status()
            theme_info = response.json()

            bitmap_response = requests.get(theme_info['bitmap_url'])
            bitmap_response.raise_for_status()

            # Save the bitmap
            bitmap_path = os.path.join(self.cache_dir, f"{theme_name}.bmp")
            with open(bitmap_path, 'wb') as bmp_file:
                bmp_file.write(bitmap_response.content)

            return bitmap_path, theme_info

        except requests.RequestException as e:
            print(f"Error downloading {theme_name}: {e}")
            return None, None

    def add_to_cache(self, theme_name, bitmap, metadata):
        if len(self.cache) >= self.max_cache_size:
            oldest = next(iter(self.cache))
            del self.cache[oldest]
            os.remove(self.cache[oldest]['bitmap'])

        self.cache[theme_name] = {'bitmap': bitmap, 'metadata': metadata}
        self.save_metadata()

    def clear_outdated_themes(self):
        with self.lock:
            current_time = time.time()
            threshold = 30 * 24 * 60 * 60  # 30 days
            for theme_name in list(self.cache.keys()):
                last_used = os.path.getmtime(self.cache[theme_name]['bitmap'])
                if current_time - last_used > threshold:
                    del self.cache[theme_name]
                    os.remove(self.cache[theme_name]['bitmap'])

    def periodic_update_check(self, interval=86400):
        while True:
            time.sleep(interval)
            for theme_name in list(self.cache.keys()):
                new_metadata = requests.get(f'https://example.com/themes/{theme_name}.json')
                if new_metadata.status_code == 200 and new_metadata.json()['version'] != self.cache[theme_name]['metadata']['version']:
                    self.get_theme(theme_name)

    def start_background_task(self):
        threading.Thread(target=self.periodic_update_check, daemon=True).start()

# Usage example:
theme_cache = ThemeCache()
theme_cache.start_background_task()
theme_data = theme_cache.get_theme('dark_mode')
```

