const { promisify } = require('util');
const readFileAsync = promisify(require('fs').readFile);
const concatStream = require('concat-stream');
const { storeDataInDB } = require('./databaseConnector');

async function handleIncomingStream(stream) {
  try {
    return new Promise((resolve, reject) => {
      stream
        .pipe(concatStream(async (dataBuffer) => {
          const data = JSON.parse(dataBuffer.toString());
          await storeDataInDB(data);
          resolve();
        }))
        .on('error', reject);
    });
  } catch (err) {
    console.error('Error handling stream:', err);
    // Implement retry logic or other error handling here
  }
}

module.exports = { handleIncomingStream };
