const { MongoClient } = require('mongodb');

let dbClient;

async function connectToDB() {
  if (!dbClient || !dbClient.isConnected()) {
    dbClient = new MongoClient(process.env.DB_URI);
    await dbClient.connect();
  }
}

async function storeDataInDB(data) {
  try {
    await connectToDB();
    const collection = dbClient.db('iotData').collection('streams');
    await collection.insertMany(data.map((d) => ({ ...d, timestamp: new Date() })));
  } catch (err) {
    console.error('Error storing data in DB:', err);
    throw err;
  }
}

module.exports = { storeDataInDB };
