    console.warn(`Attempt ${attempt + 1} failed:`, err.message);
    setTimeout(() => recoverFromError(err, attempt + 1), 1000 * Math.pow(2, attempt));
  } else {
    console.error('Failed after multiple attempts:', err);
  }
}

