```javascript
// Using a testing framework like Jest or Mocha to test

describe('asyncReduce function tests', () => {
  it('should correctly reduce arrays with initial values in parallel', async () => {
    const numbers = [1, 2, 3];
    const initialValues = [0];

    const callback = (acc, curr) => Promise.resolve(acc + curr);

    const result = await asyncReduce(numbers, initialValues, callback);
    expect(result).toEqual([6]);
  });

  it('should handle errors and continue processing', async () => {
    const numbers = [1, 'invalid', 3];
    const initialValues = [0];

    const callback = (acc, curr) => {
      if (typeof curr !== 'number') throw new Error('Invalid number');
      return Promise.resolve(acc + curr);
    };

    try {
      const result = await asyncReduce(numbers, initialValues, callback);
      expect(result).toEqual([4]); // Only valid numbers are summed
    } catch (e) {
      fail('The reduction process should not have thrown an error.');
    }
  });

  it('should support cancellation of the reduction process', async () => {
    const token = new CancellationToken();
    const numbers = [1, 2, 3];
    const initialValues = [0];

    const callback = (acc, curr) => Promise.resolve(acc + curr);

    setTimeout(() => token.cancel(), 50); // Cancel before processing starts

    try {
      const result = await asyncReduce(numbers, initialValues, callback);
      expect(result).toEqual([null]); // Expect all results to be null due to cancellation
    } catch (e) {
      fail('The reduction process should not have thrown an error.');
    }
  });

  it('should respect max concurrency level', async () => {
    const numbers = [1, 2, 3];
    const initialValues = [0, 10];

    let callsCount = 0;
    const callback = (acc, curr) => {
      callsCount++;
      return new Promise((resolve) => setTimeout(() => resolve(acc + curr), 100));
    };

    await asyncReduce(numbers, initialValues, callback, 1);
    expect(callsCount).toBe(8); // Each reduction runs independently, so 4 elements each for 2 initial values
  });
});
