#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Function to convert JPEG to PDF and embed metadata
int jpeg_to_pdf_with_metadata(const char *jpeg_file, const char *output_dir,
                             const char *author, const char *title, 
                             const char *creation_date) {
    if (!jpeg_file || !output_dir || !author || !title || !creation_date) {
        fprintf(stderr, "Invalid input: All parameters must be provided.\n");
        return 1;
    }

    // Check if JPEG file exists and is accessible
    FILE *file = fopen(jpeg_file, "rb");
    if (!file) {
        perror("Error opening JPEG file");
        return 1;
    }
    fclose(file);

    // Create output PDF filename
    char pdf_filename[256];
    snprintf(pdf_filename, sizeof(pdf_filename), "%s/output.pdf", output_dir);

    // Check if output directory is accessible and writable
    FILE *test_file = fopen(pdf_filename, "w");
    if (!test_file) {
        perror("Error accessing output directory");
        return 1;
    }
    fclose(test_file);

    // Prepare command to convert JPEG to PDF using ImageMagick's `convert` tool
    char command[1024];
    snprintf(command, sizeof(command),
             "convert %s %s && "
             "pdftk %s update_info_utf8 < metadata.txt output %s",
             jpeg_file, pdf_filename,
             pdf_filename, pdf_filename);

    // Prepare metadata file content
    FILE *metadata_file = fopen("metadata.txt", "w");
    if (!metadata_file) {
        perror("Error creating metadata file");
        return 1;
    }

    fprintf(metadata_file, "[ /Title (%s) /Author (%s) /CreationDate (D:%s) ]\n",
            title, author, creation_date);
    fclose(metadata_file);

    // Execute the command
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error converting JPEG to PDF or embedding metadata.\n");
        return 1;
    }

    printf("Conversion and metadata embedding successful!\n");
    return 0;
}
