### C++ Function for Image Conversion

```cpp
#include <iostream>
#include <filesystem>
#include <fstream>
#include <string>
#include <json/json.h> // Include a library like jsoncpp or nlohmann/json
#include <opencv2/opencv.hpp>

namespace fs = std::filesystem;

int convertImagesToPDFs(const std::string& inputDir, const std::string& configFilePath, const std::string& outputDir) {
    Json::Value config;
    std::ifstream configFile(configFilePath);
    if (!configFile.is_open()) {
        std::cerr << "Failed to open configuration file." << std::endl;
        return 0;
    }

    configFile >> config;

    int successfulConversions = 0;
    for (const auto& entry : fs::directory_iterator(inputDir)) {
        if (!entry.is_regular_file()) continue;

        try {
            cv::Mat image = cv::imread(entry.path().string(), cv::IMREAD_COLOR);
            if (image.empty()) throw std::runtime_error("Could not open or find the image.");

            int targetWidth = config["resize_width"].asInt();
            double aspectRatio = static_cast<double>(image.rows) / image.cols;
            cv::Mat resizedImage;
            cv::resize(image, resizedImage, cv::Size(targetWidth, static_cast<int>(targetWidth * aspectRatio)));

            std::string outputFileName = fs::path(outputDir) / (entry.path().stem().string() + ".pdf").string();
            cv::imwrite(outputFileName, resizedImage);

            ++successfulConversions;
        } catch (const std::exception& e) {
            std::cerr << "Error processing file: " << entry.path().string() << " - " << e.what() << std::endl;
        }
    }

    return successfulConversions;
}

int main(int argc, char** argv) {
    if (argc != 4) {
        std::cerr << "Usage: " << argv[0] << " <inputDir> <configFilePath> <outputDir>" << std::endl;
        return 1;
    }

    int successCount = convertImagesToPDFs(argv[1], argv[2], argv[3]);
    std::cout << "Successfully converted " << successCount << " files." << std::endl;

    return 0;
}
```

