### C# Function: Parse XML with XPath

```csharp
using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static XmlNode GetFirstElementByName(string xmlContent, string elementName)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlContent);

        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select($"//{elementName}");

        int count = 0;
        foreach (XPathNavigator node in nodes)
        {
            if (++count > 1)
            {
                throw new InvalidOperationException("Multiple elements found with the given name.");
            }
            firstElement = node as IXmlNode;
        }

        if (firstElement == null)
        {
            throw new Exception("No element found with the specified name.");
        }

        return firstElement;
    }
}
```

### C Function: Append Slash to String

```c
#include <stdio.h>
#include <string.h>

char* appendSlashIfPossible(const char* input, size_t sizeLimit) {
    if (strlen(input) >= sizeLimit - 1) {
        return NULL;
    }

    size_t newLength = strlen(input) + 2; // for slash and null terminator
    char* result = (char*)malloc(newLength);
    if (!result) return NULL;

    strcpy(result, input);
    strcat(result, "/");

    return result;
}
```

### Python Function: Read, Sort File Lines, Extract Sequence

```python
def process_file(filename):
    try:
        with open(filename, 'r') as file:
            lines = file.readlines()

        if not lines:
            raise ValueError("File is empty")

        lines.sort()
        last_line = lines[-1].strip()

        # Assuming sequence number is at the end of the line
        parts = last_line.split()
        if len(parts) == 0:
            raise ValueError("No data in last line")

        try:
            seq_number = int(parts[-1])
        except ValueError:
            raise ValueError("Sequence number not found in last line")

        return seq_number

    except Exception as e:
        print(f"Error processing file: {e}")
        return None
```

