// EnvironmentVariableHandler.cs
using System;
using System.Collections.Generic;
using System.IO;

public class EnvironmentVariableHandler
{
    private Dictionary<string, string> envVariables = new Dictionary<string, string>();

    public void LoadEnvFiles()
    {
        LoadEnvFile(".env");
        LoadEnvFile(".env.local"); // This will override values from .env if present
    }

    private void LoadEnvFile(string fileName)
    {
        var filePath = Path.Combine(Directory.GetCurrentDirectory(), fileName);
        if (!File.Exists(filePath)) return;

        foreach (var line in File.ReadAllLines(filePath))
        {
            var parts = line.Split('=');
            if (parts.Length == 2)
            {
                envVariables[parts[0].Trim()] = parts[1].Trim();
            }
        }
    }

    public string GetEnvVariable(string key, string defaultValue = null)
    {
        return envVariables.TryGetValue(key, out var value) ? value : defaultValue;
    }
}

