```java
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import javax.mail.*;
import javax.mail.internet.*;
import org.apache.commons.dbcp2.BasicDataSource;
import com.external.logging.service.LoggingServiceClient;

public class FileProcessingSystem {

    private static final List<String> CRITICAL_KEYWORDS = Arrays.asList("error", "critical", "warning");
    private Path[] directoriesToMonitor;
    private ExecutorService executorService = Executors.newCachedThreadPool();
    private BasicDataSource dataSource = new BasicDataSource();

    public FileProcessingSystem(Path[] directories) {
        this.directoriesToMonitor = directories;
        setupDatabaseConnection();
        startMonitoringDirectories();
    }

    private void setupDatabaseConnection() {
        dataSource.setUrl("jdbc:h2:~/test");
        dataSource.setUsername("sa");
        dataSource.setPassword("");
        // Additional configurations
    }

    private void startMonitoringDirectories() {
        for (Path directory : directoriesToMonitor) {
            try {
                Files.walkFileTree(directory, new SimpleFileVisitor<Path>() {
                    @Override
                    public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                        if (file.toString().endsWith(".log")) {
                            executorService.submit(() -> processLogFile(file));
                        }
                        return FileVisitResult.CONTINUE;
                    }
                });
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void processLogFile(Path logFile) {
        try (BufferedReader reader = Files.newBufferedReader(logFile)) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (CRITICAL_KEYWORDS.stream().anyMatch(line::contains)) {
                    storeScanResult(line, logFile);
                    generateAlerts(line, logFile);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void storeScanResult(String line, Path logFile) throws SQLException {
        try (Connection conn = dataSource.getConnection()) {
            String sql = "INSERT INTO scan_results (file_path, content) VALUES (?, ?)";
            try (PreparedStatement stmt = conn.prepareStatement(sql)) {
                stmt.setString(1, logFile.toString());
                stmt.setString(2, line);
                stmt.executeUpdate();
            }
        }
    }

    private void generateAlerts(String line, Path logFile) throws IOException {
        LoggingServiceClient client = new LoggingServiceClient("API_KEY");
        try {
            client.publishAlert(line, logFile.toString());

            // Send notifications
            sendEmailNotification("alerts@example.com", "Critical Alert", line);
            sendSMSNotification("+1234567890", line);

        } catch (ExternalServiceRateLimitException e) {
            handleRateLimit(e);
        } finally {
            client.close();
        }
    }

    private void sendEmailNotification(String to, String subject, String content) throws MessagingException {
        Session session = Session.getDefaultInstance(new Properties());
        Message message = new MimeMessage(session);
        message.setFrom(new InternetAddress("noreply@example.com"));
        message.setRecipients(Message.RecipientType.TO, InternetAddress.parse(to));
        message.setSubject(subject);
        message.setText(content);

        Transport.send(message);
    }

    private void sendSMSNotification(String phoneNumber, String content) {
        // Implementation for sending SMS
    }

    private void handleRateLimit(Exception e) {
        // Retry logic or backoff strategies
    }

    public static void main(String[] args) {
        Path[] directories = { Paths.get("/var/log/app1"), Paths.get("/var/log/app2") };
        new FileProcessingSystem(directories);
    }
}

class ExternalServiceRateLimitException extends Exception {
    // Custom exception for handling rate limits
}
```

