```rust
use reqwest::{Client as ReqwestClient, Response, StatusCode};
use serde::Serialize;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use redis::{AsyncCommands, Client as RedisClient, Error as RedisError};
use log::{error, info};
use thiserror::Error;

#[derive(Error, Debug)]
pub enum WeatherClientError {
    #[error("Network error: {0}")]
    NetworkError(#[from] reqwest::Error),
    #[error("Redis error: {0}")]
    RedisError(#[from] RedisError),
    #[error("Token refresh failed")]
    TokenRefreshFailed,
    #[error("Unexpected server response: {0:?}")]
    ServerResponse(reqwest::StatusCode),
}

struct WeatherClientConfig {
    client_id: String,
    client_secret: String,
    scope: String,
    token_refresh_url: String,
}

struct QueryParams {
    location: String,
    units: String,
    start_date: Option<String>,
    end_date: Option<String>,
}

struct OAuthToken {
    access_token: String,
    expires_at: std::time::SystemTime,
}

#[derive(Debug)]
pub struct WeatherRequestBuilder {
    client: ReqwestClient,
    config: Arc<WeatherClientConfig>,
    token: Arc<Mutex<Option<OAuthToken>>>,
    cache: Arc<Mutex<HashMap<String, Response>>>,
}

impl WeatherRequestBuilder {
    async fn new(config: WeatherClientConfig) -> Result<Self, WeatherClientError> {
        let client = ReqwestClient::new();

        let redis_client = RedisClient::open("redis://127.0.0.1/")?;
        let cache = Arc::new(Mutex::new(HashMap::new()));

        Ok(Self {
            client,
            config: Arc::new(config),
            token: Arc::new(Mutex::new(None)),
            cache,
        })
    }

    async fn get_oauth_token(&self) -> Result<OAuthToken, WeatherClientError> {
        let mut token = self.token.lock().await;
        if let Some(token_info) = &*token {
            if token_info.expires_at > std::time::SystemTime::now() {
                return Ok(token_info.clone());
            }
        }

        let client_id = &self.config.client_id;
        let client_secret = &self.config.client_secret;
        let scope = &self.config.scope;

        let response = self
            .client
            .post(&self.config.token_refresh_url)
            .form(&[
                ("grant_type", "client_credentials"),
                ("client_id", client_id),
                ("client_secret", client_secret),
                ("scope", scope),
            ])
            .send()
            .await?;

        let status = response.status();
        if status != StatusCode::OK {
            return Err(WeatherClientError::ServerResponse(status));
        }

        let json: serde_json::Value = response.json().await?;
        let access_token = json["access_token"].as_str().ok_or_else(|| WeatherClientError::TokenRefreshFailed)?;

        let expires_in_secs = json["expires_in"].as_i64().unwrap_or(3600) as u64;
        let expires_at = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_err(|_| WeatherClientError::TokenRefreshFailed)?
            .checked_add(std::time::Duration::new(expires_in_secs, 0))
            .ok_or_else(|| WeatherClientError::TokenRefreshFailed)?;

        let new_token = OAuthToken {
            access_token: access_token.to_string(),
            expires_at,
        };

        *token = Some(new_token.clone());

        Ok(new_token)
    }

    async fn build_request_url(&self, params: &QueryParams) -> Result<String, WeatherClientError> {
        let base_url = "https://api.weather-service.com/data";

        let mut url = format!("{}/?location={}&units={}", base_url, params.location, params.units);
        if let Some(start_date) = &params.start_date {
            url.push_str(&format!("&start_date={}", start_date));
        }
        if let Some(end_date) = &params.end_date {
            url.push_str(&format!("&end_date={}", end_date));
        }

        Ok(url)
    }

    async fn fetch_weather_data(
        &self,
        request_url: String,
        token: OAuthToken,
    ) -> Result<Response, WeatherClientError> {
        let mut headers = reqwest::header::HeaderMap::new();
        headers.insert(reqwest::header::AUTHORIZATION, format!("Bearer {}", token.access_token).parse()?);

        self.client
            .get(&request_url)
            .headers(headers)
            .send()
            .await
    }

    async fn get_cached_response(
        &self,
        cache_key: &str,
    ) -> Result<Option<Response>, WeatherClientError> {
        let mut cache = self.cache.lock().await;
        Ok(cache.get(cache_key).cloned())
    }

    async fn set_cache_response(&self, cache_key: String, response: Response) {
        let mut cache = self.cache.lock().await;
        cache.insert(cache_key, response);
    }

    pub async fn make_request(
        &self,
        params: QueryParams,
        success_callback: Box<dyn Fn(Response) + Send + Sync>,
        error_callback: Box<dyn Fn(WeatherClientError) + Send + Sync>,
    ) {
        let request_url = self.build_request_url(&params).unwrap_or_else(|err| {
            error!("Failed to build request URL: {:?}", err);
            error_callback(err);
            return;
        });

        let cache_key = format!("{:?}-{}", &params, request_url);

        if let Some(cached_response) = self.get_cached_response(&cache_key).await.unwrap_or(None) {
            info!("Returning cached response");
            success_callback(cached_response);
            return;
        }

        let token = match self.get_oauth_token().await {
            Ok(token) => token,
            Err(err) => {
                error!("Failed to get OAuth token: {:?}", err);
                error_callback(err);
                return;
            }
        };

        let response_result = self.fetch_weather_data(request_url, token).await;

        match response_result {
            Ok(response) => {
                if response.status() == StatusCode::UNAUTHORIZED {
                    error!("Unauthorized request, refreshing token and retrying...");
                    self.make_request(params, success_callback.clone(), error_callback.clone()).await;
                    return;
                }

                let cache_key = format!("{:?}-{}", &params, request_url);
                self.set_cache_response(cache_key, response.clone()).await;

                match response.status() {
                    StatusCode::OK => success_callback(response),
                    status => {
                        error!("Received unexpected server response: {:?}", status);
                        error_callback(WeatherClientError::ServerResponse(status));
                    }
                }
            }
            Err(err) => {
                error!("Failed to fetch weather data: {:?}", err);
                error_callback(err);
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), WeatherClientError> {
    env_logger::init();

    let config = WeatherClientConfig {
        client_id: "your_client_id".to_string(),
        client_secret: "your_client_secret".to_string(),
        scope: "weather:read".to_string(),
        token_refresh_url: "https://api.weather-service.com/token".to_string(),
    };

    let params = QueryParams {
        location: "New York".to_string(),
        units: "metric".to_string(),
        start_date: Some("2023-10-01".to_string()),
        end_date: Some("2023-10-07".to_string()),
    };

    let client = WeatherRequestBuilder::new(config).await?;

    client.make_request(
        params,
        Box::new(|response| {
            println!("Success: {:?}", response);
        }),
        Box::new(|err| {
            eprintln!("Error: {:?}", err);
        }),
    ).await;

    Ok(())
}
