    cleanup_crypto_library();

    return 0;
}

// Implementations

void init_crypto_library() {
    pthread_mutex_init(&global_lock, NULL);
    global_ctx = EVP_CIPHER_CTX_new();
}

int set_cipher_mode(CipherMode mode) {
    pthread_mutex_lock(&global_lock);
    switch (mode) {
        case MODE_ECB:
            EVP_EncryptInit_ex(global_ctx, EVP_aes_256_ecb(), NULL, NULL, NULL);
            break;
        case MODE_CBC:
            EVP_EncryptInit_ex(global_ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
            break;
        case MODE_CFB:
            EVP_EncryptInit_ex(global_ctx, EVP_aes_256_cfb1(), NULL, NULL, NULL);
            break;
        case MODE_XTS:
            // Placeholder for XTS mode initialization
            handle_error("XTS mode not supported in this example");
            return 0;
        default:
            handle_error("Unsupported cipher mode");
            return 0;
    }
    pthread_mutex_unlock(&global_lock);
    return 1;
}

CryptoContext* create_context() {
    CryptoContext *context = malloc(sizeof(CryptoContext));
    if (!context) {
        handle_error("Failed to allocate memory for context");
        return NULL;
    }

    context->ctx = EVP_CIPHER_CTX_new();
    pthread_mutex_init(&context->lock, NULL);
    return context;
}

int encrypt_decrypt(int is_encrypt, const unsigned char *input, size_t input_len,
                    unsigned char *output, size_t *output_len, CryptoContext *context) {
    int len, ciphertext_len;

    if (is_encrypt) {
        EVP_EncryptInit_ex(context->ctx, NULL, NULL, global_ctx->key, global_ctx->iv);
        if (!EVP_EncryptUpdate(context->ctx, output, &len, input, input_len)) return 0;
        ciphertext_len = len;
        if (!EVP_EncryptFinal_ex(context->ctx, output + len, &len)) return 0;
        ciphertext_len += len;
    } else {
        EVP_DecryptInit_ex(context->ctx, NULL, NULL, global_ctx->key, global_ctx->iv);
        if (!EVP_DecryptUpdate(context->ctx, output, &len, input, input_len)) return 0;
        *output_len = len;
        if (!EVP_DecryptFinal_ex(context->ctx, output + len, &len)) return 0;
        *output_len += len;
    }

    *output_len = ciphertext_len;
    pthread_mutex_lock(&context->lock);
    pthread_mutex_unlock(&context->lock);
    return 1;
}

int handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

void cleanup_crypto_library() {
    EVP_CIPHER_CTX_free(global_ctx);
    pthread_mutex_destroy(&global_lock);
}
