const rateLimit = require('express-rate-limit');

// Load configuration
const config = require('./config.json');

// Initialize express app
const app = express();
app.use(express.json());

// Redis client setup for caching
const redisClient = redis.createClient(config.redis);
const getAsync = promisify(redisClient.get).bind(redisClient);

// Dynamically load C++ encryption library using OpenSSL
const ffi = require('ffi-napi');
const pathToCppLibrary = path.resolve(__dirname, config.cppLibraryPath);
const encryptionLib = ffi.Library(pathToCppLibrary, {
  'encryptData': ['string', ['string']],
  'decryptData': ['string', ['string']],
});

// Rate limiter
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: config.rateLimits.requestsPerWindow,
});

app.use(apiLimiter);

// Middleware for logging and error handling
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path}`);
  next();
});

// Helper function to encrypt data using the C++ library
function encryptData(data) {
  return encryptionLib.encryptData(data);
}

// Function to get weather data from OpenWeatherMap API
async function fetchWeatherData(location) {
  try {
    const response = await axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${location}&appid=${config.openWeatherMapApiKey}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching weather data:', error);
    throw new Error('Failed to fetch weather data');
  }
}

// Function to get climate data from Climate API
async function fetchClimateData(location) {
  try {
    const response = await axios.get(`https://api.climate.com/v1/${location}`, {
      headers: { Authorization: `Bearer ${config.climateApiKey}` },
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching climate data:', error);
    throw new Error('Failed to fetch climate data');
  }
}

// Endpoint for getting weather and climate data
app.get('/data', async (req, res) => {
  const { location } = req.query;

  if (!location) {
    return res.status(400).send('Location query parameter is required');
  }

  try {
    // Check cache first
    const cachedData = await getAsync(location);
    if (cachedData) {
      return res.json(JSON.parse(cachedData));
    }

    // Fetch data from APIs
    const [weatherData, climateData] = await Promise.all([
      fetchWeatherData(location),
      fetchClimateData(location),
    ]);

    // Combine and encrypt data
    const combinedData = { weather: weatherData, climate: climateData };
    const encryptedData = encryptData(JSON.stringify(combinedData));

    // Cache the result
    redisClient.setex(location, config.cacheTTL, JSON.stringify(encryptedData));

    res.json({ data: encryptedData });
  } catch (error) {
    res.status(500).send(error.message);
  }
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
