```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>
#include <opencv2/opencv.hpp>

#define MAX_IMAGES_PER_PDF 10

typedef struct {
    char input_dir[256];
    char output_dir[256];
    int max_images;
    int num_threads;
} Config;

typedef struct {
    std::vector<cv::Mat> images;
    int start_index;
    int end_index;
    const char *output_file;
} ThreadData;

void log_message(const char *message) {
    printf("%s\n", message);
}

void* process_images(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    cv::Mat combined_image;

    for (int i = data->start_index; i < data->end_index; ++i) {
        if (i >= data->images.size()) break;
        if (combined_image.empty()) {
            combined_image = data->images[i];
        } else {
            int h1 = combined_image.rows;
            int h2 = data->images[i].rows;
            int w = combined_image.cols + data->images[i].cols;

            cv::Mat temp(h1 > h2 ? h1 : h2, w, CV_8UC3);
            temp.setTo(cv::Scalar(255, 255, 255));
            cv::Rect roi(0, 0, combined_image.cols, combined_image.rows);
            combined_image.copyTo(temp(roi));
            cv::Rect roi2(combined_image.cols, 0, data->images[i].cols, data->images[i].rows);
            data->images[i].copyTo(temp(roi2));

            combined_image = temp;
        }
    }

    std::vector<int> compression_params;
    compression_params.push_back(cv::IMWRITE_PDF_COMPRESSION_LEVEL);
    compression_params.push_back(9);

    cv::imwrite(data->output_file, combined_image, compression_params);
    log_message("PDF generated.");
    return NULL;
}

void load_images(const char* dir, std::vector<cv::Mat>& images) {
    DIR *dp;
    struct dirent *dirp;
    if ((dp = opendir(dir)) == NULL) {
        log_message("Error opening directory");
        exit(1);
    }

    while ((dirp = readdir(dp))) {
        if (strcmp(dirp->d_name, ".") != 0 && strcmp(dirp->d_name, "..") != 0) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", dir, dirp->d_name);

            cv::Mat image = cv::imread(path);
            if (!image.empty()) {
                images.push_back(image);
                log_message((std::string("Loaded: ") + std::string(dirp->d_name)).c_str());
            }
        }
    }

    closedir(dp);
}

void create_pdfs(Config config, const std::vector<cv::Mat>& images) {
    int total_images = images.size();
    int pdf_count = (total_images + config.max_images - 1) / config.max_images;
    pthread_t threads[config.num_threads];
    ThreadData thread_data[config.num_threads];

    for (int i = 0; i < pdf_count; ++i) {
        char output_path[256];
        snprintf(output_path, sizeof(output_path), "%s/output_%d.pdf", config.output_dir, i + 1);

        int images_in_pdf = ((i == pdf_count - 1) ? total_images % config.max_images : config.max_images);
        int start_index = i * config.max_images;
        int end_index = start_index + images_in_pdf;

        for (int j = 0; j < config.num_threads && j * config.max_images / config.num_threads < images_in_pdf; ++j) {
            thread_data[j].images.assign(images.begin() + start_index + (j * images_in_pdf / config.num_threads),
                                         images.begin() + start_index + ((j + 1) * images_in_pdf / config.num_threads));
            thread_data[j].start_index = start_index + (j * images_in_pdf / config.num_threads);
            thread_data[j].end_index = start_index + ((j + 1) * images_in_pdf / config.num_threads);
            thread_data[j].output_file = output_path;

            if (pthread_create(&threads[j], NULL, process_images, &thread_data[j]) != 0) {
                log_message("Failed to create thread");
                exit(1);
            }
        }

        for (int j = 0; j < config.num_threads && j * config.max_images / config.num_threads < images_in_pdf; ++j) {
            pthread_join(threads[j], NULL);
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        printf("Usage: %s <input_dir> <output_dir> <max_images_per_pdf> <num_threads>\n", argv[0]);
        return 1;
    }

    Config config;
    strncpy(config.input_dir, argv[1], sizeof(config.input_dir));
    strncpy(config.output_dir, argv[2], sizeof(config.output_dir));
    config.max_images = atoi(argv[3]);
    config.num_threads = atoi(argv[4]);

    std::vector<cv::Mat> images;
    load_images(config.input_dir, images);
    create_pdfs(config, images);

    return 0;
}
```

