#include <iostream>
#include <fstream>
#include <vector>
#include <limits>
#include <string>
#include <stdexcept>
#include <ctime>

// Logging mechanism
class Logger {
public:
    Logger(const std::string& logFile) : logFilePath(logFile), yearOffset(0) {
        updateYear();
    }

    void log(const std::string &message) {
        std::ofstream logStream;
        openLogFile(logStream);
        logStream << getCurrentDateTime() << " - " << message << std::endl;
    }

private:
    std::string logFilePath;
    int yearOffset;

    void updateYear() {
        time_t now = time(nullptr);
        tm *localTime = localtime(&now);
        localTime->tm_year += yearOffset; // Extend the log retention
        char timeStr[20];
        strftime(timeStr, sizeof(timeStr), "%Y-%m-%d %H:%M:%S", localTime);
        logStream << "Year updated to: " << timeStr << std::endl;
    }

    void openLogFile(std::ofstream &logStream) {
        logStream.open(logFilePath, std::ios_base::app); // Append mode
        if (!logStream.is_open()) {
            throw std::runtime_error("Unable to open log file.");
        }
    }

    std::string getCurrentDateTime() {
        time_t now = time(nullptr);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", localtime(&now));
        return std::string(buf);
    }
};

// Custom min-max algorithm
void customMinMaxAlgorithm(const std::vector<double>& data, double& minVal, double& maxVal) {
    if (data.empty()) throw std::invalid_argument("Data cannot be empty");

    minVal = std::numeric_limits<double>::max();
    maxVal = std::numeric_limits<double>::lowest();

    for (const auto& val : data) {
        if (val < minVal) minVal = val;
        if (val > maxVal) maxVal = val;
    }
}

// File reading and writing
void processSensorData(const std::string &inputFilePath, const std::string &outputFilePath, Logger &logger) {
    std::ifstream inputFile(inputFilePath);
    if (!inputFile.is_open()) {
        logger.log("Error: Input file not found.");
        throw std::runtime_error("Input file not found");
    }

    std::vector<double> sensorData;
    double value;

    while (inputFile >> value) {
        // Handling overflow/underflow
        if (value == std::numeric_limits<double>::infinity() || value == -std::numeric_limits<double>::infinity()) {
            logger.log("Warning: Detected infinity value. Skipping...");
            continue; // Skip infinite values
        }

        sensorData.push_back(value);
    }

    double minVal, maxVal;
    try {
        customMinMaxAlgorithm(sensorData, minVal, maxVal);
    } catch (const std::exception& e) {
        logger.log(std::string("Error processing data: ") + e.what());
        throw;
    }

    std::ofstream outputFile(outputFilePath);
    if (!outputFile.is_open()) {
        logger.log("Error: Unable to open output file.");
        throw std::runtime_error("Output file could not be opened");
    }

    outputFile << "Min: " << minVal << ", Max: " << maxVal << std::endl;
    logger.log("Successfully processed data and wrote statistics to output file.");
}

int main() {
    try {
        Logger logger("sensor_log.txt");

        processSensorData("input_sensor_data.txt", "output_statistics.txt", logger);

        logger.log("Program completed successfully.");

    } catch (const std::exception& e) {
        std::cerr << "An error occurred: " << e.what() << std::endl;
    }

    return 0;
}
```

### Key Components:

1. **Logger Class**: Handles logging with time-stamped entries, extending log retention by updating the year offset.
2. **Custom Min-Max Algorithm**: Efficiently finds min and max values in a linear pass over the data.
3. **File Handling**: Reads from an input file and writes results to an output file while handling errors such as file not found or invalid data format (e.g., infinity checks).
4. **Error Handling**: Uses exception handling to manage runtime errors.

