#define MAX_ELEMENTS 1000
#define RETRY_LIMIT 3

typedef struct {
    int crcflag;
    char rx_ue_information_tag[256];
    unsigned long rnti;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char db_connection_details[256];
    int retry_threshold;
    size_t memory_limit; // In bytes
} DBConfig;

// Function prototypes
void *fetch_database_data(void *arg);
NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int list_size, DBConfig config, FILE *log_file, int compress);
int connect_to_db(const char *connection_details);
char* fetch_rx_ue_information_tag();
unsigned long fetch_rnti();
int validate_crcflag(int crcflag);
void log_message(FILE *log_file, const char *message);

// Thread-safe queue and lock for database operations
pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t db_cond = PTHREAD_COND_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int list_size, DBConfig config, FILE *log_file, int compress) {
    if (list_size > MAX_ELEMENTS || list_size <= 0) {
        log_message(log_file, "Invalid list size");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfa_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size);
    if (!nfa_list) {
        log_message(log_file, "Memory allocation failed");
        return NULL;
    }

    pthread_t db_threads[MAX_ELEMENTS];
    int i;

    for (i = 0; i < list_size; ++i) {
        DBConfig thread_config = config;
        pthread_create(&db_threads[i], NULL, fetch_database_data, &thread_config);
    }

    for (i = 0; i < list_size; ++i) {
        pthread_join(db_threads[i], NULL);
    }

    // Compress if required
    if (compress) {
        // Compression logic here
    }

    return nfa_list;
}

void *fetch_database_data(void *arg) {
    DBConfig config = *(DBConfig *)arg;
    int retries = 0;

    while (retries < config.retry_threshold) {
        pthread_mutex_lock(&db_lock);

        if (connect_to_db(config.db_connection_details)) {
            char *rx_ue_tag = fetch_rx_ue_information_tag();
            unsigned long rnti = fetch_rnti();

            if (!rx_ue_tag || rnti == 0) {
                log_message(NULL, "Invalid data fetched from DB");
                pthread_mutex_unlock(&db_lock);
                retries++;
                continue;
            }

            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.crcflag = rand() % 2; // Simulate fetching CRCFLAG
            if (!validate_crcflag(pdu.crcflag)) {
                log_message(NULL, "Invalid CRCFLAG value");
                free(rx_ue_tag);
                pthread_mutex_unlock(&db_lock);
                retries++;
                continue;
            }

            strncpy(pdu.rx_ue_information_tag, rx_ue_tag, sizeof(pdu.rx_ue_information_tag) - 1);
            pdu.rnti = rnti;

            // Assume storing or processing the PDU
            free(rx_ue_tag);

            pthread_mutex_unlock(&db_lock);
            break;
        } else {
            pthread_mutex_unlock(&db_lock);
            retries++;
        }
    }

    if (retries == config.retry_threshold) {
        log_message(NULL, "Failed to fetch data after retries");
    }

    return NULL;
}

int connect_to_db(const char *connection_details) {
