import org.springframework.web.bind.annotation.RestController;
import java.util.concurrent.CompletableFuture;
import org.springframework.cache.CacheManager;
import org.springframework.beans.factory.annotation.Autowired;

@SpringBootApplication
public class PokemonServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(PokemonServiceApplication.class, args);
    }
}

@RestController
class PokemonController {

    @Autowired
    private CacheManager cacheManager;

    @GetMapping("/pokemon/details")
    public CompletableFuture<ResponseEntity<PokemonDetails>> getPokemonDetails(@RequestParam("id") String pokemonId) {
        return CompletableFuture.supplyAsync(() -> {
            PokemonDetails cachedData = (PokemonDetails) cacheManager.getCache("pokemon").get(pokemonId, null);
            if (cachedData != null) {
                return ResponseEntity.ok(cachedData);
            }

            try {
                PokemonDetails details = fetchAndProcessPokemonData(pokemonId);
                cacheManager.getCache("pokemon").put(pokemonId, details);
                return ResponseEntity.ok(details);
            } catch (Exception e) {
                // Handle errors and fallbacks
                return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).build();
            }
        });
    }

    private PokemonDetails fetchAndProcessPokemonData(String pokemonId) throws Exception {
        // Fetch data from external APIs asynchronously, handle JSON/XML parsing
        // Example pseudo-code:
        CompletableFuture<PokemonInfo> pokemonInfoFuture = fetchFromExternalApi(pokemonId);
        CompletableFuture<Weaknesses> weaknessesFuture = fetchFromExternalApi(pokemonId + "/weaknesses");
        CompletableFuture<EvolutionChain> evolutionFuture = fetchFromExternalApi(pokemonId + "/evolution");
        CompletableFuture<HabitatDetails> habitatFuture = fetchFromExternalApi(pokemonId + "/habitat");

        // Wait for all futures to complete and combine results
        return pokemonInfoFuture.thenCombine(weaknessesFuture,
                (pokemonInfo, weaknesses) -> {
                    try {
                        EvolutionChain evolution = evolutionFuture.get();
                        HabitatDetails habitat = habitatFuture.get();
                        return new PokemonDetails(pokemonInfo, weaknesses, evolution, habitat);
                    } catch (Exception e) {
