import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class NetworkDataFetcher {

    private static final Logger logger = Logger.getLogger(NetworkDataFetcher.class.getName());
    private final Map<String, CachedData> cache = new ConcurrentHashMap<>();
    private final long cacheAgeThresholdMillis;
    private final ObjectMapper objectMapper = new ObjectMapper(new JsonFactory());

    public NetworkDataFetcher(long cacheAgeThresholdMillis) {
        this.cacheAgeThresholdMillis = cacheAgeThresholdMillis;
    }

    // Retrieve JSON from the URL and cache it
    public synchronized String fetchJson(String urlString) throws IOException {
        Path cacheFile = Paths.get("cache", urlString.replaceAll("[^a-zA-Z0-9]", "_") + ".json");

        if (Files.exists(cacheFile)) {
            long lastModified = Files.getLastModifiedTime(cacheFile).toMillis();
            if (System.currentTimeMillis() - lastModified < cacheAgeThresholdMillis) {
                return new String(Files.readAllBytes(cacheFile));
            }
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        try {
            connection.setConnectTimeout(5000);  // Set timeout
            connection.setRequestMethod("GET");

            if (connection.getResponseCode() == HttpURLConnection.HTTP_OK) {
                String jsonResponse;
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                    jsonResponse = reader.lines().collect(Collectors.joining("\n"));
                }

                Files.createDirectories(cacheFile.getParent());
                Files.write(cacheFile, jsonResponse.getBytes());

                return jsonResponse;
            } else {
                throw new IOException("Failed to fetch data: " + connection.getResponseMessage());
            }
        } finally {
            connection.disconnect();
        }
    }

    // Process and filter financial data
    public static List<FinancialDataPoint> filterAndProcessFinancialData(String json, List<String> filteringCriteria) throws JsonProcessingException {
        if (json == null || json.isEmpty() || filteringCriteria == null) {
            throw new IllegalArgumentException("Invalid input JSON or filtering criteria");
        }

        JsonNode rootNode = objectMapper.readTree(json);
        List<FinancialDataPoint> filteredDataPoints = new ArrayList<>();

        // Process the JSON data
        for (JsonNode node : rootNode) {
            boolean matchesCriteria = true;
            for (String criterion : filteringCriteria) {
                if (!matchesCriterion(node, criterion)) {
                    matchesCriteria = false;
                    break;
                }
            }

            if (matchesCriteria) {
                filteredDataPoints.add(new FinancialDataPoint(
                        node.get("stockSymbol").asText(),
                        node.get("price").asDouble()
                        // Add other necessary fields here
                ));
            }
        }

        return filteredDataPoints;
    }

    private static boolean matchesCriterion(JsonNode dataNode, String criterion) {
        // Implement custom logic to match criteria with the node attributes
        return true;  // Placeholder implementation
    }

    public void runConcurrentFetchers(List<String> urls) {
        ExecutorService executor = Executors.newFixedThreadPool(10);  // Adjust thread pool size as needed

        for (String url : urls) {
            executor.submit(() -> {
                try {
                    String data = fetchJson(url);
                    logger.info("Fetched and cached data from: " + url);
                } catch (IOException e) {
                    logger.severe("Failed to fetch data from URL: " + url + ", Error: " + e.getMessage());
                }
            });
        }

        executor.shutdown();
    }

    // Inner class for caching mechanism
