class FileProcessor {

    private final AmazonS3 s3Client;

    public FileProcessor(AmazonS3 s3Client) {
        this.s3Client = s3Client;
    }

    public CompletableFuture<Void> processFilesAsync(List<String> bucketNames, List<String> keywords, Charset encoding) {
        return CompletableFuture.allOf(
            bucketNames.stream()
                .map(bucket -> CompletableFuture.runAsync(() -> processBucket(bucket, keywords, encoding)))
                .toArray(CompletableFuture[]::new)
        );
    }

    private void processBucket(String bucketName, List<String> keywords, Charset encoding) {
        try (S3Object s3Object = s3Client.getObject(new GetObjectRequest(bucketName, "your-file-key"))) {
            BufferedReader reader = new BufferedReader(
                new InputStreamReader(s3Object.getObjectContent(), encoding != null ? encoding : StandardCharsets.UTF_8)
            );
            String line;
            while ((line = reader.readLine()) != null) {
                for (String keyword : keywords) {
                    if (line.contains(keyword)) {
                        // Process the line and generate a summary report
                        logger.info("Keyword found: " + keyword);
                    }
                }
            }
        } catch (IOException e) {
            logger.severe("Error processing file from bucket: " + bucketName);
        }
    }

    public void uploadReport(String report, String format) {
        // Implement API integration with retry mechanism
        int maxRetries = 3;
        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                // Call external reporting API
                logger.info("Uploading report in " + format);
                break;
            } catch (Exception e) {
                if (attempt == maxRetries - 1) {
                    logger.severe("Failed to upload report after retries");
                }
            }
        }
    }
}
