```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <sys/wait.h>
#include <time.h>

typedef struct {
    const char *inputDir;
    const char *outputDir;
    size_t maxPagesPerPdf;
    int numThreads;
    float outputResolution;
    const char **excludedFiles;
    size_t excludedCount;
    pthread_mutex_t progressMutex;
    double totalFiles;
    double processedFiles;
} ConversionContext;

typedef struct {
    ConversionContext *context;
    char inputFile[256];
    char outputFile[256];
    int timeoutSec;
} ThreadData;

void* convertBatch(void* arg) {
    ThreadData *data = (ThreadData*)arg;
    pid_t pid;
    int status;
    double progressStart, progressEnd;

    snprintf(data->outputFile, sizeof(data->outputFile), "%s/output_%d.pdf", data->context->outputDir, rand());

    // Prepare command
    char cmd[1024];
    snprintf(cmd, sizeof(cmd),
             "convert -density %.2f \"%s\" \"%s\"",
             data->context->outputResolution,
             data->inputFile,
             data->outputFile);

    // Execute command with timeout
    if ((pid = fork()) == 0) {
        alarm(data->timeoutSec);
        execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
        _exit(EXIT_FAILURE); // If exec fails
    } else if (pid > 0) {
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            pthread_mutex_lock(&data->context->progressMutex);
            progressStart = data->context->processedFiles;
            data->context->processedFiles++;
            progressEnd = data->context->processedFiles / data->context->totalFiles * 100.0;
            printf("Progress: %.2f%%\n", progressEnd);
            pthread_mutex_unlock(&data->context->progressMutex);
        } else {
            fprintf(stderr, "Conversion process failed for %s\n", data->inputFile);
            return (void*)EXIT_FAILURE;
        }
    } else {
        perror("fork");
        return (void*)EXIT_FAILURE;
    }

    _exit(EXIT_SUCCESS);
}

int isExcluded(const char *filename, const char **excludedFiles, size_t excludedCount) {
    for (size_t i = 0; i < excludedCount; ++i) {
        if (strcmp(filename, excludedFiles[i]) == 0)
            return 1;
    }
    return 0;
}

int isValidImageFile(const char *filename) {
    const char *exts[] = {".jpg", ".jpeg", ".png"};
    size_t extCount = sizeof(exts) / sizeof(exts[0]);

    for (size_t i = 0; i < extCount; ++i) {
        if (strstr(filename, exts[i]) == filename + strlen(filename) - strlen(exts[i]))
            return 1;
    }
    return 0;
}

int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf,
                          int numThreads, float outputResolution, int timeoutSec,
                          const char **excludedFiles, size_t excludedCount) {

    // Check if input directory exists
    struct stat st;
    if (stat(inputDir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        perror("Input directory does not exist or is not a directory");
        return EXIT_FAILURE;
    }

    // Check if output directory exists, create if necessary
    if (stat(outputDir, &st) != 0) {
        if (mkdir(outputDir, 0777) != 0) {
            perror("Failed to create output directory");
            return EXIT_FAILURE;
        }
    }

    ConversionContext context = {inputDir, outputDir, maxPagesPerPdf, numThreads,
                                 outputResolution, excludedFiles, excludedCount,
                                 PTHREAD_MUTEX_INITIALIZER, 0.0, 0.0};

    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(inputDir)) == NULL) {
        perror("Failed to open directory");
        return EXIT_FAILURE;
    }

    size_t fileCount = 0;
    while ((entry = readdir(dir)) != NULL) {
        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", inputDir, entry->d_name);

        if (isValidImageFile(entry->d_name) && !isExcluded(entry->d_name, excludedFiles, excludedCount))
            fileCount++;
    }

    closedir(dir);

    context.totalFiles = fileCount;
    pthread_t threads[numThreads];
    ThreadData threadData[numThreads];

    dir = opendir(inputDir);
    if (dir == NULL) {
        perror("Failed to open directory");
        return EXIT_FAILURE;
    }

    int i = 0, j = 0;
    while ((entry = readdir(dir)) != NULL) {
        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", inputDir, entry->d_name);

        if (isValidImageFile(entry->d_name) && !isExcluded(entry->d_name, excludedFiles, excludedCount)) {
            snprintf(threadData[j].inputFile, sizeof(threadData[j].inputFile), filepath);
            threadData[j].context = &context;
            threadData[j].timeoutSec = timeoutSec;

            if (pthread_create(&threads[i], NULL, convertBatch, &threadData[j]) != 0) {
                perror("Failed to create thread");
                closedir(dir);
                return EXIT_FAILURE;
            }

            i = (i + 1) % numThreads;
            j++;
            if (j == numThreads || fileCount - j < maxPagesPerPdf) {
                for (int k = 0; k < numThreads && k < j; ++k) {
                    pthread_join(threads[k], NULL);
                }
                i = 0;
            }
        }
    }

    closedir(dir);

    return 0;
}

// Example usage
int main() {
    const char *excluded[] = {"exclude1.jpg", "exclude2.png"};
    return batchConvertJpegToPdf("input_dir", "output_dir", 10, 4, 300.0f, 30, excluded, 2);
}
```

