// Drone class representing a drone in the fleet
class Drone {
private:
    int id;
    GPSService gpsService;
    std::vector<std::string> payloadData;
    bool isAvailable;

public:
    Drone(int id) : id(id), isAvailable(true) {}

    void performSurvey(const SurveyRequest& request) {
        if (!isWeatherSuitable()) {
            std::cout << "Weather not suitable for drone " << id << std::endl;
            return;
        }

        // Simulate survey
        gpsService.updateLocation(0.0, 0.0);
        payloadData.push_back("Survey Data");

        // Upload data to cloud
        CloudStorageService().uploadData(payloadData.back());
    }

private:
