// SurveyRequest class representing a survey task
class SurveyRequest {
public:
    std::string location;
    int priority;

    SurveyRequest(const std::string& loc, int pri) : location(loc), priority(pri) {}
};

// FleetManager to manage drones and distribute tasks
class FleetManager {
private:
    std::vector<std::shared_ptr<Drone>> drones;
    std::queue<SurveyRequest> requestQueue;
    std::mutex queueMutex;
    std::condition_variable cv;

public:
    FleetManager(const std::vector<int>& droneIds) {
        for (int id : droneIds) {
            drones.emplace_back(std::make_shared<Drone>(id));
        }
    }

    void addSurveyRequest(const SurveyRequest& request) {
        std::lock_guard<std::mutex> lock(queueMutex);
        requestQueue.push(request);
        cv.notify_one();
    }

    void distributeTasks() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !requestQueue.empty(); });

            for (auto& drone : drones) {
                if (!drone->isAvailable) continue;

                auto request = requestQueue.front();
                requestQueue.pop();

                std::thread([drone, request]() {
                    drone->performSurvey(request);
                    drone->isAvailable = false;
                }).detach();
            }
        }
    }
};

int main() {
    FleetManager fleet({1, 2, 3});

    // Add survey requests
    fleet.addSurveyRequest(SurveyRequest("LocationA", 1));
    fleet.addSurveyRequest(SurveyRequest("LocationB", 2));

    // Start task distribution in a separate thread
    std::thread distributor(&FleetManager::distributeTasks, &fleet);

    distributor.join();
    return 0;
}
```

