### Hybrid C/PHP Application

**C Code (main.c):**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    float offset_avg;
    float key_avg;
} Record;

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open file");
        return;
    }

    char line[256];
    Record *records = NULL;
    size_t record_count = 0;

    while (fgets(line, sizeof(line), file)) {
        int id;
        float offset, key;

        if (sscanf(line, "%d %f %f", &id, &offset, &key) == 3) {
            records = realloc(records, (record_count + 1) * sizeof(Record));

            Record new_record = {id, offset, key};
            records[record_count++] = new_record;
        }
    }

    fclose(file);

    // Calculate averages
    for (size_t i = 0; i < record_count; ++i) {
        records[i].offset_avg = records[i].offset;
        records[i].key_avg = records[i].key;

        if (i > 0 && records[i].id == records[i - 1].id) {
            records[i - 1].offset_avg += records[i].offset;
            records[i - 1].key_avg += records[i].key;
            records[i - 1].offset_avg /= 2.0f;
            records[i - 1].key_avg /= 2.0f;
        }
    }

    // Free memory
    free(records);
}

int main() {
    process_file("data.txt");
    return 0;
}
```

