### C# `DynamicValueGenerator` Class

```csharp
using UnityEngine;

public enum DistributionType { Uniform, Gaussian, Exponential }

public class DynamicValueGenerator {
    private DistributionType currentDistribution;
    private float distributionParam1;
    private float distributionParam2;

    public void SetDistribution(DistributionType type, float param1, float param2) {
        currentDistribution = type;
        distributionParam1 = param1;
        distributionParam2 = param2;
    }

    public int GenerateInt(int minInclusive, int maxExclusive) {
        switch (currentDistribution) {
            case DistributionType.Uniform:
                return Random.Range(minInclusive, maxExclusive);
            case DistributionType.Gaussian:
                float mean = distributionParam1;
                float stddev = distributionParam2;
                return Mathf.RoundToInt(UnityEngine.Random.value * stddev + mean);
            case DistributionType.Exponential:
                // Exponential distribution logic using param1 as lambda
                float scale = 1.0f / distributionParam1;
                return (int)(-Mathf.Log(Random.value) * scale);
            default:
                throw new System.InvalidOperationException("Unsupported distribution type.");
        }
    }

    public float GenerateFloat(float minInclusive, float maxExclusive) {
        switch (currentDistribution) {
            case DistributionType.Uniform:
                return Random.Range(minInclusive, maxExclusive);
            case DistributionType.Gaussian:
                float mean = distributionParam1;
                float stddev = distributionParam2;
                return Random.value * stddev + mean;
            case DistributionType.Exponential:
                // Exponential distribution logic using param1 as lambda
                float scale = 1.0f / distributionParam1;
                return -Mathf.Log(Random.value) * scale;
            default:
                throw new System.InvalidOperationException("Unsupported distribution type.");
        }
    }

    public static void Main(string[] args) {
        // Example usage
        DynamicValueGenerator generator = new DynamicValueGenerator();
        generator.SetDistribution(DistributionType.Gaussian, 10.0f, 5.0f);

        int randomInt = generator.GenerateInt(0, 100);
        float randomFloat = generator.GenerateFloat(0.0f, 1.0f);

        Debug.Log($"Random Int: {randomInt}, Random Float: {randomFloat}");
    }
}
