// Constants for DES modes
#define MODE_ECB 1
#define MODE_EDE 2
#define MODE_EDE3 3
#define MODE_CFB 4

typedef struct {
    int mode;
    EVP_CIPHER_CTX *ctx;
} EncryptionContext;

// Function prototypes
int initialize_context(EncryptionContext *context, const unsigned char *key, const unsigned char *iv, int mode);
void finalize_context(EncryptionContext *context);
int encrypt_data(EncryptionContext *context, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len);
int decrypt_data(EncryptionContext *context, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len);

// Key management and PEM functions
char* fetch_private_key_and_cert(const char *location);
void write_to_pem_file(const char *filename, const char *data);
int handle_error(const char *error_message);

// Main function to demonstrate usage
int main() {
    // Example: Encrypt data using DES in ECB mode
    unsigned char key[8] = "secretK";
    unsigned char iv[8] = {0};  // Not used in ECB mode
    unsigned char plaintext[] = "Sensitive Data";
    int ciphertext_len, plaintext_len;
    unsigned char *ciphertext = malloc(strlen((char*)plaintext) + EVP_MAX_BLOCK_LENGTH);

    EncryptionContext context;
    if (initialize_context(&context, key, iv, MODE_ECB) != 1) {
        return handle_error("Failed to initialize encryption context");
    }

    int encrypted = encrypt_data(&context, plaintext, strlen((char*)plaintext), ciphertext, &ciphertext_len);
    if (!encrypted) {
        finalize_context(&context);
        return handle_error("Encryption failed");
    }

    unsigned char decrypted[1024];
    if (decrypt_data(&context, ciphertext, ciphertext_len, decrypted, &plaintext_len) != 1) {
        finalize_context(&context);
        return handle_error("Decryption failed");
    }

    printf("Original: %s\n", plaintext);
    printf("Decrypted: %.*s\n", plaintext_len, decrypted);

    free(ciphertext);
    finalize_context(&context);
    return 0;
}

// Initialize encryption context
int initialize_context(EncryptionContext *context, const unsigned char *key, const unsigned char *iv, int mode) {
    context->ctx = EVP_CIPHER_CTX_new();
    if (!context->ctx) return 0;

    switch (mode) {
        case MODE_ECB:
            if (!EVP_EncryptInit_ex(context->ctx, EVP_des_ecb(), NULL, key, iv)) return 0;
            break;
        case MODE_EDE:
            if (!EVP_EncryptInit_ex(context->ctx, EVP_des_ede3(), NULL, key, iv)) return 0;
            break;
        case MODE_EDE3:
            if (!EVP_EncryptInit_ex(context->ctx, EVP_des_cbc(), NULL, key, iv)) return 0;
            break;
        case MODE_CFB:
            if (!EVP_EncryptInit_ex(context->ctx, EVP_des_cfb64(), NULL, key, iv)) return 0;
            break;
        default:
            EVP_CIPHER_CTX_free(context->ctx);
            return 0;
    }
    context->mode = mode;
    return 1;
}

// Finalize encryption context
void finalize_context(EncryptionContext *context) {
    if (context->ctx) {
        EVP_CIPHER_CTX_free(context->ctx);
        context->ctx = NULL;
    }
}

// Encrypt data function
int encrypt_data(EncryptionContext *context, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len) {
    if (!EVP_EncryptUpdate(context->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len)) return 0;
    int len2 = 0;
    if (!EVP_EncryptFinal_ex(context->ctx, ciphertext + *ciphertext_len, &len2)) return 0;
    *ciphertext_len += len2;
    return 1;
}

// Decrypt data function
int decrypt_data(EncryptionContext *context, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len) {
    if (!EVP_DecryptUpdate(context->ctx, plaintext, plaintext_len, ciphertext, ciphertext_len)) return 0;
    int len2 = 0;
    if (!EVP_DecryptFinal_ex(context->ctx, plaintext + *plaintext_len, &len2)) return 0;
    *plaintext_len += len2;
    return 1;
}

// Fetch private key and certificate
char* fetch_private_key_and_cert(const char *location) {
    // Placeholder for actual implementation to fetch keys from a specified location
    return strdup("-----BEGIN PRIVATE KEY-----\n...\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n...\n-----END CERTIFICATE-----");
}

// Write data to PEM file
void write_to_pem_file(const char *filename, const char *data) {
    FILE *file = fopen(filename, "w");
    if (!file) return;
    fputs(data, file);
    fclose(file);
}

// Error handling function
int handle_error(const char *error_message) {
    fprintf(stderr, "%s\n", error_message);
    return 1;
}
```

