```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileComparator
{
    private readonly HashSet<string> _excludedExtensions = new HashSet<string>
    {
        // Add extensions to exclude, e.g., ".tmp", ".log"
    };

    public Dictionary<string, string> CompareDirectories(string dirPath1, string dirPath2)
    {
        var differences = new ConcurrentDictionary<string, string>();
        Parallel.ForEach(GetFilesInDirectory(dirPath1), file1 =>
        {
            try
            {
                string relativePath = Path.GetRelativePath(dirPath1, file1);
                string file2 = Path.Combine(dirPath2, relativePath);

                if (!File.Exists(file2) || IsExcluded(file1))
                    differences.TryAdd(file1, "File does not exist in second directory or is excluded.");
                else
                {
                    var checksum1 = CalculateFileChecksum(file1);
                    var checksum2 = CalculateFileChecksum(file2);

                    if (checksum1 != checksum2)
                        differences.TryAdd(file1, "Checksum mismatch.");
                }
            }
            catch (Exception ex) when (!(ex is OperationCanceledException))
            {
                Console.WriteLine($"Error processing {file1}: {ex.Message}");
            }
        });

        Parallel.ForEach(GetFilesInDirectory(dirPath2), file2 =>
        {
            try
            {
                string relativePath = Path.GetRelativePath(dirPath2, file2);
                string file1 = Path.Combine(dirPath1, relativePath);

                if (!File.Exists(file1) && !IsExcluded(file2))
                    differences.TryAdd(file2, "File does not exist in first directory.");
            }
            catch (Exception ex) when (!(ex is OperationCanceledException))
            {
                Console.WriteLine($"Error processing {file2}: {ex.Message}");
            }
        });

        return differences.ToDictionary(pair => pair.Key, pair => pair.Value);
    }

    private IEnumerable<string> GetFilesInDirectory(string directory)
    {
        if (!Directory.Exists(directory))
            throw new DirectoryNotFoundException($"The directory '{directory}' was not found.");

        return Directory.GetFiles(directory, "*.*", SearchOption.AllDirectories);
    }

    private string CalculateFileChecksum(string filePath)
    {
        using (var sha256 = SHA256.Create())
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hashBytes = sha256.ComputeHash(stream);
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }
        }
    }

    private bool IsExcluded(string filePath)
    {
        string extension = Path.GetExtension(filePath)?.ToLowerInvariant();
        return _excludedExtensions.Contains(extension);
    }
}
```

### Explanation:
- **ConcurrentDictionary**: Used to store differences in a thread-safe manner.
- **Parallel.ForEach**: Enables parallel processing of files for performance enhancement.
- **GetFilesInDirectory**: Gathers all file paths within a directory recursively.
- **CalculateFileChecksum**: Computes SHA-256 checksums for files.
- **IsExcluded**: Checks if a file should be excluded based on its extension.
- **Exception Handling**: Catches exceptions during I/O operations, except `OperationCanceledException` to allow cancellation propagation.

