    char *output_file;
    char *config_file;
    int max_speed; // bytes per second
} Config;

Config config;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long processed_bytes = 0;
FILE *status_log, *resource_profile_log;

// Function prototypes
