```python
import os
import logging
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor, as_completed
from PIL import Image
import boto3
import slack_sdk
import json

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ImageAnalyzer:
    def __init__(self, directories, s3_bucket, notification_channel):
        self.directories = directories
        self.s3_client = boto3.client('s3')
        self.notification_channel = notification_channel
        self.slack_client = slack_sdk.WebClient(token='your-slack-bot-token')

    def process_directory(self):
        all_images = []
        for directory in self.directories:
            all_images.extend(self._get_image_files(directory))
        return all_images

    def _get_image_files(self, directory):
        image_extensions = ['.jpg', '.jpeg', '.png', '.webp']
        return [os.path.join(directory, f) for f in os.listdir(directory)
                if os.path.splitext(f)[1].lower() in image_extensions]

    def analyze_images(self):
        images = self.process_directory()
        results = []

        with ThreadPoolExecutor(max_workers=10) as executor:
            future_to_image = {executor.submit(self._analyze_image, img): img for img in images}
            for future in as_completed(future_to_image):
                image_path = future_to_image[future]
                try:
                    data = future.result()
                    if data:
                        results.append(data)
                except Exception as exc:
                    logger.error('%r generated an exception: %s' % (image_path, exc))
        return results

    def _analyze_image(self, image_path):
        try:
            with Image.open(image_path) as img:
                metadata = {
                    'path': image_path,
                    'format': img.format,
                    'size': img.size,
                    'mode': img.mode
                }
                exif_data = img._getexif()
                if exif_data:
                    metadata['exif'] = {TAGS.get(tag, tag): value for (tag, value) in exif_data.items()}

            return metadata

        except Exception as e:
            logger.error(f"Error processing image {image_path}: {e}")
            return None

    def filter_results(self, results, criteria):
        filtered = []
        for result in results:
            if all(criteria.get(key)(result[key]) for key in criteria if key in result):
                filtered.append(result)
        return filtered

    def upload_report_to_s3(self, report_data):
        try:
            response = self.s3_client.put_object(
                Bucket='your-s3-bucket-name',
                Key=f'reports/{datetime.now().strftime("%Y%m%d%H%M%S")}_report.json',
                Body=json.dumps(report_data).encode('utf-8')
            )
            return response['ETag']
        except Exception as e:
            logger.error(f"Failed to upload report: {e}")
            return None

    def send_notification(self, message):
        try:
            self.slack_client.chat_postMessage(channel=self.notification_channel, text=message)
        except Exception as e:
            logger.error(f"Failed to send notification: {e}")

    def run(self):
        logger.info("Starting image analysis...")
        results = self.analyze_images()
        report_data = {
            'analysis_date': datetime.now().isoformat(),
            'image_count': len(results),
            'images_analyzed': results
        }

        etag = self.upload_report_to_s3(report_data)
        if etag:
            message = f"Image analysis complete. Report available: s3://your-s3-bucket-name/reports/{etag}.json"
            logger.info(message)
            self.send_notification(message)

if __name__ == "__main__":
    directories = ['/path/to/images1', '/path/to/images2']
    analyzer = ImageAnalyzer(directories, 'your-s3-bucket-name', '#slack-channel-id')
    analyzer.run()
```

