    DistributedCache cache;
    init_cache(&cache);

    RateLimiter rate_limiter;
    init_rate_limiter(&rate_limiter, 60); // Allow max 60 requests per minute

    char *token = "sample_token";
    int result = verify_token(token, &cache);
    printf("Verification result: %d\n", result);

    return 0;
}

// Initialize cache
void init_cache(DistributedCache *cache) {
    pthread_mutex_init(&cache->mutex, NULL);
    cache->count = 0;
}

// Set a cache entry
int set_cache_entry(DistributedCache *cache, const char *key, const char *value) {
    pthread_mutex_lock(&cache->mutex);

    if (cache->count >= 10) {
        pthread_mutex_unlock(&cache->mutex);
        return -1; // Cache is full
    }

    for (int i = 0; i < cache->count; ++i) {
        if (strcmp(cache->entries[i].key, key) == 0) {
            free(cache->entries[i].value);
            cache->entries[i].value = strdup(value);
            pthread_mutex_unlock(&cache->mutex);
            return 1;
        }
    }

    CacheEntry entry;
    entry.key = strdup(key);
    entry.value = strdup(value);

    cache->entries[cache->count++] = entry;

    pthread_mutex_unlock(&cache->mutex);
    return 1;
}

// Get a cache entry
char* get_cache_entry(const DistributedCache *cache, const char *key) {
    pthread_mutex_lock((DistributedCache *)cache->mutex); // Cast for const correctness

    for (int i = 0; i < cache->count; ++i) {
        if (strcmp(cache->entries[i].key, key) == 0) {
            char *value = strdup(cache->entries[i].value);
            pthread_mutex_unlock((DistributedCache *)cache->mutex); // Cast for const correctness
            return value;
        }
    }

    pthread_mutex_unlock((DistributedCache *)cache->mutex); // Cast for const correctness
    return NULL;
}

// Initialize rate limiter
void init_rate_limiter(RateLimiter *limiter, int max_requests_per_minute) {
    time(&limiter->last_request_time);
    limiter->request_count = 0;
    limiter->max_requests_per_minute = max_requests_per_minute;
}

// Check rate limit
int check_rate_limit(RateLimiter *limiter) {
    time_t current_time;
    time(&current_time);

    if (difftime(current_time, limiter->last_request_time) > 60) {
        // Reset every minute
        limiter->last_request_time = current_time;
        limiter->request_count = 0;
    }

    if (++limiter->request_count > limiter->max_requests_per_minute) {
        return 1; // Rate limit exceeded
    }

    return 0; // Within rate limits
}
```

