```java
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.security.interfaces.RSAPrivateKey;
import javax.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class JwtController {

    private final KeyManagementService kms;
    private final RedisCache redisCache;
    private final RateLimiter rateLimiter;

    public JwtController(KeyManagementService kms, RedisCache redisCache, RateLimiter rateLimiter) {
        this.kms = kms;
        this.redisCache = redisCache;
        this.rateLimiter = rateLimiter;
    }

    @PostMapping("/generate-jwt")
    public String generateJwt(HttpServletRequest request, @RequestBody AuthCredentials credentials) {
        if (!rateLimiter.isAllowed(credentials.getUserId())) {
            throw new TooManyRequestsException("Rate limit exceeded");
        }

        RSAPrivateKey privateKey = kms.retrievePrivateKey();
        String token = Jwts.builder()
                .setSubject(credentials.getUserId())
                .claim("roles", credentials.getRoles())
                .signWith(privateKey, SignatureAlgorithm.RS256)
                .compact();

        redisCache.storeToken(token);
        return token;
    }
}
```

