```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/pem.h>

// Define constants for encryption modes
typedef enum {
    ECB_MODE,
    EDE_MODE,
    EDE3_MODE,
    CFB_MODE
} EncryptionMode;

// Function prototypes
int initialize_cipher_context(EVP_CIPHER_CTX **ctx, const char *key, int key_len, EncryptionMode mode);
void finalize_cipher_context(EVP_CIPHER_CTX *ctx);
int encrypt_data(const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext,
                 EVP_CIPHER_CTX *ctx, int use_null_encryption);
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext,
                 EVP_CIPHER_CTX *ctx);

// KMS integration
char* retrieve_key_from_kms(const char *key_id);

// Thread-safe key management and data processing
pthread_mutex_t key_lock;

void initialize_library() {
    pthread_mutex_init(&key_lock, NULL);
}

void cleanup_library() {
    pthread_mutex_destroy(&key_lock);
}

int main() {
    initialize_library();

    // Example usage
    const char *key_id = "example-key-id";
    char *key = retrieve_key_from_kms(key_id);

    if (key) {
        EVP_CIPHER_CTX *ctx;
        unsigned char ciphertext[128];
        unsigned char plaintext[128] = "This is a test message.";

        initialize_cipher_context(&ctx, key, strlen(key), ECB_MODE);
        encrypt_data(plaintext, strlen((char *)plaintext), ciphertext, ctx, 0);
        finalize_cipher_context(ctx);

        EVP_CIPHER_CTX *decrypt_ctx;
        unsigned char decryptedtext[128];
        initialize_cipher_context(&decrypt_ctx, key, strlen(key), ECB_MODE);
        decrypt_data(ciphertext, sizeof(ciphertext), decryptedtext, decrypt_ctx);
        finalize_cipher_context(decrypt_ctx);

        printf("Decrypted text is: %s\n", decryptedtext);
    }

    cleanup_library();
    return 0;
}

int initialize_cipher_context(EVP_CIPHER_CTX **ctx, const char *key, int key_len, EncryptionMode mode) {
    EVP_CIPHER *cipher;

    pthread_mutex_lock(&key_lock);

    *ctx = malloc(sizeof(EVP_CIPHER_CTX));
    if (!*ctx) {
        perror("Failed to allocate context");
        pthread_mutex_unlock(&key_lock);
        return -1;
    }

    switch (mode) {
        case ECB_MODE:
            cipher = EVP_des_ecb();
            break;
        case EDE_MODE:
            cipher = EVP_des_ede3();
            break;
        case EDE3_MODE:
            cipher = EVP_des_ede3(); // Adjust for actual EDE mode
            break;
        case CFB_MODE:
            cipher = EVP_des_cfb64();
            break;
    }

    if (!EVP_EncryptInit_ex(*ctx, cipher, NULL, (unsigned char *)key, NULL)) {
        perror("Cipher initialization failed");
        free(*ctx);
        pthread_mutex_unlock(&key_lock);
        return -1;
    }

    pthread_mutex_unlock(&key_lock);
    return 0;
}

void finalize_cipher_context(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_cleanup(ctx);
    free(ctx);
}

int encrypt_data(const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext,
                 EVP_CIPHER_CTX *ctx, int use_null_encryption) {
    if (use_null_encryption) {
        memcpy(ciphertext, plaintext, plaintext_len);
        return 0;
    }

    int len;
    int ciphertext_len;

    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        perror("Encryption update failed");
        return -1;
    }
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        perror("Encryption finalization failed");
        return -1;
    }
    ciphertext_len += len;

    return ciphertext_len;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext,
                 EVP_CIPHER_CTX *ctx) {
    int len;
    int plaintext_len;

    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        perror("Decryption update failed");
        return -1;
    }
    plaintext_len = len;

    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        perror("Decryption finalization failed");
        return -1;
    }
    plaintext_len += len;

    return plaintext_len;
}

char* retrieve_key_from_kms(const char *key_id) {
    // Simulate KMS key retrieval
    pthread_mutex_lock(&key_lock);

    // Implement actual KMS interaction here

    char *key = strdup("example-key"); // Replace with actual key from KMS

    pthread_mutex_unlock(&key_lock);
    return key;
}
