import json
import xml.etree.ElementTree as ET
from abc import ABC, abstractmethod

# Base Serializer Class for JSON, XML, CSV serialization formats
class Serializer(ABC):
    @abstractmethod
    def serialize(self, data):
        pass

    @abstractmethod
    def deserialize(self, data):
        pass


class JsonSerializer(Serializer):
    def serialize(self, data):
        return json.dumps(data)

    def deserialize(self, data):
        return json.loads(data)


class XmlSerializer(Serializer):
    def serialize(self, data):
        root = ET.Element("root")
        for key, value in data.items():
            child = ET.SubElement(root, key)
            child.text = str(value)
        return ET.tostring(root).decode()

    def deserialize(self, data):
        root = ET.fromstring(data)
        return {child.tag: child.text for child in root}


class CppSerializationLibrary:
    _serializers = {
        'json': JsonSerializer(),
        'xml': XmlSerializer(),
        # Implement CSV Serializer here
    }

    @classmethod
    def get_serializer(cls, format_name):
        if format_name not in cls._serializers:
            raise ValueError(f"Unsupported serialization format: {format_name}")
        return cls._serializers[format_name]


class RealTimeStockMiddleware:
