using Microsoft.Extensions.Caching.Memory;
using MicroAuthService.API.Models;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace MicroAuthService.API.Services
{
    public class ConfigurationService : IConfigurationService
    {
        private readonly IMemoryCache _cache;
        private readonly HttpClient _httpClient;
        private readonly string _apiEndpoint = "https://external-api.com/validation-rules";

        public ConfigurationService(IMemoryCache cache, IHttpClientFactory httpClientFactory)
        {
            _cache = cache;
            _httpClient = httpClientFactory.CreateClient();
        }

        public async Task<ValidationRules> GetValidationRulesAsync()
        {
            if (!_cache.TryGetValue("ValidationRules", out ValidationRules rules))
            {
                var response = await _httpClient.GetAsync(_apiEndpoint);
                response.EnsureSuccessStatusCode();

                rules = JsonConvert.DeserializeObject<ValidationRules>(await response.Content.ReadAsStringAsync());
                _cache.Set("ValidationRules", rules, TimeSpan.FromMinutes(5)); // Cache for 5 minutes
            }

            return rules;
        }

        public Task UpdateValidationRulesAsync(ValidationRules rules)
        {
            // Logic to update cached rules if necessary
            _cache.Set("ValidationRules", rules, new MemoryCacheEntryOptions { SlidingExpiration = TimeSpan.FromMinutes(5) });
            return Task.CompletedTask;
        }
    }
}
