Below is a basic outline of how you might implement such an application in Java, using some popular libraries like `HttpClient` for RESTful API interactions, `ExecutorService` for multi-threading, and a simple caching mechanism.

```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.concurrent.*;
import java.util.Map;
import java.util.HashMap;

public class RealTimeDataSyncApp {
    private static final String API_URL = "https://api.example.com/data";
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);
    private Map<String, CachedData> cache = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private long syncIntervalSeconds;

    public RealTimeDataSyncApp(long syncIntervalSeconds) {
        this.syncIntervalSeconds = syncIntervalSeconds;
    }

    public void start() {
        scheduler.scheduleAtFixedRate(this::syncData, 0, syncIntervalSeconds, TimeUnit.SECONDS);
    }

    private void syncData() {
        executorService.submit(() -> {
            try {
                HttpRequest request = HttpRequest.newBuilder()
                        .uri(URI.create(API_URL))
                        .build();

                HttpResponse<String> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());

                // Assume JSON data; implement parsing logic
                String responseData = response.body(); 

                processData(responseData);

            } catch (Exception e) {
                e.printStackTrace();
            }
        });
    }

    private void processData(String data) {
        // Parse and process data

        String cacheKey = "data-key"; // Define your caching key strategy
        if (!cache.containsKey(cacheKey) || isCacheExpired(cacheKey)) {
            CachedData cachedData = new CachedData(data, System.currentTimeMillis());
            cache.put(cacheKey, cachedData);
        }
    }

    private boolean isCacheExpired(String cacheKey) {
        CachedData data = cache.get(cacheKey);
        // Custom expiration logic
        return (System.currentTimeMillis() - data.timestamp > 60000); // e.g., 1 minute
    }

    public void stop() {
        scheduler.shutdown();
        executorService.shutdown();
    }

    private static class CachedData {
        String data;
        long timestamp;

        CachedData(String data, long timestamp) {
            this.data = data;
            this.timestamp = timestamp;
        }
    }

    public static void main(String[] args) {
        RealTimeDataSyncApp app = new RealTimeDataSyncApp(10); // Sync every 10 seconds
        app.start();

        Runtime.getRuntime().addShutdownHook(new Thread(app::stop));
    }
}
```

