use std::process::{Command, Output};
use std::time::Instant;
use sync_lazy::SyncLazy;

#[derive(Debug)]
struct CompilationReport {
    compilation_time_ms: u64,
    rss_before_bytes: usize,
    rss_after_bytes: usize,
    warnings_and_errors: Vec<String>,
    ice_hooks_status: Vec<bool>,
}

fn measure_rss() -> usize {
    Command::new("ps")
        .arg("-o")
        .arg("rss=")
        .output()
        .unwrap()
        .stdout
        .as_slice()
        .iter()
        .map(|&b| b.to_digit(10).unwrap_or(0) as usize * 1024)
        .sum()
}

fn compile_rust_sources(paths: Vec<String>) -> Vec<CompilationReport> {
    let ice_hooks = SyncLazy::new(|| vec![]);

    paths.into_iter().map(|path| {
        let mut report = CompilationReport {
            compilation_time_ms: 0,
            rss_before_bytes: measure_rss(),
            warnings_and_errors: Vec::new(),
            ice_hooks_status: Vec::new(),
        };

        for hook in &ice_hooks.get() {
            // Simulating hook installation
            report.ice_hooks_status.push(true); // Assume success for demonstration
        }

        let start_time = Instant::now();

        rustc_driver::catch_with_exit_code(move || {
            Command::new("rustc")
                .arg(&path)
                .output()
                .expect("Failed to execute rustc");

            Ok(())
        }).map_err(|e| e.to_string());

        report.compilation_time_ms = start_time.elapsed().as_millis() as u64;
        report.rss_after_bytes = measure_rss();

        if let Output { stderr, .. } = Command::new("rustc")
            .arg(&path)
            .output()
            .expect("Failed to execute rustc") {

            report.warnings_and_errors.extend(
                String::from_utf8_lossy(&stderr)
                    .lines()
                    .filter(|line| line.contains("warning:") || line.contains("error:"))
                    .map(String::from)
            );
        }

        report
    }).collect()
}

fn main() {
    let paths = vec![
        "src/main.rs".to_string(),
        "src/lib.rs".to_string(),
    ];

    let reports = compile_rust_sources(paths);

    for report in reports {
        println!("{:?}", report);
    }
}
