```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <shared_mutex>
#include <thread>
#include <atomic>

class SpatialHashGrid {
public:
    struct Point {
        float x, y, z;
        Point(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
    };

private:
    std::vector<std::shared_mutex> gridMutexes_;
    std::unordered_map<size_t, std::vector<Point>> grid_;
    size_t bucketSizeX_, bucketSizeY_, bucketSizeZ_;
    int maxEntriesPerBucket_;
    std::atomic<bool> initialized_;

    size_t computeHash(const Point& point) const {
        return static_cast<size_t>(point.x / bucketSizeX_) ^ 
               (static_cast<size_t>(point.y / bucketSizeY_) << 1) ^
               (static_cast<size_t>(point.z / bucketSizeZ_) << 2);
    }

public:
    SpatialHashGrid(size_t bucketSizeX, size_t bucketSizeY, size_t bucketSizeZ, int maxEntriesPerBucket)
        : bucketSizeX_(bucketSizeX), bucketSizeY_(bucketSizeY), bucketSizeZ_(bucketSizeZ),
          maxEntriesPerBucket_(maxEntriesPerBucket), initialized_(false) {}

    void initialize(size_t gridResolution) {
        gridMutexes_.resize(gridResolution);
        grid_.reserve(gridResolution);
        for (auto& pair : grid_) {
            pair.second.reserve(maxEntriesPerBucket_);
        }
        initialized_ = true;
    }

    bool insertPoint(const Point& point) {
        if (!initialized_) {
            std::cerr << "Error: SpatialHashGrid not initialized." << std::endl;
            return false;
        }

        size_t hashValue = computeHash(point);
        auto& bucket = grid_[hashValue];

        std::unique_lock lock(gridMutexes_[hashValue]);

        if (bucket.size() < maxEntriesPerBucket_) {
            bucket.push_back(point);
            return true;
        } else {
            std::cerr << "Error: Bucket full for point (" << point.x << ", " << point.y << ", " << point.z << ")." << std::endl;
            return false;
        }
    }

    std::vector<Point> queryPoints(float minX, float minY, float minZ, 
                                   float maxX, float maxY, float maxZ) const {
        std::vector<Point> results;

        for (float x = minX; x <= maxX; x += bucketSizeX_) {
            for (float y = minY; y <= maxY; y += bucketSizeY_) {
                for (float z = minZ; z <= maxZ; z += bucketSizeZ_) {
                    size_t hashValue = computeHash(Point(x, y, z));

                    std::shared_lock lock(gridMutexes_[hashValue]);

                    const auto& bucket = grid_.at(hashValue);
                    results.insert(results.end(), bucket.begin(), bucket.end());
                }
            }
        }

        return results;
    }

    // Additional methods for stress testing and error handling can be added here
};

// Example usage in a multithreaded environment
void insertPoints(SpatialHashGrid& grid, const std::vector<SpatialHashGrid::Point>& points) {
    for (const auto& point : points) {
        if (!grid.insertPoint(point)) {
            std::cerr << "Failed to insert point (" << point.x << ", " << point.y << ", " << point.z << ")." << std::endl;
        }
    }
}

int main() {
    SpatialHashGrid grid(1.0f, 1.0f, 1.0f, 10);

    size_t resolution = 100; // Example grid resolution
    grid.initialize(resolution);

    std::vector<SpatialHashGrid::Point> pointsToInsert = {
        {0.5f, 0.5f, 0.5f}, {2.3f, 1.4f, 0.7f}, {-1.2f, -0.8f, 0.9f}
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(insertPoints, std::ref(grid), pointsToInsert);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    auto results = grid.queryPoints(0.0f, 0.0f, 0.0f, 5.0f, 5.0f, 5.0f);

    std::cout << "Queried points count: " << results.size() << std::endl;

    return 0;
}
```

