#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256

// Function to check if the input filename is valid.
int isValidFilename(const char *filename) {
    // Check for empty string and allowed characters (alphanumeric, dot, underscore).
    if (strlen(filename) == 0 || strpbrk(filename, "./\\:;*?<>|") != NULL)
        return 0;

    for (char *c = filename; *c; c++) {
        if (!isalnum(*c) && *c != '.' && *c != '_')
            return 0;
    }
    return 1;
}

// Function to count the number of digits in a string.
int countDigits(const char *str) {
    int count = 0;
    while (*str) {
        if (isdigit(*str))
            count++;
        str++;
    }
    return count;
}

// Main function to modify the filename based on given criteria.
char* modifyFileName(const char *filename) {
    // Validate input filename
    if (!isValidFilename(filename)) {
        fprintf(stderr, "Invalid filename.\n");
        return NULL;
    }

    char *base = strdup(filename);
    char *dot = strrchr(base, '.');

    // Set the extension based on conditions
    int digits = countDigits(base);
    char new_extension[4] = {0};

    if (digits == 3) {
        strcpy(new_extension, "jpg");
    } else if (digits == 4) {
        strcpy(new_extension, "png");
    } else if (digits == 0) {
        strcpy(new_extension, "txt");
    } else if (digits > 4) {
        char truncated[6] = {0};
        strncpy(truncated, base, 5);
        sprintf(base, "%s.bmp", truncated);
        free(strdup(filename));
        return strdup(base);
    }

    // Modify the file extension
    if (dot != NULL) {
        *dot = '\0';
    }
    char new_filename[MAX_FILENAME_LENGTH];
    sprintf(new_filename, "%s.%s", base, new_extension);

    char *result = strdup(new_filename);
    free(base);  // Free dynamically allocated memory

    return result;
}

// Unit tests for the modifyFileName function.
void testModifyFileName() {
    struct TestCase {
        const char* input;
        const char* expected_output;
    };

    struct TestCase test_cases[] = {
        {"file123", "file123.jpg"},
        {"image4567", "image4567.png"},
        {"document", "document.txt"},
        {"data12345.ext", "data123.bmp"},
        {".hiddenfile", NULL},  // Invalid filename
        {NULL, NULL}            // Edge case for null input
    };

    int test_count = sizeof(test_cases) / sizeof(struct TestCase);

    for (int i = 0; i < test_count; ++i) {
        char *result = modifyFileName(test_cases[i].input);

        if (test_cases[i].expected_output == NULL && result == NULL)
            printf("Test %d passed.\n", i+1);
        else if (test_cases[i].expected_output != NULL && result != NULL 
                 && strcmp(result, test_cases[i].expected_output) == 0) {
            printf("Test %d passed.\n", i+1);
            free(result);
        } else {
            printf("Test %d failed: Expected '%s', got '%s'\n", i+1,
                   test_cases[i].expected_output, result ? result : "NULL");
            free(result);
        }
    }
}

int main() {
    testModifyFileName();
    return 0;
}
