pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void process_files(const char **file_paths, int num_files) {
    pthread_t threads[num_files];

    for (int i = 0; i < num_files; ++i) {
        if (pthread_create(&threads[i], NULL, file_reader_thread, (void *)(intptr_t)i)) {
