import time
import logging
from lxml import etree

def fileParserAndProcessor(file_path, xpath_expr, validateNode=None, namespace=None):
    start_time = time.time()

    # Configure logging
    logging.basicConfig(filename='parser_errors.log', level=logging.ERROR)

    processed_data = []

    try:
        # Open the XML file and parse it incrementally to manage memory usage
        context = etree.iterparse(file_path, events=('end',), tag=None, recover=True)

        for event, elem in context:
            if not namespace or elem.tag.startswith(tuple(namespace.keys())):
                xpath_result = elem.xpath(xpath_expr, namespaces=namespace)

                # Process each matching node
                for match_elem in xpath_result:
                    try:
                        # Validate the node if a validation function is provided
                        if validateNode and not validateNode(match_elem):
                            continue

                        data_dict = {child.tag: child.text for child in match_elem}
                        processed_data.append(data_dict)

                    except Exception as e:
                        logging.error(f"Error processing node: {etree.tostring(match_elem, pretty_print=True)} - {str(e)}")

            # Clear the element from memory after processing
            elem.clear()
            while elem.getprevious() is not None:
                del elem.getparent()[0]

    except Exception as e:
        logging.error(f"Error parsing file: {str(e)}")

    end_time = time.time()
    print(f"Processing completed in {end_time - start_time} seconds.")

    return processed_data

