import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Node {
    String content;
    Metadata metadata;
    Node prev;

    Node(String content, Metadata metadata) {
        this.content = content;
        this.metadata = metadata;
    }
}

class Metadata {
    long fileSize;
    long lastModifiedTimestamp;
    String fileName;

    Metadata(long fileSize, long lastModifiedTimestamp, String fileName) {
        this.fileSize = fileSize;
        this.lastModifiedTimestamp = lastModifiedTimestamp;
        this.fileName = fileName;
    }
}

public class FileProcessor {

    private final Queue<String> fileQueue = new ConcurrentLinkedQueue<>();
    private final LinkedList<Node> backwardLinkedList = new LinkedList<>();

    public void processFiles() {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        while (!fileQueue.isEmpty()) {
            String filePath = fileQueue.poll();
            if (filePath != null) {
                executor.submit(() -> {
                    try {
                        retryOperation(3, () -> {
                            File file = new File(filePath);
                            if (file.exists()) {
                                Metadata metadata = getFileMetadata(file);
                                String content = readFileContent(file);

                                // Truncate content
                                if (content.length() > 500) {
                                    content = content.substring(0, 500);
                                }

                                synchronized (backwardLinkedList) {
                                    Node metadataNode = new Node(null, metadata);
                                    Node contentNode = new Node(content, null);

                                    backwardLinkedList.addFirst(metadataNode);
                                    contentNode.prev = metadataNode;
                                    backwardLinkedList.addFirst(contentNode);
                                }
                            }
                        });
                    } catch (Exception e) {
                        System.err.println("Error processing file: " + filePath);
                        e.printStackTrace();
                    }
                });
            }
        }

        executor.shutdown();
    }

    private void retryOperation(int retries, Runnable operation) throws Exception {
        int attempts = 0;
        while (attempts < retries) {
            try {
                operation.run();
                return;
            } catch (Exception e) {
                if (++attempts >= retries) throw e;
                System.err.println("Retrying due to failure: " + e.getMessage());
            }
        }
    }

    private Metadata getFileMetadata(File file) throws Exception {
        long fileSize = file.length();
        long lastModifiedTimestamp = file.lastModified();
        String fileName = file.getName();

        // Simulate integration with external storage system
        // Example: Retrieve additional metadata from Amazon S3

        return new Metadata(fileSize, lastModifiedTimestamp, fileName);
    }

    private String readFileContent(File file) throws Exception {
        byte[] bytes = Files.readAllBytes(Paths.get(file.getPath()));
        return new String(bytes);
    }
}
