use std::fs;
use std::path::Path;
use std::process::{Command, ExitStatus};
use std::time::{Duration, Instant};
use sync_lazy::SyncLazy;
use rustc_driver::{catch_with_exit_code, RunCompiler};
use sysinfo::{System, SystemExt};

// Define a constant for the maximum allowed RSS in bytes
const MAX_ALLOWED_RSS: u64 = 500 * 1024 * 1024; // 500 MB

fn main() {
    let source_file_path = "path/to/your/source.rs";
    match compile_rust_source(source_file_path) {
        Ok(exit_code) => println!("Compilation finished with exit code: {}", exit_code),
        Err(e) => eprintln!("Error during compilation: {:?}", e),
    }
}

fn compile_rust_source(path: &str) -> Result<i32, Box<dyn std::error::Error>> {
    let source_file = Path::new(path);
    if !source_file.exists() {
        return Err("Source file does not exist.".into());
    }

    let system = System::new_all();

    // Log initial RSS
    log_rss(&system, "Before compilation");

    let start_time = Instant::now();

    let exit_status: i32 = catch_with_exit_code(move || {
        rustc_driver::install_ice_hook();
        let run_compiler = SyncLazy::lazy(|| RunCompiler::new());

        run_compiler.run(None, &["-o", "output"])
    })?;

    // Log final RSS
    log_rss(&system, "After compilation");

    let duration = start_time.elapsed();
    println!("Compilation of '{}' took {:?}", source_file.to_string_lossy(), duration);

    report_to_build_server(source_file.to_str().unwrap(), exit_status == 0, exit_status)?;

    Ok(exit_status)
}

fn log_rss(system: &System, stage: &str) -> Result<(), Box<dyn std::error::Error>> {
    system.refresh_memory();
    let rss = system.get_process_mem_usage_by_name("rustc")? * 1024; // Convert KB to bytes
    println!("{} RSS: {} bytes", stage, rss);

    if rss > MAX_ALLOWED_RSS {
        eprintln!(
            "RSS exceeded the limit of {} bytes at {}",
            MAX_ALLOWED_RSS,
            stage
        );
        std::process::exit(1);
    }

    Ok(())
}

fn report_to_build_server(
    source_file: &str,
    success: bool,
    exit_code: i32,
) -> Result<(), Box<dyn std::error::Error>> {
    let build_server = env::var("BUILD_SERVER")?;

    match build_server.as_str() {
        "Jenkins" => report_to_jenkins(source_file, success, exit_code),
        "GitHubActions" => report_to_github_actions(source_file, success, exit_code),
        "CircleCI" => report_to_circleci(source_file, success, exit_code),
        _ => Err("Unsupported build server.".into()),
    }
}

