using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Collections.Concurrent;

public class DataLoader<T>
{
    private readonly string _filePath;
    private readonly BinaryFormatter _formatter = new BinaryFormatter();
    private readonly ConcurrentDictionary<int, T> _cache = new ConcurrentDictionary<int, T>();
    private static readonly object _lockObject = new object();

    public DataLoader(string filePath)
    {
        _filePath = filePath;
    }

    public T LoadData(int id)
    {
        if (_cache.TryGetValue(id, out var cachedData))
        {
            Logger.Log($"Cache hit for ID {id}");
            return cachedData;
        }

        lock (_lockObject)
        {
            try
            {
                using (var fileStream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                using (var reader = new BinaryReader(fileStream))
                {
                    // Assuming the first part of the file contains metadata about data entries.
                    long position = ReadEntryPosition(reader);

                    if (position != -1)
                    {
                        fileStream.Position = position;
                        T data = (T)_formatter.Deserialize(fileStream);

                        _cache[id] = data;  // Cache the loaded data

                        Logger.Log($"Data for ID {id} successfully deserialized from file.");
                        return data;
                    }
                }
            }
            catch (FileNotFoundException ex)
            {
                Logger.LogError($"File not found: {ex.Message}");
                throw new ApplicationException("Data source file is missing.", ex);
            }
            catch (SerializationException ex)
            {
                Logger.LogError($"Deserialization error: {ex.Message}");
                throw new ApplicationException("Error during deserialization of data.", ex);
            }
            catch (IOException ex)
            {
                Logger.LogError($"I/O Error: {ex.Message}");
                throw new ApplicationException("Error accessing the data file.", ex);
            }

            Logger.LogWarning($"Data for ID {id} not found.");
            return default;
        }
    }

    private long ReadEntryPosition(BinaryReader reader)
    {
        // Logic to determine position of the data entry in the binary file.
        // This is a placeholder function and should be implemented based on your specific file format.

        try
        {
            if (reader.BaseStream.Length > 0)
            {
                var index = int.Parse(reader.ReadString());
                if (index == id) // Assuming ID corresponds to some integer key in the binary structure
                {
                    return reader.ReadInt64(); // Read position for this data entry
                }
                else
                {
                    return -1;
                }
            }

            return -1;
        }
        catch (Exception ex)
        {
            Logger.LogError($"Error reading file metadata: {ex.Message}");
            return -1;
        }
    }
}

