mod api {
    use warp::{Filter, Rejection, Reply};
    use super::compression::SimpleCompressor;
    use std::sync::Arc;
    use tokio::sync::Mutex;

    pub struct AppState {
        compressor: Arc<Mutex<SimpleCompressor>>,
    }

    impl AppState {
        pub fn new() -> Self {
            AppState { 
                compressor: Arc::new(Mutex::new(SimpleCompressor))
            }
        }

        pub async fn process_image(&self, data: Vec<u8>) -> Result<String, Rejection> {
            let start_time = Instant::now();

            let mut compressor = self.compressor.lock().await;
            let compressed_data = compressor.compress_lossless(&data);

            let duration = start_time.elapsed();
            println!("Compression took {:?}", duration);

            Ok(format!("{{\"compressed_length\": {}}}", compressed_data.len()))
        }
    }

    pub fn with_state(state: AppState) -> impl Filter<Extract = (AppState,), Error = std::convert::Infallible> + Clone {
        warp::any().map(move || state.clone())
    }

    pub async fn image_processor(state: AppState, body: Bytes) -> Result<impl Reply, Rejection> {
        let data = body.to_vec();
        match state.process_image(data).await {
            Ok(response) => Ok(warp::reply::json(&response)),
            Err(_) => Err(warp::reject::not_found()),
        }
    }

    pub fn routes() -> impl Filter<Extract = ((),), Error = Rejection> + Clone {
        let app_state = AppState::new();

        warp::post()
            .and(warp::path("process_image"))
            .and(with_state(app_state.clone()))
            .and(warp::body::bytes())
            .and_then(image_processor)
    }
}

