#include <stdio.h>
#include <stdlib.h>

// Define a struct to hold TIFF image information
typedef struct {
    char* compressionMethod;
    int bitsPerSample[16];
    int samplesPerPixel;
    int numExtraSamples;
    char** extraSampleNames;
} TiffImageInfo;

// Error codes
#define ERROR_SUCCESS 0
#define ERROR_UNSUPPORTED_BITS_PER_SAMPLE -1
#define ERROR_INVALID_TIFF_FILE -2

// Function declarations
int parseTiffImage(const char* filePath, TiffImageInfo* info);
static int readTags(FILE* file, TiffImageInfo* info);

// Main function to parse a TIFF image and extract information
int parseTiffImage(const char* filePath, TiffImageInfo* info) {
    FILE* file = fopen(filePath, "rb");
    if (!file) return ERROR_INVALID_TIFF_FILE;

    // Initialize the info struct with default values
    info->compressionMethod = NULL;
    for (int i = 0; i < 16; ++i) {
        info->bitsPerSample[i] = -1;
    }
    info->samplesPerPixel = 0;
    info->numExtraSamples = 0;
    info->extraSampleNames = NULL;

    int result = readTags(file, info);

    // Clean up
    if (info->compressionMethod) free(info->compressionMethod);
    for (int i = 0; i < info->numExtraSamples; ++i) {
        if (info->extraSampleNames[i]) free(info->extraSampleNames[i]);
    }
    if (info->extraSampleNames) free(info->extraSampleNames);

    fclose(file);
    return result;
}

// Static function to read TIFF tags and populate the TiffImageInfo struct
static int readTags(FILE* file, TiffImageInfo* info) {
    // Assuming a simplified reading mechanism for demonstration purposes
    unsigned short compression = 1; // Example: assume uncompressed
    unsigned short bitsPerSampleCount = 3;
    unsigned short samplePerPixel = 3;

    // Set compression method
    if (compression == 1) {
        char* method = strdup("Uncompressed");
        info->compressionMethod = method;
    } else {
        return ERROR_INVALID_TIFF_FILE; // Unsupported compression for this example
    }

    // Read bits per sample
    unsigned short bitsPerSample[16];
    fread(bitsPerSample, sizeof(unsigned short), bitsPerSampleCount, file);

    if (bitsPerSampleCount > 16) return ERROR_INVALID_TIFF_FILE;

    int validBits = 1;
    for (int i = 0; i < bitsPerSampleCount; ++i) {
        info->bitsPerSample[i] = bitsPerSample[i];

        switch (bitsPerSample[i]) {
            case 1:
            case 2:
            case 4:
            case 8:
            case 16:
                break;
            default:
                validBits = 0;
        }
    }

    if (!validBits) return ERROR_UNSUPPORTED_BITS_PER_SAMPLE;

    info->samplesPerPixel = samplePerPixel;

    // Example: Read extra samples (simplified)
    unsigned short numExtraSamples = 2; // Assume two extra samples
    char* extraSampleNames[2] = {strdup("Transparency"), strdup("Alpha")};

    info->numExtraSamples = numExtraSamples;
    info->extraSampleNames = malloc(sizeof(char*) * numExtraSamples);
    for (int i = 0; i < numExtraSamples; ++i) {
        info->extraSampleNames[i] = extraSampleNames[i];
    }

    return ERROR_SUCCESS;
}

// Example usage
int main() {
    TiffImageInfo info;
    int result = parseTiffImage("example.tiff", &info);

    if (result == ERROR_SUCCESS) {
        printf("Compression Method: %s\n", info.compressionMethod);
        printf("Bits Per Sample: ");
        for (int i = 0; i < 16 && info.bitsPerSample[i] != -1; ++i) {
            printf("%d ", info.bitsPerSample[i]);
        }
        printf("\nSamples Per Pixel: %d\n", info.samplesPerPixel);
        printf("Extra Samples (%d): ", info.numExtraSamples);
        for (int i = 0; i < info.numExtraSamples; ++i) {
            printf("%s ", info.extraSampleNames[i]);
        }
        printf("\n");
    } else if (result == ERROR_UNSUPPORTED_BITS_PER_SAMPLE) {
        fprintf(stderr, "Unsupported bits per sample\n");
    } else if (result == ERROR_INVALID_TIFF_FILE) {
        fprintf(stderr, "Invalid TIFF file or unsupported format\n");
    }

    return 0;
}
```

This C code defines a structure to hold the information about a TIFF image and implements functions to parse a TIFF file. It includes error handling for unsupported bits per sample and invalid TIFF files, returning structured data containing compression methods, bits per sample, samples per pixel, and extra samples information. The function is designed with performance considerations, using dynamic memory allocation only as necessary, and aims at being easily integrable with image processing libraries by providing a clear data structure.

