// C Function: resolveHostname

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/nameser.h>
#include <resolv.h>

#define MAX_DNS_REQUESTS 10
static int active_requests = 0;
#define DNS_BUFFER_SIZE 256

int resolveHostname(const char* hostname, u_char* ip_buffer) {
    if (active_requests >= MAX_DNS_REQUESTS) {
        // External logging mechanism
        printf("Error: Maximum concurrent DNS requests reached.\n");
        return -1; // Error code for resource exhaustion
    }

    active_requests++;
    struct __res_state res_state;
    if (_res_init(&res_state, 0, NULL, _NS_DEFAULT_PORT) != 0) {
        active_requests--;
        printf("Error: DNS initialization failed.\n");
        return -2; // Error code for DNS init failure
    }

    int result = res_query(hostname, C_IN, T_A, (u_char *)ip_buffer, sizeof(ip_buffer), &res_state);
    if (result != 0) {
        active_requests--;
        _res_cleanup(&res_state);
        printf("Error: DNS resolution failed for %s.\n", hostname);
        return -3; // Error code for DNS query failure
    }

    struct dns_msg* response = (struct dns_msg*)ip_buffer;
    if (ntohs(response->header.qr) == 0) {
        active_requests--;
        _res_cleanup(&res_state);
        printf("Error: Invalid DNS response.\n");
        return -4; // Error code for invalid response
    }

    struct dns_rr* answer = &response->answer[0];
    if (ntohs(answer->rr.type) != T_A) {
        active_requests--;
        _res_cleanup(&res_state);
        printf("Error: DNS record type is not A.\n");
        return -5; // Error code for invalid record type
    }

    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, answer->rr.rdata, ip_str, sizeof(ip_str));
    printf("Success: Resolved %s to %s\n", hostname, ip_str);

    active_requests--;
    _res_cleanup(&res_state);
    return 0; // Success
}

