### Python: Distributed Task Queue Manager

```python
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse

class ImageProcessingQueueManager:
    def __init__(self, retry_limit=3):
        self.retry_limit = retry_limit

    def validate_url(self, url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except Exception:
            return False

    def process_images(self, image_urls, initial_status, callback, api_endpoint):
        if not isinstance(image_urls, list):
            raise ValueError("Input must be a list of URLs.")

        processed_statuses = {url: initial_status for url in image_urls}

        with ThreadPoolExecutor() as executor:
            future_to_url = {
                executor.submit(self._process_image_task, url, callback): url
                for url in image_urls if self.validate_url(url)
            }

            for future in as_completed(future_to_url):
                url = future_to_url[future]
                try:
                    result = future.result()
                    processed_statuses[url] = result
                except Exception as e:
                    processed_statuses[url] = str(e)

        # Integrate with external API for results
        self._report_results(api_endpoint, processed_statuses)

        return processed_statuses

    def _process_image_task(self, url, callback):
        attempt = 0
        while attempt < self.retry_limit:
            try:
                return callback(url)
            except Exception as e:
                attempt += 1
                if attempt == self.retry_limit:
                    raise RuntimeError(f"Failed to process {url}: {str(e)}")

    def _report_results(self, api_endpoint, processed_statuses):
        try:
            response = requests.post(api_endpoint, json=processed_statuses)
            response.raise_for_status()
        except Exception as e:
            print(f"Error reporting results: {str(e)}")

# Example callback function
def example_callback(url):
    # Simulate image processing
    return f"{url} processed"

# Example usage
queue_manager = ImageProcessingQueueManager()
image_urls = ["http://example.com/image1.jpg", "invalid_url"]
processed_statuses = queue_manager.process_images(image_urls, "pending", example_callback, "https://api.example.com/results")
print(processed_statuses)
```

