using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class DynamicWeatherMiddleware : IMiddleware
{
    private readonly ConcurrentQueue<UpdateRequest> _updateQueue = new();
    private readonly SemaphoreSlim _semaphore = new(1, 1);
    private WeatherData _currentConditions = new();

    public void ProcessUpdates()
    {
        Task.Run(async () =>
        {
            while (true)
            {
                await _semaphore.WaitAsync();

                if (_updateQueue.TryDequeue(out var updateRequest))
                {
                    try
                    {
                        ApplyUpdate(updateRequest);
                    }
                    catch (Exception ex)
                    {
                        LogError($"Failed to apply weather update: {ex.Message}");
                    }

                    _semaphore.Release();
                }
            }
        });
    }

    public void EnqueueUpdate(UpdateRequest request)
    {
        _updateQueue.Enqueue(request);
    }

    private void ApplyUpdate(UpdateRequest request)
    {
        // Simulate weather data processing
        _currentConditions.Temperature = GetSimulatedTemperature();
        _currentConditions.Humidity = GetSimulatedHumidity();

        // Fetch from APIs if needed
        FetchWeatherDataFromAPIs();

        LogInfo("Weather update applied.");
    }

    private async Task FetchWeatherDataFromAPIs()
    {
        using (var client = new HttpClient())
        {
            try
            {
                var response = await client.GetAsync("https://api.weather.com/data");
                if (response.IsSuccessStatusCode)
                {
                    // Process API data
                }
            }
            catch (Exception ex)
            {
                LogError($"API Fetch Error: {ex.Message}");
            }
        }
    }

    private double GetSimulatedTemperature()
    {
        Random rnd = new();
        return 15 + rnd.NextDouble() * 20; // Simulate temperature range
    }

    private double GetSimulatedHumidity()
    {
        Random rnd = new();
        return 30 + rnd.NextDouble() * 50; // Simulate humidity range
    }

    public override string ToString()
    {
        return $"Current Conditions: {_currentConditions}\nData Source: API & Simulation";
    }

    private void LogInfo(string message)
    {
        Console.WriteLine($"INFO: {message}");
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine($"ERROR: {message}");
    }
}

public interface IMiddleware
{
    void ProcessUpdates();
    void EnqueueUpdate(UpdateRequest request);
}

