using json = nlohmann::json;
using ConfigMap = std::unordered_map<std::string, std::variant<int, double, std::string, bool>>;

class UnionFind {
public:
    UnionFind(size_t size) : parent(size), rank(size, 0) {
        for (size_t i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x) 
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY])
                parent[rootY] = rootX;
            else if (rank[rootX] < rank[rootY])
                parent[rootX] = rootY;
            else {
                parent[rootY] = rootX;
                ++rank[rootX];
            }
        }
    }

private:
    std::vector<int> parent, rank;
};

class ConfigParser {
public:
    static ConfigMap parseConfig(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Unable to open config file");
        }

        json j;
        try {
            file >> j;
        } catch (json::parse_error&) {
            throw std::runtime_error("Failed to parse JSON configuration");
        }

        ConfigMap config;
        for (auto& el : j.items()) {
            if (el.value().is_number_integer())
                config[el.key()] = el.value();
            else if (el.value().is_number_float())
                config[el.key()] = el.value();
            else if (el.value().is_string())
                config[el.key()] = el.value();
            else if (el.value().is_boolean())
                config[el.key()] = el.value();
        }
        return config;
    }
};

void processArray(const std::vector<int>& array) {
    UnionFind uf(array.size());

    for (size_t i = 0; i < array.size(); ++i) {
        for (size_t j = i + 1; j < array.size(); ++j) {
            if (uf.find(i) != uf.find(j)) {
                // Process disjoint pair logic
                uf.unite(i, j);
            }
        }
    }
}

