void executeApiUpdates(const std::vector<json>& users, size_t concurrency_limit) {
    std::vector<std::thread> threads;
    std::mutex active_mutex;
    int active_threads = 0;

    for (const auto& user : users) {
        {
            std::lock_guard<std::mutex> lock(active_mutex);
            if (active_threads >= concurrency_limit)
                continue;
            ++active_threads;
        }

        threads.emplace_back([user] { updateProfile(const_cast<json&>(user)); });

        // Sleep or manage rate limit here
    }

    for (auto& th : threads) {
        if (th.joinable())
            th.join();
    }
}

