#include "distributed_cache.h"      // Distributed cache mechanism

#define MAX_THREADS 500
#define MAX_RETRIES 10
#define RETRY_BACKOFF_BASE 1000   // milliseconds

// Define a structure to hold file processing information
typedef struct {
    char* input_file;
    char* output_file;
    char* config_file;
} FileProcessingInfo;

// Thread function to process a single file
void* process_file(void *arg) {
    FileProcessingInfo* info = (FileProcessingInfo*) arg;
    int retry_count = 0;
    int success = 0;

    while (!success && retry_count < MAX_RETRIES) {
        if (decompress_and_parse(info->input_file, info->output_file, info->config_file)) {
            success = 1;
            logging_service_log("File processed successfully", INFO);
        } else {
            int wait_time = RETRY_BACKOFF_BASE * (1 << retry_count); // Exponential backoff
            sleep(wait_time / 1000);  // Sleep takes seconds as input
            retry_count++;
            logging_service_log("Retrying decompression and parsing due to failure", WARNING);
        }
    }

    if (!success) {
        logging_service_log("File processing failed after maximum retries", ERROR);
    }

    return NULL;
}

// Main function to set up multi-threaded file processing
int main(int argc, char** argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <input_files> <output_directory> <config_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Load configuration for parsing rules and logging service credentials
    load_config(argv[3]);

    // Initialize the distributed cache mechanism
    distributed_cache_init();

    // Prepare threads to process files concurrently
    pthread_t threads[MAX_THREADS];
    FileProcessingInfo* file_infos = malloc(MAX_THREADS * sizeof(FileProcessingInfo));

    int thread_count = 0;
    for (char** input_files = argv + 1; *input_files != NULL && thread_count < MAX_THREADS; ++input_files) {
        char output_file[256];

        // Create a unique output filename in the specified directory
        snprintf(output_file, sizeof(output_file), "%s/%s.out", argv[2], strrchr(*input_files, '/') + 1);

        file_infos[thread_count].input_file = *input_files;
        file_infos[thread_count].output_file = strdup(output_file);
        file_infos[thread_count].config_file = argv[3];

        if (pthread_create(&threads[thread_count], NULL, process_file, &file_infos[thread_count])) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
        thread_count++;
    }

    // Wait for all threads to complete
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup resources
    free(file_infos);

    distributed_cache_shutdown();

    return 0;
}

