#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <sqlapi.h>

#define MAX_RECORDS 1000000
#define MAX_SERVERS 10
#define MAX_METADATA_LENGTH 256

typedef struct {
    char id[32];
    int key;
    double timestamp;
    char metadata[MAX_METADATA_LENGTH];
} Record;

typedef struct {
    char address[128];
    char username[64];
    char password[64];
    SA_Connection *connection;
} ServerConfig;

ServerConfig servers[MAX_SERVERS];
int num_servers = 0;
pthread_mutex_t record_lock;
Record records[MAX_RECORDS];
size_t record_count = 0;

void load_server_configs() {
    for (int i = 0; i < MAX_SERVERS; ++i) {
        char addr[128], uname[64], pwd[64];

        if (snprintf(addr, sizeof(addr), "SERVER_%d_ADDRESS", i + 1) &&
            getenv(addr)) {
            snprintf(servers[i].address, sizeof(servers[i].address),
                     "%s", getenv(addr));

            if (snprintf(uname, sizeof(uname), "SERVER_%d_USERNAME", i + 1) &&
                getenv(uname)) {
                snprintf(servers[i].username, sizeof(servers[i].username),
                         "%s", getenv(uname));
            }

            if (snprintf(pwd, sizeof(pwd), "SERVER_%d_PASSWORD", i + 1) &&
                getenv(pwd)) {
                snprintf(servers[i].password, sizeof(servers[i].password),
                         "%s", getenv(pwd));
            }
        } else {
            break;
        }

        num_servers = i + 1;
    }
}

void connect_to_server(ServerConfig *server) {
    SA_Connection conn;
    if (SA_IsSuccess(conn.Connect(server->address, server->username,
                                  server->password))) {
        server->connection = &conn;
    } else {
        fprintf(stderr, "Failed to connect to server: %s\n", server->address);
    }
}

void initialize() {
    pthread_mutex_init(&record_lock, NULL);
    for (int i = 0; i < num_servers; ++i) {
        connect_to_server(&servers[i]);
    }
}

void cleanup() {
    for (int i = 0; i < num_servers; ++i) {
        if (servers[i].connection) {
            servers[i].connection->Disconnect();
        }
    }
    pthread_mutex_destroy(&record_lock);
}

void add_record(Record *rec) {
    pthread_mutex_lock(&record_lock);

    if (record_count < MAX_RECORDS) {
        records[record_count++] = *rec;
        printf("Added record %s\n", rec->id);
    } else {
        fprintf(stderr, "Max records reached\n");
    }

    pthread_mutex_unlock(&record_lock);
}

void* read_records(void *arg) {
    for (size_t i = 0; i < record_count; ++i) {
        printf("Reading record %s: key=%d, timestamp=%.2f, metadata=%s\n",
               records[i].id, records[i].key,
               records[i].timestamp, records[i].metadata);
    }
    return NULL;
}

int main() {
    load_server_configs();
    initialize();

    Record rec = {"12345", 10, time(NULL), "Sample Metadata"};
    add_record(&rec);

    pthread_t read_thread;
    pthread_create(&read_thread, NULL, read_records, NULL);
    pthread_join(read_thread, NULL);

    cleanup();
    return 0;
}
