import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.List;
import java.util.concurrent.CompletableFuture;

@SpringBootApplication
public class MainService {
    public static void main(String[] args) {
        SpringApplication.run(MainService.class, args);
    }
}

@RestController
class PokemonController {

    private final ObjectMapper objectMapper = new ObjectMapper();
    private final CassandraRepository cassandraRepository; // Assume this is implemented

    public PokemonController(CassandraRepository cassandraRepository) {
        this.cassandraRepository = cassandraRepository;
    }

    @GetMapping("/pokemon/{id}/weaknesses")
    public CompletableFuture<String> getPokemonWeaknesses(@PathVariable String id) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                List<String> weaknesses = getCachedOrFetchWeaknesses(id);
                String pokemonName = fetchPokemonName(id);

                WeaknessResponse response = new WeaknessResponse(pokemonName, weaknesses);
                cassandraRepository.saveWeaknesses(id, weaknesses); // Persist in database

                return objectMapper.writeValueAsString(response);

            } catch (IOException e) {
                throw new RuntimeException("Error processing request", e);
            }
        });
    }

    private List<String> getCachedOrFetchWeaknesses(String id) throws IOException {
        String cacheKey = "pokemon_weakness_" + id;
        // Assume RedisTemplate is configured
        String cachedWeaknesses = redisTemplate.opsForValue().get(cacheKey);

        if (cachedWeaknesses != null) {
            return objectMapper.readValue(cachedWeaknesses, List.class);
        } else {
            String apiUrl = "https://pokeapi.co/api/v2/pokemon/" + id;
            URL url = new URL(apiUrl);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            if (connection.getResponseCode() == 200) {
                String response = ioUtils.read(connection.getInputStream());
                PokemonData pokemonData = objectMapper.readValue(response, PokemonData.class);

                List<String> weaknesses = extractWeaknesses(pokemonData);
                redisTemplate.opsForValue().set(cacheKey, objectMapper.writeValueAsString(weaknesses), 10L, TimeUnit.MINUTES);

                return weaknesses;
            } else {
                throw new RuntimeException("Failed to fetch data from API");
            }
        }
    }

    private String fetchPokemonName(String id) throws IOException {
        String apiUrl = "https://pokeapi.co/api/v2/pokemon/" + id;
        URL url = new URL(apiUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() == 200) {
            return ioUtils.read(connection.getInputStream());
        } else {
            throw new RuntimeException("Failed to fetch Pokemon name");
        }
    }

    private List<String> extractWeaknesses(PokemonData pokemonData) {
        // Extract weaknesses from the response
        return pokemonData.getTypes().stream()
                .flatMap(type -> type.getDamageRelations().getDoubleWeakAgainst().stream())
                .map(DamageType::getName)
                .distinct()
                .toList();
    }
}

