        if "ERROR" in line or "Exception" in line:
            timestamp_match = re.search(r'\[(.*?)\]', line)
            request_id_match = re.search(r'Request-ID: (\w+)', line)

            timestamp = timestamp_match.group(1) if timestamp_match else 'N/A'
            request_id = request_id_match.group(1) if request_id_match else 'N/A'

            errors.append(f"Timestamp: {timestamp}, Request ID: {request_id}, Error: {line.strip()}")

        # Example of a performance bottleneck pattern (could be adjusted)
        elif "Latency > 500ms" in line:
            timestamp_match = re.search(r'\[(.*?)\]', line)
            request_id_match = re.search(r'Request-ID: (\w+)', line)

            timestamp = timestamp_match.group(1) if timestamp_match else 'N/A'
            request_id = request_id_match.group(1) if request_id_match else 'N/A'

            performance_issues.append(f"Timestamp: {timestamp}, Request ID: {request_id}, Latency: {line.strip()}")

    error_report = Counter(errors)
    perf_issue_report = Counter(performance_issues)

    return {"common_errors": dict(error_report), "performance_bottlenecks": dict(perf_issue_report)}

# Example usage:
log_file_path = 'service_logs.txt'
report = process_log_files(log_file_path)
print("Error Report:", report['common_errors'])
print("Performance Bottleneck Report:", report['performance_bottlenecks'])
```

