// Thread-safe cache with expiration
template<typename KeyType, typename ValueType>
class Cache {
private:
    struct CacheEntry {
        ValueType value;
        std::chrono::steady_clock::time_point expiry;

        bool isExpired() const {
            return std::chrono::steady_clock::now() > expiry;
        }
    };

    std::unordered_map<KeyType, CacheEntry> cache_;
    std::mutex mutex_;

public:
    void set(const KeyType& key, const ValueType& value, int seconds) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = {value, std::chrono::steady_clock::now() + std::chrono::seconds(seconds)};
    }

    bool get(const KeyType& key, ValueType& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end() && !it->second.isExpired()) {
            value = it->second.value;
            return true;
        }
        return false;
    }

    void clearExpiredEntries() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = cache_.begin(); it != cache_.end();) {
            if (it->second.isExpired()) {
                it = cache_.erase(it);
            } else {
                ++it;
            }
        }
    }
};

// Payment transaction processing function
class PaymentProcessor {
private:
    PaymentGatewayAPI api_;
    Logger logger_;
    Cache<std::string, std::string> resultCache_;

public:
    bool processPaymentTransaction(const std::unordered_map<std::string, std::string>& metadata) {
        if (!validateMetadata(metadata)) {
            logger_.log(Logger::Level::ERROR, "Invalid payment metadata.");
            return false;
        }

        if (isTransactionProcessed(metadata["transaction_id"])) {
            logger_.log(Logger::Level::WARNING, "Transaction already processed.");
            return true;
        }

        std::string transactionId = metadata["transaction_id"];
        int retries = 0;
        const int maxRetries = 5;

        while (retries < maxRetries) {
            try {
                if (api_.processTransaction(metadata["method"], metadata)) {
                    resultCache_.set(transactionId, "Success", 30);
                    logger_.log(Logger::Level::INFO, "Transaction processed successfully.");
                    return true;
                } else {
                    throw std::runtime_error("API processing failed");
                }
            } catch (const std::exception& e) {
                retries++;
                int waitTime = std::pow(2, retries);
                logger_.log(Logger::Level::ERROR, std::string("Error: ") + e.what() + ". Retrying in " + std::to_string(waitTime) + " seconds.");
                std::this_thread::sleep_for(std::chrono::seconds(waitTime));
            }
        }

        logger_.log(Logger::Level::ERROR, "Transaction failed after retries.");
        return false;
    }

private:
    bool validateMetadata(const std::unordered_map<std::string, std::string>& metadata) {
        // Implement validation logic
        return true;  // Assume valid for demonstration
    }

    bool isTransactionProcessed(const std::string& transactionId) {
        std::string cachedResult;
        if (resultCache_.get(transactionId, cachedResult)) {
            return cachedResult == "Success";
        }
        return false;
    }

    void logActivity(const std::string& activity) {
        logger_.log(Logger::Level::INFO, activity);
    }

    // Utility function to calculate SHA-256 hash
    std::string calculateSHA256(const std::string& filePath) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        std::ifstream file(filePath, std::ios::binary);

        if (!file.is_open()) return "";

        const size_t bufferSize = 4096;
        char buffer[bufferSize];

        SHA256_CTX sha256;
        SHA256_Init(&sha256);

        while (file.read(buffer, bufferSize)) {
            SHA256_Update(&sha256, buffer, file.gcount());
        }

        if (!file.eof()) {
            // Handle read error
            return "";
        }

        SHA256_Final(hash, &sha256);
        std::ostringstream oss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            oss << std::hex << static_cast<int>(hash[i]);
        }
        return oss.str();
    }
};

