    // Test case: Already processed transaction
    assert(processor.processPaymentTransaction(validMetadata));  // Should log warning

    // Test case: Invalid metadata
    auto invalidMetadata = {{"transaction_id", "67890"}, {"method", ""}};
    assert(!processor.processPaymentTransaction(invalidMetadata));
}

int main() {
