using System;
using System.Collections.Concurrent;
using System.Data.SqlClient;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;

public class UserPreferencesCacheService
{
    private readonly IDistributedCache _distributedCache;
    private readonly string _connectionString;
    private readonly TimeSpan _cacheTtl;

    public UserPreferencesCacheService(IDistributedCache distributedCache, string connectionString, TimeSpan cacheTtl)
    {
        _distributedCache = distributedCache;
        _connectionString = connectionString;
        _cacheTtl = cacheTtl;
    }

    public async Task<UserPreferences> LoadUserPreferencesAsync(string userId)
    {
        try
        {
            var cachedData = await _distributedCache.GetStringAsync(userId);
            if (!string.IsNullOrEmpty(cachedData))
            {
                return JsonSerializer.Deserialize<UserPreferences>(cachedData);
            }

            return await LoadFromDatabaseAsync(userId);
        }
        catch (Exception ex) when (ex is InvalidOperationException || ex is JsonException)
        {
            // Log the exception and proceed to load from database as a fallback
            Console.WriteLine($"Cache retrieval failed for {userId}: {ex.Message}");
            return await LoadFromDatabaseAsync(userId);
        }
    }

    private async Task<UserPreferences> LoadFromDatabaseAsync(string userId)
    {
        using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();

        var command = new SqlCommand("SELECT Preferences FROM UserPreferences WHERE UserId = @UserId", connection);
        command.Parameters.AddWithValue("@UserId", userId);

        using var reader = await command.ExecuteReaderAsync();
        if (reader.Read())
        {
            var preferencesJson = reader.GetString(0);
            var userPreferences = JsonSerializer.Deserialize<UserPreferences>(preferencesJson);

            // Update cache with the retrieved data
            await _distributedCache.SetStringAsync(userId, preferencesJson, new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = _cacheTtl
            });

            return userPreferences;
        }

        throw new KeyNotFoundException($"User preferences not found for userId: {userId}");
    }

    public void InsertStringAfterFirstOccurrence(LinkedList<string> forwardList, string firstStr, string secondStr)
    {
        var node = forwardList.First;
        while (node != null && node.Value != firstStr)
        {
            node = node.Next;
        }

        if (node != null)
        {
            forwardList.AddAfter(node, secondStr);
        }
        else
        {
            forwardList.AddLast(secondStr);
        }
    }
}

