EXTERNAL_SOCIAL_MEDIA_API_URL = "https://api.socialmedia.com/update-profile"
RATE_LIMIT_THRESHOLD = 100  # Maximum number of API calls per hour
rate_limit_lock = threading.Lock()
request_counter = 0

def rate_limiter():
    global request_counter
    with rate_limit_lock:
        if request_counter >= RATE_LIMIT_THRESHOLD:
            time.sleep(3600)  # Wait for an hour to reset the limit
            request_counter = 0
        else:
            request_counter += 1

@app.route('/update-profile/<user_id>', methods=['PATCH'])
def update_profile(user_id):
    try:
        if not user_id.isalnum():
            return jsonify({"error": "Invalid user ID"}), 400

        data = request.get_json()
        if 'name' not in data and 'email' not in data and 'address' not in data:
            return jsonify({"error": "No update fields provided"}), 400

        with lock:  # Ensure thread-safe updates
            user_profile = get_user_profile_from_db(user_id)
            if not user_profile:
                return jsonify({"error": "User profile not found"}), 404

            # Update nested structures and language preference
            for key, value in data.items():
                if isinstance(value, dict):
                    user_profile[key].update(value)  # Support nested updates
                else:
                    user_profile[key] = value

            update_user_profile_in_db(user_id, user_profile)

        invalidate_cache(user_id)

        return jsonify({"message": "Profile updated successfully", "data": user_profile}), 200

    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route('/sync-profile/<user_id>', methods=['POST'])
def sync_profile_with_social_media(user_id):
    try:
        if not user_id.isalnum():
            return jsonify({"error": "Invalid user ID"}), 400

        rate_limiter()

        with lock:  # Ensure thread-safe updates
            user_profile = get_user_profile_from_db(user_id)
            if not user_profile:
                return jsonify({"error": "User profile not found"}), 404

        response = requests.post(EXTERNAL_SOCIAL_MEDIA_API_URL, json=user_profile)

        if response.status_code == 429:  # Rate limit exceeded
            return jsonify({"error": "Rate limit exceeded on external platform"}), 429

        response.raise_for_status()
        social_media_response_data = response.json()

        invalidate_cache(user_id)

        return jsonify({
            "message": "Profile synchronized successfully",
            "data": social_media_response_data
        }), 200

    except requests.exceptions.RequestException as e:
        return jsonify({"error": str(e)}), 500

