struct OctreeNode {
    std::vector<OctreeNode*> children;
    int dataCapacity;

    OctreeNode(int capacity) : children(8, nullptr), dataCapacity(capacity) {}

    ~OctreeNode() {
        for (auto child : children) {
            delete child;
        }
    }

    bool isFull() const {
        // Assuming we use the dataCapacity to determine fullness
        return std::all_of(children.begin(), children.end(), [](const OctreeNode* node) { return node && node->isFull(); });
    }

    bool isEmpty() const {
        return children[0] == nullptr;
    }
};

