private:
    OctreeNode* root;
    int featureSize;
    int leafNodeCount;
    int nodeDataCapacity;
    std::vector<int> prefixLeafs;  // Simplified representation
    mutable std::mutex treeMutex;

    void initializeOctree() {
        // Initialize prefix leafs and other structures
        prefixLeafs.resize(leafNodeCount, 0);  // Example initialization

        for (int i = 0; i < initialLeafNodes; ++i) {
            insertNode();  // Prepopulate the octree with nodes
        }
    }

    void reallocateIfNecessary() {
        if (leafNodeCount > prefixLeafs.size()) {
            int newSize = std::max(2 * prefixLeafs.size(), leafNodeCount);
