To design this scalable Node.js application, we'll break down the components into smaller parts:

### 1. **Project Setup**
```bash
mkdir payment-gateway-app && cd payment-gateway-app
npm init -y
npm install express redis ioredis dotenv axios rate-limit-redis helmet winston jsonwebtoken bcryptjs cors helmet body-parser compression
```

### 2. **Server Setup**

**server.js:**
```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const compression = require('compression');
const bodyParser = require('body-parser');
const cors = require('cors');

// Load configurations
const { loadConfig } = require('./config/config');

loadConfig();

const app = express();

app.use(helmet());
app.use(compression());
app.use(cors());
app.use(bodyParser.json());

// Routes
app.use('/api', require('./routes/api'));

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

### 3. **Configuration Management**

**config/config.js:**
```javascript
const fs = require('fs');
let config;

function loadConfig() {
  const defaultConfig = JSON.parse(fs.readFileSync('./config/default.json', 'utf8'));
  const envConfig = process.env.NODE_ENV ? JSON.parse(fs.readFileSync(`./config/${process.env.NODE_ENV}.json`, 'utf8')) : {};

  config = { ...defaultConfig, ...envConfig };
}

