// Structure for Record
typedef struct {
    long id;
    double timestamp;
    char *tags;
    char *metadata;
    char *serverData;
    int statusFlag;
} Record;

// Mutex for thread safety
pthread_mutex_t recordMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize a Record
Record* create_record(long id, const char *tags, const char *metadata, const char *serverData) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) return NULL;

    pthread_mutex_lock(&recordMutex);
    record->id = id;
    record->timestamp = time(NULL);
    record->tags = strdup(tags);
    record->metadata = strdup(metadata);
    record->serverData = strdup(serverData);
    record->statusFlag = 0; // Default status
    pthread_mutex_unlock(&recordMutex);

    return record;
}

// Function to free a Record's memory
void destroy_record(Record *record) {
    if (!record) return;

    pthread_mutex_lock(&recordMutex);
    free(record->tags);
    free(record->metadata);
    free(record->serverData);
    free(record);
    pthread_mutex_unlock(&recordMutex);
}

