```cpp
#include <forward_list>
#include <string>
#include <mutex>

// Global mutex for thread-safe access to the forward_list
std::mutex list_mutex;

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
    std::lock_guard<std::mutex> lock(list_mutex);

    auto it = list.begin();
    bool found = false;

    for (; it != list.end(); ++it) {
        if (*it == target) {
            found = true;
            break;
        }
    }

    if (found) {
        list.insert_after(it, value);
    } else {
        list.push_front(value); // Efficiently appending to the front of a forward_list
    }
}

// Unit tests for the function

#include <cassert>
#include <iostream>

void testInsertAfterFirstOccurrence() {
    std::forward_list<std::string> list;

    // Test 1: Insert into an empty list
    insertAfterFirstOccurrence(list, "target", "value");
    assert(std::begin(list) != list.end() && *std::begin(list) == "value");

    // Test 2: Target not found, append to end
    insertAfterFirstOccurrence(list, "not_found", "new_value");
    auto it = std::next(std::begin(list));
    assert(it != list.end() && *it == "new_value");

    // Test 3: Insert after first occurrence of target
    insertAfterFirstOccurrence(list, "value", "after_value");
    it = std::next(std::begin(list), 2);
    assert(it != list.end() && *it == "after_value");

    // Test 4: Target appears multiple times, only insert after the first one
    list.push_front("target");
    list.push_front("value");
    insertAfterFirstOccurrence(list, "target", "another_after_value");
    it = std::next(std::begin(list), 1);
    assert(it != list.end() && *it == "another_after_value");

    // Test 5: Large dataset
    for (int i = 0; i < 1000000; ++i) {
        insertAfterFirstOccurrence(list, "large_target", "in_large_list");
    }
    auto count = std::count_if(std::begin(list), list.end(), [](const std::string& s) { return s == "in_large_list"; });
    assert(count == 1);

    std::cout << "All tests passed.\n";
}

int main() {
    testInsertAfterFirstOccurrence();
    return 0;
}
