using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

[Serializable]
public class Pokemon
{
    public string Name { get; set; }
    public string Type { get; set; }
    public List<string> Weaknesses { get; set; }

    // Constructor for older versions of the data structure
    public Pokemon()
    {
        Weaknesses = new List<string>();
    }

    // Additional constructor for newer versions if needed
}

[Serializable]
public class PokemonData
{
    public int Version { get; set; }
    public List<Pokemon> Pokemons { get; set; }

    public PokemonData()
    {
        Pokemons = new List<Pokemon>();
    }
}

public class DeserializationService
{
    private readonly IExternalApi _externalApi;

    public DeserializationService(IExternalApi externalApi)
    {
        _externalApi = externalApi;
    }

    public PokemonData LoadAndDeserialize(string filePath)
    {
        try
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            using (var binaryFormatter = new BinaryFormatter())
            {
                Console.WriteLine("Deserializing data...");
                var pokemonData = (PokemonData)binaryFormatter.Deserialize(fileStream);

                ValidatePokemonData(pokemonData);

                return pokemonData;
            }
        }
        catch (FileNotFoundException ex)
        {
            HandleError("File not found: " + filePath, ex);
            throw;
        }
        catch (SerializationException ex)
        {
            HandleError("Deserialization failed.", ex);
            throw;
        }
    }

    private void ValidatePokemonData(PokemonData pokemonData)
    {
        Console.WriteLine("Validating data against external schema...");
        foreach (var pokemon in pokemonData.Pokemons)
        {
            switch (pokemon.Type.ToLower())
            {
                case "fire":
                    if (!_externalApi.ValidateFireType(pokemon.Name))
                        throw new ValidationException($"Validation failed for Fire type Pokemon: {pokemon.Name}");
                    break;
                case "water":
                    if (!_externalApi.ValidateWaterType(pokemon.Name))
                        throw new ValidationException($"Validation failed for Water type Pokemon: {pokemon.Name}");
                    break;
                // Add more cases as needed
            }
        }

        Console.WriteLine("Data validation successful.");
    }

    private void HandleError(string message, Exception ex)
    {
        Console.WriteLine($"{message} Error: {ex.Message}");
    }
}

public interface IExternalApi
{
