    @PutMapping("/cache/update")
    public String updateCacheData(@RequestBody CacheRequest request) {
        return cacheService.update(request.getKey(), request.getValue());
    }

    // Retrieve data from the cache
    @GetMapping("/cache/retrieve/{key}")
    public String retrieveFromCache(@PathVariable String key) {
        return cacheService.retrieve(key);
    }

    // Process a transaction asynchronously
    @PostMapping("/transaction/process")
    public String processTransaction(@RequestBody TransactionRequest request) {
        return transactionService.process(request);
    }
}

