    int retryCount = 0;

    while (retryCount < maxRetries) {
        bool success = true;  // Assume all retries succeed

        for (auto& tx : transactions) {
            try {
                fetchMetadata(tx);
            } catch (...) {  // Catch specific exceptions in a real implementation
                success = false;
                break;
            }
        }

        if (success) break;

        retryCount++;
        std::this_thread::sleep_for(std::chrono::seconds(5));  // Wait before retrying
    }

    if (!success) {
        std::cerr << "Failed to process some transactions after retries." << std::endl;
    }
