// config.js - Example configuration file
module.exports = {
  environments: {
    development: {
      retryAttempts: 3,
      cacheDuration: 60 * 5 // 5 minutes
    },
    production: {
      retryAttempts: 5,
      cacheDuration: 60 * 15 // 15 minutes
    }
  },
  modulesOrder: ['moduleA', 'moduleB', 'moduleC']
};

// moduleLoader.js
const path = require('path');
const fs = require('fs');
const util = require('util');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);
const logError = (error) => console.error(`[ERROR] ${new Date().toISOString()}:`, error);

class ModuleLoader {
  constructor(config, environment) {
    this.config = config.environments[environment];
    this.modulesOrder = config.modulesOrder;
    this.cache = new Map();
    this.context = {};
  }

  async loadModules() {
    for (const moduleName of this.modulesOrder) {
      try {
        await this.loadModule(moduleName);
      } catch (error) {
        logError(error);
      }
    }
  }

  async loadModule(moduleName) {
    if (this.cache.has(moduleName)) {
      console.log(`[CACHE] Loaded ${moduleName} from cache`);
      return this.cache.get(moduleName);
    }

    const modulePath = path.resolve(__dirname, 'modules', `${moduleName}.js`);
    try {
      const code = await readFileAsync(modulePath, 'utf-8');
      const moduleFunction = new Function('context', code);
      const result = moduleFunction(this.context);

      if (result instanceof Promise) {
        await result;
      }

      this.cache.set(moduleName, this.context[moduleName]);
    } catch (error) {
      logError(`Failed to load ${moduleName}: ${error.message}`);
      throw error;
    }
  }
}

// index.js
const config = require('./config');
const ModuleLoader = require('./moduleLoader');

(async () => {
  const environment = process.env.NODE_ENV || 'development';
  console.log(`[INFO] Running in ${environment} mode`);

  const loader = new ModuleLoader(config, environment);
  await loader.loadModules();
})();

// moduleA.js - Example module with dependencies
