using System;
using System.Collections.Concurrent;
using UnityEngine;
using System.Runtime.Caching;

public enum DistributionType
{
    Uniform,
    Gaussian,
    Exponential
}

public interface IDistribution
{
    float GenerateFloat(float min, float max);
    int GenerateInt(int min, int max);
}

public class UniformDistribution : IDistribution
{
    public float GenerateFloat(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }

    public int GenerateInt(int min, int max)
    {
        return UnityEngine.Random.Range(min, max + 1);
    }
}

// Implement other distributions similarly...

public class GaussianDistribution : IDistribution
{
    // Use an appropriate library for Gaussian distribution or custom implementation.
    public float GenerateFloat(float mean, float stdDev)
    {
        var u = UnityEngine.Random.value;
        var v = UnityEngine.Random.value;

        return mean + stdDev * Mathf.Sqrt(-2.0f * Mathf.Log(u)) * Mathf.Sin(2.0f * Mathf.PI * v);
    }

    public int GenerateInt(int min, int max)
    {
        float result = GenerateFloat(float.NegativeInfinity, float.PositiveInfinity);
        // Normalize to the desired range
        return Mathf.RoundToInt(((result - float.MinValue) / (float.MaxValue - float.MinValue)) * (max - min + 1) + min);
    }
}

public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, IDistribution> _distributionCache;
    private static readonly ObjectCache ConfigurationCache = MemoryCache.Default;

    public string CurrentDistribution { get; private set; }

    public DynamicValueGenerator()
    {
        _distributionCache = new ConcurrentDictionary<string, IDistribution>();
    }

    public float GetRandomFloat(float min, float max)
    {
        ValidateRange(min, max);
        return GetCurrentDistribution().GenerateFloat(min, max);
    }

    public int GetRandomInt(int min, int max)
    {
        ValidateRange(min, max);
        return GetCurrentDistribution().GenerateInt(min, max);
    }

    private void ValidateRange(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum cannot be greater than maximum.");
    }

    private IDistribution GetCurrentDistribution()
    {
        var distribution = ConfigurationCache[CurrentDistribution] as IDistribution;
        if (distribution == null && _distributionCache.TryGetValue(CurrentDistribution, out var cachedDist))
        {
            distribution = cachedDist;
        }

        if (distribution == null)
        {
            switch (CurrentDistribution)
            {
                case nameof(DistributionType.Uniform):
                    distribution = new UniformDistribution();
                    break;
                case nameof(DistributionType.Gaussian):
                    distribution = new GaussianDistribution();
                    break;
                // Add other cases...
                default:
                    throw new NotSupportedException($"Unsupported distribution type: {CurrentDistribution}");
            }

            _distributionCache[CurrentDistribution] = distribution;
        }

        return distribution;
    }

    public void SetDistribution(string distribution)
    {
        CurrentDistribution = distribution ?? throw new ArgumentNullException(nameof(distribution));
        // Update cache and configuration as needed...
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: DistributionType={CurrentDistribution}";
    }

    // Configuration system integration, logging, and further error handling omitted for brevity.
}

// Example of usage
public class Program
{
    static void Main(string[] args)
    {
        var generator = new DynamicValueGenerator();
        generator.SetDistribution(nameof(DistributionType.Uniform));
        Console.WriteLine(generator.GetRandomFloat(0f, 10f));
        Console.WriteLine(generator.GetRandomInt(1, 5));

        // Switch to Gaussian
        generator.SetDistribution(nameof(DistributionType.Gaussian));
        Console.WriteLine(generator.GetRandomFloat(-1f, 1f));
    }
}
