        this.limit = limit;
        this.requests = new Map();
    }

    shouldThrottle(clientId) {
        const now = Date.now();
        let requests = this.requests.get(clientId) || [];

        // Remove old requests
        requests = requests.filter(timestamp => (now - timestamp) < 1000);

        if (requests.length >= this.limit) return true;

        requests.push(now);
        this.requests.set(clientId, requests);

        return false;
    }
