#include <iostream>
#include <random>
#include <mutex>
#include <unordered_map>
#include <vector>
#include <functional>

namespace RandomGenerator {

class MT19937Generator {
public:
    using DistributionType = std::uniform_int_distribution<int>;

    explicit MT19937Generator(unsigned int seed) : gen(seed), rngCacheMutex(), cacheSize(100) {
        if (seed == 0) {
            throw std::invalid_argument("Seed value cannot be zero.");
        }
    }

    ~MT19937Generator() = default;

    int getRandomNumber(int min, int max) {
        std::lock_guard<std::mutex> lock(rngCacheMutex);

        // Check cache
        if (!rngCache.empty()) {
            auto cachedValue = rngCache.back();
            rngCache.pop_back();
            return cachedValue;
        }

        // Generate a new random number and store it in the cache
        DistributionType dist(min, max);
        int randomNumber = dist(gen);
        if (rngCache.size() >= cacheSize) {
            rngCache.erase(rngCache.begin());
        }
        rngCache.push_back(randomNumber);

        return randomNumber;
    }

    template<typename T>
    T getDistribution(std::function<T()> distributionFunc) {
        std::lock_guard<std::mutex> lock(rngCacheMutex);
        return distributionFunc();
    }

    void storeSeedToDatabase(const std::string& streamId, unsigned int seed) {
        // Placeholder for database integration
        dbSeeds[streamId] = seed;
    }

    unsigned int retrieveSeedFromDatabase(const std::string& streamId) {
        if (dbSeeds.find(streamId) != dbSeeds.end()) {
            return dbSeeds[streamId];
        }
        throw std::runtime_error("Seed not found in database.");
    }

    MT19937Generator deriveStream(unsigned int seedOffset) const {
        return MT19937Generator(gen.seed() + seedOffset);
    }

private:
    mutable std::mutex rngCacheMutex;
    std::mt19937 gen;
    std::vector<int> rngCache;
    size_t cacheSize;

    // Simulated external database for storing and retrieving seeds
    std::unordered_map<std::string, unsigned int> dbSeeds;
};

}  // namespace RandomGenerator

// Unit Tests
void testMT19937Generator() {
    RandomGenerator::MT19937Generator rng(42);

    try {
        rng.getRandomNumber(-1, 10);  // Invalid range
    } catch (const std::exception& e) {
        std::cout << "Caught expected exception for invalid range: " << e.what() << '\n';
    }

    int min = 1;
    int max = 100;

    auto uniformDistribution = []() -> double {
        RandomGenerator::MT19937Generator rng(42);
        return static_cast<double>(rng.getRandomNumber(min, max)) / (max - min + 1.0);
    };

    auto normalDistribution = []() -> double {
        RandomGenerator::MT19937Generator rng(42);
        std::normal_distribution<> d(50, 15); // mean=50, stddev=15
        return d(rng.gen);
    };

    try {
        std::cout << "Uniform Distribution: " << rng.getDistribution(uniformDistribution) << '\n';
        std::cout << "Normal Distribution: " << rng.getDistribution(normalDistribution) << '\n';

        RandomGenerator::MT19937Generator newStream = rng.deriveStream(12345);
        std::cout << "Derived Stream Number: " << newStream.getRandomNumber(min, max) << '\n';
    } catch (const std::exception& e) {
        std::cerr << "Exception during unit test: " << e.what() << '\n';
    }
}

int main() {
    testMT19937Generator();
    return 0;
}
