```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>

#define MAX_IP_LENGTH 16

typedef struct {
    char *hostname;
    void (*callback)(u_char *, int);
} dns_request;

typedef enum {
    DNS_SUCCESS,
    DNS_FAILURE,
    DNS_INVALID_INPUT,
    DNS_NETWORK_ERROR
} dns_status;

// Mock external service interaction functions
dns_status fetch_hostname_details(const char *hostname, u_char **ip_addresses, int *count) {
    // Simulate fetching IP addresses for the given hostname
    // For demonstration purposes, we'll just return a static IP address
    static u_char mock_ip[] = {127, 0, 0, 1};
    *ip_addresses = malloc(sizeof(mock_ip));
    memcpy(*ip_addresses, mock_ip, sizeof(mock_ip));
    *count = 1;
    return DNS_SUCCESS;
}

void close_service_connection() {
    // Simulate closing any open connections to the external service
}

// Callback function type definition
typedef void (*dns_callback)(u_char *, int);

// Function to handle each resolved IP address
void handle_resolved_ip(u_char *ip_address, dns_callback callback) {
    if (callback != NULL) {
        callback(ip_address, 1); // Pass the resolved IP address and count
    }
}

// DNS resolution worker function for threading
void* resolve_dns_worker(void *arg) {
    dns_request *request = (dns_request *)arg;
    u_char *ip_addresses = NULL;
    int ip_count = 0;

    dns_status status = fetch_hostname_details(request->hostname, &ip_addresses, &ip_count);

    if (status != DNS_SUCCESS) {
        fprintf(stderr, "DNS resolution failed for %s\n", request->hostname);
        return NULL;
    }

    for (int i = 0; i < ip_count; ++i) {
        handle_resolved_ip(&ip_addresses[i * MAX_IP_LENGTH], request->callback);
    }

    free(ip_addresses);
    close_service_connection();
    return NULL;
}

// Main function to perform asynchronous DNS resolution
dns_status dnsAsyncResolve(const char *hostname, dns_callback callback) {
    if (hostname == NULL || strlen(hostname) == 0) {
        fprintf(stderr, "Invalid hostname\n");
        return DNS_INVALID_INPUT;
    }

    pthread_t thread_id;
    dns_request request = { .hostname = strdup(hostname), .callback = callback };

    // Start the DNS resolution in a separate thread
    int result = pthread_create(&thread_id, NULL, resolve_dns_worker, &request);
    if (result != 0) {
        fprintf(stderr, "Failed to create thread for DNS resolution\n");
        free(request.hostname);
        return DNS_NETWORK_ERROR;
    }

    // Detach the thread to allow independent execution
    pthread_detach(thread_id);

    return DNS_SUCCESS;
}

// Sample callback function
void sample_callback(u_char *ip_address, int count) {
    printf("Resolved IP: ");
    for (int i = 0; i < count; ++i) {
        printf("%d.%d.%d.%d ", ip_address[i * MAX_IP_LENGTH], ip_address[i * MAX_IP_LENGTH + 1],
               ip_address[i * MAX_IP_LENGTH + 2], ip_address[i * MAX_IP_LENGTH + 3]);
    }
    printf("\n");
}

// Main function for testing
int main() {
    const char *hostnames[] = {"example.com", "localhost"};
    int num_hostnames = sizeof(hostnames) / sizeof(hostnames[0]);

    for (int i = 0; i < num_hostnames; ++i) {
        dnsAsyncResolve(hostnames[i], sample_callback);
    }

    // Simulate wait to allow asynchronous resolution
    sleep(5);

    return 0;
}
```

This code provides a basic framework for performing asynchronous DNS resolution in C. It uses threads to handle the resolution process concurrently and includes error handling, logging, and resource management. The `dnsAsyncResolve` function initiates the resolution, while the worker thread handles the actual fetching of IP addresses and invoking the callback.

