    int port;
    int available;
} ServerInfo;

typedef struct {
    ServerInfo* servers;
    size_t server_count;
    pthread_mutex_t connection_lock;
} ServerManager;

typedef struct {
    CURL* curl_handle;
    pthread_mutex_t lock;
} CurlManager;

typedef struct {
    Cache cache;
    ServerManager server_manager;
    CurlManager curl_manager;
    double max_priority;
    pthread_mutex_t log_lock;
} DBConnectionContext;

// Function prototypes
void initializeDBConnection(DBConnectionContext* context);
UserRecord* getUserProfile(DBConnectionContext* context, const char* uuid);
int updateUserProfile(DBConnectionContext* context, UserRecord* record);
void cleanupDBConnection(DBConnectionContext* context);
void* serverDiscovery(void* args);
void performRESTCall(CurlManager* curl_manager, const char* url, const char* method, const char* data);

// Initialize database connection and setup
void initializeDBConnection(DBConnectionContext* context) {
    pthread_mutex_init(&context->cache.lock, NULL);
    context->cache.head = NULL;

    pthread_mutex_init(&context->server_manager.connection_lock, NULL);
    // Load server configurations from environment variables
    size_t server_count = /* load from env */;
    context->server_manager.servers = malloc(sizeof(ServerInfo) * server_count);
    context->server_manager.server_count = server_count;

    pthread_mutex_init(&context->curl_manager.lock, NULL);
    context->curl_manager.curl_handle = curl_easy_init();

    pthread_t discovery_thread;
    pthread_create(&discovery_thread, NULL, serverDiscovery, (void*)context);
}

// Retrieve user profile with caching and server management
UserRecord* getUserProfile(DBConnectionContext* context, const char* uuid) {
    pthread_mutex_lock(&context->cache.lock);
    // Check cache first
    CacheNode* current = context->cache.head;
    while (current != NULL) {
        if (strcmp(current->record.uuid, uuid) == 0) {
            pthread_mutex_unlock(&context->cache.lock);
            return &current->record;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&context->cache.lock);

    // Fetch from server
    char url[512];
    snprintf(url, sizeof(url), "http://%s/api/user/%s", /* server address */, uuid);
    performRESTCall(&context->curl_manager, url, "GET", NULL);

    // Assume response handling and parsing into UserRecord happens here

    pthread_mutex_lock(&context->cache.lock);
    // Add to cache with priority
    CacheNode* new_node = malloc(sizeof(CacheNode));
    strcpy(new_node->record.uuid, uuid);
    new_node->priority = context->max_priority;
    new_node->next = context->cache.head;
    context->cache.head = new_node;
    pthread_mutex_unlock(&context->cache.lock);

    return &new_node->record;
}

// Update user profile with transactional support
int updateUserProfile(DBConnectionContext* context, UserRecord* record) {
    char url[512];
    snprintf(url, sizeof(url), "http://%s/api/user/%s", /* server address */, record->uuid);

    // Begin transaction
    pthread_mutex_lock(&context->curl_manager.lock);
    performRESTCall(&context->curl_manager, url, "PUT", /* serialize record */);

    // Assume response handling and logging

    pthread_mutex_unlock(&context->curl_manager.lock);
    return 0; // Success
}

// Cleanup resources
void cleanupDBConnection(DBConnectionContext* context) {
    pthread_mutex_destroy(&context->cache.lock);
    CacheNode* current = context->cache.head;
    while (current != NULL) {
        CacheNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&context->server_manager.connection_lock);
    free(context->server_manager.servers);

    curl_easy_cleanup(context->curl_manager.curl_handle);
    pthread_mutex_destroy(&context->curl_manager.lock);
}

// Discover available servers and handle failover
void* serverDiscovery(void* args) {
    DBConnectionContext* context = (DBConnectionContext*)args;
    while (1) {
        for (size_t i = 0; i < context->server_manager.server_count; ++i) {
            // Check server availability and update status
        }
        sleep(10); // Discover every 10 seconds
    }
}

// Perform RESTful API call using libcurl
void performRESTCall(CurlManager* curl_manager, const char* url, const char* method, const char* data) {
    pthread_mutex_lock(&curl_manager->lock);
    CURLcode res;
    struct curl_slist *headers = NULL;

    if (strcmp(method, "POST") == 0 || strcmp(method, "PUT") == 0) {
        headers = curl_slist_append(headers, "Content-Type: application/json");
        res = curl_easy_setopt(curl_manager->curl_handle, CURLOPT_POSTFIELDSIZE, strlen(data));
    }

    res = curl_easy_setopt(curl_manager->curl_handle, CURLOPT_URL, url);
    res = curl_easy_perform(curl_manager->curl_handle);

    if (res != CURLE_OK) {
        fprintf(stderr, "Curl failed: %s\n", curl_easy_strerror(res));
    }
    pthread_mutex_unlock(&curl_manager->lock);
}

// Main function for testing
int main() {
    DBConnectionContext context;
    initializeDBConnection(&context);

    // Example usage
    UserRecord* record = getUserProfile(&context, "123e4567-e89b-12d3-a456-426614174000");
    updateUserProfile(&context, record);

    cleanupDBConnection(&context);
    return 0;
}
