std::unique_ptr<CloudStorageClient> createCloudStorageClient(const std::string& provider) {
    if (provider == "aws") {
        return std::make_unique<S3Client>();
    } else if (provider == "google") {
        return std::make_unique<GoogleCloudClient>();
    } else if (provider == "azure") {
        return std::make_unique<AzureBlobClient>();
    }
    throw std::invalid_argument("Unsupported cloud provider");
