public:
    CloudStorageManager(const std::string& provider)
        : client(createCloudStorageClient(provider)) {}

    void uploadAndMonitorFile(const std::string& filePath, const std::string& bucketName) {
        if (client->fileExists(filePath)) {
            // Handle file already exists
            return;
        }

        auto future = std::async(std::launch::async, [&]() { client->uploadFile(filePath, bucketName); });
        monitorAndHandleRetry(future);
    }

private:
    void monitorAndHandleRetry(std::future<void>& future) {
        try {
            future.get();  // Wait for the async task to complete
        } catch (...) {
            // Implement retry logic here
        }
        client->monitorProgress();
    }

    std::unique_ptr<CloudStorageClient> client;
};

