using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Xml.XPath;
using Microsoft.Extensions.Logging;

public class XmlElementFinder
{
    private readonly ILogger<XmlElementFinder> _logger;

    public XmlElementFinder(ILogger<XmlElementFinder> logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> GetFirstElementAsync(string urlOrPath, string elementName)
    {
        try
        {
            XDocument xmlDocument;
            if (Uri.IsWellFormedUriString(urlOrPath, UriKind.Absolute))
            {
                xmlDocument = await FetchXmlFromUrlAsync(urlOrPath);
            }
            else
            {
                xmlDocument = LoadXmlFromFile(path: urlOrPath);
            }

            var elements = xmlDocument.XPathSelectElements($"//{elementName}");
            if (elements.Count() == 0)
            {
                _logger.LogWarning("No elements found with the name {ElementName}.", elementName);
                return null;
            }
            else if (elements.Count() > 1)
            {
                _logger.LogWarning("{Count} elements found with the name {ElementName}. Returning the first one.", elements.Count(), elementName);
            }

            return elements.First().ToString();
        }
        catch (Exception ex) when (ex is XmlException || ex is HttpRequestException || ex is IOException)
        {
            _logger.LogError(ex, "Error fetching or parsing XML.");
            throw;
        }
    }

    private async Task<XDocument> FetchXmlFromUrlAsync(string url)
    {
        using var httpClient = new HttpClient();
        var response = await httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync();
        return XDocument.Parse(content);
    }

    private XDocument LoadXmlFromFile(string path)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException("The specified file does not exist.", path);

        using var stream = File.OpenRead(path);
        return XDocument.Load(stream, LoadOptions.SetLineInfo); // Optimize memory usage
    }
}

