```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32 // AES-256 key size in bytes
#define IV_SIZE 16  // IV size for AES-CBC

typedef struct {
    EVP_CIPHER_CTX *ctx;
} CipherContext;

CipherContext* init_cipher(const char *password, const unsigned char *salt, int salt_len) {
    CipherContext *cipher_ctx = (CipherContext *)malloc(sizeof(CipherContext));
    if (!cipher_ctx) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    cipher_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx->ctx) {
        fprintf(stderr, "EVP_CIPHER_CTX_new failed\n");
        free(cipher_ctx);
        return NULL;
    }

    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];

    // Derive key and IV using PBKDF2
    if (1 != PKCS5_PBKDF2_HMAC(
            password,
            strlen(password),
            salt, salt_len,
            10000, // Number of iterations for security
            EVP_sha256(),
            sizeof(key), key,
            sizeof(iv), iv)) {
        fprintf(stderr, "Key derivation failed\n");
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(
            cipher_ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    return cipher_ctx;
}

int cleanup_cipher(CipherContext *cipher_ctx) {
    if (cipher_ctx) {
        if (cipher_ctx->ctx) {
            EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        }
        free(cipher_ctx);
    }
    return 0;
}

// Example function to encrypt data
int encrypt_data(const CipherContext *cipher_ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len) {
    if (1 != EVP_EncryptUpdate(
            cipher_ctx->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption failed\n");
        return 0;
    }

    int len2 = 0;
    if (1 != EVP_EncryptFinal_ex(cipher_ctx->ctx, ciphertext + *ciphertext_len, &len2)) {
        fprintf(stderr, "Final encryption step failed\n");
        return 0;
    }
    *ciphertext_len += len2;

    return 1; // Success
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <password> <salt>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *password = argv[1];
    const unsigned char salt[] = {0x00}; // Should be derived from an external source or input
    int salt_len = sizeof(salt);

    CipherContext *cipher_ctx = init_cipher(password, salt, salt_len);
    if (!cipher_ctx) {
        return EXIT_FAILURE;
    }

    unsigned char plaintext[] = "This is a test message.";
    unsigned char ciphertext[128];
    int ciphertext_len;

    if (encrypt_data(cipher_ctx, plaintext, sizeof(plaintext), ciphertext, &ciphertext_len)) {
        printf("Encryption successful. Ciphertext length: %d\n", ciphertext_len);
    }

    cleanup_cipher(cipher_ctx);

    return EXIT_SUCCESS;
}
```

### Key Points:
