### 1. Inventory Management with Real-Time Stock Updates

```java
import java.util.concurrent.locks.ReentrantLock;
import java.util.Map;
import java.util.HashMap;

public class InventoryManager {
    private final Map<String, Integer> productStock = new HashMap<>();
    private final ReentrantLock lock = new ReentrantLock();

    public void updateStock(String productId, int quantity) {
        lock.lock();
        try {
            productStock.put(productId, productStock.getOrDefault(productId, 0) + quantity);
        } finally {
            lock.unlock();
        }
    }

    public int getStock(String productId) {
        return productStock.getOrDefault(productId, 0);
    }
}
```

