public class PaymentProcessor {
    private final String apiKey;

    public PaymentProcessor(String apiKey) {
        this.apiKey = apiKey;
        Stripe.apiKey = apiKey;
    }

    public Charge createCharge(String token, double amount) throws Exception {
        return Charge.create(
            mapOf("amount", (long) (amount * 100), "currency", "usd", "source", token)
        );
    }

    private Map<String, Object> mapOf(Object... args) {
        Map<String, Object> m = new HashMap<>();
        for (int i = 0; i < args.length; i += 2) {
            m.put((String) args[i], args[i + 1]);
        }
        return m;
    }
}
