            with smtplib.SMTP('smtp.example.com') as server:
                server.sendmail(msg['From'], [msg['To']], msg.as_string())
        except Exception as e:
            raise SMTPException("Failed to send confirmation email.") from e

class RateLimiter:
    def __init__(self, max_calls_per_minute):
        self.max_calls = max_calls_per_minute
        self.call_times = []
        self.lock = Lock()

    def is_rate_limited(self):
        with self.lock:
            now = time.time()
            # Remove old call timestamps.
            while self.call_times and now - self.call_times[0] > 60:
                self.call_times.pop(0)

            if len(self.call_times) >= self.max_calls:
                return True
            self.call_times.append(now)
        return False

class EmailUpdater:
    def __init__(self, dao, validator, smtp_service, rate_limiter):
        self.dao = dao
        self.validator = validator
        self.smtp_service = smtp_service
        self.rate_limiter = rate_limiter

    def update_user_email(self, user_id, new_email, retry_attempts=3):
        if self.rate_limiter.is_rate_limited():
            raise RateLimitExceededException("Rate limit exceeded. Please try again later.")

        for attempt in range(retry_attempts):
            try:
                # Validate email
                self.validator.validate_format(new_email)
                self.validator.check_domain_existence(new_email)

                # Check if email is unique
                if not self.dao.check_email_uniqueness(new_email):
                    raise EmailValidationException("Email already in use.")

                # Update email in database
                self.dao.update_email(user_id, new_email)

                # Send confirmation email
                self.smtp_service.send_confirmation_email(new_email, "https://example.com/confirm")
                print(f"Successfully updated email for user {user_id}.")
                break

            except (DatabaseException, EmailValidationException, SMTPException) as e:
                if attempt == retry_attempts - 1:
                    print(f"Failed to update email for user {user_id} after {retry_attempts} attempts: {e}")
                else:
                    print(f"Attempt {attempt + 1} failed. Retrying...")

