```python
import os
import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import argparse
import time
import logging
from retrying import retry

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class FileHasher:
    def __init__(self, api_endpoint):
        self.api_endpoint = api_endpoint

    @staticmethod
    def calculate_hash(file_path, chunk_size=8192):
        """Calculate SHA256 hash of a file in chunks."""
        sha256 = hashlib.sha256()
        try:
            with open(file_path, 'rb') as f:
                while chunk := f.read(chunk_size):
                    sha256.update(chunk)
            return sha256.hexdigest()
        except IOError as e:
            logger.error(f"Error reading {file_path}: {e}")
            raise

    @retry(wait_exponential_multiplier=1000, wait_exponential_max=10000, stop_max_attempt_number=5)
    def store_hash(self, file_name, hash_value):
        """Store the hash value using an external API."""
        data = {'filename': file_name, 'hash': hash_value}
        response = requests.post(f"{self.api_endpoint}/store", json=data)
        if not response.ok:
            logger.error(f"Failed to store hash for {file_name}: {response.text}")
            response.raise_for_status()

    @retry(wait_exponential_multiplier=1000, wait_exponential_max=10000, stop_max_attempt_number=5)
    def retrieve_hash(self, file_name):
        """Retrieve the stored hash value from an external API."""
        params = {'filename': file_name}
        response = requests.get(f"{self.api_endpoint}/retrieve", params=params)
        if not response.ok:
            logger.error(f"Failed to retrieve hash for {file_name}: {response.text}")
            response.raise_for_status()
        return response.json().get('hash')

def process_file(file_path, api_endpoint):
    """Process a single file: calculate its hash and store it."""
    hasher = FileHasher(api_endpoint)
    try:
        hash_value = hasher.calculate_hash(file_path)
        hasher.store_hash(os.path.basename(file_path), hash_value)
        logger.info(f"Processed {file_path}: Hash stored successfully.")
    except Exception as e:
        logger.error(f"Failed to process {file_path}: {e}")

def main():
    parser = argparse.ArgumentParser(description="File Hashing Utility")
    parser.add_argument('files', nargs='+', help='Files to hash')
    parser.add_argument('--threads', type=int, default=4, help='Number of threads for concurrent processing')
    parser.add_argument('--api-endpoint', required=True, help='API endpoint for storing/retrieving hashes')

    args = parser.parse_args()

    with ThreadPoolExecutor(max_workers=args.threads) as executor:
        futures = {executor.submit(process_file, file_path, args.api_endpoint): file_path for file_path in args.files}

        for future in as_completed(futures):
            file_path = futures[future]
            try:
                future.result()
            except Exception as e:
                logger.error(f"Error processing {file_path}: {e}")

if __name__ == '__main__':
    main()
```

