```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <signal.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Function prototypes
void insertNode(Node** head, int value);
int findMax(Node* head);
void freeList(Node* head);
void handleSignal(int sig);

// Global variables
unsigned long memoryLimit = 1048576; // 1MB in bytes

int main() {
    signal(SIGINT, handleSignal); // Handle Ctrl+C interrupt

    Node* head = NULL;
    int value, bytesRead = 0;

    printf("Enter integers (Ctrl+D to end input):\n");

    while (scanf("%d", &value) == 1) { 
        insertNode(&head, value);
        bytesRead += sizeof(Node) + sizeof(int);

        if (bytesRead > memoryLimit) {
            fprintf(stderr, "Memory limit exceeded.\n");
            freeList(head);
            exit(EXIT_FAILURE);
        }
    }

    if (ferror(stdin)) {
        perror("Input error");
        freeList(head);
        exit(EXIT_FAILURE);
    }

    int max = findMax(head);

    printf("The largest integer is: %d\n", max);
    freeList(head);

    return 0;
}

void insertNode(Node** head, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->value = value;
    newNode->next = *head;
    *head = newNode;
}

int findMax(Node* head) {
    int max = INT_MIN;
    Node* current = head;

    while (current != NULL) {
        if (current->value > max) {
            max = current->value;
        }
        current = current->next;
    }

    return max;
}

void freeList(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void handleSignal(int sig) {
    fprintf(stderr, "\nInterrupt signal received. Exiting...\n");
    exit(EXIT_FAILURE);
}
