// Hypothetical logging function prototype
void log_event(const char* message);

int dynamicStringCopy(char *dest, size_t destSize, const char *src) {
    if (dest == NULL || src == NULL || destSize == 0) {
        log_event("dynamicStringCopy: Invalid arguments");
        return -1;
    }

    size_t srcLen = strlen(src);

    // Calculate the maximum number of characters to copy
    size_t copyLen = (srcLen < destSize - 1) ? srcLen : destSize - 1;

    // Copy the string ensuring null termination
    memcpy(dest, src, copyLen);

    // Null terminate the destination buffer
    dest[copyLen] = '\0';

    if (srcLen >= destSize) {
        log_event("dynamicStringCopy: String truncated");
        char logMessage[256];
        snprintf(logMessage, sizeof(logMessage),
                 "Original length: %zu, Truncated to: %zu", srcLen, copyLen);
        log_event(logMessage);
    }

    return (int)(copyLen + 1); // Return number of characters copied including null terminator
}

// Test cases for dynamicStringCopy function

void test_dynamicStringCopy() {
    char dest[50];

    const char *testCases[] = {
        "Short string",
        "A much longer string that should be truncated because the destination buffer is too small.",
        "",
        NULL,
        (const char[]) {0x61, 0x62, 0x63, '\0'} // 'abc' with null termination
    };

    size_t destSize = sizeof(dest) / sizeof(dest[0]);

    for (int i = 0; i < sizeof(testCases) / sizeof(testCases[0]); ++i) {
        printf("Test case %d:\n", i + 1);
        int result = dynamicStringCopy(dest, destSize, testCases[i]);

        if (result != -1) {
            printf("Result: %d\nCopied string: '%s'\nLength of original string: %zu\n",
                   result,
                   dest,
                   testCases[i] ? strlen(testCases[i]) : 0);
        } else {
            printf("Error copying string.\n");
        }
        printf("\n");
    }
}

int main() {
    // Run test cases
    test_dynamicStringCopy();

    return 0;
}
