                logger.log(Level.SEVERE, "Invalid configuration in service.yaml.");
                return "Error: Invalid configuration.";
            }

            String configHash = calculateSHA256(configFile);

            // Deploy service using external API
            String deploymentResult = deployService(serviceName, region, configParams, configHash);
            if (deploymentResult.equals("Success")) {
                logger.info("Service deployed successfully.");
