                logger.log(Level.SEVERE, "Failed to deploy service: " + deploymentResult);
                return "Error: Deployment failed.";
            }

        } catch (Exception e) {
            logger.log(Level.SEVERE, "An error occurred during configuration and deployment.", e);
            return "Error: An unexpected error occurred.";
        }

        return "Success";
    }

    private boolean isValidServiceConfig(File configFile) throws IOException {
        // Implement validation logic for service.yaml
        // For simplicity, assume it returns true if the file is not empty
        return Files.size(configFile.toPath()) > 0;
    }

    private String calculateSHA256(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream fis = new BufferedInputStream(new FileInputStream(file))) {
            byte[] buffer = new byte[CHUNK_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(digest.digest());
    }

    private String calculateSHA256FromURL(String urlString) throws IOException, NoSuchAlgorithmException {
        HttpURLConnection connection = (HttpURLConnection) new URL(urlString).openConnection();
        connection.setRequestMethod("GET");
        connection.setConnectTimeout(15000);
        connection.setReadTimeout(15000);

        MessageDigest digest = MessageDigest.getInstance("SHA-256");

        try (InputStream fis = new BufferedInputStream(connection.getInputStream())) {
            byte[] buffer = new byte[CHUNK_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }

        return bytesToHex(digest.digest());
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

