Below is an example C program that demonstrates how you might structure such functionality. Note that this solution uses pseudo-code for asynchronous processing because standard C does not natively support async operations like languages such as JavaScript or Python. Instead, we can use POSIX threads (pthreads) to achieve concurrency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>

#define MAX_THREADS 4

typedef struct {
    char *filename;
} thread_data_t;

// Function prototypes
char *process_string(const char *input, size_t size_limit);
void *process_file(void *arg);

// Asynchronous file processor structure
struct AsyncProcessor {
    pthread_t threads[MAX_THREADS];
    int active_threads;
};

// JSON schema validation and summary statistics calculation (pseudo-code)
int validate_json_schema(const char *content) { return 1; }
void calculate_summary_statistics(const char *content) {}

char *process_string(const char *input, size_t size_limit) {
    if (strlen(input) >= size_limit) {
        return NULL;
    }

    size_t new_size = strlen(input) + 2; // for null terminator and slash
    char *result = malloc(new_size);
    if (!result) return NULL;

    strcpy(result, input);
    strcat(result, "/");
    return result;
}

void process_directory(const char *path) {
    DIR *dir = opendir(path);
    if (!dir) {
        fprintf(stderr, "Error: Cannot open directory %s\n", path);
        return;
    }

    struct AsyncProcessor processor = { .active_threads = 0 };

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (processor.active_threads >= MAX_THREADS) break;

        char *file_path = malloc(strlen(path) + strlen(entry->d_name) + 2);
        sprintf(file_path, "%s/%s", path, entry->d_name);

        // Check file extension
        const char *ext = strrchr(entry->d_name, '.');
        if (!ext || (strcmp(ext, ".log") != 0 && strcmp(ext, ".json") != 0 && strcmp(ext, ".csv") != 0)) {
            fprintf(stderr, "Error: Unsupported file type %s\n", entry->d_name);
            free(file_path);
            continue;
        }

        thread_data_t *data = malloc(sizeof(thread_data_t));
        data->filename = file_path;

        pthread_create(&processor.threads[processor.active_threads++], NULL, process_file, (void *)data);
    }

    for (int i = 0; i < processor.active_threads; ++i) {
        pthread_join(processor.threads[i], NULL);
    }

    closedir(dir);
}

void *process_file(void *arg) {
    thread_data_t *data = (thread_data_t *)arg;
    FILE *file = fopen(data->filename, "r");

    if (!file) {
        fprintf(stderr, "Error: Cannot open file %s\n", data->filename);
        free(data->filename);
        free(data);
        pthread_exit(NULL);
    }

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    char *content = malloc(filesize + 1);
    fread(content, 1, filesize, file);
    content[filesize] = '\0';

    fclose(file);

    // Validate and process the file
    if (validate_json_schema(content)) {
        calculate_summary_statistics(content);
    } else {
        fprintf(stderr, "Error: File %s does not match JSON schema\n", data->filename);
    }

    free(content);
    free(data->filename);
    free(data);
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_directory(argv[1]);

    return EXIT_SUCCESS;
}
```

