#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* AppendSlashIfWithinLimit(const char *input, size_t limit)
{
    if (strlen(input) >= limit - 1)
    {
        return NULL;
    }

    size_t newLength = strlen(input) + 2; // Include space for slash and null terminator
    char *result = malloc(newLength);

    if (!result)
    {
        return NULL;
    }

    strcpy(result, input);
    result[newLength - 1] = '/'; // Append slash
    result[newLength] = '\0';

    return result;
}
