def extract_sequence_number_from_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        if not lines:
            raise ValueError("File is empty or has no lines.")

        sorted_lines = sorted(lines)
        last_line = sorted_lines[-1].strip()

        # Extract sequence number from the last line assuming it's at the end
        try:
            sequence_number = int(last_line.split()[-1])
            return sequence_number
        except (IndexError, ValueError):
            raise ValueError("Last line does not contain a valid sequence number.")

    except FileNotFoundError:
        print(f"File {file_path} not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

