async function reduceArrayWithExternalIntegration(numbers, chunkSize = 10) {
  if (!Array.isArray(numbers)) throw new TypeError("Input must be an array.");

  const externalService = new ExternalService();
  let result = 0;

  try {
    for (let i = 0; i < numbers.length; i += chunkSize) {
      const chunk = numbers.slice(i, i + chunkSize);

      // Process each chunk
      await Promise.all(chunk.map(async (num) => {
        if (typeof num !== 'number') throw new TypeError("Array must contain only numbers.");

        try {
          const externalNumber = await externalService.getCurrentNumber();
          result += num + externalNumber;

          console.log(`Processed: ${num} with external number ${externalNumber}, current sum is ${result}`);
        } catch (error) {
          console.error("Error fetching from external service, retrying...", error);
          // Retry mechanism
          await new Promise(resolve => setTimeout(resolve, 1000));
          const retryExternalNumber = await externalService.getCurrentNumber();
          result += num + retryExternalNumber;
        }
      }));
    }

    return result;

  } catch (error) {
    console.error("An error occurred during reduction process:", error);
    throw error; // Rethrow after logging
  } finally {
    console.log("Reduction process completed.");
  }
}

// Example usage:
