import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.util.regex.*;
import java.util.logging.*;
import com.google.common.cache.*;

public class LogProcessorModule {

    private static final Logger logger = Logger.getLogger(LogProcessorModule.class.getName());
    private final ScheduledExecutorService reportScheduler = Executors.newScheduledThreadPool(1);
    private final ConcurrentHashMap<String, String> cache = CacheBuilder.newBuilder()
            .maximumSize(100)
            .build();
    private final ExecutorService logProcessingPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public void start() {
        scheduleReports();
        processLogsFromServers();
    }

    private void scheduleReports() {
        reportScheduler.scheduleAtFixedRate(this::generateSummaryReport, 0, 1, TimeUnit.HOURS);
    }

    private void generateSummaryReport() {
        try (InputStream is = new ProcessBuilder("sh", "generate_report.sh").start().getInputStream()) {
            String summary = new BufferedReader(new InputStreamReader(is)).lines().collect(Collectors.joining("\n"));
            sendToExternalReportingAPI(summary);
        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Error generating report: ", e);
        }
    }

    private void processLogsFromServers() {
        // Simulate fetching from multiple servers
        List<String> serverURLs = getRemoteServerURLs();

        for (String url : serverURLs) {
            logProcessingPool.submit(() -> processLogFile(url));
        }
    }

    private List<String> getRemoteServerURLs() {
        // Fetch the list of remote server URLs
        return List.of("http://server1/logs", "http://server2/logs");
    }

    private void processLogFile(String url) {
        try (InputStream is = new URL(url).openStream()) {
            String logs = new BufferedReader(new InputStreamReader(is)).lines().collect(Collectors.joining("\n"));
            Pattern pattern = getDynamicPattern();
            Matcher matcher = pattern.matcher(logs);

            while (matcher.find()) {
                String logLine = matcher.group();
                logger.info("Found matching line: " + logLine);
                cacheReport(logLine, url); // Caching mechanism
            }
        } catch (IOException e) {
            logger.log(Level.WARNING, "Error processing log file from URL: " + url, e);
        }
    }

    private Pattern getDynamicPattern() {
        String regex = "(error|warning).*"; // Configurable pattern
        return Pattern.compile(regex, Pattern.CASE_INSENSITIVE);
    }

    private void cacheReport(String line, String url) {
        if (!cache.asMap().containsKey(url)) {
            cache.put(url, line);
        }
    }

    private void sendToExternalReportingAPI(String report) {
        try (Socket socket = new Socket("external.api.url", 80)) {
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            out.println(report);

            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            String response;
            while ((response = in.readLine()) != null) {
                logger.info("API Response: " + response);
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error communicating with external API", e);
        }
    }

    public static void main(String[] args) {
        LogProcessorModule module = new LogProcessorModule();
        module.start();
    }
}
```

