```java
import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;

@Service
public class JwtService {

    private final KeyManagementService keyManagementService; // Abstracts AWS, Azure, Google KMS

    public JwtService(KeyManagementService keyManagementService) {
        this.keyManagementService = keyManagementService;
    }

    public String generateToken(String subject) {
        Algorithm algorithm = getAlgorithmFromKms();
        return JWT.create()
                .withSubject(subject)
                .sign(algorithm);
    }

    private Algorithm getAlgorithmFromKms() {
        // Retrieve the private key from KMS
        byte[] privateKey = keyManagementService.getPrivateKey();
        return Algorithm.RSA256(null, privateKey); // Use appropriate algorithm based on key type
    }
}

// Abstract Key Management Service
public interface KeyManagementService {
    byte[] getPrivateKey();
}
```

