```java
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bandwidth;
import org.springframework.stereotype.Service;

@Service
public class RateLimiter {

    private final Bucket bucket = createBucket(10, 1); // 10 requests per second

    public boolean isAllowed() {
        return bucket.tryConsume(1);
    }

    private static Bucket createBucket(long refillTokens, long refillTokensPerSecond) {
        Bandwidth limit = Bandwidth.classic(refillTokens, refillTokensPerSecond);
        return Bucket.builder().addLimit(limit).build();
    }
}
