public class ImageToPdfConverter {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java ImageToPdfConverter <output-file> <input-directory>");
            System.exit(1);
        }

        String outputFilePath = args[0];
        File inputDirectory = new File(args[1]);

        if (!inputDirectory.isDirectory()) {
            System.err.println("The specified path is not a directory.");
            System.exit(1);
        }

        try {
            runConversion(inputDirectory, outputFilePath).join();
        } catch (Exception e) {
            System.err.println("An error occurred during conversion: " + e.getMessage());
            System.exit(1);
        }
    }

    private static CompletableFuture<Void> runConversion(File directory, String outputFilePath) {
        List<File> imageFiles = Files.walk(directory.toPath())
                .filter(path -> path.toString().endsWith(".jpg") || 
                                path.toString().endsWith(".jpeg") ||
                                path.toString().endsWith(".png") ||
