Below is a C-based implementation using OpenSSL to create an encryption service with AES-256-GCM that meets the described requirements. Note that this code assumes you have appropriate setup for linking with OpenSSL libraries (such as `-lcrypto`), error handling, and integration with a KMS.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define AES_256_GCM_KEY_LEN 32
#define AES_256_GCM_IV_LEN 12
#define AES_256_GCM_TAG_LEN 16

// Structure to hold the encryption context and related information.
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[AES_256_GCM_KEY_LEN];
    unsigned char iv[AES_256_GCM_IV_LEN];
} aes_gcm_ctx;

// Function prototypes
aes_gcm_ctx* init_aes_gcm_context(const char *password, const unsigned char *salt);
int cleanup_aes_gcm_context(aes_gcm_ctx *ctx);
int encrypt_data(aes_gcm_ctx *ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char **ciphertext, size_t *ciphertext_len,
                 unsigned char *tag);

// Initialize AES-256-GCM context
aes_gcm_ctx* init_aes_gcm_context(const char *password, const unsigned char *salt) {
    if (!password || !salt) return NULL;

    aes_gcm_ctx *ctx = (aes_gcm_ctx*) malloc(sizeof(aes_gcm_ctx));
    if (!ctx) {
        perror("Failed to allocate memory for AES context");
        return NULL;
    }

    // Generate the key using PBKDF2
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 16, 10000,
                          EVP_sha256(), AES_256_GCM_KEY_LEN, ctx->key) != 1) {
        free(ctx);
        fprintf(stderr, "Failed to derive key\n");
        return NULL;
    }

    // Generate a secure IV
    if (!RAND_bytes(ctx->iv, AES_256_GCM_IV_LEN)) {
        free(ctx);
        fprintf(stderr, "Failed to generate random bytes for IV\n");
        return NULL;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        cleanup_aes_gcm_context(ctx);
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    // Initialize encryption operation with AES-256-GCM
    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key,
                                ctx->iv)) {
        cleanup_aes_gcm_context(ctx);
        fprintf(stderr, "Encryption initialization failed\n");
        return NULL;
    }

    return ctx;
}

// Cleanup AES-256-GCM context
int cleanup_aes_gcm_context(aes_gcm_ctx *ctx) {
    if (ctx) {
        if (ctx->ctx)
            EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
    return 0;
}

// Encrypt data using the initialized AES-256-GCM context
int encrypt_data(aes_gcm_ctx *ctx, const unsigned char *plaintext,
                 int plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len,
                 unsigned char *tag) {
    if (!ctx || !ciphertext || !plaintext_len > 0) return -1;

    EVP_CIPHER_CTX *cipher_ctx = ctx->ctx;
    int len, ciphertext_size;
    *ciphertext_len = plaintext_len + AES_256_GCM_TAG_LEN;
    *ciphertext = (unsigned char*) malloc(*ciphertext_len);
    if (!*ciphertext) {
        perror("Failed to allocate memory for ciphertext");
        return -1;
    }

    // Perform encryption
    if (1 != EVP_EncryptUpdate(cipher_ctx, *ciphertext, &len, plaintext,
                               plaintext_len)) {
        free(*ciphertext);
        fprintf(stderr, "Encryption update failed\n");
        return -1;
    }
    ciphertext_size = len;

    // Finalize encryption and get the tag
    if (1 != EVP_EncryptFinal_ex(cipher_ctx, *ciphertext + ciphertext_size,
                                 &len)) {
        free(*ciphertext);
        fprintf(stderr, "Encryption finalization failed\n");
        return -1;
    }
    ciphertext_size += len;

    // Generate authentication tag
    if (1 != EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_GET_TAG,
                                 AES_256_GCM_TAG_LEN, tag)) {
        free(*ciphertext);
        fprintf(stderr, "Failed to get encryption tag\n");
        return -1;
    }

    *ciphertext_len = ciphertext_size;
    return 0;
}

// Example usage
int main() {
    const char *password = "strong_password";
    unsigned char salt[16] = { /* Populate with a secure random value or from KMS */ };

    aes_gcm_ctx *ctx = init_aes_gcm_context(password, salt);
    if (!ctx) return 1;

    const char *plaintext = "This is some data to encrypt.";
    unsigned char *ciphertext;
    size_t ciphertext_len;
    unsigned char tag[AES_256_GCM_TAG_LEN];

    if (encrypt_data(ctx, (unsigned char*) plaintext, strlen(plaintext), &ciphertext,
                     &ciphertext_len, tag) != 0) {
        cleanup_aes_gcm_context(ctx);
        return 1;
    }

    // Use ciphertext and tag for further processing
    printf("Ciphertext length: %zu\n", ciphertext_len);

    free(ciphertext);
    cleanup_aes_gcm_context(ctx);
    return 0;
}
```

### Explanation:

- **Dynamic Initialization**: The `init_aes_gcm_context` function initializes an AES-256-GCM cipher context using a password and salt to derive the encryption key with PBKDF2.

- **Resource Management**: Memory for contexts is allocated dynamically, and resources are cleaned up properly in the `cleanup_aes_gcm_context` function.

- **Concurrency Considerations**: This example does not directly implement concurrency primitives. For real-world usage, you might use mutexes or other synchronization mechanisms to protect shared data structures in multi-threaded environments.

- **Error Handling**: The code checks for errors at various stages and outputs appropriate messages if something goes wrong.

This implementation sets the foundation for a service that encrypts data using AES-256-GCM. You would need to extend it further to integrate with external KMS, handle decryption, and support multi-threaded operations as per your cloud deployment requirements.

