```java
import java.util.concurrent.*;
import java.util.*;
import java.sql.*;

public class ServiceManager {

    private static final String DB_URL = "jdbc:your_database_url";
    private static final String USER = "username";
    private static final String PASS = "password";

    private ExecutorService executor;
    private int numServices;
    private long maxDelayMillis;

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        manager.loadConfigurations();
        manager.startManagingServices();

        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.println("Enter command: [config, status, exit]");
            String command = scanner.nextLine().trim();

            switch (command) {
                case "config":
                    manager.updateConfiguration(scanner);
                    break;
                case "status":
                    manager.displayStatus();
                    break;
                case "exit":
                    manager.shutdown();
                    return;
                default:
                    System.out.println("Invalid command.");
            }
        }
    }

    private void loadConfigurations() {
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery("SELECT * FROM configuration");

            if (rs.next()) {
                numServices = rs.getInt("num_services");
                maxDelayMillis = rs.getLong("max_delay_millis");
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        executor = Executors.newFixedThreadPool(numServices);
    }

    private void startManagingServices() {
        for (int i = 0; i < numServices; i++) {
            int serviceId = i;
            executor.submit(() -> manageService(serviceId));
        }
    }

    private void manageService(int serviceId) {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                if (startService(serviceId)) {
                    logStatus(serviceId, "Started");
                } else {
                    handleFailedStart(serviceId);
                }
                sendStopMessage(serviceId);

                Thread.sleep(getRandomDelay());
            } catch (InterruptedException | Exception e) {
                logError(serviceId, e.getMessage());
                break;
            }
        }
    }

    private boolean startService(int serviceId) throws Exception {
        // Simulate starting a service
        return true;  // or false if failed to start
    }

    private void sendStopMessage(int serviceId) throws SQLException {
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
            PreparedStatement pstmt = conn.prepareStatement("INSERT INTO messages (service_id, status) VALUES (?, ?)");
            pstmt.setInt(1, serviceId);
            pstmt.setString(2, "Stopped");
            pstmt.executeUpdate();
        }
    }

    private long getRandomDelay() {
        return ThreadLocalRandom.current().nextLong(maxDelayMillis);
    }

    private void handleFailedStart(int serviceId) {
        // Implement retry logic
    }

    private void logStatus(int serviceId, String status) {
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
            PreparedStatement pstmt = conn.prepareStatement("INSERT INTO service_status (service_id, status) VALUES (?, ?)");
            pstmt.setInt(1, serviceId);
            pstmt.setString(2, status);
            pstmt.executeUpdate();
        } catch (SQLException e) {
            logError(serviceId, "Failed to log status: " + e.getMessage());
        }
    }

    private void logError(int serviceId, String message) {
        System.err.println("Service ID: " + serviceId + ", Error: " + message);
    }

    private void updateConfiguration(Scanner scanner) {
        try {
            System.out.print("Enter number of services: ");
            int numServices = Integer.parseInt(scanner.nextLine());

            System.out.print("Enter max delay (in ms): ");
            long maxDelayMillis = Long.parseLong(scanner.nextLine());

            try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
                PreparedStatement pstmt = conn.prepareStatement("UPDATE configuration SET num_services = ?, max_delay_millis = ?");
                pstmt.setInt(1, numServices);
                pstmt.setLong(2, maxDelayMillis);
                pstmt.executeUpdate();

                this.numServices = numServices;
                this.maxDelayMillis = maxDelayMillis;
            }
        } catch (SQLException | NumberFormatException e) {
            System.err.println("Invalid configuration: " + e.getMessage());
        }

        executor.shutdown();
        executor = Executors.newFixedThreadPool(numServices);
        startManagingServices();
    }

    private void displayStatus() {
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS)) {
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery("SELECT * FROM service_status");

            while (rs.next()) {
                int serviceId = rs.getInt("service_id");
                String status = rs.getString("status");
                System.out.println("Service ID: " + serviceId + ", Status: " + status);
            }
        } catch (SQLException e) {
            logError(-1, "Failed to fetch statuses: " + e.getMessage());
        }
    }

    private void shutdown() {
        executor.shutdownNow();
    }
}
