#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Hypothetical logging function (thread-safe)
void log_truncation_event(size_t original_length, size_t truncated_length) {
    // Log truncation event with relevant details
    printf("Truncated: Original Length = %zu, Truncated Length = %zu\n", original_length, truncated_length);
}

pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void dynamicStringCopy(char *dest, const char *src, size_t destSize) {
    if (dest == NULL || src == NULL) return;

    pthread_mutex_lock(&log_lock);

    size_t len = strlen(src);
    size_t copyLength = (len + 1 < destSize) ? len : destSize - 1; // Ensure null-termination

    memcpy(dest, src, copyLength);
    dest[copyLength] = '\0';

    if (len >= destSize) {
        log_truncation_event(len, copyLength);
    }

    pthread_mutex_unlock(&log_lock);
}
