```python
import hashlib

class FileHasher:
    def calculate_md5_hash_from_file(self, file_path, chunk_size=8192):
        """Calculate MD5 hash of a file given its path."""
        md5 = hashlib.md5()

        try:
            with open(file_path, 'rb') as f:
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break
                    md5.update(chunk)
        except IOError as e:
            print(f"Error reading file {file_path}: {e}")

        return md5.hexdigest()
