using System;
using System.Data;
using System.Data.SqlClient;

public class FileHasher {
    public DataTableReader execute_query_and_return_result(SqlConnection connection, byte[] queryBytes) {
        if (connection == null || queryBytes == null)
            throw new ArgumentNullException("Connection or Query bytes cannot be null");

        try {
            // Convert the byte array to a string assuming it is UTF-8 encoded
            string queryString = System.Text.Encoding.UTF8.GetString(queryBytes);

            SqlCommand command = new SqlCommand(queryString, connection);

            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable dataTable = new DataTable();
            adapter.Fill(dataTable);

            return dataTable.CreateDataReader();
        } catch (Exception ex) {
            Console.WriteLine($"Error executing query: {ex.Message}");
            throw;
        }
    }
}
