```java
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;
import javax.imageio.ImageIO;
import org.apache.commons.imaging.Imaging;

public class ImageProcessingUtility {

    private final ExecutorService executorService = Executors.newCachedThreadPool();

    public List<Path> batchConvertImages(List<Path> inputPaths, String outputFormat) {
        return inputPaths.parallelStream()
                .map(this::convertImageFormat)
                .filter(Objects::nonNull)
                .toList();
    }

    private Path convertImageFormat(Path inputPath) {
        try (InputStream inputStream = Files.newInputStream(inputPath)) {
            BufferedImage image = ImageIO.read(inputStream);
            if (image == null) throw new IllegalArgumentException("Invalid image format");

            String fileNameWithoutExt = inputPath.getFileName().toString().replaceFirst("[.][^.]+$", "");
            Path outputPath = inputPath.resolveSibling(fileNameWithoutExt + "." + outputFormat.toLowerCase());

            ImageIO.write(image, outputFormat, Files.newOutputStream(outputPath));
            return outputPath;
        } catch (IOException e) {
            System.err.println("Error converting image: " + e.getMessage());
            return null;
        }
    }

    public List<Path> batchResizeImages(List<Path> inputPaths, int targetWidth, int targetHeight) {
        return inputPaths.parallelStream()
                .map(path -> resizeImage(path, targetWidth, targetHeight))
                .filter(Objects::nonNull)
                .toList();
    }

    private Path resizeImage(Path path, int targetWidth, int targetHeight) {
        try (InputStream inputStream = Files.newInputStream(path)) {
            BufferedImage originalImage = ImageIO.read(inputStream);
            if (originalImage == null) throw new IllegalArgumentException("Invalid image format");

            BufferedImage resizedImage = new BufferedImage(targetWidth, targetHeight, originalImage.getType());
            resizedImage.getGraphics().drawImage(originalImage.getScaledInstance(targetWidth, targetHeight, java.awt.Image.SCALE_SMOOTH), 0, 0, null);

            String fileNameWithoutExt = path.getFileName().toString().replaceFirst("[.][^.]+$", "");
            Path outputPath = path.resolveSibling(fileNameWithoutExt + "_resized.png");

            ImageIO.write(resizedImage, "png", Files.newOutputStream(outputPath));
            return outputPath;
        } catch (IOException e) {
            System.err.println("Error resizing image: " + e.getMessage());
            return null;
        }
    }

    public List<Path> batchCropImages(List<Path> inputPaths, int startX, int startY, int width, int height) {
        return inputPaths.parallelStream()
                .map(path -> cropImage(path, startX, startY, width, height))
                .filter(Objects::nonNull)
                .toList();
    }

    private Path cropImage(Path path, int startX, int startY, int width, int height) {
        try (InputStream inputStream = Files.newInputStream(path)) {
            BufferedImage originalImage = ImageIO.read(inputStream);
            if (originalImage == null) throw new IllegalArgumentException("Invalid image format");

            BufferedImage croppedImage = originalImage.getSubimage(startX, startY, width, height);

            String fileNameWithoutExt = path.getFileName().toString().replaceFirst("[.][^.]+$", "");
            Path outputPath = path.resolveSibling(fileNameWithoutExt + "_cropped.png");

            ImageIO.write(croppedImage, "png", Files.newOutputStream(outputPath));
            return outputPath;
        } catch (IOException e) {
            System.err.println("Error cropping image: " + e.getMessage());
            return null;
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    // Implement additional methods for metadata extraction and logging as needed.
}
```

