# Jenkinsfile - CI/CD Pipeline Definition

pipeline {
    agent any

    environment {
        DOCKER_REGISTRY = 'docker.io'
        KUBECONFIG_PATH = '/home/jenkins/.kube/config'
    }

    stages {
        stage('Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/your-repo.git'
            }
        }

        stage('Build Docker Images') {
            parallel {
                stage('Service A') {
                    steps {
                        script {
                            docker.build("service-a:${env.BUILD_ID}", "--target builder -f Dockerfile.builder ./serviceA").inside {
                                sh 'make build && make test'
                            }
                            docker.image("service-a:${env.BUILD_ID}").push("${DOCKER_REGISTRY}/service-a:latest")
                        }
                    }
                }

                stage('Service B') {
                    steps {
                        script {
                            docker.build("service-b:${env.BUILD_ID}", "--target builder -f Dockerfile.builder ./serviceB").inside {
                                sh 'make build && make test'
                            }
                            docker.image("service-b:${env.BUILD_ID}").push("${DOCKER_REGISTRY}/service-b:latest")
                        }
                    }
                }
            }
        }

        stage('Deploy to Staging') {
            when {
                branch 'main'
            }
            steps {
                script {
                    kubernetesDeploy(
                        configs: "k8s/staging/*.yaml",
                        kubeconfigId: "${KUBECONFIG_PATH}"
                    )
                }
            }
        }

        stage('Run E2E Tests on Staging') {
            when {
                branch 'main'
            }
            steps {
                script {
                    sh './run-e2e-tests.sh staging'
                }
            }
        }

        stage('Deploy to Production') {
            when {
                branch 'release/*'
            }
            steps {
                input message: "Approve deployment to production?", ok: "Deploy"
                script {
                    kubernetesDeploy(
                        configs: "k8s/production/*.yaml",
                        kubeconfigId: "${KUBECONFIG_PATH}"
                    )
                }
            }
        }

        stage('Post-Deployment Monitoring') {
            when {
                branch 'release/*'
            }
            steps {
                script {
                    sh './monitor.sh --alert-threshold=10'
                }
            }
        }
    }

    post {
        always {
            archiveArtifacts artifacts: '**/target/*.jar', allowEmptyArchive: true
        }

        failure {
            mail to: 'team@example.com',
                 subject: "Build ${currentBuild.fullDisplayName} Failed",
                 body: "Please check the Jenkins console output at: ${env.BUILD_URL}"
        }
    }
}

