// WebSocketEncryption.js

const crypto = require('crypto');
const WebSocket = require('ws');

class WebSocketEncryption {
    constructor(config) {
        this.config = config;
        this.key = crypto.scryptSync(this.config.salt, this.config.password, 16);
        this.iv = Buffer.alloc(16, 0); // Using zero IV for simplicity; in practice, use a random or unique IV.
    }

    encrypt(data) {
        const cipher = crypto.createCipheriv('aes-256-cbc', this.key, this.iv);
        let encrypted = cipher.update(data, 'utf8', 'hex');
        encrypted += cipher.final('hex');
        return encrypted;
    }

    decrypt(encryptedData) {
        const decipher = crypto.createDecipheriv('aes-256-cbc', this.key, this.iv);
        let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
        decrypted += decipher.final('utf8');
        return decrypted;
    }
}

// WebSocket connection setup
const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
    const encryptionHandler = new WebSocketEncryption({
        password: 'your-secret-password',
        salt: 'salt-value'
    });

    ws.on('message', (data) => {
        const encryptedData = encryptionHandler.encrypt(data);
        // Process or forward the data as needed
    });

    ws.send(encryptionHandler.encrypt('Welcome to the secure WebSocket server!'));
});

module.exports = { WebSocketEncryption };
