        }
    }

    private async Task<Stream> ExtractZipEntry(Stream zipFileStream)
    {
        using var archive = new ZipArchive(zipFileStream, ZipArchiveMode.Read);
        var entry = archive.Entries[0]; // Assuming single file in the zip
        return await entry.OpenAsync();
