```python
import asyncio
import aiohttp
from datetime import datetime
import logging

# Setting up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class TranscodingServiceError(Exception):
    pass

async def query_metadata(video_file_name: str) -> dict:
    async with aiohttp.ClientSession() as session:
        try:
            async with session.get(f'http://metadata-service/api/videos/{video_file_name}') as response:
                if response.status == 200:
                    return await response.json()
                else:
                    raise TranscodingServiceError("Failed to retrieve metadata")
        except Exception as e:
            logger.error(f"Metadata query error: {e}")
            raise

async def split_video(metadata: dict) -> list:
    # Dummy implementation for splitting logic
    segments = []
    duration = metadata.get('duration', 0)
    segment_length = 60  # Split every minute
    num_segments = int(duration / segment_length) + (1 if duration % segment_length > 0 else 0)

    for i in range(num_segments):
        start_time = i * segment_length
        end_time = min(start_time + segment_length, duration)
        segments.append({'start': start_time, 'end': end_time})

    return segments

async def transcode_segment(segment: dict, format_type: str) -> bool:
    # Dummy implementation for transcoding logic
    async with aiohttp.ClientSession() as session:
        try:
            logger.info(f"Transcoding segment {segment} to {format_type}")

            async with session.post('http://transcoding-service/api/transcode', json=segment) as response:
                if response.status == 200:
                    return True
                else:
                    raise TranscodingServiceError(f"Failed to transcode segment {segment} to {format_type}")
        except Exception as e:
            logger.error(f"Transcoding error: {e}")
            return False

async def transcode_video(video_file_name: str, output_directory: str) -> dict:
    try:
        metadata = await query_metadata(video_file_name)
        segments = await split_video(metadata)

        formats = ['MP4', 'WebM', 'MKV']
        results = {fmt: [] for fmt in formats}

        tasks = []
        for format_type in formats:
            for segment in segments:
                task = asyncio.create_task(transcode_segment(segment, format_type))
                tasks.append((format_type, task))

        for format_type, task in tasks:
            result = await task
            results[format_type].append(result)

        # Check if any transcodings failed
        for fmt, outcomes in results.items():
            if not all(outcomes):
                return {"error": f"Transcoding failed for {fmt}"}

        logger.info(f"Transcoding completed successfully for {video_file_name}")
        return {"status": "success", "details": results}

    except TranscodingServiceError as e:
        logger.error(f"Transcoding process encountered an error: {e}")
        return {"error_code": 500}

# To run the asynchronous function
def main():
    video_file = 'sample_video.mp4'
    output_dir = '/path/to/output/directory'

    result = asyncio.run(transcode_video(video_file, output_dir))
    logger.info(f"Result: {result}")

if __name__ == "__main__":
    main()
