from dotenv import load_dotenv
import redis
import threading
from functools import lru_cache
from time import sleep
import random

# Load environment variables from .env files
def load_env_files():
    load_dotenv()
    if os.path.exists('.env.local'):
        load_dotenv(dotenv_path='.env.local')

load_env_files()

# Thread-safe storage for configuration settings
config_lock = threading.Lock()
configuration_cache = {}

def get_config(key, default=None):
    with config_lock:
        return configuration_cache.get(key, os.getenv(key, default))

def set_config(key, value):
    with config_lock:
        configuration_cache[key] = value

# Retry decorator with exponential backoff
def retry(max_attempts=5, base_delay=1.0):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempt = 0
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    delay = base_delay * (2 ** attempt) + random.uniform(0, 1)
                    logging.warning(f"Attempt {attempt+1} failed with error: {e}. Retrying in {delay:.2f}s...")
                    sleep(delay)
                    attempt += 1
            raise Exception("Max retry attempts reached")
        return wrapper
    return decorator

# Database connection setup
class DatabaseConnection:
    def __init__(self):
        self.db_env = get_config('DB_ENV', 'development')
        self.connections = {
            'development': 'dev_db_connection_string',
            'testing': 'test_db_connection_string',
            'production': 'prod_db_connection_string'
        }

    @retry()
    def connect(self):
        db_url = self.connections.get(self.db_env)
        if not db_url:
            raise ValueError(f"No database connection string found for environment: {self.db_env}")
        logging.info(f"Connecting to the database with URL: {db_url}")
        # Simulate a database connection
        return f"Connected to {db_url}"

# Cache setup
class CacheManager:
    def __init__(self):
        self.cache_type = get_config('CACHE_TYPE', 'redis')

    @retry()
    def connect(self):
        if self.cache_type == 'redis':
            logging.info("Initializing Redis cache")
            return redis.Redis(host='localhost', port=6379, db=0)
        elif self.cache_type == 'memcached':
            # Initialize memcached connection
            logging.info("Initializing Memcached cache")
            pass
        else:
            raise ValueError(f"Unsupported cache type: {self.cache_type}")

    @lru_cache(maxsize=128)
    def get_cached_data(self, key):
        return None  # Simulate fetching cached data

# Third-party service initialization
class ServiceManager:
    def __init__(self):
        self.services = {
            'email': {'host': get_config('EMAIL_HOST'), 'port': get_config('EMAIL_PORT', 587)},
            'payment': {'api_key': get_config('PAYMENT_API_KEY')},
            'auth': {'endpoint': get_config('AUTH_ENDPOINT')}
        }

    @retry()
    def initialize_services(self):
        for service, config in self.services.items():
            if not all(config.values()):
                raise ValueError(f"Missing configuration for {service} service")
            logging.info(f"{service.capitalize()} Service initialized with config: {config}")

# Logging setup
class Logger:
    def __init__(self):
        self.log_level = get_config('LOG_LEVEL', 'INFO').upper()
        logging.basicConfig(level=self.log_level, format='%(asctime)s - %(levelname)s - %(message)s')

    @staticmethod
    def log(message, level='info'):
        if level.lower() == 'error':
            logging.error(message)
        elif level.lower() == 'warning':
            logging.warning(message)
        else:
            logging.info(message)

# Main application setup
class Application:
    def __init__(self):
        self.logger = Logger()
        self.db_connection = DatabaseConnection()
        self.cache_manager = CacheManager()
        self.service_manager = ServiceManager()

    def initialize(self):
        try:
            self.logger.log("Initializing database connection")
            db_conn = self.db_connection.connect()

            self.logger.log("Initializing cache manager")
            cache = self.cache_manager.connect()

            self.logger.log("Initializing third-party services")
            self.service_manager.initialize_services()

        except Exception as e:
            self.logger.log(f"Initialization error: {e}", level='error')
            raise

if __name__ == "__main__":
    app = Application()
    app.initialize()
