### Real-time Sensor Data Processing

```python
from confluent_kafka import Producer, KafkaError
import jsonschema
import cassandra.cluster
from cassandra.query import BatchStatement

# Define the JSON schema for sensor data validation
SENSOR_DATA_SCHEMA = {
    "type": "object",
    "properties": {
        "temperature": {"type": "number"},
        "humidity": {"type": "number"},
        # Additional fields as needed
    },
    "required": ["temperature", "humidity"]
}

def process_sensor_data(sensor_data):
    try:
        jsonschema.validate(instance=sensor_data, schema=SENSOR_DATA_SCHEMA)

        # Connect to Cassandra and batch insert sensor data
        cluster = cassandra.cluster.Cluster(['localhost'])
        session = cluster.connect('sensor_keyspace')

        query = """
        INSERT INTO sensor_data (device_id, timestamp, temperature, humidity) 
        VALUES (%s, %s, %s, %s)
        """

        prepared = session.prepare(query)
        batch = BatchStatement()
        batch.add(prepared.bind(sensor_data['device_id'],
                                sensor_data['timestamp'],
                                sensor_data['temperature'],
                                sensor_data['humidity']))

        # Execute the batch statement
        session.execute(batch)

    except jsonschema.exceptions.ValidationError as e:
        print(f"Invalid data format: {e}")
    except Exception as e:
        print(f"Error processing sensor data: {e}")

# Example usage
sensor_data = {
    "device_id": "device123",
    "timestamp": 1625072034,
    "temperature": 22.5,
    "humidity": 45.2
}

process_sensor_data(sensor_data)
