### Python Function: Process Order and Calculate MD5

```python
import hashlib
import os
from datetime import datetime, timedelta
import logging
from storage_backend_interface import StorageBackend
from payment_gateway import PaymentGateway
from email_service import EmailService

# Configure logging
logging.basicConfig(filename='order_processing.log', level=logging.INFO)

class RateLimiter:
    def __init__(self):
        self.orders = {}

    def is_allowed(self, customer_id):
        now = datetime.now()
        if customer_id not in self.orders or now - self.orders[customer_id] > timedelta(hours=1):
            self.orders[customer_id] = now
            return True
        return False

def process_order_and_calculate_md5(order_details, file_path, storage_backend: StorageBackend,
                                    payment_gateway: PaymentGateway, email_service: EmailService):
    customer_id = order_details['customer_id']

    rate_limiter = RateLimiter()
    if not rate_limiter.is_allowed(customer_id):
        logging.error(f"Rate limit exceeded for customer {customer_id}")
        return

    try:
        with open(file_path, 'rb') as f:
            file_hash = hashlib.md5()
            while chunk := f.read(8192):
                file_hash.update(chunk)

        storage_backend.save_file_hash(customer_id, file_hash.hexdigest())

        payment_gateway.charge(order_details['amount'])
        email_service.send_email(order_details['customer_email'], 'Order Confirmation')
        logging.info(f"Processed order {order_details['id']} for customer {customer_id}")

    except Exception as e:
        logging.error(f"Error processing order: {e}")

def clean_old_logs():
    now = datetime.now()
    cutoff_date = now - timedelta(days=90)
    # Logic to remove logs older than 90 days
