```cpp
#include <iostream>
#include <random>
#include <mutex>
#include <thread>
#include <vector>

class RandomNumberGenerator {
public:
    RandomNumberGenerator(unsigned long seed) : rng(seed), gen(seed) {}

    int generateInteger(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Invalid range for integer generation");

        std::uniform_int_distribution<int> dist(min, max);
        return dist(gen);
    }

    double generateFloat(double min, double max) {
        std::lock_guard<std::mutex> lock(mtx);
        if (min > max) throw std::invalid_argument("Invalid range for float generation");

        std::uniform_real_distribution<double> dist(min, max);
        return dist(gen);
    }

private:
    std::mt19937 gen;
    std::random_device rng; // Only used to seed the mt19937 in constructor
    std::mutex mtx;
};

// Unit test example (simple demonstration)
void testRandomNumberGenerator() {
    RandomNumberGenerator rng(12345);

    int minInt = 1, maxInt = 10;
    double minFloat = 0.5, maxFloat = 2.5;

    for (int i = 0; i < 100; ++i) {
        std::cout << "Random Int: " << rng.generateInteger(minInt, maxInt) << std::endl;
        std::cout << "Random Float: " << rng.generateFloat(minFloat, maxFloat) << std::endl;
    }
}

int main() {
    testRandomNumberGenerator();

    // Demonstrate thread safety
    RandomNumberGenerator sharedRng(67890);

    auto task = [&sharedRng]() {
        for (int i = 0; i < 100; ++i) {
            int randInt = sharedRng.generateInteger(1, 100);
            double randFloat = sharedRng.generateFloat(-1.0, 1.0);
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(task);
    }

    for (auto& th : threads) {
        th.join();
    }

    return 0;
}
```

### Explanation:

- **RandomNumberGenerator Class**: 
  - The class uses `std::mt19937` for generating random numbers and ensures thread safety using a mutex (`std::mutex mtx`).
  - The constructor initializes the RNG with a seed value.
  - Two methods, `generateInteger` and `generateFloat`, provide ways to generate random integers and floating-point numbers within specified ranges. These methods are synchronized using `std::lock_guard`.

- **Thread Safety**:
  - The use of `std::mutex mtx` ensures that only one thread can access the RNG state at a time, preventing race conditions.

- **Error Handling**:
  - Both generation methods check for invalid range inputs and throw exceptions if necessary.

- **Unit Testing**:
  - A simple unit test function (`testRandomNumberGenerator`) is provided to demonstrate usage. It generates random numbers in a single-threaded context.
  - The `main` function demonstrates the thread safety of the RNG by creating multiple threads that generate random numbers concurrently. 

This code provides a robust, multi-threaded random number generator with basic testing and error handling, making it suitable for high-performance applications requiring concurrent access to random number generation.

