```python
import threading
import queue
import logging
from datetime import datetime
from typing import Dict, Any
from concurrent.futures import ThreadPoolExecutor
import requests

# Configure Logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DeviceData:
    def __init__(self, device_id: str, sensor_values: Dict[str, float], timestamp: datetime, metadata: Dict[str, str]):
        self.device_id = device_id
        self.sensor_values = sensor_values
        self.timestamp = timestamp
        self.metadata = metadata

class IoTDataHandler:
    def __init__(self, max_workers: int = 10, cache_size: int = 1000):
        self.data_queue = queue.Queue()
        self.cache = {}
        self.lock = threading.Lock()
        self.executor = ThreadPoolExecutor(max_workers=max_workers)
        self.cache_size = cache_size

    def ingest_data(self, device_id: str, sensor_values: Dict[str, float], metadata: Dict[str, str]):
        try:
            timestamp = datetime.now()
            data_point = DeviceData(device_id, sensor_values, timestamp, metadata)
            self.data_queue.put(data_point)
            logger.info(f"Data ingested from {device_id}")
        except Exception as e:
            logger.error(f"Error during ingestion: {e}")

    def process_data(self):
        while True:
            data_point = self.data_queue.get()
            if data_point is None:
                break
            try:
                self.executor.submit(self._process_single_data_point, data_point)
            except Exception as e:
                logger.error(f"Error in processing: {e}")

    def _process_single_data_point(self, data_point: DeviceData):
        with self.lock:
            if len(self.cache) >= self.cache_size:
                self.cache.pop(next(iter(self.cache)))

            # Simulate processing
            cache_key = (data_point.device_id, data_point.timestamp)
            self.cache[cache_key] = data_point

            logger.info(f"Processed data from {data_point.device_id}")

            # Call external analytics API
            try:
                response = requests.post("https://api.analytics.com/analyze", json=data_point.__dict__)
                if response.status_code != 200:
                    raise ValueError("Failed to send data to analytics API")
            except Exception as e:
                logger.error(f"Error in sending data to external API: {e}")

    def shutdown(self):
        self.executor.shutdown(wait=True)
        while not self.data_queue.empty():
            self.data_queue.get()
        self.data_queue.put(None)

if __name__ == "__main__":
    handler = IoTDataHandler(max_workers=20, cache_size=10000)

    # Example of ingesting data
    try:
        for i in range(100000):
            device_id = f"device_{i % 10}"
            sensor_values = {"temperature": 22.5 + (i * 0.01), "humidity": 60}
            metadata = {"location": "warehouse"}
            handler.ingest_data(device_id, sensor_values, metadata)
    except KeyboardInterrupt:
        pass

    # Start processing in a separate thread
    processor_thread = threading.Thread(target=handler.process_data)
    processor_thread.start()

    try:
        processor_thread.join()
    except KeyboardInterrupt:
        logger.info("Shutting down gracefully...")
    finally:
        handler.shutdown()
```

