```python
import asyncio
import aiohttp
import hashlib
from aiofiles import open as async_open
import json
import yaml
import xml.etree.ElementTree as ET

# Cache dictionary to store configurations
config_cache = {}

async def fetch_config(session, url):
    try:
        async with session.get(url) as response:
            response.raise_for_status()
            return await response.read()
    except aiohttp.ClientError as e:
        print(f"Network error: {e}")
        return None

def parse_data(data, file_extension):
    if file_extension == '.json':
        return json.loads(data)
    elif file_extension == '.yaml' or file_extension == '.yml':
        return yaml.safe_load(data)
    elif file_extension == '.xml':
        return ET.fromstring(data)
    else:
        raise ValueError("Unsupported configuration format")

async def load_config(url):
    async with aiohttp.ClientSession() as session:
        data = await fetch_config(session, url)
        if data is None:
            return None

        # Determine the file extension
        file_extension = url.split('.')[-1]

        # Calculate MD5 hash for integrity check
        md5_hash = hashlib.md5()
        chunk_size = 4096
        async with async_open(url, 'rb') as f:
            while True:
                chunk = await f.read(chunk_size)
                if not chunk:
                    break
                md5_hash.update(chunk)

        # Parse the configuration data
        config_data = parse_data(data, file_extension)

        # Verify integrity
        if md5_hash.hexdigest() != 'expected_md5_checksum':  # Replace with actual expected checksum
            print("Data integrity check failed.")
            return None

        return config_data

async def manage_config(url):
    config_data = await load_config(url)
    if config_data:
        config_cache[url] = config_data

# Web-based UI using Flask (simplified example)
from flask import Flask, jsonify

app = Flask(__name__)

@app.route('/config/<path:url>', methods=['GET'])
async def get_config(url):
    if url in config_cache:
        return jsonify(config_cache[url])
    else:
        await manage_config(url)
        if url in config_cache:
            return jsonify(config_cache[url])
        else:
            return jsonify({"error": "Configuration not available"}), 404

@app.route('/cache_status', methods=['GET'])
def cache_status():
    return jsonify({
        'total_configs': len(config_cache),
        'cached_urls': list(config_cache.keys())
    })

if __name__ == '__main__':
    app.run(debug=True)
```

