```javascript
const blueslip = require('blueslip');

function runAsyncTests(tests, initialValue, reducerCallback) {
    const moduleUnderTest = tests[0]?.testFunction?.module || 'Unknown Module';

    function validateLabel(label) {
        if (typeof label !== 'string' || !label.trim()) {
            console.error(`Invalid test label: ${JSON.stringify(label)}. Test skipped.`);
            return false;
        }
        // Custom validation logic can be added here
        return true;
    }

    async function runTest(test, index, acc) {
        const { label, testFunction } = test;

        if (!validateLabel(label)) {
            return acc;  // Skip invalid tests and continue
        }

        console.log(`Running ${moduleUnderTest} - Test: ${label}`);

        try {
            await testFunction();
            console.log(`${label}: Passed`);
        } catch (error) {
            console.error(`${label}: Failed with error`, error);
        } finally {
            blueslip.reset();  // Reset the mocking library after each test
        }

        return reducerCallback(acc, label);  // Pass control to the reducer callback
    }

    async function processTests(testsArray, initial) {
        let acc = initial;

        for (let i = 0; i < testsArray.length; i++) {
            acc = await runTest(testsArray[i], i, acc);
        }

        return acc;
    }

    return processTests(tests, initialValue)
        .then(result => console.log('All tests completed. Final result:', result))
        .catch(error => console.error('An error occurred during the test processing:', error));
}

// Sample usage
