```java
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.GZIPInputStream;

public class DynamicDeserializer {
    private static final ConcurrentHashMap<String, Class<?>> CLASS_CACHE = new ConcurrentHashMap<>();

    public <T> T deserialize(byte[] data, String className) throws DeserializationException {
        validateData(data);

        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             GZIPInputStream gis = new GZIPInputStream(bis)) {

            Class<?> clazz;
            if (!CLASS_CACHE.containsKey(className)) {
                clazz = loadClass(className);
                CLASS_CACHE.put(className, clazz);
            } else {
                clazz = CLASS_CACHE.get(className);
            }

            Method method = clazz.getMethod("readObject", GZIPInputStream.class);
            return (T) method.invoke(null, gis);

        } catch (ClassNotFoundException | IOException | NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
            logError(e.getMessage());
            throw new DeserializationException("Failed to deserialize data for class: " + className, e);
        }
    }

    private Class<?> loadClass(String className) throws ClassNotFoundException {
        // Load external configuration if necessary
        return Class.forName(className);
    }

    private void validateData(byte[] data) throws DeserializationException {
        // Implement validation logic here (e.g., checksum verification)
        if (data == null || data.length == 0) {
            throw new DeserializationException("Invalid byte array data");
        }
    }

    private void logError(String message) {
        // Integrate with logging service
    }
}

class DeserializationException extends RuntimeException {
    public DeserializationException(String message, Throwable cause) {
        super(message, cause);
    }
}
