```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public enum DistributionType
{
    Gaussian,
    Uniform,
    Exponential,
    Custom
}

public class DynamicValueGenerator
{
    private readonly object _lock = new object();

    private DistributionType _currentDistributionType;
    private float _mean;
    private float _stdDeviation;
    private float _minRange;
    private float _maxRange;

    // Cache to hold distribution values with LRU eviction policy
    private class LRUCacheItem<T>
    {
        public T Value { get; set; }
        public DateTime LastAccessTime { get; set; }
    }

    private readonly Dictionary<string, LRUCacheItem<float>> _floatCache = new();
    private readonly List<string> _cacheOrder = new();

    private const int CacheSize = 100;

    // Configuration system interface (stubbed)
    private IConfigSystem _configSystem;

    public DynamicValueGenerator(IConfigSystem configSystem)
    {
        _configSystem = configSystem;
        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        var config = _configSystem.GetDistributionConfig();

        if (config != null)
        {
            SetDistribution(config.DistributionType, config.Parameters);
        }
    }

    public void SetDistribution(DistributionType type, Dictionary<string, float> parameters)
    {
        lock (_lock)
        {
            _currentDistributionType = type;
            _mean = parameters.ContainsKey("mean") ? parameters["mean"] : 0.5f;
            _stdDeviation = parameters.ContainsKey("stddev") ? parameters["stddev"] : 1.0f;
            _minRange = parameters.ContainsKey("min") ? parameters["min"] : 0.0f;
            _maxRange = parameters.ContainsKey("max") ? parameters["max"] : 1.0f;

            // Clear cache on distribution change
            _floatCache.Clear();
            _cacheOrder.Clear();
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_lock)
        {
            string cacheKey = $"{_currentDistributionType}_{_minRange}_{_maxRange}";

            if (_floatCache.TryGetValue(cacheKey, out var cachedItem) && (DateTime.UtcNow - cachedItem.LastAccessTime).TotalSeconds < 1.0)
            {
                // Update access time
                cachedItem.LastAccessTime = DateTime.UtcNow;
                return cachedItem.Value;
            }

            float value = GenerateDistributionValue();

            if (_floatCache.Count >= CacheSize)
            {
                var lruKey = _cacheOrder[0];
                _cacheOrder.RemoveAt(0);
                _floatCache.Remove(lruKey);
            }

            _floatCache[cacheKey] = new LRUCacheItem<float> { Value = value, LastAccessTime = DateTime.UtcNow };
            _cacheOrder.Add(cacheKey);

            return value;
        }
    }

    public int GenerateRandomInt(int minRange, int maxRange)
    {
        lock (_lock)
        {
            if (minRange > maxRange) throw new ArgumentException("Min range cannot be greater than max range.");

            switch (_currentDistributionType)
            {
                case DistributionType.Gaussian:
                    return Mathf.RoundToInt(GenerateGaussian(minRange, maxRange));

                case DistributionType.Uniform:
                    return UnityEngine.Random.Range(minRange, maxRange + 1);

                default:
                    // Fallback to uniform distribution for unsupported types
                    return UnityEngine.Random.Range(minRange, maxRange + 1);
            }
        }
    }

    private float GenerateDistributionValue()
    {
        switch (_currentDistributionType)
        {
            case DistributionType.Gaussian:
                return Mathf.Clamp01(UnityEngine.Random.Range(0f, 1f) * _stdDeviation + _mean);

            case DistributionType.Uniform:
                return UnityEngine.Random.Range(_minRange, _maxRange);

            case DistributionType.Exponential:
                // Placeholder for exponential distribution
                float u = UnityEngine.Random.value;
                return -Mathf.Log(1.0f - u) / (_stdDeviation > 0 ? _stdDeviation : 1);

            default:
                throw new NotSupportedException("Unsupported distribution type.");
        }
    }

    private float GenerateGaussian(float min, float max)
    {
        float gauss = UnityEngine.Random.value;
        return Mathf.Clamp(gauss * _stdDeviation + _mean, min, max);
    }

    public override string ToString()
    {
        lock (_lock)
        {
            return $"Range: {_minRange} - {_maxRange}, Distribution: {_currentDistributionType}, Mean: {_mean}, Std Dev: {_stdDeviation}";
        }
    }

    // Stubbed for illustrative purposes
    private interface IConfigSystem
    {
        (DistributionType DistributionType, Dictionary<string, float> Parameters) GetDistributionConfig();
    }
}
```

