        printf("File already present at %s/%s\n", context->bucket_name, context->directory);
        return 0;
    }

    calculate_sha256(context->file_path, &metadata);

    // Multi-threaded download setup
    int thread_count = CHUNK_SIZE / (1024 * 64); // Example value for threads

    for (int i = 0; i < thread_count; i++) {
        ChunkData* chunk_data = malloc(sizeof(ChunkData));
        pthread_create(&thread_ids[i], NULL, download_chunk, chunk_data);
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    // Upload logic using selected cipher and encryption
    EVP_CIPHER_CTX* ctx;
    int outlen;
    unsigned char in[CHUNK_SIZE];
    unsigned char out[CHUNK_SIZE + AES_BLOCK_SIZE];

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    const EVP_CIPHER* cipher = get_cipher(context->cipher_type, context->key_size);
    EVP_EncryptInit_ex(ctx, cipher, NULL, context->encryption_key, NULL);

    // Simulate reading and encrypting file
    FILE *file = fopen(context->file_path, "rb");
    if (!file) return -1;

    while (1) {
        size_t bytes_read = fread(in, 1, CHUNK_SIZE, file);
        if (bytes_read == 0) break;

        EVP_EncryptUpdate(ctx, out, &outlen, in, bytes_read);
        // Here you would write 'out' to the cloud service
    }

    int final_out_len = 0;
    EVP_EncryptFinal_ex(ctx, out + outlen, &final_out_len);

    fclose(file);
    EVP_CIPHER_CTX_free(ctx);

    return 1; // Success
}

// Helper functions implementations

static EVP_CIPHER* get_cipher(const EVP_CIPHER* cipher_type, int key_size) {
    switch (cipher_type) {
        case EVP_aes_128_ecb():
            if (key_size == 128) return EVP_aes_128_ecb();
            break;
        case EVP_aes_192_cbc():
            if (key_size == 192) return EVP_aes_192_cbc();
            break;
        // Additional cases for other cipher types
    }
    return NULL;
}

static void calculate_sha256(const char* file_path, FileMetadata* metadata) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    FILE *file = fopen(file_path, "rb");
    unsigned char buffer[CHUNK_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, CHUNK_SIZE, file)) > 0) {
        SHA256_Update(&sha256, buffer, bytes_read);
    }

    fclose(file);
    SHA256_Final(metadata->sha256, &sha256);
}

