namespace RandomGenerator {

class MT19937Generator {
private:
    std::mt19937 generator;
    std::mutex mtx;

public:
    explicit MT19937Generator(int seed = 0) {
        if (seed <= 0)
            throw std::invalid_argument("Seed must be positive");

        // Initialize the generator with a valid seed
        generator.seed(seed);

        // Store seed value in database for persistence and retrieval
        DatabaseInterface::storeSeedInDatabase("default_seed", seed);
    }

    ~MT19937Generator() = default;

    int generateRandomNumber(int min, int max) {
        std::lock_guard<std::mutex> lock(mtx);  // Ensure thread safety

        if (min >= max)
            throw std::invalid_argument("Invalid range: min must be less than max");

        std::uniform_int_distribution<int> dist(min, max);
        return dist(generator);
    }

    void configureDistribution(int newSeed) {
        if (newSeed <= 0)
            throw std::invalid_argument("New seed must be positive");

        std::lock_guard<std::mutex> lock(mtx);

        // Re-seed generator and update database
        generator.seed(newSeed);
        DatabaseInterface::storeSeedInDatabase("default_seed", newSeed);
    }

    static int retrieveAndSetSeed(const std::string& key) {
        try {
            int seed = DatabaseInterface::getSeedFromDatabase(key);
            if (seed > 0)
                return seed;
            else
                throw std::runtime_error("Failed to retrieve a valid seed from database");
        } catch (...) {
            // Handle exceptions, fallback or log error
            std::cerr << "Error retrieving seed. Using default seed." << std::endl;
            return 42;  // Fallback seed value
        }
    }

private:
    static void log(const std::string& message) {
        // Simple logging mechanism
        std::cout << "[LOG] " << message << std::endl;
    }
};

} // namespace RandomGenerator

// Example usage
int main() {
    try {
        int seed = RandomGenerator::MT19937Generator::retrieveAndSetSeed("default_seed");
        RandomGenerator::MT19937Generator rng(seed);

        for (int i = 0; i < 10; ++i) {
            std::cout << "Random Number: " << rng.generateRandomNumber(1, 100) << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception caught: " << e.what() << std::endl;
    }

    return 0;
}
