import java.io.File;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;

public class VideoTranscoder {

    private final MetadataService metadataService = new MetadataService();
    private final TranscodingService transcodingService = new TranscodingService();

    public List<Status> transcodeVideos(String inputDirPath, String outputDirPath) throws InterruptedException {
        File inputDir = new File(inputDirPath);
        if (!inputDir.isDirectory()) {
            throw new IllegalArgumentException("Input path is not a directory.");
        }

        Path outputDir = Paths.get(outputDirPath);
        Files.createDirectories(outputDir);

        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<Future<Status>> futures = new CopyOnWriteArrayList<>();

        for (File file : inputDir.listFiles((dir, name) -> name.endsWith(".mp4") || name.endsWith(".avi") || name.endsWith(".mkv"))) {
            Metadata metadata = metadataService.getMetadata(file.toPath());

            // Optimize the order based on duration and size
            int priority = calculatePriority(metadata);
            futures.add(executorService.submit(() -> transcodeFile(file, outputDir, metadata, priority)));
        }

        List<Status> results = new ArrayList<>();
        for (Future<Status> future : futures) {
            try {
                Status status = future.get();
                if (!status.isError()) {
                    System.out.println("Transcoding completed successfully: " + status.getFile().getName());
                } else {
                    System.err.println("Transcoding failed: " + status.getError());
                    // Return the first error encountered
                    return List.of(status);
                }
            } catch (ExecutionException e) {
                results.add(new Status(file, null, new TranscodingError(e.getCause())));
            }
        }

        executorService.shutdown();
        return results;
    }

    private int calculatePriority(Metadata metadata) {
        // Priority calculation logic based on duration and size
        return (int) (metadata.getDuration() / 60 + metadata.getSize() / (1024 * 1024));
    }

    private Status transcodeFile(File inputFile, Path outputDir, Metadata metadata, int priority) {
        String fileName = inputFile.getName();
        Path outputPath = outputDir.resolve(fileName.replaceFirst("[.][^.]+$", "") + "_transcoded.mp4");

        try {
            transcodingService.transcode(inputFile.toPath(), outputPath, priority);
            return new Status(outputPath, null);
        } catch (TranscodingException e) {
            return new Status(null, new TranscodingError(e.getCause()));
        }
    }

    public static class MetadataService {

        // Simulated method to fetch metadata
        public Metadata getMetadata(Path videoFilePath) throws IOException {
            // Implementation of querying external service for metadata
            // Dummy implementation returning fixed values:
            return new Metadata(120, 1080 * 720, "16:9");
        }
    }

    public static class TranscodingService {

        public void transcode(Path inputPath, Path outputPath, int priority) throws TranscodingException {
            try (Transcoder transcoder = new Transcoder(inputPath, outputPath)) {
                transcoder.start(priority);
            } catch (IOException | InterruptedException e) {
                throw new TranscodingException("Error during transcoding", e);
            }
        }
    }

    public static class Transcoder implements AutoCloseable {

        private final Path input;
        private final Path output;

        public Transcoder(Path input, Path output) throws IOException {
            this.input = input;
            this.output = output;
            Files.createDirectories(output.getParent());
        }

        public void start(int priority) throws InterruptedException {
            // Simulate transcoding process
            System.out.println("Starting transcoding: " + input.getFileName() + " with priority: " + priority);

            try {
                Thread.sleep(2000);  // Simulating transcoding time
                Files.createFile(output);
                logProgress("Completed", 100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new TranscodingException("Transcoding interrupted");
            }
        }

        private void logProgress(String status, int percentage) {
            System.out.println(status + ": " + input.getFileName() + " " + percentage + "% done.");
        }

        @Override
        public void close() throws IOException {
            // Clean-up resources if needed
        }
    }

    public static class Status {

        private final Path file;
        private final TranscodingError error;

        public Status(Path file, TranscodingError error) {
            this.file = file;
            this.error = error;
        }

        public boolean isError() {
            return error != null;
        }

        public String getError() {
            return error.getMessage();
        }

        public Path getFile() {
            return file;
        }
    }

    public static class Metadata {

        private final long duration; // in seconds
        private final int size;      // in pixels for resolution as width*height
        private final String aspectRatio;

        public Metadata(long duration, int size, String aspectRatio) {
            this.duration = duration;
            this.size = size;
            this.aspectRatio = aspectRatio;
        }

        public long getDuration() {
            return duration;
        }

        public int getSize() {
            return size;
        }
    }

    public static class TranscodingError extends Exception {

        private final Throwable cause;

        public TranscodingError(Throwable cause) {
            super(cause.getMessage());
            this.cause = cause;
        }

        public String getMessage() {
            return "Transcoding error: " + cause.getMessage();
        }
    }

    public static class TranscodingException extends RuntimeException {

        public TranscodingException(String message, Throwable cause) {
            super(message, cause);
        }

        public TranscodingException(String message) {
            super(message);
        }
    }
}
