EVP_CIPHER *create_cipher(const char *mode) {
    if (strcmp(mode, "ECB") == 0) {
        return EVP_des_ede3_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        return EVP_des_ede3();
    } else if (strcmp(mode, "EDE3") == 0) {
        return EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        return EVP_des_cfb64();
    } else if (strcmp(mode, "NULL") == 0) {
        return EVP_null_cipher();
    }
    fprintf(stderr, "Invalid mode specified\n");
    return NULL;
}
