    private final RateLimiter rateLimiter = new RateLimiter(10); // 10 requests per second

    public static void main(String[] args) {
        SpringApplication.run(PokemonService.class, args);
    }

    @GetMapping("/pokemon/{id}")
    public ResponseEntity<Map<String, Object>> getPokemonDetails(@PathVariable String id) {
        rateLimiter.acquire();

        if (cache.containsKey(id)) {
            return ResponseEntity.ok().body(cache.get(id).toMap());
        }

        Pokemon pokemon = fetchPokemonFromAPI(id);
        cache.put(id, pokemon);

        return ResponseEntity.ok().body(pokemon.toMap());
    }

    private Pokemon fetchPokemonFromAPI(String id) {
        // Mock implementation of API calls
        // Replace with actual HTTP requests to external Pokémon APIs
        List<String> weaknesses = Arrays.asList("water", "electric");
        String nextEvolution = "Pikachu evolved into Raichu";

        return new Pokemon(id, "Pikachu", "Electric", weaknesses, nextEvolution);
    }

    static class RateLimiter {
        private final int requestsPerSecond;
        private long lastRequestTime;

        public RateLimiter(int requestsPerSecond) {
            this.requestsPerSecond = requestsPerSecond;
            this.lastRequestTime = 0;
        }

        public synchronized void acquire() throws InterruptedException {
            long currentTime = System.currentTimeMillis();
            if (currentTime - lastRequestTime < 1000 / requestsPerSecond) {
                Thread.sleep((1000 / requestsPerSecond) - (currentTime - lastRequestTime));
            }
            lastRequestTime = System.currentTimeMillis();
        }
    }

    static class Pokemon {
        private String id;
        private String name;
        private String type;
        private List<String> weaknesses;
        private String nextEvolution;

        public Pokemon(String id, String name, String type, List<String> weaknesses, String nextEvolution) {
            this.id = id;
            this.name = name;
            this.type = type;
            this.weaknesses = weaknesses;
            this.nextEvolution = nextEvolution;
        }

        public Map<String, Object> toMap() {
            Map<String, Object> map = new HashMap<>();
            map.put("id", id);
            map.put("name", name);
            map.put("type", type);
            map.put("weaknesses", weaknesses);
            map.put("nextEvolution", nextEvolution);
            return map;
        }
    }
}
