        tasks = [fetch_from_api(session, url) for url in api_urls]
        return await asyncio.gather(*tasks)

@sleep_and_retry
@limits(calls=RATE_LIMIT, period=60)
def rate_limited_log(message, level='INFO'):
    logging.log(getattr(logging, level), message)

async def fetch_from_api(session, url):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            async with session.get(url) as response:
                if response.status == 200:
                    return await response.json()
                elif response.status == 429:  # Rate limit exceeded
                    await asyncio.sleep(1)
        except Exception as e:
            logging.error(f"Error fetching data from {url}: {e}")
        retries += 1
    return None

