#include <forward_list>
#include <string>
#include <mutex>

std::mutex mtx;

void insert_string_after_search(std::forward_list<std::string>& flist, const std::string& search_str, 
                                const std::string& insert_str, size_t max_inserts) {
    std::lock_guard<std::mutex> lock(mtx);

    auto it = flist.begin();
    size_t inserts = 0;

    for (size_t i = 0; i < flist.size() && inserts < max_inserts; ++i, ++it) {
        if (*it == search_str) {
            flist.insert_after(it, insert_str.substr(0, 100));
            ++inserts;
            break;
        }
    }

    if (inserts == 0) {
        flist.push_front(insert_str.substr(0, 100));
    }
}

// Example usage
int main() {
    std::forward_list<std::string> list = {"hello", "world"};
    insert_string_after_search(list, "world", "new_item", 1);

    for (const auto& str : list) {
        std::cout << str << std::endl;
    }

    return 0;
}
