```rust
use anyhow::{Context, Result};
use http::Request;
use hyper::{Body, Client as HyperClient, Request as HyperRequest, Uri};
use hyper_tls::HttpsConnectorBuilder;
use log::{info, LevelFilter};
use std::fs;
use std::sync::{Arc, Mutex};
use tokio;

// A simple logging mechanism inspired by `snprintf`
fn formatted_log(level: &str, message: &str) {
    let timestamp = chrono::Local::now().format("%Y-%m-%d %H:%M:%S").to_string();
    log::log!(level.parse::<LevelFilter>().unwrap(), "{} - {}", timestamp, message);
}

// Function to create an HTTPS client with optional TLS configuration
fn create_https_client(
    cert_validation: bool,
    trust_bundle: Option<Vec<u8>>,
    cipher_suites: Option<Vec<hyper_tls::cipher_suite::CipherSuite>>,
) -> Result<Arc<Mutex<HyperClient<HttpsConnectorBuilder>>>> {
    let mut builder = HttpsConnectorBuilder::new();

    if !cert_validation {
        builder.set_verify(hyper_tls::verify::VerifyNone);
    }

    if let Some(bundle) = trust_bundle {
        builder.add_root_certificate(std::io::Cursor::new(bundle));
    }

    if let Some(ciphers) = cipher_suites {
        builder.set_ciphers(ciphers);
    }

    let https_connector = Arc::new(Mutex::new(builder.build()));

    Ok(https_connector)
}

async fn send_request(url: &str, trust_bundle: Option<Vec<u8>>) -> Result<()> {
    // Create an HTTPS client
    let tls_config = create_https_client(true, trust_bundle.clone(), None).context("Failed to create HTTPS client")?;

    let https_client = HyperClient::builder().build::<_, Body>(tls_config.lock().await);

    // Check and delete the file if it exists
    let filename = "temp_file.txt";
    if fs::metadata(filename).is_ok() {
        fs::remove_file(filename).with_context(|| format!("Failed to remove {}", filename))?;
    }

    let uri: Uri = url.parse()?;
    let request = HyperRequest::builder()
        .method(http::Method::GET)
        .uri(uri)
        .body(Body::empty())
        .context("Failed to build HTTP request")?;

    // Send the request and log output
    match https_client.request(request).await {
        Ok(response) => {
            let status = response.status();
            formatted_log("INFO", &format!("Received response with status: {}", status));

            if let Err(e) = hyper::body::to_bytes(response.into_body()).await {
                formatted_log("ERROR", &format!("Error reading response body: {:?}", e));
            }
        },
        Err(err) => {
            formatted_log("ERROR", &format!("Failed to send request: {:?}", err));
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging
    env_logger::Builder::from_default_env()
        .filter(None, LevelFilter::Info)
        .init();

    let trust_bundle = Some(vec![]); // Example trust bundle
    formatted_log("INFO", "Starting HTTP request...");

    send_request("https://www.example.com", trust_bundle).await?;

    Ok(())
}
```

This Rust program demonstrates how to create an HTTPS client with configurable TLS settings, including certificate validation and cipher suites. It also includes a custom logging mechanism inspired by `snprintf`. The program checks for the existence of a file before proceeding with sending an HTTP request and logs responses along with potential errors gracefully.

