```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    char *message;
} record;

void initialize_and_persist(int num_records, long min_offset, long max_offset, int min_key, int max_key, size_t message_size) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Allocate memory for arrays
    offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize arrays and record structures
    srand((unsigned int)time(NULL));  // Seed random number generator

    FILE *file = fopen("records.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);
        keys[i] = min_key + rand() % (max_key - min_key + 1);

        records[i].value = keys[i];

        // Allocate and initialize message for each record
        records[i].message = (char *)malloc(message_size * sizeof(char));
        if (!records[i].message) {
            fprintf(stderr, "Memory allocation failed for record message\n");
            fclose(file);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        snprintf(records[i].message, message_size, "Record %d", i + 1);

        // Persist to file
        fwrite(&offsets[i], sizeof(long), 1, file);
        fwrite(&keys[i], sizeof(int), 1, file);
        fwrite(&records[i].value, sizeof(int), 1, file);
        size_t len = strlen(records[i].message) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(records[i].message, sizeof(char), len, file);
    }

    fclose(file);

    // Free allocated memory
    for (int i = 0; i < num_records; ++i) {
        free(records[i].message);
    }
    free(offsets);
    free(keys);
    free(records);
}
