import time
import random
from retrying import retry
import logging

# Mocked dependencies for illustration purposes
class PaymentGateway:
    def __init__(self, method):
        self.method = method

    def process_payment(self, order_id, amount, customer_ip):
        # Simulate payment processing and occasional network failure
        if random.choice([True, False]):
            raise ConnectionError("Network error")
        return "success"

class DistributedTransactionManager:
    def __init__(self, services):
        self.services = services

    def execute(self, func, *args, **kwargs):
        # Simulate distributed transaction execution
        try:
            result = func(*args, **kwargs)
            for service in self.services:
                service.commit()
            return result
        except Exception as e:
            for service in self.services:
                service.rollback()
            raise

class OrderService:
    def update_order(self, order_id, status):
        print(f"Order {order_id} updated to {status}")

class InventoryService:
    def update_inventory(self, order_id, decrement):
        print(f"Inventory updated for order {order_id}, decrement={decrement}")
        if decrement > 10:  # Simulate out-of-stock condition
            raise ValueError("Out of stock")

# Logging setup
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def log_to_prometheus_and_grafana(message):
    logger.info(f"Prometheus/Grafana Log: {message}")

@retry(wait_exponential_multiplier=1000, wait_exponential_max=10000, stop_max_attempt_number=lambda: max_retry_attempts)
def process_payment(payment_gateway, order_id, payment_amount, customer_ip):
    return payment_gateway.process_payment(order_id, payment_amount, customer_ip)

def rate_limiter(func):
    def wrapper(*args, **kwargs):
        # Simple rate limiting logic
        time.sleep(0.1)  # Simulate delay for rate limiting
        return func(*args, **kwargs)
    return wrapper

@rate_limiter
def processPaymentTransaction(order_id, payment_amount, payment_method, customer_ip, max_retry_attempts):
    order_service = OrderService()
    inventory_service = InventoryService()

    payment_gateway = PaymentGateway(payment_method)

    try:
        with DistributedTransactionManager([order_service, inventory_service]):
            # Process the payment transaction
            process_payment(payment_gateway, order_id, payment_amount, customer_ip)

            # Update services atomically within a distributed transaction context
            order_service.update_order(order_id, "Paid")
            inventory_service.update_inventory(order_id, 5)  # Assume fixed decrement for simplicity

        log_to_prometheus_and_grafana(f"Transaction successful for Order {order_id}")
        return f"Transaction successful for Order {order_id}"

    except Exception as e:
        log_to_prometheus_and_grafana(f"Transaction failed for Order {order_id}: {str(e)}")
        return f"Transaction failed for Order {order_id}: {str(e)}"
