public class PokemonWeaknessService {
    private static final Logger logger = Logger.getLogger(PokemonWeaknessService.class.getName());
    private final ConcurrentMap<String, String> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public Map<String, String> getPokemonWeaknesses(List<Pokemon> pokemons) {
        Map<String, String> result = new HashMap<>();
        for (Pokemon pokemon : pokemons) {
            try {
                String weaknesses = getWeaknessesFromCacheOrApi(pokemon.getType());
                result.put(pokemon.getName(), weaknesses);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error processing Pokemon: " + pokemon.getName(), e);
                result.put(pokemon.getName(), cache.getOrDefault(pokemon.getType(), "Unknown"));
            }
        }
        return result;
    }

    private String getWeaknessesFromCacheOrApi(String type) throws Exception {
        String weaknesses = cache.get(type);
        if (weaknesses == null || isCacheExpired(type)) {
            weaknesses = fetchWeaknessesFromApi(type);
            cache.put(type, weaknesses);
        }
        return weaknesses;
    }

    private boolean isCacheExpired(String type) {
        // Implement expiration logic here
        return false; // Placeholder
