        } catch (Exception e) {
            logger.log(Level.SEVERE, "API request failed for type: " + type, e);
            throw new RuntimeException("Failed to fetch weaknesses", e);
        }
    }

    public void startCacheUpdater() {
        scheduler.scheduleAtFixedRate(() -> {
            try {
                cache.keySet().forEach(type -> {
                    try {
                        String updatedWeaknesses = fetchWeaknessesFromApi(type);
                        cache.put(type, updatedWeaknesses);
                    } catch (Exception e) {
                        logger.log(Level.WARNING, "Failed to update cache for type: " + type, e);
                    }
                });
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error updating cache", e);
            }
        }, 0, 1, TimeUnit.HOURS); // Update every hour
    }

    public static void main(String[] args) {
