        ExternalApi.setFailNextRequest(true);
        List<Pokemon> pokemons = Arrays.asList(
                new Pokemon("Pikachu", "Electric")
        );

        PokemonWeaknessService service = new PokemonWeaknessService();
        Map<String, String> result = service.getPokemonWeaknesses(pokemons);

        Assertions.assertEquals("Unknown", result.get("Pikachu"));
    }

    @Test
    public void testConcurrentAccess() throws InterruptedException {
        List<Pokemon> pokemons = Collections.nCopies(1000, new Pokemon("Pikachu", "Electric"));

        PokemonWeaknessService service = new PokemonWeaknessService();
        ExecutorService executor = Executors.newFixedThreadPool(10);

        CountDownLatch latch = new CountDownLatch(pokemons.size());
        for (Pokemon pokemon : pokemons) {
            executor.submit(() -> {
                try {
                    service.getPokemonWeaknesses(Collections.singletonList(pokemon));
                } finally {
                    latch.countDown();
                }
            });
        }

        latch.await();
        executor.shutdown();

        Assertions.assertTrue(true); // If no exceptions, test passes
    }
}

class ExternalApi {
    private static boolean failNextRequest = false;

    public static String getWeaknesses(String type) throws Exception {
