    public void processSensorDataStream(Stream<Path> dataStream) {
        ForkJoinPool customThreadPool = new ForkJoinPool(Runtime.getRuntime().availableProcessors());

        dataStream.parallel()
            .forEach(path -> customThreadPool.submit(() -> {
                try {
                    String metadataHash = calculateSHA256Hash(path);

                    if (isFileValid(metadataHash)) {
                        parseAndValidateData(path);

                        if (!metadataCache.containsKey(metadataHash)) {
                            storeMetadataInCache(metadataHash, path.toUri().toString());
                        }

                        uploadToCloudStorage(path, metadataHash);
                    } else {
                        logError("Invalid file: " + path.toString());
                    }

                } catch (Exception e) {
                    handleProcessingException(e);
                }
            }));

        customThreadPool.shutdown();
    }

    private boolean isFileValid(String hash) {
        return !metadataCache.containsKey(hash);
    }

    private String calculateSHA256Hash(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream fis = Files.newInputStream(path)) {
            byte[] byteArray = new byte[1024];
            int bytesCount;

            while ((bytesCount = fis.read(byteArray)) != -1) {
                digest.update(byteArray, 0, bytesCount);
            }
        }

        return bytesToHex(digest.digest());
    }

