class UnionFindDataStructure {
    private final Map<Integer, Integer> parent = new ConcurrentHashMap<>();

    public void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA != rootB) {
            parent.put(rootB, rootA);
        }
    }

    public int find(int x) {
        if (!parent.containsKey(x)) {
            return x;
        }
        if (x == parent.get(x)) {
            return x;
        }
        int root = find(parent.get(x));
        parent.put(x, root);
        return root;
    }
}
