using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class ClinicStatusUpdateMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ClinicStatusUpdateMiddleware> _logger;
    private readonly IMemoryCache _cache;
    private static readonly ConcurrentDictionary<string, int> RateLimiter = new();
    private const int MaxRequestsPerMinute = 5;

    public ClinicStatusUpdateMiddleware(RequestDelegate next, ILogger<ClinicStatusUpdateMiddleware> logger, IMemoryCache cache)
    {
        _next = next;
        _logger = logger;
        _cache = cache;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!IsRateLimited(context.Connection.RemoteIpAddress))
        {
            try
            {
                var requestJson = await new StreamReader(context.Request.Body).ReadToEndAsync();
                var updateRequest = System.Text.Json.JsonSerializer.Deserialize<ClinicUpdateRequest>(requestJson);

                ValidateRequest(updateRequest);

                using (var transactionScope = new TransactionScope(TransactionScopeAsyncFlowOption.Enabled))
                {
                    var oldStatus = GetClinicStatus(updateRequest.ClinicId); // Assume this method exists
                    UpdateClinicStatus(updateRequest);

                    await IntegrateWithCMSAsync(updateRequest);
                    RecordAuditLog(updateRequest.UserId, updateRequest.ClinicId, oldStatus, updateRequest.NewStatus);
                    SendEmailNotification(updateRequest.ClinicId, updateRequest.NewStatus, updateRequest.UserId);

                    transactionScope.Complete();
                }

                context.Response.StatusCode = StatusCodes.Status200OK;
                await context.Response.WriteAsync(System.Text.Json.JsonSerializer.Serialize(new { success = true, message = "Update successful" }));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating clinic status");
                context.Response.StatusCode = StatusCodes.Status500InternalServerError;
                await context.Response.WriteAsync(System.Text.Json.JsonSerializer.Serialize(new { success = false, error = ex.Message }));
            }
        }
        else
        {
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            await context.Response.WriteAsync("Rate limit exceeded. Please try again later.");
        }

        _logger.LogInformation($"Request from IP: {context.Connection.RemoteIpAddress} completed with status code: {context.Response.StatusCode}");
    }

    private bool IsRateLimited(string ipAddress)
    {
        var now = DateTime.UtcNow;
        RateLimiter.AddOrUpdate(ipAddress, 1, (key, oldValue) => Math.Max(0, oldValue - CleanupOldRequests(key, now)) + 1);

        return RateLimiter[ipAddress] > MaxRequestsPerMinute;
    }

    private int CleanupOldRequests(string key, DateTime now)
    {
        var cacheKey = $"{key}_timestamp";
        if (_cache.TryGetValue(cacheKey, out DateTime timestamp))
        {
            if ((now - timestamp).TotalMinutes < 1)
                return 0;

            _cache.Remove(cacheKey);
        }

        _cache.Set(cacheKey, now, TimeSpan.FromMinutes(1));
        return RateLimiter[key];
    }

    private void ValidateRequest(ClinicUpdateRequest request)
    {
