#if defined(_WIN32) || defined(_WIN64)
#include <windows.h>
#else
#include <unistd.h>
#endif

char* constructFilePath(const char* filePath, int maxBufferSize, bool isAbsolute, char* errorMsgBuffer);

static char* resolveEnvironmentVariables(const char* path);
static bool appendCurrentWorkingDirectory(char** fullPath, size_t bufferSize);

char* constructFilePath(const char* filePath, int maxBufferSize, bool isAbsolute, char* errorMsgBuffer) {
    if (filePath == NULL || errorMsgBuffer == NULL || maxBufferSize <= 0) {
        snprintf(errorMsgBuffer, maxBufferSize, "Invalid input parameters.");
        return NULL;
    }

    // Resolve environment variables
    char* resolvedPath = resolveEnvironmentVariables(filePath);
    if (resolvedPath == NULL) {
        snprintf(errorMsgBuffer, maxBufferSize, "Failed to resolve environment variables.");
        return NULL;
    }

    size_t pathLength = strlen(resolvedPath);

    // Check if the path exceeds maximum buffer size
    if (pathLength >= maxBufferSize) {
        free(resolvedPath);
        snprintf(errorMsgBuffer, maxBufferSize, "The file path exceeds the maximum buffer size.");
        return NULL;
    }

    char* fullPath = malloc(pathLength + 1); // Allocate memory for the full path
    if (fullPath == NULL) {
        free(resolvedPath);
        snprintf(errorMsgBuffer, maxBufferSize, "Memory allocation failed.");
        return NULL;
    }
    strcpy(fullPath, resolvedPath);

    // Append current working directory if not absolute
    if (!isAbsolute && !appendCurrentWorkingDirectory(&fullPath, pathLength + 1)) {
        free(resolvedPath);
        snprintf(errorMsgBuffer, maxBufferSize, "Failed to append the current working directory.");
        free(fullPath);
        return NULL;
    }

    // Free temporary resolved path buffer
    free(resolvedPath);

    return fullPath;
}

static char* resolveEnvironmentVariables(const char* path) {
#if defined(_WIN32) || defined(_WIN64)
    size_t expandedSize = ExpandEnvironmentStrings(path, NULL, 0);
    if (expandedSize == 0) {
        return NULL; // Failed to expand environment variables
    }

    char* expandedPath = malloc(expandedSize);
    if (!expandedPath) {
        return NULL;
    }

    if (!ExpandEnvironmentStrings(path, expandedPath, expandedSize)) {
        free(expandedPath);
        return NULL;
    }
    return expandedPath;

#else // POSIX systems

    const char* homeDirEnvVar = getenv("HOME");
    size_t pathLength = strlen(path);

    char* resolvedPath = malloc(pathLength + 1); // Allocate memory for the resolved path
    if (!resolvedPath) {
        return NULL;
    }

    const char* src = path;
    char* dst = resolvedPath;

    while (*src) {
        if (src[0] == '~' && (src[1] == '/' || src[1] == '\0')) { // Home directory replacement
            if (homeDirEnvVar) {
                strcpy(dst, homeDirEnvVar);
                dst += strlen(homeDirEnvVar);
                src++; // Skip the '~'
            } else {
                free(resolvedPath);
                return NULL; // HOME environment variable is not set
            }
        } else {
            *dst++ = *src++;
        }
    }

    *dst = '\0'; // Null-terminate the resolved path string

    return resolvedPath;

#endif
}

static bool appendCurrentWorkingDirectory(char** fullPath, size_t bufferSize) {
#if defined(_WIN32) || defined(_WIN64)
    char cwd[MAX_PATH];
    if (!GetCurrentDirectory(MAX_PATH, cwd)) {
        snprintf(*fullPath, bufferSize, "Failed to get current directory.");
        return false;
    }
#else
    char* cwd = getcwd(NULL, 0);
    if (cwd == NULL) {
        snprintf(*fullPath, bufferSize, "Failed to get current directory.");
        return false;
    }
#endif

    size_t cwdLength = strlen(cwd);

    // Check if the full path can accommodate the current working directory
    if (strlen(*fullPath) + cwdLength + 1 >= bufferSize) {
        free(cwd);
#if defined(_WIN32) || defined(_WIN64)
        snprintf(*fullPath, bufferSize, "The file path exceeds the maximum buffer size.");
#else
        snprintf(*fullPath, bufferSize, "The file path exceeds the maximum buffer size after appending current working directory.");
#endif
        return false;
    }

    char* tempFull = malloc(strlen(cwd) + strlen(*fullPath) + 2);
    if (tempFull == NULL) {
#if defined(_WIN32) || defined(_WIN64)
        snprintf(*fullPath, bufferSize, "Memory allocation failed.");
#else
        snprintf(*fullPath, bufferSize, "Memory allocation failed when appending current working directory.");
#endif
        free(cwd);
        return false;
    }

    strcpy(tempFull, cwd);
#if defined(_WIN32) || defined(_WIN64)
    if (_access(*fullPath, 0) == -1) {
#else
    if (access(*fullPath, F_OK) != 0) {
#endif
        strcat(tempFull, "/");
    }
    strcat(tempFull, *fullPath);

    free(*fullPath);
    *fullPath = tempFull;

#if !defined(_WIN32) && !defined(_WIN64)
    free(cwd); // Free the working directory memory allocated by getcwd
#endif

    return true;
}
