class PaymentProcessor {
public:
    PaymentProcessor() : rateLimit(1000), requestsPerSecond(rateLimit) {}

    bool processPaymentTransaction(const std::string& transactionId, const std::unordered_map<std::string, std::string>& metadata);

private:
    int rateLimit;
    int requestsPerSecond;
    std::mutex mtx;
    std::chrono::time_point<std::chrono::steady_clock> startTime;

    bool validateMetadata(const std::unordered_map<std::string, std::string>& metadata);
    bool isPaymentProcessed(const std::string& transactionId);
    void logTransaction(const std::string& message, const std::string& level);
};

bool PaymentProcessor::processPaymentTransaction(const std::string& transactionId, const std::unordered_map<std::string, std::string>& metadata) {
    if (!validateMetadata(metadata)) {
        logTransaction("Invalid payment metadata", "ERROR");
        return false;
    }

    // Check if already processed
    if (isPaymentProcessed(transactionId)) {
        logTransaction("Transaction already processed", "WARN");
        return true;
    }

    std::lock_guard<std::mutex> lock(mtx);
    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - startTime).count();

    if (elapsed >= 1) {
        requestsPerSecond = rateLimit;
        startTime = now;
    }

    if (requestsPerSecond <= 0) {
        logTransaction("Rate limit exceeded", "ERROR");
        return false;
    }

    requestsPerSecond--;

    // Process payment logic here
    std::cout << "Processing transaction: " << transactionId << "\n";

    // Log success
    logTransaction("Transaction processed successfully", "INFO");

    return true;
}

bool PaymentProcessor::validateMetadata(const std::unordered_map<std::string, std::string>& metadata) {
    // Metadata validation logic
    return !metadata.empty();
}

bool PaymentProcessor::isPaymentProcessed(const std::string& transactionId) {
    // Check if payment is already processed (e.g., in a cache or database)
    static std::unordered_set<std::string> processedTransactions;
    auto it = processedTransactions.find(transactionId);
    if (it != processedTransactions.end()) return true;

    // Simulate adding to processed transactions
    processedTransactions.insert(transactionId);

    return false;
}

void PaymentProcessor::logTransaction(const std::string& message, const std::string& level) {
    // Logging logic here (e.g., log to file, syslog)
    std::cout << "[" << level << "] " << message << "\n";
}
