    @PostMapping(consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<String> ingestSensorData(@RequestBody String jsonData) {
        try {
            boolean isValid = dataProcessorService.validateAndProcess(jsonData);
            if (isValid) {
                return new ResponseEntity<>("Data processed successfully", HttpStatus.OK);
            } else {
                return new ResponseEntity<>("Invalid data format", HttpStatus.BAD_REQUEST);
            }
        } catch (Exception e) {
            // Log the error and handle reprocessing
            LOGGER.error("Error processing sensor data: ", e);
            dataProcessorService.reprocessFailedTransaction(jsonData, e);
            return new ResponseEntity<>("Internal server error", HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }
}

