ResourceCache* create_cache(size_t initial_capacity) {
    ResourceCache* cache = malloc(sizeof(ResourceCache));
    if (cache == NULL) { 
        log_event("Failed to allocate memory for resource cache.");
        return NULL; 
    }

    pthread_rwlock_init(&cache->lock, NULL);
    cache->resources = calloc(initial_capacity, sizeof(ResourceBundle*));
    cache->capacity = initial_capacity;
    cache->count = 0;
    return cache;
}

void destroy_cache(ResourceCache* cache) {
    if (cache != NULL) {
        pthread_rwlock_destroy(&cache->lock);
        for (size_t i = 0; i < cache->count; ++i) {
            free_resource_bundle(cache->resources[i]);
        }
        free(cache->resources);
        free(cache);
    }
}

