#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <errno.h>

#define MAX_FILENAME_LENGTH 255

typedef void (*TestFunction)(void);
typedef void (*CallbackFunction)(int);

// Error codes
enum {
    SUCCESS = 0,
    INVALID_FILE_TYPE,
    FILENAME_TOO_LONG,
    MEMORY_ALLOCATION_ERROR,
    MODULE_LOADING_ERROR,
};

// Mocking library reset function (assuming implementation exists)
void blueslip_reset();

// Function to validate file extension
int is_valid_extension(const char* filename) {
    const char *extensions[] = { ".txt", ".jpg", ".png" };
    size_t num_extensions = sizeof(extensions) / sizeof(extensions[0]);

    for (size_t i = 0; i < num_extensions; ++i) {
        if (strstr(filename, extensions[i]) == filename + strlen(filename) - strlen(extensions[i])) {
            return 1;
        }
    }
    return 0;
}

// Function to modify the filename
char* modify_filename(const char *original) {
    if (!original || !is_valid_extension(original)) {
        return NULL;
    }

    size_t len = strlen(original);
    const char *ext = strrchr(original, '.');

    int num_digits_to_append = 3; // Default value
    if (isdigit(ext[-1])) {
        num_digits_to_append = ext[-1] - '0';
    }

    char *new_filename = malloc(len + num_digits_to_append + 1);
    if (!new_filename) return NULL;

    snprintf(new_filename, len + num_digits_to_append + 1, "%.*s%03d%s",
             (int)(ext - original), original, rand(), ext);

    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        strncpy(new_filename, new_filename, MAX_FILENAME_LENGTH);
        new_filename[MAX_FILENAME_LENGTH] = '\0';
    }

    return new_filename;
}

// Asynchronous test runner
void reduce_async(const char* labels[], const TestFunction funcs[], int size, CallbackFunction callback, int initial_value) {
    for (int i = 0; i < size; ++i) {
        printf("Running test: %s\n", labels[i]);

        // Reset the mocking library to prevent side effects
        blueslip_reset();

        // Execute the test function asynchronously
        funcs[i]();

        // Call the callback with the index (for simplicity)
        callback(i);
    }
}

int test_module_async(const char *filename, const char *test_labels[], TestFunction test_functions[], int initial_value, CallbackFunction callback) {
    if (!is_valid_extension(filename)) {
        fprintf(stderr, "Invalid file type.\n");
        return INVALID_FILE_TYPE;
    }

    // Load the module using dlopen and dlsym
    void *handle = dlopen("your_module.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading module: %s\n", dlerror());
        return MODULE_LOADING_ERROR;
    }

    char *new_filename = modify_filename(filename);
    if (!new_filename) {
        fprintf(stderr, "Error modifying filename.\n");
        dlclose(handle);
        return MEMORY_ALLOCATION_ERROR;
    }

    printf("Testing module from file: %s\n", new_filename);

    int num_tests = 0;
    for (const char *label; label = test_labels[num_tests]; ++num_tests) {
        if (!test_functions[num_tests]) break;
    }

    reduce_async(test_labels, test_functions, num_tests, callback, initial_value);

    free(new_filename);
    dlclose(handle);

    return SUCCESS;
}
```

