    'premium': 500,
}

user_requests = {}

def is_rate_limited(user_id, tier):
    limit = rate_limits.get(tier, rate_limits['default'])
    window_start = time.time() - 60  # 1 minute window

    requests_in_window = [
        timestamp for timestamp in user_requests.get(user_id, [])
        if timestamp > window_start
    ]

    if len(requests_in_window) >= limit:
        return True

    requests_in_window.append(time.time())
    user_requests[user_id] = requests_in_window
    return False

def cache_get(key):
    cached_data = cache.get(key)
    if cached_data and time.time() - cached_data['timestamp'] < 60:  # 1 minute cache expiration
        return cached_data['value']
    return None

def cache_set(key, value):
    cache[key] = {'value': value, 'timestamp': time.time()}

@app.route('/api/resource', methods=['GET'])
def api_resource():
    user_id = request.headers.get('X-User-ID')
    tier = request.headers.get('X-Tier', 'default')

    if not user_id:
        return jsonify({'error': 'Unauthorized'}), 401

    if is_rate_limited(user_id, tier):
        return jsonify({'error': 'Rate limit exceeded'}), 429

    cache_key = f"resource_{user_id}"
    cached_response = cache_get(cache_key)
    if cached_response:
        return jsonify(cached_response)

    try:
        response = requests.get('https://primary-service/resource')
        if response.status_code == 200:
            data = response.json()
            cache_set(cache_key, data)
            return jsonify(data)
        elif response.status_code in (500, 502, 503, 504):
            # Fallback to secondary endpoint
            response = requests.get('https://secondary-service/resource')
            if response.ok:
                data = response.json()
                cache_set(cache_key, data)
                return jsonify(data)

    except requests.RequestException as e:
        return jsonify({'error': 'Service unavailable'}), 503

    return jsonify({'error': 'Unknown error'}), 500

@app.route('/health', methods=['GET'])
def health_check():
    # Implement logic for load balancing and service health checks
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(port=8080)
```

### Notes:
- This example uses Flask to set up a basic API gateway.
- A simple in-memory cache is used, which can be replaced with more advanced solutions like Redis for production environments.
- Rate limiting checks the number of requests per user within a specified time window.
- Fallbacks are implemented to switch to a secondary service if the primary fails.
- Logging and monitoring enhancements would require integration with external tools or services, such as Prometheus, Grafana, etc., which is not covered in this simple implementation.

