import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from jsonschema import validate, ValidationError
import logging
from retrying import retry

# Configure logging for auditing purposes
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s',
                    handlers=[logging.FileHandler('profile_updates.log'),
                              logging.StreamHandler()])

# Define the schema for input validation
user_schema = {
    "type": "object",
    "properties": {
        "email": {"type": "string", "format": "email"},
        "phone_number": {"type": "string"}
    },
    "required": ["email", "phone_number"]
}

# Define API endpoints for services
API_ENDPOINTS = {
    'authentication': 'https://auth.example.com/update',
    'billing': 'https://billing.example.com/update',
    'notification': 'https://notify.example.com/update'
}

@retry(wait_exponential_multiplier=1000, wait_exponential_max=10000, stop_max_attempt_number=5)
def update_service(api_url, data):
    try:
        response = requests.post(api_url, json=data)
        response.raise_for_status()
        logging.info(f"Successfully updated service at {api_url} with data: {data}")
    except (requests.exceptions.HTTPError, requests.exceptions.ConnectionError) as e:
        logging.error(f"Failed to update service at {api_url} due to error: {e}")
        raise

def validate_user_data(data):
    try:
        validate(instance=data, schema=user_schema)
    except ValidationError as e:
        logging.error(f"Validation failed for data: {data}, Error: {str(e)}")
        raise ValueError("Invalid user data")

def update_profile(user_data):
    # Validate input data
    validate_user_data(user_data)

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {
            executor.submit(update_service, url, user_data): service_name
            for service_name, url in API_ENDPOINTS.items()
        }

        for future in as_completed(futures):
            service_name = futures[future]
            try:
                future.result()  # Trigger any exceptions caught during the update
            except Exception as e:
                logging.error(f"Update failed for {service_name} with error: {str(e)}")

# Example usage
user_data = {
    "email": "new_email@example.com",
    "phone_number": "+1234567890"
}

try:
    update_profile(user_data)
except ValueError as e:
    logging.error(f"Profile update aborted due to validation failure: {e}")
