Below is a Python-based solution skeleton for a logging monitoring and incident management system that meets your specified requirements.

```python
import os
import time
import threading
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
from transformers import pipeline
from queue import Queue
import requests
import smtplib
from email.mime.text import MIMEText
import json

# Configuration
LOG_DIRECTORY = "/path/to/logs"
INCIDENT_MANAGEMENT_ENDPOINTS = {
    "service1": "https://api.service1.com/tickets",
    "service2": "https://api.service2.com/incidents"
}
EMAIL_CONFIG = {"smtp_server": "smtp.example.com", "port": 587, "username": "user@example.com", "password": "pass"}
SMS_API_URL = "https://sms.api.endpoint/send"

# NLP model for log analysis
nlp_model = pipeline("text-classification", model="distilbert-base-uncased-finetuned-sst-2-english")

class LogHandler(FileSystemEventHandler):
    def __init__(self, queue: Queue):
        self.queue = queue

    def on_created(self, event):
        if not event.is_directory:
            self.queue.put(event.src_path)

def scan_logs(queue: Queue):
    observer = Observer()
    handler = LogHandler(queue)
    observer.schedule(handler, path=LOG_DIRECTORY, recursive=False)
    observer.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

def parse_log(file_path: str):
    with open(file_path, 'r') as file:
        log_content = file.read()
    # Perform NLP processing
    result = nlp_model(log_content)[0]
    return result

def manage_incidents(queue: Queue):
    while True:
        if not queue.empty():
            file_path = queue.get()
            parsed_result = parse_log(file_path)
            if parsed_result['label'] == 'CRITICAL':
                create_ticket(parsed_result, file_path)

def create_ticket(parsed_result, log_file):
    for service_name, endpoint in INCIDENT_MANAGEMENT_ENDPOINTS.items():
        payload = {
            "severity": parsed_result["score"],
            "description": f"Critical issue detected: {parsed_result['label']} - {log_file}"
        }
        response = requests.post(endpoint, json=payload)
        if not response.ok:
            print(f"Failed to create ticket for {service_name}: {response.text}")

def send_notification(message):
    # Send Email
    msg = MIMEText(message)
    with smtplib.SMTP(EMAIL_CONFIG['smtp_server'], EMAIL_CONFIG['port']) as server:
        server.starttls()
        server.login(EMAIL_CONFIG['username'], EMAIL_CONFIG['password'])
        server.sendmail(EMAIL_CONFIG['username'], 'recipient@example.com', msg.as_string())

    # Send SMS
    sms_payload = {
        "to": "+1234567890",
        "message": message
    }
    requests.post(SMS_API_URL, json=sms_payload)

def main():
    log_queue = Queue()
    threads = [
        threading.Thread(target=scan_logs, args=(log_queue,)),
        threading.Thread(target=manage_incidents, args=(log_queue,))
    ]

    for thread in threads:
        thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for thread in threads:
            thread.join()

if __name__ == "__main__":
    main()
```

### Key Features:

- **Directory Scanning**: Uses `watchdog` to monitor a directory for new log files and adds them to a processing queue.

- **Concurrent Processing**: Employs threading to handle scanning and incident management simultaneously, allowing for horizontal scaling.

- **NLP Analysis**: Utilizes Hugging Face's Transformers library to perform real-time NLP analysis on log content using a pre-trained model.

- **Incident Management Integration**: Sends parsed data to various third-party APIs based on criticality levels defined by the NLP model results.

- **Notification System**: Implements basic email and SMS notifications for critical alerts.

This framework can be extended with more sophisticated error handling, additional notification channels, and other enhancements.

