// DisjointSetNode.java - Augments Node with Union-Find data
class DisjointSetNode extends Node {
    private DisjointSetNode parent;
    private int rank;

    public DisjointSetNode(int id) {
        super(id);
        this.parent = this;
        this.rank = 0;
    }

    public DisjointSetNode getParent() {
        if (parent != this) {
            parent = parent.getParent(); // Path Compression
        }
        return parent;
    }

    public void union(DisjointSetNode other) {
        DisjointSetNode root1 = this.getParent();
        DisjointSetNode root2 = other.getParent();

        if (root1 == root2) return;

        // Union by Rank
        if (root1.rank < root2.rank) {
            root1.parent = root2;
        } else if (root1.rank > root2.rank) {
            root2.parent = root1;
        } else {
            root2.parent = root1;
            root1.rank++;
        }
    }

    public boolean connectedTo(DisjointSetNode other) {
        return this.getParent() == other.getParent();
    }
}

// NetworkTopologyManager.java - Manages the Disjoint Set
import java.util.concurrent.ConcurrentHashMap;

public class NetworkTopologyManager {
    private final ConcurrentHashMap<Integer, DisjointSetNode> nodes = new ConcurrentHashMap<>();

    public synchronized void addNode(int id) {
        if (!nodes.containsKey(id)) {
            nodes.put(id, new DisjointSetNode(id));
        }
    }

    public synchronized void removeNode(int id) {
        nodes.remove(id);
    }

    public synchronized void connectNodes(int id1, int id2) throws Exception {
        addNode(id1);
        addNode(id2);

        DisjointSetNode node1 = nodes.get(id1);
        DisjointSetNode node2 = nodes.get(id2);

        if (node1 == null || node2 == null) {
            throw new IllegalArgumentException("Invalid node ID(s)");
        }

        node1.union(node2);
    }

    public boolean isConnected(int id1, int id2) throws Exception {
        addNode(id1);
        addNode(id2);

        DisjointSetNode node1 = nodes.get(id1);
        DisjointSetNode node2 = nodes.get(id2);

        if (node1 == null || node2 == null) {
            throw new IllegalArgumentException("Invalid node ID(s)");
        }

        return node1.connectedTo(node2);
    }
}

// NetworkTopologyService.java - Service Layer for Microservices Integration
import java.util.concurrent.ExecutorService;
