from fastapi import FastAPI, HTTPException, Request, Depends
from pydantic import BaseModel
from typing import Optional
import sqlalchemy as sa

# Define a Pydantic model for request body validation.
class ResourceUpdateModel(BaseModel):
    version: int
    # Include other fields that can be updated
    name: str = None
    description: str = None


app = FastAPI()

# SQLAlchemy setup (assuming already connected to database)
engine = sa.create_engine("sqlite:///./test.db")
metadata = sa.MetaData()
resources = sa.Table(
    "resources", metadata,
    sa.Column('id', sa.Integer, primary_key=True),
    sa.Column('name', sa.String),
    sa.Column('description', sa.String),
    sa.Column('version', sa.Integer, nullable=False),
    sa.Column('is_deleted', sa.Boolean, default=False)
)

metadata.create_all(engine)
Session = sa.orm.sessionmaker(bind=engine)


@app.put("/resource/{resource_id}")
def update_resource(resource_id: int, request_body: ResourceUpdateModel, db: Session = Depends(Session)):
    resource = db.query(resources).filter_by(id=resource_id, is_deleted=False).with_for_update().first()

    if not resource:
        raise HTTPException(status_code=404, detail="Resource not found")

    # Check for version match
    if request_body.version != resource.version:
        raise HTTPException(
            status_code=409,
            detail="Version mismatch: Resource has been modified since you last fetched it."
        )

    # Update fields and increment version number
    update_data = {**request_body.dict(), "version": resource.version + 1}
    for key, value in update_data.items():
        if value is not None:
            resources.update({key: value}, where=sa.and_(resources.c.id == resource_id, resources.c.version == request_body.version))

    # Commit transaction and close session
    try:
        db.commit()
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=500, detail="Error updating the resource")

    updated_resource = db.query(resources).filter_by(id=resource_id).first()
    return {"id": updated_resource.id, "name": updated_resource.name, "description": updated_resource.description, "version": updated_resource.version}


@app.delete("/resource/{resource_id}")
def soft_delete_resource(resource_id: int, db: Session = Depends(Session)):
    resource = db.query(resources).filter_by(id=resource_id, is_deleted=False).first()

    if not resource:
        raise HTTPException(status_code=404, detail="Resource not found")

    # Mark as deleted
    resources.update({"is_deleted": True}, where=resources.c.id == resource_id)

    try:
        db.commit()
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=500, detail="Error deleting the resource")

    return {"detail": "Resource marked as deleted"}
