    log4c_init();
    logger = log4c_category_get("network_stream");
    log4c_category_log(logger, LOG4C_PRIORITY_INFO, "Starting network stream handler.");

    pthread_t threads[10]; // Adjust based on expected concurrency
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, stream_handler, NULL)) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    log4c_fini();
    return 0;
}

void *stream_handler(void *arg) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
