            log4c_category_log(logger, LOG4C_PRIORITY_ERROR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return NULL;
}

