const axios = require('axios');
const fs = require('fs');

async function uploadFile(url) {
    const maxRetries = 3;
    let attempts = 0;

    async function tryUpload() {
        try {
            const response = await axios.post(url, fs.readFileSync('/path/to/file'), {
                headers: { 'Content-Type': 'application/octet-stream' }
            });
            return response.data.uploadedFileUrl; // Assuming this is the returned property
        } catch (error) {
            if (attempts < maxRetries && error.response && [429, 500, 502, 503, 504].includes(error.response.status)) {
                attempts++;
                const backoffTime = Math.pow(2, attempts) * 1000;
                console.log(`Retry ${attempts} after ${backoffTime}ms`);
                await new Promise(resolve => setTimeout(resolve, backoffTime));
                return tryUpload();
            } else {
                throw error;
            }
        }
    }

    return tryUpload();
}

// Unit test example
describe('File upload', () => {
    it('should successfully upload the file', async () => {
        const url = 'https://api.example.com/upload';
        const result = await uploadFile(url);
        expect(result).toBeDefined();
    });
});

module.exports = { uploadFile };
