```cpp
#include <forward_list>
#include <string>

enum class OperationStatus {
    Success,
    EmptyValueForReplacement,
    KeyNotFound
};

OperationStatus updateForwardList(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    bool found = false;

    for (auto it = list.before_begin(); std::next(it) != list.end(); ++it) {
        if (*std::next(it) == key) {
            found = true;

            if (!value.empty()) {
                *std::next(it) = value;
            } else {
                // If value is empty, insert after the found key
                list.insert_after(std::next(it), value);
                return OperationStatus::EmptyValueForReplacement;
            }

            break;  // Exit loop as we've made our modification
        }
    }

    if (!found) {
        if (!value.empty()) {
            list.push_back(value);
        } else {
            // If key not found and value is empty, append nothing (or handle as needed)
            return OperationStatus::KeyNotFound;
        }
    }

    return OperationStatus::Success;
}
