        # Mock implementation to simulate fetching metrics from an external service
        return []

    @staticmethod
    def trigger_alert(device_id: int, message: str):
        # Mock implementation to simulate triggering alerts via the API
        print(f"Alert triggered for device {device_id}: {message}")

class WeatherServiceAPI:
    @staticmethod
    def fetch_current_weather() -> Dict[str, float]:
        # Mock implementation to simulate fetching weather data
        return {"temperature": 25.0}  # Example temperature in Celsius

def adjust_threshold_based_on_weather(weather_data: Dict[str, float]) -> float:
    temperature = weather_data.get("temperature", 20.0)
    if temperature > 30:
        return 1.1  # Increase threshold by 10% during extreme heat
    return 1.0

class DeviceUsageMonitor:
    def __init__(self):
        self.metrics_lock = threading.Lock()
        self.device_metrics: Dict[int, DeviceMetrics] = {}
        self.load_device_usage_statistics()

    def load_device_usage_statistics(self):
        statistics = MonitoringServiceAPI.fetch_device_usage_statistics()
        with self.metrics_lock:
            for metric in statistics:
                self.device_metrics[metric.device_id] = metric

    def process_log_entry(self, log: ActivityLog) -> None:
        try:
            device_id = int(log.device_info.get("device_id", 0))
            activity_duration = log.timestamp  # Assuming timestamp is used as duration for simplicity

            with self.metrics_lock:
                if device_id not in self.device_metrics:
                    self.device_metrics[device_id] = DeviceMetrics(device_id)

                metrics = self.device_metrics[device_id]
                metrics.total_activity_time += activity_duration
                metrics.user_count += 1

                # Calculate average time spent
                avg_time_spent = metrics.total_activity_time / metrics.user_count if metrics.user_count else 0.0
                metrics.max_avg_time_spent = max(metrics.max_avg_time_spent, avg_time_spent)

            weather_data = WeatherServiceAPI.fetch_current_weather()
            threshold_multiplier = adjust_threshold_based_on_weather(weather_data)
            adjusted_threshold = 60 * threshold_multiplier  # Example threshold of 60 seconds

            if avg_time_spent > adjusted_threshold:
                MonitoringServiceAPI.trigger_alert(device_id, f"Average time spent exceeds {adjusted_threshold} seconds")

        except Exception as e:
            self.log_error(f"Failed to process log entry: {e}")

    def log_error(self, message: str):
        # Mock implementation of logging errors
        print(f"Error: {message}")

def monitor_device_usage(log_stream: List[ActivityLog]):
    monitor = DeviceUsageMonitor()
    for log in log_stream:
        monitor.process_log_entry(log)

