import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.nio.ByteBuffer;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.json.JSONObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DynamicDeserializer {
    private static final Logger logger = LoggerFactory.getLogger(DynamicDeserializer.class);

    // Cache for storing classes and constructors
    private final Map<String, Class<?>> classCache = new ConcurrentHashMap<>();
    private final Map<String, Constructor<?>> constructorCache = new ConcurrentHashMap<>();

    public <T> T deserialize(byte[] data, String className) throws DeserializationException {
        try {
            Class<?> clazz = getClassFromCacheOrFetch(className);
            Constructor<T> constructor;

            synchronized (this.constructorCache) {  // Ensure thread-safety for constructor fetching
                if (!constructorCache.containsKey(className)) {
                    constructor = clazz.getDeclaredConstructor(ByteArrayInputStream.class);
                    constructor.setAccessible(true);
                    constructorCache.put(className, constructor);
                } else {
                    constructor = (Constructor<T>) constructorCache.get(className);
                }
            }

            ByteArrayInputStream byteArrayStream = new ByteArrayInputStream(data);
            T deserializedObject = constructor.newInstance(byteArrayStream);

            return deserializedObject;

        } catch (ClassNotFoundException e) {
            logger.error("Class not found: {}", className, e);
            throw new DeserializationException("Class not found", e);
        } catch (IOException | ReflectiveOperationException e) {
            logger.error("Deserialization failed for class {}: {}", className, e.getMessage());
            throw new DeserializationException("Deserialization error", e);
        }
    }

    private Class<?> getClassFromCacheOrFetch(String className) throws ClassNotFoundException {
        return classCache.computeIfAbsent(className, this::fetchAndValidateClass);
    }

    private Class<?> fetchAndValidateClass(String className) {
        try {
            // Simulate fetching class definition from an external REST API
            JSONObject jsonResponse = simulateApiCallToFetchClassDefinition(className);

            if (!jsonResponse.has("class")) {
                logger.error("Invalid JSON response for class {}", className);
                throw new ClassNotFoundException();
            }

            String classData = jsonResponse.getString("class");
            return Class.forName(classData);

        } catch (Exception e) {
            logger.error("Failed to fetch and validate class: {}", className, e);
            throw new ClassNotFoundException(className + " not found", e);
        }
    }

    private JSONObject simulateApiCallToFetchClassDefinition(String className) {
        // This is a stub method. In real implementation, it would make an API call.
        return new JSONObject().put("class", "your.package." + className);
    }

    public static class DeserializationException extends RuntimeException {
        public DeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
