        var requestLimit = 10; // updates per minute
        var timeWindow = TimeSpan.FromMinutes(1);

        if (!_rateLimitCache.TryGetValue(ip, out var rateInfo) || DateTime.UtcNow - rateInfo.lastRequestTime > timeWindow)
        {
            _rateLimitCache[ip] = (DateTime.UtcNow, 0);
            rateInfo = (_rateLimitCache[ip].lastRequestTime, 0);
        }

        if (rateInfo.requestCount >= requestLimit)
        {
            context.Response.StatusCode = StatusCodes.Status429TooManyRequests;
            await context.Response.WriteAsync("Rate limit exceeded.");
            return;
        }

        try
        {
            var content = await new StreamReader(context.Request.Body).ReadToEndAsync();
            var jsonContent = JObject.Parse(content);

            int clinicId = (int)jsonContent["clinicId"];
            string status = (string)jsonContent["status"];
            string lastModifiedIp = (string)jsonContent["lastModifiedIp"];
            int userId = (int)jsonContent["lastModifiedByUserId"];

            using var scope = context.RequestServices.CreateScope();
            var dbContext = scope.ServiceProvider.GetRequiredService<YourDbContext>();

            await UpdateClinicStatusAsync(dbContext, clinicId, status, lastModifiedIp, userId);

            _rateLimitCache[ip] = (rateInfo.lastRequestTime, rateInfo.requestCount + 1);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing request");
            context.Response.StatusCode = StatusCodes.Status500InternalServerError;
            await context.Response.WriteAsync("An error occurred.");
        }

        await _next(context);
    }

    private async Task UpdateClinicStatusAsync(YourDbContext dbContext, int clinicId, string status, string lastModifiedIp, int userId)
    {
        var clinic = await dbContext.Clinics.FindAsync(clinicId);

        if (clinic == null) throw new Exception("Clinic not found");

        using var transaction = await dbContext.Database.BeginTransactionAsync();

        try
        {
            clinic.Status = status;
            clinic.LastModifiedDate = DateTime.UtcNow;
            clinic.LastModifiedIp = lastModifiedIp;
            clinic.LastModifiedByUserId = userId;

            await dbContext.SaveChangesAsync();
            await transaction.CommitAsync();

            // Cache invalidation logic here

            _logger.LogInformation($"Updated clinic {clinicId} with status {status}");

            // Notify external CMS
            var cmsResponse = await ExternalCmsService.UpdateStatusAsync(clinicId, status);
            if (!cmsResponse.IsSuccessStatusCode)
            {
                _logger.LogWarning("Failed to update CMS");
                // Implement fallback strategy
            }

            // Send email notification
            string adminEmail = clinic.AdministratorEmail;
            if (!string.IsNullOrEmpty(adminEmail))
            {
                var subject = $"Clinic Status Updated: {clinicId}";
                var messageBody = $"New status: {status}\nLast modified by user ID: {userId}\nTime: {DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss")}";
                await EmailService.SendAsync(adminEmail, subject, messageBody);
            }

        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating clinic status");
            await transaction.RollbackAsync();
            throw;
        }
    }
}

