```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>
#include <unistd.h>

#define JPEG ".jpeg"
#define PNG  ".png"
#define PDF  ".pdf"

typedef struct {
    char *inputDir;
    char *outputDir;
    size_t maxPagesPerPdf;
    int outputResolution;
    int timeoutSecs;
    const char *excludeListFile;
    const char *metadataFile;
} ConversionTask;

int isValidImageFile(const char *filename) {
    return (strstr(filename, JPEG) || strstr(filename, PNG));
}

void* convertImagesToPdfThread(void *arg) {
    ConversionTask *task = (ConversionTask *)arg;
    DIR *dir = opendir(task->inputDir);
    if (!dir) return NULL;

    struct dirent *entry;
    char fullPath[1024];
    char outputFilename[256];

    // Load exclude list
    FILE *excludeList = fopen(task->excludeListFile, "r");
    char excludedFileName[256];
    int excludeFlag = 0;

    while (fscanf(excludeList, "%s", excludedFileName) != EOF) {
        if (!excludeFlag && !strcmp(entry->d_name, excludedFileName)) {
            excludeFlag = 1;
        }
    }
    fclose(excludeList);

    size_t currentPageCount = 0;
    char command[1024];

    while ((entry = readdir(dir))) {
        if (isValidImageFile(entry->d_name) && !excludeFlag) {
            snprintf(fullPath, sizeof(fullPath), "%s/%s", task->inputDir, entry->d_name);

            // Prepare PDF output filename
            snprintf(outputFilename, sizeof(outputFilename), "%s/page%d.pdf", task->outputDir, currentPageCount / task->maxPagesPerPdf);

            // Construct conversion command
            snprintf(command, sizeof(command),
                     "convert -density %d \"%s\" -quality 100 \"%s\"",
                     task->outputResolution,
                     fullPath,
                     outputFilename);

            int status = system(command);
            if (status != 0) {
                return (void *)(intptr_t)-1;
            }

            currentPageCount++;
            if (currentPageCount >= task->maxPagesPerPdf) {
                break; // Move to the next batch
            }
        }
    }

    closedir(dir);
    return NULL;
}

int batchConvertImagesToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf, int outputResolution, size_t numThreads, int timeoutSecs, const char *configFile, const char *excludeListFile, const char *metadataFile) {
    struct stat st;

    if (stat(inputDir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        return -1; // Input directory does not exist
    }

    pthread_t threads[numThreads];
    ConversionTask task = {inputDir, outputDir, maxPagesPerPdf, outputResolution, timeoutSecs, excludeListFile, metadataFile};

    for (size_t i = 0; i < numThreads; ++i) {
        if (pthread_create(&threads[i], NULL, convertImagesToPdfThread, &task)) {
            return -2; // Failed to create thread
        }
    }

    int result = 0;
    for (size_t i = 0; i < numThreads; ++i) {
        void *threadResult;
        if (pthread_join(threads[i], &threadResult) == 0 && (intptr_t)threadResult == -1) {
            result = -3; // Thread encountered an error
            break;
        }
    }

    return result;
}
```

### Key Points:
- **Thread Pooling:** This implementation creates a fixed number of threads (`numThreads`) to perform the conversion tasks concurrently.
- **File Validation:** Ensures only JPEG and PNG files are processed.
- **Error Handling:** Returns error codes for various failure scenarios, such as directory not found or thread creation failures.
- **Command Execution:** Uses `system()` to call a third-party tool like ImageMagick's `convert` command for conversion.
- **Exclude List:** Skips files listed in the exclude file during processing.

