```c
#include <openssl/evp.h>
#include <string.h>

// Function to initialize and return a pointer to an EVP_CIPHER structure
EVP_CIPHER_CTX *initialize_cipher(const char *cipher_name, const unsigned char *key, size_t key_len, const unsigned char *iv, int iv_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error: unable to allocate context
        return NULL;
    }

    // Initialize the cipher based on the provided name and parameters
    if (strcmp(cipher_name, "DES-ECB") == 0) {
        if (!EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, key, iv)) {
            // Handle error: unable to initialize DES ECB mode
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(cipher_name, "DES-EDE") == 0) {
        if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv)) {
            // Handle error: unable to initialize DES EDE mode
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(cipher_name, "DES-EDE3") == 0) {
        if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv)) {
            // Handle error: unable to initialize DES EDE3 mode
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(cipher_name, "DES-CFB") == 0) {
        if (!EVP_EncryptInit_ex(ctx, EVP_des_cfb64(), NULL, key, iv)) {
            // Handle error: unable to initialize DES CFB mode
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(cipher_name, "NULL") == 0) {
        if (!EVP_EncryptInit_ex(ctx, EVP_null(), NULL, key, iv)) {
            // Handle error: unable to initialize NULL cipher
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else {
        // Handle invalid cipher name
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

