```python
import hashlib
import os
import sys
import requests
from tqdm import tqdm

def calculate_sha256(file_path):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):
            sha256.update(chunk)
    return sha256.hexdigest()

def download_file(url, dest_path):
    response = requests.get(url, stream=True)
    total_size_in_bytes= int(response.headers.get('content-length', 0))

    with open(dest_path, 'wb') as file, tqdm(
        desc=dest_path,
        total=total_size_in_bytes,
        unit='iB',
        unit_scale=True,
        unit_divisor=1024,
    ) as bar:
        for data in response.iter_content(chunk_size=8192):
            size = file.write(data)
            bar.update(size)

def verify_hash(file_path, expected_checksum):
    actual_checksum = calculate_sha256(file_path)
    return actual_checksum == expected_checksum

def main():
    if len(sys.argv) < 3:
        print("Usage: python script.py <file_path_or_url> [expected_checksum]")
        sys.exit(1)

    file_input = sys.argv[1]
    expected_checksum = sys.argv[2] if len(sys.argv) > 2 else None

    if file_input.startswith('http://') or file_input.startswith('https://'):
        local_filename = os.path.basename(file_input)
        download_file(file_input, local_filename)
        file_path = local_filename
    else:
        file_path = file_input

    actual_checksum = calculate_sha256(file_path)
    print(f"SHA-256: {actual_checksum}")

    if expected_checksum and verify_hash(file_path, expected_checksum):
        print("Success: Hash matches the provided checksum.")
    elif expected_checksum:
        print("Error: Hash does not match the provided checksum.")

if __name__ == "__main__":
    main()
