// Node.js Part

const fs = require('fs');
const path = require('path');

class ModuleLoader {
  constructor(modulesPath) {
    this.modulesPath = modulesPath;
    this.loadedModules = new Map();
  }

  loadModule(moduleName, callback) {
    if (this.loadedModules.has(moduleName)) {
      return callback(null, this.loadedModules.get(moduleName));
    }

    const moduleFilePath = path.join(this.modulesPath, `${moduleName}.js`);

    fs.readFile(moduleFilePath, 'utf8', (err, code) => {
      if (err) {
        console.error(`Failed to load module ${moduleName}:`, err.message);
        return callback(err);
      }

      try {
        const moduleFunction = new Function('require', 'exports', 'module', code);
        const moduleExports = {};

        moduleFunction(
          (name) => this.loadModule(name, (error, exports) => {
            if (error) throw error;
            module.exports[name] = exports;
          }),
          moduleExports,
          { id: `/${moduleName}.js` }
        );

        this.loadedModules.set(moduleName, moduleExports);
        callback(null, moduleExports);
      } catch (execErr) {
        console.error(`Execution failed for module ${moduleName}:`, execErr.message);
        callback(execErr);
      }
    });
  }

  executeModulesInOrder(modules, finalCallback) {
    const loadModuleChain = (index, accumulatedErrors) => {
      if (index >= modules.length) return finalCallback(accumulatedErrors);

      this.loadModule(modules[index], (err, exports) => {
        if (err) {
          accumulatedErrors.push({ module: modules[index], error: err.message });
          return loadModuleChain(index + 1, accumulatedErrors);
        }

        console.log(`Executed ${modules[index]} successfully.`);
        loadModuleChain(index + 1, accumulatedErrors);
      });
    };

    loadModuleChain(0, []);
  }
}

// Usage example
const moduleLoader = new ModuleLoader('./path/to/modules');
moduleLoader.executeModulesInOrder(['moduleA', 'moduleB'], (errors) => {
  if (errors.length > 0) {
    console.error('Some modules failed to execute:', errors);
  } else {
    console.log('All modules executed successfully.');
  }
});


