import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;

public class CommandExecutor {

    private static final Logger logger = Logger.getLogger(CommandExecutor.class.getName());

    public static Map<String, String> safeCommandExecutor(String command, String workingDirPath) {
        File workingDir = new File(workingDirPath);
        if (!workingDir.exists()) {
            throw new IllegalArgumentException("Working directory does not exist.");
        }

        Process process;
        Map<String, String> result = new HashMap<>();

        try (InputStreamReader isrOut = new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8);
             InputStreamReader isrErr = new InputStreamReader(process.getErrorStream(), StandardCharsets.UTF_8);
             BufferedReader brOut = new BufferedReader(isrOut);
             BufferedReader brErr = new BufferedReader(isrErr)) {

            StringBuilder outputBuilder = new StringBuilder();
            StringBuilder errorBuilder = new StringBuilder();

            String line;
            while ((line = brOut.readLine()) != null) {
                if (outputBuilder.length() > Integer.MAX_VALUE - 128) { // Example threshold
                    logger.log(Level.WARNING, "Output truncated. Original length: " + outputBuilder.length());
                }
                outputBuilder.append(line).append("\n");
            }

            while ((line = brErr.readLine()) != null) {
                if (errorBuilder.length() > Integer.MAX_VALUE - 128) { // Example threshold
                    logger.log(Level.WARNING, "Error truncated. Original length: " + errorBuilder.length());
                }
                errorBuilder.append(line).append("\n");
            }

            result.put("output", outputBuilder.toString().trim());
            result.put("error", errorBuilder.toString().trim());

        } catch (IOException e) {
            logger.log(Level.SEVERE, "IO Exception occurred while executing command.", e);
        }

        return result;
    }

    public static void main(String[] args) {
        // Test cases to validate functionality
        Map<String, String> result = safeCommandExecutor("echo Hello World", "/path/to/dir");
        System.out.println("Output: " + result.get("output"));
        System.out.println("Error: " + result.get("error"));

        result = safeCommandExecutor("invalid-command", "/path/to/dir");
        System.out.println("Output: " + result.get("output"));
        System.out.println("Error: " + result.get("error"));
    }
}
```

### Explanation:
- **Logging**: Uses `java.util.logging.Logger` to log warnings and errors.
- **Stream Handling**: Reads from both output and error streams using buffered readers with UTF-8 encoding.
- **Truncation Logging**: Logs a warning if the output or error exceeds a certain length.
- **Error Handling**: Catches `IOException` during stream operations and logs it.
- **Main Method**: Includes basic test cases to demonstrate functionality. Adjust paths and commands as needed for actual tests.

